# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║  X AETHER ULTRA 3.1.0 · GUARDIÁN DE COMANDOS                                      ║
# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║  Evita que el bot se caiga por nombres o aliases repetidos.                 ║
# ║  Si un comando moderno sobrescribe uno viejo, se retira el viejo antes.      ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

_AMX231_COMMAND_GUARD_REPORT = []

try:
    _AMX231_ORIGINAL_ADD_COMMAND = commands.Bot.add_command

    def _amx231_clean_aliases(command):
        """Elimina aliases duplicados dentro del propio comando antes de registrarlo."""
        try:
            base = str(getattr(command, "name", "") or "").lower()
            seen = {base}
            clean = []
            for alias in list(getattr(command, "aliases", []) or []):
                alias_s = str(alias or "").strip()
                alias_l = alias_s.lower()
                if not alias_s or alias_l in seen:
                    _AMX231_COMMAND_GUARD_REPORT.append(f"alias_interno_omitido:{getattr(command,'name','?')}->{alias_s}")
                    continue
                seen.add(alias_l)
                clean.append(alias_s)
            command.aliases = clean
        except Exception as exc:
            _AMX231_COMMAND_GUARD_REPORT.append(f"clean_aliases_error:{getattr(command,'name','?')}:{exc!r}")
        return command

    def _amx231_remove_existing_name(bot_instance, token: str):
        """Retira cualquier comando ya registrado que use ese nombre o alias."""
        token = str(token or "").strip()
        if not token:
            return None
        existing = None
        try:
            existing = bot_instance.all_commands.get(token)
        except Exception:
            existing = None
        if existing is None:
            try:
                existing = bot_instance.get_command(token)
            except Exception:
                existing = None
        if existing is not None:
            old_name = getattr(existing, "name", token)
            try:
                bot_instance.remove_command(old_name)
                _AMX231_COMMAND_GUARD_REPORT.append(f"reemplazado:{token}->{old_name}")
            except Exception as exc:
                _AMX231_COMMAND_GUARD_REPORT.append(f"remove_error:{token}:{exc!r}")
            # Limpieza defensiva del mapa interno por si quedó algún alias fantasma.
            try:
                bot_instance.all_commands.pop(token, None)
            except Exception:
                pass
            return old_name
        return None

    def _amx231_guarded_add_command(self, command):
        command = _amx231_clean_aliases(command)
        names = [getattr(command, "name", "")] + list(getattr(command, "aliases", []) or [])
        for token in names:
            _amx231_remove_existing_name(self, token)
        try:
            return _AMX231_ORIGINAL_ADD_COMMAND(self, command)
        except commands.errors.CommandRegistrationError:
            # Segunda pasada agresiva: limpia todos los nombres y aliases del comando nuevo.
            for token in names:
                _amx231_remove_existing_name(self, token)
                try:
                    self.all_commands.pop(str(token), None)
                except Exception:
                    pass
            return _AMX231_ORIGINAL_ADD_COMMAND(self, command)

    if not getattr(commands.Bot.add_command, "_amx231_guard", False):
        _amx231_guarded_add_command._amx231_guard = True
        commands.Bot.add_command = _amx231_guarded_add_command
        print("✅ X AETHER ULTRA 3.1.0 · Guardián de comandos activado")
except Exception as _amx231_guard_error:
    print(f"⚠️ X AETHER 3.1.0 · No se pudo activar el guardián de comandos: {_amx231_guard_error!r}")

