def _contiene_palabra_bloqueada(contenido: str, palabra: str) -> bool:
    """Evita falsos positivos por substring y bloquea términos/frases exactas."""
    if not palabra:
        return False
    patron = r"(?<!\w)" + re.escape(str(palabra).lower()) + r"(?!\w)"
    return re.search(patron, str(contenido or "").lower()) is not None

