def cargar_historial_ia() -> Dict[int, list]:
    """Carga el historial de conversaciones desde disco al arrancar."""
    try:
        if os.path.exists(AI_HISTORIAL_FILE):
            with open(AI_HISTORIAL_FILE, "r", encoding="utf-8") as f:
                raw = json.load(f)
            # Las claves en JSON son strings, las convertimos a int
            return {int(k): v for k, v in raw.items()}
    except Exception as e:
        print(f"[IA HIST] Error cargando historial: {e}")
    return {}

def guardar_historial_ia():
    """Guarda el historial de conversaciones en disco."""
    try:
        # Guardamos solo los últimos AI_HISTORY_LIMIT mensajes por usuario para no inflar el archivo
        snapshot = {str(uid): hist[-AI_HISTORY_LIMIT:] for uid, hist in ai_user_history.items() if hist}
        with open(AI_HISTORIAL_FILE, "w", encoding="utf-8") as f:
            json.dump(snapshot, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[IA HIST] Error guardando historial: {e}")

def cargar_datos() -> Dict[str, Any]:
    """
    X AETHER ULTRA PATCH:
    Carga segura de datos.json con lock reentrante.
    Mantiene compatibilidad con todos los comandos existentes del monolito.
    """
    with _datos_lock:
        try:
            if not os.path.exists(DATOS_FILE):
                return {}
            with open(DATOS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, dict) else {}
        except (FileNotFoundError, json.JSONDecodeError):
            # Si el JSON está corrupto o vacío, el bot no cae: arranca con datos limpios.
            return {}
        except Exception as exc:
            print(f"[X AETHER JSON] Error cargando datos: {exc!r}")
            return {}


def guardar_datos(datos: Dict[str, Any]):
    """
    X AETHER ULTRA PATCH:
    Guardado atómico de datos.json.
    Escribe primero en un temporal y luego hace os.replace(), evitando archivos cortados
    si Pterodactyl, el host o Discord reinician el proceso en mitad de una escritura.
    """
    with _datos_lock:
        tmp_path = None
        try:
            base_dir = os.path.dirname(DATOS_FILE) or "."
            os.makedirs(base_dir, exist_ok=True)
            with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=base_dir, delete=False) as tmp:
                tmp_path = tmp.name
                json.dump(datos if isinstance(datos, dict) else {}, tmp, ensure_ascii=False, indent=4)
                tmp.flush()
                os.fsync(tmp.fileno())
            os.replace(tmp_path, DATOS_FILE)
        except PermissionError:
            print("[X AETHER ULTRA JSON] Sin permisos para guardar datos en", DATOS_FILE)
        except Exception as e:
            print(f"[X AETHER JSON] guardar_datos falló: {e!r}")
            try:
                if tmp_path and os.path.exists(tmp_path):
                    os.remove(tmp_path)
            except Exception:
                pass


async def cargar_datos_async() -> Dict[str, Any]:
    """
    X AETHER ULTRA PATCH:
    Wrapper asíncrono con asyncio.Lock para operaciones críticas nuevas.
    No sustituye llamadas antiguas para no romper compatibilidad del monolito.
    """
    async with _datos_async_lock:
        return await asyncio.to_thread(cargar_datos)


async def guardar_datos_async(datos: Dict[str, Any]):
    """
    X AETHER ULTRA PATCH:
    Guardado asíncrono no bloqueante para comandos nuevos o refactors futuros.
    """
    async with _datos_async_lock:
        await asyncio.to_thread(guardar_datos, datos)


def asegurar_usuario(datos: Dict[str, Any], uid: str):
    """Garantiza que un usuario tenga su estructura completa en el JSON."""
    defaults = {
        "cash": 0, "bank": 0, "nivel": 1, "experiencia": 0,
        "monedas": 0, "items": {}, "reputacion": 0, "rango_rl": "Sin rango",
        "logros": [], "advertencias": 0,
    }
    if uid not in datos:
        datos[uid] = {k: (list(v) if isinstance(v, list) else (v.copy() if isinstance(v, dict) else v)) for k, v in defaults.items()}
    else:
        for key, val in defaults.items():
            if key not in datos[uid]:
                datos[uid][key] = list(val) if isinstance(val, list) else (val.copy() if isinstance(val, dict) else val)

def agregar_a_cash(datos: Dict[str, Any], uid: str, cantidad: int):
    """Suma cantidad al cash (sin modificar monedas históricas)."""
    asegurar_usuario(datos, uid)
    datos[uid]["cash"] = datos[uid].get("cash", 0) + cantidad

def agregar_a_cash_y_monedas(datos: Dict[str, Any], uid: str, cantidad: int):
    """Añade cash y también suma a monedas (solo si cantidad > 0)."""
    asegurar_usuario(datos, uid)
    datos[uid]["cash"] = datos[uid].get("cash", 0) + cantidad
    if cantidad > 0:
        datos[uid]["monedas"] = datos[uid].get("monedas", 0) + cantidad

def obtener_monedas(datos: Dict[str, Any], uid: str) -> int:
    """Devuelve la suma del cash + bank actual del usuario."""
    asegurar_usuario(datos, uid)
    return datos[uid].get("cash", 0) + datos[uid].get("bank", 0)

def restar_de_cash(datos: Dict[str, Any], uid: str, cantidad: int) -> bool:
    """
    Resta cash. 
    Si ALLOW_NEGATIVE_BALANCE es True, puede dejar el saldo en negativo.
    Si es False, cancela la operación si no hay suficiente dinero.
    """
    asegurar_usuario(datos, uid)
    if not ALLOW_NEGATIVE_BALANCE and datos[uid].get("cash", 0) < cantidad:
        return False
    datos[uid]["cash"] = datos[uid].get("cash", 0) - cantidad
    return True

def obtener_multiplicador(datos: dict, uid: str, tipo: str) -> float:
    """
    Devuelve el multiplicador total de ganancias según los ítems del usuario.
    tipo puede ser: 'blackjack', 'apostar', 'vip', etc.
    """
    asegurar_usuario(datos, uid)
    items = datos[uid].get("items", {})
    info = items.get(tipo)
    if info:
        return info.get("multiplicador_total", 1.0)  # multiplicador acumulado
    return 1.0

def formato_tiempo(segundos: float) -> str:
    total = int(round(segundos))
    minutos = total // 60
    segundos_rest = total % 60
    if minutos > 0:
        return f"{minutos}m {segundos_rest}s"
    return f"{segundos_rest}s"

def obtener_rank_por_monedas(datos: Dict[str, Any], uid: str) -> Optional[int]:
    lista = sorted(
        [(u, info.get("monedas", 0)) for u, info in datos.items()],
        key=lambda x: x[1],
        reverse=True
    )
    for idx, (user_id, monedas) in enumerate(lista, start=1):
        if user_id == uid:
            return idx
    return None

def recompensa_por_bloque(nivel: int) -> int:
    bloques = nivel // 10
    if bloques <= 0:
        return 0
    return 200 + (bloques - 1) * 100

