def _help_command_key(label: str) -> Optional[str]:
    m = re.match(r"([!/][\w_]+)", str(label or "").strip())
    return m.group(1).lstrip("!/").lower() if m else None


def _sync_help_catalog_with_bot_commands():
    """Garantiza que ningún comando cargado se quede fuera de !ayuda."""
    existing = set()
    for data in COMMAND_CATEGORIES.values():
        if isinstance(data, dict):
            for key in data.keys():
                k = _help_command_key(key)
                if k:
                    existing.add(k)

    for cmd in bot.commands:
        if getattr(cmd, "hidden", False):
            continue
        name = cmd.name.lower()
        if name in existing:
            continue
        cat, text = HELP_COMMAND_HINTS.get(name, ("otros", f"!{cmd.name}: {cmd.help or cmd.description or 'Comando disponible.'}"))
        label, _, desc = text.partition(":")
        COMMAND_CATEGORIES.setdefault(cat, {})[label] = desc.strip() or "Comando disponible."
        existing.add(name)

    try:
        for cmd in tree.get_commands():
            name = cmd.name.lower()
            if name in existing:
                continue
            COMMAND_CATEGORIES.setdefault("otros", {})[f"/{cmd.name}"] = getattr(cmd, "description", None) or "Comando slash disponible."
            existing.add(name)
    except Exception:
        pass


