async def procesar_xp(message: discord.Message):
    """Añade XP al usuario por cada mensaje (con cooldown de 60s)."""
    
    uid = str(message.author.id)
    ahora = _t.time()
    
    # Cooldown de 60 segundos entre ganancias de XP
    ultimo = _xp_cooldown.get(message.author.id, 0)
    if ahora - ultimo < 60:
        return
    _xp_cooldown[message.author.id] = ahora
    
    d = cargar_datos()
    asegurar_usuario(d, uid)
    
    xp_ganado = random.randint(5, 12)
    
    # Boost XP si tiene el item
    if item_activo(d, uid, "xp_boost"):
        xp_ganado *= 2
    
    d[uid]["experiencia"] = d[uid].get("experiencia", 0) + xp_ganado
    
    # Subir de nivel
    nivel_actual = d[uid].get("nivel", 1)
    xp_necesario = 100 + (nivel_actual - 1) * 50
    
    if d[uid]["experiencia"] >= xp_necesario:
        d[uid]["experiencia"] -= xp_necesario
        d[uid]["nivel"] = nivel_actual + 1
        nuevo_nivel = d[uid]["nivel"]
        
        # Recompensa por subir de nivel
        recompensa = 50 + nuevo_nivel * 10
        agregar_a_cash_y_monedas(d, uid, recompensa)
        
        canal_niveles_id = 1412574049942503444
        canal_niveles = message.guild.get_channel(canal_niveles_id) if message.guild else None
        if canal_niveles:
            try:
                await canal_niveles.send(
                    f"🎉 {message.author.mention} ¡Has subido al nivel **{nuevo_nivel}**! "
                    f"Recompensa: **{recompensa}** 💎"
                )
            except Exception:
                pass
    
    guardar_datos(d)

def _guardar_misiones(data: dict):
    """Guarda el archivo de misiones activas."""
    try:
        with open(MISIONES_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[MISIONES] Error guardando: {e}")

def cargar_misiones_activas() -> dict:
    import datetime as _dt
    hoy = _dt.datetime.now().strftime("%Y-%m-%d")
    try:
        with open(MISIONES_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        # Limpiar misiones de días anteriores
        modificado = False
        for uid in list(data.keys()):
            if data[uid].get("fecha") != hoy:
                del data[uid]
                modificado = True
        if modificado:
            _guardar_misiones(data)
        return data
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def _progresar_mision(uid: str, tipo: str, cantidad: int = 1):
    """Progresa una misión del usuario y GUARDA en disco."""
    import datetime as _dt
    misiones_activas = cargar_misiones_activas()
    hoy = _dt.datetime.now().strftime("%Y-%m-%d")
    if uid not in misiones_activas or misiones_activas[uid].get("fecha") != hoy:
        return
    modificado = False
    for m in misiones_activas[uid].get("misiones", []):
        if m["tipo"] == tipo and not m.get("completada"):
            m["progreso"] = m.get("progreso", 0) + cantidad
            if m["progreso"] >= m["meta"]:
                m["completada"] = True
            modificado = True
    if modificado:
        _guardar_misiones(misiones_activas)

