def _actualizar_streak_trabajo(uid: str) -> dict:
    """Actualiza streak laboral diario. Devuelve info del usuario."""
    import datetime as _dt
    nomina = _cargar_nomina()
    hoy = _dt.datetime.now().strftime("%Y-%m-%d")
    ayer = (_dt.datetime.now() - _dt.timedelta(days=1)).strftime("%Y-%m-%d")
    if uid not in nomina:
        nomina[uid] = {"streak": 1, "ultimo_dia": hoy, "semanas_completas": 0}
    else:
        ultimo = nomina[uid].get("ultimo_dia", "")
        streak = nomina[uid].get("streak", 0)
        if ultimo == hoy:
            pass  # ya trabó hoy, no cambiar streak
        elif ultimo == ayer:
            nomina[uid]["streak"] = streak + 1
            nomina[uid]["ultimo_dia"] = hoy
        else:
            nomina[uid]["streak"] = 1
            nomina[uid]["ultimo_dia"] = hoy
    _guardar_nomina(nomina)
    return nomina[uid]

