async def _cargar_json(filepath: str, lock: asyncio.Lock, default=None):
    if default is None:
        default = {}
    async with lock:
        try:
            if os.path.exists(filepath):
                with open(filepath, "r", encoding="utf-8") as f:
                    return json.load(f)
        except Exception as e:
            print(f"[JSON] Error cargando {filepath}: {e}")
        return default

async def _guardar_json(filepath: str, lock: asyncio.Lock, data):
    async with lock:
        try:
            with open(filepath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"[JSON] Error guardando {filepath}: {e}")

