async def check_spam(message):
    uid = message.author.id
    now = _time_module.time()
    data = spam_tracker.get(uid, {"msgs": []})
    data["msgs"] = [t for t in data["msgs"] if now - t < 10]
    data["msgs"].append(now)
    spam_tracker[uid] = data
    if len(data["msgs"]) > 7:
        try:
            await message.author.timeout(datetime.timedelta(seconds=30))
        except Exception:
            pass

async def otorgar_logro(uid: str, logro_id: str) -> bool:
    logros_data = await cargar_logros_data()
    if uid not in logros_data:
        logros_data[uid] = []
    if logro_id in logros_data[uid]:
        return False
    logros_data[uid].append(logro_id)
    await guardar_logros_data(logros_data)
    datos = cargar_datos()
    asegurar_usuario(datos, uid)
    recompensa = LOGROS_DISPONIBLES[logro_id]["recompensa"]
    agregar_a_cash_y_monedas(datos, uid, recompensa)
    guardar_datos(datos)
    return True

async def verificar_logros(uid: str, tipo: str, valor: int = 1):
    datos = cargar_datos()
    asegurar_usuario(datos, uid)
    notificaciones = []
    if tipo == "cash":
        total = datos[uid].get("cash", 0) + datos[uid].get("bank", 0)
        if total >= 1_000_000 and await otorgar_logro(uid, "millonario"):
            notificaciones.append("millonario")
    elif tipo == "nivel":
        nivel = datos[uid].get("nivel", 1)
        if nivel >= 10 and await otorgar_logro(uid, "nivel_10"):   notificaciones.append("nivel_10")
        if nivel >= 50 and await otorgar_logro(uid, "nivel_50"):   notificaciones.append("nivel_50")
        if nivel >= 100 and await otorgar_logro(uid, "veterano"):  notificaciones.append("veterano")
    elif tipo == "trabajo" and await otorgar_logro(uid, "primer_trabajo"):
        notificaciones.append("primer_trabajo")
    elif tipo == "bank" and datos[uid].get("bank", 0) >= 10_000 and await otorgar_logro(uid, "ahorrador"):
        notificaciones.append("ahorrador")
    elif tipo == "inversion" and await otorgar_logro(uid, "inversor"):
        notificaciones.append("inversor")
    elif tipo == "reputacion" and datos[uid].get("reputacion", 0) >= 50 and await otorgar_logro(uid, "popular"):
        notificaciones.append("popular")
    elif tipo == "streaker" and await otorgar_logro(uid, "streaker"):
        notificaciones.append("streaker")
    return notificaciones

async def verificar_logros_mejorado(uid):
    datos = cargar_datos()
    asegurar_usuario(datos, uid)
    total = datos[uid]["cash"] + datos[uid]["bank"]
    if total > 100000 and "rico" not in datos[uid]["logros"]:
        datos[uid]["logros"].append("rico")
        agregar_a_cash_y_monedas(datos, uid, 500)
    guardar_datos(datos)

