def item_activo(datos: dict, uid: str, tipo: str) -> bool:
    asegurar_usuario(datos, uid)
    info = datos[uid].get("items", {}).get(tipo)
    if not info:
        return False
    expira = info.get("expira")
    if not expira:
        return True
    import datetime as _dt
    return _dt.datetime.fromisoformat(expira) > _dt.datetime.now()

def aplicar_item(datos: dict, uid: str, item_id: str) -> str:
    import datetime as _dt
    item = TIENDA_ITEMS.get(item_id)
    if not item:
        return "Item no encontrado."
    asegurar_usuario(datos, uid)
    item_tipo = item.get("tipo", item_id)

    # Consumibles: se acumulan por cantidad y luego se usan con !usar.
    if item.get("consumible") or item.get("stackable"):
        actual = datos[uid].setdefault("items", {}).get(item_tipo, {})
        if not isinstance(actual, dict):
            actual = {}
        actual.update({
            "item_id": item_id,
            "nombre": item["nombre"],
            "multiplicador_total": item.get("multiplicador", 1.0),
            "expira": None,
            "activado": actual.get("activado") or _dt.datetime.now().isoformat(),
            "categoria": item.get("categoria", "especial"),
            "rareza": item.get("rareza", "común"),
            "consumible": True,
        })
        actual["cantidad"] = int(actual.get("cantidad", 0) or 0) + 1
        datos[uid]["items"][item_tipo] = actual
        return f"Añadido al inventario. Cantidad: x{actual['cantidad']}"

    expira = None
    if item["duracion_dias"] > 0:
        expira = (_dt.datetime.now() + _dt.timedelta(days=item["duracion_dias"])).isoformat()
    datos[uid]["items"][item_tipo] = {
        "item_id": item_id,
        "nombre": item["nombre"],
        "multiplicador_total": item.get("multiplicador", 1.0),
        "expira": expira,
        "activado": _dt.datetime.now().isoformat(),
        "categoria": item.get("categoria", "otros"),
        "rareza": item.get("rareza", "normal"),
    }
    if expira:
        dt = _dt.datetime.fromisoformat(expira)
        return f"Activado hasta {dt.strftime('%d/%m/%Y')}"
    return "Añadido al inventario permanente."

