async def _iniciar_poker(ctx, modo, apuesta):
    """Inicia la partida según el modo elegido."""
    d = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(d, uid)

    restar_de_cash(d, uid, apuesta)
    guardar_datos(d)
    _poker_sessions[ctx.author.id] = True

    baraja = _crear_baraja_poker()
    random.shuffle(baraja)

    if modo == "texas":
        mano_j = [baraja.pop(), baraja.pop()]
        mano_b = [baraja.pop(), baraja.pop()]
        com = [baraja.pop() for _ in range(5)]
        pot = apuesta * 2
        view = PokerView(
            ctx=ctx, apuesta=apuesta, pot=pot,
            mano_j=mano_j, mano_b=mano_b, com=com,
            baraja=baraja, fase=0, bot_bet=apuesta, j_bet=apuesta
        )
        await ctx.send(embed=view.construir_embed(), view=view)

    elif modo == "speed":
        # Speed: reparte todo de golpe, showdown directo
        mano_j = [baraja.pop(), baraja.pop()]
        mano_b = [baraja.pop(), baraja.pop()]
        com = [baraja.pop() for _ in range(5)]
        pot = apuesta * 2

        sc_j, nom_j, _ = _mejor_mano_poker(mano_j + com)
        sc_b, nom_b, _ = _mejor_mano_poker(mano_b + com)

        com_str = " ".join(_carta_str(c) for c in com)
        j_str   = " ".join(_carta_str(c) for c in mano_j)
        b_str   = " ".join(_carta_str(c) for c in mano_b)

        if sc_j > sc_b:
            agregar_a_cash_y_monedas(d, uid, pot)
            guardar_datos(d)
            neto = pot - apuesta
            resultado = f"🎉 **¡GANASTE!** +{neto:,} amatista"
            color = discord.Color.gold()
        elif sc_j < sc_b:
            resultado = f"😢 **El bot gana.** -{apuesta:,} amatista"
            color = discord.Color.red()
        else:
            agregar_a_cash(d, uid, apuesta)
            guardar_datos(d)
            resultado = "🤝 **Empate.** Te devuelven la apuesta."
            color = discord.Color.orange()

        embed = discord.Embed(
            title="⚡ Speed Poker — Showdown",
            color=color
        )
        embed.add_field(name="🎴 Mesa", value=com_str, inline=False)
        embed.add_field(name="🫵 Tu mano", value=j_str, inline=True)
        embed.add_field(name="🤖 Bot", value=b_str, inline=True)
        embed.add_field(name="Tu mano", value=f"**{nom_j}**", inline=True)
        embed.add_field(name="Mano bot", value=f"**{nom_b}**", inline=True)
        embed.add_field(name="🏆 Resultado", value=resultado, inline=False)
        embed.set_footer(text=f"Bote: {pot:,} amatista")
        _poker_sessions.pop(ctx.author.id, None)
        await ctx.send(embed=embed)

    elif modo == "highcard":
        # High Card: 1 carta cada uno, la más alta gana
        carta_j = baraja.pop()
        carta_b = baraja.pop()
        val_j = _VALORES_POKER.index(carta_j[0])
        val_b = _VALORES_POKER.index(carta_b[0])
        pot = apuesta * 2

        if val_j > val_b:
            agregar_a_cash_y_monedas(d, uid, pot)
            guardar_datos(d)
            neto = pot - apuesta
            resultado = f"🎉 **¡GANASTE!** +{neto:,} amatista"
            color = discord.Color.gold()
        elif val_j < val_b:
            resultado = f"😢 **El bot gana.** -{apuesta:,} amatista"
            color = discord.Color.red()
        else:
            agregar_a_cash(d, uid, apuesta)
            guardar_datos(d)
            resultado = "🤝 **Empate.** Te devuelven la apuesta."
            color = discord.Color.orange()

        embed = discord.Embed(
            title="🎯 High Card Duel",
            color=color
        )
        embed.add_field(
            name="🫵 Tu carta",
            value=f"**{_carta_str(carta_j)}**",
            inline=True
        )
        embed.add_field(
            name="🤖 Bot",
            value=f"**{_carta_str(carta_b)}**",
            inline=True
        )
        embed.add_field(name="🏆 Resultado", value=resultado, inline=False)
        embed.set_footer(text=f"Bote: {pot:,} amatista")
        _poker_sessions.pop(ctx.author.id, None)
        await ctx.send(embed=embed)

