def cargar_ouroboros() -> dict:
    """Carga el estado Ouroboros de AETHER."""
    try:
        if os.path.exists(OUROBOROS_FILE):
            with open(OUROBOROS_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    estado = {
        "version": "1.0",
        "ciclos_evolucion": 0,
        "ultima_reflexion": None,
        "rasgos_activos": ["analítico", "ingenioso", "directo"],
        "reflexiones": [],
        "estadisticas": {
            "mensajes_procesados": 0,
            "usuarios_recordados": 0,
            "warns_emitidos": 0,
            "kicks_emitidos": 0,
            "conversaciones_totales": 0,
        },
        "aprendizajes": []
    }
    guardar_ouroboros(estado)
    return estado

def guardar_ouroboros(estado: dict):
    """Guarda el estado Ouroboros."""
    try:
        with open(OUROBOROS_FILE, "w", encoding="utf-8") as f:
            json.dump(estado, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[OUROBOROS] Error guardando estado: {e}")

def ouroboros_tick(evento: str, datos: dict = None):
    """Registra un evento en el ciclo Ouroboros de AETHER."""
    estado = cargar_ouroboros()
    estado["estadisticas"]["mensajes_procesados"] = estado["estadisticas"].get("mensajes_procesados", 0) + 1
    if evento == "warn":
        estado["estadisticas"]["warns_emitidos"] = estado["estadisticas"].get("warns_emitidos", 0) + 1
    elif evento == "kick":
        estado["estadisticas"]["kicks_emitidos"] = estado["estadisticas"].get("kicks_emitidos", 0) + 1
    elif evento == "conversacion":
        estado["estadisticas"]["conversaciones_totales"] = estado["estadisticas"].get("conversaciones_totales", 0) + 1
    guardar_ouroboros(estado)

async def ouroboros_reflexionar(user_id: int, username: str, conversacion: list):
    """
    Reflexión autónoma de AETHER sobre sus interacciones.
    - Primeras 3 reflexiones: cada 50 conversaciones.
    - Después: cada 150 conversaciones.
    - Si han pasado más de 24 h desde la última reflexión, se fuerza una.
    """
    estado = cargar_ouroboros()
    total = estado["estadisticas"].get("conversaciones_totales", 0)

    if total == 0:
        return

    # Determinar cada cuántas conversaciones reflexionar
    ciclos = estado.get("ciclos_evolucion", 0)
    if ciclos < 3:
        umbral = 50   # más frecuente al principio
    else:
        umbral = 150  # más espaciado después

    # Verificar si toca por número de conversaciones
    if total % umbral == 0:
        deberia_reflexionar = True
    else:
        deberia_reflexionar = False

    # Verificar si ha pasado más de 24 h desde la última reflexión
    ultima_str = estado.get("ultima_reflexion")
    if ultima_str:
        try:
            ultima = datetime.datetime.fromisoformat(ultima_str)
            if (datetime.datetime.now() - ultima).total_seconds() > 86400:  # 24 horas
                deberia_reflexionar = True
        except Exception:
            pass

    if not deberia_reflexionar:
        return

    try:
        # Construir contexto para reflexión
        conv_texto = "\n".join([
            f"{'Usuario' if m['role']=='user' else 'AETHER'}: {m['content'][:100]}"
            for m in conversacion[-6:]
        ])

        prompt_reflexion = f"""Eres el sistema de reflexión de AETHER, una IA de Discord.\n\nHas tenido {total} conversaciones totales.\nEstadísticas: warns={estado['estadisticas'].get('warns_emitidos',0)}, kicks={estado['estadisticas'].get('kicks_emitidos',0)}
        
        Última conversación analizada:
        {conv_texto}
        Aprendizajes anteriores:
        {chr(10).join(estado['aprendizajes'][-5:]) if estado['aprendizajes'] else 'Ninguno aún.'}
        Reflexiona brevemente (máx 2 frases) sobre UNA cosa concreta que hayas aprendido de esta conversación o patrón que hayas detectado. 
        Si no hay nada nuevo, responde: NADA
        Responde solo con la reflexión o NADA:"""

        # Llamada asíncrona correcta (sin run_in_executor)
        respuesta = await _llamar_groq_async(
            [{"role": "user", "content": prompt_reflexion}],
            GROQ_MODELOS[_modelo_idx]
        )
        reflexion = respuesta.strip()

        if reflexion.upper() != "NADA" and reflexion:
            estado["reflexiones"].append({
                "timestamp": datetime.datetime.now().isoformat(),
                "conversacion": total,
                "reflexion": reflexion,
                "tipo": "auto"
            })
            estado["aprendizajes"].append(reflexion)
            if len(estado["aprendizajes"]) > 30:
                estado["aprendizajes"] = estado["aprendizajes"][-30:]
            if len(estado["reflexiones"]) > 50:
                estado["reflexiones"] = estado["reflexiones"][-50:]
            estado["ultima_reflexion"] = datetime.datetime.now().isoformat()
            estado["ciclos_evolucion"] = ciclos + 1
            guardar_ouroboros(estado)
            print(f"[OUROBOROS] Reflexión #{estado['ciclos_evolucion']}: {reflexion[:80]}...")

    except Exception as e:
        print(f"[OUROBOROS] Error en reflexión: {e}")

def construir_contexto_ouroboros() -> str:
    """Construye el contexto Ouroboros para el system prompt de AETHER."""
    estado = cargar_ouroboros()
    if not estado["aprendizajes"]:
        return ""
    ultimos = estado["aprendizajes"][-5:]
    aprendizajes_str = "\n".join(f"  • {a}" for a in ultimos)
    return f"""\n━━ AETHER OUROBOROS — APRENDIZAJES PROPIOS ━━━━━━\nHe reflexionado sobre mis interacciones y he aprendido:\n{aprendizajes_str}\nCiclos de evolución completados: {estado.get('ciclos_evolucion', 0)}\nÚsalos de forma natural si son relevantes para la conversación actual."""

def construir_system_prompt_ouroboros(base_prompt: str) -> str:
    """Enriquece el system prompt con el contexto Ouroboros."""
    ctx_ouro = construir_contexto_ouroboros()
    if ctx_ouro:
        return base_prompt + ctx_ouro
    return base_prompt

def cargar_memoria_aether() -> dict:
    """Carga el archivo aether_memoria.json. Lo crea si no existe."""
    try:
        if not os.path.exists(MEMORIA_FILE):
            estructura = {
                "_meta": {
                    "creado": datetime.datetime.now().isoformat(),
                    "descripcion": "Memoria persistente de AETHER — recuerdos por usuario"
                }
            }
            with open(MEMORIA_FILE, "w", encoding="utf-8") as f:
                json.dump(estructura, f, ensure_ascii=False, indent=2)
            return estructura
        with open(MEMORIA_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception as e:
        print(f"[AETHER MEM] Error cargando memoria: {e}")
        return {}

def guardar_memoria_aether(memoria: dict):
    """Guarda el archivo aether_memoria.json."""
    try:
        with open(MEMORIA_FILE, "w", encoding="utf-8") as f:
            json.dump(memoria, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[AETHER MEM] Error guardando memoria: {e}")

def obtener_memoria_usuario(user_id: int) -> list:
    """Devuelve la lista de recuerdos de un usuario."""
    memoria = cargar_memoria_aether()
    uid = str(user_id)
    return memoria.get(uid, {}).get("recuerdos", [])

def construir_contexto_memoria(user_id: int) -> str:
    """Construye el bloque de memoria para el system prompt."""
    recuerdos = obtener_memoria_usuario(user_id)
    if not recuerdos:
        return ""
    lineas = "\n".join(f"  - {r}" for r in recuerdos[-20:])  # máx 20 recuerdos
    return f"""\n━━ LO QUE RECUERDAS DE ESTE USUARIO ━━━━━━━━━━━━\n{lineas}\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nUsa estos recuerdos de forma natural. No los leas todos de golpe."""

async def actualizar_memoria_aether(user_id: int, username: str, historial_reciente: list):
    """
    Después de una conversación, llama a Groq para que AETHER
    decida qué vale la pena recordar del usuario.
    Solo se ejecuta cada 5 mensajes para no saturar la API.
    """
    if not GROQ_API_KEY or len(historial_reciente) < 2:
        return

    # Solo analizar si hay suficiente conversación
    mensajes_usuario = [m for m in historial_reciente if m["role"] == "user"]
    if len(mensajes_usuario) < 2:
        return

    try:
        # Construir el historial como texto plano
        conv_texto = ""
        for m in historial_reciente[-10:]:
            rol = username if m["role"] == "user" else "AETHER"
            conv_texto += f"{rol}: {m['content']}\n"

        recuerdos_actuales = obtener_memoria_usuario(user_id)
        recuerdos_str = "\n".join(f"- {r}" for r in recuerdos_actuales) if recuerdos_actuales else "Ninguno aún."

        prompt_memoria = f"""Eres el sistema de memoria de AETHER, una IA de Discord.\nAnaliza esta conversación reciente con el usuario "{username}" y decide qué información nueva y relevante merece ser recordada.\n\nCONVERSACIÓN RECIENTE:\n{conv_texto}
RECUERDOS QUE YA TIENES DE ESTE USUARIO:
{recuerdos_str}

INSTRUCCIONES:
- Extrae SOLO información nueva que no esté ya en los recuerdos
- Solo recuerda cosas útiles y personales: nombre real, rango RL, gustos, contexto importante, cosas que mencionó sobre sí mismo
- NO recuerdes preguntas genéricas, saludos, o información del servidor
- Si no hay nada nuevo que recordar, responde exactamente: NADA
- Si hay cosas nuevas, responde con una lista, una por línea, empezando cada línea con "-"
- Máximo 3 recuerdos nuevos por conversación
- Sé conciso: cada recuerdo en una frase corta

Responde SOLO con la lista o con "NADA":"""

        # ✅ Llamada asíncrona directa, sin run_in_executor
        resultado = await _llamar_groq_async(
            [{"role": "user", "content": prompt_memoria}],
            GROQ_MODELOS[_modelo_idx]
        )
        resultado = resultado.strip()

        if resultado.upper() == "NADA" or not resultado:
            return

        # Parsear los nuevos recuerdos
        nuevos = []
        for linea in resultado.split("\n"):
            linea = linea.strip().lstrip("-").strip()
            if linea and len(linea) > 5:
                nuevos.append(linea)

        if not nuevos:
            return

        # Guardar en el archivo
        memoria = cargar_memoria_aether()
        uid = str(user_id)
        if uid not in memoria:
            memoria[uid] = {
                "username": username,
                "primera_vez": datetime.datetime.now().isoformat(),
                "recuerdos": []
            }

        memoria[uid]["username"] = username
        memoria[uid]["ultima_actualizacion"] = datetime.datetime.now().isoformat()
        memoria[uid]["recuerdos"].extend(nuevos)

        # Limitar a 50 recuerdos por usuario
        if len(memoria[uid]["recuerdos"]) > 50:
            memoria[uid]["recuerdos"] = memoria[uid]["recuerdos"][-50:]

        guardar_memoria_aether(memoria)
        print(f"[AETHER MEM] Nuevos recuerdos para {username}: {nuevos}")

    except Exception as e:
        print(f"[AETHER MEM] Error actualizando memoria: {e}")

def construir_perfil_aether(user_id: int) -> str:
    """
    Lee datos.json y construye un resumen conciso del usuario
    para que AETHER lo use como contexto al responder.
    """
    try:
        datos = cargar_datos()
        uid = str(user_id)
        if uid not in datos:
            print(f"[AETHER PERFIL] Usuario {uid} no encontrado en datos.json")
            return ""

        d = datos[uid]

        # Nivel y XP
        nivel = d.get("nivel", 1)
        xp = d.get("experiencia", 0)
        xp_necesario = nivel * 100

        # Economía
        cash = d.get("cash", 0)
        bank = d.get("bank", 0)
        total = cash + bank

        # Ranking
        todos = sorted(
            [(u, info.get("monedas", 0)) for u, info in datos.items()],
            key=lambda x: x[1], reverse=True
        )
        ranking = next((i+1 for i, (u, _) in enumerate(todos) if u == uid), None)

        # Social
        reputacion = d.get("reputacion", 0)
        rango_rl = d.get("rango_rl", "Sin rango")
        advertencias = d.get("advertencias", 0)

        # Items activos (solo los más relevantes)
        items = d.get("items", {})
        items_activos = []
        import datetime as _dt
        ahora = _dt.datetime.now()
        for tipo, info in items.items():
            if isinstance(info, dict):
                expira = info.get("expira")
                nombre = info.get("nombre") or tipo
                if expira:
                    try:
                        dt = _dt.datetime.fromisoformat(expira)
                        if dt > ahora:
                            dias = (dt - ahora).days
                            items_activos.append(f"{nombre} ({dias}d)")
                    except:
                        pass
                elif info.get("multiplicador_total", 0) > 1:
                    items_activos.append(nombre)

        items_str = ", ".join(items_activos) if items_activos else "sin boosts activos"

        # Construir el bloque de contexto (formato compacto y directo)
        perfil = (
            "\n━━ DATOS REALES DEL USUARIO (CONSULTA OBLIGATORIA) ━━━\n"
            f"**Usuario:** {uid}\n"
            f"**Nivel:** {nivel} | **XP:** {xp}/{xp_necesario}\n"
            f"**Cash:** {cash:,} amatista | **Banco:** {bank:,} amatista | **Total:** {total:,}\n"
            f"**Ranking:** #{ranking if ranking else '?'} | **Reputación:** {reputacion}\n"
            f"**Rango RL:** {rango_rl} | **Advertencias:** {advertencias}\n"
            f"**Ranking:** {ranking}\n"
            f"**Boosts:** {items_str}\n"
            "━━ FIN DE DATOS REALES ━━━\n"
            "[IMPORTANTE: Estos son los datos reales extraídos de datos.json. Úsalos si la conversación lo requiere. No inventes cifras.]"
        )

        # Log de depuración para ver en consola
        print(f"[AETHER PERFIL] Generado para {uid}: Cash={cash}, Banco={bank}, Total={total}")
        return perfil

    except Exception as e:
        print(f"[AETHER] Error construyendo perfil: {e}")
        return ""

async def _llamar_groq(mensajes: list, modelo: str) -> str:
    """Llama a un modelo de Groq. Lanza excepción si falla."""
    client = Groq(api_key=GROQ_API_KEY)
    response = client.chat.completions.create(
        model=modelo,
        max_tokens=AI_MAX_TOKENS,
        messages=mensajes
    )
    return response.choices[0].message.content

async def _llamar_openrouter(mensajes: list, modelo: str) -> str:
    """Llama a un modelo de OpenRouter vía HTTP. Lanza excepción si falla."""
    
    headers = {
        "Authorization": f"Bearer {OPENROUTER_API_KEY}",
        "Content-Type": "application/json",
        "HTTP-Referer": "https://discord.com",
        "X-Title": "AETHER Bot"
    }
    payload = {
        "model": modelo,
        "max_tokens": AI_MAX_TOKENS,
        "messages": mensajes
    }
    async with aiohttp.ClientSession() as session:
        async with session.post(
            f"{OPENROUTER_BASE_URL}/chat/completions",
            json=payload,
            headers=headers,
            timeout=aiohttp.ClientTimeout(total=30)
        ) as resp:
            if resp.status == 429:
                raise Exception("rate limit openrouter")
            if resp.status != 200:
                txt = await resp.text()
                raise Exception(f"openrouter error {resp.status}: {txt[:200]}")
            data = await resp.json()
            return data["choices"][0]["message"]["content"]

async def _llamar_deepseek(mensajes: list, modelo: str) -> str:
    """Llama a un modelo de DeepSeek usando AsyncOpenAI."""
    global deepseek_async_client
    if not deepseek_async_client:
        raise Exception("DeepSeek client not initialized")
    respuesta = await deepseek_async_client.chat.completions.create(
        model=modelo,
        max_tokens=AI_MAX_TOKENS,
        messages=mensajes
    )
    return respuesta.choices[0].message.content

async def preguntar_aether(user_id: int, user_message: str, username: str, perfil_usuario: str = "") -> str:
    """
    AETHER v5 — Multi-proveedor: Groq + OpenRouter + DeepSeek.
    Orden: Groq → OpenRouter → DeepSeek.
    """
    global _modelo_idx, groq_async_client
    import time as _time

    if not GROQ_API_KEY:
        return "⚠️ La IA no está configurada. Añade `GROQ_API_KEY` al `.env`."
    # Registrar interacción en Ouroboros
    ouroboros_tick("conversacion")
    es_markelson = (user_id == MARKELSON_ID)

    if user_id not in ai_user_history:
        ai_user_history[user_id] = []
    historial = ai_user_history[user_id]

    _ctx_memoria = construir_contexto_memoria(user_id)
    _ctx_ouroboros = construir_contexto_ouroboros() if "construir_contexto_ouroboros" in dir() else ""
    base_prompt = construir_system_prompt_ouroboros(AI_SYSTEM_PROMPT)

    if es_markelson:
        system_prompt = base_prompt + f"""
━━ MODO MARKELSON ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
- Estás hablando con Markelson, tu creador y jefe.
- Confianza total: sé directo, coloquial, sin filtros ni censura.
- JAMÁS uses [AETHER_WARN] ni [AETHER_KICK] con él.
- Sin límite de historial. Recuerdas todo lo de esta sesión.
- Trátalo como a tu mejor colega que además es tu jefe.
""" + _ctx_memoria + _ctx_ouroboros + f"""

[NORMA ABSOLUTA - LÉELO CON ATENCIÓN]
A continuación se muestran los datos REALES de Markelson extraídos directamente del archivo datos.json.
DEBES utilizarlos obligatoriamente si la conversación requiere mencionar su cash, banco, rango o cualquier otra estadística.
NO inventes números. Si no figuran aquí, no los menciones.

{perfil_usuario}

[FIN DE LOS DATOS REALES]
"""
    else:
        warns_activos = aether_warnings.get(user_id, 0)
        ctx_warns = f"\n- ⚠️ Este usuario tiene {warns_activos} advertencia(s)." if warns_activos > 0 else ""
        system_prompt = base_prompt + f"""

━━ USUARIO ACTUAL ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
- Nombre: {username}{ctx_warns}
- Recuerdas sus últimos {AI_HISTORY_LIMIT} mensajes contigo.
""" + _ctx_memoria + f"""

[NORMA ABSOLUTA - DATOS REALES DEL USUARIO]
La siguiente información proviene de datos.json. Úsala sin alterar si la conversación lo pide.
No inventes cantidades ni atributos.

{perfil_usuario}

[FIN DE LOS DATOS REALES]
"""
    historial.append({"role": "user", "content": user_message})
    if not es_markelson and len(historial) > AI_HISTORY_LIMIT:
        historial = historial[-AI_HISTORY_LIMIT:]
        ai_user_history[user_id] = historial

    mensajes = [{"role": "system", "content": system_prompt}] + historial

    sem = _ia_semaphore or asyncio.Semaphore(3)
    async with sem:

        ahora = _time.time()

        # ── PROVEEDOR 1: GROQ ─────────────────
        if GROQ_API_KEY and groq_async_client:
            for intento in range(len(GROQ_MODELOS)):
                modelo_actual = GROQ_MODELOS[_modelo_idx]
                try:
                    respuesta = await asyncio.wait_for(
                        _llamar_groq_async(mensajes, modelo_actual),
                        timeout=25
                    )
                    historial.append({"role": "assistant", "content": respuesta})
                    if _modelo_idx != 0:
                        print(f"[AETHER] Groq fallback: {modelo_actual}")
                    msgs_u = sum(1 for m in historial if m["role"] == "user")
                    if msgs_u % 5 == 0:
                        asyncio.create_task(actualizar_memoria_aether(user_id, username, historial.copy()))
                        asyncio.create_task(ouroboros_reflexionar(user_id, username, historial.copy()))
                    asyncio.create_task(asyncio.to_thread(guardar_historial_ia))
                    return respuesta
                except asyncio.TimeoutError:
                    print(f"[AETHER] Timeout en Groq {modelo_actual}")
                except Exception as e:
                    err = str(e).lower()
                    if "authentication" in err or "invalid api" in err:
                        return "❌ Error de autenticación con Groq. Revisa tu `GROQ_API_KEY`."
                    elif any(x in err for x in ["rate", "429", "too many", "quota", "exceeded"]):
                        print(f"[AETHER] Rate limit Groq {modelo_actual}, rotando...")
                    else:
                        print(f"[AETHER] Error Groq {modelo_actual}: {e}")
                    _modelo_idx = (_modelo_idx + 1) % len(GROQ_MODELOS)

        # ── PROVEEDOR 2: OPENROUTER ────────────────
        if OPENROUTER_API_KEY:
            for i, modelo_or in enumerate(OPENROUTER_MODELOS):
                try:
                    print(f"[AETHER] Intentando OpenRouter: {modelo_or}")
                    respuesta = await _llamar_openrouter(mensajes, modelo_or)
                    historial.append({"role": "assistant", "content": respuesta})
                    print(f"[AETHER] OpenRouter respondió con: {modelo_or}")
                    msgs_u = sum(1 for m in historial if m["role"] == "user")
                    if msgs_u % 5 == 0:
                        asyncio.create_task(actualizar_memoria_aether(user_id, username, historial.copy()))
                        asyncio.create_task(ouroboros_reflexionar(user_id, username, historial.copy()))
                    asyncio.create_task(asyncio.to_thread(guardar_historial_ia))
                    return respuesta
                except Exception as e:
                    err = str(e).lower()
                    if "rate" in err or "429" in err:
                        print(f"[AETHER] Rate limit OpenRouter {modelo_or}")
                    else:
                        print(f"[AETHER] Error OpenRouter {modelo_or}: {e}")
        else:
            print("[AETHER] OpenRouter no configurado (sin OPENROUTER_API_KEY)")

        # ── PROVEEDOR 3: DEEPSEEK ────────────────
        if DEEPSEEK_API_KEY and deepseek_async_client:
            for i, modelo_ds in enumerate(DEEPSEEK_MODELOS):
                try:
                    print(f"[AETHER] Intentando DeepSeek: {modelo_ds}")
                    respuesta = await asyncio.wait_for(
                        _llamar_deepseek(mensajes, modelo_ds),
                        timeout=25
                    )
                    historial.append({"role": "assistant", "content": respuesta})
                    print(f"[AETHER] DeepSeek respondió con: {modelo_ds}")
                    msgs_u = sum(1 for m in historial if m["role"] == "user")
                    if msgs_u % 5 == 0:
                        asyncio.create_task(actualizar_memoria_aether(user_id, username, historial.copy()))
                        asyncio.create_task(ouroboros_reflexionar(user_id, username, historial.copy()))
                    asyncio.create_task(asyncio.to_thread(guardar_historial_ia))
                    return respuesta
                except asyncio.TimeoutError:
                    print(f"[AETHER] Timeout en DeepSeek {modelo_ds}")
                except Exception as e:
                    print(f"[AETHER] Error DeepSeek {modelo_ds}: {e}")
        else:
            print("[AETHER] DeepSeek no configurado (sin DEEPSEEK_API_KEY)")

        # ── NINGÚN PROVEEDOR DISPONIBLE ─────────
        return "⚠️ No pude conectar con ningún proveedor de IA. Inténtalo en unos segundos."

async def _llamar_groq_async(mensajes: list, modelo: str) -> str:
    """Llama a un modelo de Groq usando el cliente asíncrono."""
    global groq_async_client
    respuesta = await groq_async_client.chat.completions.create(
        model=modelo,
        max_tokens=AI_MAX_TOKENS,
        messages=mensajes
    )
    return respuesta.choices[0].message.content

async def procesar_respuesta_aether(message: discord.Message, respuesta: str, es_ticket: bool = False):
    """Procesa la respuesta de la IA: extrae acciones, las ejecuta y envía el mensaje limpio."""
    uid = message.author.id
    es_markelson = (uid == MI_ID)

    # 1. Protección total para Markelson: quitar cualquier etiqueta de moderación
    if es_markelson:
        respuesta = respuesta.replace("[AETHER_WARN]", "").replace("[AETHER_KICK]", "")

    # 2. Extraer acciones (DM, PING, REACT)
    acciones_dm = re.findall(r'\[AETHER_DM\s+(\d+)\]\s*(.*?)(?=\[AETHER_|$)', respuesta, re.DOTALL)
    acciones_ping = re.findall(r'\[AETHER_PING\s+(\d+)\]', respuesta)
    acciones_react = re.findall(r'\[AETHER_REACT\s+([^\]]+)\]', respuesta)

    # Ejecutar envío de DMs
    for user_id_str, dm_text in acciones_dm:
        try:
            user = await bot.fetch_user(int(user_id_str))
            if user:
                await user.send(dm_text.strip())
                print(f"[AETHER] DM enviado a {user} (ID {user_id_str})")
        except Exception as e:
            print(f"[AETHER] Error enviando DM a {user_id_str}: {e}")

    # Ejecutar reacciones (solo si el mensaje está en un servidor)
    if message.guild is not None:
        for emoji in acciones_react:
            try:
                await message.add_reaction(emoji.strip())
            except Exception as e:
                print(f"[AETHER] Error al reaccionar con {emoji}: {e}")

    # 3. Limpiar respuesta de etiquetas internas
    limpio = re.sub(r'\[AETHER_DM\s+\d+\]\s*.*?(?=\[AETHER_|$)', '', respuesta, flags=re.DOTALL)
    limpio = re.sub(r'\[AETHER_PING\s+\d+\]', '', limpio)
    limpio = re.sub(r'\[AETHER_REACT\s+[^\]]+\]', '', limpio)

    # Insertar las menciones reales donde se pidieron (sustituimos el placeholder que dejó la IA)
    for user_id_str in acciones_ping:
        limpio = limpio.replace(f'[AETHER_PING {user_id_str}]', f'<@{user_id_str}>', 1)

    # 4. Moderación AETHER (warn / kick) — solo en servidores
    if not es_markelson and message.guild is not None:
        if "[AETHER_KICK]" in limpio:
            limpio = limpio.replace("[AETHER_KICK]", "").strip()
            if message.guild.me.guild_permissions.kick_members:
                if message.author.top_role < message.guild.me.top_role:
                    try:
                        await message.author.kick(reason="Expulsado por AETHER: comportamiento inapropiado repetido.")
                        await message.channel.send(f"🔨 {message.author.mention} ha sido expulsado del servidor por AETHER.")
                    except Exception as e:
                        await message.channel.send(f"❌ No pude expulsar: {e}")
                else:
                    await message.channel.send(f"{message.author.mention} ⚠️ No puedo expulsarte por tu rol.")
            else:
                await message.channel.send("❌ No tengo permisos para expulsar miembros en este servidor.")
            aether_warnings.pop(uid, None)
            return  # No se envía más nada porque el usuario ya fue expulsado

        elif "[AETHER_WARN]" in limpio:
            limpio = limpio.replace("[AETHER_WARN]", "").strip()
            aether_warnings[uid] = aether_warnings.get(uid, 0) + 1
            advertencias = aether_warnings[uid]
            limpio += f"\n\n⚠️ **Advertencia {advertencias}/2. Si continúas así, serás expulsado.**"

    # 5. Cierre automático de ticket
    if "[AETHER_CLOSE_TICKET]" in limpio and es_ticket:
        limpio = limpio.replace("[AETHER_CLOSE_TICKET]", "").strip()
        await message.channel.send(f"{message.author.mention} {limpio}")
        await asyncio.sleep(1)
        await _cerrar_ticket(message.channel, cerrado_por=None)  # None = Aether
        return

    # 6. Enviar respuesta final (dividida si es necesario)
    texto_final = limpio.strip()
    if texto_final:
        prefijo = f"{message.author.mention} " if message.guild else ""
        if len(texto_final) <= 1900:
            await message.channel.send(f"{prefijo}{texto_final}")
        else:
            partes = [texto_final[i:i+1900] for i in range(0, len(texto_final), 1900)]
            for i, parte in enumerate(partes):
                prefix = prefijo if i == 0 else ""
                await message.channel.send(f"{prefix}{parte}")

