async def generate_tts_audio(text: str, voice: str = "es-ES-AlvaroNeural") -> io.BytesIO:
    """Genera un buffer MP3 en memoria a partir de texto usando edge-tts (asíncrono)."""
    communicate = edge_tts.Communicate(text, voice)
    audio_data = io.BytesIO()
    async for chunk in communicate.stream():
        if chunk["type"] == "audio":
            audio_data.write(chunk["data"])
    audio_data.seek(0)
    return audio_data

def convert_pcm_to_wav_for_groq(pcm_data: bytes, sample_rate: int = 48000, channels: int = 2) -> io.BytesIO:
    """
    Convierte PCM estéreo 48kHz de Discord a WAV mono 16kHz para Groq Whisper.
    Utiliza pydub (requiere ffmpeg).
    """
    audio_segment = AudioSegment(
        data=pcm_data,
        sample_width=2,       # 16 bits = 2 bytes por muestra
        frame_rate=sample_rate,
        channels=channels
    )
    # Convertir a mono y 16kHz (requisito de Groq Whisper)
    audio_segment = audio_segment.set_channels(1).set_frame_rate(16000)
    buffer = io.BytesIO()
    audio_segment.export(buffer, format="wav")
    buffer.seek(0)
    return buffer

