def shop_embed(category: str = "all", user=None):
    category = str(category or "all").lower()
    items = _shop_items(category)
    emoji, label = SHOP_CATEGORY_META.get(category, ("🛒", category.title()))
    embed = discord.Embed(
        title=f"{emoji} Tienda de Amatistas — {label}",
        description=(
            f"Compra con el selector de abajo o con `!comprar <id>`.\n"
            f"Moneda: {amatista} · Objetos en esta vista: **{len(items)}**\n"
            "Los boosts caducan, las decoraciones permanentes quedan en tu inventario."
        ),
        color=discord.Color.purple() if category in ("decoracion", "cosmetico", "all") else discord.Color.gold()
    )
    for iid, item in items[:12]:
        embed.add_field(
            name=f"{item['emoji']} {item['nombre']} · {item['precio']:,}{amatista}",
            value=f"`{iid}` · {item['descripcion']} · **{_shop_duration_text(item)}** · `{item.get('rareza', 'normal')}`",
            inline=False
        )
    if len(items) > 12:
        embed.set_footer(text=f"Mostrando 12 de {len(items)}. Usa el selector para comprar cualquiera de los primeros 25 de esta categoría.")
    else:
        embed.set_footer(text="Diseño mejorado · Usa categorías para navegar sin lío")
    if user:
        try:
            embed.set_author(name=f"Tienda solicitada por {user.display_name}", icon_url=user.display_avatar.url)
        except Exception:
            pass
    return embed


