SHOP_CATEGORY_META.update({
    "mascota": ("🐾", "Mascotas"),
    "titulo": ("👑", "Títulos"),
    "fondo": ("🌌", "Fondos"),
    "loot": ("🧰", "Loot"),
    "nivel": ("⭐", "Tarjetas Nivel"),
})

SHOP_RARITY_META = {
    "común": ("⚪", discord.Color.light_grey()),
    "normal": ("⚪", discord.Color.light_grey()),
    "raro": ("🔵", discord.Color.blue()),
    "épico": ("🟣", discord.Color.purple()),
    "legendario": ("🟡", discord.Color.gold()),
    "mítico": ("🔴", discord.Color.red()),
}

SHOP_SLOTS = {"titulo", "fondo", "mascota", "firma", "placa", "aura", "marco", "color", "lvl_fondo", "lvl_marco"}


def _shop_rarity_text(item: dict) -> str:
    rareza = str(item.get("rareza", "normal")).lower()
    icon, _ = SHOP_RARITY_META.get(rareza, ("⚪", discord.Color.light_grey()))
    return f"{icon} {rareza.title()}"


def _shop_color_for_category(category: str):
    category = str(category or "all").lower()
    if category in ("all", "decoracion", "perfil", "titulo", "fondo", "mascota"):
        return discord.Color.purple()
    if category == "nivel":
        return discord.Color.from_rgb(168, 85, 247)
    if category in ("jugable", "especial", "loot"):
        return discord.Color.gold()
    if category in ("proteccion", "utilidad"):
        return discord.Color.teal()
    if category == "social":
        return discord.Color.magenta()
    return discord.Color.blurple()


def _shop_user_balance(user) -> str:
    if not user:
        return ""
    try:
        d = cargar_datos()
        uid = str(user.id)
        asegurar_usuario(d, uid)
        return f"\nSaldo de {user.display_name}: **{d[uid].get('cash', 0):,}** {amatista}"
    except Exception:
        return ""


def _shop_daily_offer_ids(limit: int = 8):
    today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
    pool = list(TIENDA_ITEMS.keys())
    seed = int(hashlib.sha256((today + "|xau_public_shop_v3").encode("utf-8")).hexdigest()[:12], 16)
    rng = random.Random(seed)
    rng.shuffle(pool)
    return pool[:limit]


def _shop_offer_price(item: dict) -> int:
    base = int(item.get("precio", 0) or 0)
    return max(1, int(base * 0.80))


def shop_embed(category: str = "all", user=None, page: int = 0):
    category = str(category or "all").lower()
    items = _shop_items(category)
    per_page = 10
    max_page = max(0, (len(items) - 1) // per_page)
    page = max(0, min(int(page or 0), max_page))
    start = page * per_page
    shown = items[start:start + per_page]
    emoji, label = SHOP_CATEGORY_META.get(category, ("🛒", category.title()))

    total_consumibles = sum(1 for _, i in items if i.get("consumible") or i.get("stackable"))
    total_equipables = sum(1 for _, i in items if i.get("slot") or i.get("categoria") in ("decoracion", "perfil", "titulo", "fondo", "mascota", "cosmetico"))

    embed = discord.Embed(
        title=f"{emoji} Mercado de Amatistas — {label}",
        description=(
            "Compra objetos, abre cajas, usa consumibles, equipa decoraciones y busca ofertas diarias.\n"
            f"{amatista} Objetos: **{len(items)}** · Consumibles: **{total_consumibles}** · Equipables: **{total_equipables}**"
            f"{_shop_user_balance(user)}\n\n"
            "Atajos: `!comprar <id>` · `!usar <id>` · `!equipar <id>` · `!ofertas` · `!fondosnivel` · `!inv`"
        ),
        color=_shop_color_for_category(category)
    )

    for iid, item in shown:
        duration = _shop_duration_text(item)
        rareza = _shop_rarity_text(item)
        slot = item.get("slot")
        slot_txt = f" · Slot `{slot}`" if slot else ""
        embed.add_field(
            name=f"{item['emoji']} {item['nombre']} · {item['precio']:,}{amatista}",
            value=f"`{iid}` · {rareza}{slot_txt}\n{item['descripcion']}\n**{duration}**",
            inline=False
        )

    if not shown:
        embed.description = "Esta categoría está vacía. Cambia de pestaña con el selector."

    embed.set_footer(text=f"Página {page + 1}/{max_page + 1} · Selector compra los objetos de esta página · Tienda V3")
    if user:
        try:
            embed.set_author(name=f"Solicitado por {user.display_name}", icon_url=user.display_avatar.url)
        except Exception:
            pass
    return embed


