    @discord.ui.button(label="✋ Plantarse", style=discord.ButtonStyle.red)
    async def plantar(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.accion = "plantar"
        self.stop()
        await interaction.response.defer()

    @discord.ui.button(label="💀 Doblar", style=discord.ButtonStyle.blurple)
    async def doblar(self, interaction: discord.Interaction, button: discord.ui.Button):
        d = cargar_datos()
        uid = str(interaction.user.id)
        asegurar_usuario(d, uid)
        if d[uid]["cash"] < self.parent_apuesta:
            await interaction.response.send_message("❌ No tienes cash suficiente", ephemeral=True)
            return
        restar_de_cash(d, uid, self.parent_apuesta)
        guardar_datos(d)
        self.accion = "doblar"
        self.stop()
        await interaction.response.defer()

    async def on_timeout(self):
        self.accion = "plantar"
        self.stop()

