# Voz
# ──────────────────────────────────────────────────────────────────────────────

class ConversationAudioSink(voice_recv.AudioSink):
    """
    Sink de audio personalizado:
    - Escucha a un usuario específico.
    - Detecta voz por energía (RMS) – sin WebRTC VAD.
    - Almacena audio en buffer.
    - Al detectar silencio, transcribe con Groq Whisper, obtiene respuesta de Aether
      y la reproduce con TTS (edge-tts).
    """
    def __init__(self, bot_instance, voice_client, user_id):
        self.muted = False
        super().__init__()
        self.bot = bot_instance
        self.vc = voice_client
        self.user_id = user_id
        self.speaking = False
        self.buffer = io.BytesIO()
        self.last_speech_time = 0.0
        self.processing_lock = asyncio.Lock()
        # Decodificador OPUS mono
        self.opus_decoder = opuslib.Decoder(48000, 1)
        # Obtener el loop principal de forma segura
        try:
            self.loop = asyncio.get_running_loop()
        except RuntimeError:
            self.loop = asyncio.get_event_loop()

    def wants_opus(self) -> bool:
        return True

    def write(self, user: discord.User, data: voice_recv.VoiceData):
        if self.muted:
            return
        if user.id != self.user_id:
            return
        if not data.opus:
            return
        try:
            pcm = self.opus_decoder.decode(data.opus, frame_size=960)
        except Exception:
            return

        # Detección de voz por energía (RMS)
        audio_segment = AudioSegment(
            data=pcm,
            sample_width=2,
            frame_rate=48000,
            channels=1
        )
        loudness = audio_segment.dBFS
        if loudness > -40:  # Umbral de voz (ajústalo si quieres más/menos sensibilidad)
            if not self.speaking:
                self.speaking = True
                self.buffer = io.BytesIO()
                print("🎤 Usuario empezó a hablar...")
            self.buffer.write(pcm)
            self.last_speech_time = time.monotonic()
        elif self.speaking:
            now = time.monotonic()
            if now - self.last_speech_time > (SILENCE_THRESHOLD_MS / 1000.0):
                self.speaking = False
                # Procesar el audio en el loop principal de asyncio
                asyncio.run_coroutine_threadsafe(self.process_audio(), self.loop)

    def cleanup(self):
        """Limpia los recursos del sink (requerido por AudioSink)."""
        if hasattr(self, 'buffer'):
            self.buffer.close()

    async def process_audio(self):
        async with self.processing_lock:
            raw_pcm = self.buffer.getvalue()
            wav_buffer = convert_pcm_to_wav_for_groq(raw_pcm)

            # 1. Transcribir con Groq Whisper
            text = await self.transcribe_audio(wav_buffer)
            if not text:
                print("❌ No se detectó texto.")
                return
            print(f"🗣️ Tú: {text}")

            # 2. Obtener respuesta de Aether
            perfil = construir_perfil_aether(self.user_id)
            respuesta = await self.bot.preguntar_aether(
                user_id=self.user_id,
                user_message=text,
                username="Markelson",      # o el nombre del usuario correspondiente
                perfil_usuario=perfil
            )
            print(f"🤖 Aether: {respuesta}")

            # 3. Sintetizar voz y reproducir
            await self.speak_text(respuesta)

    async def transcribe_audio(self, wav_buffer: io.BytesIO) -> str:
        """Envía un buffer WAV a la API de transcripciones de Groq y devuelve el texto."""
        try:
            url = "https://api.groq.com/openai/v1/audio/transcriptions"
            headers = {"Authorization": f"Bearer {GROQ_API_KEY}"}
            files = {"file": ("audio.wav", wav_buffer, "audio/wav")}
            data = {"model": GROQ_STT_MODEL, "response_format": "json"}
            response = await self.loop.run_in_executor(
                None, lambda: requests.post(url, headers=headers, files=files, data=data)
            )
            response.raise_for_status()
            return response.json()["text"].strip()
        except Exception as e:
            print(f"❌ Error en STT: {e}")
            return ""

    async def speak_text(self, text: str):
        """Convierte texto a voz y lo reproduce, silenciando el micrófono mientras habla."""
        try:
            # Silenciar la recepción para no grabar la respuesta del bot
            self.muted = True
            print("🔇 Micrófono silenciado durante respuesta")

            # Generar el audio MP3 con edge-tts
            print(f"🎵 Generando TTS para: {text[:50]}...")
            mp3_buffer = await generate_tts_audio(text, voice=TTS_VOICE)
            if mp3_buffer.getbuffer().nbytes == 0:
                print("❌ El buffer MP3 está vacío.")
                return
            print(f"✅ MP3 generado ({mp3_buffer.getbuffer().nbytes} bytes)")

            # Guardar a archivo temporal para la reproducción
            with tempfile.NamedTemporaryFile(suffix=".mp3", delete=False) as f:
                f.write(mp3_buffer.read())
                temp_path = f.name
            print(f"📁 Archivo temporal: {temp_path}")

            # Crear la fuente de audio (Opus para mejor compatibilidad)
            audio_source = discord.FFmpegOpusAudio(temp_path)
            print("🔊 Iniciando reproducción...")
            self.vc.play(audio_source)

            # Esperar a que termine la reproducción
            while self.vc.is_playing():
                await asyncio.sleep(0.1)
            print("🔇 Reproducción finalizada.")

            # Eliminar el archivo temporal
            os.unlink(temp_path)
        except Exception as e:
            print(f"❌ Error en TTS: {e}")
            import traceback
            traceback.print_exc()
        finally:
            # Reactivar el micrófono
            self.muted = False
            print("🎤 Micrófono reactivado")

