class PujaModal(Modal, title="Realizar puja"):
    cantidad = TextInput(label="Cantidad a pujar", placeholder="Ej: 1000", max_length=10)

    def __init__(self, subasta_view):
        super().__init__()
        self.subasta_view = subasta_view

    async def on_submit(self, interaction: discord.Interaction):
        try:
            cant = int(self.cantidad.value)
        except ValueError:
            await interaction.response.send_message("❌ Cantidad inválida.", ephemeral=True); return
        if cant <= self.subasta_view.precio_actual:
            await interaction.response.send_message(
                f"❌ La puja mínima es **{self.subasta_view.precio_actual+1}{amatista}**.", ephemeral=True); return
        d = cargar_datos(); uid = str(interaction.user.id); asegurar_usuario(d, uid)
        if d[uid]["cash"] < cant:
            await interaction.response.send_message(
                f"❌ No tienes suficiente cash. Tienes **{d[uid]['cash']:,}{amatista}**.", ephemeral=True); return
        self.subasta_view.precio_actual = cant
        self.subasta_view.pujas.append((interaction.user.id, cant))
        await self.subasta_view.actualizar_embed(interaction)

class SubastaView(View):
    def __init__(self, subasta_id, item, precio_inicial, vendedor_id, duracion=300):
        super().__init__(timeout=duracion)
        self.subasta_id = subasta_id; self.item = item
        self.precio_actual = precio_inicial; self.vendedor_id = vendedor_id
        self.pujas: list = []; self.finalizada = False; self.message = None

    @discord.ui.button(label="💰 Pujar", style=discord.ButtonStyle.green)
    async def pujar(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id == self.vendedor_id:
            await interaction.response.send_message("❌ No puedes pujar en tu propia subasta.", ephemeral=True); return
        await interaction.response.send_modal(PujaModal(self))

    async def actualizar_embed(self, interaction: discord.Interaction):
        embed = discord.Embed(title=f"🏷️ Subasta: {self.item}", color=discord.Color.gold())
        embed.add_field(name="Precio actual", value=f"{self.precio_actual:,}{amatista}", inline=True)
        embed.add_field(name="Vendedor", value=f"<@{self.vendedor_id}>", inline=True)
        embed.add_field(name="Pujas totales", value=str(len(self.pujas)), inline=True)
        if self.pujas:
            uid_ult, cant_ult = self.pujas[-1]
            embed.add_field(name="Última puja", value=f"<@{uid_ult}> — {cant_ult:,}{amatista}", inline=False)
        await interaction.response.edit_message(embed=embed, view=self)

    async def on_timeout(self):
        if self.finalizada: return
        self.finalizada = True
        if not self.pujas:
            if self.message: await self.message.channel.send("❌ Subasta finalizada sin pujas.")
            return
        ganador_id, monto = self.pujas[-1]
        d = cargar_datos(); uid_v = str(self.vendedor_id); uid_g = str(ganador_id)
        asegurar_usuario(d, uid_v); asegurar_usuario(d, uid_g)
        if restar_de_cash(d, uid_g, monto):
            agregar_a_cash(d, uid_v, monto); guardar_datos(d)
            if self.message:
                await self.message.channel.send(
                    f"🎉 Subasta finalizada. Ganador: <@{ganador_id}> con **{monto:,}{amatista}**.")
        else:
            if self.message:
                await self.message.channel.send(f"⚠️ El ganador <@{ganador_id}> no tenía cash. Subasta cancelada.")
        subastas_d = await cargar_subastas()
        subastas_d.pop(self.subasta_id, None)
        await guardar_subastas(subastas_d)


