def _rlshop_load_state() -> dict:
    try:
        if os.path.exists(RL_SHOP_STATE_FILE):
            with open(RL_SHOP_STATE_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception as e:
        print(f"[RLSHOP] Error cargando estado: {e}")
    return {}


def _rlshop_save_state(data: dict):
    try:
        with open(RL_SHOP_STATE_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[RLSHOP] Error guardando estado: {e}")


async def _rlshop_fetch_html(url: str) -> str:
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                      "(KHTML, like Gecko) Chrome/124.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    }
    timeout = aiohttp.ClientTimeout(total=25)
    session = getattr(bot, "http_session", None)

    if session and not session.closed:
        async with session.get(url, headers=headers, timeout=timeout) as resp:
            resp.raise_for_status()
            return await resp.text()

    async with aiohttp.ClientSession(timeout=timeout) as local_session:
        async with local_session.get(url, headers=headers) as resp:
            resp.raise_for_status()
            return await resp.text()




def _rlshop_extract_page_content(html: str) -> dict:
    """Parser robusto para rlshop.gg con tiendas planas, packs y RLCS.

    rlshop.gg mezcla 3 formas:
    1) Tienda plana: cards normales con h3 + tipo + precio.
    2) Tiendas con grupos: h2 + "X items included" y debajo h3 internos.
    3) RLCS: h2 por equipo + "X items" y debajo decals/goal explosions.

    La regla clave: los h2 son carpetas/grupos, los h3/h4 son objetos reales.
    Al abrir un grupo se renderizan SOLO sus h3/h4 internos, nunca el h2/carpeta.
    """
    import html as _html_module

    html = _html_module.unescape(str(html or "")).replace("&quot;", '"')

    def _clean_text(value: str) -> str:
        value = re.sub(r"<script\b[^>]*>.*?</script>", " ", str(value or ""), flags=re.S | re.I)
        value = re.sub(r"<style\b[^>]*>.*?</style>", " ", value, flags=re.S | re.I)
        value = re.sub(r"<[^>]+>", " ", value)
        value = _html_module.unescape(value)
        return re.sub(r"\s+", " ", value).strip()

    def _full_url(url: str) -> str:
        url = (url or "").strip()
        if not url:
            return ""
        if url.startswith("//"):
            return "https:" + url
        if url.startswith("/"):
            return "https://rlshop.gg" + url
        return url

    def _all_image_matches(source: str) -> list:
        found = []
        pattern = re.compile(
            r'background-image:\s*url\(["\']?([^"\')]+)["\']?\)'
            r'|<img[^>]+(?:src|data-src)=["\']([^"\']+)["\']'
            r'|<source[^>]+srcset=["\']([^"\']+)["\']',
            re.S | re.I,
        )
        for match in pattern.finditer(source or ""):
            src = match.group(1) or match.group(2) or match.group(3) or ""
            if "," in src and " " in src:
                src = src.split(",")[0].strip().split(" ")[0]
            low = src.lower()
            if not src or "credits" in low or "data:" in low or "base64" in low:
                continue
            found.append((match.start(), match.end(), _full_url(src)))
        return found

    def _first_image(block: str) -> str:
        images = _all_image_matches(block)
        return images[0][2] if images else ""

    def _prices(block: str) -> list:
        patterns = [
            r'text-blue-400[^>]*>\s*(\d{2,5})\s*</span>',
            r'>\s*(\d{2,5})\s*</(?:span|div|p)>',
            r'Credits\s*(\d{2,5})',
            r'(\d{2,5})\s*créditos',
            r'(\d{2,5})\s*credits',
        ]
        result = []
        for pattern in patterns:
            for p in re.findall(pattern, block or "", re.I):
                try:
                    n = int(p)
                except Exception:
                    continue
                if 10 <= n <= 10000 and p not in result:
                    result.append(p)
        return result

    def _first_price(block: str) -> str:
        values = _prices(block)
        return values[0] if values else ""

    def _first_time(block: str) -> str:
        match = re.search(r'>(\d+d\s+\d+h\s+\d+m|\d+h\s+\d+m|\d+m)</span>', block or "", re.I)
        if match:
            return match.group(1).strip()
        match = re.search(r'(\d+d\s+\d+h\s+\d+m|\d+h\s+\d+m|\d+m)', _clean_text(block or ""), re.I)
        return match.group(1).strip() if match else "Disponible"

    def _paint(block: str) -> str:
        plain = _clean_text(block)
        for paint_name in RL_SHOP_PAINTS:
            if f">{paint_name}<" in block or re.search(rf"\b{re.escape(paint_name)}\b", plain):
                return paint_name
        return ""

    def _is_noise_token(token: str) -> bool:
        t = re.sub(r"\s+", " ", str(token or "")).strip()
        if not t:
            return True
        low = t.lower()
        if low in {
            "available", "disponible", "credits", "credit", "image", "image not found",
            "rlshop.gg", "rocket league item shop", "shop", "featured shop", "bundles", "rlcs",
        }:
            return True
        if re.fullmatch(r"\d{1,5}", t):
            return True
        if re.fullmatch(r"\d+d\s+\d+h\s+\d+m|\d+h\s+\d+m|\d+m", t, re.I):
            return True
        if re.fullmatch(r"\d+\s+items?(?:\s+included)?", t, re.I):
            return True
        if low.startswith("last updated"):
            return True
        return False

    def _text_tokens(block: str) -> list:
        tokens = []
        for raw in re.findall(r">\s*([^<>]{1,180}?)\s*<", block or "", re.S):
            token = _clean_text(raw)
            if token and not _is_noise_token(token):
                tokens.append(token)
        for raw in re.findall(r'(?:aria-label|title|alt)=["\']([^"\']{1,180})["\']', block or "", re.I):
            token = _clean_text(raw)
            if token and not _is_noise_token(token) and token not in tokens:
                tokens.append(token)
        return tokens

    def _normal_type(value: str) -> str:
        value_low = str(value or "").lower()
        for typ in sorted(RL_SHOP_ITEM_TYPES, key=len, reverse=True):
            if value_low == typ.lower():
                return typ
        for typ in sorted(RL_SHOP_ITEM_TYPES, key=len, reverse=True):
            if re.search(rf"\b{re.escape(typ.lower())}\b", value_low):
                return typ
        return ""

    def _dedupe_items(items: list) -> list:
        clean = []
        seen = set()
        for item in items:
            name = _clean_text(item.get("name", ""))
            type_ = _clean_text(item.get("type", "")) or "Objeto"
            if not name:
                continue
            if name.lower() in {"rocket league item shop", "rlshop.gg"}:
                continue
            if re.fullmatch(r"\d+\s+items?(?:\s+included)?", type_, re.I):
                continue
            key = (
                name.lower(), type_.lower(), str(item.get("price", "")),
                str(item.get("paint", "")).lower(), str(item.get("image", "")),
            )
            if key in seen:
                continue
            seen.add(key)
            item = dict(item)
            item["name"] = name
            item["type"] = type_
            clean.append(item)
        return clean

    def _extract_items_by_headings(source: str, *, base_pos: int = 0, group_title: str = "", require_price: bool = False) -> list:
        """Extrae objetos reales desde h3/h4.

        Importante: NO lee h2, porque h2 en rlshop.gg representa carpeta/grupo.
        Esto corrige Porsche/Bundles/RLCS: el selector ya no enseña otra vez la carpeta.
        """
        result = []
        heading_re = re.compile(r'<h[34][^>]*>(.*?)</h[34]>', re.S | re.I)
        headings = list(heading_re.finditer(source or ""))
        if not headings:
            return result

        title_low = _clean_text(group_title).lower()
        all_h2_names = {
            _clean_text(x).lower()
            for x in re.findall(r'<h2[^>]*>(.*?)</h2>', source or "", re.S | re.I)
            if _clean_text(x)
        }

        for idx, match in enumerate(headings):
            name = _clean_text(match.group(1))
            if not name or _is_noise_token(name):
                continue
            if title_low and name.lower() == title_low:
                continue
            if name.lower() in all_h2_names:
                continue

            prev_boundary = headings[idx - 1].start() if idx > 0 else 0
            next_boundary = headings[idx + 1].start() if idx + 1 < len(headings) else len(source)
            local_block = source[prev_boundary:next_boundary]
            after_heading = source[match.end():next_boundary]
            local_heading_pos = match.start() - prev_boundary

            images = _all_image_matches(local_block)
            before_images = [img for img in images if img[0] <= local_heading_pos]
            # La imagen del objeto suele ser la más cercana antes del h3.
            image = before_images[-1][2] if before_images else (images[0][2] if images else "")

            type_match = re.search(
                r'<p[^>]*class=["\'][^"\']*text-gray-400[^"\']*["\'][^>]*>(.*?)</p>',
                after_heading,
                re.S | re.I,
            )
            type_ = _clean_text(type_match.group(1)) if type_match else ""

            if not type_:
                for token in _text_tokens(after_heading[:900]):
                    typ = _normal_type(token)
                    if typ:
                        type_ = typ
                        break

            price = _first_price(after_heading) or _first_price(local_block)
            if require_price and not price:
                continue

            result.append({
                "name": name,
                "type": type_ or "Objeto",
                "price": price,
                "time": _first_time(local_block),
                "paint": _paint(local_block),
                "image": image,
                "kind": "item",
                "_pos": base_pos + match.start(),
            })

        return _dedupe_items(result)

    card_re = re.compile(r'<div[^>]+class=["\'][^"\']*\bgroup\b[^"\']*\brelative\b[^"\']*["\'][^>]*>', re.I)

    def _extract_cards(source: str, *, require_price: bool) -> list:
        """Parser de cards normales. Solo usa h3/h4 para objetos; evita h2/carpetas."""
        matches = list(card_re.finditer(source or ""))
        result = []

        for i, match in enumerate(matches):
            block_start = match.end()
            block_end = matches[i + 1].start() if i + 1 < len(matches) else len(source)
            block = source[block_start:block_end]

            name_match = (
                re.search(r'<h3[^>]*>(.*?)</h3>', block, re.S | re.I)
                or re.search(r'<h4[^>]*>(.*?)</h4>', block, re.S | re.I)
            )
            if not name_match:
                continue

            name = _clean_text(name_match.group(1))
            if not name or name.lower() in {"rocket league item shop", "rlshop.gg"}:
                continue

            type_match = re.search(r'<p[^>]*class=["\'][^"\']*text-gray-400[^"\']*["\'][^>]*>(.*?)</p>', block, re.S | re.I)
            type_ = _clean_text(type_match.group(1)) if type_match else "Objeto"
            price = _first_price(block)
            if require_price and not price:
                continue

            result.append({
                "name": name,
                "type": type_ or "Objeto",
                "price": price,
                "time": _first_time(block),
                "paint": _paint(block),
                "image": _first_image(block),
                "kind": "item",
                "_pos": match.start(),
            })

        return _dedupe_items(result)

    def _extract_loose_items(source: str, *, require_price: bool = False, base_pos: int = 0, group_title: str = "") -> list:
        """Fallback por imágenes + tokens cuando rlshop.gg cambia el markup."""
        images = _all_image_matches(source)
        result = []
        if not images:
            return result

        group_title_low = _clean_text(group_title).lower()
        group_titles = {
            _clean_text(x).lower()
            for x in re.findall(r'<h2[^>]*>(.*?)</h2>', source or "", re.S | re.I)
            if _clean_text(x)
        }

        for idx, (start, end, image) in enumerate(images):
            next_start = images[idx + 1][0] if idx + 1 < len(images) else len(source)
            snippet = source[start:min(next_start, end + 2000)]
            tokens = _text_tokens(snippet)
            if not tokens:
                continue

            paint = ""
            name = ""
            type_ = ""
            price = _first_price(snippet)
            time_value = _first_time(snippet)

            filtered = []
            for token in tokens:
                clean = _clean_text(token)
                if not clean:
                    continue
                if clean in RL_SHOP_PAINTS:
                    paint = clean
                    continue
                typ = _normal_type(clean)
                if typ and not type_:
                    type_ = typ
                    continue
                if clean.lower() in group_titles or clean.lower() == group_title_low:
                    continue
                if re.search(r"items?(?:\s+included)?", clean, re.I):
                    continue
                filtered.append(clean)

            if filtered:
                name = filtered[0]

            if not name:
                alt = re.search(r'(?:alt|title|aria-label)=["\']([^"\']+)["\']', snippet, re.I)
                if alt:
                    candidate = _clean_text(alt.group(1))
                    if candidate.lower() != group_title_low and not re.search(r"items?(?:\s+included)?", candidate, re.I):
                        name = candidate

            if not name:
                continue
            if require_price and not price:
                continue

            result.append({
                "name": name,
                "type": type_ or "Objeto",
                "price": price,
                "time": time_value,
                "paint": paint,
                "image": image,
                "kind": "item",
                "_pos": base_pos + start,
            })

        return _dedupe_items(result)

    standalone_items = []
    standalone_items.extend(_extract_cards(html, require_price=True))
    standalone_items.extend(_extract_items_by_headings(html, require_price=True))
    standalone_items.extend(_extract_loose_items(html, require_price=True))
    standalone_items = _dedupe_items(standalone_items)

    groups = []
    h2_matches = list(re.finditer(r'<h2[^>]*>(.*?)</h2>', html, re.S | re.I))

    for idx, match in enumerate(h2_matches):
        title = _clean_text(match.group(1))
        if not title or title.lower() in {"rocket league item shop", "rlshop.gg"}:
            continue

        chunk_start = match.start()
        chunk_end = h2_matches[idx + 1].start() if idx + 1 < len(h2_matches) else len(html)
        chunk = html[chunk_start:chunk_end]
        plain = _clean_text(chunk)
        included_match = re.search(r'(\d+\s+items?(?:\s+included)?)', plain, re.I)
        if not included_match:
            continue

        # Hay secciones con header de bundle + precio, y debajo h3/h4 reales.
        child_items = []
        child_items.extend(_extract_items_by_headings(chunk, base_pos=chunk_start, group_title=title, require_price=False))
        child_items.extend(_extract_cards(chunk, require_price=False))
        # El fallback solo se usa si no hay h3/h4. Así evitamos que vuelva a meter la carpeta.
        if not child_items:
            child_items.extend(_extract_loose_items(chunk, require_price=False, base_pos=chunk_start, group_title=title))

        title_low = title.lower()
        cleaned_children = []
        for child in _dedupe_items(child_items):
            child_name = _clean_text(child.get("name", ""))
            child_type = _clean_text(child.get("type", ""))
            if not child_name:
                continue
            if child_name.lower() == title_low:
                continue
            if child.get("kind") == "group":
                continue
            if re.fullmatch(r"\d+\s+items?(?:\s+included)?", child_name, re.I):
                continue
            if re.fullmatch(r"\d+\s+items?(?:\s+included)?", child_type, re.I):
                continue
            cleaned_children.append(child)

        child_items = _dedupe_items(cleaned_children)

        # El precio del grupo es el precio que sale en el encabezado de la sección.
        header_slice = chunk[: max(600, (child_items[0].get("_pos", chunk_start) - chunk_start) if child_items else 1200)]
        group_price = _first_price(header_slice) or _first_price(chunk)
        group_time = _first_time(header_slice)
        preview_image = next((c.get("image", "") for c in child_items if c.get("image")), "") or _first_image(chunk)

        groups.append({
            "name": title,
            "type": included_match.group(1),
            "price": group_price,
            "time": group_time,
            "paint": "",
            "image": preview_image,
            "kind": "group",
            "group_index": len(groups),
            "items": child_items,
            "_pos": chunk_start,
        })

    grouped_keys = {
        (child.get("name", "").lower(), child.get("type", "").lower())
        for group in groups
        for child in group.get("items", [])
    }
    group_names = {group.get("name", "").lower() for group in groups}

    filtered_standalone = []
    for item in standalone_items:
        name_low = item.get("name", "").lower()
        key = (name_low, item.get("type", "").lower())
        if name_low in group_names:
            continue
        if groups and key in grouped_keys:
            continue
        filtered_standalone.append(item)

    cards = []
    cards.extend(groups)
    cards.extend(filtered_standalone)
    cards = _dedupe_items(cards)
    cards.sort(key=lambda x: x.get("_pos", 0))

    return {
        "items": filtered_standalone,
        "groups": groups,
        "cards": cards,
    }

def _rlshop_extract_items(html: str) -> list:
    """Compatibilidad con versiones anteriores: devuelve las cards visibles de la tienda."""
    return _rlshop_extract_page_content(html).get("cards", [])


async def rlshop_get_page(index: int, force: bool = False) -> dict:
    index = max(0, min(index, len(RL_SHOP_PAGES) - 1))
    page = RL_SHOP_PAGES[index]
    cached = _rlshop_cache["pages"].get(index)
    now = time.time()

    if cached and not force and now - cached.get("time", 0) < 600:
        return cached["data"]

    html = await _rlshop_fetch_html(page["url"])
    content = _rlshop_extract_page_content(html)
    data = {
        "index": index,
        "title": page["title"],
        "url": page["url"],
        "items": content.get("cards", []),
        "standalone_items": content.get("items", []),
        "groups": content.get("groups", []),
        "fetched_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }
    _rlshop_cache["pages"][index] = {"time": now, "data": data}
    return data


async def rlshop_current_signature() -> str:
    parts = []
    for idx in range(len(RL_SHOP_PAGES)):
        try:
            data = await rlshop_get_page(idx, force=True)
            compact_cards = [
                f"card:{item.get('kind')}|{item.get('name')}|{item.get('paint')}|{item.get('type')}|{item.get('price')}"
                for item in data.get("items", [])
            ]
            compact_groups = []
            for group in data.get("groups", []):
                child = ";".join(
                    f"{item.get('name')}|{item.get('paint')}|{item.get('type')}|{item.get('price')}"
                    for item in group.get("items", [])
                )
                compact_groups.append(f"group:{group.get('name')}|{group.get('price')}|{child}")
            parts.append(f"{idx}:{';'.join(compact_cards)}##{';'.join(compact_groups)}")
        except Exception as e:
            print(f"[RLSHOP] No se pudo firmar tienda {idx}: {e}")
    return hashlib.sha256("||".join(parts).encode("utf-8")).hexdigest()


def _rlshop_font(size: int, bold: bool = False):
    if ImageFont is None:
        return None
    candidates = []
    if os.name == "nt":
        candidates += [
            r"C:\Windows\Fonts\segoeuib.ttf" if bold else r"C:\Windows\Fonts\segoeui.ttf",
            r"C:\Windows\Fonts\arialbd.ttf" if bold else r"C:\Windows\Fonts\arial.ttf",
        ]
    candidates += [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/dejavu/DejaVuSans.ttf",
    ]
    for path in candidates:
        try:
            if path and os.path.exists(path):
                return ImageFont.truetype(path, size=size)
        except Exception:
            pass
    return ImageFont.load_default()


def _rlshop_text_size(draw, text: str, font):
    box = draw.textbbox((0, 0), text, font=font)
    return box[2] - box[0], box[3] - box[1]


def _rlshop_trim_text(draw, text: str, font, max_width: int) -> str:
    text = str(text)
    if _rlshop_text_size(draw, text, font)[0] <= max_width:
        return text
    ell = "…"
    while len(text) > 1 and _rlshop_text_size(draw, text + ell, font)[0] > max_width:
        text = text[:-1]
    return text + ell


def _rlshop_gradient(size, top=(9, 9, 21), bottom=(13, 16, 36)):
    img = Image.new("RGB", size, top)
    px = img.load()
    w, h = size
    for y in range(h):
        t = y / max(1, h - 1)
        r = int(top[0] * (1 - t) + bottom[0] * t)
        g = int(top[1] * (1 - t) + bottom[1] * t)
        b = int(top[2] * (1 - t) + bottom[2] * t)
        for x in range(w):
            px[x, y] = (r, g, b)
    return img.convert("RGBA")


def _rlshop_add_glow(base, center, radius, color):
    overlay = Image.new("RGBA", base.size, (0, 0, 0, 0))
    draw = ImageDraw.Draw(overlay)
    x, y = center
    draw.ellipse((x - radius, y - radius, x + radius, y + radius), fill=color)
    overlay = overlay.filter(ImageFilter.GaussianBlur(radius // 2))
    base.alpha_composite(overlay)


async def _rlshop_download_image(url: str):
    if Image is None or not url:
        return None
    try:
        session = getattr(bot, "http_session", None)
        if session and not session.closed:
            async with session.get(url, timeout=aiohttp.ClientTimeout(total=20)) as resp:
                if resp.status != 200:
                    return None
                data = await resp.read()
        else:
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=20)) as local_session:
                async with local_session.get(url) as resp:
                    if resp.status != 200:
                        return None
                    data = await resp.read()
        return Image.open(io.BytesIO(data)).convert("RGBA")
    except Exception as e:
        print(f"[RLSHOP] Imagen no descargada: {url} | {e}")
        return None


def _rlshop_fit_paste(base, img, box):
    if img is None:
        return
    x, y, w, h = box
    img = img.copy()
    img.thumbnail((w, h), Image.Resampling.LANCZOS)
    px = x + (w - img.width) // 2
    py = y + (h - img.height) // 2
    base.alpha_composite(img, (px, py))





def _rlshop_safe_label(text: str, limit: int = 95) -> str:
    text = re.sub(r"\s+", " ", str(text or "")).strip()
    return text if len(text) <= limit else text[: max(1, limit - 1)] + "…"


async def rlshop_create_image_bytes(page_index: int, group_index: Optional[int] = None) -> bytes:
    """Genera la tienda 1920x1080 con el diseño morado y soporte de grupos desplegables."""
    if Image is None:
        raise RuntimeError("Falta Pillow. Instala: pip install pillow")

    page = await rlshop_get_page(page_index)
    groups = page.get("groups", []) or []
    selected_group = None

    if group_index is not None and 0 <= int(group_index) < len(groups):
        selected_group = groups[int(group_index)]
        raw_group_items = selected_group.get("items") or []
        # Seguridad extra: al desplegar un grupo, nunca vuelvas a dibujar la carpeta del grupo.
        filtered_group_items = []
        selected_name = str(selected_group.get("name") or "").strip().lower()
        for child in raw_group_items:
            child_name = str(child.get("name") or "").strip().lower()
            child_type = str(child.get("type") or "").strip()
            if child.get("kind") == "group":
                continue
            if selected_name and child_name == selected_name:
                continue
            if re.fullmatch(r"\d+\s+items?(?:\s+included)?", child_type, re.I):
                continue
            filtered_group_items.append(child)
        items = filtered_group_items[:8]
        title_text = selected_group.get("name") or page.get("title", "Tienda")
        subtitle_text = f"{page.get('title', 'Tienda')} · {selected_group.get('type', 'Grupo')}"
        total_count = len(filtered_group_items)
    else:
        group_index = None
        items = (page.get("items") or [])[:8]
        title_text = "Tienda de Rocket League"
        subtitle_text = page.get("title", "Objetos destacados de la tienda actual")
        if subtitle_text == "Featured Shop":
            subtitle_text = "Objetos destacados de la tienda actual"
        total_count = len(page.get("items") or [])

    if not items:
        # Fallback claro: no vuelvas a enseñar la carpeta, muestra estado real de extracción.
        fallback_name = "Sin objetos internos detectados" if selected_group else page.get("title", "Tienda")
        fallback_type = "La página no entregó los productos internos de este grupo" if selected_group else "Sin objetos detectados ahora mismo"
        items = [{
            "name": fallback_name,
            "type": fallback_type,
            "price": "0",
            "time": "Disponible",
            "paint": "",
            "image": "",
            "kind": "empty",
        }]

    W, H = 1920, 1080
    canvas = _rlshop_gradient((W, H), top=(7, 6, 18), bottom=(12, 13, 31))

    _rlshop_add_glow(canvas, (0, 0), 650, (91, 33, 182, 135))
    _rlshop_add_glow(canvas, (W, 0), 690, (168, 85, 247, 150))
    _rlshop_add_glow(canvas, (W, H), 560, (76, 29, 149, 95))
    _rlshop_add_glow(canvas, (0, H), 500, (30, 64, 175, 58))

    draw = ImageDraw.Draw(canvas)

    font_title = _rlshop_font(58, True)
    font_sub = _rlshop_font(19)
    font_badge = _rlshop_font(18, True)
    font_promo = _rlshop_font(35, True)
    font_promo_sub = _rlshop_font(17)
    font_code = _rlshop_font(46, True)
    font_name = _rlshop_font(26, True)
    font_type = _rlshop_font(17)
    font_price = _rlshop_font(23, True)
    font_small = _rlshop_font(13, True)
    font_footer = _rlshop_font(20, True)

    outer = (20, 18, W - 20, H - 18)
    draw.rounded_rectangle(
        outer,
        radius=30,
        fill=(12, 13, 30, 202),
        outline=(168, 85, 247, 32),
        width=2,
    )

    # Carrito manual para evitar emojis cuadrados en Linux.
    cart_x, cart_y = 50, 45
    cart_col = (170, 145, 255, 230)
    draw.line((cart_x, cart_y + 2, cart_x + 12, cart_y + 2, cart_x + 18, cart_y + 45), fill=cart_col, width=4)
    draw.rounded_rectangle((cart_x + 18, cart_y + 10, cart_x + 62, cart_y + 42), radius=5, outline=cart_col, width=4)
    draw.line((cart_x + 20, cart_y + 25, cart_x + 61, cart_y + 25), fill=(170, 145, 255, 120), width=2)
    for gx in (cart_x + 31, cart_x + 45, cart_x + 59):
        draw.line((gx, cart_y + 12, gx - 5, cart_y + 41), fill=(170, 145, 255, 120), width=2)
    draw.ellipse((cart_x + 22, cart_y + 49, cart_x + 32, cart_y + 59), fill=cart_col)
    draw.ellipse((cart_x + 52, cart_y + 49, cart_x + 62, cart_y + 59), fill=cart_col)

    title_text = _rlshop_trim_text(draw, title_text, font_title, W - 360)
    subtitle_text = _rlshop_trim_text(draw, subtitle_text, font_sub, W - 360)
    draw.text((128, 39), title_text, font=font_title, fill=(255, 255, 255))
    draw.text((41, 98), subtitle_text, font=font_sub, fill=(202, 192, 236))

    count_text = f"{total_count} objetos"
    count_w, _ = _rlshop_text_size(draw, count_text, font_badge)
    badge = (W - 146, 45, W - 45, 89)
    draw.rounded_rectangle(badge, radius=999, fill=(124, 58, 237, 178), outline=(216, 180, 254, 65), width=1)
    draw.text((badge[0] + (badge[2] - badge[0] - count_w) // 2, badge[1] + 10), count_text, font=font_badge, fill=(244, 232, 255))

    promo = (40, 135, W - 40, 253)
    draw.rounded_rectangle(promo, radius=24, fill=(122, 50, 225, 242), outline=(233, 213, 255, 65), width=2)
    banner_glow = Image.new("RGBA", (promo[2] - promo[0], promo[3] - promo[1]), (0, 0, 0, 0))
    gdraw = ImageDraw.Draw(banner_glow)
    gdraw.ellipse((-200, -110, 460, 250), fill=(168, 85, 247, 70))
    banner_glow = banner_glow.filter(ImageFilter.GaussianBlur(22))
    canvas.alpha_composite(banner_glow, (promo[0], promo[1]))

    flame_x, flame_y = 76, 174
    draw.ellipse((flame_x, flame_y + 7, flame_x + 24, flame_y + 32), fill=(255, 113, 26))
    draw.polygon([(flame_x + 12, flame_y - 5), (flame_x + 25, flame_y + 16), (flame_x + 13, flame_y + 36), (flame_x + 2, flame_y + 16)], fill=(255, 149, 0))
    draw.ellipse((flame_x + 8, flame_y + 13, flame_x + 18, flame_y + 31), fill=(255, 223, 91))

    draw.text((116, 169), "Apoya a Markelson en la tienda", font=font_promo, fill=(255, 255, 255))
    draw.text((76, 214), "Usa el código de creador antes de comprar objetos", font=font_promo_sub, fill=(239, 231, 255))

    code_text = RL_SHOP_CREATOR_CODE.upper()
    code_w, _ = _rlshop_text_size(draw, code_text, font_code)
    code_box = (W - 405, 154, W - 68, 234)
    draw.rounded_rectangle(code_box, radius=18, fill=(36, 24, 71, 235), outline=(255, 255, 255, 70), width=2)
    draw.text((code_box[0] + (code_box[2] - code_box[0] - code_w) // 2, code_box[1] + 14), code_text, font=font_code, fill=(255, 255, 255))

    images = await asyncio.gather(*[_rlshop_download_image(item.get("image", "")) for item in items])

    left, top = 40, 276
    gap_x, gap_y = 20, 20
    card_w = (W - left * 2 - gap_x * 3) // 4
    card_h = 370
    thumb_h = 225

    for idx, item in enumerate(items):
        col = idx % 4
        row = idx // 4
        x = left + col * (card_w + gap_x)
        y = top + row * (card_h + gap_y)
        card = (x, y, x + card_w, y + card_h)

        shadow = Image.new("RGBA", (card_w + 26, card_h + 26), (0, 0, 0, 0))
        sdraw = ImageDraw.Draw(shadow)
        sdraw.rounded_rectangle((13, 13, card_w + 13, card_h + 13), radius=20, fill=(0, 0, 0, 95))
        shadow = shadow.filter(ImageFilter.GaussianBlur(10))
        canvas.alpha_composite(shadow, (x - 13, y - 13))

        draw.rounded_rectangle(card, radius=20, fill=(18, 22, 43, 238), outline=(255, 255, 255, 14), width=1)

        thumb = (x + 12, y + 14, x + card_w - 12, y + thumb_h)
        draw.rounded_rectangle(thumb, radius=15, fill=(10, 14, 28, 255), outline=(255, 255, 255, 8), width=1)
        _rlshop_add_glow(canvas, (x + card_w // 2, y + 125), 135, (168, 85, 247, 20))

        img = images[idx] if idx < len(images) else None
        if img is not None:
            _rlshop_fit_paste(canvas, img, (thumb[0] + 12, thumb[1] + 12, thumb[2] - thumb[0] - 24, thumb[3] - thumb[1] - 24))
        else:
            ph = (thumb[0] + 25, thumb[1] + 30, thumb[2] - 25, thumb[3] - 28)
            draw.rounded_rectangle(ph, radius=18, fill=(20, 14, 42, 255), outline=(168, 85, 247, 70), width=2)
            _rlshop_add_glow(canvas, (x + card_w // 2, y + 116), 100, (168, 85, 247, 45))
            label = _rlshop_trim_text(draw, item.get("name", "Grupo"), _rlshop_font(32, True), ph[2] - ph[0] - 24)
            lw, lh = _rlshop_text_size(draw, label, _rlshop_font(32, True))
            draw.text((ph[0] + (ph[2] - ph[0] - lw) // 2, ph[1] + (ph[3] - ph[1] - lh) // 2), label, font=_rlshop_font(32, True), fill=(244, 232, 255))

        if item.get("paint"):
            bg, fg = RL_SHOP_PAINT_STYLES.get(item["paint"], ((124, 58, 237), (255, 255, 255)))
            badge_text = item["paint"]
            bw, _ = _rlshop_text_size(draw, badge_text, font_small)
            paint_box = (x + 18, y + 18, x + 18 + bw + 30, y + 18 + 29)
            draw.rounded_rectangle(paint_box, radius=999, fill=bg + (255,), outline=(255, 255, 255, 70), width=1)
            draw.text((paint_box[0] + 15, paint_box[1] + 7), badge_text, font=font_small, fill=fg)

        time_text = "Grupo" if item.get("kind") == "group" else item.get("time", "Disponible")
        tw, _ = _rlshop_text_size(draw, time_text, font_small)
        time_box = (thumb[2] - tw - 35, thumb[3] - 32, thumb[2] - 10, thumb[3] - 8)
        draw.rounded_rectangle(time_box, radius=999, fill=(13, 20, 38, 218), outline=(255, 255, 255, 22), width=1)
        draw.text((time_box[0] + 13, time_box[1] + 6), time_text, font=font_small, fill=(255, 255, 255))

        meta_y = y + thumb_h + 26
        name = _rlshop_trim_text(draw, item.get("name", "Objeto"), font_name, card_w - 34)
        draw.text((x + 17, meta_y), name, font=font_name, fill=(255, 255, 255))
        draw.text((x + 17, meta_y + 36), item.get("type", "Objeto"), font=font_type, fill=(184, 179, 209))

        price_text = str(item.get("price", "")).strip()
        if price_text and price_text != "0":
            bottom_text = f"◆  {price_text} créditos"
        elif item.get("kind") == "group":
            bottom_text = "◆  Abrir grupo"
        elif selected_group is not None:
            bottom_text = "◆  Incluido"
        else:
            bottom_text = "◆  Ver en tienda"
        draw.text((x + 17, meta_y + 74), bottom_text, font=font_price, fill=(185, 144, 255))

    footer = f"USA CÓDIGO: {RL_SHOP_CREATOR_CODE.upper()}"
    fw, _ = _rlshop_text_size(draw, footer, font_footer)
    draw.text(((W - fw) // 2, H - 43), footer, font=font_footer, fill=(255, 255, 255))

    out = io.BytesIO()
    canvas.convert("RGB").save(out, format="PNG", optimize=True)
    return out.getvalue()


async def rlshop_build_embed_and_file(page_index: int, group_index: Optional[int] = None):
    page = await rlshop_get_page(page_index)
    groups = page.get("groups", []) or []
    selected_group = groups[group_index] if group_index is not None and 0 <= int(group_index) < len(groups) else None

    image_bytes = await rlshop_create_image_bytes(page_index, group_index)
    file_tag = "main" if selected_group is None else f"grupo_{int(group_index) + 1}"
    filename = f"rlshop_{page_index + 1}_{file_tag}.png"
    file = discord.File(io.BytesIO(image_bytes), filename=filename)

    if selected_group is None:
        title = f"🛒 {page['title']}"
        description = (
            f"Tienda de Rocket League actualizada."
            f"\n\n📦 Usa el selector para abrir grupos/bundles cuando aparezcan."
            f"\n🔥 Usa código: **{RL_SHOP_CREATOR_CODE.upper()}**"
        )
    else:
        title = f"📦 {selected_group.get('name', page['title'])}"
        description = (
            f"Items internos de **{selected_group.get('name', page['title'])}**."
            f"\nPulsa **Volver a la tienda** para salir del grupo."
            f"\n\n🔥 Usa código: **{RL_SHOP_CREATOR_CODE.upper()}**"
        )

    embed = discord.Embed(
        title=title,
        description=description,
        color=0xA855F7,
        timestamp=discord.utils.utcnow()
    )
    embed.set_image(url=f"attachment://{filename}")
    embed.set_footer(text="Tienda 24/7")
    return embed, file


class RLShopGroupSelect(discord.ui.Select):
    def __init__(self, groups: list, current_group_index: Optional[int] = None, group_select_page: int = 0):
        self.group_select_page = max(0, int(group_select_page or 0))
        start = self.group_select_page * 25
        end = start + 25
        options = []

        for idx, group in enumerate(groups[start:end], start=start):
            price = str(group.get("price") or "").strip()
            group_type = str(group.get("type") or "Grupo").strip()
            description = group_type if not price or price == "0" else f"{group_type} · {price} créditos"
            options.append(discord.SelectOption(
                label=_rlshop_safe_label(group.get("name", f"Grupo {idx + 1}"), 95),
                value=str(idx),
                description=_rlshop_safe_label(description, 95),
                emoji="📦",
                default=(current_group_index == idx),
            ))

        if not options:
            options = [discord.SelectOption(label="Sin grupos", value="none", description="Esta tienda no tiene grupos detectados")]

        super().__init__(
            placeholder="Selecciona un grupo/bundle de esta tienda…",
            min_values=1,
            max_values=1,
            options=options,
            row=1,
            custom_id="rlshop_group_select",
        )

    async def callback(self, interaction: discord.Interaction):
        if not self.values or self.values[0] == "none":
            await interaction.response.send_message("No hay grupos seleccionables en esta tienda.", ephemeral=True)
            return
        await self.view._open_group(interaction, int(self.values[0]))


class RLShopBackButton(discord.ui.Button):
    def __init__(self):
        super().__init__(label="Volver a la tienda", emoji="↩️", style=discord.ButtonStyle.danger, row=2, custom_id="rlshop_back_to_shop")

    async def callback(self, interaction: discord.Interaction):
        await self.view._back_to_shop(interaction)


class RLShopGroupPageButton(discord.ui.Button):
    def __init__(self, delta: int, disabled: bool = False):
        label = "Grupos ◀" if delta < 0 else "Grupos ▶"
        custom_id = "rlshop_group_page_prev" if delta < 0 else "rlshop_group_page_next"
        super().__init__(label=label, style=discord.ButtonStyle.secondary, row=2, disabled=disabled, custom_id=custom_id)
        self.delta = delta

    async def callback(self, interaction: discord.Interaction):
        await self.view._turn_group_select_page(interaction, self.delta)


class RLShopView(discord.ui.View):
    def __init__(self, index: int = 0, group_index: Optional[int] = None, *, timeout: Optional[float] = 300, group_select_page: int = 0):
        super().__init__(timeout=timeout)
        self.index = max(0, min(int(index or 0), len(RL_SHOP_PAGES) - 1))
        self.group_index = group_index if group_index is not None else None
        self.group_select_page = max(0, int(group_select_page or 0))
        self._sync_buttons()
        self._add_group_controls()

    def _current_page_data(self) -> dict:
        cached = _rlshop_cache.get("pages", {}).get(self.index)
        if cached:
            return cached.get("data", {}) or {}
        return {}

    def _current_groups(self) -> list:
        return self._current_page_data().get("groups", []) or []

    def _sync_buttons(self):
        in_group = self.group_index is not None
        self.prev_button.disabled = in_group or self.index <= 0
        self.next_button.disabled = in_group or self.index >= len(RL_SHOP_PAGES) - 1

    def _add_group_controls(self):
        groups = self._current_groups()
        if self.group_index is not None:
            # Dentro de un grupo: solo botón rojo para volver. Así no se confunde con otra carpeta.
            self.add_item(RLShopBackButton())
            return

        if groups:
            max_page = max(0, (len(groups) - 1) // 25)
            self.group_select_page = max(0, min(self.group_select_page, max_page))
            self.add_item(RLShopGroupSelect(groups, None, self.group_select_page))

            if len(groups) > 25:
                self.add_item(RLShopGroupPageButton(-1, disabled=self.group_select_page <= 0))
                self.add_item(RLShopGroupPageButton(1, disabled=self.group_select_page >= max_page))

    async def _render_state(
        self,
        interaction: discord.Interaction,
        *,
        index: int,
        group_index: Optional[int] = None,
        group_select_page: Optional[int] = None,
    ):
        if group_select_page is None:
            group_select_page = self.group_select_page

        try:
            embed, file = await rlshop_build_embed_and_file(index, group_index)
        except Exception as e:
            print(f"[RLSHOP] Error renderizando tienda {index} grupo {group_index}: {e}")
            msg = "No pude cargar esa vista de la tienda ahora mismo. Prueba otra opción o inténtalo más tarde."
            if interaction.response.is_done():
                await interaction.followup.send(msg, ephemeral=True)
            else:
                await interaction.response.send_message(msg, ephemeral=True)
            return

        new_view = RLShopView(
            index,
            group_index=group_index,
            timeout=None if interaction.user.id == MI_ID else 300,
            group_select_page=group_select_page,
        )

        # Markelson modifica el mensaje público. Los demás navegan en privado para no spamear.
        if interaction.user.id == MI_ID:
            await interaction.response.defer()
            await interaction.message.edit(embed=embed, attachments=[file], view=new_view)
            return

        is_ephemeral = bool(getattr(interaction.message.flags, "ephemeral", False))
        if is_ephemeral:
            try:
                await interaction.response.edit_message(embed=embed, attachments=[file], view=new_view)
            except Exception:
                await interaction.response.send_message(embed=embed, file=file, view=new_view, ephemeral=True)
        else:
            await interaction.response.send_message(embed=embed, file=file, view=new_view, ephemeral=True)

    async def _move(self, interaction: discord.Interaction, delta: int):
        if self.group_index is not None:
            await interaction.response.send_message("Vuelve primero a la tienda principal para cambiar de tienda.", ephemeral=True)
            return

        new_index = max(0, min(self.index + delta, len(RL_SHOP_PAGES) - 1))
        if new_index == self.index:
            await interaction.response.send_message("No hay más tiendas en esa dirección.", ephemeral=True)
            return

        await self._render_state(interaction, index=new_index, group_index=None, group_select_page=0)

    async def _open_group(self, interaction: discord.Interaction, group_index: int):
        groups = self._current_groups()
        if not groups or group_index < 0 or group_index >= len(groups):
            await interaction.response.send_message("Ese grupo ya no está disponible en esta tienda.", ephemeral=True)
            return
        await self._render_state(interaction, index=self.index, group_index=group_index, group_select_page=group_index // 25)

    async def _back_to_shop(self, interaction: discord.Interaction):
        await self._render_state(interaction, index=self.index, group_index=None, group_select_page=self.group_select_page)

    async def _turn_group_select_page(self, interaction: discord.Interaction, delta: int):
        groups = self._current_groups()
        max_page = max(0, (len(groups) - 1) // 25)
        new_page = max(0, min(self.group_select_page + delta, max_page))
        if new_page == self.group_select_page:
            await interaction.response.send_message("No hay más grupos en esa dirección.", ephemeral=True)
            return
        await self._render_state(interaction, index=self.index, group_index=self.group_index, group_select_page=new_page)

    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary, custom_id="rlshop_prev", row=0)
    async def prev_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._move(interaction, -1)

    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary, custom_id="rlshop_next", row=0)
    async def next_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._move(interaction, 1)


async def rlshop_publish_auto(force: bool = False):
    channel = bot.get_channel(RL_SHOP_CHANNEL_ID)
    if channel is None:
        try:
            channel = await bot.fetch_channel(RL_SHOP_CHANNEL_ID)
        except Exception as e:
            print(f"[RLSHOP] No se encontró el canal {RL_SHOP_CHANNEL_ID}: {e}")
            return

    state = _rlshop_load_state()
    signature = await rlshop_current_signature()
    message = None

    message_id = state.get("message_id")
    if message_id:
        try:
            message = await channel.fetch_message(int(message_id))
        except Exception:
            message = None

    if not force and message is not None and state.get("signature") == signature:
        print("[RLSHOP] Sin cambios. No se edita la tienda.")
        return

    embed, file = await rlshop_build_embed_and_file(0)
    view = RLShopView(0, timeout=None)

    if message is None:
        message = await channel.send(embed=embed, file=file, view=view)
        print(f"[RLSHOP] Mensaje de tienda enviado: {message.id}")
    else:
        await message.edit(embed=embed, attachments=[file], view=view)
        print(f"[RLSHOP] Mensaje de tienda editado: {message.id}")

    _rlshop_save_state({
        "channel_id": RL_SHOP_CHANNEL_ID,
        "message_id": message.id,
        "signature": signature,
        "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    })


@tasks.loop(time=RL_SHOP_POST_TIME_UTC)
async def rlshop_daily_loop():
    await rlshop_publish_auto(force=False)


@rlshop_daily_loop.before_loop
async def before_rlshop_daily_loop():
    await bot.wait_until_ready()

