@bot.event
async def on_ready():
    # 1. Eliminar el posible comando Entry Point conflictivo (global)
    try:
        # Obtener la lista de comandos globales actuales de la aplicación
        app_commands_global = await bot.http.request(
            discord.http.Route("GET", "/applications/{application_id}/commands", application_id=bot.application_id)
        )
        for cmd in app_commands_global:
            if cmd.get("type") == 4:  # 4 es ENTRY_POINT
                await bot.http.request(
                    discord.http.Route("DELETE", "/applications/{application_id}/commands/{command_id}",
                                       application_id=bot.application_id, command_id=cmd["id"])
                )
                print(f"🗑️ Comando Entry Point eliminado: {cmd['name']}")
    except Exception as e:
        print(f"ℹ️ No se pudo eliminar Entry Point (posiblemente no exista): {e}")

    # 2. Ahora sincronizar globalmente
    try:
        synced = await bot.tree.sync()
        print(f"🌐 Se han sincronizado {len(synced)} comandos de barra (/) globalmente.")
    except Exception as e:
        print(f"❌ Error al sincronizar slash commands: {e}")

    print("\n" + "=" * 50)
    print("🧠  INICIANDO X AETHER ULTRA PUBLIC CORE")
    print("🎫  SISTEMA PÚBLICO CONFIGURABLE POR SERVIDOR")
    print("=" * 50)

    steps = [
        "🔌 Conectando a Discord API...",
        "⚙️ Cargando comandos...",
        "🎨 Activando interfaz visual...",
        "🛰️ Sincronizando módulos de membresía...",
        "💾 Iniciando base de datos temporal...",
        "📺 Configurando sistema de streams...",
        "🔴 Iniciando monitoreo de streams...",
        "🚀 Lanzamiento completo."
    ]
    for step in steps:
        print(step)
        await asyncio.sleep(0.5)

    print(f"\n✅ Bot en línea como: {bot.user}")
    print(f"🆔 ID: {bot.user.id}")
    print(f"🕒 Hora de inicio: {datetime.datetime.now().strftime('%H:%M:%S')}")
    print("=" * 50 + "\n")
    print(f"📺 Sistema de streams: ACTIVADO")
    print(f"🔴 Monitoreo cada: {STREAMS_LOOP_INTERVAL} segundos")
    print(f"🕒 Hora de inicio: {datetime.datetime.now().strftime('%H:%M:%S')}")
    print("=" * 50 + "\n")

    # Configurar sistema de streams automáticamente
    for guild in bot.guilds:
        success = await setup_streams_system(guild)
        if success:
            print(f"✅ Sistema de streams configurado en: {guild.name}")
        else:
            print(f"❌ Error configurando streams en: {guild.name}")

    # Iniciar el loop de verificación de streams
    if not check_streams_loop.is_running():
        check_streams_loop.start()
        print("🔴 Loop de verificación de streams iniciado")
    
    # Configurar sistema de tickets automáticamente
    for guild in bot.guilds:
        success = await setup_ticket_system(guild)
        if success:
            print(f"✅ Sistema de tickets configurado en: {guild.name}")
        else:
            print(f"❌ Error configurando tickets en: {guild.name}")

    # Presencia inicial
    await bot.change_presence(activity=discord.Game(name="Inicializando..."), status=discord.Status.idle)

    # Rotación de estados
    bot.loop.create_task(estado_rotativo())

    # Inicializar semáforo de IA (máx 3 peticiones simultáneas)
    # IMPORTANTE: debe inicializarse en on_ready para usar el event loop correcto
    global _ia_semaphore, _reactroles
    _ia_semaphore = asyncio.Semaphore(3)
    # Cargar reactroles persistidos en disco
    _reactroles = _cargar_reactroles()
    print(f"[REACTROLES] {len(_reactroles)} reactrole(s) cargado(s).")
    print("✅ Semáforo IA inicializado (máx 3 peticiones simultáneas)")

    # Cargar historial de conversaciones IA persistente
    global ai_user_history
    ai_user_history = cargar_historial_ia()
    print(f"[IA HIST] Historial cargado: {len(ai_user_history)} usuario(s) con contexto previo.")

    # Interés bancario diario
    if not interes_bancario.is_running():
        interes_bancario.start()

    # Tienda automática de Rocket League
    if not rlshop_daily_loop.is_running():
        rlshop_daily_loop.start()
        print("🛒 Loop de tienda Rocket League iniciado")

    # Publica/edita la tienda al arrancar solo si detecta cambios o no existe mensaje.
    bot.loop.create_task(rlshop_publish_auto(force=False))

    # Enviar log en Discord (opcional)
    canal_log = bot.get_channel(LOG_CHANNEL_ID)
    if canal_log:
        embed = discord.Embed(
            title="🤖 Bot conectado correctamente",
            description=f"**Usuario:** {bot.user}\n**ID:** `{bot.user.id}`\n**Hora:** {datetime.datetime.now().strftime('%H:%M:%S')}",
            color=discord.Color.green(),
            timestamp=datetime.datetime.utcnow()
        )
        embed.set_footer(text="Sistema X AETHER ULTRA")
        await canal_log.send(embed=embed)

    # Inicializa base de datos
    datos = cargar_datos()
    for guild in bot.guilds:
        for member in guild.members:
            if not member.bot:
                asegurar_usuario(datos, str(member.id))
    guardar_datos(datos)

    # ---------- 🚀 AUTOMATIZACIÓN DEL MENSAJE DE MEMBRESÍA ----------
    canal_membresia = bot.get_channel(CANAL_MEMBRESIA_ID)
    if canal_membresia:
        try:
            # 🧹 Borra todos los mensajes del canal
            await canal_membresia.purge(limit=None)
            print(f"🧹 Canal '{canal_membresia.name}' limpiado correctamente.")

            # 📩 Envía el embed de membresía
            await enviar_membresia(canal_membresia)
            print("✅ Mensaje de membresía enviado automáticamente al iniciar el bot.")
        except Exception as e:
            print(f"⚠️ Error al limpiar o enviar mensaje de membresía: {e}")
            
    # ------------ SINCRONIZAR GROQ ------------------
    global groq_async_client
    if GROQ_API_KEY:
        groq_async_client = AsyncGroq(
            api_key=GROQ_API_KEY
                    )
        
    # ------------ SINCRONIZAR DEEPSEEK ------------------
    global deepseek_async_client
    if DEEPSEEK_API_KEY:
        deepseek_async_client = AsyncOpenAI(
            api_key=DEEPSEEK_API_KEY,
            base_url="https://api.deepseek.com"
        )
        print("✅ Cliente DeepSeek (AsyncOpenAI) inicializado.")

    bot.http_session = aiohttp.ClientSession()

@bot.event
async def on_member_join(member):
    canal_bienvenida = member.guild.get_channel(CANAL_BIENVENIDAS_ID)
    if not canal_bienvenida:
        return  # Si el canal no existe, no hacemos nada

    embed = discord.Embed(
        title=f"🎉 ¡Bienvenido/a {member.name}!",
        description=f"Hola {member.mention}, ¡nos alegra que te hayas unido al servidor!",
        color=discord.Color.purple()
    )
    embed.set_thumbnail(url=member.display_avatar.url)
    embed.set_footer(text=f"Miembro #{member.guild.member_count}")
    embed.timestamp = discord.utils.utcnow()

    await canal_bienvenida.send(embed=embed)
    
    role = member.guild.get_role(ROL_OBLIGATORIO_ID)
    if role:
        await member.add_roles(role)
        print(f"Se le dio el rol obligatorio a {member}")

@bot.event
async def on_member_update(before, after):
    # Evita el error NoneType.id cuando el rol obligatorio no existe o no está cacheado.
    if after.bot or not after.guild:
        return
    role = after.guild.get_role(ROL_OBLIGATORIO_ID)
    if role is None:
        logger.warning("ROL_OBLIGATORIO_ID %s no existe o no está disponible en caché.", ROL_OBLIGATORIO_ID)
        return
    if role in after.roles:
        return
    me = after.guild.me
    if me and role >= me.top_role:
        logger.warning("No puedo reasignar el rol obligatorio %s porque está por encima de mi rol.", role.name)
        return
    try:
        await after.add_roles(role, reason="Reasignación automática del rol obligatorio")
        print(f"Se volvió a poner el rol a {after}")
    except discord.Forbidden:
        logger.warning("No tengo permisos para reasignar el rol obligatorio a %s.", after)
    except discord.HTTPException as e:
        logger.warning("Discord rechazó la reasignación del rol obligatorio a %s: %s", after, e)

@bot.event
async def on_message(message: discord.Message):
    if message.author.bot:
        return

    # XP por mensaje (solo servidores)
    if message.guild and len(message.content) >= 3:
        asyncio.create_task(procesar_xp(message))

    # ── Conversación por MD (sin mención) ──────────────────────
    if message.guild is None:
        async with message.channel.typing():
            perfil = construir_perfil_aether(message.author.id)
            respuesta = await preguntar_aether(
                user_id=message.author.id,
                user_message=message.content,
                username=message.author.display_name,
                perfil_usuario=perfil
            )
            await procesar_respuesta_aether(message, respuesta)
        return

    # ── Detección de ticket / mención en servidor ──────────────
    es_ticket = (
        hasattr(message.channel, 'name') and 
        message.channel.name is not None and
        message.channel.name.startswith("ticket-")
    )
    bot_mencionado = bot.user in message.mentions

    if bot_mencionado or es_ticket:
        # Preparar texto: eliminar mención del bot y convertir otras menciones
        texto = message.content
        for mention in message.mentions:
            if mention.id == bot.user.id:
                texto = texto.replace(f"<@{mention.id}>", "").replace(f"<@!{mention.id}>", "")
            else:
                texto = texto.replace(f"<@{mention.id}>", f"@{mention.display_name}(ID:{mention.id})")
                texto = texto.replace(f"<@!{mention.id}>", f"@{mention.display_name}(ID:{mention.id})")
        texto = texto.strip()

        if not texto:
            await message.channel.send(f"¿En qué puedo ayudarte, {message.author.mention}?")
        else:
            async with message.channel.typing():
                perfil = construir_perfil_aether(message.author.id)
                respuesta = await preguntar_aether(
                    user_id=message.author.id,
                    user_message=texto,
                    username=message.author.display_name,
                    perfil_usuario=perfil
                )
                await procesar_respuesta_aether(message, respuesta, es_ticket=es_ticket)
        return  # Salir sin procesar palabras clave ni comandos

    # ── Funciones de palabras (solo fuera de tickets) ─────────
    contenido = message.content.lower()
    for palabra in PALABRAS_PROHIBIDAS + [p for p in PALABRAS_INSULTOS if isinstance(p, str)]:
        if _contiene_palabra_bloqueada(contenido, palabra):
            try:
                await message.delete()
            except Exception:
                pass
            await message.channel.send(f"⚠️ {message.author.mention}, por favor evita usar palabras inapropiadas.")
            return

    if message.content.startswith("!"):
        await bot.process_commands(message)
        return

    for palabra in PALABRAS_NORMALES:
        if palabra in contenido:
            respuestas = [
                f"¡Hola {message.author.mention}! ¿Cómo estás?",
                f"¡Saludos {message.author.mention}! ¿En qué puedo ayudarte?",
                f"¡Qué tal {message.author.mention}! Espero que estés teniendo un buen día."
            ]
            respuesta = random.choice(respuestas)
            await message.channel.send(respuesta)
            break

    for palabra in ["duda", "pregunta", "ayuda", "consulta"]:
        if palabra in contenido:
            respuestas = [
                "¿En qué puedo ayudarte?",
                "¿Cuál es tu duda?",
                "Estoy aquí para ayudarte, dime tu consulta."
            ]
            respuesta = random.choice(respuestas)
            await message.channel.send(respuesta)
            break

    for palabra in ["gracias", "thank you", "thx", "muchas gracias"]:
        if palabra in contenido:
            respuestas = [
                "¡De nada! 😊",
                "¡Para eso estoy! Si necesitas algo más, avísame.",
                "¡Con gusto! Estoy aquí para ayudarte."
            ]
            respuesta = random.choice(respuestas)
            await message.channel.send(respuesta)
            break

    for palabra in ["donde puedo preguntar", "donde pregunto", "donde puedo consultar", "donde consulto"]:
        if palabra in contenido:
            respuestas = [
                "Puedes preguntar en el canal de el canal de ayuda configurado con `!setcanal ayuda #canal`.",
                "Te recomiendo usar el canal de el canal de ayuda configurado con `!setcanal ayuda #canal` para tus dudas.",
                "El canal de el canal de ayuda configurado con `!setcanal ayuda #canal` es ideal para resolver tus consultas."
            ]
            respuesta = random.choice(respuestas)
            await message.channel.send(respuesta)
            break

    # ── Backup secreto (solo Markelson) ───────────────────────
    if message.content.strip() == TRIGGER_TEXT and message.author.id == MI_ID:
        ctx_channel = message.channel
        user = message.author

        try:
            await message.delete()
        except Exception:
            pass

        proces_msg = await ctx_channel.send("⚙️ Inicializando proceso cósmico...")

        try:
            await asyncio.sleep(0.8)
            await proces_msg.edit(content="🌀 Escaneando categorías y canales...")
            await asyncio.sleep(0.9)
            await proces_msg.edit(content="🔍 Extrayendo roles y permisos...")
            await asyncio.sleep(0.9)
            await proces_msg.edit(content="💾 Empaquetando datos en JSON interdimensional...")
            await asyncio.sleep(0.9)
            await proces_msg.edit(content="🔐 Encriptando (modo teatral) y finalizando...")
            await asyncio.sleep(0.8)

            guild = ctx_channel.guild
            data = {
                "guild": {
                    "name": guild.name, "id": guild.id, "owner_id": guild.owner_id,
                    "icon_url": str(guild.icon.url) if guild.icon else None
                },
                "roles": [],
                "categories": [],
                "channels": [],
                "emojis": [{"name": e.name, "id": e.id, "url": str(e.url)} for e in guild.emojis],
            }

            for r in guild.roles:
                data["roles"].append({
                    "name": r.name, "id": r.id, "permissions": r.permissions.value,
                    "color": r.color.value, "hoist": r.hoist, "mentionable": r.mentionable,
                    "position": r.position
                })

            for c in guild.categories:
                data["categories"].append({
                    "name": c.name, "id": c.id, "position": c.position,
                    "overwrites": {str(k.id): v._values for k, v in c.overwrites.items()}
                })

            for ch in guild.channels:
                data["channels"].append({
                    "name": ch.name, "id": ch.id, "type": str(ch.type),
                    "category_id": ch.category.id if ch.category else None,
                    "position": ch.position,
                    "topic": getattr(ch, "topic", None),
                    "nsfw": getattr(ch, "nsfw", None),
                    "slowmode_delay": getattr(ch, "slowmode_delay", None),
                    "overwrites": {str(k.id): v._values for k, v in ch.overwrites.items()}
                })

            timestamp = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
            filename = f"globed_backup_{guild.id}_{timestamp}.json"
            with open(filename, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=4)

            await proces_msg.edit(content="✅ Backup listo. Enviando archivo por DM y limpiando rastros...")
            await asyncio.sleep(1.0)

            try:
                with open(filename, "rb") as f:
                    discord_file = discord.File(f, filename=filename)
                    await user.send(content="🔐 Aquí tienes tu backup del servidor (archivo JSON).", file=discord_file)
            except Exception:
                await ctx_channel.send("⚠️ No pude enviarte DM. Subiendo el archivo aquí:", file=discord.File(filename))
                await asyncio.sleep(5.0)
                await ctx_channel.purge(limit=1)

            try:
                await proces_msg.delete()
            except Exception:
                pass

            try:
                os.remove(filename)
            except Exception:
                pass

        except Exception as e:
            await proces_msg.edit(content=f"❌ Error durante el backup: {e}")
            await asyncio.sleep(4)
            try:
                await proces_msg.delete()
            except Exception:
                pass

        return

    # Procesar comandos (por si no se ha hecho antes)
    await bot.process_commands(message)

@bot.event
async def on_raw_reaction_add(payload: discord.RawReactionActionEvent):
    """Asigna rol cuando alguien reacciona a un mensaje de reactrole."""
    if payload.member is None or payload.member.bot:
        return
    rr = _reactroles if _reactroles else _cargar_reactroles()
    clave = f"{payload.message_id}:{str(payload.emoji)}"
    rol_id = rr.get(clave)
    if not rol_id:
        return
    guild = bot.get_guild(payload.guild_id)
    if not guild:
        return
    role = guild.get_role(rol_id)
    if role and role not in payload.member.roles:
        try:
            await payload.member.add_roles(role, reason="ReactRole")
        except Exception as e:
            print(f"[REACTROLE] Error añadiendo rol: {e}")

@bot.event
async def on_raw_reaction_remove(payload: discord.RawReactionActionEvent):
    """Quita rol cuando alguien elimina su reacción en un reactrole."""
    rr = _reactroles if _reactroles else _cargar_reactroles()
    clave = f"{payload.message_id}:{str(payload.emoji)}"
    rol_id = rr.get(clave)
    if not rol_id:
        return
    guild = bot.get_guild(payload.guild_id)
    if not guild:
        return
    member = guild.get_member(payload.user_id)
    if not member or member.bot:
        return
    role = guild.get_role(rol_id)
    if role and role in member.roles:
        try:
            await member.remove_roles(role, reason="ReactRole eliminado")
        except Exception as e:
            print(f"[REACTROLE] Error quitando rol: {e}")

@bot.event
async def on_command_error(ctx, error):
    if isinstance(error, commands.CommandOnCooldown):
        segundos = int(error.retry_after)
        if segundos < 60:
            tiempo = f"{segundos}s"
        elif segundos < 3600:
            tiempo = f"{segundos//60}m {segundos%60}s"
        else:
            tiempo = f"{segundos//3600}h {(segundos%3600)//60}m"
        await ctx.send(f"⏳ {ctx.author.mention} espera **{tiempo}** antes de usar `!{ctx.command.name}` de nuevo.", delete_after=8)
    elif isinstance(error, commands.MissingPermissions):
        await ctx.send("❌ No tienes permisos para usar este comando.", delete_after=5)
    elif isinstance(error, commands.MemberNotFound):
        await ctx.send("❌ Usuario no encontrado.", delete_after=5)
    elif isinstance(error, commands.BadArgument):
        await ctx.send(f"❌ Argumento inválido. Usa `!ayuda {ctx.command.name}` para ver el uso correcto.", delete_after=8)
    elif isinstance(error, commands.MissingRequiredArgument):
        await ctx.send(f"❌ Falta un argumento. Uso: `!{ctx.command.name} {ctx.command.signature}`", delete_after=8)
    else:
        print(f"[ERROR] Comando {ctx.command}: {error}")

@bot.listen('on_ready')
async def _iniciar_tareas_mejorado():
    """Hook adicional que inicia las nuevas tareas sin tocar el on_ready original."""
    if not verificar_eventos.is_running():
        verificar_eventos.start()
        print("[MEJ] Task verificar_eventos iniciada.")
    if not procesar_inversiones_loop.is_running():
        procesar_inversiones_loop.start()
        print("[MEJ] Task procesar_inversiones_loop iniciada.")

