def _find_shop_item_by_type(tipo: str):
    tipo = str(tipo or "")
    for item_id, item in TIENDA_ITEMS.items():
        if item_id == tipo or str(item.get("tipo", item_id)) == tipo:
            return item_id, item
    return None, None


def _level_equipped_item(datos: dict, uid: str, slot: str):
    asegurar_usuario(datos, uid)
    equipado = datos[uid].get("equipado", {}) if isinstance(datos[uid].get("equipado", {}), dict) else {}
    tipo = equipado.get(slot)
    if not tipo:
        return None, None, None
    inv = datos[uid].get("items", {})
    if tipo not in inv:
        return None, None, None
    item_id, item = _find_shop_item_by_type(tipo)
    return tipo, item_id, item


def _level_style_for_user(datos: dict, uid: str):
    _, _, item = _level_equipped_item(datos, uid, "lvl_fondo")
    style_id = (item or {}).get("level_style", "default")
    return LEVEL_CARD_STYLES.get(style_id, LEVEL_CARD_STYLES["default"]), item


def _level_frame_for_user(datos: dict, uid: str):
    _, _, item = _level_equipped_item(datos, uid, "lvl_marco")
    return item


def _level_font(size: int, bold: bool = False):
    if not ImageFont:
        return None
    names = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
    ]
    for path in names:
        try:
            return ImageFont.truetype(path, size)
        except Exception:
            pass
    try:
        return ImageFont.load_default()
    except Exception:
        return None


def _level_gradient(size, colors):
    w, h = size
    img = Image.new("RGB", size, colors[0])
    px = img.load()
    c1, c2, c3 = colors
    for y in range(h):
        t = y / max(h - 1, 1)
        if t < 0.55:
            a = t / 0.55
            c = tuple(int(c1[i] * (1 - a) + c2[i] * a) for i in range(3))
        else:
            a = (t - 0.55) / 0.45
            c = tuple(int(c2[i] * (1 - a) + c3[i] * a) for i in range(3))
        for x in range(w):
            # Pequeño brillo diagonal, como una tarjeta premium.
            glow = int(18 * (x / max(w, 1)) * (1 - abs(0.5 - t)))
            px[x, y] = tuple(min(255, v + glow) for v in c)
    return img



def _xp_needed_for_level(nivel: int) -> int:
    """Cantidad de XP necesaria para completar el nivel actual."""
    nivel = max(1, int(nivel or 1))
    return 100 + (nivel - 1) * 50

def _rounded_mask(size, radius):
    mask = Image.new("L", size, 0)
    d = ImageDraw.Draw(mask)
    d.rounded_rectangle((0, 0, size[0]-1, size[1]-1), radius=radius, fill=255)
    return mask


async def _level_card_file(ctx, miembro: discord.Member, datos: dict):
    """Genera una tarjeta XP visual con avatar, barra de experiencia y personalización."""
    if not Image or not ImageDraw or not ImageFilter:
        return None

    uid = str(miembro.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    nivel = int(info.get("nivel", 1) or 1)
    xp = int(info.get("experiencia", 0) or 0)
    xp_necesario = max(1, _xp_needed_for_level(nivel))
    xp_actual = max(0, min(xp, xp_necesario))
    pct = max(0.0, min(1.0, xp_actual / xp_necesario))
    xp_restante = max(0, xp_necesario - xp_actual)
    rank = obtener_rank_por_monedas(datos, uid)

    style, bg_item = _level_style_for_user(datos, uid)
    frame_item = _level_frame_for_user(datos, uid)
    title_item = _level_equipped_item(datos, uid, "titulo")[2]
    pet_item = _level_equipped_item(datos, uid, "mascota")[2]
    badge_item = _level_equipped_item(datos, uid, "placa")[2]

    W, H = 1280, 450
    img = _level_gradient((W, H), style["colors"]).convert("RGBA")

    # Decoración de fondo premium
    deco = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    dd = ImageDraw.Draw(deco)
    glow = style["glow"]
    for i in range(14):
        x = int((i * 151) % W)
        y = int((i * 83) % H)
        r = 80 + (i % 4) * 20
        dd.ellipse((x-r, y-r, x+r, y+r), fill=(*glow, 16))
    for i in range(8):
        y = 36 + i * 52
        dd.line((40, y, W - 40, y), fill=(255, 255, 255, 7), width=1)
    if (bg_item or {}).get("level_style") == "pixel":
        for x in range(0, W, 34):
            for y in range(0, H, 34):
                if (x // 34 + y // 34) % 3 == 0:
                    dd.rectangle((x, y, x + 14, y + 14), fill=(*style["accent"], 30))
    elif (bg_item or {}).get("level_style") == "circuit":
        for y in range(58, H, 68):
            dd.line((56, y, W - 56, y), fill=(*style["accent"], 42), width=2)
            for x in range(96, W - 56, 168):
                dd.ellipse((x - 4, y - 4, x + 4, y + 4), fill=(*style["accent"], 90))
    elif (bg_item or {}).get("level_style") == "blue_fire":
        for i in range(15):
            x = 30 + i * 85
            dd.pieslice((x, H - 160, x + 130, H + 30), 180, 360, fill=(*style["accent"], 32))
    img = Image.alpha_composite(img, deco.filter(ImageFilter.GaussianBlur(3)))

    draw = ImageDraw.Draw(img)
    font_big = _level_font(50, True)
    font_title = _level_font(36, True)
    font_mid = _level_font(24, True)
    font_small = _level_font(20, False)
    font_tiny = _level_font(16, False)

    # Marco y paneles
    main_panel = (28, 28, W - 28, H - 28)
    draw.rounded_rectangle(main_panel, radius=34, fill=(10, 12, 28, 162), outline=(*style["accent"], 105), width=2)
    if frame_item:
        frame_color = (255, 215, 0, 225) if "dorado" in frame_item.get("tipo", "") else (*style["accent"], 230)
        draw.rounded_rectangle((18, 18, W - 18, H - 18), radius=40, outline=frame_color, width=6)

    # Panel avatar
    left_panel = (48, 62, 292, 388)
    draw.rounded_rectangle(left_panel, radius=30, fill=(255, 255, 255, 20), outline=(255, 255, 255, 35), width=1)

    avatar_size = 178
    avatar_pos = (82, 98)
    try:
        avatar_bytes = await miembro.display_avatar.replace(size=256, static_format="png").read()
        av = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA").resize((avatar_size, avatar_size))
    except Exception:
        av = Image.new("RGBA", (avatar_size, avatar_size), (*style["accent"], 255))
        ad = ImageDraw.Draw(av)
        initial = (miembro.display_name[:1] or "?").upper()
        ad.text((avatar_size // 2 - 22, avatar_size // 2 - 34), initial, font=_level_font(68, True), fill=(20, 20, 35, 255))
    mask = Image.new("L", (avatar_size, avatar_size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, avatar_size - 1, avatar_size - 1), fill=255)
    shadow = Image.new("RGBA", (avatar_size + 22, avatar_size + 22), (0, 0, 0, 0))
    sdraw = ImageDraw.Draw(shadow)
    sdraw.ellipse((8, 8, avatar_size + 10, avatar_size + 10), fill=(0, 0, 0, 120))
    shadow = shadow.filter(ImageFilter.GaussianBlur(8))
    img.paste(shadow, (avatar_pos[0] - 11, avatar_pos[1] - 7), shadow)
    img.paste(av, avatar_pos, mask)
    draw.ellipse((avatar_pos[0] - 8, avatar_pos[1] - 8, avatar_pos[0] + avatar_size + 8, avatar_pos[1] + avatar_size + 8), outline=(*style["accent"], 230), width=7)

    draw.text((78, 294), "XP CARD", font=font_tiny, fill=(230, 230, 245, 185))
    draw.text((78, 316), f"Nivel {nivel}", font=font_mid, fill=(255, 255, 255, 255))
    draw.text((78, 347), f"Rank {('#' + str(rank)) if rank else 'N/A'}", font=font_small, fill=(230, 230, 245, 220))

    # Cabecera
    display_name = miembro.display_name[:30]
    draw.text((332, 70), display_name, font=font_big, fill=(255, 255, 255, 255))
    subtitle = (title_item or {}).get("nombre") or "Tarjeta XP personalizable"
    subemoji = (title_item or {}).get("emoji", "⭐")
    draw.text((336, 128), f"{subemoji} {subtitle}", font=font_small, fill=(*style["accent"], 255))

    # Badge de nivel
    lvl_box = (1042, 64, 1198, 144)
    draw.rounded_rectangle(lvl_box, radius=22, fill=(255, 255, 255, 24), outline=(*style["accent"], 90), width=2)
    draw.text((1078, 78), "LEVEL", font=font_tiny, fill=(235, 235, 246, 215))
    lvl_text = str(nivel)
    lx = 1116 - (len(lvl_text) - 1) * 10
    draw.text((lx, 95), lvl_text, font=font_title, fill=(255, 255, 255, 255))

    # Barra XP con glow
    bar_x, bar_y, bar_w, bar_h = 336, 202, 842, 42
    draw.text((bar_x, bar_y - 34), f"Experiencia · {xp_actual:,}/{xp_necesario:,} XP", font=font_small, fill=(245, 245, 255, 240))
    draw.text((bar_x + bar_w - 166, bar_y - 34), f"Faltan {xp_restante:,} XP", font=font_tiny, fill=(225, 225, 240, 215))

    glow_layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    gdraw = ImageDraw.Draw(glow_layer)
    gdraw.rounded_rectangle((bar_x, bar_y, bar_x + bar_w, bar_y + bar_h), radius=21, fill=(255, 255, 255, 18))
    fill_w = max(20, int(bar_w * pct)) if pct > 0 else 0
    if fill_w:
        gdraw.rounded_rectangle((bar_x, bar_y, bar_x + fill_w, bar_y + bar_h), radius=21, fill=(*style["accent"], 220))
    glow_layer = glow_layer.filter(ImageFilter.GaussianBlur(6))
    img.alpha_composite(glow_layer)
    draw.rounded_rectangle((bar_x, bar_y, bar_x + bar_w, bar_y + bar_h), radius=21, fill=(255, 255, 255, 22), outline=(255, 255, 255, 30), width=1)
    if fill_w:
        draw.rounded_rectangle((bar_x, bar_y, bar_x + fill_w, bar_y + bar_h), radius=21, fill=(*style["accent"], 235))
    pct_text = f"{int(pct * 100)}%"
    tw = len(pct_text) * 11
    draw.text((bar_x + bar_w/2 - tw/2, bar_y + 8), pct_text, font=font_mid, fill=(255, 255, 255, 250))

    # Stats
    stats = [
        ("💰 Cash", f"{int(info.get('cash', 0) or 0):,}"),
        ("🏦 Banco", f"{int(info.get('bank', 0) or 0):,}"),
        ("✨ Reputación", str(info.get("reputacion", 0))),
        ("📈 Progreso", f"{xp_actual:,} / {xp_necesario:,}"),
    ]
    sx, sy, sw, sh, gap = 336, 284, 194, 72, 18
    for idx, (label, value) in enumerate(stats):
        x1 = sx + idx * (sw + gap)
        draw.rounded_rectangle((x1, sy, x1 + sw, sy + sh), radius=20, fill=(255, 255, 255, 22), outline=(255, 255, 255, 34), width=1)
        draw.text((x1 + 16, sy + 13), label, font=font_tiny, fill=(232, 232, 246, 220))
        draw.text((x1 + 16, sy + 38), value, font=font_small, fill=(255, 255, 255, 255))

    # Chips inferiores
    chips = []
    if bg_item:
        chips.append(f"{bg_item.get('emoji','🌌')} {bg_item.get('nombre')}")
    if frame_item:
        chips.append(f"{frame_item.get('emoji','💠')} {frame_item.get('nombre')}")
    if pet_item:
        chips.append(f"{pet_item.get('emoji','🐾')} {pet_item.get('nombre')}")
    if badge_item:
        chips.append(f"{badge_item.get('emoji','🪪')} {badge_item.get('nombre')}")

    chip_text = " · ".join(chips[:3]) if chips else "Desbloquea fondos y marcos en !tienda nivel y equípalos con !equipar"
    chip_box = (336, 380, 1180, 414)
    draw.rounded_rectangle(chip_box, radius=16, fill=(255, 255, 255, 18), outline=(255, 255, 255, 20), width=1)
    draw.text((352, 389), chip_text[:105], font=font_tiny, fill=(255, 255, 255, 220))

    draw.text((W - 250, H - 40), "X AETHER ULTRA XP CARD", font=font_tiny, fill=(255, 255, 255, 150))

    buffer = io.BytesIO()
    img.save(buffer, format="PNG")
    buffer.seek(0)
    return discord.File(buffer, filename=f"nivel_{miembro.id}.png")


# # @bot.command(name="lvl", aliases=["xpcard", "cardxp", "tarjetaxp"])  # clean core: decorador antiguo desactivado  # XAU310 deduplicado: comando antiguo desactivado
async def lvl_cmd(ctx, miembro: discord.Member = None):
    """Muestra tu XP Card visual con avatar, nivel y barra de experiencia."""
    miembro = miembro or ctx.author
    d = cargar_datos()
    uid = str(miembro.id)
    asegurar_usuario(d, uid)
    nivel = d[uid].get("nivel", 1)
    xp = d[uid].get("experiencia", 0)
    xp_necesario = max(1, _xp_needed_for_level(nivel))
    progreso = min(int((xp / xp_necesario) * 20), 20)
    barra = "█" * progreso + "░" * (20 - progreso)

    file = await _level_card_file(ctx, miembro, d)
    if file:
        await ctx.send(file=file)
        return

    # Fallback si Pillow no está instalado o falla la imagen.
    embed = discord.Embed(title=f"⭐ Nivel de {miembro.display_name}", color=discord.Color.purple())
    embed.add_field(name="Nivel", value=str(nivel), inline=True)
    embed.add_field(name="XP", value=f"{xp}/{xp_necesario}", inline=True)
    embed.add_field(name="Progreso", value=f"`[{barra}]`", inline=False)
    embed.add_field(name="🎨 Personalización", value="Compra fondos en `!tienda nivel` y equipa con `!equipar <id>`.", inline=False)
    embed.set_thumbnail(url=miembro.display_avatar.url)
    await ctx.send(embed=embed)


# @bot.command(name="fondosnivel", aliases=["levelcards", "tarjetasnivel"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 5, commands.BucketType.user)
async def fondosnivel_cmd(ctx, miembro: discord.Member = None):
    """Muestra tarjetas de nivel desbloqueadas y equipadas."""
    miembro = miembro or ctx.author
    datos = cargar_datos()
    uid = str(miembro.id)
    asegurar_usuario(datos, uid)
    inv = datos[uid].get("items", {})
    equipado = datos[uid].get("equipado", {}) if isinstance(datos[uid].get("equipado", {}), dict) else {}

    fondos = []
    marcos = []
    bloqueados = []
    for item_id, item in TIENDA_ITEMS.items():
        if str(item.get("categoria", "")).lower() != "nivel":
            continue
        tipo = item.get("tipo", item_id)
        owned = tipo in inv
        marker = "✅" if owned else "🔒"
        line = f"{marker} `{item_id}` · {item.get('emoji','⭐')} **{item.get('nombre')}** · {item.get('precio',0):,}{amatista} · {item.get('rareza','normal')}"
        if item.get("slot") == "lvl_marco":
            marcos.append(line)
        else:
            fondos.append(line)
        if not owned:
            bloqueados.append(item_id)

    embed = discord.Embed(title=f"⭐ Tarjetas de nivel — {miembro.display_name}", color=discord.Color.purple())
    embed.description = (
        f"Fondo equipado: `{equipado.get('lvl_fondo', 'base')}`\n"
        f"Marco equipado: `{equipado.get('lvl_marco', 'ninguno')}`\n\n"
        "Compra en `!tienda nivel` y equipa con `!equipar <id>`."
    )
    embed.set_thumbnail(url=miembro.display_avatar.url)
    if fondos:
        embed.add_field(name="🌌 Fondos", value="\n".join(fondos[:12])[:1024], inline=False)
    if marcos:
        embed.add_field(name="🖼️ Marcos", value="\n".join(marcos[:8])[:1024], inline=False)
    embed.set_footer(text="Usa !previewnivel para ver cómo queda tu tarjeta antes de presumirla.")
    await ctx.send(embed=embed)


