@bot.command(name="asignar_rol")
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def asignar_rol_cmd(ctx):
    """Asigna el rol obligatorio a todos los miembros que no lo tengan."""
    rol = ctx.guild.get_role(ROL_OBLIGATORIO_ID)
    if not rol:
        await ctx.send("❌ Rol obligatorio no encontrado. Revisa ROL_OBLIGATORIO_ID."); return
    count = 0
    async with ctx.typing():
        for member in ctx.guild.members:
            if not member.bot and rol not in member.roles:
                try:
                    await member.add_roles(rol)
                    count += 1
                    await asyncio.sleep(0.3)
                except:
                    pass
    await ctx.send(f"✅ Rol asignado a **{count}** miembros.")

