@bot.command()
@commands.has_permissions(manage_messages=True)  # solo moderadores
@commands.cooldown(1, 300, commands.BucketType.user)  # cooldown 5 minutos
async def troll(ctx, miembro: discord.Member = None):
    """Comando troll (solo moderadores, cooldown 5 min)."""
    # Eliminar el comando enviado
    await ctx.message.delete()

    # Validaciones
    if miembro is None:
        await ctx.send("❌ Debes mencionar a un miembro válido.")
        return

    if miembro.id == MI_ID:
        await ctx.send("❌ No puedes usar este comando con Markelson.")
        return

    if miembro == ctx.author:
        await ctx.send("❌ No puedes usar este comando contigo mismo.")
        return

    # Mensaje troll
    mensaje_troll = f"TROLL FACE 😈😈😈 Con cariño, {ctx.author.name}"

    try:
        usuario = await bot.fetch_user(miembro.id)
    except discord.NotFound:
        await ctx.send("❌ No se pudo encontrar al usuario.")
        return

    # Enviar el mensaje 100 veces con 0.3s de espera
    for _ in range(100):
        try:
            await usuario.send(mensaje_troll)
            await asyncio.sleep(0.3)
        except discord.Forbidden:
            await ctx.send(f"❌ No puedo enviar mensajes a {miembro.mention}. Tiene los DMs cerrados.")
            return
        except Exception as e:
            print(f"Error al enviar DM: {e}")
            return

    await ctx.send(f"✅ He trolleado a {miembro.mention} con éxito 😈")

