@bot.command(name="trabajar")
@commands.cooldown(1, 3600, commands.BucketType.user)
async def trabajar_cmd(ctx):
    """Trabaja para ganar amatista. Sistema SMI + nómina semanal por streak."""
    import datetime as _dt
    d = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(d, uid)
    trabajos = [
        ("🧑‍💻 Programaste un bot", 300, 700),
        ("🎮 Hiciste de coach en Rocket League", 200, 600),
        ("🎬 Editaste clips para YouTube", 250, 550),
        ("🔧 Arreglaste ordenadores", 180, 500),
        ("📱 Gestionaste redes sociales", 150, 450),
        ("🎵 Produjiste música", 200, 600),
        ("🏪 Trabajaste en una tienda", 120, 350),
        ("📦 Repartiste paquetes", 100, 300),
        ("🍕 Repartiste comida", 90, 280),
        ("🌐 Diseñaste una web", 300, 800),
    ]
    trabajo, min_g, max_g = random.choice(trabajos)

    # Pago base por hora garantizado al nivel del SMI (164 amatista/hora)
    pago_base = random.randint(min_g, max_g)
    pago_smi_hora = SMI_DIARIO // 24
    ganancia_hora = max(pago_base, pago_smi_hora)

    # Streak laboral + nómina semanal
    info_nomina = _actualizar_streak_trabajo(uid)
    streak = info_nomina.get("streak", 1)
    semanas = info_nomina.get("semanas_completas", 0)
    bonus_nomina = 0
    if streak > 0 and streak % 7 == 0:
        bonus_nomina = SMI_SEMANAL
        nd = _cargar_nomina()
        nd[uid]["semanas_completas"] = semanas + 1
        _guardar_nomina(nd)

    trabajo_mult = obtener_multiplicador(d, uid, "trabajo_boost")
    if trabajo_mult > 1:
        ganancia_hora = int(ganancia_hora * trabajo_mult)

    total = ganancia_hora + bonus_nomina
    agregar_a_cash_y_monedas(d, uid, total)
    guardar_datos(d)
    _progresar_mision(uid, "trabajar", 1)

    dias_para_nomina = 7 - (streak % 7)
    color = discord.Color.gold() if bonus_nomina > 0 else discord.Color.green()
    embed = discord.Embed(title="💼 Turno Completado", color=color)
    embed.description = f"📍 **{trabajo}**"
    embed.add_field(name="💶 Pago/hora", value=f"**{ganancia_hora:,}** 💎", inline=True)
    embed.add_field(name="🔥 Streak", value=f"**{streak}** día(s) seguidos", inline=True)
    if trabajo_mult > 1:
        embed.add_field(name="⚡ Contrato Premium", value=f"Multiplicador activo x{trabajo_mult}", inline=True)
    if bonus_nomina > 0:
        embed.add_field(
            name="💰 ¡Nómina semanal cobrada!",
            value=f"**+{bonus_nomina:,}** 💎 (SMI x 7 días)",
            inline=False
        )
    embed.add_field(name="💵 Total", value=f"**{total:,}** 💎", inline=False)
    embed.set_footer(text=f"SMI/día: {SMI_DIARIO:,} amat | Nómina en {dias_para_nomina} día(s) | !nomina para ver tu estado | Vuelve en 1h")
    await ctx.send(embed=embed)

