@bot.command(name="misiones")
@commands.cooldown(1, 10, commands.BucketType.user)
async def misiones_cmd(ctx):
    import datetime as _dt
    hoy = _dt.datetime.now().strftime("%Y-%m-%d")
    uid = str(ctx.author.id)
    misiones_activas = cargar_misiones_activas()
    MISIONES_POOL = [
        {"id": "msg", "desc": "Enviar mensajes", "meta": 20, "tipo": "msg", "recompensa": 100},
        {"id": "rep_dado", "desc": "Dar reputación", "meta": 5, "tipo": "rep_dado", "recompensa": 150},
        {"id": "robar", "desc": "Robar a otros usuarios", "meta": 3, "tipo": "robar", "recompensa": 200},
        {"id": "lvl_up", "desc": "Subir de nivel", "meta": 1, "tipo": "lvl_up", "recompensa": 250},
        {"id": "tienda", "desc": "Comprar en la tienda", "meta": 1, "tipo": "tienda", "recompensa": 300},
    ]
    
    if uid not in misiones_activas or misiones_activas[uid].get("fecha") != hoy:
        sel = random.sample(MISIONES_POOL, 3)
        misiones_activas[uid] = {"fecha": hoy, "misiones": [
            {"id": m["id"], "desc": m["desc"], "meta": m["meta"], "tipo": m["tipo"],
             "recompensa": m["recompensa"], "progreso": 0, "completada": False} for m in sel
        ]}
        _guardar_misiones(misiones_activas)
    misiones = misiones_activas[uid]["misiones"]
    embed = discord.Embed(title="📋 Misiones Diarias", color=discord.Color.purple(), description=f"Fecha: {hoy}")
    total_rec = 0
    completadas = sum(1 for m in misiones if m.get("completada"))
    for m in misiones:
        if m.get("completada"):
            st = "✅ Completada"
            if m.get("reclamada"):
                st = "💰 Reclamada"
        else:
            st = f"🟡 {m.get('progreso',0)}/{m['meta']}"
        embed.add_field(
            name=f"{st} — {m['desc']}",
            value=f"Recompensa: **{m['recompensa']}** 💎",
            inline=False
        )
        if m.get("completada") and not m.get("reclamada"):
            total_rec += m["recompensa"]
    if total_rec > 0:
        d = cargar_datos()
        asegurar_usuario(d, uid)
        misiones_mult = obtener_multiplicador(d, uid, "misiones_boost")
        if misiones_mult > 1:
            total_rec = int(total_rec * misiones_mult)
        agregar_a_cash_y_monedas(d, uid, total_rec)
        guardar_datos(d)
        for m in misiones:
            if m.get("completada") and not m.get("reclamada"):
                m["reclamada"] = True
        _guardar_misiones(misiones_activas)
        embed.color = discord.Color.gold()
        embed.set_footer(text=f"🎉 Has reclamado {total_rec:,} amatista de {completadas} misión/misiones!")
    elif completadas > 0:
        embed.set_footer(text=f"✅ {completadas} misión(es) completada(s) y reclamada(s).")
    else:
        embed.set_footer(text="Completa las misiones para recibir tu recompensa. ¡Vuelve mañana para nuevas!")
    
    # ── CALCULAR TIEMPO HASTA LA PRÓXIMA MEDIANOCHE ──
    ahora = _dt.datetime.now()
    medianoche = ahora.replace(hour=0, minute=0, second=0, microsecond=0) + _dt.timedelta(days=1)
    restante = medianoche - ahora
    horas, resto = divmod(restante.seconds, 3600)
    minutos, segundos = divmod(resto, 60)
    tiempo_str = f"{horas}h {minutos}m {segundos}s"
    # Añadir el tiempo restante al footer existente
    embed.set_footer(text=f"{embed.footer.text} | ⏳ Próximas misiones en {tiempo_str}")
    
    await ctx.send(embed=embed)


def _tienda_item_by_user_key(key: str):
    """Devuelve (tipo, item_id, item_def) aceptando tanto id de tienda como tipo interno."""
    key = str(key or "").lower().strip()
    if key in TIENDA_ITEMS:
        item = TIENDA_ITEMS[key]
        return item.get("tipo", key), key, item
    for item_id, item in TIENDA_ITEMS.items():
        if str(item.get("tipo", item_id)).lower() == key:
            return item.get("tipo", item_id), item_id, item
    return None, None, None


def _tienda_decrementar_consumible(datos: dict, uid: str, tipo: str) -> bool:
    asegurar_usuario(datos, uid)
    inv = datos[uid].setdefault("items", {})
    info = inv.get(tipo)
    if not isinstance(info, dict):
        return False
    cantidad = int(info.get("cantidad", 1) or 1)
    if cantidad <= 1:
        inv.pop(tipo, None)
    else:
        info["cantidad"] = cantidad - 1
    return True


def _tienda_add_xp_simple(datos: dict, uid: str, xp: int) -> str:
    asegurar_usuario(datos, uid)
    datos[uid]["experiencia"] = datos[uid].get("experiencia", 0) + int(xp)
    subidas = 0
    while True:
        nivel = int(datos[uid].get("nivel", 1) or 1)
        necesario = 100 + (nivel - 1) * 50
        if datos[uid].get("experiencia", 0) < necesario:
            break
        datos[uid]["experiencia"] -= necesario
        datos[uid]["nivel"] = nivel + 1
        subidas += 1
        recompensa = 50 + datos[uid]["nivel"] * 10
        agregar_a_cash_y_monedas(datos, uid, recompensa)
    if subidas:
        return f"+{xp} XP · Subiste {subidas} nivel(es)."
    return f"+{xp} XP."


def _tienda_random_collectible(exclude_owned: dict = None):
    exclude_owned = exclude_owned or {}
    pool = [
        (item_id, item) for item_id, item in TIENDA_ITEMS.items()
        if item.get("categoria") in ("coleccion", "perfil", "decoracion", "cosmetico")
        and item.get("tipo") not in exclude_owned
        and not item.get("consumible")
    ]
    if not pool:
        return None, None
    return random.choice(pool)


