# @bot.command(name="inventario", aliases=["inv"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 5, commands.BucketType.user)
async def inventario_cmd(ctx, miembro: discord.Member = None):
    """Muestra los items activos del inventario. Uso: !inv [@usuario]"""
    import datetime as _dt
    miembro = miembro or ctx.author
    d = cargar_datos()
    uid = str(miembro.id)
    asegurar_usuario(d, uid)
    items_raw = d[uid].get("items", {})

    activos = []
    expirados = []
    ahora = _dt.datetime.now()

    for tipo, info in list(items_raw.items()):
        # Compatibilidad con items sin campo 'nombre'
        if not isinstance(info, dict):
            expirados.append(tipo)
            continue
        nombre = info.get("nombre") or info.get("item_id") or tipo.replace("_", " ").title()
        expira_str = info.get("expira")

        if info.get("consumible") or int(info.get("cantidad", 0) or 0) > 0:
            cantidad = int(info.get("cantidad", 1) or 1)
            activos.append((nombre, tipo, f"Consumible · x{cantidad} · usa `!usar {info.get('item_id', tipo)}`", "🎮"))
        elif expira_str:
            try:
                dt_exp = _dt.datetime.fromisoformat(expira_str)
                if dt_exp > ahora:
                    diff = dt_exp - ahora
                    dias = diff.days
                    horas = diff.seconds // 3600
                    if dias > 0:
                        tiempo_restante = f"{dias}d {horas}h"
                    else:
                        tiempo_restante = f"{horas}h"
                    activos.append((nombre, tipo, f"⏳ Expira en {tiempo_restante}", "🟢"))
                else:
                    expirados.append(tipo)
            except (ValueError, TypeError):
                expirados.append(tipo)
        else:
            # Sin fecha de expiración = permanente
            activos.append((nombre, tipo, f"Permanente · {info.get('rareza', 'normal')}", "🔒"))

    # Limpiar expirados
    for tipo in expirados:
        if tipo in d[uid]["items"]:
            del d[uid]["items"][tipo]
    if expirados:
        guardar_datos(d)

    embed = discord.Embed(
        title=f"🎒 Inventario de {miembro.display_name}",
        color=discord.Color.blue()
    )
    embed.set_thumbnail(url=miembro.display_avatar.url)

    equipado = d[uid].get("equipado", {}) if isinstance(d[uid].get("equipado", {}), dict) else {}
    if equipado:
        lineas_eq = []
        for slot, tipo_eq in equipado.items():
            info_eq = next((v for v in TIENDA_ITEMS.values() if v.get("tipo") == tipo_eq or v.get("item_id") == tipo_eq), None)
            if info_eq:
                lineas_eq.append(f"**{slot.title()}**: {info_eq.get('emoji', '✨')} {info_eq.get('nombre', tipo_eq)}")
            else:
                lineas_eq.append(f"**{slot.title()}**: `{tipo_eq}`")
        embed.add_field(name="🪪 Perfil equipado", value="\n".join(lineas_eq)[:1024], inline=False)

    if not activos:
        embed.description = (
            "📦 Sin items activos.\n\n"
            "Visita **!tienda** para comprar boosts, protecciones y cosméticos."
        )
    else:
        for nombre, tipo, estado, icono in activos:
            # Buscar info del item en TIENDA_ITEMS para descripción
            info_tienda = next(
                (v for v in TIENDA_ITEMS.values() if v.get("tipo") == tipo),
                None
            )
            emoji_item = info_tienda["emoji"] if info_tienda else icono
            desc_item = info_tienda["descripcion"] if info_tienda else tipo.replace("_", " ").title()
            embed.add_field(
                name=f"{emoji_item} {nombre}",
                value=f"{desc_item}\n`{estado}`",
                inline=True
            )

    if expirados:
        embed.set_footer(text=f"🗑️ {len(expirados)} item(s) expirado(s) eliminado(s) automáticamente.")
    else:
        embed.set_footer(text=f"Items activos: {len(activos)} | !tienda para comprar")

    await ctx.send(embed=embed)


