def _tienda_find_owned_item(datos: dict, uid: str, key: str):
    key = str(key or "").lower().strip()
    asegurar_usuario(datos, uid)
    inv = datos[uid].get("items", {})
    tipo, item_id, item_def = _tienda_item_by_user_key(key)
    if tipo and tipo in inv:
        return tipo, item_id, item_def, inv[tipo]
    if key in inv:
        item_def = next((v for v in TIENDA_ITEMS.values() if v.get("tipo") == key), None)
        return key, (item_def or {}).get("item_id", key), item_def, inv[key]
    return None, None, None, None


def _tienda_slot_for_item(item_def: dict, tipo: str) -> str:
    if not item_def:
        return ""
    if item_def.get("slot"):
        return str(item_def.get("slot")).lower()
    cat = str(item_def.get("categoria", "")).lower()
    if cat in ("titulo", "fondo", "mascota"):
        return cat
    if cat in ("decoracion", "cosmetico", "perfil"):
        # Mapear decoraciones antiguas a slots útiles
        if "aura" in tipo:
            return "aura"
        if "marco" in tipo:
            return "marco"
        if "color" in tipo:
            return "color"
        if "firma" in tipo:
            return "firma"
        if "placa" in tipo or "badge" in tipo:
            return "placa"
        return "decoracion"
    return ""


