@commands.cooldown(1, 3, commands.BucketType.user)
async def equipar_cmd(ctx, item_id: str = None):
    """Equipa un cosmético permanente. Uso: !equipar <item>"""
    if not item_id:
        await ctx.send("Uso: `!equipar <item>` · mira tus objetos con `!inv`.")
        return
    datos = cargar_datos()
    uid = str(ctx.author.id)
    tipo, real_id, item_def, owned = _tienda_find_owned_item(datos, uid, item_id)
    if not owned or not item_def:
        await ctx.send("❌ No tienes ese objeto en tu inventario.")
        return
    if owned.get("consumible") or int(owned.get("cantidad", 0) or 0) > 0:
        await ctx.send("🎮 Ese objeto es consumible. Úsalo con `!usar <item>`.")
        return
    slot = _tienda_slot_for_item(item_def, tipo)
    if not slot:
        await ctx.send("⚠️ Ese objeto no es equipable. Prueba con títulos, fondos, mascotas, placas, firmas, auras o marcos.")
        return
    datos[uid].setdefault("equipado", {})[slot] = tipo
    guardar_datos(datos)
    await ctx.send(f"✅ Equipado en slot **{slot}**: {item_def.get('emoji', '✨')} **{item_def.get('nombre', tipo)}**")


