@bot.command(name="vender", aliases=["sell"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def vender_cmd(ctx, item_id: str = None, cantidad: int = 1):
    """Vende consumibles o cosméticos permanentes. Uso: !vender <item> [cantidad]"""
    if not item_id:
        await ctx.send("Uso: `!vender <item> [cantidad]`")
        return
    cantidad = max(1, int(cantidad or 1))
    datos = cargar_datos()
    uid = str(ctx.author.id)
    tipo, real_id, item_def, owned = _tienda_find_owned_item(datos, uid, item_id)
    if not owned or not item_def:
        await ctx.send("❌ No tienes ese objeto.")
        return
    if item_def.get("categoria") == "boost" or owned.get("expira"):
        await ctx.send("⚠️ No puedes vender boosts o efectos temporales activos.")
        return
    inv = datos[uid].setdefault("items", {})
    precio = int(item_def.get("precio", 0) or 0)
    if owned.get("consumible") or int(owned.get("cantidad", 0) or 0) > 0:
        disponible = int(owned.get("cantidad", 1) or 1)
        cantidad = min(cantidad, disponible)
        reembolso = max(1, int(precio * 0.45)) * cantidad
        if disponible <= cantidad:
            inv.pop(tipo, None)
        else:
            owned["cantidad"] = disponible - cantidad
    else:
        reembolso = max(1, int(precio * 0.35))
        inv.pop(tipo, None)
        equipado = datos[uid].get("equipado", {})
        for slot, tipo_eq in list(equipado.items()):
            if tipo_eq == tipo:
                equipado.pop(slot, None)
    agregar_a_cash_y_monedas(datos, uid, reembolso)
    guardar_datos(datos)
    await ctx.send(f"💰 Vendido **{item_def.get('emoji', '📦')} {item_def.get('nombre', tipo)}** x{cantidad} por **{reembolso:,}** {amatista}.")


# @bot.command(name="coleccion", aliases=["collection", "cosmeticos"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 5, commands.BucketType.user)
async def coleccion_cmd(ctx, miembro: discord.Member = None):
    """Muestra resumen de colección y perfil equipado."""
    miembro = miembro or ctx.author
    datos = cargar_datos()
    uid = str(miembro.id)
    asegurar_usuario(datos, uid)
    inv = datos[uid].get("items", {})
    equipado = datos[uid].get("equipado", {}) if isinstance(datos[uid].get("equipado", {}), dict) else {}
    permanentes = []
    consumibles = 0
    for tipo, info in inv.items():
        if not isinstance(info, dict):
            continue
        if info.get("consumible") or int(info.get("cantidad", 0) or 0) > 0:
            consumibles += int(info.get("cantidad", 1) or 1)
        elif not info.get("expira"):
            permanentes.append((tipo, info))
    embed = discord.Embed(title=f"🏆 Colección de {miembro.display_name}", color=discord.Color.purple())
    embed.set_thumbnail(url=miembro.display_avatar.url)
    embed.description = f"Permanentes: **{len(permanentes)}** · Consumibles acumulados: **{consumibles}** · Slots equipados: **{len(equipado)}**"
    if equipado:
        lineas = []
        for slot, tipo_eq in equipado.items():
            item_def = next((v for v in TIENDA_ITEMS.values() if v.get("tipo") == tipo_eq), None)
            lineas.append(f"**{slot.title()}**: {(item_def or {}).get('emoji', '✨')} {(item_def or {}).get('nombre', tipo_eq)}")
        embed.add_field(name="🪪 Equipado", value="\n".join(lineas)[:1024], inline=False)
    if permanentes:
        muestra = []
        for tipo, info in permanentes[:20]:
            item_def = next((v for v in TIENDA_ITEMS.values() if v.get("tipo") == tipo), None)
            muestra.append(f"{(item_def or {}).get('emoji', '🔒')} {(item_def or {}).get('nombre', info.get('nombre', tipo))}")
        embed.add_field(name="🔒 Permanentes", value="\n".join(muestra)[:1024], inline=False)
    embed.set_footer(text="Usa !equipar <item> para lucir cosméticos")
    await ctx.send(embed=embed)


