# @bot.command(name="addstream")  # XAU310 deduplicado: comando antiguo desactivado
async def addstream_cmd(ctx, plataforma: str, *, usuario: str):
    """Registra tu stream. Uso: !addstream twitch nombreusuario"""
    plataformas_validas = ["twitch", "youtube", "tiktok", "kick"]
    plat = plataforma.lower()
    if plat not in plataformas_validas:
        await ctx.send(f"❌ Plataformas válidas: {', '.join(plataformas_validas)}"); return
    uid = ctx.author.id
    if uid not in _streams_db:
        _streams_db[uid] = []
    if len(_streams_db[uid]) >= 3:
        await ctx.send("❌ Máximo 3 streams registrados."); return
    _streams_db[uid].append({"plataforma": plat, "usuario": usuario})
    await ctx.send(f"✅ Stream registrado: **{plat}** — `{usuario}`")

# @bot.command(name="mystreams")  # XAU310 deduplicado: comando antiguo desactivado
async def mystreams_cmd(ctx):
    """Ver tus streams registrados."""
    uid = ctx.author.id
    streams = _streams_db.get(uid, [])
    if not streams:
        await ctx.send("No tienes streams registrados. Usa `!addstream`."); return
    embed = discord.Embed(title="📺 Tus Streams", color=discord.Color.red())
    for i, s in enumerate(streams, 1):
        embed.add_field(name=f"#{i} {s['plataforma'].title()}", value=s["usuario"], inline=True)
    await ctx.send(embed=embed)

# @bot.command(name="delstream")  # XAU310 deduplicado: comando antiguo desactivado
async def delstream_cmd(ctx, numero: int):
    """Elimina un stream. Uso: !delstream 1"""
    uid = ctx.author.id
    streams = _streams_db.get(uid, [])
    if not streams:
        await ctx.send("No tienes streams registrados."); return
    if numero < 1 or numero > len(streams):
        await ctx.send(f"❌ Número inválido. Tienes {len(streams)} stream(s)."); return
    eliminado = streams.pop(numero - 1)
    await ctx.send(f"✅ Stream eliminado: **{eliminado['plataforma']}** — `{eliminado['usuario']}`")

# @bot.command(name="streams")  # XAU310 deduplicado: comando antiguo desactivado
async def streams_cmd(ctx):
    """Lista todos los streams registrados en el servidor."""
    if not _streams_db:
        await ctx.send("No hay streams registrados en el servidor."); return
    embed = discord.Embed(title="📺 Streams del Servidor", color=discord.Color.red())
    count = 0
    for uid, streams in _streams_db.items():
        member = ctx.guild.get_member(uid)
        if member and streams:
            for s in streams:
                embed.add_field(name=f"{member.display_name} ({s['plataforma'].title()})", value=s["usuario"], inline=True)
                count += 1
    if count == 0:
        embed.description = "No hay streams registrados."
    await ctx.send(embed=embed)

