@bot.command()
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def encuesta(ctx, pregunta: str, *opciones, tiempo: int = 60):
    """Crea una encuesta con reacciones. Uso: !encuesta \"¿Pregunta?\" op1 op2 ..."""
    if len(opciones) < 2:
        await ctx.send("❌ Necesitas al menos 2 opciones. Uso: `!encuesta \"pregunta\" opcion1 opcion2`")
        return
    if len(opciones) > 9:
        await ctx.send("❌ Máximo 9 opciones.")
        return
    numeros = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣"]
    descripcion = ""
    for i, op in enumerate(opciones):
        descripcion += f"{numeros[i]} {op}\n"
    embed = discord.Embed(
        title=f"📊 {pregunta}",
        description=descripcion,
        color=discord.Color.blue(),
        timestamp=discord.utils.utcnow()
    )
    embed.set_footer(text=f"Encuesta creada por {ctx.author.display_name}")
    try:
        await ctx.message.delete()
    except:
        pass
    msg = await ctx.send(embed=embed)
    for i in range(len(opciones)):
        await msg.add_reaction(numeros[i])
    
    tiempo = tiempo * 60  # convertir a segundos
    await asyncio.sleep(tiempo)
        # Contar votos
    msg = await ctx.fetch_message(msg.id)  # Obtener mensaje actualizado con reacciones
    votos = {}
    for reaction in msg.reactions:
        if reaction.emoji in numeros:
            idx = numeros.index(reaction.emoji)
            votos[opciones[idx]] = reaction.count - 1  # restar 1 para no contar el bot
    votos_str = "voto" if sum(votos.values()) == 1 else "votos"
    # Mostrar resultados
    resultado_desc = ""
    for op in opciones:
        resultado_desc += f"**{op}** — {votos.get(op, 0)} {votos_str}\n"
    resultado_embed = discord.Embed(
        title=f"📊 Resultados de: {pregunta}"
        , description=resultado_desc,
        color=discord.Color.green(),
        timestamp=discord.utils.utcnow()
    )
    resultado_embed.set_footer(text=f"Encuesta creada por {ctx.author.display_name}")
    await ctx.send(embed=resultado_embed)

@bot.command()
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def recordatorio(ctx, tiempo: str, *, mensaje: str):
    """Crea un recordatorio por DM. Ej: !recordatorio 10m Estudiar | Formatos: s m h d"""
    unidades = {"s": 1, "m": 60, "h": 3600, "d": 86400}
    unidad = tiempo[-1].lower()
    if unidad not in unidades:
        await ctx.send("❌ Formato inválido. Usa: `10s`, `5m`, `2h`, `1d`.")
        return
    try:
        cantidad = int(tiempo[:-1])
    except:
        await ctx.send("❌ Número inválido. Ej: `!recordatorio 10m Estudiar`")
        return
    segundos = cantidad * unidades[unidad]
    if segundos > 604800:
        await ctx.send("❌ El recordatorio máximo es de 7 días.")
        return
    await ctx.send(f"⏰ ¡Listo! Te recordaré **{mensaje}** en **{tiempo}**.")
    await asyncio.sleep(segundos)
    try:
        await ctx.author.send(
            embed=discord.Embed(
                title="⏰ Recordatorio",
                description=f"**{mensaje}**",
                color=discord.Color.gold(),
                timestamp=discord.utils.utcnow()
            ).set_footer(text=f"Establecido en #{ctx.channel.name}")
        )
    except:
        await ctx.send(f"⏰ {ctx.author.mention} ¡Recordatorio! **{mensaje}**")

# @bot.command()  # XAU310 deduplicado: comando antiguo desactivado
async def meme(ctx):
    """Envía un meme aleatorio de Reddit."""
    subreddits = ["dankmemes", "memes", "me_irl", "AdviceAnimals", "funny"]
    sub = random.choice(subreddits)
    url = f"https://www.reddit.com/r/{sub}/random/.json"
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(url, headers={"User-Agent": "discord-bot"}, allow_redirects=True) as resp:
                if resp.status != 200:
                    await ctx.send("❌ No pude obtener un meme en este momento.")
                    return
                data = await resp.json()
                post = data[0]["data"]["children"][0]["data"]
                titulo = post.get("title", "Meme")
                img_url = post.get("url", "")
                permalink = "https://reddit.com" + post.get("permalink", "")
                if not img_url.endswith((".jpg", ".jpeg", ".png", ".gif")):
                    await ctx.send("❌ El post no tiene imagen válida. Inténtalo de nuevo.")
                    return
                embed = discord.Embed(title=titulo, url=permalink, color=discord.Color.orange())
                embed.set_image(url=img_url)
                embed.set_footer(text=f"r/{sub} • Reddit")
                await ctx.send(embed=embed)
    except Exception as e:
        await ctx.send(f"❌ Error al obtener meme: {e}")

@tree.command(name="ping", description="Muestra la latencia del bot.")
async def ping_slash(interaction: discord.Interaction):
    latencia = round(bot.latency * 1000)
    color = discord.Color.green() if latencia < 100 else discord.Color.yellow() if latencia < 200 else discord.Color.red()
    embed = discord.Embed(title="🏓 Pong!", description=f"Latencia: **{latencia} ms**", color=color)
    await interaction.response.send_message(embed=embed)

@tree.command(name="amor", description="Calcula el % de amor entre dos usuarios.")
async def amor_slash(interaction: discord.Interaction, usuario1: discord.Member, usuario2: discord.Member):
    seed = (usuario1.id + usuario2.id) % 101
    pct = seed
    barra = "❤️" * (pct // 10) + "🖤" * (10 - pct // 10)
