@bot.command(name="top")
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def top_cmd(ctx):
    """Top 5 general: cash, nivel y rep."""
    d = cargar_datos()
    miembros = [(uid, info) for uid, info in d.items() if ctx.guild.get_member(int(uid))]
    if not miembros:
        await ctx.send("Sin datos aún."); return

    top_cash = sorted(miembros, key=lambda x: x[1].get("cash", 0) + x[1].get("bank", 0), reverse=True)[:5]
    top_nivel = sorted(miembros, key=lambda x: (x[1].get("nivel", 1), x[1].get("experiencia", 0)), reverse=True)[:5]
    top_rep = sorted(miembros, key=lambda x: x[1].get("reputacion", 0), reverse=True)[:5]

    def formato_top(lista, key_fn, suffix=""):
        lines = []
        medallas = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣"]
        for i, (uid, info) in enumerate(lista):
            m = ctx.guild.get_member(int(uid))
            nombre = m.display_name if m else f"Usuario {uid[:4]}"
            lines.append(f"{medallas[i]} **{nombre}** — {key_fn(info)}{suffix}")
        return "\n".join(lines) or "Sin datos"

    embed = discord.Embed(title="🏆 Top del Servidor X AETHER ULTRA", color=discord.Color.gold())
    embed.add_field(
        name="💰 Top Amatista",
        value=formato_top(top_cash, lambda i: f"{i.get('cash',0)+i.get('bank',0):,}"),
        inline=False
    )
    embed.add_field(
        name="⭐ Top Nivel",
        value=formato_top(top_nivel, lambda i: f"Nv.{i.get('nivel',1)} (XP:{i.get('experiencia',0)})"),
        inline=False
    )
    embed.add_field(
        name="🌟 Top Reputación",
        value=formato_top(top_rep, lambda i: str(i.get("reputacion", 0)), " rep"),
        inline=False
    )
    await ctx.send(embed=embed)

@bot.command(name="buscar")
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def buscar_cmd(ctx, *, query: str):
    """Busca un miembro del servidor por nombre o apodo."""
    query_lower = query.lower()
    encontrados = [
        m for m in ctx.guild.members
        if query_lower in m.display_name.lower() or query_lower in m.name.lower()
    ]
    if not encontrados:
        await ctx.send(f"❌ No encontré ningún miembro con '{query}'."); return
    if len(encontrados) > 5:
        lista = "\n".join(f"• {m.mention} (`{m.name}`)" for m in encontrados[:5])
        await ctx.send(f"🔍 Encontré {len(encontrados)} coincidencias (mostrando 5):\n{lista}")
        return
    miembro = encontrados[0]
    d = cargar_datos()
    uid = str(miembro.id)
    asegurar_usuario(d, uid)
    embed = discord.Embed(
        title=f"🔍 {miembro.display_name}",
        color=miembro.color if miembro.color.value != 0 else discord.Color.purple()
    )
    embed.set_thumbnail(url=miembro.display_avatar.url)
    embed.add_field(name="Nivel", value=str(d[uid].get("nivel", 1)), inline=True)
    embed.add_field(name="Cash", value=str(d[uid].get("cash", 0)), inline=True)
    embed.add_field(name="Rep", value=str(d[uid].get("reputacion", 0)), inline=True)
    embed.add_field(name="Rango RL", value=d[uid].get("rango_rl", "Sin rango"), inline=True)
    await ctx.send(embed=embed)

