@bot.command(name="sorteo")
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def sorteo_cmd(ctx, tiempo: str, *, premio: str):
    """Crea un sorteo. Uso: !sorteo 30m Premio (formatos: 30s, 5m, 2h)"""
    unidades = {"s": 1, "m": 60, "h": 3600}
    unidad = tiempo[-1].lower()
    if unidad not in unidades:
        await ctx.send("❌ Formato de tiempo inválido. Usa: 30s, 5m, 2h"); return
    try:
        cantidad = int(tiempo[:-1])
    except:
        await ctx.send("❌ Número inválido."); return
    segundos = cantidad * unidades[unidad]
    if segundos > 86400:
        await ctx.send("❌ Máximo 24 horas por sorteo."); return

    embed = discord.Embed(
        title="🎉 ¡SORTEO!",
        description=f"**Premio:** {premio}\n\nReacciona con 🎉 para participar.",
        color=discord.Color.gold(),
        timestamp=discord.utils.utcnow() + datetime.timedelta(seconds=segundos)
    )
    embed.add_field(name="⏰ Finaliza en", value=tiempo, inline=True)
    embed.add_field(name="👑 Organizado por", value=ctx.author.mention, inline=True)
    embed.set_footer(text="Finaliza")
    msg = await ctx.send(embed=embed)
    await msg.add_reaction("🎉")
    await asyncio.sleep(segundos)

    # Recargar el mensaje para obtener reacciones actualizadas
    msg = await ctx.channel.fetch_message(msg.id)
    reaccion = discord.utils.get(msg.reactions, emoji="🎉")
    participantes = []
    if reaccion:
        async for user in reaccion.users():
            if not user.bot:
                participantes.append(user)

    if not participantes:
        await ctx.send(f"😔 El sorteo de **{premio}** terminó pero nadie participó.")
        return

    ganador = random.choice(participantes)
    embed_fin = discord.Embed(
        title="🎊 ¡Sorteo Finalizado!",
        description=f"**Premio:** {premio}\n\n🏆 **Ganador:** {ganador.mention} ¡Felicidades!",
        color=discord.Color.green()
    )
    embed_fin.add_field(name="Participantes", value=str(len(participantes)), inline=True)
    await ctx.send(embed=embed_fin)

@bot.command(name="silenciar")
@commands.has_permissions(manage_messages=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def silenciar_cmd(ctx, miembro: discord.Member, minutos: int = 5, *, razon: str = "Sin razón"):
    """Silencia a un miembro con timeout. Uso: !silenciar @u <minutos> [razon]"""
    if minutos < 1 or minutos > 40320:
        await ctx.send("❌ El tiempo debe estar entre 1 y 40320 minutos (28 días)."); return
    if miembro.top_role >= ctx.author.top_role and ctx.author.id != MI_ID:
        await ctx.send("❌ No puedes silenciar a alguien con igual o mayor rol."); return
    try:
        duracion = datetime.timedelta(minutes=minutos)
        await miembro.timeout(duracion, reason=razon)
        embed = discord.Embed(
            title="🔇 Miembro Silenciado",
            description=f"{miembro.mention} silenciado por **{minutos} minutos**.",
            color=discord.Color.orange()
        )
        embed.add_field(name="Razón", value=razon, inline=False)
        embed.set_footer(text=f"Por {ctx.author.display_name}")
        await ctx.send(embed=embed)
        canal_log = bot.get_channel(LOG_CHANNEL_ID)
        if canal_log:
            await canal_log.send(embed=embed)
    except discord.Forbidden:
        await ctx.send("❌ No tengo permisos para silenciar a ese usuario.")

