@bot.command(name="voz")
@commands.cooldown(1, 30, commands.BucketType.user)
async def voz_cmd(ctx):
    """Conecta a Aether al canal de voz para conversación por voz."""

    if not ctx.author.voice or not ctx.author.voice.channel:
        await ctx.send("❌ Debes estar en un canal de voz.")
        return

    channel = ctx.author.voice.channel

    if ctx.voice_client and ctx.voice_client.is_connected():
        await ctx.send("⚠️ Ya estoy en un canal de voz.")
        return

    try:
        global voice_conversation_active
        voice_conversation_active = True
        vc = await channel.connect(cls=voice_recv.VoiceRecvClient)
        sink = ConversationAudioSink(bot, vc, ctx.author.id)
        vc.listen(sink)
        await ctx.send(f"🎤 Me he unido a **{channel.name}**. ¡Habla conmigo! Usa `!colgar` para terminar.")
    except Exception as e:
        voice_conversation_active = False
        await ctx.send(f"❌ No pude conectarme al canal de voz: {e}")

@bot.command(name="colgar")
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def colgar_cmd(ctx):
    """Desconecta a Aether del canal de voz."""
    global voice_conversation_active
    voice_client = ctx.voice_client
    if voice_client and voice_client.is_connected():
        await voice_client.disconnect()
        voice_conversation_active = False
        await ctx.send("👋 He colgado. La conversación por voz ha terminado.")
    else:
        await ctx.send("❌ No estoy en un canal de voz.")

