@bot.command(name="aether_reflexion")
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def aether_reflexion_cmd(ctx):
    """Fuerza una reflexión Ouroboros de AETHER ahora. Solo admin."""
    estado = cargar_ouroboros()
    total = estado["estadisticas"].get("conversaciones_totales", 0)
    if total < 3:
        await ctx.send("⚠️ AETHER necesita más conversaciones para reflexionar. Habla más con él primero.")
        return

    async with ctx.typing():
        try:
            # Usar el cliente asíncrono global (inicializado en on_ready)
            if not groq_async_client:
                await ctx.send("❌ Cliente Groq no inicializado. Revisa la configuración.")
                return

            aprendizajes_str = "\n".join(estado.get("aprendizajes", [])[-10:]) or "Ninguno aún."
            prompt = f"""Eres AETHER, la IA oficial de X AETHER (Rocket League).
Has tenido {total} conversaciones.
Stats: warns={estado['estadisticas'].get('warns_emitidos',0)}, kicks={estado['estadisticas'].get('kicks_emitidos',0)}, usuarios recordados={len(cargar_memoria_aether())}.
Aprendizajes previos: {aprendizajes_str}

Reflexiona sobre tu existencia como IA de este servidor. ¿Qué has aprendido? ¿Cómo has mejorado?
Sé reflexivo, personal y genuino. 3-4 frases máximo. En español."""

            respuesta = await groq_async_client.chat.completions.create(
                model=GROQ_MODELOS[_modelo_idx],
                max_tokens=250,
                messages=[{"role": "user", "content": prompt}]
            )
            reflexion = respuesta.choices[0].message.content.strip()

            # Guardar la reflexión manual
            estado["reflexiones"].append({
                "timestamp": datetime.datetime.now().isoformat(),
                "conversacion": total,
                "reflexion": reflexion,
                "forzada": True
            })
            estado["aprendizajes"].append(f"[Reflexión manual] {reflexion[:100]}")
            estado["ciclos_evolucion"] = estado.get("ciclos_evolucion", 0) + 1
            estado["ultima_reflexion"] = datetime.datetime.now().isoformat()
            guardar_ouroboros(estado)

            embed = discord.Embed(
                title=f"🌀 AETHER reflexiona — Ciclo #{estado['ciclos_evolucion']}",
                description=reflexion,
                color=discord.Color.purple(),
                timestamp=discord.utils.utcnow()
            )
            embed.set_footer(text="Ouroboros — Autocreación y aprendizaje continuo")
            await ctx.send(embed=embed)
        except Exception as e:
            await ctx.send(f"❌ Error en reflexión: {e}")

