# @bot.command(name="memoria_juego", aliases=["juegomemoria"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 60, commands.BucketType.user)
async def memoria_juego(ctx):
    """Juego de memoria — encuentra todos los pares. !memoria_juego"""
    pares = ["🐶","🐱","🐭","🐹","🐰","🦊","🐻","🐼"]
    cartas_vals = pares * 2; random.shuffle(cartas_vals)
    reveladas = [False] * 16; seleccion = None

    def _render():
        linea = ""
        for i, v in enumerate(cartas_vals):
            linea += (v if reveladas[i] else "🃏") + " "
            if (i + 1) % 4 == 0: linea += "\n"
        return linea

    msg = await ctx.send(f"🃏 **Juego de Memoria**\n{_render()}\nEscribe el número de la carta (1-16):")

    def check(m):
        return m.author == ctx.author and m.channel == ctx.channel and m.content.isdigit()

    while not all(reveladas):
        try:
            resp = await bot.wait_for("message", check=check, timeout=30)
            pos = int(resp.content) - 1
            await resp.delete()
            if pos < 0 or pos >= 16 or reveladas[pos]:
                await ctx.send("Posición inválida.", delete_after=3); continue
            reveladas[pos] = True
            if seleccion is None:
                seleccion = pos
            else:
                if cartas_vals[seleccion] == cartas_vals[pos]:
                    seleccion = None
                else:
                    await msg.edit(content=f"🃏 **Juego de Memoria**\n{_render()}\n❌ No coinciden.")
                    await asyncio.sleep(1.5)
                    if seleccion is not None:
                        reveladas[seleccion] = False
                    reveladas[pos] = False
                    seleccion = None
            await msg.edit(content=f"🃏 **Juego de Memoria**\n{_render()}\nEscribe el número de la carta (1-16):")
        except asyncio.TimeoutError:
            await ctx.send("⏰ Tiempo agotado."); return

    d = cargar_datos(); uid = str(ctx.author.id)
    asegurar_usuario(d, uid); agregar_a_cash_y_monedas(d, uid, 200); guardar_datos(d)
    await msg.edit(content=f"🎉 **¡Completaste el juego!** Ganas **200{amatista}**.\n{_render()}")

# @bot.command()  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 60, commands.BucketType.user)
async def ahorcado(ctx):
    """Adivina la palabra antes de que te ahorquen. !ahorcado"""
    palabra = random.choice(AHORCADO_PALABRAS)
    oculta = ["_"] * len(palabra); intentos = 7; usadas = []

    def check(m):
        return m.author == ctx.author and m.channel == ctx.channel and len(m.content) == 1 and m.content.isalpha()

    while intentos > 0 and "_" in oculta:
        embed = discord.Embed(
            title="🪢 Ahorcado",
            description=f"{AHORCADO_DIBUJOS[7-intentos]}\n"
                        f"Palabra: **{' '.join(oculta)}**\n"
                        f"Letras usadas: {', '.join(usadas) or 'ninguna'}\n"
                        f"Intentos restantes: **{intentos}**",
            color=discord.Color.blue()
        )
        await ctx.send(embed=embed)
        try:
            resp = await bot.wait_for("message", check=check, timeout=30)
            letra = resp.content.upper(); await resp.delete()
        except asyncio.TimeoutError:
            await ctx.send("⏰ Tiempo agotado. Fin del juego."); return
        if letra in usadas:
            await ctx.send("Ya usaste esa letra.", delete_after=3); continue
        usadas.append(letra)
        if letra in palabra:
            for i, l in enumerate(palabra):
                if l == letra: oculta[i] = letra
            await ctx.send("✅ ¡Bien!", delete_after=2)
        else:
            intentos -= 1; await ctx.send("❌ Fallaste.", delete_after=2)

    if "_" not in oculta:
        d = cargar_datos(); uid = str(ctx.author.id)
        asegurar_usuario(d, uid); agregar_a_cash_y_monedas(d, uid, 300); guardar_datos(d)
        await ctx.send(f"🎉 ¡Ganaste! La palabra era **{palabra}**. +**300{amatista}**")
    else:
        await ctx.send(f"💀 Perdiste. La palabra era **{palabra}**.")

