@bot.command(name="logros", aliases=["logro", "achievements", "ach", "trofeos"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def logros_cmd(ctx, miembro: discord.Member = None):
    """Muestra los logros desbloqueados. !logros | !logros @usuario"""
    miembro = miembro or ctx.author
    uid = str(miembro.id)
    logros_data = await cargar_logros_data()
    obtenidos = logros_data.get(uid, [])
    total_disp = len(LOGROS_DISPONIBLES); total_obt = len(obtenidos)
    barras = 12
    filled = min(int((total_obt / max(total_disp, 1)) * barras), barras)
    barra_total = "█" * filled + "░" * (barras - filled)
    pct = total_obt / max(total_disp, 1)
    if pct >= 1.0:    color = discord.Color.from_rgb(255, 215, 0)
    elif pct >= 0.5:  color = discord.Color.purple()
    elif pct > 0:     color = discord.Color.blurple()
    else:             color = discord.Color.dark_gray()
    embed = discord.Embed(title=f"🏆 Logros — {miembro.display_name}", color=color)
    embed.description = (
        f"**Progreso:** `[{barra_total}]` {total_obt}/{total_disp} desbloqueados\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    )
    for lid, linfo in LOGROS_DISPONIBLES.items():
        desbloqueado = lid in obtenidos
        icono = "✅" if desbloqueado else "🔒"
        estado_txt = "**Desbloqueado**" if desbloqueado else "*Bloqueado*"
        reward_txt = (f"💰 +{linfo['recompensa']:,} {amatista} cobrado" if desbloqueado
                      else f"Recompensa: **{linfo['recompensa']:,}** {amatista}")
        embed.add_field(name=f"{icono} {linfo['nombre']}", value=f"*{linfo['desc']}*\n{estado_txt} · {reward_txt}", inline=False)
    embed.set_thumbnail(url=miembro.display_avatar.url)
    if total_obt == total_disp and total_disp > 0:
        embed.set_footer(text="🌟 ¡Perfección absoluta! Todos los logros desbloqueados.")
    elif total_obt == 0:
        embed.set_footer(text="¡Empieza a jugar y desbloquea tu primer logro!")
    else:
        embed.set_footer(text=f"Faltan {total_disp - total_obt} logro(s) por desbloquear. ¡Tú puedes!")
    await ctx.send(embed=embed)

