class ServerTemplateAdaptModal(Modal, title="🛠️ Adaptar plantilla con IA"):
    request = TextInput(
        label="Qué quieres cambiar",
        placeholder="Ej: hazla más profesional, menos canales, añade zona de programación y permisos más privados...",
        style=discord.TextStyle.long,
        max_length=2500,
        required=True,
    )

    def __init__(self, ctx, template_key: str):
        super().__init__(timeout=600)
        self.ctx = ctx
        self.template_key = template_key

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Solo quien abrió el panel puede usar esto.", ephemeral=True)
            return
        template = SERVER_TEMPLATE_MEMORY.get(self.template_key)
        if not template:
            await interaction.response.send_message("Esta vista caducó. Vuelve a generar/cargar la plantilla.", ephemeral=True)
            return
        await interaction.response.defer(thinking=True, ephemeral=True)
        try:
            raw_template = await server_template_call_ai("", base_template=template, edit_request=str(self.request.value))
            new_template = server_template_normalize(raw_template, source=f"{template.get('source', 'plantilla')}_adaptada")
            key = _server_template_now_id("preview")
            SERVER_TEMPLATE_MEMORY[key] = new_template
            embed = server_template_preview_embed(new_template, interaction.user)
            await interaction.followup.send(embed=embed, view=ServerTemplatePreviewView(self.ctx, key), ephemeral=True)
        except Exception as e:
            await interaction.followup.send(f"❌ No pude adaptar la plantilla: `{str(e)[:1500]}`", ephemeral=True)


class ServerTemplateFinalConfirmModal(Modal, title="⚠️ Confirmación final"):
    confirm = TextInput(
        label="Escribe CONFIRMAR para aplicar",
        placeholder="CONFIRMAR",
        max_length=20,
        required=True,
    )

    def __init__(self, ctx, template_key: str):
        super().__init__(timeout=300)
        self.ctx = ctx
        self.template_key = template_key

