class ServerTemplateRollbackConfirmModal(Modal, title="↩️ Confirmar rollback"):
    confirm = TextInput(
        label="RESTAURAR = archivar · RESTAURAR COMPLETO = borrar",
        placeholder="RESTAURAR",
        max_length=30,
        required=True,
    )

    def __init__(self, ctx, deployment_id: str, mode: str):
        super().__init__(timeout=300)
        self.ctx = ctx
        self.deployment_id = deployment_id
        self.mode = mode

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Solo quien abrió el panel puede restaurar.", ephemeral=True)
            return
        expected = "RESTAURAR COMPLETO" if self.mode == "full" else "RESTAURAR"
        if str(self.confirm.value).strip().upper() != expected:
            await interaction.response.send_message(f"Cancelado. Debías escribir `{expected}`.", ephemeral=True)
            return
        await interaction.response.defer(thinking=True, ephemeral=True)
        try:
            result = await server_template_rollback(self.ctx, self.deployment_id, self.mode)
            embed = discord.Embed(title="↩️ Rollback ejecutado", color=discord.Color.orange())
            embed.description = f"Deployment: `{self.deployment_id}`\nModo: `{self.mode}`"
            embed.add_field(name="Canales archivados", value=str(len(result.get("archived_channels", []))), inline=True)
            embed.add_field(name="Categorías archivadas", value=str(len(result.get("archived_categories", []))), inline=True)
            embed.add_field(name="Canales eliminados", value=str(len(result.get("deleted_channels", []))), inline=True)
            embed.add_field(name="Categorías eliminadas", value=str(len(result.get("deleted_categories", []))), inline=True)
            embed.add_field(name="Roles eliminados", value=str(len(result.get("deleted_roles", []))), inline=True)
            if result.get("skipped"):
                embed.add_field(name="Avisos", value="\n".join(f"• {x}" for x in result.get("skipped", [])[:8])[:1024], inline=False)
            await interaction.followup.send(embed=embed, ephemeral=True)
        except Exception as e:
            await interaction.followup.send(f"❌ Error restaurando: `{str(e)[:1800]}`", ephemeral=True)


