class ServerTemplateSavedSelect(discord.ui.Select):
    def __init__(self, ctx, files):
        self.ctx = ctx
        options = []
        for path in files[:25]:
            options.append(discord.SelectOption(label=os.path.basename(path)[:100], value=path, description="Cargar plantilla guardada"))
        super().__init__(placeholder="Elige una plantilla JSON guardada", options=options, min_values=1, max_values=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Solo quien abrió el panel puede usar esto.", ephemeral=True)
            return
        await interaction.response.defer(thinking=True, ephemeral=True)
        try:
            with open(self.values[0], "r", encoding="utf-8") as f:
                raw_template = json.load(f)
            template = server_template_normalize(raw_template, source="json_guardado")
            key = _server_template_now_id("preview")
            SERVER_TEMPLATE_MEMORY[key] = template
            await interaction.followup.send(embed=server_template_preview_embed(template, interaction.user), view=ServerTemplatePreviewView(self.ctx, key), ephemeral=True)
        except Exception as e:
            await interaction.followup.send(f"❌ No pude cargar esa plantilla: `{str(e)[:1500]}`", ephemeral=True)


