@bot.command(name="plantilla_json")
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def plantilla_json_cmd(ctx, *, raw_json: str = None):
    """Carga una plantilla JSON desde texto o archivo adjunto."""
    if ctx.guild is None:
        await ctx.send("❌ Este comando solo funciona dentro de un servidor.")
        return
    try:
        if ctx.message.attachments:
            attachment = ctx.message.attachments[0]
            if not attachment.filename.lower().endswith(".json"):
                await ctx.send("❌ Adjunta un archivo `.json`.")
                return
            content = (await attachment.read()).decode("utf-8", errors="replace")
        elif raw_json:
            content = raw_json
        else:
            await ctx.send("Uso: `!plantilla_json {json}` o adjunta un `.json` junto al comando.")
            return
        raw_template = _server_template_parse_json(content)
        template = server_template_normalize(raw_template, source="json_comando")
        key = _server_template_now_id("preview")
        SERVER_TEMPLATE_MEMORY[key] = template
        await ctx.send(embed=server_template_preview_embed(template, ctx.author), view=ServerTemplatePreviewView(ctx, key))
    except Exception as e:
        await ctx.send(f"❌ No pude leer esa plantilla: `{str(e)[:1800]}`")


