# X AETHER ULTRA UX + MINIJUEGOS V6
# ══════════════════════════════════════════════════════════════════════════════

XAU_PUBLIC_PURPLE = 0x8B5CF6
XAU_PUBLIC_DARK = 0x111827
XAU_PUBLIC_GOLD = 0xFACC15
XAU_PUBLIC_GREEN = 0x22C55E
XAU_PUBLIC_RED = 0xEF4444


def _amethyst(n: int) -> str:
    try:
        return f"{int(n):,} {amatista}".replace(",", ".")
    except Exception:
        return f"{n} {amatista}"


def _am_embed(title: str, description: str = "", color: int = XAU_PUBLIC_PURPLE, ctx=None) -> discord.Embed:
    embed = discord.Embed(title=title, description=description, color=color)
    if ctx is not None:
        try:
            embed.set_footer(text=f"X AETHER • pedido por {ctx.author.display_name}", icon_url=ctx.author.display_avatar.url)
        except Exception:
            embed.set_footer(text="X AETHER ULTRA")
    else:
        embed.set_footer(text="X AETHER ULTRA")
    return embed


def _soft_bar(pct: float, size: int = 18) -> str:
    pct = max(0.0, min(1.0, float(pct)))
    filled = int(round(size * pct))
    return "▰" * filled + "▱" * (size - filled)


def _parse_bet_amount(datos: dict, uid: str, cantidad: str, *, min_bet: int = 1, max_bet: int = None):
    asegurar_usuario(datos, uid)
    cash = int(datos[uid].get("cash", 0) or 0)
    raw = str(cantidad).strip().lower()
    if raw in ("all", "todo", "max"):
        apuesta = cash
    elif raw in ("half", "mitad"):
        apuesta = cash // 2
    else:
        raw = raw.replace(".", "").replace(",", "")
        if not raw.isdigit():
            return None, "Cantidad inválida. Usa un número, `all` o `mitad`."
        apuesta = int(raw)
    if apuesta < min_bet:
        return None, f"La apuesta mínima es **{min_bet}**."
    if max_bet is not None and apuesta > max_bet:
        return None, f"La apuesta máxima para este juego es **{max_bet}**."
    if apuesta > cash:
        return None, f"No tienes suficiente cash. Tienes **{_amethyst(cash)}**."
    return apuesta, None


def _game_stats_bucket(datos: dict, uid: str, game_key: str) -> dict:
    asegurar_usuario(datos, uid)
    stats = datos[uid].setdefault("game_stats", {})
    return stats.setdefault(game_key, {
        "jugadas": 0,
        "ganadas": 0,
        "perdidas": 0,
        "neto": 0,
        "racha": 0,
        "mejor_racha": 0,
    })


def _record_game(datos: dict, uid: str, game_key: str, won: bool, net: int):
    bucket = _game_stats_bucket(datos, uid, game_key)
    bucket["jugadas"] = int(bucket.get("jugadas", 0) or 0) + 1
    bucket["neto"] = int(bucket.get("neto", 0) or 0) + int(net)
    if won:
        bucket["ganadas"] = int(bucket.get("ganadas", 0) or 0) + 1
        bucket["racha"] = int(bucket.get("racha", 0) or 0) + 1
        bucket["mejor_racha"] = max(int(bucket.get("mejor_racha", 0) or 0), int(bucket.get("racha", 0) or 0))
    else:
        bucket["perdidas"] = int(bucket.get("perdidas", 0) or 0) + 1
        bucket["racha"] = 0


def _game_footer_text(datos: dict, uid: str, game_key: str) -> str:
    st = _game_stats_bucket(datos, uid, game_key)
    return f"Jugadas: {st.get('jugadas',0)} • Ganadas: {st.get('ganadas',0)} • Racha: {st.get('racha',0)} • Neto: {st.get('neto',0):,}".replace(",", ".")


