class MiniGameSelect(discord.ui.Select):
    def __init__(self, ctx):
        self.ctx = ctx
        options = [
            discord.SelectOption(label="Casino Amatista", value="casino", emoji="🎰", description="Apuestas y juegos de riesgo"),
            discord.SelectOption(label="Habilidad y reflejos", value="skill", emoji="🎯", description="Juegos rápidos y de precisión"),
            discord.SelectOption(label="Party games", value="party", emoji="🎉", description="Juegos sociales para el canal"),
        ]
        super().__init__(placeholder="Elige una zona de minijuegos", options=options, min_values=1, max_values=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Abre tu propio `!minijuegos` para navegar.", ephemeral=True)
            return
        await interaction.response.edit_message(embed=_minigame_category_embed(self.values[0], self.ctx), view=MiniGamesView(self.ctx))


