def _minigame_stats_embed(member: discord.Member, ctx=None):
    datos = cargar_datos()
    uid = str(member.id)
    asegurar_usuario(datos, uid)
    stats = datos[uid].get("game_stats", {}) if isinstance(datos[uid].get("game_stats", {}), dict) else {}
    embed = _am_embed(f"📊 Estadísticas de juegos — {member.display_name}", "Tu historial del casino y minijuegos.", XAU_PUBLIC_GOLD, ctx)
    if not stats:
        embed.description = "Todavía no tienes estadísticas. Entra al Game Hub con `!minijuegos` y empieza la leyenda."
        return embed
    rows = []
    for game, st in sorted(stats.items(), key=lambda kv: int(kv[1].get("jugadas", 0) or 0), reverse=True)[:10]:
        jugadas = int(st.get("jugadas", 0) or 0)
        ganadas = int(st.get("ganadas", 0) or 0)
        winrate = int((ganadas / jugadas) * 100) if jugadas else 0
        rows.append(f"**{game.title()}** · {jugadas} partidas · {winrate}% win · Neto `{int(st.get('neto',0) or 0):,}` · Racha `{st.get('racha',0)}`".replace(",", "."))
    embed.add_field(name="🎮 Resumen", value="\n".join(rows)[:1024], inline=False)
    return embed


