async def _play_apostar(ctx, cantidad: str, eleccion: str):
    datos = cargar_datos()
    uid = str(ctx.author.id)
    apuesta, error = _parse_bet_amount(datos, uid, cantidad, min_bet=10)
    if error:
        await ctx.send(embed=_am_embed("🪙 Cara o cruz", f"❌ {error}", XAU_PUBLIC_RED, ctx)); return
    eleccion = str(eleccion).lower().strip()
    if eleccion not in ("cara", "cruz"):
        await ctx.send(embed=_am_embed("🪙 Cara o cruz", "Elige `cara` o `cruz`.", XAU_PUBLIC_RED, ctx)); return
    resultado = random.choice(["cara", "cruz"])
    restar_de_cash(datos, uid, apuesta)
    won = eleccion == resultado
    if won:
        mult = obtener_multiplicador(datos, uid, "apostar")
        premio = int(apuesta * 1.92 * mult)
        agregar_a_cash_y_monedas(datos, uid, premio)
        net = premio - apuesta
        color = XAU_PUBLIC_GREEN
        title = "🪙 Cara o cruz — Victoria"
        desc = f"La moneda cayó en **{resultado}**.\nGanaste **+{_amethyst(net)} neto**."
    else:
        net = -apuesta
        color = XAU_PUBLIC_RED
        title = "🪙 Cara o cruz — Derrota"
        desc = f"La moneda cayó en **{resultado}**.\nPerdiste **{_amethyst(apuesta)}**."
    _record_game(datos, uid, "apostar", won, net)
    guardar_datos(datos)
    embed = _am_embed(title, desc, color, ctx)
    embed.add_field(name="Tu elección", value=eleccion.title(), inline=True)
    embed.add_field(name="Resultado", value=resultado.title(), inline=True)
    embed.add_field(name="Balance", value=f"Cash actual: **{_amethyst(datos[uid].get('cash',0))}**", inline=False)
    embed.set_footer(text=_game_footer_text(datos, uid, "apostar"))
    await ctx.send(embed=embed, view=MiniReplayView(ctx, "Repetir moneda", _play_apostar, cantidad, eleccion))


