async def _play_ppt(ctx, cantidad: str, choice: str):
    datos = cargar_datos()
    uid = str(ctx.author.id)
    apuesta, error = _parse_bet_amount(datos, uid, cantidad, min_bet=10)
    if error:
        await ctx.send(embed=_am_embed("✂️ Piedra Papel Tijera", f"❌ {error}", XAU_PUBLIC_RED, ctx)); return
    choice = str(choice).lower().strip()
    aliases = {"p": "piedra", "papel": "papel", "t": "tijera", "tijeras": "tijera", "r": "piedra", "rock": "piedra"}
    choice = aliases.get(choice, choice)
    choices = ["piedra", "papel", "tijera"]
    if choice not in choices:
        await ctx.send(embed=_am_embed("✂️ Piedra Papel Tijera", "Elige `piedra`, `papel` o `tijera`.", XAU_PUBLIC_RED, ctx)); return
    bot_choice = random.choice(choices)
    emoji = {"piedra": "🪨", "papel": "📄", "tijera": "✂️"}
    draw = choice == bot_choice
    won = (choice == "piedra" and bot_choice == "tijera") or (choice == "papel" and bot_choice == "piedra") or (choice == "tijera" and bot_choice == "papel")
    if draw:
        color = XAU_PUBLIC_GOLD
        title = "✂️ PPT — Empate"
        desc = "Empate limpio. Se mantiene tu cash."
        net = 0
    else:
        restar_de_cash(datos, uid, apuesta)
        if won:
            mult = obtener_multiplicador(datos, uid, "ppt")
            premio = int(apuesta * 1.85 * mult)
            agregar_a_cash_y_monedas(datos, uid, premio)
            net = premio - apuesta
            color = XAU_PUBLIC_GREEN
            title = "✂️ PPT — Victoria"
            desc = f"Ganaste **+{_amethyst(net)} neto**."
        else:
            net = -apuesta
            color = XAU_PUBLIC_RED
            title = "✂️ PPT — Derrota"
            desc = f"Perdiste **{_amethyst(apuesta)}**."
        _record_game(datos, uid, "ppt", won, net)
    guardar_datos(datos)
    embed = _am_embed(title, desc, color, ctx)
    embed.add_field(name="Tú", value=f"{emoji[choice]} {choice.title()}", inline=True)
    embed.add_field(name="AETHER", value=f"{emoji[bot_choice]} {bot_choice.title()}", inline=True)
    embed.add_field(name="Progreso", value=_soft_bar(1.0 if won else 0.0 if not draw else 0.5, 16), inline=False)
    embed.set_footer(text=_game_footer_text(datos, uid, "ppt"))
    await ctx.send(embed=embed, view=MiniReplayView(ctx, "Revancha PPT", _play_ppt, cantidad, choice))


