async def _play_slots(ctx, cantidad: str):
    datos = cargar_datos()
    uid = str(ctx.author.id)
    apuesta, error = _parse_bet_amount(datos, uid, cantidad, min_bet=10)
    if error:
        await ctx.send(embed=_am_embed("🎰 Slots Neón", f"❌ {error}", XAU_PUBLIC_RED, ctx)); return
    restar_de_cash(datos, uid, apuesta)
    symbols = ["🍒", "🍋", "🍊", "🍇", "🔔", "⭐", "💎", "👑"]
    weights = [28, 24, 19, 13, 8, 5, 2, 1]
    msg = await ctx.send(embed=_am_embed("🎰 Slots Neón", f"Apuesta: **{_amethyst(apuesta)}**\n\n`◇ ◇ ◇`\n\nGirando carretes...", XAU_PUBLIC_GOLD, ctx))
    reels = ["◇", "◇", "◇"]
    for i in range(6):
        reels = random.choices(symbols, weights=weights, k=3)
        em = _am_embed("🎰 Slots Neón", f"Apuesta: **{_amethyst(apuesta)}**\n\n# {' | '.join(reels)}\n\n{_soft_bar((i+1)/6, 14)}", XAU_PUBLIC_GOLD, ctx)
        await msg.edit(embed=em)
        await asyncio.sleep(0.25)
    reels = random.choices(symbols, weights=weights, k=3)
    counts = {s: reels.count(s) for s in set(reels)}
    mults = {"🍒": 4, "🍋": 5, "🍊": 6, "🍇": 8, "🔔": 10, "⭐": 14, "💎": 22, "👑": 35}
    premio = 0
    if len(counts) == 1:
        premio = apuesta * mults.get(reels[0], 4)
    elif max(counts.values()) == 2:
        pair = max(counts, key=counts.get)
        premio = apuesta * (2 if pair not in ("💎", "👑") else 4)
    elif reels == ["🍒", "⭐", "💎"] or reels == ["💎", "⭐", "🍒"]:
        premio = apuesta * 7
    if premio:
        mult = obtener_multiplicador(datos, uid, "tragaperras")
        premio = int(premio * mult)
        agregar_a_cash_y_monedas(datos, uid, premio)
        won = True
        net = premio - apuesta
        color = XAU_PUBLIC_GREEN
        title = "🎰 Slots — Premio"
        desc = f"# {' | '.join(reels)}\nGanaste **+{_amethyst(net)} neto**."
    else:
        won = False
        net = -apuesta
        color = XAU_PUBLIC_RED
        title = "🎰 Slots — Sin premio"
        desc = f"# {' | '.join(reels)}\nPerdiste **{_amethyst(apuesta)}**."
    _record_game(datos, uid, "slots", won, net)
    guardar_datos(datos)
    embed = _am_embed(title, desc, color, ctx)
    embed.add_field(name="Tabla rápida", value="Pareja x2 · Triple 💎 x22 · Triple 👑 x35", inline=False)
    embed.set_footer(text=_game_footer_text(datos, uid, "slots"))
    await msg.edit(embed=embed, view=MiniReplayView(ctx, "Girar otra vez", _play_slots, cantidad))


