# @bot.command(name="adivina")  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 20, commands.BucketType.user)
async def adivina_cmd_v6(ctx):
    """Adivina el número, ahora con premios por precisión."""
    datos = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(datos, uid)
    secreto = random.randint(1, 100)
    max_intentos = 7
    embed = _am_embed("🔮 Adivina el número", "Pienso en un número entre **1 y 100**. Tienes **7 intentos**.\nCuanto antes aciertes, más amatistas ganas.", XAU_PUBLIC_PURPLE, ctx)
    embed.add_field(name="Premio", value="1 intento: 700 · 3 intentos: 450 · 7 intentos: 150", inline=False)
    await ctx.send(embed=embed)

    def check(msg):
        return msg.author.id == ctx.author.id and msg.channel.id == ctx.channel.id and msg.content.strip().isdigit()

    for intento in range(1, max_intentos + 1):
        try:
            msg = await bot.wait_for("message", check=check, timeout=18.0)
        except asyncio.TimeoutError:
            em = _am_embed("🔮 Adivina el número", f"Tiempo agotado. El número era **{secreto}**.", XAU_PUBLIC_RED, ctx)
            _record_game(datos, uid, "adivina", False, 0)
            guardar_datos(datos)
            await ctx.send(embed=em)
            return
        guess = int(msg.content.strip())
        if guess == secreto:
            premio = max(150, 800 - intento * 90)
            agregar_a_cash_y_monedas(datos, uid, premio)
            _record_game(datos, uid, "adivina", True, premio)
            guardar_datos(datos)
            em = _am_embed("🔮 ¡Correcto!", f"Número secreto: **{secreto}**\nLo lograste en **{intento}/{max_intentos}** intentos.\nPremio: **+{_amethyst(premio)}**", XAU_PUBLIC_GREEN, ctx)
            em.add_field(name="Precisión", value=_soft_bar((max_intentos - intento + 1) / max_intentos, 18), inline=False)
            em.set_footer(text=_game_footer_text(datos, uid, "adivina"))
            await ctx.send(embed=em)
            return
        pista = "más alto" if guess < secreto else "más bajo"
        distancia = abs(guess - secreto)
        calor = "🔥 muy cerca" if distancia <= 5 else "🌡️ cerca" if distancia <= 15 else "❄️ lejos"
        await ctx.send(f"{calor} · prueba **{pista}**. Intento `{intento}/{max_intentos}`")

    _record_game(datos, uid, "adivina", False, 0)
    guardar_datos(datos)
    await ctx.send(embed=_am_embed("🔮 Fin", f"No hubo suerte. El número era **{secreto}**.", XAU_PUBLIC_RED, ctx))


class UltraHelpSelect(discord.ui.Select):
    def __init__(self, ctx):
        self.ctx = ctx
        opts = []
        emojis = {
            "basicos": "🟢", "moderacion": "🛡️", "economia": "💰", "minijuegos": "🎮", "tickets": "🎫",
            "streams": "🔴", "ouroboros": "🌀", "utilidades": "🧰", "otros": "✨", "funciones": "⚙️", "aether": "🤖"
        }
        for cat in COMMAND_CATEGORIES.keys():
            opts.append(discord.SelectOption(label=cat.title(), value=cat, emoji=emojis.get(cat, "📌"), description=f"Ver comandos de {cat}"))
        super().__init__(placeholder="Elige una categoría de ayuda", options=opts[:25], min_values=1, max_values=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Abre tu propio menú con `!ayuda`.", ephemeral=True)
            return
        await interaction.response.edit_message(embed=_ultra_help_category_embed(self.ctx, self.values[0]), view=UltraHelpView(self.ctx))


