def _ultra_help_home_embed(ctx):
    total = len(list(bot.commands)) + len(tree.get_commands())
    embed = _am_embed("📚 Centro de ayuda X AETHER ULTRA", "Todo el bot ordenado por categorías, con navegación limpia y sin comandos perdidos.", XAU_PUBLIC_PURPLE, ctx)
    embed.add_field(name="Comandos detectados", value=f"**{total}** comandos entre prefijo y slash", inline=True)
    embed.add_field(name="Prefijo", value="`!`", inline=True)
    embed.add_field(name="Atajos", value="`!minijuegos` · `!tienda` · `!xpcard` · `!plantilla`", inline=False)
    embed.add_field(name="Categorías", value="\n".join(f"`{cat}`" for cat in COMMAND_CATEGORIES.keys())[:1024], inline=False)
    return embed


def _ultra_help_category_embed(ctx, cat: str):
    data = COMMAND_CATEGORIES.get(cat, {})
    embed = _am_embed(f"📜 Ayuda — {cat.title()}", "Comandos disponibles en esta zona.", XAU_PUBLIC_PURPLE, ctx)
    if not data:
        embed.description = "No hay comandos registrados aquí."
        return embed
    lines = []
    for cmd, desc in data.items():
        lines.append(f"**{cmd}**\n{desc}")
    chunks = []
    cur = ""
    for line in lines:
        if len(cur) + len(line) + 2 > 950:
            chunks.append(cur)
            cur = line
        else:
            cur += ("\n\n" if cur else "") + line
    if cur:
        chunks.append(cur)
    for i, chunk in enumerate(chunks[:5], start=1):
        embed.add_field(name=f"Página {i}", value=chunk, inline=False)
    return embed


