@bot.event
async def on_command_error(ctx, error):
    if isinstance(error, commands.CommandNotFound):
        return
    if isinstance(error, commands.CommandOnCooldown):
        await ctx.send(embed=_am_embed("⏳ Cooldown", f"Espera **{formato_tiempo(error.retry_after)}** antes de volver a usar ese comando.", XAU_PUBLIC_GOLD, ctx), delete_after=10)
        return
    if isinstance(error, commands.MissingPermissions):
        await ctx.send(embed=_am_embed("🛡️ Permisos insuficientes", "No tienes permisos para usar ese comando.", XAU_PUBLIC_RED, ctx), delete_after=12)
        return
    if isinstance(error, commands.MissingRequiredArgument):
        await ctx.send(embed=_am_embed("🧩 Faltan datos", f"Falta el argumento `{error.param.name}`. Usa `!ayuda` para ver ejemplos.", XAU_PUBLIC_RED, ctx), delete_after=14)
        return
    if isinstance(error, commands.BadArgument):
        await ctx.send(embed=_am_embed("🧩 Argumento inválido", "Algún dato no tiene el formato correcto. Revisa `!ayuda`.", XAU_PUBLIC_RED, ctx), delete_after=14)
        return
    try:
        logger.exception("Error en comando %s", getattr(ctx.command, "qualified_name", "desconocido"), exc_info=error)
    except Exception:
        pass
    await ctx.send(embed=_am_embed("💥 Error controlado", f"El comando falló, pero el bot sigue vivo.\n`{str(error)[:800]}`", XAU_PUBLIC_RED, ctx))


