V7_VERSION = "X AETHER ULTRA 3.1.0 · Core Premium"
V7_ACCENT = discord.Color.purple()
V7_OK = discord.Color.green()
V7_WARN = discord.Color.gold()
V7_BAD = discord.Color.red()


def _v7_path(filename: str) -> str:
    """Devuelve una ruta segura dentro del directorio base del bot."""
    return os.path.join(BASE_DIR, filename)


def _v7_now_iso() -> str:
    """Marca temporal humana para logs internos."""
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def _v7_load_json_file(filename: str, default=None):
    """Carga JSON sin romper el bot si el archivo está vacío o corrupto."""
    if default is None:
        default = {}
    path = _v7_path(filename)
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception as e:
        try:
            logger.warning("[3.1.0] No se pudo cargar %s: %s", filename, e)
        except Exception:
            pass
    return default


def _v7_save_json_file(filename: str, data) -> bool:
    """Guarda JSON con indentación bonita y devuelve si salió bien."""
    path = _v7_path(filename)
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        try:
            logger.exception("[3.1.0] No se pudo guardar %s", filename, exc_info=e)
        except Exception:
            pass
        return False


def _v7_trim(texto: str, limit: int = 1024) -> str:
    """Recorta texto para embeds de Discord sin que explote el dragón de 1024 caracteres."""
    texto = str(texto or "")
    if len(texto) <= limit:
        return texto
    return texto[: max(0, limit - 3)] + "..."


def _v7_is_staff(ctx) -> bool:
    """Permiso cómodo: Markelson, admin o gestionar servidor."""
    if getattr(ctx.author, "id", None) == MI_ID:
        return True
    perms = getattr(ctx.author, "guild_permissions", None)
    return bool(perms and (perms.administrator or perms.manage_guild))


def _v7_embed(title: str, description: str = "", color=None, ctx=None, footer: str = None) -> discord.Embed:
    """Embed estándar con estética amatista."""
    embed = discord.Embed(
        title=title,
        description=description,
        color=color or V7_ACCENT,
        timestamp=datetime.datetime.now()
    )
    try:
        embed.set_author(name="X AETHER ULTRA · Núcleo Amatista", icon_url=getattr(bot.user.display_avatar, "url", None) if bot.user else None)
    except Exception:
        pass
    if description:
        try:
            embed.description = f"{description}\n\n`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`"
        except Exception:
            pass
    if ctx is not None:
        try:
            embed.set_footer(
                text=footer or f"X AETHER · solicitado por {ctx.author.display_name}",
                icon_url=ctx.author.display_avatar.url
            )
        except Exception:
            embed.set_footer(text=footer or "X AETHER ULTRA")
    else:
        embed.set_footer(text=footer or "X AETHER ULTRA")
    return embed


def _v7_command_signature(command: commands.Command) -> str:
    """Convierte un comando real en una línea legible."""
    aliases = f" · alias: {', '.join(command.aliases[:3])}" if getattr(command, "aliases", None) else ""
    return f"!{command.qualified_name}{aliases}"


def _v7_all_help_entries() -> dict:
    """Devuelve todos los comandos documentados en COMMAND_CATEGORIES."""
    entries = {}
    for category, items in COMMAND_CATEGORIES.items():
        if not isinstance(items, dict):
            continue
        for raw_name, desc in items.items():
            raw_name = str(raw_name)
            m = re.match(r"([!/][^\s(]+)", raw_name.strip())
            key = m.group(1).lower() if m else raw_name.lower()
            entries[key] = {"category": category, "raw": raw_name, "desc": str(desc)}
    return entries


