# @bot.command(name="comandos")  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 5, commands.BucketType.user)
async def comandos_cmd(ctx, *, busqueda: str = None):
    """Busca comandos por nombre o descripción."""
    entries = _v7_all_help_entries()
    if not busqueda:
        cats = []
        for cat, items in COMMAND_CATEGORIES.items():
            if isinstance(items, dict):
                cats.append(f"**{cat.title()}** · {len(items)} entradas")
        embed = _v7_embed(
            "🔎 Buscador de comandos",
            "Usa `!comandos <texto>` para buscar.\nEjemplo: `!comandos tienda`, `!comandos nivel`, `!comandos ruleta`.",
            V7_ACCENT,
            ctx
        )
        embed.add_field(name="Categorías", value=_v7_trim("\n".join(cats), 1000), inline=False)
        await ctx.send(embed=embed)
        return

    q = busqueda.lower().strip()
    matches = []
    for item in entries.values():
        haystack = f"{item['raw']} {item['desc']} {item['category']}".lower()
        if q in haystack:
            matches.append(item)

    embed = _v7_embed(
        f"🔎 Resultados para: {busqueda}",
        f"Encontré **{len(matches)}** coincidencia(s).",
        V7_ACCENT,
        ctx
    )
    if not matches:
        embed.description = "No encontré nada. Prueba con otra palabra: `tienda`, `nivel`, `juego`, `plantilla`, `ia`."
    else:
        lines = []
        for item in matches[:18]:
            lines.append(f"**{item['raw']}** · `{item['category']}`\n{_v7_trim(item['desc'], 90)}")
        embed.add_field(name="Coincidencias", value=_v7_trim("\n\n".join(lines), 1024), inline=False)
    await ctx.send(embed=embed)


