# @bot.command(name="auditar_bot")  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 20, commands.BucketType.user)
async def auditar_bot_cmd(ctx):
    """Auditor técnico del bot."""
    if not _v7_is_staff(ctx):
        await ctx.send(embed=_v7_embed("🛡️ Solo staff", "Este auditor toca zonas técnicas. Necesitas admin o ser Markelson.", V7_BAD, ctx), delete_after=12)
        return

    real_commands = [c for c in bot.commands if not c.hidden]
    help_entries = _v7_all_help_entries()
    documented = set(help_entries.keys())
    missing = []
    for cmd in real_commands:
        name = f"!{cmd.qualified_name}".lower()
        if name not in documented:
            missing.append(name)

    files_to_check = [
        ("datos.json", DATOS_FILE),
        ("memoria AETHER", MEMORIA_FILE),
        ("historial IA", AI_HISTORIAL_FILE),
        ("tienda RL", RL_SHOP_STATE_FILE),
        ("streams", STREAMS_DATA_FILE),
    ]
    file_lines = []
    for label, path in files_to_check:
        file_lines.append(f"{'✅' if os.path.exists(path) else '⚠️'} {label}")

    env_lines = [
        f"{'✅' if os.getenv('TOKEN') else '❌'} TOKEN",
        f"{'✅' if os.getenv('GROQ_API_KEY') else '⚠️'} GROQ_API_KEY",
        f"{'✅' if os.getenv('OPENROUTER_API_KEY') else '⚪'} OPENROUTER_API_KEY",
        f"{'✅' if os.getenv('DEEPSEEK_API_KEY') else '⚪'} DEEPSEEK_API_KEY",
    ]

    embed = _v7_embed(
        "🧪 Auditor técnico X AETHER ULTRA",
        "Revisión rápida del núcleo. No modifica nada, solo mira y señala con láser morado.",
        V7_ACCENT,
        ctx
    )
    embed.add_field(name="📦 Comandos", value=f"Reales: **{len(real_commands)}**\nDocumentados: **{len(help_entries)}**\nSin ayuda: **{len(missing)}**", inline=True)
    embed.add_field(name="📁 Archivos", value="\n".join(file_lines), inline=True)
    embed.add_field(name="🔐 Entorno", value="\n".join(env_lines), inline=True)
    if missing:
        embed.add_field(name="⚠️ Comandos sin ayuda", value=_v7_trim(", ".join(missing[:35]), 1024), inline=False)
    else:
        embed.add_field(name="✅ Ayuda", value="Todos los comandos principales parecen estar documentados.", inline=False)
    embed.add_field(name="🧭 Recomendación", value="Cuando el bot crezca más, el siguiente salto serio es separar en cogs: economía, minijuegos, IA, tienda, plantillas y eventos.", inline=False)
    await ctx.send(embed=embed)


