V8_VERSION = "X AETHER ULTRA 3.1.0 · Core Premium"
V8_GEM = "💎"
V8_LINE = "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
V8_SOFT_LINE = "────────────────────────────────"
V8_SPARKS = ["✦", "✧", "◆", "◇", "▰", "▱", "◈", "▸", "▹"]
V8_PANEL_COLOR = discord.Color.from_rgb(138, 43, 226)
V8_DEEP_COLOR = discord.Color.from_rgb(72, 25, 120)
V8_NEON_COLOR = discord.Color.from_rgb(190, 120, 255)


def _v8_pick_spark(index: int = 0) -> str:
    """Devuelve un símbolo decorativo estable para listas bonitas."""
    try:
        return V8_SPARKS[index % len(V8_SPARKS)]
    except Exception:
        return "✦"


def _v8_bar(label: str = "X AETHER ULTRA", size: int = 30) -> str:
    """Genera una barra compacta para embeds sin pasarse del ancho visual."""
    label = str(label or "X AETHER ULTRA").strip().upper()[:28]
    side = "━" * max(3, min(size, 34))
    return f"`{side} {label} {side}`"


def _v8_chip(texto: str, emoji: str = "◈") -> str:
    """Pequeña cápsula visual para estados, secciones y datos rápidos."""
    texto = str(texto or "").strip()
    return f"{emoji} **{texto}**"


def _v8_code_banner(title: str, subtitle: str = "") -> str:
    """Plantilla de comentario grande para pegar en zonas nuevas del app.py."""
    title = str(title or "BLOQUE").upper()[:62]
    subtitle = str(subtitle or "").strip()[:70]
    line_title = f"# ║  {title:<72}║"
    line_sub = f"# ║  {subtitle:<72}║" if subtitle else "# ║                                                                        ║"
    return "\n".join([
        "# ╔════════════════════════════════════════════════════════════════════════╗",
        line_title,
        line_sub,
        "# ╚════════════════════════════════════════════════════════════════════════╝",
    ])


def _v8_mini_banner(title: str) -> str:
    """Plantilla de comentario mediano para separar funciones."""
    title = str(title or "SECCIÓN").strip()[:60]
    return "\n".join([
        "# ──────────────────────────────────────────────────────────────────────",
        f"# {title}",
        "# ──────────────────────────────────────────────────────────────────────",
    ])


def _v8_compact_list(items, emoji: str = "✦", limit: int = 900) -> str:
    """Convierte una lista en líneas elegantes aptas para campos de embed."""
    lines = []
    for i, item in enumerate(items or []):
        mark = _v8_pick_spark(i) if emoji == "auto" else emoji
        lines.append(f"{mark} {item}")
    return _v7_trim("\n".join(lines), limit)


def _v8_premium_embed(title: str, description: str = "", ctx=None, color=None, footer: str = None) -> discord.Embed:
    """Embed 3.1.0 con decoración premium y firma visual consistente."""
    decorated_description = (
        f"{_v8_bar('X AETHER ULTRA 3.1.0')}\n"
        f"{description or 'Panel visual activo.'}\n\n"
        f"`{V8_SOFT_LINE}`"
    )
    embed = discord.Embed(
        title=f"◈ {title}",
        description=decorated_description,
        color=color or V8_PANEL_COLOR,
        timestamp=datetime.datetime.now()
    )
    try:
        if bot.user:
            embed.set_author(name="X AETHER ULTRA · Decoración Premium", icon_url=bot.user.display_avatar.url)
            embed.set_thumbnail(url=bot.user.display_avatar.url)
    except Exception:
        pass
    try:
        if ctx is not None:
            embed.set_footer(text=footer or f"{V8_VERSION} · solicitado por {ctx.author.display_name}", icon_url=ctx.author.display_avatar.url)
        else:
            embed.set_footer(text=footer or V8_VERSION)
    except Exception:
        embed.set_footer(text=footer or V8_VERSION)
    return embed


