def _v9_chunks(items: list, size: int) -> list:
    return [items[i:i + size] for i in range(0, len(items), size)] or [[]]


def _v9_clamp_page(page: int, total_pages: int) -> int:
    try:
        page = int(page)
    except Exception:
        page = 1
    return max(1, min(max(1, total_pages), page))


def _v9_clean_category(cat: str) -> str:
    cat = (cat or "otros").strip().lower().replace("á", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u")
    cat = cat.replace(" ", "_").replace("-", "_")
    aliases = {
        "basico": "basicos", "basicos": "basicos", "general": "basicos",
        "eco": "economia", "economía": "economia", "dinero": "economia",
        "juegos": "minijuegos", "casino": "minijuegos", "gamehub": "minijuegos",
        "mod": "moderacion", "admin": "moderacion", "staff": "moderacion",
        "ia": "aether", "ai": "aether", "memoria": "aether",
        "plantilla": "plantillas", "templates": "plantillas", "template": "plantillas",
        "perfil_xp": "perfil", "xp": "perfil", "nivel": "perfil",
        "shop": "tienda", "store": "tienda",
        "utilidad": "utilidades", "tools": "utilidades",
    }
    return aliases.get(cat, cat)


def _v9_command_keys_from_label(label: str) -> set:
    found = set()
    for raw in re.findall(r"[!/]([A-Za-z0-9_]+)", str(label or "")):
        found.add(raw.lower())
    return found


def _v9_infer_category(cmd) -> str:
    name = getattr(cmd, "name", "").lower()
    aliases = [a.lower() for a in getattr(cmd, "aliases", [])]
    pool = " ".join([name] + aliases + [str(getattr(cmd, "help", "") or ""), str(getattr(cmd, "description", "") or "")]).lower()

    if name in V9_COMMAND_HINTS:
        return V9_COMMAND_HINTS[name][0]
    if any(k in pool for k in ["plantilla", "rollback", "backup", "template"]):
        return "plantillas"
    if any(k in pool for k in ["memoria", "aether", "ia", "modelo", "deepseek", "groq", "openrouter"]):
        return "aether"
    if any(k in pool for k in ["tienda", "comprar", "inventario", "equipar", "oferta", "vender", "cofre", "mascota"]):
        return "tienda"
    if any(k in pool for k in ["lvl", "xp", "perfil", "nivel", "coleccion", "logro", "fondo"]):
        return "perfil"
    if any(k in pool for k in ["daily", "trabajar", "banco", "cash", "bal", "robar", "crimen", "prestamo", "invertir", "nomina", "donar", "misiones", "rep"]):
        return "economia"
    if any(k in pool for k in ["blackjack", "ruleta", "slots", "dado", "ppt", "apostar", "bingo", "tiro", "ahorcado", "juego", "casino", "adivina"]):
        return "minijuegos"
    if any(k in pool for k in ["ban", "kick", "clear", "warn", "aviso", "rol", "moder", "staff", "permis", "lock"]):
        return "moderacion"
    if any(k in pool for k in ["ticket", "soporte"]):
        return "tickets"
    if any(k in pool for k in ["stream", "twitch", "youtube", "directo", "kick.com"]):
        return "streams"
    if any(k in pool for k in ["ouroboros", "evolucion", "reflexion"]):
        return "ouroboros"
    if any(k in pool for k in ["status", "panel", "ayuda", "comando", "auditar", "mapa", "decoracion", "guia", "credito", "vitrina"]):
        return "utilidades"
    return "otros"


def _v9_command_desc(cmd) -> str:
    doc = getattr(cmd, "help", None) or getattr(cmd, "description", None) or getattr(cmd, "brief", None) or ""
    doc = str(doc).strip().split("\n")[0].strip()
    return doc or "Comando disponible."


def _v9_command_label(cmd) -> str:
    name = getattr(cmd, "name", "comando")
    if name.lower() in V9_COMMAND_HINTS:
        return V9_COMMAND_HINTS[name.lower()][1]
    return f"!{name}"


def _v9_order_catalog(catalog: dict) -> dict:
    ordered = {}
    for cat in V9_HELP_ORDER:
        if cat in catalog:
            ordered[cat] = dict(sorted(catalog[cat].items(), key=lambda kv: str(kv[0]).lower()))
    for cat in sorted(c for c in catalog.keys() if c not in ordered):
        ordered[cat] = dict(sorted(catalog[cat].items(), key=lambda kv: str(kv[0]).lower()))
    return ordered


def _v9_build_help_catalog() -> dict:
    """Crea un catálogo fresco: categorías manuales + comandos reales + slash commands."""
    catalog = {}
    known = set()

    for raw_cat, raw_items in COMMAND_CATEGORIES.items():
        cat = _v9_clean_category(raw_cat)
        catalog.setdefault(cat, {})
        if isinstance(raw_items, dict):
            for label, desc in raw_items.items():
                label = str(label).strip()
                if not label:
                    continue
                catalog[cat][label] = str(desc or "Comando disponible.").strip()
                known.update(_v9_command_keys_from_label(label))

    # Pistas 3.1.0 explícitas para comandos importantes.
    for name, (cat, label, desc) in V9_COMMAND_HINTS.items():
        cat = _v9_clean_category(cat)
        catalog.setdefault(cat, {})
        keys = _v9_command_keys_from_label(label) or {name}
        if not keys.intersection(known):
            catalog[cat][label] = desc
            known.update(keys)

    # Comandos reales de discord.py cargados en el bot.
    try:
        command_list = sorted(list(bot.commands), key=lambda c: c.name.lower())
    except Exception:
        command_list = []

    for cmd in command_list:
        if getattr(cmd, "hidden", False):
            continue
        names = {getattr(cmd, "name", "").lower()} | {a.lower() for a in getattr(cmd, "aliases", [])}
        names.discard("")
        if names.intersection(known):
            continue
        cat = _v9_clean_category(_v9_infer_category(cmd))
        label = _v9_command_label(cmd)
        desc = _v9_command_desc(cmd)
        aliases = [a for a in getattr(cmd, "aliases", []) if a]
        if aliases:
            desc += "\nAliases: " + " · ".join(f"`!{a}`" for a in aliases[:6])
        catalog.setdefault(cat, {})[label] = desc
        known.update(names)

    # Slash commands, si existen.
    try:
        slash_list = sorted(tree.get_commands(), key=lambda c: c.name.lower())
    except Exception:
        slash_list = []
    for cmd in slash_list:
        name = getattr(cmd, "name", "").lower()
        if not name or name in known:
            continue
        desc = getattr(cmd, "description", None) or "Comando slash disponible."
        catalog.setdefault("otros", {})[f"/{name}"] = desc
        known.add(name)

    # Limpieza de categorías vacías.
    catalog = {cat: items for cat, items in catalog.items() if isinstance(items, dict) and items}
    return _v9_order_catalog(catalog)


def _v9_pretty_cat(cat: str) -> tuple:
    cat = _v9_clean_category(cat)
    return V9_HELP_META.get(cat, ("📌", cat.replace("_", " ").title(), "Categoría detectada automáticamente."))


def _v9_make_help_home(ctx, catalog: dict) -> discord.Embed:
    total_entries = sum(len(items) for items in catalog.values())
    total_prefix = len([c for c in bot.commands if not getattr(c, "hidden", False)])
    try:
        total_slash = len(tree.get_commands())
    except Exception:
        total_slash = 0

    embed = _v8_premium_embed(
        "Centro de ayuda total",
        "Catálogo reconstruido en tiempo real: categorías manuales, comandos reales, aliases y slash commands. Nada se queda perdido en el sótano del monolito.",
        ctx=ctx,
        color=V8_PANEL_COLOR
    ) if "_v8_premium_embed" in globals() else _am_embed(
        "📚 Centro de ayuda total",
        "Catálogo reconstruido en tiempo real: categorías manuales, comandos reales, aliases y slash commands.",
        XAU_PUBLIC_PURPLE,
        ctx
    )
    embed.add_field(name="📦 Comandos detectados", value=f"Prefijo: **{total_prefix}**\nSlash: **{total_slash}**\nEntradas ayuda: **{total_entries}**", inline=True)
    embed.add_field(name="🧭 Uso rápido", value="`!ayuda`\n`!ayuda economia`\n`!ayuda minijuegos 2`\n`!ayuda aether`", inline=True)

    rows = []
    for cat, items in catalog.items():
        emoji, title, desc = _v9_pretty_cat(cat)
        pages = len(_v9_chunks(list(items.items()), V9_HELP_PAGE_SIZE))
        rows.append(f"{emoji} **{title}** · `{cat}` · **{len(items)}** cmds · {pages} pág.")

    for idx, chunk in enumerate(_v9_chunks(rows, 10), start=1):
        embed.add_field(name=f"🟣 Categorías {idx}", value="\n".join(chunk)[:1024], inline=False)

    embed.set_footer(text=f"{V9_VERSION} • Selector activo durante 4 minutos", icon_url=ctx.author.display_avatar.url)
    return embed


def _v9_make_help_category(ctx, catalog: dict, cat: str, page: int = 1) -> discord.Embed:
    cat = _v9_clean_category(cat)
    items = list(catalog.get(cat, {}).items())
    emoji, title, desc = _v9_pretty_cat(cat)
    pages = _v9_chunks(items, V9_HELP_PAGE_SIZE)
    page = _v9_clamp_page(page, len(pages))

    embed = _v8_premium_embed(
        f"{emoji} Ayuda · {title}",
        f"{desc}\nPágina **{page}/{len(pages)}** · `{len(items)}` entradas detectadas.",
        ctx=ctx,
        color=V8_PANEL_COLOR
    ) if "_v8_premium_embed" in globals() else _am_embed(
        f"{emoji} Ayuda · {title}",
        f"{desc}\nPágina **{page}/{len(pages)}** · `{len(items)}` entradas detectadas.",
        XAU_PUBLIC_PURPLE,
        ctx
    )

    current = pages[page - 1]
    if not current:
        embed.add_field(name="Sin comandos", value="Esta categoría está vacía.", inline=False)
    else:
        for label, description in current:
            description = str(description or "Comando disponible.").strip()
            if len(description) > 420:
                description = description[:417] + "..."
            embed.add_field(name=str(label)[:256], value=description or "Comando disponible.", inline=False)

    embed.add_field(name="🧭 Navegación", value="Usa los botones, el selector o escribe `!ayuda <categoría> <página>`.", inline=False)
    embed.set_footer(text=f"Categoría: {cat} • Página {page}/{len(pages)} • {V9_VERSION}", icon_url=ctx.author.display_avatar.url)
    return embed


class V9HelpSelect(discord.ui.Select):
    def __init__(self, owner_id: int, catalog: dict):
        self.owner_id = owner_id
        options = []
        for cat, items in list(catalog.items())[:25]:
            emoji, title, desc = _v9_pretty_cat(cat)
            options.append(discord.SelectOption(
                label=title[:100],
                value=cat,
                emoji=emoji,
                description=f"{len(items)} comandos · {desc}"[:100]
            ))
        super().__init__(placeholder="Selecciona una categoría del bot", options=options, min_values=1, max_values=1, row=0)

    async def callback(self, interaction: discord.Interaction):
        view = self.view
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Abre tu propio centro con `!ayuda`.", ephemeral=True)
            return
        view.category = self.values[0]
        view.page = 1
        view.catalog = _v9_build_help_catalog()
        view._sync_buttons()
        await interaction.response.edit_message(embed=_v9_make_help_category(view.ctx, view.catalog, view.category, view.page), view=view)


class V9HelpView(discord.ui.View):
    def __init__(self, ctx, category: str = None, page: int = 1):
        super().__init__(timeout=240)
        self.ctx = ctx
        self.owner_id = ctx.author.id
        self.catalog = _v9_build_help_catalog()
        self.category = _v9_clean_category(category) if category else None
        self.page = max(1, int(page or 1))
        if self.catalog:
            self.add_item(V9HelpSelect(self.owner_id, self.catalog))
        self._sync_buttons()

    def _max_pages(self) -> int:
        if not self.category:
            return 1
        return len(_v9_chunks(list(self.catalog.get(self.category, {}).items()), V9_HELP_PAGE_SIZE))

    def _sync_buttons(self):
        max_pages = self._max_pages()
        for item in self.children:
            if isinstance(item, discord.ui.Button):
                if item.custom_id == "v9_help_prev":
                    item.disabled = not self.category or self.page <= 1
                elif item.custom_id == "v9_help_next":
                    item.disabled = not self.category or self.page >= max_pages

    async def _guard(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel pertenece a otra persona. Usa `!ayuda` para abrir el tuyo.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="⬅️", style=discord.ButtonStyle.secondary, custom_id="v9_help_prev", row=1)
    async def prev_page(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.page = max(1, self.page - 1)
        self.catalog = _v9_build_help_catalog()
        self._sync_buttons()
        await interaction.response.edit_message(embed=_v9_make_help_category(self.ctx, self.catalog, self.category, self.page), view=self)

    @discord.ui.button(label="🏠 Inicio", style=discord.ButtonStyle.blurple, custom_id="v9_help_home", row=1)
    async def home_page(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.category = None
        self.page = 1
        self.catalog = _v9_build_help_catalog()
        self._sync_buttons()
        await interaction.response.edit_message(embed=_v9_make_help_home(self.ctx, self.catalog), view=self)

    @discord.ui.button(label="➡️", style=discord.ButtonStyle.secondary, custom_id="v9_help_next", row=1)
    async def next_page(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.catalog = _v9_build_help_catalog()
        self.page = min(self._max_pages(), self.page + 1)
        self._sync_buttons()
        await interaction.response.edit_message(embed=_v9_make_help_category(self.ctx, self.catalog, self.category, self.page), view=self)

    @discord.ui.button(label="🔄 Actualizar", style=discord.ButtonStyle.success, custom_id="v9_help_refresh", row=1)
    async def refresh_page(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.catalog = _v9_build_help_catalog()
        self._sync_buttons()
        embed = _v9_make_help_category(self.ctx, self.catalog, self.category, self.page) if self.category else _v9_make_help_home(self.ctx, self.catalog)
        await interaction.response.edit_message(embed=embed, view=self)


