def _v9_memory_clean_text(text: str) -> str:
    text = str(text or "").replace("\n", " ").strip()
    text = re.sub(r"\s+", " ", text)
    text = text.lstrip("-•· ").strip()
    return text[:260]


def _v9_memory_dedupe(recuerdos: list) -> list:
    clean = []
    seen = set()
    for item in recuerdos or []:
        txt = _v9_memory_clean_text(item)
        if not txt or len(txt) < 4:
            continue
        key = re.sub(r"[^a-z0-9áéíóúñü]+", "", txt.lower())[:180]
        if key in seen:
            continue
        seen.add(key)
        clean.append(txt)
    return clean


# Sobrescribe el lector para que siempre devuelva datos sanos y sin basura.
def obtener_memoria_usuario(user_id: int) -> list:
    memoria = cargar_memoria_aether()
    uid = str(user_id)
    raw = memoria.get(uid, {}) if isinstance(memoria, dict) else {}
    recuerdos = raw.get("recuerdos", []) if isinstance(raw, dict) else []
    return _v9_memory_dedupe(recuerdos)


# Sobrescribe el contexto para que la IA no reciba paredes infinitas de memoria.
def construir_contexto_memoria(user_id: int) -> str:
    recuerdos = obtener_memoria_usuario(user_id)
    if not recuerdos:
        return ""
    seleccion = recuerdos[-V9_MEMORY_CONTEXT_LIMIT:]
    lineas = "\n".join(f"  - {r}" for r in seleccion)
    total = len(recuerdos)
    extra = f"\n  - Nota interna: hay {total} recuerdos totales; se muestran los {len(seleccion)} más recientes/relevantes." if total > len(seleccion) else ""
    return f"""\n━━ MEMORIA PERSISTENTE DE ESTE USUARIO ━━━━━━━━━━━━\n{lineas}{extra}\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nUsa estos recuerdos de forma natural. No los listes todos salvo que el usuario lo pida."""


async def actualizar_memoria_aether(user_id: int, username: str, historial_reciente: list):
    """Actualiza memoria con límite amplio, deduplicación y prompt pequeño."""
    if not GROQ_API_KEY or len(historial_reciente or []) < 2:
        return
    mensajes_usuario = [m for m in historial_reciente if isinstance(m, dict) and m.get("role") == "user"]
    if len(mensajes_usuario) < 2:
        return
    try:
        conv_texto = ""
        for m in historial_reciente[-10:]:
            if not isinstance(m, dict):
                continue
            rol = username if m.get("role") == "user" else "AETHER"
            contenido = str(m.get("content", ""))[:700]
            conv_texto += f"{rol}: {contenido}\n"

        recuerdos_actuales = obtener_memoria_usuario(user_id)
        recuerdos_str = "\n".join(f"- {r}" for r in recuerdos_actuales[-80:]) if recuerdos_actuales else "Ninguno aún."

        prompt_memoria = f"""Eres el módulo de memoria persistente de AETHER para Discord.

Usuario: {username}

CONVERSACIÓN RECIENTE:
{conv_texto}

RECUERDOS EXISTENTES, SOLO LOS MÁS RECIENTES:
{recuerdos_str}

OBJETIVO:
Decide si hay información nueva, útil y estable que deba recordarse.

REGLAS:
- Responde exactamente NADA si no hay nada útil.
- Recuerda solo preferencias, proyectos, datos personales no sensibles, planes, gustos, contexto técnico o decisiones importantes.
- No guardes saludos, preguntas genéricas, insultos, secretos, tokens, contraseñas, datos bancarios ni información demasiado privada.
- No dupliques recuerdos existentes.
- Máximo 4 recuerdos nuevos.
- Cada recuerdo debe tener menos de 160 caracteres.
- Formato obligatorio si hay recuerdos: una línea por recuerdo empezando con '-'.

RESPUESTA:"""

        resultado = await _llamar_groq_async(
            [{"role": "user", "content": prompt_memoria}],
            GROQ_MODELOS[_modelo_idx]
        )
        resultado = (resultado or "").strip()
        if not resultado or resultado.upper() == "NADA":
            return

        nuevos = []
        for linea in resultado.splitlines():
            linea = _v9_memory_clean_text(linea)
            if linea and linea.upper() != "NADA":
                nuevos.append(linea)
        nuevos = _v9_memory_dedupe(nuevos)[:4]
        if not nuevos:
            return

        memoria = cargar_memoria_aether()
        uid = str(user_id)
        if uid not in memoria or not isinstance(memoria.get(uid), dict):
            memoria[uid] = {
                "username": username,
                "primera_vez": datetime.datetime.now().isoformat(),
                "recuerdos": []
            }

        fusion = _v9_memory_dedupe(list(memoria[uid].get("recuerdos", [])) + nuevos)
        memoria[uid]["username"] = username
        memoria[uid]["ultima_actualizacion"] = datetime.datetime.now().isoformat()
        memoria[uid]["recuerdos"] = fusion[-V9_MEMORY_MAX_RECUERDOS:]
        memoria[uid]["memoria_v9"] = {
            "max_recuerdos": V9_MEMORY_MAX_RECUERDOS,
            "page_size": V9_MEMORY_PAGE_SIZE,
            "ultima_limpieza": datetime.datetime.now().isoformat(),
        }
        guardar_memoria_aether(memoria)
        print(f"[AETHER MEM 3.1.0] {username}: +{len(nuevos)} recuerdos, total={len(memoria[uid]['recuerdos'])}")
    except Exception as e:
        print(f"[AETHER MEM 3.1.0] Error actualizando memoria: {e}")


def _v9_memory_pages(recuerdos: list) -> list:
    return _v9_chunks(_v9_memory_dedupe(recuerdos), V9_MEMORY_PAGE_SIZE)


def _v9_make_memory_embed(ctx, miembro: discord.Member, recuerdos: list, page: int = 1, *, admin_view: bool = False) -> discord.Embed:
    recuerdos = _v9_memory_dedupe(recuerdos)
    pages = _v9_memory_pages(recuerdos)
    page = _v9_clamp_page(page, len(pages))
    current = pages[page - 1]
    owner_text = f"sobre **{miembro.display_name}**" if admin_view else f"de **{miembro.display_name}**"

    embed = _v8_premium_embed(
        "Memoria AETHER",
        f"Recuerdos persistentes {owner_text}. Página **{page}/{len(pages)}** · **{len(recuerdos)}** recuerdos totales.",
        ctx=ctx,
        color=V8_NEON_COLOR
    ) if "_v8_premium_embed" in globals() else _am_embed(
        "🧠 Memoria AETHER",
        f"Página **{page}/{len(pages)}** · **{len(recuerdos)}** recuerdos totales.",
        XAU_PUBLIC_PURPLE,
        ctx
    )

    try:
        embed.set_thumbnail(url=miembro.display_avatar.url)
    except Exception:
        pass

    if not recuerdos:
        embed.add_field(
            name="🌙 Sin recuerdos guardados",
            value="Todavía no hay memoria persistente para este usuario. Habla con AETHER y se irá construyendo con el tiempo.",
            inline=False
        )
    else:
        start = (page - 1) * V9_MEMORY_PAGE_SIZE
        lines = []
        for idx, recuerdo in enumerate(current, start=start + 1):
            recuerdo = _v9_memory_clean_text(recuerdo)
            lines.append(f"`{idx:02d}.` {recuerdo}")
        for field_idx, chunk in enumerate(_v9_chunks(lines, 5), start=1):
            embed.add_field(name=f"💠 Recuerdos {field_idx}", value="\n".join(chunk)[:1024], inline=False)

    embed.add_field(
        name="🧭 Navegación",
        value="Botones: `⬅️` `➡️` · Comando: `!mimemoria <página>` · Admin: `!memoriaaether @usuario <página>`",
        inline=False
    )
    embed.set_footer(text=f"{V9_VERSION} • 10 recuerdos por página", icon_url=ctx.author.display_avatar.url)
    return embed


class V9MemoryView(discord.ui.View):
    def __init__(self, ctx, miembro: discord.Member, recuerdos: list, page: int = 1, *, admin_view: bool = False):
        super().__init__(timeout=240)
        self.ctx = ctx
        self.owner_id = ctx.author.id
        self.miembro = miembro
        self.recuerdos = _v9_memory_dedupe(recuerdos)
        self.admin_view = admin_view
        self.page = _v9_clamp_page(page, len(_v9_memory_pages(self.recuerdos)))
        self._sync_buttons()

    def _max_pages(self) -> int:
        return len(_v9_memory_pages(self.recuerdos))

    def _sync_buttons(self):
        for item in self.children:
            if isinstance(item, discord.ui.Button):
                if item.custom_id == "v9_mem_prev":
                    item.disabled = self.page <= 1
                elif item.custom_id == "v9_mem_next":
                    item.disabled = self.page >= self._max_pages()

    async def _guard(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de memoria pertenece a otra persona.", ephemeral=True)
            return False
        return True

    async def _refresh(self, interaction: discord.Interaction):
        self.recuerdos = obtener_memoria_usuario(self.miembro.id)
        self.page = _v9_clamp_page(self.page, self._max_pages())
        self._sync_buttons()
        await interaction.response.edit_message(embed=_v9_make_memory_embed(self.ctx, self.miembro, self.recuerdos, self.page, admin_view=self.admin_view), view=self)

    @discord.ui.button(label="⬅️", style=discord.ButtonStyle.secondary, custom_id="v9_mem_prev")
    async def prev_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.page = max(1, self.page - 1)
        await self._refresh(interaction)

    @discord.ui.button(label="➡️", style=discord.ButtonStyle.secondary, custom_id="v9_mem_next")
    async def next_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.page = min(self._max_pages(), self.page + 1)
        await self._refresh(interaction)

    @discord.ui.button(label="🔄 Actualizar", style=discord.ButtonStyle.success, custom_id="v9_mem_refresh")
    async def refresh_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        await self._refresh(interaction)


