def _v10_load_json(path: str, default=None):
    if default is None:
        default = {}
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception as exc:
        try:
            logger.warning("[3.1.0] No se pudo cargar %s: %s", path, exc)
        except Exception:
            pass
    return default


def _v10_save_json(path: str, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        return True
    except Exception as exc:
        try:
            logger.warning("[3.1.0] No se pudo guardar %s: %s", path, exc)
        except Exception:
            pass
        return False


def _v10_today() -> str:
    return datetime.date.today().isoformat()


def _v10_money(n: int) -> str:
    try:
        return f"{int(n):,}".replace(",", ".") + f" {amatista}"
    except Exception:
        return f"{n} {amatista}"


def _v10_bar(pct: float, size: int = 18, fill: str = "▰", empty: str = "▱") -> str:
    pct = max(0.0, min(1.0, float(pct or 0)))
    filled = int(round(size * pct))
    return fill * filled + empty * (size - filled)


def _v10_embed(title: str, description: str = "", *, ctx=None, color: int = V10_PURPLE, footer: str = None) -> discord.Embed:
    desc = str(description or "")
    if len(desc) > 4096:
        desc = desc[:4090] + "..."
    embed = discord.Embed(title=title, description=desc, color=color, timestamp=discord.utils.utcnow())
    if ctx is not None:
        try:
            embed.set_footer(text=footer or f"{V10_VERSION} · {ctx.author.display_name}", icon_url=ctx.author.display_avatar.url)
        except Exception:
            embed.set_footer(text=footer or V10_VERSION)
    else:
        embed.set_footer(text=footer or V10_VERSION)
    return embed


def _v10_parse_bet(datos: dict, uid: str, cantidad: str, *, min_bet: int = 1, max_bet: int = None):
    asegurar_usuario(datos, uid)
    cash = int(datos[uid].get("cash", 0) or 0)
    raw = str(cantidad or "").lower().strip()
    if raw in ("all", "todo", "max", "full"):
        bet = cash
    elif raw in ("mitad", "half", "50%"):
        bet = cash // 2
    elif raw in ("cuarto", "25%"):
        bet = cash // 4
    else:
        raw = raw.replace(".", "").replace(",", "")
        if not raw.isdigit():
            return None, "Cantidad inválida. Usa un número, `all`, `mitad` o `cuarto`."
        bet = int(raw)
    if bet < min_bet:
        return None, f"La apuesta mínima es **{_v10_money(min_bet)}**."
    if max_bet is not None and bet > max_bet:
        return None, f"La apuesta máxima aquí es **{_v10_money(max_bet)}**."
    if bet > cash:
        return None, f"Cash insuficiente. Tienes **{_v10_money(cash)}**."
    return bet, None


def _v10_add_xp(datos: dict, uid: str, xp: int):
    asegurar_usuario(datos, uid)
    datos[uid]["experiencia"] = int(datos[uid].get("experiencia", 0) or 0) + max(0, int(xp or 0))
    subidas = 0
    while True:
        nivel = int(datos[uid].get("nivel", 1) or 1)
        needed = _xp_needed_for_level(nivel) if "_xp_needed_for_level" in globals() else 100 + (nivel - 1) * 50
        if datos[uid]["experiencia"] < needed:
            break
        datos[uid]["experiencia"] -= needed
        datos[uid]["nivel"] = nivel + 1
        reward = 50 + datos[uid]["nivel"] * 10
        agregar_a_cash_y_monedas(datos, uid, reward)
        subidas += 1
    return subidas


def _v10_game_bucket(datos: dict, uid: str, game: str) -> dict:
    try:
        return _game_stats_bucket(datos, uid, game)
    except Exception:
        asegurar_usuario(datos, uid)
        stats = datos[uid].setdefault("game_stats", {})
        return stats.setdefault(game, {"jugadas": 0, "ganadas": 0, "perdidas": 0, "neto": 0, "racha": 0, "mejor_racha": 0})


def _v10_record_game(datos: dict, uid: str, game: str, won: bool, net: int, xp: int = 0):
    try:
        _record_game(datos, uid, game, won, net)
    except Exception:
        bucket = _v10_game_bucket(datos, uid, game)
        bucket["jugadas"] = int(bucket.get("jugadas", 0) or 0) + 1
        bucket["neto"] = int(bucket.get("neto", 0) or 0) + int(net or 0)
        if won:
            bucket["ganadas"] = int(bucket.get("ganadas", 0) or 0) + 1
            bucket["racha"] = int(bucket.get("racha", 0) or 0) + 1
            bucket["mejor_racha"] = max(int(bucket.get("mejor_racha", 0) or 0), int(bucket.get("racha", 0) or 0))
        else:
            bucket["perdidas"] = int(bucket.get("perdidas", 0) or 0) + 1
            bucket["racha"] = 0
    if xp:
        _v10_add_xp(datos, uid, xp)


def _v10_stats_footer(datos: dict, uid: str, game: str) -> str:
    b = _v10_game_bucket(datos, uid, game)
    return (
        f"{V10_VERSION} · partidas {b.get('jugadas', 0)} · victorias {b.get('ganadas', 0)} · "
        f"racha {b.get('racha', 0)} · neto {int(b.get('neto', 0) or 0):,}"
    ).replace(",", ".")


