def _v10_give_item(datos: dict, uid: str, item_key: str) -> bool:
    asegurar_usuario(datos, uid)
    item = TIENDA_ITEMS.get(item_key)
    if not item:
        return False
    tipo = item.get("tipo", item_key)
    inv = datos[uid].setdefault("items", {})
    if tipo in inv:
        return False
    inv[tipo] = {
        "nombre": item.get("nombre", item_key),
        "emoji": item.get("emoji", "✨"),
        "tipo": tipo,
        "rareza": item.get("rareza", "especial"),
        "slot": item.get("slot"),
        "permanente": True,
        "origen": "reputacion_v10",
    }
    return True


