V10_REP_TIERS = [
    (0, "🌱 Nuevo", "Sin bonus todavía"),
    (5, "🤝 Confiable", "+bonus básico en !repbonus"),
    (15, "💬 Querido", "Desbloquea título social"),
    (50, "🌟 Popular", "Desbloquea placa popular"),
    (100, "👑 Referente", "Desbloquea fondo de reputación"),
    (200, "💎 Leyenda Social", "Desbloquea marco social dorado"),
]


def _v10_rep_tier(rep: int):
    actual = V10_REP_TIERS[0]
    for tier in V10_REP_TIERS:
        if int(rep or 0) >= tier[0]:
            actual = tier
    return actual


def _v10_rep_progress(rep: int):
    rep = int(rep or 0)
    current = V10_REP_TIERS[0]
    next_tier = None
    for i, tier in enumerate(V10_REP_TIERS):
        if rep >= tier[0]:
            current = tier
            next_tier = V10_REP_TIERS[i + 1] if i + 1 < len(V10_REP_TIERS) else None
    if not next_tier:
        return current, None, 1.0
    prev = current[0]
    nxt = next_tier[0]
    pct = (rep - prev) / max(1, nxt - prev)
    return current, next_tier, pct


def _v10_rep_embed(ctx, member: discord.Member):
    datos = cargar_datos()
    uid = str(member.id)
    asegurar_usuario(datos, uid)
    rep = int(datos[uid].get("reputacion", 0) or 0)
    current, next_tier, pct = _v10_rep_progress(rep)
    embed = _v10_embed(
        f"⭐ Reputación de {member.display_name}",
        "La reputación ahora sirve para bonus diarios, cosméticos sociales y prestigio del servidor.",
        ctx=ctx,
        color=V10_GOLD,
    )
    embed.set_thumbnail(url=member.display_avatar.url)
    embed.add_field(name="Puntos", value=f"**{rep}** rep", inline=True)
    embed.add_field(name="Tier actual", value=f"{current[1]}\n{current[2]}", inline=True)
    if next_tier:
        faltan = max(0, next_tier[0] - rep)
        embed.add_field(name="Siguiente tier", value=f"{next_tier[1]}\nFaltan **{faltan}** rep\n{_v10_bar(pct, 18)}", inline=False)
    else:
        embed.add_field(name="Siguiente tier", value="Nivel social máximo alcanzado. La vitrina ya huele a corona.", inline=False)
    embed.add_field(name="Comandos útiles", value="`!rep @usuario` · `!repbonus` · `!repclaim` · `!toprep`", inline=False)
    return embed


