@commands.cooldown(1, 5, commands.BucketType.user)
async def rep_cmd_v10(ctx, miembro: discord.Member = None):
    """Da reputación o mira tu reputación. Uso: !rep @usuario"""
    if miembro is None:
        await ctx.send(embed=_v10_rep_embed(ctx, ctx.author))
        return
    if miembro.bot:
        await ctx.send(embed=_v10_embed("⭐ Reputación", "Los bots no necesitan reputación. Ya viven en cables y paciencia.", ctx=ctx, color=V10_RED))
        return
    if miembro.id == ctx.author.id:
        await ctx.send(embed=_v10_embed("⭐ Reputación", "No puedes darte rep a ti mismo. El espejo no cuenta como testigo.", ctx=ctx, color=V10_RED))
        return
    rep_diario = cargar_reputacion_diaria()
    key = f"{ctx.guild.id if ctx.guild else 'dm'}:{ctx.author.id}"
    hoy = _v10_today()
    if rep_diario.get(key) == hoy:
        await ctx.send(embed=_v10_embed("⭐ Reputación diaria", "Ya diste reputación hoy. Vuelve mañana para soltar otra chispa social.", ctx=ctx, color=V10_GOLD))
        return
    datos = cargar_datos()
    giver = str(ctx.author.id)
    target = str(miembro.id)
    asegurar_usuario(datos, giver)
    asegurar_usuario(datos, target)
    giver_rep = int(datos[giver].get("reputacion", 0) or 0)
    bonus = 1 if giver_rep >= 100 else 0
    gain = 1 + bonus
    datos[target]["reputacion"] = int(datos[target].get("reputacion", 0) or 0) + gain
    _v10_add_xp(datos, giver, 12)
    _v10_add_xp(datos, target, 18)
    rep_diario[key] = hoy
    _guardar_reputacion_diaria(rep_diario)
    _progresar_mision(str(ctx.author.id), "rep_dado", 1)
    guardar_datos(datos)
    total = datos[target]["reputacion"]
    tier = _v10_rep_tier(total)
    embed = _v10_embed(
        "⭐ Reputación enviada",
        f"{ctx.author.mention} dio **+{gain} rep** a {miembro.mention}.\nAhora tiene **{total} rep** y está en tier **{tier[1]}**.",
        ctx=ctx,
        color=V10_GOLD,
    )
    embed.add_field(name="Bonus", value="+1 extra porque tienes 100+ rep." if bonus else "Sin bonus extra. A 100 rep empiezas a potenciar tus votos.", inline=False)
    await ctx.send(embed=embed)


