@commands.cooldown(1, 8, commands.BucketType.user)
async def toprep_cmd_v10(ctx):
    """Ranking de reputación del servidor."""
    datos = cargar_datos()
    rows = []
    for uid, info in datos.items():
        if not isinstance(info, dict):
            continue
        rep = int(info.get("reputacion", 0) or 0)
        if rep <= 0:
            continue
        member = ctx.guild.get_member(int(uid)) if ctx.guild and str(uid).isdigit() else None
        name = member.display_name if member else f"Usuario {uid}"
        rows.append((rep, name))
    rows.sort(reverse=True)
    embed = _v10_embed("🏆 Ranking de reputación", "Los usuarios con más confianza social del servidor.", ctx=ctx, color=V10_GOLD)
    if not rows:
        embed.add_field(name="Sin datos", value="Todavía no hay reputación registrada.", inline=False)
    else:
        lines = []
        medals = ["🥇", "🥈", "🥉"]
        for i, (rep, name) in enumerate(rows[:10], start=1):
            medal = medals[i - 1] if i <= 3 else f"`#{i}`"
            tier = _v10_rep_tier(rep)[1]
            lines.append(f"{medal} **{name}** · `{rep}` rep · {tier}")
        embed.add_field(name="Top social", value="\n".join(lines), inline=False)
    await ctx.send(embed=embed)


