def _v10_wrap_text(draw, text: str, font, max_width: int):
    words = str(text or "").split()
    lines = []
    current = ""
    for word in words:
        test = f"{current} {word}".strip()
        try:
            w = draw.textbbox((0, 0), test, font=font)[2]
        except Exception:
            w = len(test) * 12
        if w <= max_width or not current:
            current = test
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines[:4]


def _v10_meme_font(size: int):
    if not ImageFont:
        return None
    for fp in [
        "/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Bold.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
    ]:
        try:
            return ImageFont.truetype(fp, size)
        except Exception:
            pass
    return ImageFont.load_default()


def _v10_draw_centered_text(draw, y: int, text: str, font, width: int, fill=(255, 255, 255), stroke=(0, 0, 0)):
    lines = _v10_wrap_text(draw, text.upper(), font, width - 80)
    line_h = 48
    for line in lines:
        bbox = draw.textbbox((0, 0), line, font=font)
        x = (width - (bbox[2] - bbox[0])) // 2
        draw.text((x, y), line, font=font, fill=fill, stroke_width=4, stroke_fill=stroke)
        y += line_h


async def _v10_make_meme_file(ctx, top: str, bottom: str = ""):
    if not Image or not ImageDraw:
        return None
    W, H = 960, 720
    img = Image.new("RGB", (W, H), (18, 10, 35))
    draw = ImageDraw.Draw(img)
    # Fondo tipo cartel neón.
    for y in range(H):
        t = y / max(1, H - 1)
        r = int(18 * (1 - t) + 80 * t)
        g = int(10 * (1 - t) + 20 * t)
        b = int(35 * (1 - t) + 130 * t)
        draw.line((0, y, W, y), fill=(r, g, b))
    for i in range(16):
        x = (i * 127) % W
        y = (i * 73) % H
        draw.ellipse((x - 90, y - 90, x + 90, y + 90), outline=(168, 85, 247), width=2)
    # Panel central.
    draw.rounded_rectangle((55, 95, W - 55, H - 95), radius=40, fill=(9, 7, 22), outline=(216, 180, 254), width=4)
    try:
        avatar_bytes = await ctx.author.display_avatar.replace(size=256, static_format="png").read()
        av = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA").resize((190, 190))
        mask = Image.new("L", (190, 190), 0)
        ImageDraw.Draw(mask).ellipse((0, 0, 189, 189), fill=255)
        img.paste(av, (385, 255), mask)
        draw.ellipse((375, 245, 585, 455), outline=(250, 204, 21), width=6)
    except Exception:
        draw.ellipse((385, 255, 575, 445), fill=(88, 28, 135), outline=(250, 204, 21), width=6)
        draw.text((430, 320), "MEME", font=_v10_meme_font(42), fill=(255, 255, 255))
    font = _v10_meme_font(44)
    _v10_draw_centered_text(draw, 130, top or "CUANDO EL BOT COMPILA", font, W)
    _v10_draw_centered_text(draw, 560, bottom or "PERO SALE UN ERROR NUEVO", font, W)
    draw.text((32, H - 42), f"X AETHER MEME LAB · {ctx.author.display_name}", font=_v10_meme_font(22), fill=(216, 180, 254))
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return discord.File(buf, filename=f"meme_{ctx.author.id}.png")


@bot.command(name="meme", aliases=["memes", "memegen"])
@commands.cooldown(1, 8, commands.BucketType.user)
async def meme_cmd_v10(ctx, *, texto: str = None):
    """Genera un meme local. Uso: !meme texto superior | texto inferior"""
    ejemplos = [
        ("CUANDO ARREGLAS UN BUG", "Y APARECEN 7 MINIJUEGOS NUEVOS"),
        ("YO: SOLO UNA MEJORA MÁS", "EL APP.PY: 700KB Y SUBIENDO"),
        ("EL BOT CON DECORACIÓN", "EL SERVIDOR ENTRA EN MODO PREMIUM"),
        ("CUANDO ALGUIEN DA !REP", "Y DESBLOQUEA AURA SOCIAL"),
    ]
    if texto and "|" in texto:
        top, bottom = [p.strip() for p in texto.split("|", 1)]
    elif texto:
        top, bottom = texto.strip(), random.choice(["NO ERA UN BUG, ERA UNA FEATURE", "X AETHER ULTRA LO HACE MÁS MORADO", "COMPILA Y BRILLA", "NEÓN ACTIVADO"])
    else:
        top, bottom = random.choice(ejemplos)
    f = await _v10_make_meme_file(ctx, top, bottom)
    embed = _v10_embed("🖼️ Meme generado", "Meme creado localmente, sin depender de Reddit. Usa `!meme texto arriba | texto abajo`.", ctx=ctx, color=V10_PINK)
    if f:
        embed.set_image(url=f"attachment://{f.filename}")
        await ctx.send(embed=embed, file=f)
    else:
        embed.add_field(name=top, value=bottom or " ", inline=False)
        await ctx.send(embed=embed)


