def _v10_stats_embed(ctx, member: discord.Member):
    datos = cargar_datos()
    uid = str(member.id)
    asegurar_usuario(datos, uid)
    stats = datos[uid].get("game_stats", {}) if isinstance(datos[uid].get("game_stats", {}), dict) else {}
    embed = _v10_embed(f"📊 Estadísticas de juegos · {member.display_name}", "Rachas, victorias y balance neto.", ctx=ctx, color=V10_GOLD)
    embed.set_thumbnail(url=member.display_avatar.url)
    if not stats:
        embed.add_field(name="Sin partidas", value="Juega con `!minijuegos` para llenar esta vitrina.", inline=False)
        return embed
    lines = []
    for game, st in sorted(stats.items(), key=lambda kv: int(kv[1].get("jugadas", 0) or 0), reverse=True)[:12]:
        played = int(st.get("jugadas", 0) or 0)
        wins = int(st.get("ganadas", 0) or 0)
        wr = int((wins / played) * 100) if played else 0
        net = int(st.get("neto", 0) or 0)
        lines.append(f"**{game.replace('_',' ').title()}** · `{played}` partidas · `{wr}%` win · racha `{st.get('racha',0)}` · neto `{net:,}`".replace(",", "."))
    embed.add_field(name="🎮 Resumen", value="\n".join(lines)[:1024], inline=False)
    return embed


class V10ReplayView(discord.ui.View):
    def __init__(self, ctx, callback, *args):
        super().__init__(timeout=50)
        self.ctx = ctx
        self.callback = callback
        self.args = args

    @discord.ui.button(label="🔁 Otra vez", style=discord.ButtonStyle.blurple)
    async def again(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Este botón pertenece a otra partida.", ephemeral=True)
            return
        await interaction.response.defer()
        await self.callback(self.ctx, *self.args)

    @discord.ui.button(label="🎮 Game Hub", style=discord.ButtonStyle.secondary)
    async def hub(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Abre tu propio `!minijuegos`.", ephemeral=True)
            return
        await interaction.response.edit_message(embed=_v10_minigames_embed(self.ctx), view=V10MiniGamesView(self.ctx))


