async def _v10_play_apostar(ctx, cantidad: str, eleccion: str):
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    apuesta, error = _v10_parse_bet(datos, uid, cantidad, min_bet=5)
