async def _v10_play_slots(ctx, cantidad: str):
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    apuesta, error = _v10_parse_bet(datos, uid, cantidad, min_bet=10)
    if error:
        await ctx.send(embed=_v10_embed("🎰 Slots", f"❌ {error}", ctx=ctx, color=V10_RED)); return
    restar_de_cash(datos, uid, apuesta)
    symbols = ["🍒", "🍋", "🍊", "🍇", "🔔", "⭐", "💎", "👑", "🐉"]
    weights = [26, 22, 18, 13, 8, 5, 3, 2, 1]
    msg = await ctx.send(embed=_v10_embed("🎰 Slots Prisma", f"Apuesta: **{_v10_money(apuesta)}**\n`◇ | ◇ | ◇`", ctx=ctx, color=V10_GOLD))
    reels = ["◇", "◇", "◇"]
    for i in range(5):
        reels = random.choices(symbols, weights=weights, k=3)
        await msg.edit(embed=_v10_embed("🎰 Slots Prisma", f"# {' | '.join(reels)}\n{_v10_bar((i+1)/5, 18)}", ctx=ctx, color=V10_GOLD))
        await asyncio.sleep(0.22)
    reels = random.choices(symbols, weights=weights, k=3)
    counts = {s: reels.count(s) for s in set(reels)}
    triple_mult = {"🍒": 5, "🍋": 6, "🍊": 7, "🍇": 9, "🔔": 12, "⭐": 16, "💎": 25, "👑": 40, "🐉": 60}
    premio = 0
    rule = "Sin combinación"
    if len(counts) == 1:
        premio = apuesta * triple_mult.get(reels[0], 5)
        rule = f"Triple {reels[0]}"
    elif max(counts.values()) == 2:
        pair = max(counts, key=counts.get)
        premio = apuesta * (3 if pair in ("💎", "👑", "🐉") else 2)
        rule = f"Pareja {pair}"
    elif set(reels) == {"⭐", "💎", "👑"}:
        premio = apuesta * 12
        rule = "Escalera premium"
    if premio:
        mult = max(obtener_multiplicador(datos, uid, "slots"), obtener_multiplicador(datos, uid, "tragaperras"))
        premio = int(premio * mult)
        agregar_a_cash_y_monedas(datos, uid, premio)
        net = premio - apuesta
        won = True
        color = V10_GREEN
        title = "🎰 Slots Prisma · Premio"
        desc = f"# {' | '.join(reels)}\n**{rule}**\nGanaste **+{_v10_money(net)} neto**."
    else:
        net = -apuesta
        won = False
        color = V10_RED
        title = "🎰 Slots Prisma · Vacío"
        desc = f"# {' | '.join(reels)}\nPerdiste **{_v10_money(apuesta)}**."
    _v10_record_game(datos, uid, "slots", won, net, 10)
    guardar_datos(datos)
