V11_STREAMS_VERSION = "X AETHER ULTRA 3.1.0 · Streams Públicos Premium"
V11_STREAMS_MAX_PER_MEMBER = 5
V11_STREAMS_PAGE_SIZE = 8
V11_STREAMS_TOPIC_MARK = "X AETHER ULTRA_STREAMS_PUBLICOS_V11"
V11_STREAMS_PLATFORMS = {
    "youtube": {"emoji": "📺", "color": 0xFF0033, "label": "YouTube", "env": ["YOUTUBE_API_KEY"]},
    "twitch": {"emoji": "🟣", "color": 0x9146FF, "label": "Twitch", "env": ["TWITCH_CLIENT_ID", "TWITCH_TOKEN"]},
    "tiktok": {"emoji": "🎵", "color": 0x00F2EA, "label": "TikTok", "env": []},
    "kick": {"emoji": "🟢", "color": 0x53FC18, "label": "Kick", "env": []},
}
V11_STREAMS_ALIASES = {
    "yt": "youtube", "youtube": "youtube", "youtu": "youtube",
    "ttv": "twitch", "tw": "twitch", "twitch": "twitch",
    "tt": "tiktok", "tik": "tiktok", "tok": "tiktok", "tiktok": "tiktok",
    "kick": "kick", "k": "kick",
}


def _v11_stream_colour(platform):
    return discord.Color(V11_STREAMS_PLATFORMS.get(platform, {}).get("color", 0x8B5CF6))


def _v11_stream_platform_label(platform):
    meta = V11_STREAMS_PLATFORMS.get(platform, {})
    return f"{meta.get('emoji', '🔴')} {meta.get('label', str(platform).title())}"


def _v11_stream_now():
    return discord.utils.utcnow().replace(microsecond=0).isoformat()


def _v11_stream_load():
    try:
        if os.path.exists(STREAMS_DATA_FILE):
            with open(STREAMS_DATA_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data if isinstance(data, dict) else {}
    except Exception as exc:
        print(f"[STREAMS 3.1.0] Error cargando datos: {exc}")
    return {}


def _v11_stream_save(data):
    try:
        with open(STREAMS_DATA_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=4)
    except Exception as exc:
        print(f"[STREAMS 3.1.0] Error guardando datos: {exc}")


def _v11_normalize_platform(platform):
    return V11_STREAMS_ALIASES.get(str(platform or "").strip().lower())


def _v11_clean_identifier(platform, identifier):
    ident = str(identifier or "").strip().strip("/").split("?")[0].strip()
    if platform in {"twitch", "tiktok", "kick"}:
        ident = ident.replace("@", "").split("/")[0].lower()
    elif platform == "youtube":
        if "/channel/" in ident:
            ident = ident.split("/channel/", 1)[-1].split("/")[0]
        elif "@" in ident:
            ident = "@" + ident.split("@", 1)[-1].split("/")[0]
        elif ident and not ident.startswith("@") and not ident.startswith("UC") and "/" not in ident:
            ident = "@" + ident
    return ident


def _v11_canonical_url(platform, identifier):
    ident = _v11_clean_identifier(platform, identifier)
    if platform == "twitch":
        return f"https://www.twitch.tv/{ident}"
    if platform == "tiktok":
        return f"https://www.tiktok.com/@{ident.replace('@', '')}"
    if platform == "kick":
        return f"https://kick.com/{ident}"
    if platform == "youtube":
        if ident.startswith("UC"):
            return f"https://www.youtube.com/channel/{ident}"
        return f"https://www.youtube.com/{ident}"
    return str(identifier)


def _v11_parse_stream_input(platform_arg=None, account_arg=""):
    raw_first = str(platform_arg or "").strip()
    raw_account = str(account_arg or "").strip()
    if not raw_first:
        return None, None, None, "Uso: `!addstream <youtube|twitch|tiktok|kick> <usuario o URL>` o `!addstream <URL>`."
    forced = _v11_normalize_platform(raw_first)
    raw = raw_account if forced and raw_account else raw_first
    lower = raw.lower()
    platform = forced
    identifier = raw
    if "twitch.tv/" in lower:
        platform = "twitch"; identifier = raw.split("twitch.tv/", 1)[-1].split("?")[0].split("/")[0]
    elif "tiktok.com/" in lower:
        platform = "tiktok"; identifier = raw.split("@", 1)[-1].split("?")[0].split("/")[0] if "@" in raw else raw.split("tiktok.com/", 1)[-1].split("?")[0].split("/")[0]
    elif "kick.com/" in lower:
        platform = "kick"; identifier = raw.split("kick.com/", 1)[-1].split("?")[0].split("/")[0]
    elif "youtube.com/" in lower or "youtu.be/" in lower:
        platform = "youtube"
        if "/channel/" in lower:
            identifier = raw.split("/channel/", 1)[-1].split("?")[0].split("/")[0]
        elif "@" in raw:
            identifier = "@" + raw.split("@", 1)[-1].split("?")[0].split("/")[0]
        elif "youtu.be/" in lower:
            identifier = raw.split("youtu.be/", 1)[-1].split("?")[0].split("/")[0]
        else:
            identifier = raw.rstrip("/").split("/")[-1].split("?")[0]
    elif not platform:
        return None, None, None, "No detecté la plataforma. Usa `youtube`, `twitch`, `tiktok`, `kick` o pega una URL completa."
    if platform not in V11_STREAMS_PLATFORMS:
        return None, None, None, "Plataforma no válida. Usa `youtube`, `twitch`, `tiktok` o `kick`."
    identifier = _v11_clean_identifier(platform, identifier)
    if not identifier or identifier in {"@", "https:", "http:"}:
        return None, None, None, "No pude detectar usuario/canal. Ejemplo: `!addstream twitch markelson`."
    return platform, identifier, _v11_canonical_url(platform, identifier), None


def _v11_normalize_stream_entry(entry):
    if not isinstance(entry, dict):
        return None
    platform = entry.get("platform") or entry.get("plataforma") or entry.get("plataform")
    identifier = entry.get("identifier") or entry.get("usuario") or entry.get("user") or entry.get("cuenta")
    platform = _v11_normalize_platform(platform) or str(platform or "").lower().strip()
    if platform not in V11_STREAMS_PLATFORMS or not identifier:
        return None
    identifier = _v11_clean_identifier(platform, identifier)
    return {
        "platform": platform,
        "identifier": identifier,
        "url": entry.get("url") or _v11_canonical_url(platform, identifier),
        "message": str(entry.get("message") or entry.get("mensaje") or "").strip()[:220],
        "registered_at": entry.get("registered_at") or _v11_stream_now(),
        "last_live": entry.get("last_live"),
        "times_detected": int(entry.get("times_detected", 0) or 0),
    }


def _v11_get_guild_streams(data, guild_id):
    gid = str(guild_id)
    if gid in data and isinstance(data[gid], dict):
        return data[gid]
    guild_data = {}
    legacy_keys = []
    for key, value in list(data.items()):
        if str(key).isdigit() and isinstance(value, list):
            migrated = [_v11_normalize_stream_entry(x) for x in value]
            migrated = [x for x in migrated if x]
            if migrated:
                guild_data[str(key)] = migrated
                legacy_keys.append(key)
    data[gid] = guild_data
    for key in legacy_keys:
        data.pop(key, None)
    return guild_data


def _v11_member_role(guild):
    if not guild:
        return None
    role = guild.get_role(ROLE_MIEMBRO)
    if role:
        return role
    for role in guild.roles:
        name = role.name.lower().strip()
        if name in {"miembro", "miembros", "member", "members"} or "miembro" in name or "member" in name:
            return role
    return None


def _v11_can_register_stream(member):
    if member.bot:
        return False, "Los bots no pueden registrar streams."
    if member.guild_permissions.administrator:
        return True, "Acceso admin."
    role = _v11_member_role(member.guild)
    if role and role in member.roles:
        return True, f"Rol detectado: {role.name}"
    if role:
        return False, f"Necesitas el rol **{role.name}** para registrar streams."
    return True, "No encontré el rol configurado; modo público para miembros reales activado."


def _v11_stream_api_status_lines():
    lines = []
    for platform, meta in V11_STREAMS_PLATFORMS.items():
        envs = meta.get("env") or []
        if not envs:
            detail = "registro público + enlace directo"
            if platform == "kick": detail += " + endpoint público experimental"
            if platform == "tiktok": detail += "; TikTok no tiene API pública estable"
            lines.append(f"{meta['emoji']} **{meta['label']}** · {detail}")
            continue
        configured = all(bool(os.getenv(x)) for x in envs)
        badge = "✅ API configurada" if configured else "⚠️ falta configurar API"
        lines.append(f"{meta['emoji']} **{meta['label']}** · {badge} · `{', '.join(envs)}`")
    return lines


def _v11_stream_card(entry, index=None):
    platform = entry.get("platform", "unknown")
    ident = entry.get("identifier", "?")
    url = entry.get("url") or _v11_canonical_url(platform, ident)
    prefix = f"`#{index}` · " if index else ""
    msg = f"\n> {entry.get('message')}" if entry.get("message") else ""
    return f"{prefix}{_v11_stream_platform_label(platform)} · [`{ident}`]({url}){msg}"


async def _v11_check_youtube_stream(session, identifier):
    url = _v11_canonical_url("youtube", identifier)
    api_key = os.getenv("YOUTUBE_API_KEY", "").strip()
    if api_key and str(identifier).startswith("UC"):
        try:
            params = {"part": "snippet", "channelId": identifier, "eventType": "live", "type": "video", "key": api_key, "maxResults": 1}
            async with session.get("https://www.googleapis.com/youtube/v3/search", params=params, timeout=aiohttp.ClientTimeout(total=12)) as response:
                if response.status == 200:
                    data = await response.json(); items = data.get("items") or []
                    if items:
                        item = items[0]; snippet = item.get("snippet", {}); video_id = item.get("id", {}).get("videoId")
                        thumb = (((snippet.get("thumbnails") or {}).get("high") or {}).get("url"))
                        return {"live": True, "title": snippet.get("title") or "YouTube Live", "url": f"https://www.youtube.com/watch?v={video_id}" if video_id else url, "thumbnail": thumb, "source": "YouTube Data API"}
        except Exception as exc:
            print(f"[STREAMS 3.1.0] YouTube API error: {exc}")
    return {"live": False, "title": "YouTube", "url": url, "source": "link-only"}


async def _v11_check_twitch_stream(session, username):
    url = _v11_canonical_url("twitch", username)
    client_id = os.getenv("TWITCH_CLIENT_ID", "").strip(); token = os.getenv("TWITCH_TOKEN", "").strip()
    if not client_id or not token:
        return {"live": False, "title": "Twitch", "url": url, "source": "missing-api"}
    headers = {"Client-ID": client_id, "Authorization": f"Bearer {token}"}
    try:
        async with session.get(f"https://api.twitch.tv/helix/streams?user_login={username}", headers=headers, timeout=aiohttp.ClientTimeout(total=12)) as response:
            if response.status == 200:
                data = await response.json(); streams = data.get("data") or []
                if streams:
                    s = streams[0]
                    return {"live": True, "title": s.get("title") or "Twitch Live", "url": url, "thumbnail": (s.get("thumbnail_url") or "").format(width=1280, height=720), "viewers": s.get("viewer_count"), "game": s.get("game_name"), "source": "Twitch Helix API"}
            return {"live": False, "title": "Twitch", "url": url, "source": f"api-{response.status}"}
    except Exception as exc:
        print(f"[STREAMS 3.1.0] Twitch API error: {exc}")
        return {"live": False, "title": "Twitch", "url": url, "source": "api-error"}


async def _v11_check_tiktok_stream(session, username):
    return {"live": False, "title": "TikTok Live", "url": _v11_canonical_url("tiktok", username), "source": "link-only"}


async def _v11_check_kick_stream(session, username):
    url = _v11_canonical_url("kick", username)
    try:
        async with session.get(f"https://kick.com/api/v2/channels/{username}", timeout=aiohttp.ClientTimeout(total=12)) as response:
            if response.status == 200:
                data = await response.json(); live = data.get("livestream") or {}
                if live:
                    thumb = live.get("thumbnail")
                    if isinstance(thumb, dict): thumb = thumb.get("url")
                    return {"live": True, "title": live.get("session_title") or live.get("title") or "Kick Live", "url": url, "thumbnail": thumb, "viewers": live.get("viewer_count"), "source": "Kick public endpoint"}
            return {"live": False, "title": "Kick", "url": url, "source": f"kick-{response.status}"}
    except Exception as exc:
        print(f"[STREAMS 3.1.0] Kick check error: {exc}")
        return {"live": False, "title": "Kick", "url": url, "source": "api-error"}


async def check_stream_status(platform, identifier):
    async with aiohttp.ClientSession(headers={"User-Agent": "X AETHER ULTRA-Streams-3.1.0/1.0"}) as session:
        platform = _v11_normalize_platform(platform) or platform
        if platform == "youtube": return await _v11_check_youtube_stream(session, identifier)
        if platform == "twitch": return await _v11_check_twitch_stream(session, identifier)
        if platform == "tiktok": return await _v11_check_tiktok_stream(session, identifier)
        if platform == "kick": return await _v11_check_kick_stream(session, identifier)
        return {"live": False, "url": str(identifier), "source": "unknown"}


def create_stream_embed(member, platform, stream_data):
    platform = _v11_normalize_platform(platform) or str(platform).lower()
    title = stream_data.get("title") or "Stream en vivo"; url = stream_data.get("url") or "#"
    embed = discord.Embed(
        title=f"{_v11_stream_platform_label(platform)} · {member.display_name} está EN VIVO",
        description=(f"## 🔴 {title}\n╭─────────────── · · · ───────────────╮\n**Creador:** {member.mention}\n**Plataforma:** {_v11_stream_platform_label(platform)}\n**Estado:** directo detectado automáticamente\n╰─────────────── · · · ───────────────╯"),
        color=_v11_stream_colour(platform), url=url, timestamp=discord.utils.utcnow())
    try:
        embed.set_author(name=member.display_name, icon_url=member.display_avatar.url); embed.set_thumbnail(url=member.display_avatar.url)
    except Exception:
        pass
    if stream_data.get("game"): embed.add_field(name="🎮 Categoría/Juego", value=str(stream_data.get("game"))[:1024], inline=True)
    if stream_data.get("viewers"): embed.add_field(name="👀 Espectadores", value=str(stream_data.get("viewers")), inline=True)
    if stream_data.get("source"): embed.add_field(name="📡 Fuente", value=str(stream_data.get("source")), inline=True)
    embed.add_field(name="🔗 Enlace directo", value=f"[Abrir directo]({url})", inline=False)
    if stream_data.get("thumbnail"): embed.set_image(url=stream_data.get("thumbnail"))
    embed.set_footer(text=f"{V11_STREAMS_VERSION} · Usa !streams para ver creadores registrados")
    return embed


async def setup_streams_system(guild):
    global STREAMS_CHANNEL_ID
    try:
        channel = discord.utils.get(guild.text_channels, name=STREAMS_CHANNEL_NAME)
        if not channel:
            overwrites = {guild.default_role: discord.PermissionOverwrite(view_channel=True, send_messages=False, read_message_history=True, add_reactions=True)}
            if guild.me:
                overwrites[guild.me] = discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_messages=True, read_message_history=True)
            member_role = _v11_member_role(guild)
            if member_role:
                overwrites[member_role] = discord.PermissionOverwrite(view_channel=True, send_messages=False, read_message_history=True, add_reactions=True)
            channel = await guild.create_text_channel(name=STREAMS_CHANNEL_NAME, overwrites=overwrites, reason="X AETHER ULTRA 3.1.0: canal público de streams")
        STREAMS_CHANNEL_ID = channel.id
        try:
            await channel.edit(topic=f"{V11_STREAMS_TOPIC_MARK} · registro público con !addstream", reason="Actualizar topic Streams 3.1.0")
            await channel.set_permissions(guild.default_role, view_channel=True, send_messages=False, read_message_history=True, add_reactions=True)
            member_role = _v11_member_role(guild)
            if member_role:
                await channel.set_permissions(member_role, view_channel=True, send_messages=False, read_message_history=True, add_reactions=True)
        except Exception as exc:
            print(f"[STREAMS 3.1.0] Permisos/topic: {exc}")
        print(f"✅ {V11_STREAMS_VERSION}: canal listo en {guild.name} -> {channel.name}")
        return True
    except Exception as exc:
        print(f"❌ [STREAMS 3.1.0] Error configurando canal: {exc}")
        return False


@tasks.loop(seconds=STREAMS_LOOP_INTERVAL)
async def check_streams_loop():
    data = _v11_stream_load(); changed = False
    for guild in bot.guilds:
        channel = guild.get_channel(STREAMS_CHANNEL_ID) if STREAMS_CHANNEL_ID else None
        if not channel: channel = discord.utils.get(guild.text_channels, name=STREAMS_CHANNEL_NAME)
        if not channel: continue
        guild_data = _v11_get_guild_streams(data, guild.id)
        for user_id, entries in list(guild_data.items()):
            if not str(user_id).isdigit() or not isinstance(entries, list): continue
            member = guild.get_member(int(user_id))
            if not member: continue
            can_register, _reason = _v11_can_register_stream(member)
            if not can_register: continue
            for idx, entry in enumerate(list(entries)):
                normalized = _v11_normalize_stream_entry(entry)
                if not normalized: continue
                platform = normalized["platform"]; identifier = normalized["identifier"]
                stream_key = f"{guild.id}:{user_id}:{platform}:{identifier}"
                stream_data = await check_stream_status(platform, identifier)
                if stream_data.get("live") and stream_key not in active_streams:
                    embed = create_stream_embed(member, platform, stream_data)
                    if normalized.get("message"):
                        embed.insert_field_at(0, name="💬 Mensaje del creador", value=normalized["message"], inline=False)
                    ping_role = _v11_member_role(guild); ping = ping_role.mention if ping_role else "@here"
                    try:
                        msg = await channel.send(content=f"🎉 **¡NUEVO DIRECTO!** {member.mention} está en vivo · {ping}", embed=embed)
                        active_streams[stream_key] = {"message_id": msg.id, "start_time": _v11_stream_now()}; stream_notifications[stream_key] = msg.id
                        normalized["last_live"] = _v11_stream_now(); normalized["times_detected"] = int(normalized.get("times_detected", 0) or 0) + 1
                        entries[idx] = normalized; changed = True
                    except Exception as exc:
                        print(f"[STREAMS 3.1.0] Error enviando aviso: {exc}")
                elif not stream_data.get("live") and stream_key in active_streams:
                    active_streams.pop(stream_key, None)
    if changed: _v11_stream_save(data)


for _cmd_name in ["addstream", "mystreams", "delstream", "streams", "teststream", "registrarstream", "streamadd", "streamregistrar", "misstreams", "streamlist", "creadores"]:
    try: bot.remove_command(_cmd_name)
    except Exception: pass


class V11StreamsPageView(discord.ui.View):
    def __init__(self, ctx, pages):
        super().__init__(timeout=90); self.ctx = ctx; self.pages = pages; self.index = 0; self._sync()
    def _sync(self):
        self.prev_page.disabled = self.index <= 0; self.next_page.disabled = self.index >= len(self.pages) - 1
    async def _guard(self, interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("🔒 Este panel pertenece a quien ejecutó el comando.", ephemeral=True); return False
        return True
    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary)
    async def prev_page(self, interaction, button):
        if not await self._guard(interaction): return
        self.index = max(0, self.index - 1); self._sync(); await interaction.response.edit_message(embed=self.pages[self.index], view=self)
    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary)
    async def next_page(self, interaction, button):
        if not await self._guard(interaction): return
        self.index = min(len(self.pages) - 1, self.index + 1); self._sync(); await interaction.response.edit_message(embed=self.pages[self.index], view=self)
    @discord.ui.button(label="Guía", emoji="🧭", style=discord.ButtonStyle.primary)
    async def guide(self, interaction, button):
        if not await self._guard(interaction): return
        await interaction.response.send_message(embed=_v11_streamguide_embed(interaction.guild), ephemeral=True)


def _v11_streamguide_embed(guild=None):
    role = _v11_member_role(guild) if guild else None; role_txt = role.mention if role else "Miembro del servidor"
    embed = discord.Embed(title="🧭 Guía de Streams Públicos", description=("## Registro de creadores sin líos\n" f"Cualquier usuario con acceso de **{role_txt}** puede añadir sus cuentas.\n\n" "`!addstream twitch usuario`\n`!addstream youtube @canal`\n`!addstream tiktok @usuario`\n`!addstream kick usuario`\n`!addstream https://www.twitch.tv/usuario`\n\n" "Personaliza tu aviso con `!streammsg <número> <mensaje>`."), color=discord.Color(0x8B5CF6))
    embed.add_field(name="📦 Límite", value=f"Hasta **{V11_STREAMS_MAX_PER_MEMBER}** cuentas por miembro.", inline=True)
    embed.add_field(name="🔄 Revisión", value=f"Cada **{STREAMS_LOOP_INTERVAL} segundos** aproximadamente.", inline=True)
    embed.add_field(name="📡 APIs", value="`!streamapi` muestra qué plataformas tienen API configurada.", inline=False)
    embed.set_footer(text=f"{V11_STREAMS_VERSION} · registro público, canal limpio, avisos premium")
    return embed


