@bot.command(name="streamscan", aliases=["scanstreams"])
@commands.guild_only()
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def streamscan_cmd_v11(ctx):
    data = _v11_stream_load(); guild_data = _v11_get_guild_streams(data, ctx.guild.id); report = []
    await ctx.trigger_typing()
    for uid, entries in guild_data.items():
        if not str(uid).isdigit() or not isinstance(entries, list): continue
        member = ctx.guild.get_member(int(uid)); name = member.display_name if member else uid
        for entry in entries[:V11_STREAMS_MAX_PER_MEMBER]:
            entry = _v11_normalize_stream_entry(entry)
            if not entry: continue
            status = await check_stream_status(entry["platform"], entry["identifier"]); icon = "🔴" if status.get("live") else "⚫"
            report.append(f"{icon} **{name}** · {_v11_stream_platform_label(entry['platform'])} · `{entry['identifier']}` · {status.get('source', 'desconocido')}")
    embed = discord.Embed(title="🧪 Escaneo manual de streams", color=discord.Color(0x8B5CF6)); embed.description = "\n".join(report[:25]) if report else "No hay streams registrados."
    embed.set_footer(text=f"{V11_STREAMS_VERSION} · resultados limitados a 25 líneas"); await ctx.send(embed=embed)


