def _v12_bootstrap_shop_items():
    """Añade precio_base y nivel mínimo inteligente a todos los objetos existentes."""
    rarity_level = {"común": 1, "normal": 1, "raro": 5, "épico": 10, "legendario": 22, "mítico": 40}
    category_level = {
        "boost": 2, "proteccion": 3, "jugable": 1, "social": 1, "utilidad": 4,
        "cosmetico": 5, "decoracion": 7, "perfil": 8, "fondo": 8, "mascota": 10,
        "titulo": 8, "nivel": 1, "reputacion": 8, "especial": 6, "coleccion": 5,
    }
    for item_id, item in list(TIENDA_ITEMS.items()):
        if not isinstance(item, dict):
            continue
        item.setdefault("precio_base", int(item.get("precio", 0) or 0))
        item.setdefault("rareza", "normal")
        item.setdefault("emoji", "💎")
        item.setdefault("categoria", "otros")
        item.setdefault("tipo", item_id)
        item.setdefault("duracion_dias", 0)
        base_level = max(category_level.get(str(item.get("categoria", "otros")).lower(), 1), rarity_level.get(str(item.get("rareza", "normal")).lower(), 1))
        item.setdefault("nivel_min", base_level)
        if str(item.get("categoria", "")).lower() in {"fondo", "nivel", "mascota", "titulo", "perfil", "reputacion", "decoracion", "cosmetico"}:
            if "slot" not in item:
                tipo = str(item.get("tipo", item_id))
                if "fondo_lvl" in tipo or item.get("level_style"):
                    item["slot"] = "lvl_fondo"
                elif "marco_lvl" in tipo:
                    item["slot"] = "lvl_marco"
                elif "mascota" in tipo:
                    item["slot"] = "mascota"
                elif "titulo" in tipo:
                    item["slot"] = "titulo"
                elif "placa" in tipo or "badge" in tipo:
                    item["slot"] = "placa"
                elif "firma" in tipo:
                    item["slot"] = "firma"
                elif "fondo" in tipo:
                    item["slot"] = "fondo"


_v12_bootstrap_shop_items()


