def _v12_money(n: int) -> str:
    return f"{int(n):,}".replace(",", ".")


def _v12_level_of(info: dict) -> int:
    try:
        return max(1, int(info.get("nivel", 1) or 1))
    except Exception:
        return 1


def _v12_xp_needed(level: int) -> int:
    try:
        return max(100, _xp_needed_for_level(int(level)))
    except Exception:
        return max(100, 100 + (int(level) - 1) * 50)


def _v12_progress_bar(value: int, maximum: int, size: int = 18, fill: str = "▰", empty: str = "▱") -> str:
    maximum = max(1, int(maximum or 1))
    value = max(0, min(int(value or 0), maximum))
    done = min(size, int(round((value / maximum) * size)))
    return fill * done + empty * (size - done)


def _v12_rarity(item: dict) -> str:
    return str(item.get("rareza", "normal")).lower()


def _v12_rarity_emoji(item: dict) -> str:
    return {
        "común": "⚪", "normal": "⚪", "raro": "🔵", "épico": "🟣",
        "legendario": "🟡", "mítico": "🔴"
    }.get(_v12_rarity(item), "💎")


def _v12_rarity_color(item: dict):
    rarity = _v12_rarity(item)
    return {
        "común": discord.Color.light_grey(), "normal": discord.Color.light_grey(),
        "raro": discord.Color.blue(), "épico": discord.Color.purple(),
        "legendario": discord.Color.gold(), "mítico": discord.Color.red(),
    }.get(rarity, discord.Color(0x8B5CF6))


def _v12_item_key(query: str):
    q = str(query or "").strip().lower()
    if not q:
        return None, None
    if q in TIENDA_ITEMS:
        return q, TIENDA_ITEMS[q]
    for item_id, item in TIENDA_ITEMS.items():
        names = {item_id.lower(), str(item.get("tipo", "")).lower(), str(item.get("nombre", "")).lower()}
        if q in names:
            return item_id, item
    for item_id, item in TIENDA_ITEMS.items():
        if q in item_id.lower() or q in str(item.get("nombre", "")).lower():
            return item_id, item
    return None, None


def _v12_dynamic_price(item: dict, level: int) -> int:
    base = int(item.get("precio_base", item.get("precio", 0)) or 0)
    level = max(1, min(int(level or 1), V12_MAX_SHOP_PRICE_LEVEL))
    rarity_extra = {"común": 0, "normal": 0, "raro": 0.03, "épico": 0.06, "legendario": 0.10, "mítico": 0.16}.get(_v12_rarity(item), 0)
    scaled = base * (1 + (level - 1) * V12_SHOP_PRICE_GROWTH_PER_LEVEL + rarity_extra)
    return int(max(1, round(scaled / 10) * 10))


def _v12_min_level(item: dict) -> int:
    try:
        return max(1, int(item.get("nivel_min", 1) or 1))
    except Exception:
        return 1


def _v12_min_rep(item: dict) -> int:
    try:
        return max(0, int(item.get("rep_min", 0) or 0))
    except Exception:
        return 0


def _v12_inventory_key(item_id: str, item: dict) -> str:
    return str(item.get("tipo", item_id))


def _v12_has_item(info: dict, item_id: str, item: dict) -> bool:
    inv = info.get("items", {}) if isinstance(info.get("items", {}), dict) else {}
    key = _v12_inventory_key(item_id, item)
    return key in inv or item_id in inv


def _v12_item_record(info: dict, item_id: str, item: dict) -> dict:
    inv = info.get("items", {}) if isinstance(info.get("items", {}), dict) else {}
    key = _v12_inventory_key(item_id, item)
    rec = inv.get(key) or inv.get(item_id) or {}
    return rec if isinstance(rec, dict) else {}


def _v12_unlock_state(info: dict, item: dict) -> tuple[bool, str]:
    level = _v12_level_of(info)
    rep = int(info.get("reputacion", 0) or 0)
    if level < _v12_min_level(item):
        return False, f"requiere nivel {_v12_min_level(item)}"
    if rep < _v12_min_rep(item):
        return False, f"requiere {_v12_min_rep(item)} rep"
    return True, "desbloqueado"


def _v12_shop_line(item_id: str, item: dict, info: dict) -> str:
    lvl = _v12_level_of(info)
    price = _v12_dynamic_price(item, lvl)
    ok, reason = _v12_unlock_state(info, item)
    owned = _v12_has_item(info, item_id, item)
    marker = "✅" if owned else ("🟢" if ok else "🔒")
    slot = f" · slot `{item.get('slot')}`" if item.get("slot") else ""
    return (
        f"{marker} `{item_id}` · {item.get('emoji','💎')} **{item.get('nombre', item_id)}**\n"
        f"{_v12_rarity_emoji(item)} {item.get('rareza','normal')} · nivel {item.get('nivel_min',1)} · {_v12_money(price)} {amatista}{slot}\n"
        f"╰ {str(item.get('descripcion','Objeto de tienda')).strip()[:90]}{'...' if len(str(item.get('descripcion',''))) > 90 else ''}"
    )


def _v12_user_equipped(info: dict) -> dict:
    eq = info.get("equipado", {})
    if not isinstance(eq, dict):
        eq = {}
        info["equipado"] = eq
    return eq


def _v12_find_item_by_type(item_type: str):
    for item_id, item in TIENDA_ITEMS.items():
        if str(item.get("tipo", item_id)) == str(item_type) or item_id == item_type:
            return item_id, item
    return None, None


def _v12_embed(title: str, description: str = "", color=None, member: discord.Member = None) -> discord.Embed:
    embed = discord.Embed(title=title, description=description, color=color or discord.Color(0x8B5CF6), timestamp=datetime.datetime.utcnow())
    embed.set_footer(text=f"{V12_VERSION} · diseño amatista")
    if member:
        try:
            embed.set_thumbnail(url=member.display_avatar.url)
        except Exception:
            pass
    return embed


def _v12_load_game_stats() -> dict:
    try:
        if os.path.exists(V12_GAME_STATS_FILE):
            with open(V12_GAME_STATS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data if isinstance(data, dict) else {}
    except Exception:
        pass
    return {}


def _v12_save_game_stats(data: dict):
    try:
        with open(V12_GAME_STATS_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[3.1.0 GAME STATS] Error guardando: {e}")


def _v12_record_game(uid: int, game: str, won: bool, delta: int = 0):
    data = _v12_load_game_stats()
    u = data.setdefault(str(uid), {})
    g = u.setdefault(game, {"partidas": 0, "ganadas": 0, "perdidas": 0, "neto": 0, "racha": 0, "mejor_racha": 0})
    g["partidas"] = int(g.get("partidas", 0)) + 1
    if won:
        g["ganadas"] = int(g.get("ganadas", 0)) + 1
        g["racha"] = int(g.get("racha", 0)) + 1
        g["mejor_racha"] = max(int(g.get("mejor_racha", 0)), int(g.get("racha", 0)))
    else:
        g["perdidas"] = int(g.get("perdidas", 0)) + 1
        g["racha"] = 0
    g["neto"] = int(g.get("neto", 0)) + int(delta or 0)
    _v12_save_game_stats(data)


async def _v12_animate_message(message: discord.Message, frames: list[str], delay: float = 0.45):
    for frame in frames:
        try:
            await message.edit(content=frame)
            await asyncio.sleep(delay)
        except Exception:
            break


