def construir_contexto_memoria(user_id: int) -> str:
    """Contexto de memoria 3.1.0: compacto, paginado mentalmente y sin paredes infinitas."""
    recuerdos = obtener_memoria_usuario(user_id)
    if not recuerdos:
        return "\n[Memoria AETHER 3.1.0]\nNo hay recuerdos persistentes útiles todavía.\n"
    limpios = []
    seen = set()
    for rec in recuerdos[-60:]:
        r = str(rec).strip()
        if not r or len(r) < 4:
            continue
        low = r.lower()
        if any(x in low for x in ["token", "password", "contraseña", "api_key", "secret"]):
            continue
        key = re.sub(r"\s+", " ", low)[:120]
        if key in seen:
            continue
        seen.add(key)
        limpios.append(r[:240])
    seleccion = limpios[-18:]
    return "\n[Memoria AETHER 3.1.0 · recuerdos relevantes]\n" + "\n".join(f"- {r}" for r in seleccion) + "\n"


