@bot.command(name="aetheroptimizar", aliases=["optimizarmemoria", "limpiarmemoriaia"])
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def aetheroptimizar_cmd_v12(ctx):
    memoria = cargar_memoria_aether()
    total_antes = 0
    total_despues = 0
    for uid, payload in list(memoria.items()):
        if str(uid).startswith("_") or not isinstance(payload, dict):
            continue
        recuerdos = [str(x).strip() for x in payload.get("recuerdos", []) if str(x).strip()]
        total_antes += len(recuerdos)
        dedup = []
        seen = set()
        for rec in recuerdos:
            low = rec.lower()
            if any(x in low for x in ["token", "password", "contraseña", "api_key", "secret"]):
                continue
            key = re.sub(r"\s+", " ", low)[:160]
            if key in seen:
                continue
            seen.add(key)
            dedup.append(rec[:260])
        payload["recuerdos"] = dedup[-200:]
        payload["memoria_v12"] = {"optimizada": datetime.datetime.now().isoformat(), "limite": 200}
        total_despues += len(payload["recuerdos"])
    guardar_memoria_aether(memoria)
    embed = _v12_embed("🧹 Memoria AETHER optimizada", f"Antes: **{total_antes}** recuerdos\nDespués: **{total_despues}** recuerdos\n\nSe eliminaron duplicados, entradas vacías y contenido sensible.", discord.Color.green())
    await ctx.send(embed=embed)


