def _v12_level_style(style_name: str):
    styles = {
        "base":       {"colors": [(45, 20, 80), (100, 40, 180)], "accent": (190, 120, 255), "glow": (150, 70, 255)},
        "neon_purple":{"colors": [(18, 8, 40), (114, 30, 190)], "accent": (210, 120, 255), "glow": (170, 60, 255)},
        "galaxy":     {"colors": [(5, 8, 30), (78, 28, 130)], "accent": (160, 140, 255), "glow": (110, 80, 255)},
        "circuit":    {"colors": [(4, 15, 22), (20, 70, 88)], "accent": (0, 240, 220), "glow": (0, 180, 255)},
        "obsidian":   {"colors": [(5, 5, 10), (45, 10, 70)], "accent": (185, 85, 255), "glow": (105, 30, 190)},
        "diamond":    {"colors": [(20, 55, 85), (170, 235, 255)], "accent": (50, 210, 255), "glow": (110, 235, 255)},
        "blue_fire":  {"colors": [(0, 8, 22), (10, 70, 150)], "accent": (60, 170, 255), "glow": (0, 130, 255)},
        "pixel":      {"colors": [(20, 10, 50), (80, 20, 110)], "accent": (255, 80, 210), "glow": (255, 80, 180)},
        "dragon":     {"colors": [(25, 0, 0), (90, 0, 150)], "accent": (255, 95, 95), "glow": (255, 50, 120)},
        "matrix":     {"colors": [(0, 15, 10), (16, 60, 38)], "accent": (80, 255, 140), "glow": (30, 220, 100)},
        "supernova":  {"colors": [(22, 5, 50), (230, 90, 50)], "accent": (255, 210, 90), "glow": (255, 100, 80)},
        "cybercity":  {"colors": [(8, 8, 28), (25, 25, 95)], "accent": (255, 80, 220), "glow": (80, 190, 255)},
        "void":       {"colors": [(0, 0, 8), (22, 5, 40)], "accent": (140, 90, 255), "glow": (90, 40, 255)},
        "solar":      {"colors": [(80, 35, 0), (220, 160, 60)], "accent": (255, 235, 130), "glow": (255, 180, 60)},
        "glitch":     {"colors": [(8, 0, 30), (50, 0, 70)], "accent": (0, 255, 245), "glow": (255, 40, 220)},
    }
    return styles.get(style_name, styles["base"])


def _v12_equipped_item(info: dict, slot: str):
    eq = _v12_user_equipped(info)
    value = eq.get(slot)
    if not value:
        return None, None
    return _v12_find_item_by_type(value)


async def _v12_xp_card_file(ctx, miembro: discord.Member, datos: dict):
    if not Image or not ImageDraw or not ImageFilter:
        return None
    uid = str(miembro.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    level = _v12_level_of(info)
    xp = int(info.get("experiencia", 0) or 0)
    needed = _v12_xp_needed(level)
    pct = max(0.0, min(1.0, xp / max(1, needed)))
    rank = obtener_rank_por_monedas(datos, uid) or "N/A"

    fondo_id, fondo_item = _v12_equipped_item(info, "lvl_fondo")
    marco_id, marco_item = _v12_equipped_item(info, "lvl_marco")
    titulo_id, titulo_item = _v12_equipped_item(info, "titulo")
    mascota_id, mascota_item = _v12_equipped_item(info, "mascota")
    placa_id, placa_item = _v12_equipped_item(info, "placa")
    style_name = (fondo_item or {}).get("level_style", "base")
    style = _v12_level_style(style_name)
    W, H = 1420, 520
    bg = _level_gradient((W, H), style["colors"]).convert("RGBA")
    deco = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    dd = ImageDraw.Draw(deco)
    accent = style["accent"]
    glow = style["glow"]

    for i in range(22):
        x = (i * 173 + 40) % W
        y = (i * 91 + 20) % H
        r = 50 + (i % 5) * 18
        dd.ellipse((x-r, y-r, x+r, y+r), fill=(*glow, 18))
    if style_name in {"matrix", "circuit"}:
        for x in range(40, W, 110):
            dd.line((x, 40, x, H-40), fill=(*accent, 32), width=2)
        for y in range(50, H, 70):
            dd.line((45, y, W-45, y), fill=(*accent, 35), width=2)
            for x in range(80, W, 180):
                dd.ellipse((x-4, y-4, x+4, y+4), fill=(*accent, 100))
    elif style_name in {"glitch", "pixel"}:
        for i in range(65):
            x = random.randint(20, W-80); y = random.randint(20, H-30)
            dd.rectangle((x, y, x+random.randint(15, 80), y+random.randint(3, 12)), fill=(*accent, random.randint(18, 62)))
    elif style_name in {"supernova", "solar"}:
        dd.ellipse((W-360, -160, W+120, 320), fill=(*accent, 42))
        dd.ellipse((W-310, -110, W+70, 270), outline=(*accent, 85), width=6)
    elif style_name == "void":
        dd.ellipse((W//2-170, H//2-170, W//2+170, H//2+170), outline=(*accent, 70), width=8)
    bg = Image.alpha_composite(bg, deco.filter(ImageFilter.GaussianBlur(3)))
    draw = ImageDraw.Draw(bg)
    font_big = _level_font(58, True)
    font_title = _level_font(34, True)
    font_mid = _level_font(25, True)
    font_small = _level_font(20, False)
    font_tiny = _level_font(16, False)

    # Cristal principal
    panel = (28, 28, W-28, H-28)
    draw.rounded_rectangle(panel, radius=42, fill=(8, 10, 26, 165), outline=(*accent, 130), width=3)
    frame_color = (255, 215, 80, 235) if marco_item and "dorado" in str(marco_item.get("tipo", "")) else (*accent, 230)
    if marco_item:
        draw.rounded_rectangle((14, 14, W-14, H-14), radius=48, outline=frame_color, width=8)
        draw.rounded_rectangle((38, 38, W-38, H-38), radius=34, outline=(*accent, 70), width=2)

    # Avatar panel
    draw.rounded_rectangle((58, 72, 330, 450), radius=34, fill=(255,255,255,24), outline=(255,255,255,42), width=1)
    av_size = 205
    av_pos = (91, 106)
    try:
        avatar_bytes = await miembro.display_avatar.replace(size=256, static_format="png").read()
        av = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA").resize((av_size, av_size))
    except Exception:
        av = Image.new("RGBA", (av_size, av_size), (*accent, 255))
        ImageDraw.Draw(av).text((av_size//2-25, av_size//2-35), (miembro.display_name[:1] or "?").upper(), font=_level_font(70, True), fill=(20,20,35,255))
    mask = Image.new("L", (av_size, av_size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, av_size-1, av_size-1), fill=255)
    shadow = Image.new("RGBA", (av_size+30, av_size+30), (0,0,0,0))
    ImageDraw.Draw(shadow).ellipse((10, 10, av_size+20, av_size+20), fill=(0,0,0,135))
    shadow = shadow.filter(ImageFilter.GaussianBlur(9))
    bg.paste(shadow, (av_pos[0]-15, av_pos[1]-9), shadow)
    bg.paste(av, av_pos, mask)
    draw.ellipse((av_pos[0]-9, av_pos[1]-9, av_pos[0]+av_size+9, av_pos[1]+av_size+9), outline=(*accent, 240), width=8)
    draw.text((89, 338), "XP CARD 3.1.0", font=font_tiny, fill=(240,240,255,190))
    draw.text((89, 362), f"Nivel {level}", font=font_title, fill=(255,255,255,255))
    draw.text((89, 405), f"Rank #{rank}" if rank != "N/A" else "Rank N/A", font=font_small, fill=(238,238,250,225))

    # Texto principal
    title = miembro.display_name[:32]
    draw.text((382, 78), title, font=font_big, fill=(255,255,255,255))
    title_line = f"{(titulo_item or {}).get('emoji','✨')} {(titulo_item or {}).get('nombre','Perfil premium sin título equipado')}"
    draw.text((386, 146), title_line[:70], font=font_mid, fill=(*accent, 255))

    # Level badge grande
    badge = (1150, 70, 1320, 168)
    draw.rounded_rectangle(badge, radius=28, fill=(255,255,255,26), outline=(*accent, 110), width=2)
    draw.text((1192, 86), "LEVEL", font=font_tiny, fill=(240,240,255,205))
    draw.text((1210 - max(0, len(str(level))-2)*11, 106), str(level), font=_level_font(46, True), fill=(255,255,255,255))

    # Barra XP premium
    bar_x, bar_y, bar_w, bar_h = 386, 226, 890, 52
    draw.text((bar_x, bar_y-36), f"Experiencia · {_v12_money(xp)} / {_v12_money(needed)} XP", font=font_small, fill=(248,248,255,238))
    draw.text((bar_x+bar_w-170, bar_y-36), f"Faltan {_v12_money(max(0, needed-xp))}", font=font_tiny, fill=(235,235,250,210))
    fill_w = int(bar_w * pct)
    glow_layer = Image.new("RGBA", (W, H), (0,0,0,0))
    gd = ImageDraw.Draw(glow_layer)
    if fill_w:
        gd.rounded_rectangle((bar_x, bar_y, bar_x+fill_w, bar_y+bar_h), radius=26, fill=(*accent, 220))
    bg.alpha_composite(glow_layer.filter(ImageFilter.GaussianBlur(8)))
    draw.rounded_rectangle((bar_x, bar_y, bar_x+bar_w, bar_y+bar_h), radius=26, fill=(255,255,255,22), outline=(255,255,255,40), width=1)
    if fill_w:
        draw.rounded_rectangle((bar_x, bar_y, bar_x+fill_w, bar_y+bar_h), radius=26, fill=(*accent, 235))
    draw.text((bar_x+bar_w//2-30, bar_y+12), f"{int(pct*100)}%", font=font_mid, fill=(255,255,255,250))

    stats = [
        ("💰 Cash", _v12_money(info.get("cash", 0))),
        ("🏦 Banco", _v12_money(info.get("bank", 0))),
        ("✨ Rep", _v12_money(info.get("reputacion", 0))),
        ("🎨 Estilos", str(sum(1 for x in info.get("items", {}).values() if isinstance(x, dict) and x.get("categoria") in ["nivel", "fondo", "mascota", "titulo", "reputacion", "perfil", "decoracion"])))
    ]
    sx, sy, sw, sh, gap = 386, 318, 206, 78, 18
    for idx, (label, val) in enumerate(stats):
        x1 = sx + idx*(sw+gap)
        draw.rounded_rectangle((x1, sy, x1+sw, sy+sh), radius=22, fill=(255,255,255,22), outline=(255,255,255,34), width=1)
        draw.text((x1+16, sy+13), label, font=font_tiny, fill=(235,235,250,220))
        draw.text((x1+16, sy+40), str(val), font=font_small, fill=(255,255,255,255))

    chips = []
    for item in [fondo_item, marco_item, titulo_item, mascota_item, placa_item]:
        if item:
            chips.append(f"{item.get('emoji','💎')} {item.get('nombre')}")
    chip = " · ".join(chips[:4]) or "Compra estilos en !tienda nivel y equipa con !equipar <item>"
    draw.rounded_rectangle((386, 424, 1276, 462), radius=18, fill=(255,255,255,18), outline=(255,255,255,24), width=1)
    draw.text((405, 434), chip[:118], font=font_tiny, fill=(255,255,255,220))
    draw.text((W-300, H-36), "X AETHER ULTRA · XP CARD 3.1.0", font=font_tiny, fill=(255,255,255,145))

    buf = io.BytesIO()
    bg.save(buf, format="PNG")
    buf.seek(0)
    return discord.File(buf, filename=f"xpcard_2_0_0_{miembro.id}.png")


