@commands.cooldown(1, 5, commands.BucketType.user)
async def inventario_cmd_v12(ctx, miembro: discord.Member = None, pagina: int = 1):
    miembro = miembro or ctx.author
    datos = cargar_datos(); uid = str(miembro.id); asegurar_usuario(datos, uid); info = datos[uid]
    inv = info.get("items", {}) if isinstance(info.get("items", {}), dict) else {}
    entries = []
    for key, rec in inv.items():
        item_id, item = _v12_find_item_by_type(key)
        if not item:
            item = rec if isinstance(rec, dict) else {"nombre": str(key), "emoji": "📦", "rareza": "normal"}
            item_id = str(key)
        qty = int(rec.get("cantidad", 1) or 1) if isinstance(rec, dict) else 1
        slot = item.get("slot") or ("consumible" if item.get("consumible") else item.get("categoria", "item"))
        equipped = " · **EQUIPADO**" if key in _v12_user_equipped(info).values() or item.get("tipo") in _v12_user_equipped(info).values() else ""
        entries.append(f"{item.get('emoji','📦')} `{item_id}` · **{item.get('nombre', item_id)}** x{qty}\n{_v12_rarity_emoji(item)} {item.get('rareza','normal')} · {slot}{equipped}")
    entries.sort()
    per = 8
    total_pages = max(1, (len(entries)+per-1)//per)
    pagina = max(1, min(int(pagina or 1), total_pages))
    embed = _v12_embed(f"🎒 Inventario premium · {miembro.display_name}", member=miembro)
    embed.description = f"Objetos: **{len(entries)}** · Página **{pagina}/{total_pages}**\nUsa `!equipar <item>` para cosméticos y `!usar <item>` para consumibles."
    chunk = entries[(pagina-1)*per:pagina*per]
    embed.add_field(name="📦 Objetos", value="\n\n".join(chunk)[:1024] if chunk else "Inventario vacío. Ve a `!tienda`.", inline=False)
    embed.add_field(name="🎨 Equipado", value="\n".join(f"`{k}` → `{v}`" for k, v in _v12_user_equipped(info).items()) or "Nada equipado.", inline=False)
    await ctx.send(embed=embed)


# # @bot.command(name="equipar", aliases=["equip"])  # clean core: decorador antiguo desactivado  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 4, commands.BucketType.user)
async def equipar_cmd_v12(ctx, *, item_query: str = None):
    if not item_query:
        await ctx.send(embed=_v12_embed("🎨 Equipar cosmético", "Uso: `!equipar <item>`\nEjemplo: `!equipar fondo_lvl_galaxia`", member=ctx.author))
        return
    item_id, item = _v12_item_key(item_query)
    if not item:
        await ctx.send("❌ No encontré ese item. Usa `!tienda` o `!inv`.")
        return
    slot = item.get("slot")
    if not slot:
        await ctx.send("❌ Ese objeto no es equipable. Los consumibles se usan con `!usar <item>`.")
        return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid); info = datos[uid]
    if not _v12_has_item(info, item_id, item):
        await ctx.send(f"🔒 No tienes **{item.get('nombre')}**. Cómpralo en `!tienda {item.get('categoria','otros')}`.")
        return
    ok, reason = _v12_unlock_state(info, item)
    if not ok:
        await ctx.send(f"🔒 Todavía no puedes equiparlo: **{reason}**.")
        return
    eq = _v12_user_equipped(info)
    eq[slot] = str(item.get("tipo", item_id))
    guardar_datos(datos)
    embed = _v12_embed("✅ Cosmético equipado", f"{item.get('emoji','💎')} **{item.get('nombre')}** ahora está en el slot `{slot}`.", discord.Color.green(), ctx.author)
    embed.add_field(name="Vista", value="Usa `!perfil` o `!xpcard` para verlo aplicado.", inline=False)
    await ctx.send(embed=embed)


