async def desequipar_cmd_v12(ctx, slot: str = "all"):
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid); info = datos[uid]
    eq = _v12_user_equipped(info)
    if slot.lower() in {"all", "todo", "todos"}:
        eq.clear(); msg = "Se quitaron todos los cosméticos equipados."
