def _v13_json_load(path: str, default=None):
    default = {} if default is None else default
    try:
        if not os.path.exists(path):
            return default
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return default


def _v13_json_save(path: str, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=4)
        return True
    except Exception as e:
        print(f"[3.1.0] Error guardando {path}: {e}")
        return False


def _v13_cfg():
    return _v13_json_load(V13_MEMBER_CONFIG_FILE, {})


def _v13_save_cfg(cfg):
    return _v13_json_save(V13_MEMBER_CONFIG_FILE, cfg)


def _v13_guild_cfg(guild):
    cfg = _v13_cfg()
    return cfg.setdefault(str(guild.id), {}) if guild else {}


def _v13_get_member_role(guild):
    if guild is None:
        return None
    cfg = _v13_cfg().get(str(guild.id), {})
    raw_id = cfg.get("member_role_id") or os.getenv("MIEMBRO_ROLE_ID") or os.getenv("MEMBER_ROLE_ID")
    try:
        if raw_id:
            role = guild.get_role(int(raw_id))
            if role:
                return role
    except Exception:
        pass
    for role in guild.roles:
        if role.name.lower().strip() in V13_MEMBER_ROLE_NAMES:
            return role
    return None


def _v13_has_member_access(member) -> bool:
    if member is None or getattr(member, "bot", False):
        return False
    if getattr(member.guild_permissions, "administrator", False):
        return True
    role = _v13_get_member_role(member.guild)
    if role and role in getattr(member, "roles", []):
        return True
    return any(r.name.lower().strip() in V13_MEMBER_ROLE_NAMES for r in getattr(member, "roles", []))


async def _v13_require_member(ctx) -> bool:
    if _v13_has_member_access(ctx.author):
        return True
    role = _v13_get_member_role(ctx.guild)
    role_txt = role.mention if role else "`Miembro`"
    embed = discord.Embed(
        title="🔒 Zona exclusiva de miembros",
        description=(
            f"Este comando pertenece al **Club Royal Member**.\n\n"
            f"Necesitas el rol {role_txt} para usarlo. Si ya lo tienes y no funciona, un admin puede ejecutar "
            f"`!setrolmiembro @rol`."
        ),
        color=discord.Color.dark_purple(),
    )
    embed.set_footer(text="X AETHER ULTRA 3.1.0 · sistema de miembros")
    await ctx.reply(embed=embed, mention_author=False)
    return False


def _v13_money(n: int) -> str:
    try:
        return f"{int(n):,}".replace(",", ".")
    except Exception:
        return str(n)


def _v13_level(uid: str, datos=None) -> int:
    datos = datos or cargar_datos()
    asegurar_usuario(datos, uid)
    return max(1, int(datos[uid].get("nivel", 1) or 1))


def _v13_rep(uid: str, datos=None) -> int:
    datos = datos or cargar_datos()
    asegurar_usuario(datos, uid)
    return int(datos[uid].get("reputacion", 0) or 0)


def _v13_member_tier(nivel: int, rep: int = 0):
    if nivel >= 50 and rep >= 20:
        return "👑 Mythic Member", discord.Color.gold(), 0.82
    if nivel >= 30:
        return "🌌 Elite Member", discord.Color.purple(), 0.88
    if nivel >= 15:
        return "💠 Plus Member", discord.Color.blurple(), 0.94
    if nivel >= 5:
        return "🟣 Active Member", discord.Color.magenta(), 1.0
    return "🔮 New Member", discord.Color.dark_purple(), 1.0


def _v13_member_price(item: dict, nivel: int, rep: int = 0) -> int:
    base = int(item.get("precio", 0) or 0)
    min_level = max(1, int(item.get("nivel_min", 1) or 1))
    # El catálogo sube de precio con tu nivel, pero los tiers altos también tienen un pequeño descuento de fidelidad.
    level_inflation = 1 + min(max(nivel - 1, 0), 100) * 0.018
    tier_name, _, loyalty = _v13_member_tier(nivel, rep)
    rarity = str(item.get("rareza", "común")).lower()
    rarity_boost = {"común": 1.0, "raro": 1.08, "épico": 1.18, "legendario": 1.34, "mítico": 1.55}.get(rarity, 1.0)
    gate_boost = 1 + max(min_level - 1, 0) * 0.012
    return max(1, int(base * level_inflation * rarity_boost * gate_boost * loyalty))


def _v13_member_item_unlocked(item: dict, uid: str, datos=None):
    datos = datos or cargar_datos()
    nivel = _v13_level(uid, datos)
    rep = _v13_rep(uid, datos)
    min_level = int(item.get("nivel_min", 1) or 1)
    min_rep = int(item.get("rep_min", 0) or 0)
    if nivel < min_level:
        return False, f"nivel {min_level}"
    if rep < min_rep:
        return False, f"rep {min_rep}"
    return True, "desbloqueado"


def _v13_rarity_icon(item):
    return {"común": "⚪", "raro": "🔵", "épico": "🟣", "legendario": "🟡", "mítico": "🔴"}.get(str(item.get("rareza", "")).lower(), "✨")


def _v13_progress_bar(value, maximum, size=14):
    maximum = max(1, int(maximum or 1))
    value = max(0, min(int(value or 0), maximum))
    filled = round((value / maximum) * size)
    return "▰" * filled + "▱" * (size - filled)


def _v13_member_stats(datos, uid):
    asegurar_usuario(datos, uid)
    return datos[uid].setdefault("member_stats", {
        "plays": 0, "wins": 0, "earned": 0, "daily_claims": 0, "last_daily": "",
        "plays_today_date": "", "plays_today": 0, "mission_claim_date": "",
    })


def _v13_record_member_game(uid, won: bool, earned: int = 0):
    datos = cargar_datos()
    asegurar_usuario(datos, str(uid))
    stats = _v13_member_stats(datos, str(uid))
    today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
    if stats.get("plays_today_date") != today:
        stats["plays_today_date"] = today
        stats["plays_today"] = 0
    stats["plays"] = int(stats.get("plays", 0) or 0) + 1
    stats["plays_today"] = int(stats.get("plays_today", 0) or 0) + 1
    if won:
        stats["wins"] = int(stats.get("wins", 0) or 0) + 1
    if earned > 0:
        stats["earned"] = int(stats.get("earned", 0) or 0) + int(earned)
    guardar_datos(datos)


def _v13_add_xp(datos, uid: str, xp: int):
    asegurar_usuario(datos, uid)
    datos[uid]["experiencia"] = int(datos[uid].get("experiencia", 0) or 0) + int(xp)
    ups = 0
    while True:
        lvl = int(datos[uid].get("nivel", 1) or 1)
        need = _xp_needed_for_level(lvl) if "_xp_needed_for_level" in globals() else 100 + (lvl - 1) * 50
        if datos[uid]["experiencia"] < need:
            break
        datos[uid]["experiencia"] -= need
        datos[uid]["nivel"] = lvl + 1
        ups += 1
        agregar_a_cash_y_monedas(datos, uid, 50 + datos[uid]["nivel"] * 12)
    return ups


def _v13_member_shop_items(category: str = "all"):
    category = str(category or "all").lower().strip()
    pool = []
    for iid, item in V13_MEMBER_SHOP_ITEMS.items():
        if category in ("all", "todo") or str(item.get("categoria", "miembro")).lower() == category or str(item.get("slot", "")).lower() == category:
            pool.append((iid, item))
    pool.sort(key=lambda kv: (int(kv[1].get("nivel_min", 1) or 1), int(kv[1].get("precio", 0) or 0), kv[0]))
    return pool


def _v13_member_shop_embed(member, category="all", page=0):
    datos = cargar_datos()
    uid = str(member.id)
    asegurar_usuario(datos, uid)
    nivel = _v13_level(uid, datos)
    rep = _v13_rep(uid, datos)
    tier, color, _ = _v13_member_tier(nivel, rep)
    items = _v13_member_shop_items(category)
    per_page = 8
    max_page = max(0, (len(items) - 1) // per_page)
    page = max(0, min(int(page or 0), max_page))
    shown = items[page * per_page:(page + 1) * per_page]
    embed = discord.Embed(
        title="💎 Tienda Exclusiva de Miembros",
        description=(
            f"{member.mention}, estás en **{tier}**.\n"
            f"Los objetos se desbloquean por **nivel XP** y algunos por **reputación**. "
            f"Cuanto más subes, aparecen piezas más raras y el mercado escala su precio.\n\n"
            f"`!comprarmiembro <id>` para comprar · `!equipar <id>` para lucir cosméticos."
        ),
        color=color,
    )
    embed.set_thumbnail(url=member.display_avatar.url)
    if not shown:
        embed.add_field(name="🫥 Sin items", value="No hay objetos en esta categoría.", inline=False)
    for iid, item in shown:
        unlocked, reason = _v13_member_item_unlocked(item, uid, datos)
        price = _v13_member_price(item, nivel, rep)
        lock = "✅" if unlocked else f"🔒 {reason}"
        slot = f" · slot `{item.get('slot')}`" if item.get("slot") else ""
        embed.add_field(
            name=f"{item.get('emoji','✨')} `{iid}`",
            value=(
                f"**{item.get('nombre', iid)}**\n"
                f"{_v13_rarity_icon(item)} {item.get('rareza','normal')} · min lvl **{item.get('nivel_min',1)}**{slot}\n"
                f"Precio dinámico: **{_v13_money(price)}** {amatista} · {lock}\n"
                f"{item.get('descripcion','Sin descripción.')}"
            )[:1024],
            inline=False,
        )
    embed.set_footer(text=f"Página {page + 1}/{max_page + 1} · 3.1.0 Member Shop · categoría {category}")
    return embed


class V13MemberShopView(discord.ui.View):
    def __init__(self, author, category="all", page=0):
        super().__init__(timeout=120)
        self.author = author
        self.category = category
        self.page = int(page or 0)
        cats = ["all", "miembro", "lvl_fondo", "lvl_marco", "titulo", "placa", "mascota", "firma"]
        self.add_item(V13MemberShopSelect(self, cats))

    async def _guard(self, interaction):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("Este panel pertenece a otra persona.", ephemeral=True)
            return False
        return True

    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary)
    async def prev_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.page = max(0, self.page - 1)
        await interaction.response.edit_message(embed=_v13_member_shop_embed(self.author, self.category, self.page), view=self)

    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary)
    async def next_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        self.page += 1
        await interaction.response.edit_message(embed=_v13_member_shop_embed(self.author, self.category, self.page), view=self)

    @discord.ui.button(label="Miembro", emoji="💎", style=discord.ButtonStyle.primary)
    async def member_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction):
            return
        await interaction.response.send_message("Usa `!miembro` para ver beneficios, misiones y estado del club.", ephemeral=True)


class V13MemberShopSelect(discord.ui.Select):
    def __init__(self, parent, cats):
        self.parent_view = parent
        labels = {
            "all": ("Todo", "🌌"), "miembro": ("Consumibles", "💎"), "lvl_fondo": ("Fondos XP", "🖼️"),
            "lvl_marco": ("Marcos XP", "🧿"), "titulo": ("Títulos", "🏷️"), "placa": ("Placas", "💠"),
            "mascota": ("Mascotas", "🛸"), "firma": ("Firmas", "✍️"),
        }
        options = []
        for cat in cats:
            label, emoji = labels.get(cat, (cat.title(), "✨"))
            options.append(discord.SelectOption(label=label, emoji=emoji, value=cat, default=(cat == parent.category)))
        super().__init__(placeholder="Filtrar tienda de miembros", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.parent_view.author.id:
            await interaction.response.send_message("Este selector no es tuyo.", ephemeral=True)
            return
        self.parent_view.category = self.values[0]
        self.parent_view.page = 0
        for opt in self.options:
            opt.default = (opt.value == self.values[0])
        await interaction.response.edit_message(embed=_v13_member_shop_embed(self.parent_view.author, self.parent_view.category, self.parent_view.page), view=self.parent_view)


def _v13_parse_amount(raw, available):
    if raw is None:
        return 100
    raw = str(raw).lower().strip()
    if raw in ("all", "todo"):
        return max(0, int(available))
    try:
        return max(1, int(raw))
    except Exception:
        return 100


