# @bot.command(name="inventario", aliases=["inv", "mochila", "bag"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 4, commands.BucketType.user)
async def inventario_cmd(ctx, objetivo: str = None, pagina: int = 1):
    """Inventario decorado y paginado. Uso: !inv [pagina] o !inv @usuario [pagina]"""
    miembro = ctx.author
    if objetivo:
        if objetivo.isdigit():
            pagina = int(objetivo)
        else:
            try:
                miembro = await commands.MemberConverter().convert(ctx, objetivo)
            except Exception:
                miembro = ctx.author
    datos = cargar_datos(); uid = str(miembro.id); asegurar_usuario(datos, uid)
    inv = datos[uid].get("items", {}) if isinstance(datos[uid].get("items", {}), dict) else {}
    equipado = datos[uid].get("equipado", {}) if isinstance(datos[uid].get("equipado", {}), dict) else {}
    items = []
    for tipo, info in inv.items():
        if not isinstance(info, dict):
            continue
        item_id, item = _find_shop_item_by_type(tipo) if "_find_shop_item_by_type" in globals() else (None, None)
        item = item or {}
        qty = int(info.get("cantidad", 1) or 1) if (info.get("consumible") or info.get("cantidad")) else 1
        tag = "Consumible" if info.get("consumible") or qty > 1 else ("Temporal" if info.get("expira") else "Permanente")
        eq_slot = next((slot for slot, val in equipado.items() if val == tipo), None)
        items.append((tipo, item, qty, tag, eq_slot))
    per = 10
    max_page = max(1, (len(items) + per - 1) // per)
    pagina = max(1, min(int(pagina or 1), max_page))
    shown = items[(pagina - 1) * per: pagina * per]
    nivel = _v13_level(uid, datos); rep = _v13_rep(uid, datos); tier, color, _ = _v13_member_tier(nivel, rep)
    embed = discord.Embed(
        title=f"🎒 Inventario Premium · {miembro.display_name}",
        description=f"Items: **{len(items)}** · Equipados: **{len(equipado)}** · Estado: **{tier}**",
        color=color,
    )
    embed.set_thumbnail(url=miembro.display_avatar.url)
    if not shown:
        embed.add_field(name="📦 Vacío", value="No hay objetos todavía. Mira `!tienda` y `!tiendamiembro`.", inline=False)
    for tipo, item, qty, tag, eq_slot in shown:
        marker = f" · equipado en `{eq_slot}`" if eq_slot else ""
        embed.add_field(
            name=f"{item.get('emoji','📦')} {item.get('nombre', tipo)} x{qty}",
            value=f"`{tipo}` · **{tag}**{marker}\n{item.get('descripcion','Sin descripción.')[:160]}",
            inline=False,
        )
    embed.set_footer(text=f"Página {pagina}/{max_page} · usa !equipar <item> para cosméticos")
    await ctx.send(embed=embed)

