@commands.cooldown(1, 4, commands.BucketType.user)
async def comprarmiembro_cmd(ctx, item_id: str = None):
    if not await _v13_require_member(ctx):
        return
    if not item_id:
        await ctx.reply("Uso: `!comprarmiembro <id>` · mira `!tiendamiembro`", mention_author=False)
        return
    item_id = item_id.lower().strip()
    item = V13_MEMBER_SHOP_ITEMS.get(item_id)
    if not item:
        await ctx.reply("❌ Ese item no existe en la tienda de miembros. Mira `!tiendamiembro`.", mention_author=False)
        return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    unlocked, reason = _v13_member_item_unlocked(item, uid, datos)
    if not unlocked:
        await ctx.reply(f"🔒 No desbloqueado todavía. Requisito: **{reason}**.", mention_author=False)
        return
    precio = _v13_member_price(item, _v13_level(uid, datos), _v13_rep(uid, datos))
    if int(datos[uid].get("cash", 0) or 0) < precio:
        await ctx.reply(f"💸 Te faltan amatistas. Precio: **{_v13_money(precio)}** {amatista} · Cash: **{_v13_money(datos[uid].get('cash',0))}**", mention_author=False)
        return
    if not (item.get("consumible") or item.get("stackable")) and item.get("tipo") in datos[uid].get("items", {}):
        await ctx.reply("⚠️ Ya tienes ese cosmético. Equípalo con `!equipar <id>`.", mention_author=False)
        return
    restar_de_cash(datos, uid, precio)
    res = aplicar_item(datos, uid, item_id)
    guardar_datos(datos)
    embed = _v13_member_embed("✅ Compra Member realizada", f"{item['emoji']} **{item['nombre']}**\n{item['descripcion']}\n\nPrecio: **{_v13_money(precio)}** {amatista}\n{res}", discord.Color.green(), ctx.author)
    await ctx.send(embed=embed)


