@bot.command(name="minacristal", aliases=["mineclub", "minamiembro"])
@commands.cooldown(1, 45, commands.BucketType.user)
async def minacristal_cmd(ctx):
    if not await _v13_require_member(ctx):
        return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    nivel = _v13_level(uid, datos)
