@bot.command(name="ruletamiembro", aliases=["memberroulette", "ruletavip"])
@commands.cooldown(1, 20, commands.BucketType.user)
async def ruletamiembro_cmd(ctx, apuesta: str = "100"):
    if not await _v13_require_member(ctx):
        return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    cash = int(datos[uid].get("cash", 0) or 0)
    amount = _v13_parse_amount(apuesta, cash)
    if amount <= 0 or amount > cash:
        await ctx.reply(f"❌ Apuesta inválida. Cash: **{_v13_money(cash)}** {amatista}.", mention_author=False)
        return
    restar_de_cash(datos, uid, amount)
    msg = await ctx.send(embed=_v13_member_embed("🎡 Ruleta Member", "La ruleta gira: `🟣 ⚫ 🟣 ⚫ 💎`", discord.Color.purple(), ctx.author))
    for icon in ["🟣", "⚫", "💎", "🟣", "👑"]:
        await asyncio.sleep(0.35)
        await msg.edit(embed=_v13_member_embed("🎡 Ruleta Member", f"La bola salta por el aro: **{icon}**", discord.Color.purple(), ctx.author))
    roll = random.random()
    if roll < 0.48:
        gain = 0; won = False; label = "Perdiste la apuesta, pero la ruleta dejó chispas bonitas."
    elif roll < 0.82:
        gain = int(amount * 1.65); won = True; label = "Victoria violeta."
    elif roll < 0.97:
        gain = int(amount * 2.4); won = True; label = "Golpe premium."
    else:
        gain = int(amount * 5); won = True; label = "JACKPOT MEMBER."
    if gain:
        agregar_a_cash_y_monedas(datos, uid, gain)
    xp = random.randint(25, 80)
    _v13_add_xp(datos, uid, xp)
    guardar_datos(datos); _v13_record_member_game(uid, won, max(0, gain - amount))
    await msg.edit(embed=_v13_member_embed("🎡 Ruleta Member · Resultado", f"{label}\nApuesta: **{_v13_money(amount)}**\nRetorno: **{_v13_money(gain)}** {amatista}\nXP: **{xp}**", discord.Color.green() if won else discord.Color.red(), ctx.author))


