@commands.cooldown(1, 75, commands.BucketType.user)
async def bossmiembro_cmd(ctx):
    if not await _v13_require_member(ctx):
        return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    inv = datos[uid].get("items", {})
    has_ticket = isinstance(inv.get("miembro_ticket_boss"), dict) and int(inv["miembro_ticket_boss"].get("cantidad", 0) or 0) > 0
    if has_ticket:
        _tienda_decrementar_consumible(datos, uid, "miembro_ticket_boss")
    nivel = _v13_level(uid, datos)
    hp = 3 + min(5, nivel // 10)
    msg = await ctx.send(embed=_v13_member_embed("👾 Boss Morado", f"Aparece un boss con **{hp}** escudos. Preparando ataque...", discord.Color.dark_purple(), ctx.author))
    hits = 0
    for i in range(hp):
        await asyncio.sleep(0.5)
        if random.random() < (0.58 + min(0.22, nivel * 0.006)):
            hits += 1
        await msg.edit(embed=_v13_member_embed("👾 Boss Morado", f"Escudos rotos: **{hits}/{hp}**\n`{'▰'*hits}{'▱'*(hp-hits)}`", discord.Color.dark_purple(), ctx.author))
    won = hits >= max(2, hp - 1)
    premio = (random.randint(1800, 4200) + nivel * 80) if won else random.randint(250, 700)
    if has_ticket:
        premio = int(premio * 1.45)
    xp = random.randint(120, 360) if won else random.randint(30, 100)
    agregar_a_cash_y_monedas(datos, uid, premio)
    ups = _v13_add_xp(datos, uid, xp)
    guardar_datos(datos); _v13_record_member_game(uid, won, premio)
    await msg.edit(embed=_v13_member_embed("👾 Boss Morado derrotado" if won else "👾 Boss Morado resistió", f"Premio: **{_v13_money(premio)}** {amatista}\nXP: **{xp}**" + ("\nTicket Boss usado: bonus aplicado." if has_ticket else "") + (f"\nSubiste **{ups}** nivel(es)." if ups else ""), discord.Color.green() if won else discord.Color.orange(), ctx.author))


