# ──────────────────────────────────────────────────────────────────────────────
# Streams públicos para miembros
# ──────────────────────────────────────────────────────────────────────────────

def _v13_load_streams():
    data = _v13_json_load(STREAMS_DATA_FILE, {})
    fixed = {}
    for uid, arr in (data or {}).items():
        fixed[str(uid)] = []
        if isinstance(arr, list):
            for s in arr:
                if not isinstance(s, dict):
                    continue
                platform = (s.get("platform") or s.get("plataforma") or "").lower().strip()
                identifier = (s.get("identifier") or s.get("usuario") or s.get("user") or "").strip()
                if platform and identifier:
                    fixed[str(uid)].append({
                        "platform": platform, "identifier": identifier,
                        "message": s.get("message", s.get("mensaje", "")),
                        "url": s.get("url", _v13_stream_url(platform, identifier)),
                    })
    return fixed


def _v13_save_streams(data):
    global _streams_db
    _streams_db = {str(k): v for k, v in (data or {}).items()}
    return _v13_json_save(STREAMS_DATA_FILE, _streams_db)


def _v13_stream_url(platform, identifier):
    ident = str(identifier or "").strip().lstrip("@")
    if str(identifier).startswith("http"):
        return identifier
    platform = str(platform or "").lower()
    if platform == "twitch": return f"https://www.twitch.tv/{ident}"
    if platform == "youtube": return f"https://www.youtube.com/{ident}" if ident.startswith("@") else f"https://www.youtube.com/@{ident}"
    if platform == "tiktok": return f"https://www.tiktok.com/@{ident}/live"
    if platform == "kick": return f"https://kick.com/{ident}"
    return ident


def _v13_parse_stream_args(plataforma, usuario=None):
    if not plataforma:
        return None, None, None
    raw = str(plataforma).strip()
    user = str(usuario or "").strip()
    if raw.startswith("http://") or raw.startswith("https://"):
        from urllib.parse import urlparse
        url = raw
        host = urlparse(url).netloc.lower()
        path = urlparse(url).path.strip("/")
        if "twitch.tv" in host:
            platform = "twitch"; ident = path.split("/")[0]
        elif "youtube.com" in host or "youtu.be" in host:
            platform = "youtube"; ident = path.split("/")[-1] if path else raw
        elif "tiktok.com" in host:
            platform = "tiktok"; ident = path.replace("@", "").split("/")[0]
        elif "kick.com" in host:
            platform = "kick"; ident = path.split("/")[0]
        else:
            return None, None, None
        return platform, ident, url
    platform = raw.lower()
    if platform not in ("twitch", "youtube", "tiktok", "kick"):
        return None, None, None
    ident = user.strip().lstrip("@")
    if not ident:
        return None, None, None
    return platform, ident, _v13_stream_url(platform, ident)


@bot.command(name="addstream", aliases=["registrarstream", "streamadd"])
@commands.cooldown(1, 8, commands.BucketType.user)
async def addstream_cmd(ctx, plataforma: str = None, *, usuario: str = None):
    if not await _v13_require_member(ctx):
        return
    platform, ident, url = _v13_parse_stream_args(plataforma, usuario)
    if not platform:
        await ctx.reply("Uso: `!addstream twitch usuario`, `!addstream youtube @canal`, `!addstream tiktok usuario`, `!addstream kick usuario` o pega una URL.", mention_author=False)
        return
    data = _v13_load_streams(); uid = str(ctx.author.id); arr = data.setdefault(uid, [])
    if len(arr) >= 5:
        await ctx.reply("❌ Límite de miembro: máximo **5** cuentas de stream.", mention_author=False); return
    if any(s.get("platform") == platform and s.get("identifier", "").lower() == ident.lower() for s in arr):
        await ctx.reply("⚠️ Esa cuenta ya está registrada.", mention_author=False); return
    arr.append({"platform": platform, "identifier": ident, "url": url, "message": ""})
    _v13_save_streams(data)
    embed = _v13_member_embed("🔴 Stream registrado", f"Plataforma: **{platform.title()}**\nUsuario/canal: `{ident}`\nEnlace: {url}\n\nEl monitor usará la API disponible o el enlace público según plataforma.", discord.Color.red(), ctx.author)
    await ctx.send(embed=embed)


