@bot.command(name="delstream", aliases=["remstream", "borrarstream"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def delstream_cmd(ctx, numero: int = None):
    if not await _v13_require_member(ctx):
        return
    data = _v13_load_streams(); uid = str(ctx.author.id); arr = data.get(uid, [])
    if not arr:
        await ctx.reply("No tienes streams registrados.", mention_author=False); return
    if numero is None or numero < 1 or numero > len(arr):
        await ctx.reply(f"Uso: `!delstream <1-{len(arr)}>`", mention_author=False); return
    removed = arr.pop(numero - 1)
    data[uid] = arr; _v13_save_streams(data)
    await ctx.send(embed=_v13_member_embed("✅ Stream eliminado", f"{removed['platform'].title()} · `{removed['identifier']}`", discord.Color.green(), ctx.author))


