def _v14_remove_help_entry(command_text: str):
    command_text = str(command_text).lower().strip()
    try:
        for _, cmds in list(COMMAND_CATEGORIES.items()):
            if not isinstance(cmds, dict):
                continue
            for key in list(cmds.keys()):
                if command_text in str(key).lower():
                    cmds.pop(key, None)
    except Exception:
        pass


def _v14_cleanup_help():
    for token in ("invmiembro", "memberinv"):
        _v14_remove_help_entry(token)
    try:
        for dct in (HELP_COMMAND_HINTS, V9_COMMAND_HINTS):
            if isinstance(dct, dict):
                for key in list(dct.keys()):
                    val = str(dct.get(key, "")).lower()
                    if "invmiembro" in key.lower() or "invmiembro" in val or "memberinv" in key.lower() or "memberinv" in val:
                        dct.pop(key, None)
    except Exception:
        pass


