def _v14_bar(value, maximum, size=18, full="▰", empty="▱"):
    try:
        maximum = max(1, int(maximum or 1)); value = max(0, min(int(value or 0), maximum))
        filled = round((value / maximum) * size)
        return full * filled + empty * (size - filled)
    except Exception:
        return empty * size


def _v14_find_item_by_type(tipo: str):
    try:
        if "_find_shop_item_by_type" in globals():
            return _find_shop_item_by_type(tipo)
    except Exception:
        pass
    for iid, item in TIENDA_ITEMS.items():
        if item.get("tipo") == tipo or iid == tipo:
            return iid, item
    return None, None


def _v14_item_category(item: dict, inv_info: dict = None):
    inv_info = inv_info or {}
    if item.get("member_only") or inv_info.get("member_only"):
        return "miembro"
    if item.get("slot"):
        return "cosmetico"
    if item.get("consumible") or inv_info.get("consumible") or int(inv_info.get("cantidad", 1) or 1) > 1:
        return "consumible"
    if item.get("multiplicador", 1) not in (1, 1.0) or inv_info.get("expira"):
        return "boost"
    return "general"


def _v14_collect_inventory(member):
    datos = cargar_datos(); uid = str(member.id); asegurar_usuario(datos, uid)
    inv = datos[uid].get("items", {}) if isinstance(datos[uid].get("items", {}), dict) else {}
    equipado = datos[uid].get("equipado", {}) if isinstance(datos[uid].get("equipado", {}), dict) else {}
    rows = []
    for tipo, info in inv.items():
        if not isinstance(info, dict):
            info = {"cantidad": 1}
        item_id, item = _v14_find_item_by_type(tipo)
        item = item or {"nombre": tipo, "emoji": "📦", "descripcion": "Objeto guardado en tu inventario."}
        qty = int(info.get("cantidad", 1) or 1)
        eq_slot = next((slot for slot, val in equipado.items() if val == tipo or val == item_id), None)
        cat = _v14_item_category(item, info)
        rows.append({
            "tipo": tipo, "item_id": item_id or tipo, "item": item, "qty": max(1, qty),
            "equipped_slot": eq_slot, "category": cat, "info": info,
        })
    order = {"miembro": 0, "cosmetico": 1, "consumible": 2, "boost": 3, "general": 4}
    rows.sort(key=lambda r: (order.get(r["category"], 9), str(r["item"].get("nombre", r["tipo"])).lower()))
    return datos, uid, rows


def _v14_inventory_embed(ctx, member, page=1, filtro="all"):
    datos, uid, rows = _v14_collect_inventory(member)
    filtro = str(filtro or "all").lower().strip()
    aliases = {"todo": "all", "member": "miembro", "members": "miembro", "cosmeticos": "cosmetico", "cosméticos": "cosmetico", "consumibles": "consumible", "boosts": "boost"}
    filtro = aliases.get(filtro, filtro)
    if filtro != "all":
        rows = [r for r in rows if r["category"] == filtro or str(r["item"].get("slot", "")).lower() == filtro]
    per = 8
    max_page = max(1, (len(rows) + per - 1) // per)
    page = max(1, min(int(page or 1), max_page))
    shown = rows[(page - 1) * per: page * per]
    nivel = _v13_level(uid, datos); rep = _v13_rep(uid, datos); tier, color, _ = _v13_member_tier(nivel, rep)
    inv_total = len(_v14_collect_inventory(member)[2])
    equipped = datos[uid].get("equipado", {}) if isinstance(datos[uid].get("equipado", {}), dict) else {}
    desc = (
        f"{member.mention} · **Inventario único oficial**. Aquí se ven objetos normales y objetos de miembro, sin `!invmiembro`.\n"
        f"{_v14_bar(len(equipped), max(1, 6), 16)} **{len(equipped)}** equipados · **{inv_total}** objetos distintos\n"
        f"Filtro: `{filtro}` · Estado: **{tier}**"
    )
    embed = discord.Embed(title=f"🎒 Inventario Aether · {member.display_name}", description=desc, color=color)
    embed.set_thumbnail(url=member.display_avatar.url)
    if not shown:
        embed.add_field(
            name="📦 Nada por aquí",
            value="No hay objetos en este filtro. Prueba `!inv all`, `!tienda` o `!tiendamiembro`.",
            inline=False,
        )
    for r in shown:
        item = r["item"]; info = r["info"]
        marker = f" · equipado en `{r['equipped_slot']}`" if r["equipped_slot"] else ""
        rare = _v13_rarity_icon(item) if "_v13_rarity_icon" in globals() else "✨"
        member_tag = " · 💎 member" if item.get("member_only") else ""
        exp = f" · expira `{info.get('expira')}`" if info.get("expira") else ""
        use_hint = "`!usar`" if item.get("consumible") or info.get("consumible") else ("`!equipar`" if item.get("slot") else "`!perfil`")
        embed.add_field(
            name=f"{item.get('emoji','📦')} {item.get('nombre', r['tipo'])} x{r['qty']}",
            value=(
                f"ID: `{r['item_id']}` · tipo `{r['tipo']}`\n"
                f"{rare} **{item.get('rareza','normal')}** · `{r['category']}`{member_tag}{marker}{exp}\n"
                f"{str(item.get('descripcion','Sin descripción.'))[:190]}\n"
                f"Acción sugerida: {use_hint}"
            )[:1024],
            inline=False,
        )
    embed.set_footer(text=f"Página {page}/{max_page} · filtros: all, miembro, cosmetico, consumible, boost · 3.1.0")
    return embed, max_page, filtro


class V14InventoryView(discord.ui.View):
    def __init__(self, ctx, member, page=1, filtro="all"):
        super().__init__(timeout=150)
        self.ctx = ctx
        self.member = member
        self.page = int(page or 1)
        self.filtro = filtro
        self.add_item(V14InventoryFilterSelect(self))

    async def _guard(self, interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("Este inventario lo abrió otra persona.", ephemeral=True)
            return False
        return True

    async def _redraw(self, interaction):
        embed, max_page, filtro = _v14_inventory_embed(self.ctx, self.member, self.page, self.filtro)
        self.page = max(1, min(self.page, max_page)); self.filtro = filtro
        await interaction.response.edit_message(embed=embed, view=self)

    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary)
    async def prev_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction): return
        self.page = max(1, self.page - 1)
        await self._redraw(interaction)

    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary)
    async def next_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction): return
        self.page += 1
        await self._redraw(interaction)

    @discord.ui.button(label="Cosméticos", emoji="✨", style=discord.ButtonStyle.primary)
    async def cosmetics_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._guard(interaction): return
        self.filtro = "cosmetico"; self.page = 1
        await self._redraw(interaction)


class V14InventoryFilterSelect(discord.ui.Select):
    def __init__(self, parent):
        self.parent_view = parent
        opts = [
            discord.SelectOption(label="Todo", value="all", emoji="🌌"),
            discord.SelectOption(label="Miembro", value="miembro", emoji="💎"),
            discord.SelectOption(label="Cosméticos", value="cosmetico", emoji="✨"),
            discord.SelectOption(label="Consumibles", value="consumible", emoji="🎟️"),
            discord.SelectOption(label="Boosts", value="boost", emoji="⚡"),
        ]
        super().__init__(placeholder="Filtrar inventario", min_values=1, max_values=1, options=opts)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.parent_view.ctx.author.id:
            await interaction.response.send_message("Este filtro no es tuyo.", ephemeral=True)
            return
        self.parent_view.filtro = self.values[0]
        self.parent_view.page = 1
        await self.parent_view._redraw(interaction)


