@bot.command(name="topmiembros", aliases=["membertop", "rankmiembros"])
@commands.cooldown(1, 10, commands.BucketType.guild)
async def topmiembros_cmd_v14(ctx):
    datos = cargar_datos()
    ranking = []
    for uid, info in datos.items():
        try:
            m = ctx.guild.get_member(int(uid))
        except Exception:
            m = None
        if not m or not _v13_has_member_access(m):
            continue
        stats = info.get("member_stats", {}) if isinstance(info.get("member_stats", {}), dict) else {}
        score = int(info.get("nivel", 1) or 1) * 1000 + int(info.get("reputacion", 0) or 0) * 80 + int(stats.get("earned", 0) or 0) // 10
        ranking.append((score, m, info, stats))
    ranking.sort(key=lambda x: x[0], reverse=True)
    embed = discord.Embed(title="🏆 Top Miembros Aether", color=discord.Color.gold())
    if not ranking:
        embed.description = "No hay miembros puntuables todavía."
    for idx, (score, m, info, stats) in enumerate(ranking[:10], 1):
        embed.add_field(name=f"#{idx} · {m.display_name}", value=f"Nivel **{info.get('nivel',1)}** · Rep **{info.get('reputacion',0)}** · Ganado **{_v13_money(stats.get('earned',0))}** · score `{score}`", inline=False)
    await ctx.send(embed=embed)

