# @bot.command(name="cristalflip", aliases=["flipcristal", "memberflip"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 8, commands.BucketType.user)
async def cristalflip_cmd_v14(ctx, apuesta: str = "100"):
    if not await _v13_require_member(ctx): return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    cantidad = _v13_parse_amount(apuesta, datos[uid].get("cash", 0))
    cantidad = min(cantidad, 25000)
    if cantidad <= 0 or datos[uid].get("cash", 0) < cantidad:
        await ctx.reply("Apuesta inválida o cash insuficiente.", mention_author=False); return
    msg = await ctx.send("🪙 **Cristal Flip** · lanzando moneda amatista... `░░░░░░`")
    for frame in ("▰░░░░░", "▰▰░░░░", "▰▰▰░░░", "▰▰▰▰░░", "▰▰▰▰▰░", "▰▰▰▰▰▰"):
        await asyncio.sleep(0.35)
        try: await msg.edit(content=f"🪙 **Cristal Flip** · calculando destino... `{frame}`")
        except Exception: pass
    win = random.random() < 0.53
    if win:
        premio = int(cantidad * random.uniform(1.65, 2.15))
        agregar_a_cash_y_monedas(datos, uid, premio - cantidad)
        stats = _v13_member_stats(datos, uid)
        today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
        if stats.get("plays_today_date") != today:
            stats["plays_today_date"] = today; stats["plays_today"] = 0
        stats["plays"] = int(stats.get("plays", 0) or 0) + 1
        stats["plays_today"] = int(stats.get("plays_today", 0) or 0) + 1
        stats["wins"] = int(stats.get("wins", 0) or 0) + 1
        stats["earned"] = int(stats.get("earned", 0) or 0) + int(premio - cantidad)
        color = discord.Color.green(); title = "💎 Cristal brillante"
        desc = f"Apostaste **{_v13_money(cantidad)}** y ganaste **{_v13_money(premio - cantidad)}** neto {amatista}."
    else:
        restar_de_cash(datos, uid, cantidad)
        stats = _v13_member_stats(datos, uid)
        today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
        if stats.get("plays_today_date") != today:
            stats["plays_today_date"] = today; stats["plays_today"] = 0
        stats["plays"] = int(stats.get("plays", 0) or 0) + 1
        stats["plays_today"] = int(stats.get("plays_today", 0) or 0) + 1
        color = discord.Color.red(); title = "🪨 Cristal apagado"
        desc = f"Perdiste **{_v13_money(cantidad)}** {amatista}. El cristal se quedó sin brillo."
    guardar_datos(datos)
    await msg.edit(content=None, embed=_v13_member_embed(title, desc, color, ctx.author))


@bot.command(name="codigomorado", aliases=["purplecode", "codemember"])
@commands.cooldown(1, 12, commands.BucketType.user)
async def codigomorado_cmd_v14(ctx):
    if not await _v13_require_member(ctx): return
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    sequence = random.sample(["💎", "🔮", "🟣", "⚡", "🌌"], 4)
    fake = " ".join(sequence)
    msg = await ctx.send(f"🧩 **Código Morado**\nMemoriza: **{fake}**")
    await asyncio.sleep(3)
    try: await msg.edit(content="🧩 **Código Morado**\nSe cerró el panel. Responde con los emojis en el mismo orden. Tienes 12s.")
    except Exception: pass
    def check(m):
        return m.author.id == ctx.author.id and m.channel.id == ctx.channel.id
    try:
        m = await bot.wait_for("message", check=check, timeout=12)
        ok = " ".join(m.content.split()) == fake
    except asyncio.TimeoutError:
        ok = False
    if ok:
        premio = random.randint(700, 1500) + _v13_level(uid, datos) * 30
        agregar_a_cash_y_monedas(datos, uid, premio)
        stats = _v13_member_stats(datos, uid)
        today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
        if stats.get("plays_today_date") != today:
            stats["plays_today_date"] = today; stats["plays_today"] = 0
        stats["plays"] = int(stats.get("plays", 0) or 0) + 1
        stats["plays_today"] = int(stats.get("plays_today", 0) or 0) + 1
        stats["wins"] = int(stats.get("wins", 0) or 0) + 1
        stats["earned"] = int(stats.get("earned", 0) or 0) + int(premio)
        desc = f"Código correcto. Ganaste **{_v13_money(premio)}** {amatista}."
        color = discord.Color.green()
    else:
        stats = _v13_member_stats(datos, uid)
        today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
        if stats.get("plays_today_date") != today:
            stats["plays_today_date"] = today; stats["plays_today"] = 0
        stats["plays"] = int(stats.get("plays", 0) or 0) + 1
        stats["plays_today"] = int(stats.get("plays_today", 0) or 0) + 1
        desc = f"Código fallido. La secuencia era: **{fake}**"
        color = discord.Color.red()
    guardar_datos(datos)
    await ctx.send(embed=_v13_member_embed("🧩 Código Morado", desc, color, ctx.author))


