def _v15_load(path, default=None):
    try:
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                data=json.load(f); return data if data is not None else (default or {})
    except Exception as e:
        print(f"[3.1.0 LOAD] {path}: {e}")
    return default or {}

def _v15_save(path, data):
    try:
        with open(path, 'w', encoding='utf-8') as f: json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[3.1.0 SAVE] {path}: {e}")

def _v15_money(n):
    try: return f"{int(n):,}".replace(',', '.')
    except Exception: return str(n)

def _v15_embed(title, description='', color=V15_PURPLE, member=None):
    e=discord.Embed(title=title, description=description, color=discord.Color(color), timestamp=datetime.datetime.utcnow())
    e.set_footer(text=f"{V15_VERSION} · estética amatista")
    if member:
        try: e.set_thumbnail(url=member.display_avatar.url)
        except Exception: pass
    return e

def _v15_level(info):
    try: return max(1, int(info.get('nivel',1) or 1))
    except Exception: return 1

def _v15_xp_need(level):
    try: return max(100, _xp_needed_for_level(int(level)))
    except Exception: return max(100, 100 + (int(level)-1)*50)

def _v15_bar(v, m, size=18):
    m=max(1,int(m or 1)); v=max(0,min(int(v or 0),m)); fill=round(v/m*size)
    return '▰'*fill + '▱'*(size-fill)

def _v15_rep_value(info):
    try: return max(0, int(info.get('reputacion',0) or 0))
    except Exception: return 0

V15_REP_TIERS=[(0,'Cuarzo Gris','⚪',1.00),(5,'Chispa Amatista','🟣',1.02),(10,'Voz Confiable','🔵',1.04),(20,'Aliado del Servidor','💠',1.07),(35,'Guardián Social','🛡️',1.10),(50,'Aura Cristal','✨',1.14),(75,'Leyenda Cercana','🌟',1.18),(100,'Embajador Aether','👑',1.24),(150,'Oráculo Violeta','🔮',1.32),(250,'Mito del Servidor','🐉',1.45),(400,'Constelación Viva','🌌',1.60),(650,'Deidad Amatista','💎',1.80),(1000,'Núcleo Inmortal','⚛️',2.05)]

def _v15_rep_tier(rep):
    cur=V15_REP_TIERS[0]
    for t in V15_REP_TIERS:
        if rep>=t[0]: cur=t
    return cur

def _v15_next_rep_tier(rep):
    for t in V15_REP_TIERS:
        if rep<t[0]: return t
    return None

def _v15_member(member):
    try: return bool(_v13_has_member_access(member))
    except Exception: pass
    if not member: return False
    if getattr(member.guild_permissions,'administrator',False): return True
    return any(str(r.name).lower().strip() in {'miembro','member','vip','premium','royal member'} for r in getattr(member,'roles',[]))

async def _v15_require_member(ctx):
    if _v15_member(ctx.author): return True
    await ctx.reply(embed=_v15_embed('🔒 Club de miembros','Necesitas el rol **Miembro** para usar este comando. Los comandos globales siguen disponibles.',V15_RED,ctx.author), mention_author=False)
    return False

def _v15_find_item(q):
    q=str(q or '').strip().lower()
    if not q: return None,None
    if q in TIENDA_ITEMS: return q, TIENDA_ITEMS[q]
    for iid,it in TIENDA_ITEMS.items():
        if q in {iid.lower(), str(it.get('tipo','')).lower(), str(it.get('nombre','')).lower()}: return iid,it
    for iid,it in TIENDA_ITEMS.items():
        if q in iid.lower() or q in str(it.get('nombre','')).lower(): return iid,it
    return None,None

def _v15_find_type(t):
    for iid,it in TIENDA_ITEMS.items():
        if str(it.get('tipo',iid))==str(t) or iid==t: return iid,it
    return None,None

def _v15_rarity(it): return str(it.get('rareza','normal')).lower()
def _v15_rarity_icon(it): return {'común':'⚪','normal':'⚪','raro':'🔵','épico':'🟣','legendario':'🟡','mítico':'🔴'}.get(_v15_rarity(it),'💎')
def _v15_min_level(it):
    try: return max(1,int(it.get('nivel_min',1) or 1))
    except Exception: return 1
def _v15_min_rep(it):
    try: return max(0,int(it.get('rep_min',0) or 0))
    except Exception: return 0

def _v15_inventory(info):
    inv=info.get('items',{})
    if not isinstance(inv,dict): inv={}; info['items']=inv
    return inv

def _v15_equipped(info):
    eq=info.get('equipado',{})
    if not isinstance(eq,dict): eq={}; info['equipado']=eq
    return eq

def _v15_has_item(info,iid,it):
    inv=_v15_inventory(info); key=str(it.get('tipo',iid))
    return iid in inv or key in inv

def _v15_price(it, info, member=None):
    if it.get('rep_shop') and int(it.get('precio',0) or 0)<=1: return 1
    base=int(it.get('precio_base',it.get('precio',0)) or 0)
    level=min(_v15_level(info),V15_MAX_PRICE_LEVEL); rep=_v15_rep_value(info)
    rarity={'común':0,'normal':0,'raro':0.04,'épico':0.08,'legendario':0.14,'mítico':0.22}.get(_v15_rarity(it),0)
    scale=1+(level-1)*V15_LEVEL_PRICE_GROWTH+rarity+max(0,_v15_min_level(it)-1)*0.006
    discount=min(0.18,(_v15_rep_tier(rep)[3]-1)*0.11)
    if it.get('member_only') and member and _v15_member(member): scale*=0.94
    return max(1,int(round(base*max(0.65,scale-discount)/10)*10))

def _v15_unlock(info,it,member=None):
    if it.get('member_only') and not (member and _v15_member(member)): return False,'requiere rol Miembro'
    if _v15_level(info)<_v15_min_level(it): return False,f"requiere nivel {_v15_min_level(it)}"
    if _v15_rep_value(info)<_v15_min_rep(it): return False,f"requiere {_v15_min_rep(it)} rep"
    return True,'desbloqueado'

def _v15_shop_line(iid,it,info,member=None):
    ok,why=_v15_unlock(info,it,member); owned=_v15_has_item(info,iid,it); marker='✅' if owned else ('🟢' if ok else '🔒')
    price='rep shop' if it.get('rep_shop') else f"{_v15_money(_v15_price(it,info,member))} {globals().get('amatista','💎')}"
    rep=f" · rep {_v15_min_rep(it)}" if _v15_min_rep(it) else ''
    mem=' · 💎 member' if it.get('member_only') else ''
    slot=f" · `{it.get('slot')}`" if it.get('slot') else ''
    return f"{marker} `{iid}` · {it.get('emoji','💎')} **{it.get('nombre',iid)}**\n{_v15_rarity_icon(it)} {it.get('rareza','normal')} · nivel {_v15_min_level(it)}{rep}{mem}{slot} · **{price}**\n╰ {str(it.get('descripcion','Objeto premium'))[:95]}"

def _v15_add_xp(datos,uid,amount):
    asegurar_usuario(datos,uid); info=datos[uid]; amount=max(0,int(amount or 0)); info['experiencia']=int(info.get('experiencia',0) or 0)+amount
    levels=0; reward=0
    while info['experiencia']>=_v15_xp_need(_v15_level(info)):
        need=_v15_xp_need(_v15_level(info)); info['experiencia']-=need; info['nivel']=_v15_level(info)+1; levels+=1; bonus=75+info['nivel']*12; reward+=bonus; agregar_a_cash_y_monedas(datos,uid,bonus)
    return levels,reward

