# @bot.command(name='bal', aliases=['balance','saldo','cartera'])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1,4,commands.BucketType.user)
async def bal_cmd_v15(ctx, miembro: discord.Member=None):
    miembro=miembro or ctx.author; d=cargar_datos(); uid=str(miembro.id); asegurar_usuario(d,uid); info=d[uid]
    lvl=_v15_level(info); xp=int(info.get('experiencia',0) or 0); need=_v15_xp_need(lvl); rep=_v15_rep_value(info); tier=_v15_rep_tier(rep); nxt=_v15_next_rep_tier(rep)
    total=int(info.get('cash',0) or 0)+int(info.get('bank',0) or 0); rank=obtener_rank_por_monedas(d,uid) or 'N/A'
    e=_v15_embed(f'💎 Balance Galáctico · {miembro.display_name}', member=miembro)
    e.description=f"╭─ **Cartera amatista**\n├ 💰 Cash: **{_v15_money(info.get('cash',0))}** {globals().get('amatista','💎')}\n├ 🏦 Banco: **{_v15_money(info.get('bank',0))}** {globals().get('amatista','💎')}\n├ 💠 Total: **{_v15_money(total)}** {globals().get('amatista','💎')}\n╰ 🏆 Ranking: **#{rank}**"
    e.add_field(name='⭐ Nivel y XP', value=f"Nivel **{lvl}**\n`{_v15_bar(xp,need,20)}`\n{_v15_money(xp)}/{_v15_money(need)} XP", inline=False)
    rep_txt=f"{tier[2]} **{tier[1]}** · {rep} rep"
    if nxt: rep_txt+=f"\nSiguiente: **{nxt[1]}** en **{nxt[0]-rep}** rep"
    e.add_field(name='✨ Reputación', value=rep_txt+'\n`!rep` · `!repclaim` · `!repshop`', inline=True)
    e.add_field(name='🛒 Atajos', value='`!tienda mi` · `!shoptiers` · `!fondosnivel` · `!inv`', inline=True)
    await ctx.send(embed=e)

