# @bot.command(name='inventario', aliases=['inv','mochila','items'])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1,4,commands.BucketType.user)
async def inv_cmd_v15(ctx, filtro: str='all', pagina: int=1):
    if str(filtro).isdigit(): pagina=int(filtro); filtro='all'
    d=cargar_datos(); uid=str(ctx.author.id); asegurar_usuario(d,uid); info=d[uid]; inv=_v15_inventory(info); eq=set(_v15_equipped(info).values()); filtro=str(filtro or 'all').lower()
    rows=[]
    for key,rec in inv.items():
        iid,it=_v15_find_type(key)
        if not it: iid=str(key); it={'nombre':str(key),'emoji':'📦','categoria':'otros','rareza':'normal','tipo':str(key)}
        cat=str(it.get('categoria','otros')).lower(); slot=str(it.get('slot','')).lower(); cons=bool(it.get('consumible') or (isinstance(rec,dict) and rec.get('consumible')))
        if filtro not in {'all','todo','todos'}:
            if filtro in {'cosmetico','cosmeticos','cosmético','cosméticos'} and not slot: continue
            if filtro in {'consumible','consumibles'} and not cons: continue
            if filtro in {'member','miembro'} and not it.get('member_only'): continue
            if filtro not in {cat,slot,'cosmetico','cosmeticos','consumible','consumibles','member','miembro'}: continue
        qty=int(rec.get('cantidad',1) or 1) if isinstance(rec,dict) else 1; equipped=' · **EQUIPADO**' if str(it.get('tipo',iid)) in eq or iid in eq else ''
        rows.append(f"{it.get('emoji','📦')} `{iid}` · **{it.get('nombre',iid)}** x{qty}\n{_v15_rarity_icon(it)} {it.get('rareza','normal')} · {cat}{' · '+slot if slot else ''}{equipped}")
    rows.sort(); per=8; total=max(1,(len(rows)+per-1)//per); pagina=max(1,min(int(pagina or 1),total)); shown=rows[(pagina-1)*per:pagina*per]
    e=_v15_embed(f'🎒 Inventario Galáctico · {ctx.author.display_name}', member=ctx.author)
    e.description=f"Filtro `{filtro}` · Objetos **{len(rows)}** · Página **{pagina}/{total}**\n`!inv cosmetico` · `!inv consumible` · `!inv miembro` · `!equipar <item>`"
    e.add_field(name='📦 Objetos', value='\n\n'.join(shown)[:1024] if shown else 'No hay objetos con ese filtro.', inline=False)
    e.add_field(name='🧭 Navegación', value=f"`!inv {filtro} {max(1,pagina-1)}` · `!inv {filtro} {min(total,pagina+1)}`", inline=False)
    await ctx.send(embed=e)

