# ──────────────────────────────────────────────────────────────────────────────
# Helpers premium 3.1.0
# ──────────────────────────────────────────────────────────────────────────────
def _amx_now() -> datetime.datetime:
    return datetime.datetime.utcnow()


def _amx_money(n) -> str:
    try:
        return f"{int(n):,}".replace(",", ".")
    except Exception:
        return "0"


def _amx_emoji_money() -> str:
    return str(globals().get("amatista", "💎"))


def _amx_embed(title: str, description: str = "", color: int | discord.Color = XAU_PUBLIC_PURPLE, member: discord.Member = None) -> discord.Embed:
    if isinstance(color, int):
        color = discord.Color(color)
    e = discord.Embed(title=title, description=description, color=color, timestamp=_amx_now())
    e.set_footer(text=f"{XAU_PUBLIC_VERSION_NAME} · panel amatista")
    if member:
        try:
            e.set_thumbnail(url=member.display_avatar.url)
        except Exception:
            pass
    return e


def _amx_level(info: dict) -> int:
    try:
        return max(1, int(info.get("nivel", 1) or 1))
    except Exception:
        return 1


def _amx_xp_needed(level: int) -> int:
    try:
        return max(100, _xp_needed_for_level(int(level)))
    except Exception:
        return max(100, 100 + (int(level or 1) - 1) * 50)


def _amx_rep(info: dict) -> int:
    try:
        return max(0, int(info.get("reputacion", 0) or 0))
    except Exception:
        return 0


def _amx_inventory(info: dict) -> dict:
    inv = info.get("items")
    if not isinstance(inv, dict):
        inv = {}
        info["items"] = inv
    return inv


def _amx_equipped(info: dict) -> dict:
    eq = info.get("equipado")
    if not isinstance(eq, dict):
        eq = {}
        info["equipado"] = eq
    return eq


def _amx_item_type(item_id: str, item: dict) -> str:
    return str(item.get("tipo", item_id))


def _amx_find_item(query: str):
    q = str(query or "").strip().lower()
    if not q:
        return None, None
    if q in TIENDA_ITEMS:
        return q, TIENDA_ITEMS[q]
    for item_id, item in TIENDA_ITEMS.items():
        aliases = {
            item_id.lower(),
            str(item.get("tipo", "")).lower(),
            str(item.get("nombre", "")).lower(),
        }
        if q in aliases:
            return item_id, item
    for item_id, item in TIENDA_ITEMS.items():
        if q in item_id.lower() or q in str(item.get("nombre", "")).lower():
            return item_id, item
    return None, None


def _amx_has_item(info: dict, item_id: str, item: dict) -> bool:
    inv = _amx_inventory(info)
    typ = _amx_item_type(item_id, item)
    return item_id in inv or typ in inv


def _amx_min_level(item: dict) -> int:
    try:
        return max(1, int(item.get("nivel_min", 1) or 1))
    except Exception:
        return 1


def _amx_min_rep(item: dict) -> int:
    try:
        return max(0, int(item.get("rep_min", 0) or 0))
    except Exception:
        return 0


def _amx_rarity(item: dict) -> str:
    return str(item.get("rareza", "normal")).lower()


def _amx_rarity_icon(item: dict) -> str:
    return {
        "común": "⚪", "normal": "⚪", "raro": "🔵", "épico": "🟣",
        "legendario": "🟡", "mítico": "🔴", "divino": "💎", "exclusivo": "👑"
    }.get(_amx_rarity(item), "💎")


def _amx_slot_for_item(item_id: str, item: dict) -> str | None:
    slot = item.get("slot")
    if slot:
        return str(slot)
    typ = str(item.get("tipo", item_id)).lower()
    cat = str(item.get("categoria", "")).lower()
    if "lvl" in typ and "marco" in typ:
        return "lvl_marco"
    if "lvl" in typ or "xpcard" in typ or "xp_card" in typ or cat in {"nivel", "xp card", "xpcard"}:
        return "lvl_fondo"
    if "marco" in typ:
        return "lvl_marco"
    if "titulo" in typ:
        return "titulo"
    if "placa" in typ or "badge" in typ:
        return "placa"
    if "mascota" in typ:
        return "mascota"
    if "firma" in typ:
        return "firma"
    if "fondo" in typ:
        return "fondo"
    return None


def _amx_unlock(info: dict, item: dict) -> tuple[bool, str]:
    lvl = _amx_level(info)
    rep = _amx_rep(info)
    if lvl < _amx_min_level(item):
        return False, f"nivel {_amx_min_level(item)} requerido"
    if rep < _amx_min_rep(item):
        return False, f"{_amx_min_rep(item)} rep requerida"
    if item.get("member_only") and not _amx_is_member_cached_info(info):
        return False, "requiere club miembro"
    return True, "desbloqueado"


def _amx_price(item: dict, info: dict, member: discord.Member = None) -> int:
    base = int(item.get("precio_base", item.get("precio", 0)) or 0)
    lvl = min(_amx_level(info), 200)
    rarity_bonus = {
        "común": 0.00, "normal": 0.00, "raro": 0.04, "épico": 0.08,
        "legendario": 0.13, "mítico": 0.19, "divino": 0.27, "exclusivo": 0.34,
    }.get(_amx_rarity(item), 0.02)
    min_level_bonus = max(0, _amx_min_level(item) - 1) * 0.004
    rep_discount = min(0.18, _amx_rep(info) / 9000)
    member_discount = 0.07 if member and amx_is_member(member) else 0
    scaled = base * (1 + (lvl - 1) * 0.018 + rarity_bonus + min_level_bonus - rep_discount - member_discount)
    return int(max(1, round(scaled / 10) * 10))


def _amx_progress(value: int, maximum: int, size: int = 22, fill="▰", empty="▱") -> str:
    maximum = max(1, int(maximum or 1))
    value = max(0, min(int(value or 0), maximum))
    done = min(size, int(round(value / maximum * size)))
    return fill * done + empty * (size - done)


def _amx_paged(lines: list[str], per: int) -> list[list[str]]:
    return [lines[i:i + per] for i in range(0, len(lines), per)] or [[]]


def _amx_user_item_state(info: dict, item_id: str, item: dict) -> str:
    owned = _amx_has_item(info, item_id, item)
    unlocked, why = _amx_unlock(info, item)
    if owned:
        return "✅ comprado"
    if unlocked:
        return "🟢 disponible"
    return f"🔒 bloqueado · {why}"


def _amx_item_line(item_id: str, item: dict, info: dict, member: discord.Member = None, compact=False) -> str:
    state = _amx_user_item_state(info, item_id, item)
    price = _amx_price(item, info, member)
    slot = _amx_slot_for_item(item_id, item)
    desc = str(item.get("descripcion", "Objeto premium del catálogo.")).strip()
    if compact:
        return f"{state} · `{item_id}` · {item.get('emoji','💎')} **{item.get('nombre', item_id)}** · {_amx_money(price)} {_amx_emoji_money()}"
    return (
        f"{state}\n"
        f"{item.get('emoji','💎')} `{item_id}` · **{item.get('nombre', item_id)}**\n"
        f"{_amx_rarity_icon(item)} {item.get('rareza','normal')} · nivel `{_amx_min_level(item)}` · rep `{_amx_min_rep(item)}` · precio **{_amx_money(price)}** {_amx_emoji_money()}"
        f"{f' · slot `{slot}`' if slot else ''}\n"
        f"╰ {desc[:110]}{'...' if len(desc) > 110 else ''}"
    )


def _amx_is_member_cached_info(info: dict) -> bool:
    return bool(info.get("member_cache", False))


def amx_is_member(member: discord.Member) -> bool:
    try:
        if member.guild_permissions.administrator:
            return True
    except Exception:
        pass
    try:
        custom_id = globals().get("MEMBER_ROLE_ID") or globals().get("ROL_MIEMBRO_ID") or globals().get("MIEMBRO_ROLE_ID")
        if custom_id:
            role = member.guild.get_role(int(custom_id))
            if role and role in member.roles:
                return True
    except Exception:
        pass
    names = {"miembro", "member", "members", "premium", "royal member", "aether", "vip"}
    try:
        return any(str(r.name).strip().lower() in names for r in member.roles)
    except Exception:
        return False


def _amx_update_member_cache(info: dict, member: discord.Member):
    try:
        info["member_cache"] = bool(amx_is_member(member))
    except Exception:
        pass


def _amx_load_json(path: str, default):
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data if isinstance(data, type(default)) else default
    except Exception as exc:
        print(f"[X AETHER 3.1.0 LOAD] {path}: {exc}")
    return default


def _amx_save_json(path: str, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"[X AETHER 3.1.0 SAVE] {path}: {exc}")


def _amx_add_cash(datos: dict, uid: str, amount: int):
    try:
        agregar_a_cash_y_monedas(datos, uid, int(amount))
    except Exception:
        asegurar_usuario(datos, uid)
        datos[uid]["cash"] = int(datos[uid].get("cash", 0) or 0) + int(amount)


def agregar_xp(datos: dict, uid: str, amount: int):
    """Fallback estable para sumar XP aunque el bloque viejo no exista."""
    asegurar_usuario(datos, str(uid))
    user = datos[str(uid)]
    user["experiencia"] = int(user.get("experiencia", 0) or 0) + int(amount)
    while user["experiencia"] >= max(100, int(user.get("nivel", 1) or 1) * 100):
        need = max(100, int(user.get("nivel", 1) or 1) * 100)
        user["experiencia"] -= need
        user["nivel"] = int(user.get("nivel", 1) or 1) + 1


def _amx_add_xp(datos: dict, uid: str, amount: int):
    try:
        agregar_xp(datos, uid, int(amount))
    except Exception:
        asegurar_usuario(datos, uid)
        datos[uid]["experiencia"] = int(datos[uid].get("experiencia", 0) or 0) + int(amount)

