def _amx_level_style(name: str):
    try:
        base = _v12_level_style(name)
    except Exception:
        base = {"colors": [(17, 14, 45), (70, 35, 130)], "accent": (185, 120, 255), "glow": (130, 80, 255)}
    return XAU_PUBLIC_LEVEL_STYLES.get(str(name or "").lower(), base)


def _amx_get_equipped_item(info: dict, slot: str):
    value = _amx_equipped(info).get(slot)
    if not value:
        return None, None
    for item_id, item in TIENDA_ITEMS.items():
        if str(item.get("tipo", item_id)) == str(value) or str(item_id) == str(value):
            return item_id, item
    return None, None


async def _amx_xp_card_file(ctx, miembro: discord.Member, datos: dict, preview_item: dict = None):
    if not Image or not ImageDraw or not ImageFilter:
        return None
    uid = str(miembro.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    lvl = _amx_level(info)
    xp = int(info.get("experiencia", 0) or 0)
    needed = _amx_xp_needed(lvl)
    pct = max(0.0, min(1.0, xp / max(1, needed)))
    fondo_id, fondo_item = _amx_get_equipped_item(info, "lvl_fondo")
    marco_id, marco_item = _amx_get_equipped_item(info, "lvl_marco")
    titulo_id, titulo_item = _amx_get_equipped_item(info, "titulo")
    mascota_id, mascota_item = _amx_get_equipped_item(info, "mascota")
    placa_id, placa_item = _amx_get_equipped_item(info, "placa")
    if preview_item and _amx_slot_for_item("preview", preview_item) == "lvl_fondo":
        fondo_item = preview_item
    elif preview_item and _amx_slot_for_item("preview", preview_item) == "lvl_marco":
        marco_item = preview_item
    style = _amx_level_style((fondo_item or {}).get("level_style", "base"))
    accent = style.get("accent", (185, 120, 255))
    glow = style.get("glow", accent)
    W, H = 1480, 540
    bg = _level_gradient((W, H), style.get("colors", [(17, 14, 45), (70, 35, 130)])).convert("RGBA")
    deco = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    dd = ImageDraw.Draw(deco)
    for i in range(26):
        x = (i * 179 + 30) % W
        y = (i * 97 + 60) % H
        r = 45 + (i % 6) * 18
        dd.ellipse((x-r, y-r, x+r, y+r), fill=(*glow, 18))
    for y in range(58, H, 72):
        dd.line((70, y, W-70, y), fill=(*accent, 23), width=2)
    bg = Image.alpha_composite(bg, deco.filter(ImageFilter.GaussianBlur(4)))
    draw = ImageDraw.Draw(bg)
    font_big = _level_font(62, True)
    font_title = _level_font(36, True)
    font_mid = _level_font(26, True)
    font_small = _level_font(20, False)
    font_tiny = _level_font(16, False)
    draw.rounded_rectangle((24, 24, W-24, H-24), radius=46, fill=(8, 10, 26, 168), outline=(*accent, 135), width=3)
    frame_color = (255, 220, 95, 240) if marco_item else (*accent, 220)
    if marco_item or preview_item:
        draw.rounded_rectangle((12, 12, W-12, H-12), radius=54, outline=frame_color, width=8)
    # avatar
    panel = (58, 72, 340, 466)
    draw.rounded_rectangle(panel, radius=36, fill=(255,255,255,24), outline=(255,255,255,44), width=1)
    av_size = 215
    av_pos = (92, 108)
    try:
        avatar_bytes = await miembro.display_avatar.replace(size=256, static_format="png").read()
        av = Image.open(io.BytesIO(avatar_bytes)).convert("RGBA").resize((av_size, av_size))
    except Exception:
        av = Image.new("RGBA", (av_size, av_size), (*accent, 255))
        ImageDraw.Draw(av).text((av_size//2-24, av_size//2-36), (miembro.display_name[:1] or "?").upper(), font=_level_font(76, True), fill=(20,20,35,255))
    mask = Image.new("L", (av_size, av_size), 0)
    ImageDraw.Draw(mask).ellipse((0,0,av_size-1,av_size-1), fill=255)
    shadow = Image.new("RGBA", (av_size+34, av_size+34), (0,0,0,0))
    ImageDraw.Draw(shadow).ellipse((10,10,av_size+24,av_size+24), fill=(0,0,0,145))
    shadow = shadow.filter(ImageFilter.GaussianBlur(10))
    bg.paste(shadow, (av_pos[0]-17, av_pos[1]-10), shadow)
    bg.paste(av, av_pos, mask)
    draw.ellipse((av_pos[0]-10, av_pos[1]-10, av_pos[0]+av_size+10, av_pos[1]+av_size+10), outline=(*accent, 245), width=8)
    draw.text((91, 352), "XP CARD 3.1.0", font=font_tiny, fill=(240,240,255,190))
    draw.text((91, 378), f"Nivel {lvl}", font=font_title, fill=(255,255,255,255))
    rank = obtener_rank_por_monedas(datos, uid) or "N/A"
    draw.text((91, 422), f"Rank #{rank}" if rank != "N/A" else "Rank N/A", font=font_small, fill=(238,238,250,225))
    # content
    draw.text((392, 78), miembro.display_name[:34], font=font_big, fill=(255,255,255,255))
    subtitle = f"{(titulo_item or {}).get('emoji','✨')} {(titulo_item or {}).get('nombre','Sin título equipado')}"
    draw.text((397, 150), subtitle[:76], font=font_mid, fill=(*accent,255))
    # level badge
    draw.rounded_rectangle((1210, 68, 1370, 168), radius=28, fill=(255,255,255,26), outline=(*accent,110), width=2)
    draw.text((1252, 85), "LEVEL", font=font_tiny, fill=(240,240,255,205))
    draw.text((1270 - max(0, len(str(lvl))-2)*12, 107), str(lvl), font=_level_font(46, True), fill=(255,255,255,255))
    # xp bar
    bar_x, bar_y, bar_w, bar_h = 397, 230, 920, 54
    draw.text((bar_x, bar_y-38), f"Experiencia · {_amx_money(xp)} / {_amx_money(needed)} XP", font=font_small, fill=(248,248,255,238))
    draw.text((bar_x+bar_w-190, bar_y-38), f"Faltan {_amx_money(max(0, needed-xp))}", font=font_tiny, fill=(235,235,250,210))
    fill_w = int(bar_w * pct)
    glow_layer = Image.new("RGBA", (W,H), (0,0,0,0))
    gd = ImageDraw.Draw(glow_layer)
    if fill_w:
        gd.rounded_rectangle((bar_x,bar_y,bar_x+fill_w,bar_y+bar_h), radius=27, fill=(*accent,220))
    bg.alpha_composite(glow_layer.filter(ImageFilter.GaussianBlur(8)))
    draw.rounded_rectangle((bar_x,bar_y,bar_x+bar_w,bar_y+bar_h), radius=27, fill=(255,255,255,22), outline=(255,255,255,42), width=1)
    if fill_w:
        draw.rounded_rectangle((bar_x,bar_y,bar_x+fill_w,bar_y+bar_h), radius=27, fill=(*accent,235))
    draw.text((bar_x+bar_w//2-32, bar_y+13), f"{int(pct*100)}%", font=font_mid, fill=(255,255,255,250))
    stats = [
        ("💰 Cash", _amx_money(info.get("cash",0))),
        ("🏦 Banco", _amx_money(info.get("bank",0))),
        ("✨ Rep", _amx_money(_amx_rep(info))),
        ("🎨 Cards", str(sum(1 for k,it in TIENDA_ITEMS.items() if _amx_slot_for_item(k,it) in {"lvl_fondo","lvl_marco"} and _amx_has_item(info,k,it))))
    ]
    sx, sy, sw, sh, gap = 397, 325, 214, 78, 20
    for idx, (label, val) in enumerate(stats):
        x1 = sx + idx*(sw+gap)
        draw.rounded_rectangle((x1, sy, x1+sw, sy+sh), radius=22, fill=(255,255,255,22), outline=(255,255,255,34), width=1)
        draw.text((x1+16, sy+13), label, font=font_tiny, fill=(235,235,250,220))
        draw.text((x1+16, sy+40), str(val), font=font_small, fill=(255,255,255,255))
    chips = []
    for item in [fondo_item, marco_item, titulo_item, mascota_item, placa_item]:
        if item:
            chips.append(f"{item.get('emoji','💎')} {item.get('nombre')}")
    chip = " · ".join(chips[:4]) or "Compra estilos en !xpcards y equipa con !equipar <item>"
    if preview_item:
        chip = f"👁️ PREVIEW · {preview_item.get('emoji','💎')} {preview_item.get('nombre')} · no hace falta comprar para probar visualmente"
    draw.rounded_rectangle((397, 434, 1318, 474), radius=18, fill=(255,255,255,18), outline=(255,255,255,24), width=1)
    draw.text((417, 445), chip[:122], font=font_tiny, fill=(255,255,255,220))
    draw.text((W-340, H-36), "X AETHER ULTRA 3.1.0 · XP CARD", font=font_tiny, fill=(255,255,255,145))
    buf = io.BytesIO()
    bg.save(buf, format="PNG")
    buf.seek(0)
    return discord.File(buf, filename=f"xpcard_2_0_0_{miembro.id}.png")


class AMXXPCardView(discord.ui.View):
    def __init__(self, ctx, member: discord.Member, page: int = 0, category: str = "all"):
        super().__init__(timeout=180)
        self.ctx = ctx
        self.member = member
        self.page = max(0, page)
        self.category = category
        self.add_item(AMXXPCardSelect(self))

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("💜 Este panel pertenece a otra persona. Usa `!xpcards` para abrir el tuyo.", ephemeral=True)
            return False
        return True

    def entries(self):
        datos = cargar_datos(); uid = str(self.member.id); asegurar_usuario(datos, uid); info = datos[uid]
        pool = [(k, v) for k, v in TIENDA_ITEMS.items() if _amx_slot_for_item(k, v) in {"lvl_fondo", "lvl_marco"}]
        if self.category == "owned":
            pool = [(k,v) for k,v in pool if _amx_has_item(info,k,v)]
        elif self.category == "locked":
            pool = [(k,v) for k,v in pool if not _amx_unlock(info,v)[0]]
        elif self.category == "available":
            pool = [(k,v) for k,v in pool if _amx_unlock(info,v)[0] and not _amx_has_item(info,k,v)]
        pool.sort(key=lambda kv: (_amx_min_level(kv[1]), _amx_min_rep(kv[1]), _amx_price(kv[1], info, self.member), kv[0]))
        return pool, info

    async def send_page(self, interaction: discord.Interaction = None):
        pool, info = self.entries()
        pages = _amx_paged(pool, XAU_PUBLIC_XP_CARD_PAGE_SIZE)
        self.page = max(0, min(self.page, len(pages)-1))
        shown = pages[self.page]
        embed = _amx_embed("🎴 XP Cards · Galería personalizable", member=self.member)
        embed.description = (
            f"Usuario: {self.member.mention}\n"
            f"Filtro: **{self.category}** · Página **{self.page+1}/{len(pages)}**\n"
            "Estado visible en cada card: ✅ comprado · 🟢 disponible · 🔒 bloqueado.\n"
            "Usa `!previewxp <id>` para ver una card antes de comprarla."
        )
        lines = [_amx_item_line(k, v, info, self.member) for k, v in shown]
        embed.add_field(name="🎨 Catálogo XP", value="\n\n".join(lines)[:1024] if lines else "No hay estilos en este filtro.", inline=False)
        embed.add_field(name="🧭 Comandos", value="`!xpcards owned` · `!xpcards available` · `!xpcards locked` · `!previewxp <id>` · `!equipar <id>`", inline=False)
        if interaction:
            await interaction.response.edit_message(embed=embed, view=self)
        else:
            await self.ctx.send(embed=embed, view=self)

    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary)
    async def prev_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page -= 1
        await self.send_page(interaction)

    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary)
    async def next_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page += 1
        await self.send_page(interaction)

    @discord.ui.button(label="Comprados", emoji="✅", style=discord.ButtonStyle.success)
    async def owned_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.category = "owned"; self.page = 0
        await self.send_page(interaction)

    @discord.ui.button(label="Disponibles", emoji="🟢", style=discord.ButtonStyle.primary)
    async def available_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.category = "available"; self.page = 0
        await self.send_page(interaction)

    @discord.ui.button(label="Bloqueadas", emoji="🔒", style=discord.ButtonStyle.danger)
    async def locked_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.category = "locked"; self.page = 0
        await self.send_page(interaction)


class AMXXPCardSelect(discord.ui.Select):
    def __init__(self, parent: AMXXPCardView):
        self.parent_view = parent
        pool, info = parent.entries()
        shown = _amx_paged(pool, XAU_PUBLIC_XP_CARD_PAGE_SIZE)[max(0, min(parent.page, max(0, (len(pool)-1)//XAU_PUBLIC_XP_CARD_PAGE_SIZE)))]
        options = []
        for item_id, item in shown[:25]:
            state = _amx_user_item_state(info, item_id, item)
            options.append(discord.SelectOption(label=str(item.get("nombre", item_id))[:90], value=item_id, description=f"{state} · nivel {_amx_min_level(item)}"[:100], emoji=item.get("emoji", "🎴")))
        if not options:
            options = [discord.SelectOption(label="Sin estilos", value="none", description="No hay XP Cards en esta página.")]
        super().__init__(placeholder="👁️ Previsualizar una XP Card de esta página", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        item_id = self.values[0]
        if item_id == "none":
            return await interaction.response.send_message("No hay estilos en esta página.", ephemeral=True)
        item = TIENDA_ITEMS.get(item_id)
        if not item:
            return await interaction.response.send_message("No encontré ese estilo.", ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        datos = cargar_datos()
        file = await _amx_xp_card_file(self.parent_view.ctx, interaction.user, datos, preview_item=item)
        embed = _amx_embed("👁️ Preview XP Card", f"{item.get('emoji','🎴')} **{item.get('nombre', item_id)}**\n`{item_id}`\n\nEstado: {_amx_user_item_state(datos[str(interaction.user.id)], item_id, item)}", member=interaction.user)
        if file:
            await interaction.followup.send(embed=embed, file=file, ephemeral=True)
        else:
            await interaction.followup.send(embed=embed, ephemeral=True)


