@commands.cooldown(1, 5, commands.BucketType.user)
async def lvl_cmd_200(ctx, miembro: discord.Member = None):
    miembro = miembro or ctx.author
    datos = cargar_datos(); uid = str(miembro.id); asegurar_usuario(datos, uid)
    file = await _amx_xp_card_file(ctx, miembro, datos)
    if file:
        await ctx.send(file=file)
        return
    info = datos[uid]
    lvl = _amx_level(info); xp = int(info.get("experiencia", 0) or 0); needed = _amx_xp_needed(lvl)
    embed = _amx_embed(f"⭐ XP Card · {miembro.display_name}", member=miembro)
    embed.add_field(name="Nivel", value=str(lvl), inline=True)
    embed.add_field(name="XP", value=f"{_amx_money(xp)}/{_amx_money(needed)}", inline=True)
    embed.add_field(name="Progreso", value=f"`{_amx_progress(xp, needed, 24)}`", inline=False)
    await ctx.send(embed=embed)


# # @bot.command(name="previewxp", aliases=["xpcardpreview", "previewnivel", "nivelpreview", "previewlvl"])  # clean core: decorador antiguo desactivado  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 6, commands.BucketType.user)
async def previewxp_cmd_200(ctx, *, item_query: str = None):
    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid)
    if item_query:
        item_id, item = _amx_find_item(item_query)
        if not item or _amx_slot_for_item(item_id, item) not in {"lvl_fondo", "lvl_marco"}:
            await ctx.send(embed=_amx_embed("❌ XP Card no encontrada", "Usa `!xpcards` para ver los IDs válidos.", XAU_PUBLIC_RED, ctx.author))
            return
        file = await _amx_xp_card_file(ctx, ctx.author, datos, preview_item=item)
        embed = _amx_embed("👁️ Preview XP Card", f"{item.get('emoji','🎴')} **{item.get('nombre', item_id)}**\nID: `{item_id}`\nEstado: {_amx_user_item_state(datos[uid], item_id, item)}", member=ctx.author)
        if file:
            await ctx.send(embed=embed, file=file)
        else:
            await ctx.send(embed=embed)
        return
    await lvl_cmd_200(ctx, ctx.author)


