async def xpcards_cmd_200(ctx, filtro: str = "all", pagina: int = 1):
    filtro = str(filtro or "all").lower()
    if filtro not in {"all", "owned", "comprados", "available", "disponibles", "locked", "bloqueados"}:
        filtro = "all"
