# Comandos globales decorados: tienda, comprar, equipar, balance, perfil, inv
# ──────────────────────────────────────────────────────────────────────────────
class AMXShopView(discord.ui.View):
    def __init__(self, ctx, categoria="home", page=0):
        super().__init__(timeout=180)
        self.ctx = ctx; self.categoria = categoria; self.page = max(0, page)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("🛒 Abre tu propia tienda con `!tienda`.", ephemeral=True)
            return False
        return True

    def pool(self):
        datos = cargar_datos(); uid=str(self.ctx.author.id); asegurar_usuario(datos,uid); info=datos[uid]; _amx_update_member_cache(info,self.ctx.author)
        cat = self.categoria
        items = list(TIENDA_ITEMS.items())
        if cat in {"home", "inicio", "destacados"}:
            items.sort(key=lambda kv:(0 if _amx_unlock(info, kv[1])[0] and not _amx_has_item(info,kv[0],kv[1]) else 1, _amx_min_level(kv[1]), _amx_price(kv[1],info,self.ctx.author)))
            items = items[:42]
        elif cat in {"owned", "comprados"}:
            items = [(k,v) for k,v in items if _amx_has_item(info,k,v)]
        elif cat in {"locked", "bloqueados"}:
            items = [(k,v) for k,v in items if not _amx_unlock(info,v)[0]]
        elif cat in {"available", "disponibles"}:
            items = [(k,v) for k,v in items if _amx_unlock(info,v)[0] and not _amx_has_item(info,k,v)]
        elif cat in {"miembro", "member"}:
            items = [(k,v) for k,v in items if v.get("member_only") or str(v.get("categoria","")).lower()=="miembro"]
        else:
            items = [(k,v) for k,v in items if str(v.get("categoria", "otros")).lower() == cat]
        items.sort(key=lambda kv:(_amx_min_level(kv[1]), _amx_min_rep(kv[1]), _amx_price(kv[1], info, self.ctx.author), kv[0]))
        return items, info

    async def render(self, interaction: discord.Interaction=None):
        items, info = self.pool(); pages=_amx_paged(items, 7); self.page=max(0,min(self.page,len(pages)-1)); shown=pages[self.page]
        embed=_amx_embed(f"🛒 Tienda 3.1.0 · {self.categoria}", member=self.ctx.author)
        embed.description=(
            f"Nivel **{_amx_level(info)}** · Rep **{_amx_rep(info)}** · Member **{'sí' if amx_is_member(self.ctx.author) else 'no'}** · Página **{self.page+1}/{len(pages)}**\n"
            "Precios dinámicos: suben con nivel, bajan ligeramente por reputación y miembro.\n"
            "Estados: ✅ comprado · 🟢 disponible · 🔒 bloqueado."
        )
        embed.add_field(name="💎 Catálogo", value="\n\n".join(_amx_item_line(k,v,info,self.ctx.author) for k,v in shown)[:1024] if shown else "No hay objetos aquí.", inline=False)
        embed.add_field(name="🧭 Filtros", value="`!tienda available` · `!tienda owned` · `!tienda locked` · `!tienda nivel` · `!tienda miembro` · `!xpcards`", inline=False)
        if interaction:
            await interaction.response.edit_message(embed=embed, view=self)
        else:
            await self.ctx.send(embed=embed, view=self)

    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary)
    async def prev_btn(self, interaction, button):
        self.page -= 1; await self.render(interaction)
    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary)
    async def next_btn(self, interaction, button):
        self.page += 1; await self.render(interaction)
    @discord.ui.button(label="Disponibles", emoji="🟢", style=discord.ButtonStyle.primary)
    async def available_btn(self, interaction, button):
        self.categoria="available"; self.page=0; await self.render(interaction)
    @discord.ui.button(label="Comprados", emoji="✅", style=discord.ButtonStyle.success)
    async def owned_btn(self, interaction, button):
        self.categoria="owned"; self.page=0; await self.render(interaction)
    @discord.ui.button(label="XP Cards", emoji="🎴", style=discord.ButtonStyle.secondary)
    async def xpcards_btn(self, interaction, button):
        await interaction.response.send_message("🎴 Abriendo galería XP Card... usa `!xpcards` para el panel completo.", ephemeral=True)


