# @bot.command(name="comprar", aliases=["buy"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 4, commands.BucketType.user)
async def comprar_cmd_200(ctx, *, item_query: str = None):
    if not item_query:
        return await ctx.send(embed=_amx_embed("🛒 Comprar", "Uso: `!comprar <id>`\nMira IDs en `!tienda` o `!xpcards`.", member=ctx.author))
    item_id, item = _amx_find_item(item_query)
    if not item:
        return await ctx.send(embed=_amx_embed("❌ Item no encontrado", "Usa `!tienda` para ver IDs válidos.", XAU_PUBLIC_RED, ctx.author))
    datos=cargar_datos(); uid=str(ctx.author.id); asegurar_usuario(datos,uid); info=datos[uid]; _amx_update_member_cache(info, ctx.author)
    ok, why = _amx_unlock(info, item)
    if not ok:
        return await ctx.send(embed=_amx_embed("🔒 Objeto bloqueado", f"{item.get('emoji','💎')} **{item.get('nombre',item_id)}** está bloqueado: **{why}**.", XAU_PUBLIC_RED, ctx.author))
    price=_amx_price(item, info, ctx.author)
    if int(info.get("cash",0) or 0) < price:
        return await ctx.send(embed=_amx_embed("💸 Cash insuficiente", f"Necesitas **{_amx_money(price)}** {_amx_emoji_money()} y tienes **{_amx_money(info.get('cash',0))}**.", XAU_PUBLIC_RED, ctx.author))
    if _amx_has_item(info,item_id,item) and not item.get("consumible") and not item.get("stackable"):
        return await ctx.send(embed=_amx_embed("✅ Ya comprado", f"Ya tienes **{item.get('nombre',item_id)}**. Usa `!equipar {item_id}`.", XAU_PUBLIC_GREEN, ctx.author))
    info["cash"] = int(info.get("cash",0) or 0) - price
    try:
        result = aplicar_item(datos, uid, item_id)
    except Exception:
        inv=_amx_inventory(info); key=_amx_item_type(item_id,item); rec=inv.setdefault(key,{"cantidad":0,"nombre":item.get("nombre",item_id),"categoria":item.get("categoria","item")}); rec["cantidad"]=int(rec.get("cantidad",0))+1; result="Item guardado en inventario."
    guardar_datos(datos)
    embed=_amx_embed("✅ Compra realizada", f"{item.get('emoji','💎')} **{item.get('nombre',item_id)}**\nPrecio: **{_amx_money(price)}** {_amx_emoji_money()}\n{result}", XAU_PUBLIC_GREEN, ctx.author)
    slot=_amx_slot_for_item(item_id,item)
    if slot: embed.add_field(name="🎨 Equipable", value=f"Slot `{slot}` · usa `!equipar {item_id}`.", inline=False)
    if item.get("consumible"): embed.add_field(name="🎁 Consumible", value=f"Úsalo con `!usar {item_id}`.", inline=False)
    await ctx.send(embed=embed)


# # @bot.command(name="equipar", aliases=["equip"])  # clean core: decorador antiguo desactivado  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 4, commands.BucketType.user)
async def equipar_cmd_200(ctx, *, item_query: str = None):
    if not item_query:
        return await ctx.send(embed=_amx_embed("🎨 Equipar cosmético", "Uso: `!equipar <item>`\nSlots: `lvl_fondo`, `lvl_marco`, `titulo`, `placa`, `mascota`, `firma`, `fondo`.", member=ctx.author))
    item_id, item = _amx_find_item(item_query)
    if not item:
        return await ctx.send(embed=_amx_embed("❌ No encontrado", "No encontré ese cosmético. Mira `!inv` o `!tienda`.", XAU_PUBLIC_RED, ctx.author))
    slot = _amx_slot_for_item(item_id, item)
    if not slot:
        return await ctx.send(embed=_amx_embed("📦 No equipable", "Ese objeto no tiene slot cosmético. Si es consumible, usa `!usar <item>`.", XAU_PUBLIC_RED, ctx.author))
    datos=cargar_datos(); uid=str(ctx.author.id); asegurar_usuario(datos,uid); info=datos[uid]
    if not _amx_has_item(info,item_id,item):
        return await ctx.send(embed=_amx_embed("🔒 No comprado", f"No tienes **{item.get('nombre',item_id)}**. Puedes verlo en `!tienda` o probarlo con `!previewxp {item_id}` si es XP Card.", XAU_PUBLIC_RED, ctx.author))
    ok, why = _amx_unlock(info,item)
    if not ok:
        return await ctx.send(embed=_amx_embed("🔒 Bloqueado", f"Aunque lo tengas, aún no lo puedes equipar: **{why}**.", XAU_PUBLIC_RED, ctx.author))
    eq=_amx_equipped(info); eq[slot]=_amx_item_type(item_id,item); guardar_datos(datos)
    embed=_amx_embed("✅ Cosmético equipado", f"{item.get('emoji','💎')} **{item.get('nombre',item_id)}** ahora está activo en `{slot}`.", XAU_PUBLIC_GREEN, ctx.author)
    embed.add_field(name="Vista rápida", value="`!perfil` · `!lvl` · `!xpcards owned`", inline=False)
    await ctx.send(embed=embed)


# @bot.command(name="desequipar", aliases=["unequip"])  # XAU310 deduplicado: comando antiguo desactivado
async def desequipar_cmd_200(ctx, slot: str = "all"):
    datos=cargar_datos(); uid=str(ctx.author.id); asegurar_usuario(datos,uid); eq=_amx_equipped(datos[uid])
    if str(slot).lower() in {"all","todo","todos"}:
        eq.clear(); msg="Se quitaron todos los cosméticos."
    else:
        old=eq.pop(str(slot), None); msg=f"Slot `{slot}` liberado." if old else f"No había nada equipado en `{slot}`."
    guardar_datos(datos)
    await ctx.send(embed=_amx_embed("🧼 Estilo actualizado", msg, member=ctx.author))


