class AMXInventoryView(discord.ui.View):
    def __init__(self, ctx, member, page=0, filtro="all"):
        super().__init__(timeout=180); self.ctx=ctx; self.member=member; self.page=max(0,page); self.filtro=filtro
    async def interaction_check(self, interaction):
        if interaction.user.id != self.ctx.author.id:
            await interaction.response.send_message("🎒 Usa `!inv` para abrir tu inventario.", ephemeral=True); return False
        return True
    def entries(self):
        d=cargar_datos(); uid=str(self.member.id); asegurar_usuario(d,uid); info=d[uid]; inv=_amx_inventory(info); eq=_amx_equipped(info); lines=[]
        for key, rec in inv.items():
            iid,it=_amx_find_item(key)
            if not it:
                for k,x in TIENDA_ITEMS.items():
                    if str(x.get("tipo",k)) == str(key): iid,it=k,x; break
            if not it:
                it = rec if isinstance(rec,dict) else {"nombre":str(key),"emoji":"📦","categoria":"item","rareza":"normal"}; iid=str(key)
            slot=_amx_slot_for_item(iid,it) or ("consumible" if it.get("consumible") else str(it.get("categoria","item")))
            if self.filtro != "all" and self.filtro not in {slot, str(it.get("categoria","")).lower()}:
                if not (self.filtro == "cosmetico" and _amx_slot_for_item(iid,it)):
                    continue
            qty=int(rec.get("cantidad",1) if isinstance(rec,dict) else 1)
            equipped=" · **EQUIPADO**" if str(it.get("tipo",iid)) in eq.values() or iid in eq.values() else ""
            lines.append(f"{it.get('emoji','📦')} `{iid}` · **{it.get('nombre',iid)}** x{qty}\n{_amx_rarity_icon(it)} {it.get('rareza','normal')} · `{slot}`{equipped}")
        return sorted(lines), info
    async def render(self, interaction=None):
        lines, info=self.entries(); pages=_amx_paged(lines,8); self.page=max(0,min(self.page,len(pages)-1)); shown=pages[self.page]
        embed=_amx_embed(f"🎒 Inventario · {self.member.display_name}", member=self.member)
        embed.description=f"Filtro **{self.filtro}** · Página **{self.page+1}/{len(pages)}** · Objetos visibles **{len(lines)}**\nUsa `!equipar <item>` o `!usar <item>`."
        embed.add_field(name="📦 Objetos", value="\n\n".join(shown)[:1024] if shown else "Nada por aquí. Visita `!tienda`.", inline=False)
        if interaction: await interaction.response.edit_message(embed=embed, view=self)
        else: await self.ctx.send(embed=embed, view=self)
    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary)
    async def prev_btn(self, interaction, button): self.page-=1; await self.render(interaction)
    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary)
    async def next_btn(self, interaction, button): self.page+=1; await self.render(interaction)
    @discord.ui.button(label="Cosméticos", emoji="🎨", style=discord.ButtonStyle.primary)
    async def cos_btn(self, interaction, button): self.filtro="cosmetico"; self.page=0; await self.render(interaction)
    @discord.ui.button(label="Consumibles", emoji="🎁", style=discord.ButtonStyle.success)
    async def cons_btn(self, interaction, button): self.filtro="consumible"; self.page=0; await self.render(interaction)
    @discord.ui.button(label="Todo", emoji="📦", style=discord.ButtonStyle.secondary)
    async def all_btn(self, interaction, button): self.filtro="all"; self.page=0; await self.render(interaction)


