# Minijuegos 3.1.0: animaciones más limpias y recompensas
# ──────────────────────────────────────────────────────────────────────────────
def _amx_game_stats_record(uid: int, game: str, won: bool, delta: int, xp: int = 0):
    data=_amx_load_json(XAU_PUBLIC_GAME_STATS_FILE,{})
    u=data.setdefault(str(uid),{}); g=u.setdefault(game,{"partidas":0,"ganadas":0,"perdidas":0,"neto":0,"xp":0,"racha":0,"mejor_racha":0})
    g["partidas"]=int(g.get("partidas",0))+1
    if won:
        g["ganadas"]=int(g.get("ganadas",0))+1; g["racha"]=int(g.get("racha",0))+1; g["mejor_racha"]=max(int(g.get("mejor_racha",0)), int(g.get("racha",0)))
    else:
        g["perdidas"]=int(g.get("perdidas",0))+1; g["racha"]=0
    g["neto"]=int(g.get("neto",0))+int(delta); g["xp"]=int(g.get("xp",0))+int(xp)
    _amx_save_json(XAU_PUBLIC_GAME_STATS_FILE,data)


async def _amx_spin(ctx, title: str, frames: list[str], delay=0.42):
    msg=await ctx.send(f"{title}\n{frames[0]}")
    for fr in frames[1:]:
        await asyncio.sleep(delay)
        try: await msg.edit(content=f"{title}\n{fr}")
        except Exception: break
    return msg


