# @bot.command(name="slots", aliases=["maquina"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 6, commands.BucketType.user)
async def slots_cmd_200(ctx, apuesta: int = 100):
    apuesta=max(10,min(int(apuesta or 100),50000)); d=cargar_datos(); uid=str(ctx.author.id); asegurar_usuario(d,uid); info=d[uid]
    if int(info.get("cash",0) or 0)<apuesta: return await ctx.send(embed=_amx_embed("💸 Sin cash", f"Necesitas **{_amx_money(apuesta)}** {_amx_emoji_money()}.", XAU_PUBLIC_RED, ctx.author))
    icons=["💎","🍇","🔮","👑","🌌","7️⃣","🐉"]
    frames=["🎰 `| ? | ? | ? |`", "🎰 `| 💎 | ? | ? |`", "🎰 `| 💎 | 🔮 | ? |`", "🎰 `| ░ | ░ | ░ |`"]
    msg=await _amx_spin(ctx,"🎰 **Slots Aether girando...**",frames,0.35)
    roll=[random.choice(icons) for _ in range(3)]
    mult=0
    if len(set(roll))==1: mult=6 if roll[0] != "7️⃣" else 12
    elif len(set(roll))==2: mult=2
    delta=-apuesta
    if mult: delta=apuesta*mult-apuesta
    info["cash"]=int(info.get("cash",0) or 0)+delta
    xp=20+max(0,delta//200); _amx_add_xp(d,uid,xp); guardar_datos(d); _amx_game_stats_record(ctx.author.id,"slots",delta>0,delta,xp)
    result="GANASTE" if delta>0 else "perdiste"
