def construir_contexto_memoria(user_id: int) -> str:
    recuerdos = obtener_memoria_usuario(user_id)
    if not recuerdos:
        return "\n[Memoria AETHER 3.1.0]\nSin recuerdos útiles todavía.\n"
    cleaned=[]; seen=set()
    for rec in recuerdos[-120:]:
        r=str(rec).strip()
        if len(r)<4: continue
        low=r.lower()
        if any(x in low for x in ["token", "password", "contraseña", "secret", "api_key", "cookie"]):
            continue
        key=re.sub(r"\s+"," ",low)[:150]
        if key in seen: continue
        seen.add(key); cleaned.append(r[:260])
    selected=cleaned[-12:]
    return "\n[Memoria AETHER 3.1.0 · compacta]\n" + "\n".join(f"- {r}" for r in selected) + "\n"


