BOT_VERSION = "3.1.0"
XAU_PUBLIC_VERSION_NAME = "X AETHER ULTRA 3.1.0 · XP Card Hotfix"


def _amx_normalize_slot(item_id: str, item: dict) -> str | None:
    """Devuelve el slot real del cosmético, compatible con nombres antiguos."""
    slot = _amx_slot_for_item(item_id, item) if "_amx_slot_for_item" in globals() else item.get("slot")
    slot = str(slot or "").strip().lower() or None
    tipo = str(item.get("tipo", item_id)).lower()
    categoria = str(item.get("categoria", "")).lower()
    if slot in {"xp", "xp_card", "xpcard", "card", "tarjeta", "tarjeta_xp", "fondo_nivel", "nivel_fondo"}:
        return "lvl_fondo"
    if slot in {"marco_xp", "xp_marco", "nivel_marco", "marco_nivel"}:
        return "lvl_marco"
    if slot == "fondo" and (item.get("level_style") or categoria in {"nivel", "xpcard", "xp card"} or "lvl" in tipo or "xpcard" in tipo):
        return "lvl_fondo"
    if slot:
        return slot
    if item.get("level_style") or categoria in {"nivel", "xpcard", "xp card"} or "xpcard" in tipo or "fondo_lvl" in tipo:
        return "lvl_fondo"
    if "marco_lvl" in tipo or ("marco" in tipo and "xp" in tipo):
        return "lvl_marco"
    return None


def _amx_find_item_by_saved_value(value):
    """Busca items guardados como ID, tipo o nombre. Evita que una card equipada quede invisible."""
    if value is None:
        return None, None
    raw = str(value).strip()
    if not raw:
        return None, None
    low = raw.lower()
    if low in TIENDA_ITEMS:
        return low, TIENDA_ITEMS[low]
    for item_id, item in TIENDA_ITEMS.items():
        aliases = {
            str(item_id).lower(),
            str(item.get("tipo", item_id)).lower(),
            str(item.get("nombre", "")).lower(),
        }
        if low in aliases:
            return item_id, item
    for item_id, item in TIENDA_ITEMS.items():
        if low in str(item_id).lower() or low in str(item.get("tipo", item_id)).lower() or low in str(item.get("nombre", "")).lower():
            return item_id, item
    return None, None


def _amx_get_equipped_item(info: dict, slot: str):
    """Lee el cosmético equipado con compatibilidad entre slots antiguos y nuevos."""
    eq = _amx_equipped(info)
    slot = str(slot or "").strip().lower()
    aliases = {
        "lvl_fondo": ["lvl_fondo", "xp_fondo", "xpcard", "xp_card", "card", "tarjeta_xp", "fondo_nivel", "nivel_fondo", "fondo"],
        "lvl_marco": ["lvl_marco", "xp_marco", "marco_xp", "marco_nivel", "nivel_marco"],
        "titulo": ["titulo", "title"],
        "placa": ["placa", "badge"],
        "mascota": ["mascota", "pet"],
        "firma": ["firma", "signature"],
    }.get(slot, [slot])

    # 1) Busca por slot directo o alias.
    for key in aliases:
        value = eq.get(key)
        item_id, item = _amx_find_item_by_saved_value(value)
        if item:
            real_slot = _amx_normalize_slot(item_id, item)
            if slot in {real_slot, key} or (slot == "lvl_fondo" and real_slot == "lvl_fondo") or (slot == "lvl_marco" and real_slot == "lvl_marco"):
                return item_id, item

    # 2) Si el usuario tenía la card guardada en un slot raro, rescátala.
    for value in list(eq.values()):
        item_id, item = _amx_find_item_by_saved_value(value)
        if item and _amx_normalize_slot(item_id, item) == slot:
            return item_id, item

    return None, None


def _amx_equipped_summary(info: dict) -> str:
    parts = []
    for slot, label in [("lvl_fondo", "Fondo XP"), ("lvl_marco", "Marco XP"), ("titulo", "Título"), ("placa", "Placa"), ("mascota", "Mascota")]:
        iid, item = _amx_get_equipped_item(info, slot)
        if item:
            parts.append(f"**{label}:** {item.get('emoji','💎')} `{iid}`")
    return "\n".join(parts) if parts else "No tienes cosméticos equipados todavía. Usa `!xpcards` y `!equipar <id>`."


