# # @bot.command(name="equipar", aliases=["equip"])  # clean core: decorador antiguo desactivado  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 4, commands.BucketType.user)
async def equipar_cmd_201(ctx, *, item_query: str = None):
    if not item_query:
        return await ctx.send(embed=_amx_embed(
            "🎨 Equipar cosmético",
            "Uso: `!equipar <item>`\nEjemplos:\n`!equipar xpcard_lunar_dream`\n`!equipar marco_xp_cristal`\n`!equipar titulo_rey_arcade`",
            member=ctx.author,
        ))
    item_id, item = _amx_find_item(item_query)
    if not item:
        return await ctx.send(embed=_amx_embed("❌ No encontrado", "No encontré ese objeto. Mira `!inv`, `!tienda` o `!xpcards`.", XAU_PUBLIC_RED, ctx.author))
    slot = _amx_normalize_slot(item_id, item)
    if not slot:
        return await ctx.send(embed=_amx_embed("📦 No equipable", "Ese objeto no es cosmético. Si es consumible, usa `!usar <item>`.", XAU_PUBLIC_RED, ctx.author))

    datos = cargar_datos(); uid = str(ctx.author.id); asegurar_usuario(datos, uid); info = datos[uid]
    _amx_update_member_cache(info, ctx.author)
    if not _amx_has_item(info, item_id, item):
        hint = f"Puedes probarlo visualmente con `!previewxp {item_id}`." if slot in {"lvl_fondo", "lvl_marco"} else f"Cómpralo con `!comprar {item_id}`."
        return await ctx.send(embed=_amx_embed("🔒 No comprado", f"No tienes **{item.get('nombre', item_id)}**.\n{hint}", XAU_PUBLIC_RED, ctx.author))
    ok, why = _amx_unlock(info, item)
    if not ok:
        return await ctx.send(embed=_amx_embed("🔒 Bloqueado", f"Todavía no puedes equiparlo: **{why}**.", XAU_PUBLIC_RED, ctx.author))

    eq = _amx_equipped(info)
    saved_value = _amx_item_type(item_id, item)
    eq[slot] = saved_value
    # Compatibilidad: si es XP Card, limpiamos alias confusos y dejamos el slot canónico.
    if slot == "lvl_fondo":
        for old in ["xp_fondo", "xpcard", "xp_card", "card", "tarjeta_xp", "fondo_nivel", "nivel_fondo"]:
            if old != slot:
                eq.pop(old, None)
    if slot == "lvl_marco":
        for old in ["xp_marco", "marco_xp", "marco_nivel", "nivel_marco"]:
            if old != slot:
                eq.pop(old, None)
    guardar_datos(datos)

    embed = _amx_embed("✅ Cosmético equipado", f"{item.get('emoji','💎')} **{item.get('nombre', item_id)}**\nSlot activo: `{slot}`", XAU_PUBLIC_GREEN, ctx.author)
    if slot in {"lvl_fondo", "lvl_marco"}:
        embed.add_field(name="XP Card", value="Ya debería verse en `!lvl`, `!xpcard`, `!cardxp` y `!tarjetaxp`.", inline=False)
    embed.add_field(name="Equipado actual", value=_amx_equipped_summary(info), inline=False)
    await ctx.send(embed=embed)


