XAU_PUBLIC_VERSION_NAME = "X AETHER ULTRA 2.0.2 · Welcome Cards"
AMX_WELCOME_CONFIG_FILE = os.path.join(BASE_DIR, "xau_public_welcome_config.json")
AMX_WELCOME_CARD_SIZE = (1280, 520)
AMX_WELCOME_CARD_VERSION = "2.0.2"


def _amx_wc_read_config() -> dict:
    """Carga configuración ligera de canales de bienvenida/despedida."""
    try:
        if os.path.exists(AMX_WELCOME_CONFIG_FILE):
            with open(AMX_WELCOME_CONFIG_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, dict) else {}
    except Exception as exc:
        print(f"[WELCOME CARDS] No pude leer config: {exc}")
    return {}


def _amx_wc_write_config(data: dict) -> None:
    """Guarda configuración de canales de bienvenida/despedida."""
    try:
        with open(AMX_WELCOME_CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(data or {}, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"[WELCOME CARDS] No pude guardar config: {exc}")


def _amx_wc_channel_id(kind: str) -> int | None:
    """Obtiene canal configurado. Fallback: bienvenidas para ambos."""
    cfg = _amx_wc_read_config()
    key = "welcome_channel_id" if kind == "welcome" else "farewell_channel_id"
    env_key = "CANAL_BIENVENIDAS_ID" if kind == "welcome" else "CANAL_DESPEDIDAS_ID"
    raw = cfg.get(key) or os.getenv(env_key)
    if raw:
        try:
            return int(raw)
        except Exception:
            pass
    if kind == "welcome":
        return int(CANAL_BIENVENIDAS_ID) if CANAL_BIENVENIDAS_ID else None
    return int(CANAL_BIENVENIDAS_ID) if CANAL_BIENVENIDAS_ID else None


def _amx_wc_font(size: int, bold: bool = False):
    """Fuente robusta para Linux/Pterodactyl. Si falla, usa default."""
    if ImageFont is None:
        return None
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
        "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf" if bold else "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
    ]
    for p in candidates:
        try:
            if p and os.path.exists(p):
                return ImageFont.truetype(p, size)
        except Exception:
            pass
    try:
        return ImageFont.load_default()
    except Exception:
        return None


def _amx_wc_text_size(draw, text: str, font) -> tuple[int, int]:
    """Medición compatible con varias versiones de Pillow."""
    try:
        box = draw.textbbox((0, 0), text, font=font)
        return box[2] - box[0], box[3] - box[1]
    except Exception:
        try:
            return draw.textsize(text, font=font)
        except Exception:
            return (len(str(text)) * 12, 24)


def _amx_wc_gradient(size: tuple[int, int], start=(10, 7, 28), end=(48, 12, 88)):
    """Fondo degradado amatista con líneas horizontales suaves."""
    w, h = size
    img = Image.new("RGBA", size, start + (255,))
    draw = ImageDraw.Draw(img)
    for y in range(h):
        t = y / max(1, h - 1)
        r = int(start[0] * (1 - t) + end[0] * t)
        g = int(start[1] * (1 - t) + end[1] * t)
        b = int(start[2] * (1 - t) + end[2] * t)
        draw.line((0, y, w, y), fill=(r, g, b, 255))
    return img


def _amx_wc_safe_name(name: str, limit: int = 26) -> str:
    text = str(name or "Usuario").strip()
    if len(text) <= limit:
        return text
    return text[: max(3, limit - 3)] + "..."


def _amx_wc_add_glow(draw, xy, radius: int, color: tuple[int, int, int], steps: int = 7):
    """Dibuja un glow circular simple sin filtros caros."""
    x1, y1, x2, y2 = xy
    for i in range(steps, 0, -1):
        pad = i * radius
        alpha = max(10, int(70 / i))
        draw.ellipse((x1 - pad, y1 - pad, x2 + pad, y2 + pad), outline=(*color, alpha), width=max(1, radius // 2))


async def _amx_wc_avatar(member: discord.Member, size: int = 244):
    """Descarga y recorta el avatar como círculo."""
    if Image is None:
        return None
    try:
        raw = await member.display_avatar.replace(size=512, static_format="png").read()
        avatar = Image.open(io.BytesIO(raw)).convert("RGBA").resize((size, size))
    except Exception:
        avatar = Image.new("RGBA", (size, size), (125, 70, 255, 255))
        d = ImageDraw.Draw(avatar)
        font = _amx_wc_font(92, True)
        initial = (member.display_name[:1] or "?").upper()
        tw, th = _amx_wc_text_size(d, initial, font)
        d.text(((size - tw) / 2, (size - th) / 2 - 8), initial, font=font, fill=(255, 255, 255, 255))
    mask = Image.new("L", (size, size), 0)
    mdraw = ImageDraw.Draw(mask)
    mdraw.ellipse((0, 0, size - 1, size - 1), fill=255)
    circ = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    circ.paste(avatar, (0, 0), mask)
    return circ


async def _amx_wc_make_card(member: discord.Member, kind: str = "welcome") -> discord.File | None:
    """Genera una imagen premium de bienvenida o despedida."""
    if Image is None or ImageDraw is None:
        return None

    is_welcome = kind == "welcome"
    W, H = AMX_WELCOME_CARD_SIZE
    img = _amx_wc_gradient((W, H), (7, 8, 24), (37, 11, 72))
    deco = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    draw = ImageDraw.Draw(deco)

    purple = (167, 88, 255)
    violet = (111, 45, 210)
    gold = (246, 205, 132)
    soft = (230, 218, 255)
    dark_panel = (13, 14, 34, 190)

    # Nebulosas y brillos del fondo
    for i in range(14):
        x = (i * 137 + 80) % W
        y = (i * 79 + 38) % H
        r = 52 + (i % 5) * 22
        c = purple if i % 2 == 0 else violet
        draw.ellipse((x - r, y - r, x + r, y + r), fill=(*c, 18))
    for i in range(90):
        x = (i * 73 + 19) % W
        y = (i * 41 + 31) % H
        a = 65 + (i % 4) * 35
        draw.ellipse((x, y, x + 2, y + 2), fill=(255, 255, 255, a))
    for i in range(8):
        x1 = 760 + i * 54
        y1 = 26 + (i % 5) * 48
        draw.line((x1, y1, x1 + 72, y1 + 18), fill=(*purple, 34), width=2)
    try:
        deco = deco.filter(ImageFilter.GaussianBlur(1.6))
    except Exception:
        pass
    img.alpha_composite(deco)
    draw = ImageDraw.Draw(img)

    # Marco exterior y detalles geométricos
    draw.rounded_rectangle((18, 18, W - 18, H - 18), radius=32, outline=(*purple, 180), width=3)
    draw.rounded_rectangle((28, 28, W - 28, H - 28), radius=26, outline=(255, 255, 255, 24), width=1)
    for x, y, flip in [(36, 36, 1), (W - 36, 36, -1), (36, H - 36, 1), (W - 36, H - 36, -1)]:
        draw.line((x, y, x + 62 * flip, y), fill=(*gold, 120), width=2)
        draw.line((x, y, x, y + (62 if y < H / 2 else -62)), fill=(*gold, 120), width=2)
        draw.polygon([(x, y - 10), (x + 10 * flip, y), (x, y + 10), (x - 10 * flip, y)], outline=(*purple, 190), fill=(0, 0, 0, 0))

    # Avatar grande
    avatar_size = 244
    ax, ay = 88, 138
    ring_box = (ax - 30, ay - 30, ax + avatar_size + 30, ay + avatar_size + 30)
    _amx_wc_add_glow(draw, ring_box, 4, purple, 7)
    draw.ellipse(ring_box, outline=(*purple, 240), width=7)
    draw.ellipse((ax - 15, ay - 15, ax + avatar_size + 15, ay + avatar_size + 15), outline=(*gold, 160), width=2)
    draw.ellipse((ax - 45, ay - 45, ax + avatar_size + 45, ay + avatar_size + 45), outline=(*purple, 55), width=1)
    for px, py in [(ax + avatar_size / 2, ay - 42), (ax + avatar_size / 2, ay + avatar_size + 42), (ax - 42, ay + avatar_size / 2), (ax + avatar_size + 42, ay + avatar_size / 2)]:
        draw.polygon([(px, py - 12), (px + 12, py), (px, py + 12), (px - 12, py)], fill=(*purple, 235))
    avatar = await _amx_wc_avatar(member, avatar_size)
    if avatar:
        img.alpha_composite(avatar, (ax, ay))
        draw.ellipse((ax, ay, ax + avatar_size, ay + avatar_size), outline=(255, 255, 255, 120), width=2)

    # Emblema superior
    cx = 814
    draw.line((cx - 170, 104, cx - 36, 104), fill=(*gold, 110), width=2)
    draw.line((cx + 36, 104, cx + 170, 104), fill=(*gold, 110), width=2)
    draw.polygon([(cx, 56), (cx + 28, 104), (cx, 152), (cx - 28, 104)], fill=(*purple, 140), outline=(*soft, 180))
    draw.ellipse((cx - 58, 46, cx + 58, 162), outline=(*purple, 115), width=2)

    # Textos principales
    title = "¡BIENVENIDO!" if is_welcome else "¡HASTA LUEGO!"
    subtitle = "Nos alegra tenerte aquí" if is_welcome else "Esperamos verte de nuevo"
    headline_font = _amx_wc_font(76, True)
    subtitle_font = _amx_wc_font(34, False)
    name_font = _amx_wc_font(30, True)
    small_font = _amx_wc_font(20, False)
    tiny_font = _amx_wc_font(16, False)

    # Sombra y glow de título
    tx, ty = 486, 172
    for off, alpha in [(6, 50), (3, 80), (1, 130)]:
        draw.text((tx + off, ty + off), title, font=headline_font, fill=(82, 28, 130, alpha))
    draw.text((tx, ty), title, font=headline_font, fill=(238, 213, 255, 255))
    draw.text((tx + 2, ty + 2), title, font=headline_font, fill=(171, 96, 255, 115))

    draw.text((tx + 106, ty + 94), subtitle, font=subtitle_font, fill=(255, 236, 202, 238))
    draw.line((tx + 132, ty + 153, tx + 520, ty + 153), fill=(*purple, 170), width=3)
    draw.polygon([(tx + 326, ty + 141), (tx + 338, ty + 153), (tx + 326, ty + 165), (tx + 314, ty + 153)], fill=(*purple, 240))

    # Placa de usuario y servidor
    user_name = _amx_wc_safe_name(member.display_name, 30)
    server_name = _amx_wc_safe_name(getattr(member.guild, "name", "Servidor"), 34)
    plaque = (482, 360, W - 86, 456)
    draw.rounded_rectangle(plaque, radius=24, fill=dark_panel, outline=(*gold, 180), width=2)
    draw.rounded_rectangle((plaque[0] + 10, plaque[1] + 10, plaque[2] - 10, plaque[3] - 10), radius=18, outline=(*purple, 130), width=2)
    label = "Nuevo miembro" if is_welcome else "Miembro despedido"
    draw.text((plaque[0] + 38, plaque[1] + 16), label.upper(), font=tiny_font, fill=(*gold, 215))
    draw.text((plaque[0] + 38, plaque[1] + 42), user_name, font=name_font, fill=(255, 255, 255, 255))
    draw.text((plaque[0] + 438, plaque[1] + 43), server_name, font=name_font, fill=(255, 236, 202, 235))
    draw.text((plaque[0] + 438, plaque[1] + 18), "SERVIDOR", font=tiny_font, fill=(*purple, 230))

    count_text = f"Miembro #{member.guild.member_count}" if is_welcome else "Gracias por haber formado parte"
    draw.rounded_rectangle((86, 410, 392, 454), radius=18, fill=(255, 255, 255, 18), outline=(*purple, 90), width=1)
    draw.text((110, 421), count_text, font=small_font, fill=(255, 255, 255, 215))
    draw.text((W - 214, H - 42), f"X AETHER {AMX_WELCOME_CARD_VERSION}", font=tiny_font, fill=(255, 255, 255, 120))

    buffer = io.BytesIO()
    img.convert("RGB").save(buffer, format="PNG", optimize=True)
    buffer.seek(0)
    filename = "xau_public_welcome.png" if is_welcome else "xau_public_farewell.png"
    return discord.File(buffer, filename=filename)


async def _amx_wc_send(channel: discord.abc.Messageable, member: discord.Member, kind: str, preview: bool = False):
    """Envía embed + imagen generada de bienvenida/despedida."""
    is_welcome = kind == "welcome"
    color = discord.Color.purple() if is_welcome else discord.Color.dark_purple()
    title = "🌌 ¡Bienvenido al servidor!" if is_welcome else "🌙 Hasta luego"
    desc = (
        f"{member.mention}, acabas de entrar al núcleo amatista de **{member.guild.name}**.\n"
        "Ponte cómodo, revisa las normas y usa `!ayuda` para ver todo lo que puedes hacer."
        if is_welcome else
        f"**{member.display_name}** ha salido de **{member.guild.name}**.\n"
        "La puerta queda abierta por si algún día vuelve a cruzar la galaxia."
    )
    if preview:
        desc = "**PREVIEW:** esto es una prueba visual, no un evento real.\n\n" + desc
    filename = "xau_public_welcome.png" if is_welcome else "xau_public_farewell.png"
    embed = discord.Embed(title=title, description=desc, color=color, timestamp=discord.utils.utcnow())
    embed.add_field(name="👤 Usuario", value=f"{member.mention}\n`{member.id}`", inline=True)
    embed.add_field(name="📊 Servidor", value=f"**{member.guild.name}**\nMiembros: **{member.guild.member_count}**", inline=True)
    embed.add_field(name="✨ Panel", value="Imagen generada automáticamente con avatar circular y tema amatista.", inline=False)
    embed.set_image(url=f"attachment://{filename}")
    embed.set_footer(text=f"{XAU_PUBLIC_VERSION_NAME} · bienvenidas/despedidas premium")

    file = None
    try:
        file = await _amx_wc_make_card(member, kind)
    except Exception as exc:
        print(f"[WELCOME CARDS] Fallo generando imagen {kind}: {exc}")

    try:
        if file:
            await channel.send(embed=embed, file=file)
        else:
            embed.set_image(url=None)
            embed.set_thumbnail(url=member.display_avatar.url)
            embed.add_field(name="⚠️ Sin imagen", value="Pillow no está activo. Instala `pillow` para usar las cards visuales.", inline=False)
            await channel.send(embed=embed)
    except Exception as exc:
        print(f"[WELCOME CARDS] Fallo enviando {kind}: {exc}")


async def _amx_wc_assign_required_role(member: discord.Member):
    """Asigna rol obligatorio con comprobaciones para evitar NoneType/Forbidden."""
    if not member.guild or member.bot:
        return
    role = member.guild.get_role(ROL_OBLIGATORIO_ID)
    if role is None:
        print(f"[WELCOME CARDS] Rol obligatorio no encontrado: {ROL_OBLIGATORIO_ID}")
        return
    if role in member.roles:
        return
    me = member.guild.me
    if me and role >= me.top_role:
        print(f"[WELCOME CARDS] No puedo asignar {role.name}: está por encima de mi rol.")
        return
    try:
        await member.add_roles(role, reason="Rol obligatorio al entrar al servidor")
    except discord.Forbidden:
        print(f"[WELCOME CARDS] Sin permisos para dar rol obligatorio a {member}.")
    except discord.HTTPException as exc:
        print(f"[WELCOME CARDS] Discord rechazó el rol obligatorio: {exc}")


@bot.event
async def on_member_join(member: discord.Member):
    """Bienvenida premium con imagen generada y rol obligatorio seguro."""
    await _amx_wc_assign_required_role(member)
    channel_id = _amx_wc_channel_id("welcome")
    channel = member.guild.get_channel(channel_id) if channel_id else None
    if channel:
        await _amx_wc_send(channel, member, "welcome")


