def _amx21_remove_command(*names: str):
    """Elimina comandos/aliases antes de redefinirlos. Evita CommandRegistrationError."""
    for name in names:
        try:
            bot.remove_command(str(name))
        except Exception:
            pass


def _amx21_money(value) -> str:
    try:
        return f"{int(value):,}{amatista}"
    except Exception:
        return f"0{amatista}"


def _amx21_trim(text: str, limit: int = 950) -> str:
    text = str(text or "")
    return text if len(text) <= limit else text[: max(0, limit - 3)] + "..."


def _amx21_pages(seq, size: int = 8):
    seq = list(seq or [])
    return [seq[i:i + size] for i in range(0, len(seq), size)] or [[]]


def _amx21_bar(current: int, total: int, width: int = 18) -> str:
    total = max(1, int(total or 1))
    current = max(0, min(int(current or 0), total))
    filled = min(width, int((current / total) * width))
    return "█" * filled + "░" * (width - filled)


def _amx21_embed(title: str, description: str = "", color=None, member=None) -> discord.Embed:
    embed = discord.Embed(
        title=title,
        description=description,
        color=color or AMX21_ACCENT,
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.set_footer(text=f"{XAU_PUBLIC_VERSION_NAME} · sistema amatista")
    if member is not None:
        try:
            embed.set_thumbnail(url=member.display_avatar.url)
        except Exception:
            pass
    return embed


def _amx21_get_info(datos: dict, user_id: int | str) -> dict:
    uid = str(user_id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    if not isinstance(info.get("items"), dict):
        info["items"] = {}
    if not isinstance(info.get("equipado"), dict):
        info["equipado"] = {}
    return info


def _amx21_item_key(item_id: str, item: dict) -> str:
    return str(item.get("tipo") or item_id)


def _amx21_owned(info: dict, item_id: str, item: dict = None) -> bool:
    item = item or TIENDA_ITEMS.get(item_id, {})
    inv = info.get("items", {}) if isinstance(info.get("items"), dict) else {}
    return item_id in inv or _amx21_item_key(item_id, item) in inv


def _amx21_inv_entry(info: dict, item_id: str, item: dict = None):
    item = item or TIENDA_ITEMS.get(item_id, {})
    inv = info.get("items", {}) if isinstance(info.get("items"), dict) else {}
    return inv.get(item_id) or inv.get(_amx21_item_key(item_id, item))


def _amx21_min_level(item: dict) -> int:
    for key in ("nivel_min", "min_level", "nivel", "level"):
        try:
            return max(1, int(item.get(key, 1) or 1))
        except Exception:
            pass
    return 1


def _amx21_user_price(item: dict, level: int = 1) -> int:
    """Precio estable pero escalable: más nivel = catálogo más premium sin romper economía."""
    base = int(item.get("precio", 0) or 0)
    rarity = str(item.get("rareza", "normal")).lower()
    rarity_mul = {
        "común": 1.00, "comun": 1.00, "normal": 1.00,
        "raro": 1.08, "épico": 1.16, "epico": 1.16,
        "legendario": 1.28, "mítico": 1.42, "mitico": 1.42,
        "divino": 1.60,
    }.get(rarity, 1.0)
    level_mul = 1 + min(max(level - 1, 0), 100) * 0.006
    return max(1, int(round(base * rarity_mul * level_mul)))


def _amx21_slot_for_item(item_id: str, item: dict) -> str | None:
    if "_amx_normalize_slot" in globals():
        try:
            slot = _amx_normalize_slot(item_id, item)
            if slot:
                return slot
        except Exception:
            pass
    slot = str(item.get("slot", "") or "").strip().lower()
    categoria = str(item.get("categoria", "") or "").strip().lower()
    tipo = str(item.get("tipo", item_id) or item_id).strip().lower()
    if slot:
        return slot
    if item.get("level_style") or categoria in {"nivel", "xp_card", "xpcard"} or "xpcard" in tipo or tipo.startswith("fondo_lvl"):
        return "lvl_fondo"
    if tipo.startswith("marco_lvl") or ("marco" in tipo and ("xp" in tipo or "lvl" in tipo)):
        return "lvl_marco"
    if categoria in {"titulo", "mascota", "fondo", "placa", "firma", "aura", "marco"}:
        return categoria
    return None


def _amx21_add_item_to_inventory(info: dict, item_id: str, item: dict, amount: int = 1):
    inv = info.setdefault("items", {})
    key = item_id
    if item.get("consumible"):
        entry = inv.get(key)
        if not isinstance(entry, dict):
            entry = {"cantidad": 0}
        entry.update({
            "id": item_id,
            "tipo": _amx21_item_key(item_id, item),
            "nombre": item.get("nombre", item_id),
            "emoji": item.get("emoji", "🎁"),
            "categoria": item.get("categoria", "especial"),
            "rareza": item.get("rareza", "normal"),
        })
        entry["cantidad"] = int(entry.get("cantidad", 0) or 0) + max(1, int(amount or 1))
        inv[key] = entry
        return
    inv[key] = {
        "id": item_id,
        "tipo": _amx21_item_key(item_id, item),
        "nombre": item.get("nombre", item_id),
        "emoji": item.get("emoji", "✨"),
        "categoria": item.get("categoria", "cosmetico"),
        "rareza": item.get("rareza", "normal"),
        "comprado_en": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "slot": _amx21_slot_for_item(item_id, item),
    }


