# ──────────────────────────────────────────────────────────────────────────────
# Normalizador de ayuda: COMMAND_CATEGORIES queda estable aunque bloques viejos
# hayan intentado mezclar dict/list.
# ──────────────────────────────────────────────────────────────────────────────
def _amx21_normalize_help_catalog():
    global COMMAND_CATEGORIES
    if not isinstance(COMMAND_CATEGORIES, dict):
        COMMAND_CATEGORIES = {}
    normalized = {}
    for cat, value in list(COMMAND_CATEGORIES.items()):
        cat_key = str(cat or "otros").lower().strip() or "otros"
        if isinstance(value, dict):
            normalized[cat_key] = {str(k): str(v) for k, v in value.items()}
        elif isinstance(value, (list, tuple, set)):
            normalized[cat_key] = {str(v): "Comando disponible." for v in value}
        else:
            normalized[cat_key] = {str(value): "Función disponible."}
    COMMAND_CATEGORIES = normalized

    # Catalogar comandos reales que no estén en ayuda.
    existing = set()
    for data in COMMAND_CATEGORIES.values():
        for key in data.keys():
            first = str(key).split()[0].lstrip("!/").lower()
            if first:
                existing.add(first)

    buckets = {
        "perfil": {"bal", "balance", "perfil", "lvl", "xpcard", "cardxp", "tarjetaxp", "inventario", "inv", "coleccion", "equipar", "desequipar", "fondosnivel", "previewxp", "xpcards"},
        "tienda": {"tienda", "comprar", "usar", "ofertas", "oferta", "vender", "tiendamiembro", "comprarmiembro", "repshop"},
        "minijuegos": {"slots", "maquina", "ruleta", "dado", "ppt", "apostar", "blackjack", "poker", "bingo", "tiro", "ahorcado", "adivina", "minas", "carrera", "cofre", "crash", "tesoro", "cartaalta"},
        "miembros": {"miembro", "beneficios", "memberdaily", "minijuegosmiembro", "memberpack", "cristalflip", "clubtrabajo", "miembroplus", "miembrostats", "topmiembros"},
        "streams": {"addstream", "mystreams", "delstream", "streams", "streamguide", "streamapi", "streamperfil", "streamstats", "streamscan", "streamcanal"},
        "aether": {"ia", "chat", "pregunta", "mimemoria", "memoriaaether", "iaestado", "iastatus", "aetherdiagnostico", "aetheroptimizar"},
        "rocket league": {"tiendarl", "rlshop", "tiendarocket", "tiendarl_actualizar"},
        "moderacion": {"kick", "ban", "clear", "warn", "aviso", "silenciar", "dessilenciar", "slowmode", "auditar_bot", "setbienvenida", "setdespedida"},
    }
    for cmd in bot.commands:
        if getattr(cmd, "hidden", False):
            continue
        name = cmd.name.lower()
        if name in existing:
            continue
        target = "otros"
        for cat, names in buckets.items():
            if name in names:
                target = cat
                break
        aliases = ", ".join(f"!{a}" for a in getattr(cmd, "aliases", [])[:5])
        desc = getattr(cmd, "help", None) or getattr(cmd, "brief", None) or (cmd.callback.__doc__.strip().split("\n")[0] if getattr(cmd.callback, "__doc__", None) else "Comando disponible.")
        if aliases:
            desc += f" Alias: {aliases}."
        COMMAND_CATEGORIES.setdefault(target, {})[f"!{cmd.name}"] = _amx21_trim(desc, 180)


_amx21_normalize_help_catalog()


