class AMX21HelpSelect(discord.ui.Select):
    def __init__(self, view: "AMX21HelpView"):
        self.parent_view = view
        categories = sorted(COMMAND_CATEGORIES.keys())
        options = []
        icon_map = {
            "perfil": "👤", "economia": "💎", "economía": "💎", "tienda": "🛒",
            "minijuegos": "🎮", "miembros": "👑", "streams": "🔴", "aether": "🧠",
            "moderacion": "🛡️", "moderación": "🛡️", "rocket league": "🚗", "tickets": "🎫",
            "utilidades": "🧰", "funciones": "✨", "otros": "📦",
        }
        for cat in categories[:25]:
            count = len(COMMAND_CATEGORIES.get(cat, {}))
            options.append(discord.SelectOption(
                label=cat.title()[:100],
                value=cat,
                description=f"{count} entradas disponibles"[:100],
                emoji=icon_map.get(cat, "📚"),
                default=(cat == view.category),
            ))
        super().__init__(placeholder="📚 Cambiar categoría de ayuda", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        self.parent_view.category = self.values[0]
        self.parent_view.page = 0
        await self.parent_view.refresh(interaction)


class AMX21HelpView(discord.ui.View):
    def __init__(self, ctx, category: str = "inicio", page: int = 0):
        super().__init__(timeout=180)
        self.ctx = ctx
        self.author_id = ctx.author.id
        self.category = category if category in COMMAND_CATEGORIES else "inicio"
        self.page = max(0, int(page or 0))
        if COMMAND_CATEGORIES:
            self.add_item(AMX21HelpSelect(self))
        self._sync_buttons()

    def _sync_buttons(self):
        if self.category == "inicio":
            max_page = 0
        else:
            entries = list(COMMAND_CATEGORIES.get(self.category, {}).items())
            max_page = max(0, len(_amx21_pages(entries, 8)) - 1)
        for child in self.children:
            if isinstance(child, discord.ui.Button):
                if child.custom_id == "amx21_help_prev":
                    child.disabled = self.page <= 0
                elif child.custom_id == "amx21_help_next":
                    child.disabled = self.page >= max_page

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Este panel de ayuda no es tuyo. Usa `!ayuda` para abrir el tuyo.", ephemeral=True)
            return False
        return True

    def build_embed(self) -> discord.Embed:
        _amx21_normalize_help_catalog()
        total_cmds = len([c for c in bot.commands if not getattr(c, "hidden", False)])
        if self.category == "inicio":
            embed = _amx21_embed(
                "📚 Centro de ayuda X AETHER ULTRA",
                f"{AMX21_LINE}\nSelecciona una categoría o usa `!ayuda <categoría>` para ir directo.\n\nComandos prefix detectados: **{total_cmds}**\nCategorías: **{len(COMMAND_CATEGORIES)}**\n{AMX21_LINE}",
                AMX21_ACCENT,
                self.ctx.author,
            )
            for cat in sorted(COMMAND_CATEGORIES.keys()):
                entries = COMMAND_CATEGORIES.get(cat, {})
                sample = " · ".join(list(entries.keys())[:4]) or "Sin entradas"
                embed.add_field(name=f"💠 {cat.title()} · {len(entries)}", value=_amx21_trim(sample, 180), inline=True)
            embed.add_field(name="🔎 Búsqueda", value="Usa `!comandos <texto>` para encontrar comandos por nombre o descripción.", inline=False)
            return embed

        entries = list(COMMAND_CATEGORIES.get(self.category, {}).items())
        pages = _amx21_pages(entries, 8)
        self.page = max(0, min(self.page, len(pages) - 1))
        embed = _amx21_embed(
            f"📜 Ayuda · {self.category.title()}",
            f"Página **{self.page + 1}/{len(pages)}** · **{len(entries)}** entradas\n{AMX21_LINE}",
            AMX21_ACCENT,
            self.ctx.author,
        )
        for cmd, desc in pages[self.page]:
            embed.add_field(name=str(cmd)[:256], value=_amx21_trim(desc, 900), inline=False)
        return embed

    async def refresh(self, interaction: discord.Interaction):
        self._sync_buttons()
        await interaction.response.edit_message(embed=self.build_embed(), view=self)

    @discord.ui.button(label="Inicio", emoji="🏠", style=discord.ButtonStyle.secondary, custom_id="amx21_help_home", row=1)
    async def home_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.category = "inicio"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Anterior", emoji="⬅️", style=discord.ButtonStyle.primary, custom_id="amx21_help_prev", row=1)
    async def prev_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page = max(0, self.page - 1)
        await self.refresh(interaction)

    @discord.ui.button(label="Siguiente", emoji="➡️", style=discord.ButtonStyle.primary, custom_id="amx21_help_next", row=1)
    async def next_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page += 1
        await self.refresh(interaction)

    @discord.ui.button(label="Actualizar", emoji="🔄", style=discord.ButtonStyle.success, custom_id="amx21_help_refresh", row=1)
    async def refresh_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        _amx21_normalize_help_catalog()
        await self.refresh(interaction)


