class AMX21InventoryView(discord.ui.View):
    def __init__(self, ctx, member, filtro="todo", page=0):
        super().__init__(timeout=120)
        self.ctx = ctx
        self.member = member
        self.author_id = ctx.author.id
        self.filtro = filtro
        self.page = page
        self._sync_buttons()

    async def interaction_check(self, interaction):
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Abre tu propio inventario con `!inv`.", ephemeral=True)
            return False
        return True

    def entries(self):
        datos = cargar_datos()
        info = _amx21_get_info(datos, self.member.id)
        inv = info.get("items", {}) if isinstance(info.get("items"), dict) else {}
        entries = []
        for item_id, entry in inv.items():
            item = TIENDA_ITEMS.get(str(item_id)) or next((v for k, v in TIENDA_ITEMS.items() if v.get("tipo") == item_id), {})
            cat = str((entry or {}).get("categoria") or item.get("categoria") or "otros").lower()
            if self.filtro != "todo" and self.filtro not in cat and self.filtro != str(item.get("slot", "")).lower():
                continue
            entries.append((str(item_id), entry if isinstance(entry, dict) else {}, item))
        return entries

    def build_embed(self):
        entries = self.entries()
        pages = _amx21_pages(entries, 8)
        self.page = max(0, min(self.page, len(pages) - 1))
        embed = _amx21_embed(
            f"🎒 Inventario · {self.member.display_name}",
            f"Filtro: **{self.filtro}** · Página **{self.page + 1}/{len(pages)}** · Objetos: **{len(entries)}**\n{AMX21_LINE}",
            AMX21_ACCENT,
            self.member,
        )
        if not pages[self.page]:
            embed.description += "\nNo hay objetos en este filtro. La mochila está haciendo eco cósmico."
            return embed
        for item_id, entry, item in pages[self.page]:
            qty = int(entry.get("cantidad", 1) or 1)
            qty_txt = f" · x{qty}" if qty > 1 or item.get("consumible") else ""
            slot = _amx21_slot_for_item(item_id, item) or entry.get("slot") or "sin slot"
            desc = item.get("descripcion") or entry.get("descripcion") or "Objeto del inventario."
            embed.add_field(
                name=f"{item.get('emoji', entry.get('emoji', '✨'))} {entry.get('nombre') or item.get('nombre') or item_id}{qty_txt}",
                value=f"`{item_id}` · **{item.get('rareza', entry.get('rareza', 'normal'))}** · slot `{slot}`\n{_amx21_trim(desc, 180)}",
                inline=False,
            )
        return embed

    def _sync_buttons(self):
        entries = self.entries() if hasattr(self, "ctx") else []
        max_page = max(0, len(_amx21_pages(entries, 8)) - 1)
        for child in self.children:
            if isinstance(child, discord.ui.Button):
                if child.custom_id == "amx21_inv_prev":
                    child.disabled = self.page <= 0
                elif child.custom_id == "amx21_inv_next":
                    child.disabled = self.page >= max_page

    async def refresh(self, interaction):
        self._sync_buttons()
        await interaction.response.edit_message(embed=self.build_embed(), view=self)

    @discord.ui.button(label="Todo", emoji="🎒", style=discord.ButtonStyle.secondary, row=0)
    async def all_btn(self, interaction, button):
        self.filtro = "todo"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Cosméticos", emoji="🎨", style=discord.ButtonStyle.secondary, row=0)
    async def cos_btn(self, interaction, button):
        self.filtro = "nivel"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Consumibles", emoji="🎁", style=discord.ButtonStyle.secondary, row=0)
    async def con_btn(self, interaction, button):
        self.filtro = "jugable"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Prev", emoji="⬅️", style=discord.ButtonStyle.primary, custom_id="amx21_inv_prev", row=1)
    async def prev_btn(self, interaction, button):
        self.page = max(0, self.page - 1)
        await self.refresh(interaction)

    @discord.ui.button(label="Next", emoji="➡️", style=discord.ButtonStyle.primary, custom_id="amx21_inv_next", row=1)
    async def next_btn(self, interaction, button):
        self.page += 1
        await self.refresh(interaction)


