class AMX21ShopView(discord.ui.View):
    def __init__(self, ctx, category="todo", page=0):
        super().__init__(timeout=160)
        self.ctx = ctx
        self.author_id = ctx.author.id
        self.category = category
        self.page = page
        self.add_item(AMX21ShopSelect(self))
        self._sync_buttons()

    def pool(self):
        datos = cargar_datos()
        info = _amx21_get_info(datos, self.author_id)
        level = int(info.get("nivel", 1) or 1)
        entries = []
        for item_id, item in TIENDA_ITEMS.items():
            cat = str(item.get("categoria", "otros")).lower()
            slot = str(_amx21_slot_for_item(item_id, item) or "").lower()
            if self.category not in {"todo", "all"} and self.category not in cat and self.category not in slot:
                continue
            entries.append((item_id, item, _amx21_min_level(item), _amx21_user_price(item, level)))
        entries.sort(key=lambda x: (x[2], x[3], x[0]))
        return entries, info, level

    def build_embed(self):
        entries, info, level = self.pool()
        pages = _amx21_pages(entries, 6)
        self.page = max(0, min(self.page, len(pages) - 1))
        embed = _amx21_embed(
            "🛒 Tienda Aether",
            f"Categoría: **{self.category}** · Nivel usuario: **{level}** · Página **{self.page + 1}/{len(pages)}**\n{AMX21_LINE}\nCompra con `!comprar <id>` · equipa con `!equipar <id>` · usa consumibles con `!usar <id>`",
            AMX21_ACCENT,
            self.ctx.author,
        )
        if not pages[self.page]:
            embed.description += "\nNo hay items en esta sección."
            return embed
        for item_id, item, min_lvl, price in pages[self.page]:
            owned = _amx21_owned(info, item_id, item)
            locked = level < min_lvl
            state = "✅ Comprado" if owned and not item.get("consumible") else ("🔒 Bloqueado" if locked else "🟢 Disponible")
            if item.get("consumible") and owned:
                entry = _amx21_inv_entry(info, item_id, item) or {}
                state = f"🎁 Tienes x{int(entry.get('cantidad', 0) or 0)}"
            embed.add_field(
                name=f"{item.get('emoji','✨')} {item.get('nombre', item_id)} · {state}",
                value=f"`{item_id}` · **{_amx21_money(price)}** · nivel **{min_lvl}+** · {item.get('rareza','normal')}\n{_amx21_trim(item.get('descripcion',''), 180)}",
                inline=False,
            )
        return embed

    def _sync_buttons(self):
        entries, _, _ = self.pool() if hasattr(self, "ctx") else ([], {}, 1)
        max_page = max(0, len(_amx21_pages(entries, 6)) - 1)
        for child in self.children:
            if isinstance(child, discord.ui.Button):
                if child.custom_id == "amx21_shop_prev": child.disabled = self.page <= 0
                elif child.custom_id == "amx21_shop_next": child.disabled = self.page >= max_page

    async def interaction_check(self, interaction):
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Abre tu tienda con `!tienda` para comprar desde tu cuenta.", ephemeral=True)
            return False
        return True

    async def refresh(self, interaction):
        self._sync_buttons()
        await interaction.response.edit_message(embed=self.build_embed(), view=self)

    @discord.ui.button(label="Todo", emoji="🛒", style=discord.ButtonStyle.secondary, row=1)
    async def todo_btn(self, interaction, button):
        self.category = "todo"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Nivel", emoji="🎴", style=discord.ButtonStyle.secondary, row=1)
    async def nivel_btn(self, interaction, button):
        self.category = "nivel"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Jugable", emoji="🎲", style=discord.ButtonStyle.secondary, row=1)
    async def jugable_btn(self, interaction, button):
        self.category = "jugable"; self.page = 0
        await self.refresh(interaction)

    @discord.ui.button(label="Prev", emoji="⬅️", style=discord.ButtonStyle.primary, custom_id="amx21_shop_prev", row=2)
    async def prev_btn(self, interaction, button):
        self.page = max(0, self.page - 1)
        await self.refresh(interaction)

    @discord.ui.button(label="Next", emoji="➡️", style=discord.ButtonStyle.primary, custom_id="amx21_shop_next", row=2)
    async def next_btn(self, interaction, button):
        self.page += 1
        await self.refresh(interaction)


class AMX21ShopSelect(discord.ui.Select):
    def __init__(self, parent: AMX21ShopView):
        self.parent_view = parent
        entries, info, level = parent.pool()
        pages = _amx21_pages(entries, 6)
        shown = pages[max(0, min(parent.page, len(pages) - 1))]
        options = []
        for item_id, item, min_lvl, price in shown[:25]:
            status = "Comprado" if _amx21_owned(info, item_id, item) and not item.get("consumible") else ("Bloqueado" if level < min_lvl else "Comprar")
            options.append(discord.SelectOption(
                label=str(item.get("nombre", item_id))[:90],
                value=item_id,
                description=f"{status} · {_amx21_money(price)} · nivel {min_lvl}+"[:100],
                emoji=item.get("emoji", "✨"),
            ))
        if not options:
            options = [discord.SelectOption(label="Sin items", value="none", description="No hay objetos aquí.")]
        super().__init__(placeholder="🛍️ Comprar item visible", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction):
        if self.values[0] == "none":
            return await interaction.response.send_message("No hay item para comprar.", ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        ok, embed = _amx21_purchase_item(interaction.user, self.values[0])
        await interaction.followup.send(embed=embed, ephemeral=True)


def _amx21_purchase_item(user, item_id: str):
    item_id = str(item_id).strip()
    item = TIENDA_ITEMS.get(item_id)
    if not item:
        return False, _amx21_embed("❌ Item no encontrado", f"No existe `{item_id}` en la tienda.", AMX21_BAD, user)
    datos = cargar_datos()
    info = _amx21_get_info(datos, user.id)
    level = int(info.get("nivel", 1) or 1)
    min_lvl = _amx21_min_level(item)
    if level < min_lvl:
        return False, _amx21_embed("🔒 Item bloqueado", f"Necesitas nivel **{min_lvl}** para comprar `{item_id}`. Tu nivel actual es **{level}**.", AMX21_WARN, user)
    if _amx21_owned(info, item_id, item) and not item.get("consumible"):
        return False, _amx21_embed("✅ Ya lo tienes", f"Ese cosmético ya está en tu inventario. Usa `!equipar {item_id}`.", AMX21_OK, user)
    price = _amx21_user_price(item, level)
    cash = int(info.get("cash", 0) or 0)
    if cash < price:
        return False, _amx21_embed("💸 Cash insuficiente", f"Precio: **{_amx21_money(price)}**\nTu cash: **{_amx21_money(cash)}**", AMX21_BAD, user)
    info["cash"] = cash - price
    _amx21_add_item_to_inventory(info, item_id, item, 1)
    guardar_datos(datos)
    embed = _amx21_embed("🛍️ Compra realizada", f"Has comprado {item.get('emoji','✨')} **{item.get('nombre', item_id)}**\nID: `{item_id}`\nPrecio: **{_amx21_money(price)}**", AMX21_OK, user)
    slot = _amx21_slot_for_item(item_id, item)
    if slot:
        embed.add_field(name="🎨 Equipable", value=f"Slot `{slot}` · usa `!equipar {item_id}`", inline=False)
    if item.get("consumible"):
        embed.add_field(name="🎁 Consumible", value=f"Úsalo con `!usar {item_id}`", inline=False)
    return True, embed


