# @bot.command(name="usar", aliases=["use"])  # XAU310 deduplicado: comando antiguo desactivado
@commands.cooldown(1, 5, commands.BucketType.user)
async def usar_cmd_210(ctx, item_id: str = None, objetivo: discord.Member = None):
    """Usa consumibles de la tienda con recompensas reales."""
    if not item_id:
        return await ctx.send(embed=_amx21_embed("🎁 Falta item", "Uso: `!usar <id>`\nEjemplo: `!usar cofre_nebulosa`", AMX21_WARN, ctx.author))
    item = TIENDA_ITEMS.get(item_id)
    if not item or not item.get("consumible"):
        return await ctx.send(embed=_amx21_embed("⚠️ No consumible", f"`{item_id}` no es un consumible usable.", AMX21_WARN, ctx.author))
    datos = cargar_datos()
    info = _amx21_get_info(datos, ctx.author.id)
    entry = _amx21_inv_entry(info, item_id, item)
    if not isinstance(entry, dict) or int(entry.get("cantidad", 0) or 0) <= 0:
        return await ctx.send(embed=_amx21_embed("🔒 No tienes ese item", f"Compra uno con `!comprar {item_id}`.", AMX21_BAD, ctx.author))
    entry["cantidad"] = int(entry.get("cantidad", 0) or 0) - 1
    if entry["cantidad"] <= 0:
        info.get("items", {}).pop(item_id, None)
        info.get("items", {}).pop(_amx21_item_key(item_id, item), None)

    reward_cash = 0
    reward_xp = 0
    reward_rep = 0
    msg = ""
    roll = random.randint(1, 100)
    if item_id in {"ticket_gemrush", "rasca_amatista", "moneda_suerte", "dado_destino"}:
        reward_cash = random.randint(120, 900) if roll < 90 else random.randint(1200, 3000)
        reward_xp = random.randint(15, 80)
        msg = "La suerte chispeó en morado."
    elif item_id in {"cofre_nebulosa", "cofre_tesoro", "caja_legendaria", "llave_mistica", "llave_arcana", "capsula_caos"}:
        reward_cash = random.randint(500, 2400) if roll < 82 else random.randint(3500, 9000)
        reward_xp = random.randint(40, 180)
        msg = "El cofre abrió una grieta amatista."
        if roll >= 92:
            bonus_candidates = [k for k, v in TIENDA_ITEMS.items() if not v.get("consumible") and _amx21_min_level(v) <= int(info.get("nivel", 1) or 1)]
            if bonus_candidates:
                won = random.choice(bonus_candidates)
                _amx21_add_item_to_inventory(info, won, TIENDA_ITEMS[won], 1)
                msg += f" Además desbloqueaste `{won}`."
    elif item_id in {"pocion_xp", "orbe_reputacion"}:
        reward_xp = random.randint(120, 420)
        reward_rep = 1 if roll >= 70 else 0
        msg = "Tu perfil absorbió energía de experiencia."
    elif item_id in {"regalo_amethyst", "contrato_caza", "duelo_amistoso"} and objetivo:
        target = _amx21_get_info(datos, objetivo.id)
        reward_cash = random.randint(250, 1200)
        target_bonus = max(50, reward_cash // 2)
        target["cash"] = int(target.get("cash", 0) or 0) + target_bonus
        target["monedas"] = int(target.get("monedas", 0) or 0) + target_bonus
        msg = f"{objetivo.mention} también recibió **{_amx21_money(target_bonus)}**."
    else:
        reward_cash = random.randint(150, 1300)
        reward_xp = random.randint(25, 120)
        msg = "Consumible activado correctamente."
    info["cash"] = int(info.get("cash", 0) or 0) + reward_cash
    if reward_cash > 0:
        info["monedas"] = int(info.get("monedas", 0) or 0) + reward_cash
    info["experiencia"] = int(info.get("experiencia", 0) or 0) + reward_xp
    info["reputacion"] = int(info.get("reputacion", 0) or 0) + reward_rep
    guardar_datos(datos)
    embed = _amx21_embed("🎁 Item usado", f"Usaste {item.get('emoji','🎁')} **{item.get('nombre', item_id)}**\n{msg}", AMX21_OK, ctx.author)
    embed.add_field(name="💎 Cash", value=f"+{_amx21_money(reward_cash)}", inline=True)
    embed.add_field(name="⭐ XP", value=f"+{reward_xp}", inline=True)
    if reward_rep:
        embed.add_field(name="✨ Rep", value=f"+{reward_rep}", inline=True)
    await ctx.send(embed=embed)


# ──────────────────────────────────────────────────────────────────────────────
# Rocket League Shop 2.1.0: parser más tolerante y firma correcta.
# ──────────────────────────────────────────────────────────────────────────────
try:
    _rlshop_extract_page_content_base_210 = _rlshop_extract_page_content
except Exception:
    _rlshop_extract_page_content_base_210 = None


def _rlshop_deep_find_json_items(obj, limit=80):
    """Busca items en JSON embebido de forma defensiva. No depende del nombre exacto de campos."""
    found = []
    seen = set()
    def clean(v):
        return re.sub(r"\s+", " ", str(v or "")).strip()
    def image_url(v):
        s = clean(v)
        if not s:
            return ""
        if s.startswith("//"): return "https:" + s
        if s.startswith("/"): return "https://rlshop.gg" + s
        if s.startswith("http"): return s
        return ""
    def walk(x):
        if len(found) >= limit:
            return
        if isinstance(x, dict):
            name = clean(x.get("name") or x.get("title") or x.get("itemName") or x.get("displayName"))
            typ = clean(x.get("type") or x.get("itemType") or x.get("category") or x.get("slot"))
            price_raw = x.get("price") or x.get("credits") or x.get("cost") or x.get("amount")
            price = ""
            try:
                if price_raw is not None and 0 <= int(price_raw) <= 10000:
                    price = str(int(price_raw))
            except Exception:
                price = ""
            img = ""
            for key in ("image", "imageUrl", "thumbnail", "thumbnailUrl", "icon", "url", "src"):
                val = x.get(key)
                if isinstance(val, dict):
                    for vv in val.values():
                        img = image_url(vv)
                        if img: break
                else:
                    img = image_url(val)
                if img: break
            if name and not re.search(r"items? included|rlshop|featured shop", name, re.I) and (img or price or typ):
                k = (name.lower(), typ.lower(), price, img)
                if k not in seen:
                    seen.add(k)
                    found.append({"name": name, "type": typ or "Objeto", "price": price, "time": "Disponible", "paint": "", "image": img, "kind": "item"})
            for v in x.values():
                walk(v)
        elif isinstance(x, list):
            for v in x:
                walk(v)
    walk(obj)
    return found


def _rlshop_extract_json_fallback_210(html: str) -> list:
    import html as _html_module
    candidates = []
    for raw in re.findall(r'<script[^>]+type=["\']application/json["\'][^>]*>(.*?)</script>', html or "", re.S | re.I):
        candidates.append(_html_module.unescape(raw))
    m = re.search(r'<script[^>]+id=["\']__NEXT_DATA__["\'][^>]*>(.*?)</script>', html or "", re.S | re.I)
    if m:
        candidates.append(_html_module.unescape(m.group(1)))
    items = []
    for raw in candidates:
        try:
            data = json.loads(raw)
        except Exception:
            continue
        items.extend(_rlshop_deep_find_json_items(data))
    # dedupe
    clean = []
    seen = set()
    for item in items:
        key = (item.get("name"," ").lower(), item.get("type"," ").lower(), item.get("price",""), item.get("image",""))
        if key not in seen:
            seen.add(key); clean.append(item)
    return clean


def _rlshop_merge_cards_210(base: dict, extra_items: list) -> dict:
    base = dict(base or {})
    cards = list(base.get("cards") or [])
    groups = list(base.get("groups") or [])
    standalone = list(base.get("items") or [])
    seen = {(str(c.get("name"," ")).lower(), str(c.get("type"," ")).lower(), str(c.get("image",""))) for c in cards}
    for item in extra_items:
        key = (str(item.get("name"," ")).lower(), str(item.get("type"," ")).lower(), str(item.get("image","")))
        if key in seen:
            continue
        seen.add(key)
        standalone.append(item)
        cards.append(item)
    base["items"] = standalone
    base["cards"] = cards
    base["groups"] = groups
    return base


def _rlshop_extract_page_content(html: str) -> dict:
    base = {"items": [], "groups": [], "cards": []}
    if _rlshop_extract_page_content_base_210:
        try:
            base = _rlshop_extract_page_content_base_210(html)
        except Exception as exc:
            print(f"[RLSHOP 2.1] parser base falló: {exc}")
    try:
        extra = _rlshop_extract_json_fallback_210(html)
        # Solo mezcla si el parser base se queda corto o hay imágenes nuevas claras.
        if extra and len(base.get("cards", [])) < len(extra):
            base = _rlshop_merge_cards_210(base, extra)
    except Exception as exc:
        print(f"[RLSHOP 2.1] parser JSON falló: {exc}")
    return base


async def rlshop_current_signature() -> str:
    parts = []
    for idx in range(len(RL_SHOP_PAGES)):
        try:
            data = await rlshop_get_page(idx, force=True)
            for card in data.get("items", []) + data.get("groups", []):
                parts.append(f"{idx}|{card.get('kind')}|{card.get('name')}|{card.get('type')}|{card.get('price')}|{len(card.get('items', []))}")
                for child in card.get("items", [])[:20]:
                    parts.append(f"{idx}|child|{child.get('name')}|{child.get('type')}|{child.get('price')}")
        except Exception as e:
            parts.append(f"error:{idx}:{e}")
    return hashlib.sha256("\n".join(parts).encode("utf-8", "ignore")).hexdigest()


