WELCOME_CONFIG_FILE = os.path.join(BASE_DIR, "welcome_config.json")


def _amx_welcome_load_config() -> dict:
    try:
        with open(WELCOME_CONFIG_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _amx_welcome_save_config(data: dict) -> None:
    try:
        with open(WELCOME_CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(data if isinstance(data, dict) else {}, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"[WELCOME CONFIG] No se pudo guardar: {exc!r}")


def _amx_welcome_font(size: int, bold: bool = False):
    if not ImageFont:
        return None
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
    ]
    for path in candidates:
        try:
            return ImageFont.truetype(path, size)
        except Exception:
            continue
    try:
        return ImageFont.load_default()
    except Exception:
        return None


def _amx_welcome_gradient(size, c1=(28, 8, 55), c2=(114, 36, 180)):
    if not Image:
        return None
    w, h = size
    img = Image.new("RGBA", size, c1 + (255,))
    px = img.load()
    for y in range(h):
        t = y / max(1, h - 1)
        for x in range(w):
            k = (x / max(1, w - 1) * 0.45) + (t * 0.55)
            r = int(c1[0] * (1 - k) + c2[0] * k)
            g = int(c1[1] * (1 - k) + c2[1] * k)
            b = int(c1[2] * (1 - k) + c2[2] * k)
            px[x, y] = (r, g, b, 255)
    return img


async def _amx_welcome_card_file(member: discord.Member, kind: str = "welcome"):
    if not Image or not ImageDraw or not ImageFilter:
        return None
    kind = "farewell" if str(kind).lower().startswith("fare") else "welcome"
    W, H = 1280, 420
    base = _amx_welcome_gradient((W, H), (14, 8, 34), (116, 38, 180)).convert("RGBA")
    deco = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    d = ImageDraw.Draw(deco)
    rng = random.Random(int(member.id) + (77 if kind == "farewell" else 33))
    for _ in range(120):
        x, y = rng.randint(0, W), rng.randint(0, H)
        r = rng.randint(1, 3)
        d.ellipse((x-r, y-r, x+r, y+r), fill=(230, 210, 255, rng.randint(35, 110)))
    for i in range(9):
        y = 35 + i * 42
        d.line((40, y, W-40, y), fill=(255, 255, 255, 10), width=1)
    for i in range(7):
        x = 120 + i * 170
        d.arc((x-140, -70, x+220, 290), 15, 180, fill=(190, 120, 255, 35), width=2)
    base = Image.alpha_composite(base, deco.filter(ImageFilter.GaussianBlur(1)))
    d = ImageDraw.Draw(base)
    d.rounded_rectangle((24, 24, W-24, H-24), 32, outline=(211, 157, 255, 210), width=4, fill=(8, 5, 22, 74))
    d.rounded_rectangle((46, 46, W-46, H-46), 26, outline=(255, 255, 255, 35), width=1)

    avatar_size = 220
    ax, ay = 76, 92
    try:
        av_bytes = await member.display_avatar.replace(size=256, static_format="png").read()
        avatar = Image.open(io.BytesIO(av_bytes)).convert("RGBA").resize((avatar_size, avatar_size))
    except Exception:
        avatar = Image.new("RGBA", (avatar_size, avatar_size), (125, 72, 210, 255))
    mask = Image.new("L", (avatar_size, avatar_size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, avatar_size-1, avatar_size-1), fill=255)
    glow = Image.new("RGBA", (avatar_size+36, avatar_size+36), (0,0,0,0))
    gd = ImageDraw.Draw(glow)
    gd.ellipse((12, 12, avatar_size+24, avatar_size+24), outline=(202, 141, 255, 235), width=14)
    gd.ellipse((0, 0, avatar_size+36, avatar_size+36), outline=(132, 64, 255, 95), width=6)
    base.alpha_composite(glow.filter(ImageFilter.GaussianBlur(2)), (ax-18, ay-18))
    base.paste(avatar, (ax, ay), mask)
    d.ellipse((ax-8, ay-8, ax+avatar_size+8, ay+avatar_size+8), outline=(245, 220, 255, 235), width=5)

    title = "¡BIENVENIDO!" if kind == "welcome" else "¡HASTA LUEGO!"
    subtitle = "Nos alegra tenerte aquí" if kind == "welcome" else "Esperamos verte de nuevo"
    color = (255, 235, 255, 255)
    accent = (211, 157, 255, 255)
    d.text((350, 92), title, font=_amx_welcome_font(64, True), fill=color)
    d.text((354, 170), subtitle, font=_amx_welcome_font(30, False), fill=(232, 212, 255, 235))
    name = member.display_name[:36]
    d.rounded_rectangle((350, 228, 1158, 305), 24, fill=(255,255,255,22), outline=(211,157,255,90), width=2)
    d.text((378, 244), f"{name}", font=_amx_welcome_font(38, True), fill=accent)
    server = getattr(member.guild, "name", "Servidor")[:42]
    count = getattr(member.guild, "member_count", 0) or 0
    d.text((378, 314), f"Servidor: {server}  ·  Miembro #{count}", font=_amx_welcome_font(22, False), fill=(238, 230, 255, 220))
    d.text((W-310, H-48), "X AETHER ULTRA · ROYAL WELCOME", font=_amx_welcome_font(17, True), fill=(255,255,255,155))
    buf = io.BytesIO()
    filename = "xau_public_welcome.png" if kind == "welcome" else "xau_public_farewell.png"
    base.save(buf, format="PNG")
    buf.seek(0)
    return discord.File(buf, filename=filename)


