@bot.event
async def on_member_remove(member: discord.Member):
    if member.bot:
        return
    canal = _amx21_get_config_channel(member.guild, "despedida", CANAL_BIENVENIDAS_ID)
    if not canal:
        return
    try:
        file = await _amx_welcome_card_file(member, "farewell") if "_amx_welcome_card_file" in globals() else None
        embed = _amx21_embed(
            "🌙 Un miembro se ha ido",
            f"**{member.display_name}** salió del servidor. Que el camino vuelva a cruzarse con el brillo amatista.",
            AMX21_DARK,
            member,
        )
        if file:
            embed.set_image(url="attachment://xau_public_farewell.png")
            await canal.send(embed=embed, file=file)
        else:
            await canal.send(embed=embed)
    except Exception as exc:
        print(f"[WELCOME 2.1] Error enviando despedida: {exc}")


