@commands.has_permissions(administrator=True)
async def auditar_bot_cmd_210(ctx):
    """Auditor completo: comandos, ayuda, JSON, Pillow, RL Shop y arranque."""
    _amx21_normalize_help_catalog()
    visible = [c for c in bot.commands if not getattr(c, "hidden", False)]
    help_names = set()
    for data in COMMAND_CATEGORIES.values():
        for k in data.keys():
            help_names.add(str(k).split()[0].lstrip("!/").lower())
    missing = [c.name for c in visible if c.name.lower() not in help_names]
    files = [DATOS_FILE, MEMORIA_FILE, STREAMS_DATA_FILE, RL_SHOP_STATE_FILE]
    file_report = []
    for fp in files:
        try:
            file_report.append(f"✅ `{os.path.basename(fp)}`" if os.path.exists(fp) else f"⚠️ `{os.path.basename(fp)}` no existe aún")
        except Exception:
            file_report.append(f"⚠️ `{fp}` no comprobado")
    run_count = 0
    try:
        with open(__file__, "r", encoding="utf-8") as f:
            run_count = len(re.findall(r"^[\t ]*bot\.run\(", f.read(), re.M))
    except Exception:
        pass
    embed = _amx21_embed("🧪 Auditor X AETHER ULTRA", f"{AMX21_LINE}\nRevisión técnica rápida del núcleo.\n{AMX21_LINE}", AMX21_ACCENT, ctx.author)
    embed.add_field(name="🧩 Comandos", value=f"Prefix visibles: **{len(visible)}**\nSin categoría de ayuda: **{len(missing)}**", inline=True)
    embed.add_field(name="📚 Ayuda", value=f"Categorías: **{len(COMMAND_CATEGORIES)}**\nEntradas: **{sum(len(v) for v in COMMAND_CATEGORIES.values())}**", inline=True)
    embed.add_field(name="🚀 Arranque", value=f"`bot.run` detectado: **{run_count}**\n{'✅ correcto' if run_count == 1 else '⚠️ revisar'}", inline=True)
    embed.add_field(name="🖼️ Pillow", value="✅ disponible" if Image and ImageDraw else "⚠️ no disponible", inline=True)
    embed.add_field(name="🌐 aiohttp", value="✅ importado" if aiohttp else "⚠️ no importado", inline=True)
    embed.add_field(name="🚗 RL Shop", value=f"Páginas: **{len(RL_SHOP_PAGES)}**\nCanal: `{RL_SHOP_CHANNEL_ID}`", inline=True)
    embed.add_field(name="📁 Archivos", value="\n".join(file_report), inline=False)
    if missing[:12]:
        embed.add_field(name="🧭 Comandos fuera de catálogo", value=_amx21_trim(", ".join(f"`!{m}`" for m in missing[:30]), 950), inline=False)
    await ctx.send(embed=embed)


