# ──────────────────────────────────────────────────────────────────────────────
_amx21_remove_command("comandos", "buscarcomando")
@bot.command(name="comandos", aliases=["buscarcomando"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def comandos_cmd_210(ctx, *, busqueda: str = None):
    """Busca comandos por nombre o descripción."""
    _amx21_normalize_help_catalog()
    if not busqueda:
        return await ctx.send(embed=_amx21_embed("🔎 Buscador de comandos", "Uso: `!comandos tienda`, `!comandos xp`, `!comandos miembro`", AMX21_ACCENT, ctx.author))
    q = busqueda.lower().strip()
    results = []
    for cat, data in COMMAND_CATEGORIES.items():
        for cmd, desc in data.items():
            hay = f"{cmd} {desc}".lower()
            if q in hay:
                results.append((cat, cmd, desc))
    embed = _amx21_embed("🔎 Resultado de búsqueda", f"Búsqueda: **{busqueda}** · resultados: **{len(results)}**\n{AMX21_LINE}", AMX21_ACCENT, ctx.author)
    for cat, cmd, desc in results[:10]:
        embed.add_field(name=f"{cmd} · {cat}", value=_amx21_trim(desc, 220), inline=False)
    if len(results) > 10:
        embed.set_footer(text=f"{XAU_PUBLIC_VERSION_NAME} · mostrando 10 de {len(results)} resultados")
    await ctx.send(embed=embed)


# ──────────────────────────────────────────────────────────────────────────────
# Error handler global: mensajes bonitos y útiles en todos los comandos.
# ──────────────────────────────────────────────────────────────────────────────
@bot.event
async def on_command_error(ctx, error):
    original = getattr(error, "original", error)
    if isinstance(error, commands.CommandNotFound):
        return
    if isinstance(error, commands.CommandOnCooldown):
        return await ctx.send(embed=_amx21_embed("⏳ Cooldown", f"Espera **{error.retry_after:.1f}s** antes de usar esto otra vez.", AMX21_WARN, ctx.author))
    if isinstance(error, commands.MissingRequiredArgument):
        return await ctx.send(embed=_amx21_embed("🧩 Falta un dato", f"Falta el argumento `{error.param.name}`. Usa `!ayuda {ctx.command.name if ctx.command else ''}` o `!comandos {ctx.command.name if ctx.command else ''}`.", AMX21_WARN, ctx.author))
    if isinstance(error, (commands.BadArgument, commands.MemberNotFound, commands.ChannelNotFound, commands.RoleNotFound)):
        return await ctx.send(embed=_amx21_embed("⚠️ Dato inválido", f"No pude interpretar ese argumento. Revisa menciones, números o IDs.\n`{_amx21_trim(original, 350)}`", AMX21_WARN, ctx.author))
    if isinstance(error, commands.MissingPermissions):
        return await ctx.send(embed=_amx21_embed("🛡️ Sin permisos", "No tienes permisos para usar este comando.", AMX21_BAD, ctx.author))
    if isinstance(error, commands.BotMissingPermissions):
        return await ctx.send(embed=_amx21_embed("🤖 Me faltan permisos", f"Necesito: `{', '.join(error.missing_permissions)}`", AMX21_BAD, ctx.author))
    print(f"[COMMAND ERROR 2.1] {ctx.command}: {repr(original)}")
    try:
        await ctx.send(embed=_amx21_embed("💥 Error controlado", f"Algo falló, pero el bot sigue vivo.\n```{_amx21_trim(repr(original), 700)}```", AMX21_BAD, ctx.author))
    except Exception:
        pass


