def _amx22_remove_command(*names: str):
    for name in names:
        try:
            bot.remove_command(str(name))
        except Exception:
            pass


def _amx22_json_load(path: str, default=None):
    try:
        if not os.path.exists(path):
            return default if default is not None else {}
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if data is not None else (default if default is not None else {})
    except Exception as exc:
        print(f"[X AETHER 2.2] No pude leer {path}: {exc}")
        return default if default is not None else {}


def _amx22_json_save(path: str, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=4)
        return True
    except Exception as exc:
        print(f"[X AETHER 2.2] No pude guardar {path}: {exc}")
        return False


def _amx22_embed(title: str, description: str = "", color=None, member=None) -> discord.Embed:
    embed = discord.Embed(
        title=title,
        description=description,
        color=color or AMX22_ACCENT,
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.set_footer(text=f"{XAU_PUBLIC_VERSION_NAME} · experiencia premium")
    if member is not None:
        try:
            embed.set_thumbnail(url=member.display_avatar.url)
        except Exception:
            pass
    return embed


def _amx22_safe_int(value, default: int = 0) -> int:
    try:
        return int(value)
    except Exception:
        return default


def _amx22_has_member_role(member: discord.Member) -> bool:
    try:
        if member.guild_permissions.administrator:
            return True
        for role in getattr(member, "roles", []):
            if getattr(role, "id", None) == ROLE_MIEMBRO:
                return True
            if str(getattr(role, "name", "")).lower() in {"miembro", "member", "members", "royal member", "premium"}:
                return True
    except Exception:
        pass
    return False


def _amx22_normalize_user(info: dict) -> dict:
    if not isinstance(info.get("items"), dict):
        info["items"] = {}
    if not isinstance(info.get("equipado"), dict):
        info["equipado"] = {}
    if not isinstance(info.get("estadisticas"), dict):
        info["estadisticas"] = {}
    if not isinstance(info.get("preferencias"), dict):
        info["preferencias"] = {}
    return info


def _amx22_get_user_info(datos: dict, user_id: int | str) -> dict:
    uid = str(user_id)
    asegurar_usuario(datos, uid)
    return _amx22_normalize_user(datos[uid])


def _amx22_user_level(info: dict) -> int:
    return max(1, _amx22_safe_int(info.get("nivel", 1), 1))


def _amx22_item_state(info: dict, item_id: str, item: dict) -> str:
    lvl = _amx22_user_level(info)
    min_lvl = _amx21_min_level(item) if "_amx21_min_level" in globals() else int(item.get("nivel_min", 1) or 1)
    if _amx21_owned(info, item_id, item):
        return "comprado" if not item.get("consumible") else "en inventario"
    if lvl < min_lvl:
        return "bloqueado"
    return "disponible"


def _amx22_register_game(uid: str, name: str, won: bool, delta: int):
    data = _amx22_json_load(AMX22_GAME_STATS_FILE, {})
    user = data.setdefault(str(uid), {})
    game = user.setdefault(name, {"partidas": 0, "ganadas": 0, "perdidas": 0, "neto": 0})
    game["partidas"] = _amx22_safe_int(game.get("partidas"), 0) + 1
    if won:
        game["ganadas"] = _amx22_safe_int(game.get("ganadas"), 0) + 1
    else:
        game["perdidas"] = _amx22_safe_int(game.get("perdidas"), 0) + 1
    game["neto"] = _amx22_safe_int(game.get("neto"), 0) + int(delta)
    _amx22_json_save(AMX22_GAME_STATS_FILE, data)


