# Consumibles 2.2: complementa !usar sin romper los consumibles anteriores.
def _amx22_use_item_effect(ctx, datos: dict, info: dict, item_id: str) -> tuple[int, int, int, str, str | None]:
    reward_cash = 0
    reward_xp = 0
    reward_rep = 0
    unlocked_item = None
    roll = random.randint(1, 100)
    if item_id in {"bateria_xp"}:
        reward_xp = random.randint(120, 360)
        text = "La batería descargó un pulso de experiencia violeta."
    elif item_id in {"contrato_trabajo_plus"}:
        reward_cash = random.randint(450, 1600)
        reward_xp = random.randint(60, 140)
        text = "Contrato completado. Limpio, rápido y con olor a amatista recién minada."
    elif item_id in {"token_reputacion", "orbe_reputacion"}:
        reward_rep = 1 if roll < 85 else 2
        reward_xp = random.randint(40, 120)
        text = "Tu reputación brilló un poco más en el servidor."
    elif item_id in {"sobre_cosmetico"}:
        pool = [k for k, v in TIENDA_ITEMS.items() if not v.get("consumible") and _amx21_slot_for_item(k, v) and _amx21_min_level(v) <= _amx22_user_level(info) and not _amx21_owned(info, k, v)]
        if pool and roll >= 35:
            unlocked_item = random.choice(pool)
            _amx21_add_item_to_inventory(info, unlocked_item, TIENDA_ITEMS[unlocked_item], 1)
            text = f"El sobre traía un cosmético real: `{unlocked_item}`."
        else:
            reward_cash = random.randint(450, 1800)
            reward_xp = random.randint(40, 150)
            text = "El sobre no trajo cosmético, pero sí una compensación jugosa."
    elif item_id in {"cofre_comodidad"}:
        reward_cash = random.randint(350, 1900)
        reward_xp = random.randint(50, 180)
        text = "Cofre abierto sin drama: premio equilibrado y progreso limpio."
    elif item_id in {"pase_ruleta_segura"}:
        reward_cash = random.randint(200, 1300)
        reward_xp = random.randint(20, 80)
        text = "La ruleta giró con red de seguridad. No fue épico, pero no mordió."
    else:
        return 0, 0, 0, "", None
    if reward_cash:
        info["cash"] = _amx22_safe_int(info.get("cash"), 0) + reward_cash
        info["monedas"] = _amx22_safe_int(info.get("monedas"), 0) + max(0, reward_cash)
    if reward_xp:
        info["experiencia"] = _amx22_safe_int(info.get("experiencia"), 0) + reward_xp
    if reward_rep:
        info["reputacion"] = _amx22_safe_int(info.get("reputacion"), 0) + reward_rep
    return reward_cash, reward_xp, reward_rep, text, unlocked_item


# ──────────────────────────────────────────────────────────────────────────────
# Panel central cómodo: menos comandos memorizados, más botones y rutas claras.
# ──────────────────────────────────────────────────────────────────────────────
class AMX22HubView(discord.ui.View):
    def __init__(self, ctx):
        super().__init__(timeout=180)
        self.ctx = ctx
        self.user_id = ctx.author.id
        self.page = "inicio"

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("Abre tu propio panel con `!panel`.", ephemeral=True)
            return False
        return True

    def build(self) -> discord.Embed:
        datos = cargar_datos()
        info = _amx22_get_user_info(datos, self.user_id)
        nivel = _amx22_user_level(info)
        cash = _amx22_safe_int(info.get("cash"), 0)
        bank = _amx22_safe_int(info.get("bank"), 0)
        rep = _amx22_safe_int(info.get("reputacion"), 0)
        xp = _amx22_safe_int(info.get("experiencia"), 0)
        xp_need = _xp_needed_for_level(nivel) if "_xp_needed_for_level" in globals() else max(100, nivel * 100)
        if self.page == "tienda":
            desc = f"{AMX22_LINE}\nCompra, equipa y usa objetos sin perderte.\n{AMX22_END}"
            e = _amx22_embed("🛒 Centro de tienda", desc, AMX22_ACCENT, self.ctx.author)
            e.add_field(name="Rutas rápidas", value="`!tienda nivel` · XP Cards\n`!tienda jugable` · consumibles\n`!buscaritem <texto>` · buscar\n`!decoraciones` · cosméticos", inline=False)
            e.add_field(name="Tu estado", value=f"Nivel **{nivel}** · Cash **{_amx21_money(cash)}** · Rep **{rep}**", inline=False)
            return e
        if self.page == "juegos":
            e = _amx22_embed("🎮 Centro de minijuegos", f"{AMX22_LINE}\nJuega, gana amatistas y sube progreso.\n{AMX22_END}", AMX22_ACCENT, self.ctx.author)
            e.add_field(name="Rápidos", value="`!gemflip <apuesta>`\n`!mineria`\n`!lootbox`\n`!slots <apuesta>`\n`!ruleta <apuesta> rojo`", inline=False)
            e.add_field(name="Consejo", value="Empieza con apuestas pequeñas. La economía castiga la avaricia con guantes de terciopelo morado.", inline=False)
            return e
        if self.page == "perfil":
            e = _amx22_embed("👤 Centro de perfil", f"{AMX22_LINE}\nPersonaliza tu identidad visual.\n{AMX22_END}", AMX22_ACCENT, self.ctx.author)
            equipped = info.get("equipado", {}) if isinstance(info.get("equipado"), dict) else {}
            eq = "\n".join(f"`{k}` → `{v}`" for k, v in list(equipped.items())[:8]) or "Nada equipado todavía."
            e.add_field(name="Progreso", value=f"Nivel **{nivel}** · XP **{xp}/{xp_need}**\n{_amx21_bar(min(xp, xp_need), xp_need, 18)}", inline=False)
            e.add_field(name="Equipado", value=eq, inline=False)
            e.add_field(name="Comandos", value="`!lvl` · `!perfil` · `!inv` · `!equipar <id>` · `!desequipar all`", inline=False)
            return e
        e = _amx22_embed("💜 Panel X AETHER ULTRA", f"{AMX22_LINE}\nTodo lo importante en un solo sitio.\n{AMX22_END}", AMX22_ACCENT, self.ctx.author)
        e.add_field(name="Cuenta", value=f"Cash **{_amx21_money(cash)}**\nBanco **{_amx21_money(bank)}**\nNivel **{nivel}** · Rep **{rep}**", inline=True)
        e.add_field(name="XP", value=f"`{xp}/{xp_need}`\n{_amx21_bar(min(xp, xp_need), xp_need, 16)}", inline=True)
        e.add_field(name="Atajos", value="`!bal` · `!perfil` · `!inv`\n`!tienda` · `!lvl` · `!minijuegosplus`", inline=False)
        return e

    async def refresh(self, interaction: discord.Interaction):
        await interaction.response.edit_message(embed=self.build(), view=self)

    @discord.ui.button(label="Inicio", emoji="🏠", style=discord.ButtonStyle.primary)
    async def home_btn(self, interaction, button):
        self.page = "inicio"
        await self.refresh(interaction)

    @discord.ui.button(label="Perfil", emoji="👤", style=discord.ButtonStyle.secondary)
    async def profile_btn(self, interaction, button):
        self.page = "perfil"
        await self.refresh(interaction)

    @discord.ui.button(label="Tienda", emoji="🛒", style=discord.ButtonStyle.secondary)
    async def shop_btn(self, interaction, button):
        self.page = "tienda"
        await self.refresh(interaction)

    @discord.ui.button(label="Juegos", emoji="🎮", style=discord.ButtonStyle.secondary)
    async def games_btn(self, interaction, button):
        self.page = "juegos"
        await self.refresh(interaction)


