@bot.command(name="buscaritem", aliases=["iteminfo", "finditem"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def buscaritem_cmd_220(ctx, *, busqueda: str = None):
    """Busca objetos de la tienda por nombre, ID, rareza, categoría o descripción."""
    if not busqueda:
        return await ctx.send(embed=_amx22_embed("🔎 Buscar item", "Uso: `!buscaritem card`, `!buscaritem dragon`, `!buscaritem legendario`", AMX22_WARN, ctx.author))
    datos = cargar_datos()
    info = _amx22_get_user_info(datos, ctx.author.id)
    q = busqueda.lower().strip()
    results = []
    for item_id, item in TIENDA_ITEMS.items():
        hay = " ".join(str(item.get(k, "")) for k in ("nombre", "descripcion", "categoria", "rareza", "tipo", "slot", "level_style"))
        hay = f"{item_id} {hay}".lower()
        if q in hay:
            price = _amx21_user_price(item, _amx22_user_level(info)) if "_amx21_user_price" in globals() else int(item.get("precio", 0) or 0)
            results.append((item_id, item, price, _amx22_item_state(info, item_id, item)))
    embed = _amx22_embed("🔎 Buscador de tienda", f"Búsqueda: **{busqueda}** · resultados: **{len(results)}**", AMX22_ACCENT, ctx.author)
    for item_id, item, price, state in results[:12]:
        icon = {"comprado": "✅", "en inventario": "🎒", "bloqueado": "🔒", "disponible": "🟢"}.get(state, "✨")
        embed.add_field(
            name=f"{icon} {item.get('emoji','✨')} {item.get('nombre', item_id)}",
            value=f"ID: `{item_id}` · {item.get('rareza','normal')} · nivel {_amx21_min_level(item)}+\nPrecio: **{_amx21_money(price)}** · estado: **{state}**",
            inline=False,
        )
    if len(results) > 12:
        embed.set_footer(text=f"{XAU_PUBLIC_VERSION_NAME} · mostrando 12 de {len(results)} · afina la búsqueda")
    await ctx.send(embed=embed)


