@bot.command(name="claimsemanal", aliases=["semanal", "weekly"])
@commands.cooldown(1, 10, commands.BucketType.user)
async def claimsemanal_cmd_220(ctx):
    """Recompensa semanal cómoda basada en nivel y reputación."""
    today = datetime.datetime.now(datetime.timezone.utc).date()
    year, week, _ = today.isocalendar()
    key_week = f"{year}-W{week}"
    claims = _amx22_json_load(AMX22_WEEKLY_FILE, {})
    uid = str(ctx.author.id)
    if claims.get(uid) == key_week:
        return await ctx.send(embed=_amx22_embed("⏳ Ya reclamado", "Tu cofre semanal ya fue abierto. Vuelve la próxima semana.", AMX22_WARN, ctx.author))
    datos = cargar_datos()
    info = _amx22_get_user_info(datos, uid)
    nivel = _amx22_user_level(info)
    rep = _amx22_safe_int(info.get("reputacion"), 0)
    cash = random.randint(900, 1800) + nivel * 55 + min(rep, 500) * 4
    xp = random.randint(120, 280) + nivel * 8
    info["cash"] = _amx22_safe_int(info.get("cash"), 0) + cash
    info["monedas"] = _amx22_safe_int(info.get("monedas"), 0) + cash
    info["experiencia"] = _amx22_safe_int(info.get("experiencia"), 0) + xp
    claims[uid] = key_week
    guardar_datos(datos)
    _amx22_json_save(AMX22_WEEKLY_FILE, claims)
    embed = _amx22_embed("🎁 Cofre semanal abierto", f"{AMX22_LINE}\nHas reclamado tu recompensa semanal.\n{AMX22_END}", AMX22_OK, ctx.author)
    embed.add_field(name="💎 Amatistas", value=f"+{_amx21_money(cash)}", inline=True)
    embed.add_field(name="⚡ XP", value=f"+{xp} XP", inline=True)
    embed.add_field(name="📈 Escala", value=f"Nivel **{nivel}** · Rep **{rep}**", inline=False)
    await ctx.send(embed=embed)


