_amx22_remove_command("gemflip", "cristalflip2")
@bot.command(name="gemflip", aliases=["cristalflip2"])
@commands.cooldown(1, 8, commands.BucketType.user)
async def gemflip_cmd_220(ctx, apuesta: str = None, lado: str = "cara"):
    if not apuesta:
        return await ctx.send(embed=_amx22_embed("🪙 GemFlip", "Uso: `!gemflip <apuesta> [cara/cruz]`", AMX22_WARN, ctx.author))
    datos = cargar_datos()
    info = _amx22_get_user_info(datos, ctx.author.id)
    cash = _amx22_safe_int(info.get("cash"), 0)
    amount = cash if str(apuesta).lower() == "all" else _amx22_safe_int(apuesta, 0)
    amount = max(1, min(amount, cash, 25000))
    if amount <= 0 or cash < amount:
        return await ctx.send(embed=_amx22_embed("💸 Cash insuficiente", f"Tu cash: **{_amx21_money(cash)}**", AMX22_BAD, ctx.author))
    lado = lado.lower()
    if lado not in {"cara", "cruz"}:
        lado = random.choice(["cara", "cruz"])
    msg = await ctx.send(embed=_amx22_embed("🪙 GemFlip", "La moneda amatista está girando... `◆◇◆`", AMX22_ACCENT, ctx.author))
    for frame in ["◆◇◇", "◇◆◇", "◇◇◆", "✦◆✦"]:
        await asyncio.sleep(0.45)
        try:
            await msg.edit(embed=_amx22_embed("🪙 GemFlip", f"Girando... `{frame}`", AMX22_ACCENT, ctx.author))
        except Exception:
            pass
    result = random.choice(["cara", "cruz"])
    won = result == lado
    delta = amount if won else -amount
    info["cash"] = cash + delta
    if won:
        info["monedas"] = _amx22_safe_int(info.get("monedas"), 0) + amount
        info["experiencia"] = _amx22_safe_int(info.get("experiencia"), 0) + random.randint(8, 25)
    guardar_datos(datos)
    _amx22_register_game(str(ctx.author.id), "gemflip", won, delta)
    color = AMX22_OK if won else AMX22_BAD
    title = "💜 GemFlip ganado" if won else "🖤 GemFlip perdido"
    embed = _amx22_embed(title, f"Elegiste **{lado}** · salió **{result}**\nResultado: **{_amx21_money(delta)}**", color, ctx.author)
    await msg.edit(embed=embed)


