    xp_gain = random.randint(15, 60)
    if roll >= 92:
        pool = [k for k, v in TIENDA_ITEMS.items() if not v.get("consumible") and _amx21_slot_for_item(k, v) and _amx21_min_level(v) <= _amx22_user_level(info) and not _amx21_owned(info, k, v)]
        if pool:
            won_item = random.choice(pool)
            _amx21_add_item_to_inventory(info, won_item, TIENDA_ITEMS[won_item], 1)
    elif roll >= 40:
        cash_gain = random.randint(300, 2200)
    else:
        cash_gain = random.randint(50, 350)
    if cash_gain:
        info["cash"] = _amx22_safe_int(info.get("cash"), 0) + cash_gain
        info["monedas"] = _amx22_safe_int(info.get("monedas"), 0) + max(0, cash_gain - cost)
    info["experiencia"] = _amx22_safe_int(info.get("experiencia"), 0) + xp_gain
    guardar_datos(datos)
    net = cash_gain - cost
    _amx22_register_game(str(ctx.author.id), "lootbox", bool(won_item or net > 0), net)
    embed = _amx22_embed("📦 Lootbox abierta", "La caja se abrió con humo violeta y ruido de inventario.", AMX22_ACCENT, ctx.author)
    embed.add_field(name="Coste", value=f"-{_amx21_money(cost)}", inline=True)
    embed.add_field(name="Premio", value=(f"`{won_item}`" if won_item else f"+{_amx21_money(cash_gain)}"), inline=True)
    embed.add_field(name="XP", value=f"+{xp_gain} XP", inline=True)
    await ctx.send(embed=embed)


