@bot.command(name="inv", aliases=["inventario"])
@commands.cooldown(1, 6, commands.BucketType.user)
async def inv_cmd_220(ctx, miembro: discord.Member = None, filtro: str = "todo", pagina: int = 1):
    miembro = miembro or ctx.author
    datos = cargar_datos()
    info = _amx22_get_user_info(datos, miembro.id)
    inv = info.get("items", {}) if isinstance(info.get("items"), dict) else {}
    filtro = (filtro or "todo").lower()
    rows = []
    for key, val in inv.items():
        if isinstance(val, dict):
            item_id = val.get("id") or key
            item = TIENDA_ITEMS.get(item_id, {})
            categoria = str(val.get("categoria") or item.get("categoria") or "otros").lower()
            slot = str(val.get("slot") or _amx21_slot_for_item(item_id, item) or "").lower()
            if filtro not in {"todo", "all"} and filtro not in categoria and filtro not in slot and filtro not in str(item_id).lower():
                continue
            qty = _amx22_safe_int(val.get("cantidad"), 1)
            qty_text = f" x{qty}" if qty > 1 else ""
            rows.append((categoria, f"{val.get('emoji') or item.get('emoji','✨')} `{item_id}`{qty_text}\n{val.get('nombre') or item.get('nombre', item_id)} · {categoria}"))
        else:
            if filtro not in {"todo", "all"} and filtro not in str(key).lower():
                continue
            rows.append(("otros", f"🎁 `{key}`"))
    rows.sort(key=lambda x: (x[0], x[1]))
    pages = _amx21_pages(rows, 8)
    idx = max(0, min(int(pagina or 1) - 1, len(pages) - 1))
    embed = _amx22_embed("🎒 Inventario Premium", f"{AMX22_LINE}\nUsuario: **{miembro.display_name}** · filtro: `{filtro}`\nPágina **{idx+1}/{len(pages)}**\n{AMX22_END}", AMX22_ACCENT, miembro)
    if not pages[idx]:
        embed.add_field(name="Vacío", value="No hay objetos con ese filtro. Prueba `!tienda` o `!buscaritem card`.", inline=False)
    else:
        for _, text in pages[idx]:
            embed.add_field(name="◇ Item", value=text, inline=True)
    embed.add_field(name="Filtros útiles", value="`!inv todo` · `!inv nivel` · `!inv jugable` · `!inv mascota` · `!decoraciones`", inline=False)
    await ctx.send(embed=embed)


