        embed.description = f"{item.get('emoji','🎴')} **{item.get('nombre', item_id)}**\nID: `{item_id}`\nEstado: {'✅ comprado' if _amx23_item_owned(datos[uid], item_id, item) else '🟢 preview disponible'}"
