# @bot.command(name="xpcards", aliases=["fondosnivel", "levelcards", "tarjetasnivel", "estilosxp"])  # clean core: decorador antiguo desactivado
@commands.cooldown(1, 6, commands.BucketType.user)
async def xpcards_cmd_230(ctx, filtro: str = "todo", pagina: int = 1):
    datos = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    filtro = str(filtro or "todo").lower()
    pool = [(k, v) for k, v in TIENDA_ITEMS.items() if _amx23_slot_for_item(k, v) in {"lvl_fondo", "lvl_marco"}]
    if filtro in {"comprado", "comprados", "owned", "mios"}:
        pool = [(k, v) for k, v in pool if _amx23_item_owned(info, k, v)]
    elif filtro in {"bloqueado", "bloqueados", "locked"}:
        pool = [(k, v) for k, v in pool if not _amx23_item_owned(info, k, v)]
    pool.sort(key=lambda kv: (int(kv[1].get("nivel_min", 1) or 1), int(kv[1].get("precio", 0) or 0), kv[0]))
    per = 7
    pages = [pool[i:i+per] for i in range(0, len(pool), per)] or [[]]
    idx = max(0, min(int(pagina or 1)-1, len(pages)-1))
    embed = _amx23_embed("🎴 Galería XP Cards", f"{AMX23_LINE}\nFiltro: `{filtro}` · Página **{idx+1}/{len(pages)}**\n✅ comprado · 🟢 disponible · 🔒 no comprado/bloqueado\n{AMX23_LINE}", AMX23_PURPLE, ctx.author)
    for item_id, item in pages[idx]:
        owned = _amx23_item_owned(info, item_id, item)
        state = "✅ comprado" if owned else "🟢 disponible" if int(item.get("nivel_min", 1) or 1) <= _amx23_level(info) else f"🔒 nivel {item.get('nivel_min')}"
        slot = _amx23_slot_for_item(item_id, item)
        embed.add_field(name=f"{item.get('emoji','🎴')} {item.get('nombre', item_id)}", value=f"{state}\nID: `{item_id}` · slot `{slot}`\n`!previewxp {item_id}` · `!equipar {item_id}`", inline=False)
    embed.add_field(name="🧭 Comandos", value="`!xpcards comprado` · `!xpcards bloqueado 2` · `!previewxp <id>` · `!comprar <id>` · `!equipar <id>`", inline=False)
    await ctx.send(embed=embed)


# @bot.command(name="equipar", aliases=["equip"])  # clean core: decorador antiguo desactivado
@commands.cooldown(1, 4, commands.BucketType.user)
async def equipar_cmd_230(ctx, *, item_query: str = None):
    if not item_query:
        return await ctx.send(embed=_amx23_embed("🎨 Equipar cosmético", "Uso: `!equipar <id>`\nEjemplo: `!equipar xpcard_lunar_dream`", AMX23_INFO, ctx.author))
    item_id, item = _amx23_find_item(item_query)
    if not item:
        return await ctx.send(embed=_amx23_embed("❌ No encontrado", "No encontré ese item. Prueba `!buscaritem <texto>` o `!xpcards`.", AMX23_BAD, ctx.author))
    slot = _amx23_slot_for_item(item_id, item)
    if not slot:
        return await ctx.send(embed=_amx23_embed("⚠️ No equipable", f"{item.get('emoji','🎁')} **{item.get('nombre', item_id)}** no es cosmético equipable. Si es consumible usa `!usar {item_id}`.", AMX23_BAD, ctx.author))
    datos = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    if not _amx23_item_owned(info, item_id, item):
        return await ctx.send(embed=_amx23_embed("🔒 No comprado", f"Primero compra este cosmético con `!comprar {item_id}`.\nTambién puedes verlo con `!previewxp {item_id}` si es una XP Card.", AMX23_BAD, ctx.author))
    eq = _amx23_equipped(info)
    eq[slot] = item_id
    guardar_datos(datos)
    embed = _amx23_embed("✅ Cosmético equipado", f"{item.get('emoji','💎')} **{item.get('nombre', item_id)}**\nSlot activo: `{slot}`", AMX23_OK, ctx.author)
    if slot in {"lvl_fondo", "lvl_marco"}:
        embed.add_field(name="XP Card", value="Ya se verá en `!lvl`, `!xpcard`, `!cardxp` y `!tarjetaxp`.", inline=False)
    await ctx.send(embed=embed)

# ──────────────────────────────────────────────────────────────────────────────
# Membresía Royal: registro, salida con permiso y anti-saturación.
# ──────────────────────────────────────────────────────────────────────────────
def _amx23_membership_db() -> dict:
    data = _amx23_load_json(AMX23_MEMBERSHIP_REQUESTS_FILE, {})
    data.setdefault("requests", {})
    data.setdefault("user_index", {})
    return data


def _amx23_membership_save(data: dict) -> None:
    data.setdefault("requests", {})
    data.setdefault("user_index", {})
    _amx23_save_json(AMX23_MEMBERSHIP_REQUESTS_FILE, data)


def _amx23_save_membership_db(data: dict) -> None:
    _amx23_membership_save(data)


def _amx23_config() -> dict:
    cfg = _amx23_load_json(AMX23_MEMBERSHIP_CONFIG_FILE, {})
    cfg.setdefault("join_cooldown", AMX23_JOIN_COOLDOWN_SECONDS)
    cfg.setdefault("leave_cooldown", AMX23_LEAVE_COOLDOWN_SECONDS)
    cfg.setdefault("max_requests_24h", AMX23_MAX_REQUESTS_PER_24H)
    return cfg


def _amx23_request_id(kind: str, user_id: int) -> str:
    raw = f"{kind}:{user_id}:{time.time()}:{random.randint(1000,9999)}"
    return hashlib.sha1(raw.encode()).hexdigest()[:10].upper()


def _amx23_get_member_role(guild: discord.Guild):
    for rid in [globals().get("ROLE_MIEMBRO"), globals().get("VIP_ROLE_ID")]:
        try:
            role = guild.get_role(int(rid)) if rid else None
            if role:
                return role
        except Exception:
            pass
    names = {"miembro", "member", "royal member", "premium", "vip"}
    for role in guild.roles:
        if role.name.strip().lower() in names:
            return role
    return None


def _amx23_membership_roles(guild: discord.Guild, kind: str = None):
    ids = [globals().get("ROLE_MIEMBRO"), globals().get("ROLE_COMPETITIVO"), globals().get("ROLE_FREESTYLER"), globals().get("ROLE_CCH")]
    roles = []
    for rid in ids:
        try:
            role = guild.get_role(int(rid)) if rid else None
            if role and role not in roles:
                roles.append(role)
        except Exception:
            pass
    if kind:
        mapping = {
            "COMPETITIVO": globals().get("ROLE_COMPETITIVO"),
            "FREESTYLER": globals().get("ROLE_FREESTYLER"),
            "CCH": globals().get("ROLE_CCH"),
        }
        try:
            role = guild.get_role(int(mapping.get(kind))) if mapping.get(kind) else None
            if role and role not in roles:
                roles.append(role)
        except Exception:
            pass
    return roles


def _amx23_has_member_role(member: discord.Member) -> bool:
    role = _amx23_get_member_role(member.guild)
    return bool(role and role in member.roles)


def _amx23_can_make_request(user_id: int, kind: str) -> tuple[bool, str]:
    db = _amx23_membership_db()
    cfg = _amx23_config()
    now = time.time()
    uid = str(user_id)
    requests = db.get("requests", {})
    user_reqs = [r for r in requests.values() if str(r.get("user_id")) == uid]
    for req in user_reqs:
        if req.get("kind") == kind and req.get("status") == "pending":
            return False, f"ya tienes una solicitud `{kind}` pendiente. Espera la respuesta de Markelson."
    last_same = [r for r in user_reqs if r.get("kind") == kind]
    cooldown = cfg.get("leave_cooldown" if kind == "leave" else "join_cooldown", AMX23_JOIN_COOLDOWN_SECONDS)
    if last_same:
        latest = max(float(r.get("created_at", 0) or 0) for r in last_same)
        remaining = int(cooldown - (now - latest))
        if remaining > 0:
            return False, f"anti-saturación activo. Te faltan `{formato_tiempo(remaining) if 'formato_tiempo' in globals() else str(remaining)+'s'}` para volver a solicitar."
    recent = [r for r in user_reqs if now - float(r.get("created_at", 0) or 0) <= 86400]
    if len(recent) >= int(cfg.get("max_requests_24h", AMX23_MAX_REQUESTS_PER_24H)):
        return False, "has llegado al límite de solicitudes en 24 horas. Así Markelson no se satura."
    return True, "ok"


async def _amx23_fetch_member(guild: discord.Guild, user_id: int):
    if not guild:
        return None
    member = guild.get_member(int(user_id))
    if member:
        return member
    try:
        return await guild.fetch_member(int(user_id))
    except Exception:
        return None


def _amx23_member_request_embed(req: dict, title: str = None) -> discord.Embed:
    kind = req.get("kind")
    color = AMX23_GOLD if kind == "join" else AMX23_BAD
    title = title or ("💎 Solicitud de Membresía" if kind == "join" else "🚪 Solicitud de Salida de Membresía")
    embed = _amx23_embed(title, f"{AMX23_LINE}\nID solicitud: `{req.get('id')}`\nEstado: **{req.get('status','pending')}**\n{AMX23_LINE}", color)
    embed.add_field(name="👤 Usuario", value=f"<@{req.get('user_id')}>\n`{req.get('user_id')}`", inline=True)
    embed.add_field(name="🕒 Creada", value=f"`{req.get('created_text','sin fecha')}`", inline=True)
    if kind == "join":
        embed.add_field(name="🪪 Nombre real", value=str(req.get("real_name", "No indicado"))[:1024], inline=True)
        embed.add_field(name="🎮 Tipo", value=str(req.get("member_type", "No indicado")), inline=True)
        embed.add_field(name="🏆 Rango", value=str(req.get("rank", "No indicado")), inline=True)
        embed.add_field(name="💬 Habilidades", value=str(req.get("skills", "Sin texto"))[:1024], inline=False)
    else:
        embed.add_field(name="🪪 Nombre real", value=str(req.get("real_name", "No indicado"))[:1024], inline=True)
        embed.add_field(name="📌 Motivo de salida", value=str(req.get("reason", "Sin motivo"))[:1024], inline=False)
    embed.add_field(name="🛡️ Anti-saturación", value="1 solicitud pendiente por persona + cooldown + máximo diario.", inline=False)
    return embed


async def _amx23_send_owner_request(req: dict) -> bool:
    try:
        owner = await bot.fetch_user(MI_ID)
        await owner.send(embed=_amx23_member_request_embed(req), view=AMX23MembershipDecisionView(req.get("id")))
        return True
    except Exception as exc:
        print(f"[AMX23 MEMBERSHIP DM] No pude enviar solicitud a Markelson: {exc!r}")
        return False


async def _amx23_decide_membership(request_id: str, approve: bool, actor: discord.abc.User, public_reason: str = "") -> tuple[bool, str, discord.Embed]:
    db = _amx23_membership_db()
    req = db.get("requests", {}).get(str(request_id))
    if not req:
        return False, "No encontré esa solicitud.", _amx23_embed("❌ Solicitud no encontrada", f"ID: `{request_id}`", AMX23_BAD)
    if req.get("status") != "pending":
        return False, "La solicitud ya fue resuelta.", _amx23_member_request_embed(req, "⚠️ Solicitud ya resuelta")
    guild = bot.get_guild(int(req.get("guild_id") or GUILD_ID)) or bot.get_guild(GUILD_ID)
    member = await _amx23_fetch_member(guild, int(req.get("user_id"))) if guild else None
    req["status"] = "approved" if approve else "rejected"
    req["decided_at"] = time.time()
    req["decided_text"] = _amx23_ts()
    req["decided_by"] = getattr(actor, "id", None)
    req["decision_reason"] = public_reason or "Sin motivo extra."
    ok_actions = []
    failed_actions = []
    if approve and member and guild:
        bot_member = guild.me
        if req.get("kind") == "join":
            roles = []
            base = _amx23_get_member_role(guild)
            if base:
                roles.append(base)
            roles += _amx23_membership_roles(guild, req.get("member_type"))
            roles = [r for r in roles if r and r not in member.roles]
            for role in roles:
                try:
                    if role.managed or (bot_member and role >= bot_member.top_role):
                        failed_actions.append(f"No puedo asignar `{role.name}` por jerarquía o rol gestionado.")
                        continue
                    await member.add_roles(role, reason=f"Membresía aprobada por {actor}")
                    ok_actions.append(f"Rol añadido: `{role.name}`")
                except Exception as exc:
                    failed_actions.append(f"Error añadiendo `{role.name}`: {exc!r}")
        elif req.get("kind") == "leave":
            roles = [r for r in _amx23_membership_roles(guild) if r in member.roles]
            if not roles:
                base = _amx23_get_member_role(guild)
                if base and base in member.roles:
                    roles = [base]
            for role in roles:
                try:
                    if role.managed or (bot_member and role >= bot_member.top_role):
                        failed_actions.append(f"No puedo quitar `{role.name}` por jerarquía o rol gestionado.")
                        continue
                    await member.remove_roles(role, reason=f"Salida de membresía aprobada por {actor}")
                    ok_actions.append(f"Rol quitado: `{role.name}`")
                except Exception as exc:
                    failed_actions.append(f"Error quitando `{role.name}`: {exc!r}")
    elif approve and not member:
        failed_actions.append("El usuario ya no está en el servidor o no pude obtenerlo.")
    _amx23_membership_save(db)
    if member:
        try:
            if approve:
                msg = "✅ Tu solicitud de membresía fue aceptada. Bienvenido al club X AETHER ULTRA." if req.get("kind") == "join" else "✅ Markelson aprobó tu salida de la membresía. Tus roles fueron retirados si el bot tenía permisos."
            else:
                msg = "❌ Tu solicitud fue rechazada por Markelson."
            if public_reason:
                msg += f"\nMotivo: {public_reason}"
            await member.send(msg)
        except Exception:
            pass
    embed = _amx23_member_request_embed(req, "✅ Solicitud aprobada" if approve else "🚫 Solicitud rechazada")
    if ok_actions:
        embed.add_field(name="Acciones realizadas", value="\n".join(ok_actions)[:1024], inline=False)
    if failed_actions:
        embed.add_field(name="Avisos", value="\n".join(failed_actions)[:1024], inline=False)
    return True, "resuelto", embed


class AMX23JoinModal(Modal, title="💎 Registro Royal X AETHER ULTRA"):
    real_name = TextInput(label="Nombre real", placeholder="Ej: Markel", max_length=60)
    age = TextInput(label="Edad", placeholder="Ej: 19", max_length=2)
    member_type = TextInput(label="Tipo", placeholder="FREESTYLER / COMPETITIVO / CCH", max_length=15)
    rank = TextInput(label="Rango Rocket League", placeholder="Ej: C1, GC2, SSL,...", max_length=10)
    skills = TextInput(label="Habilidades y por qué quieres entrar", style=discord.TextStyle.long, placeholder="Cuéntanos qué aportas al clan, actividad, juegos, streams, etc.", max_length=900)

    async def on_submit(self, interaction: discord.Interaction):
        kind = str(self.member_type.value or "").strip().upper()
        if kind not in {"FREESTYLER", "COMPETITIVO", "CCH"}:
            return await interaction.response.send_message("⚠️ El tipo debe ser exactamente `FREESTYLER`, `COMPETITIVO` o `CCH`.", ephemeral=True)
        ok, reason = _amx23_can_make_request(interaction.user.id, "join")
        if not ok:
            return await interaction.response.send_message(f"🛡️ {reason}", ephemeral=True)
        if isinstance(interaction.user, discord.Member) and _amx23_has_member_role(interaction.user):
            return await interaction.response.send_message("💜 Ya tienes rol de miembro. Si quieres cambiar tu tipo, habla con staff o abre ticket.", ephemeral=True)
        req_id = _amx23_request_id("join", interaction.user.id)
        req = {
            "id": req_id, "kind": "join", "status": "pending", "user_id": interaction.user.id,
            "user_tag": str(interaction.user), "guild_id": interaction.guild.id if interaction.guild else GUILD_ID,
            "created_at": time.time(), "created_text": _amx23_ts(),
            "real_name": str(self.real_name.value).strip(), "age": str(self.age.value).strip(),
            "member_type": kind, "rank": str(self.rank.value).strip(), "skills": str(self.skills.value).strip(),
        }
        db = _amx23_membership_db()
        db["requests"][req_id] = req
        db.setdefault("user_index", {}).setdefault(str(interaction.user.id), []).append(req_id)
        _amx23_membership_save(db)
        sent = await _amx23_send_owner_request(req)
        embed = _amx23_embed("📨 Solicitud enviada", f"{AMX23_LINE}\nTu solicitud Royal fue enviada a Markelson.\nID: `{req_id}`\n{AMX23_LINE}", AMX23_OK, interaction.user)
        embed.add_field(name="Anti-saturación", value="No podrás mandar otra solicitud igual hasta que se revise o pase el cooldown.", inline=False)
        if not sent:
            embed.add_field(name="Aviso", value="No pude mandar DM a Markelson, pero la solicitud quedó guardada. Usa `!membresia_pendientes` como admin.", inline=False)
        await interaction.response.send_message(embed=embed, ephemeral=True)


class AMX23LeaveModal(Modal, title="🚪 Salir de Miembro"):
    real_name = TextInput(label="Nombre real", placeholder="Tu nombre real", max_length=60)
    reason = TextInput(label="Motivo de salida", style=discord.TextStyle.long, placeholder="Explica por qué quieres salir de miembro. Markelson debe aprobarlo.", max_length=900)

    async def on_submit(self, interaction: discord.Interaction):
        ok, reason_text = _amx23_can_make_request(interaction.user.id, "leave")
        if not ok:
            return await interaction.response.send_message(f"🛡️ {reason_text}", ephemeral=True)
        if isinstance(interaction.user, discord.Member) and not _amx23_has_member_role(interaction.user):
            return await interaction.response.send_message("⚠️ No tienes el rol de miembro, así que no hay membresía que retirar.", ephemeral=True)
        req_id = _amx23_request_id("leave", interaction.user.id)
        req = {
            "id": req_id, "kind": "leave", "status": "pending", "user_id": interaction.user.id,
            "user_tag": str(interaction.user), "guild_id": interaction.guild.id if interaction.guild else GUILD_ID,
            "created_at": time.time(), "created_text": _amx23_ts(),
            "real_name": str(self.real_name.value).strip(), "reason": str(self.reason.value).strip(),
        }
        db = _amx23_membership_db()
        db["requests"][req_id] = req
        db.setdefault("user_index", {}).setdefault(str(interaction.user.id), []).append(req_id)
        _amx23_membership_save(db)
        sent = await _amx23_send_owner_request(req)
        embed = _amx23_embed("🚪 Solicitud de salida enviada", f"Tu salida **no se aplica todavía**. Markelson debe aprobarla.\nID: `{req_id}`", AMX23_GOLD, interaction.user)
        embed.add_field(name="Anti-saturación", value="Solicitud guardada con cooldown para no saturar los DMs de Markelson.", inline=False)
        if not sent:
            embed.add_field(name="Aviso", value="No pude mandar DM a Markelson, pero la solicitud quedó guardada.", inline=False)
        await interaction.response.send_message(embed=embed, ephemeral=True)


class AMX23MembershipDecisionView(View):
    def __init__(self, request_id: str):
        super().__init__(timeout=None)
        self.request_id = str(request_id)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != MI_ID:
            await interaction.response.send_message("🔒 Solo Markelson puede decidir esta solicitud.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Aprobar", emoji="✅", style=discord.ButtonStyle.success)
    async def approve_btn(self, interaction: discord.Interaction, button: Button):
        ok, msg, embed = await _amx23_decide_membership(self.request_id, True, interaction.user)
        await interaction.response.edit_message(embed=embed, view=None)

    @discord.ui.button(label="Rechazar", emoji="❌", style=discord.ButtonStyle.danger)
    async def reject_btn(self, interaction: discord.Interaction, button: Button):
        ok, msg, embed = await _amx23_decide_membership(self.request_id, False, interaction.user)
        await interaction.response.edit_message(embed=embed, view=None)


