def _amx231_force_help_normalized():
    """Normaliza el catálogo de ayuda para que ningún bloque viejo use .extend sobre dict."""
    global COMMAND_CATEGORIES
    try:
        if not isinstance(COMMAND_CATEGORIES, dict):
            COMMAND_CATEGORIES = {}
        fixed = {}
        for cat, value in list(COMMAND_CATEGORIES.items()):
            cat = str(cat or "otros").lower().strip() or "otros"
            if isinstance(value, dict):
                fixed[cat] = {str(k): str(v) for k, v in value.items()}
            elif isinstance(value, (list, tuple, set)):
                fixed[cat] = {str(x): "Comando disponible." for x in value}
            else:
                fixed[cat] = {str(value): "Función disponible."}
        COMMAND_CATEGORIES = fixed
        return True, "Catálogo de ayuda normalizado."
    except Exception as exc:
        return False, f"No se pudo normalizar ayuda: {exc!r}"


def _amx231_pillow_status():
    """Diagnóstico fuerte: confirma PIL, Pillow y versión real usada por Python."""
    try:
        ok, msg = _amx23_ensure_pillow() if "_amx23_ensure_pillow" in globals() else (False, "_amx23_ensure_pillow no existe")
    except Exception as exc:
        ok, msg = False, f"_amx23_ensure_pillow falló: {exc!r}"
    try:
        import PIL
        version = getattr(PIL, "__version__", "desconocida")
        pil_path = getattr(PIL, "__file__", "ruta desconocida")
    except Exception as exc:
        version = "no importado"
        pil_path = repr(exc)
    return bool(ok), f"{msg}\nPIL versión: {version}\nRuta: {pil_path}"


def _amx231_count_bot_runs() -> int:
    try:
        with open(__file__, "r", encoding="utf-8") as f:
            return len(re.findall(r"^[\t ]*bot\.run\(", f.read(), flags=re.M))
    except Exception:
        return -1


def _amx231_command_collision_report(limit: int = 18):
    seen = {}
    dup = []
    try:
        for cmd in list(bot.commands):
            for token in [cmd.name] + list(getattr(cmd, "aliases", []) or []):
                key = str(token).lower()
                if key in seen and seen[key] != cmd.name:
                    dup.append((key, seen[key], cmd.name))
                else:
                    seen[key] = cmd.name
    except Exception:
        pass
    return dup[:limit], len(dup)


def _amx231_membership_compact_stats():
    try:
        db = _amx23_membership_db() if "_amx23_membership_db" in globals() else {"requests": {}}
        rows = list((db.get("requests") or {}).values())
        pending = sum(1 for r in rows if r.get("status") == "pending")
        approved = sum(1 for r in rows if r.get("status") == "approved")
        rejected = sum(1 for r in rows if r.get("status") == "rejected")
        return pending, approved, rejected, len(rows)
    except Exception:
        return 0, 0, 0, 0


