@bot.command(name="membresia_limpiar", aliases=["limpiarsolicitudes", "purga_membresia"])
@commands.has_permissions(administrator=True)
@commands.cooldown(1, 3, commands.BucketType.user)  # X AETHER ULTRA PATCH: cooldown global anti-spam
async def membresia_limpiar_cmd_231(ctx, dias: int = AMX231_REQUEST_MAX_AGE_DAYS):
    if "_amx23_membership_db" not in globals() or "_amx23_save_membership_db" not in globals():
        return await ctx.send(embed=_amx231_embed("⚠️ Membresía no disponible", "No encontré el módulo Royal Membership cargado.", AMX231_BAD, ctx.author))
    db = _amx23_membership_db()
    reqs = db.setdefault("requests", {})
    now = _amx231_now()
    keep = {}
    removed = 0
    for rid, req in list(reqs.items()):
        status = req.get("status")
        created = float(req.get("created_at", 0) or 0)
        age_days = (now - created) / 86400 if created else 999
        if status != "pending" and age_days >= max(1, int(dias or 1)):
            removed += 1
        else:
            keep[rid] = req
    db["requests"] = keep
    _amx23_save_membership_db(db)
    await ctx.send(embed=_amx231_embed("🧹 Solicitudes limpiadas", f"Se eliminaron **{removed}** solicitudes cerradas con más de **{dias}** día(s).\nLas solicitudes pendientes no se tocan.", AMX231_OK, ctx.author))


