def _amx242_load_json(path: str, default):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, type(default)) else default
    except Exception:
        return default


def _amx242_save_json(path: str, data) -> None:
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as exc:
        print(f"[AMX242 JSON] {path}: {exc!r}")


def _amx242_ticket_db() -> dict:
    data = _amx242_load_json(AMX242_TICKET_DB_FILE, {})
    data.setdefault("tickets", {})
    data.setdefault("stats", {"created": 0, "closed": 0, "claimed": 0})
    return data


def _amx242_ticket_save(data: dict) -> None:
    data.setdefault("tickets", {})
    data.setdefault("stats", {"created": 0, "closed": 0, "claimed": 0})
    _amx242_save_json(AMX242_TICKET_DB_FILE, data)


def _amx242_safe_channel_name(text: str) -> str:
    text = re.sub(r"[^a-zA-Z0-9áéíóúñÁÉÍÓÚÑ_-]+", "-", str(text or "ticket").lower())
    text = re.sub(r"-+", "-", text).strip("-")
    return text[:44] or "ticket"


async def _amx242_get_or_create_category(guild: discord.Guild):
    category = discord.utils.get(guild.categories, name=TICKET_CATEGORY_NAME)
    if category:
        return category
    overwrites = {guild.default_role: discord.PermissionOverwrite(view_channel=False)}
    return await guild.create_category(TICKET_CATEGORY_NAME, overwrites=overwrites, reason="X AETHER ULTRA Ticket Royal setup")


async def _amx242_get_or_create_logs(guild: discord.Guild):
    channel = discord.utils.get(guild.text_channels, name=TICKET_LOGS_CHANNEL_NAME)
    if channel:
        return channel
    category = await _amx242_get_or_create_category(guild)
    overwrites = {guild.default_role: discord.PermissionOverwrite(view_channel=False)}
    for role in guild.roles:
        if role.permissions.manage_channels or role.permissions.administrator:
            overwrites[role] = discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True)
    return await guild.create_text_channel(TICKET_LOGS_CHANNEL_NAME, category=category, overwrites=overwrites, reason="X AETHER ULTRA Ticket logs")


def _amx242_staff_overwrites(guild: discord.Guild, member: discord.Member):
    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        member: discord.PermissionOverwrite(view_channel=True, send_messages=True, attach_files=True, read_message_history=True),
    }
    if guild.me:
        overwrites[guild.me] = discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True, read_message_history=True)
    for role in guild.roles:
        try:
            if role.permissions.administrator or role.permissions.manage_channels or role.permissions.manage_messages:
                overwrites[role] = discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_messages=True, read_message_history=True)
        except Exception:
            pass
    return overwrites


async def _amx242_make_transcript(channel: discord.TextChannel):
    lines = [f"Transcript X AETHER · {channel.name}", f"Fecha UTC: {datetime.datetime.utcnow().isoformat()}", ""]
    try:
        async for msg in channel.history(limit=700, oldest_first=True):
            content = msg.content or ""
            attach = " ".join(a.url for a in msg.attachments) if msg.attachments else ""
            lines.append(f"[{msg.created_at:%Y-%m-%d %H:%M:%S}] {msg.author}: {content} {attach}".strip())
    except Exception as exc:
        lines.append(f"[ERROR TRANSCRIPT] {exc!r}")
    raw = "\n".join(lines).encode("utf-8", errors="replace")
    buf = io.BytesIO(raw)
    buf.seek(0)
    return discord.File(buf, filename=f"transcript_{channel.id}.txt")


def _amx242_is_staff(member: discord.Member) -> bool:
    return bool(
        getattr(member.guild_permissions, "administrator", False)
        or getattr(member.guild_permissions, "manage_channels", False)
        or getattr(member.guild_permissions, "manage_messages", False)
    )


class AMX242TicketModal(Modal):
    def __init__(self, kind: str):
        super().__init__(title=f"Ticket X AETHER · {kind.title()}")
        self.kind = kind
        self.asunto = TextInput(label="Asunto", placeholder="Ej: problema con tienda, reporte, soporte...", max_length=80)
        self.detalle = TextInput(label="Detalles", placeholder="Explica qué necesitas con claridad.", style=discord.TextStyle.long, max_length=1200)
        self.add_item(self.asunto)
        self.add_item(self.detalle)

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        user = interaction.user
        if not guild or not isinstance(user, discord.Member):
            return await interaction.response.send_message("❌ Esto solo funciona dentro de un servidor.", ephemeral=True)
        category = await _amx242_get_or_create_category(guild)
        db = _amx242_ticket_db()
        open_for_user = [r for r in db.get("tickets", {}).values() if r.get("user_id") == user.id and r.get("status") == "open"]
        if len(open_for_user) >= 3:
            return await interaction.response.send_message("⚠️ Tienes demasiados tickets abiertos. Cierra alguno antes de crear otro.", ephemeral=True)
        short = hashlib.sha1(f"{user.id}:{time.time()}".encode()).hexdigest()[:5]
        name = f"ticket-{self.kind}-{_amx242_safe_channel_name(user.display_name)}-{short}"
        channel = await guild.create_text_channel(name, category=category, overwrites=_amx242_staff_overwrites(guild, user), reason=f"Ticket {self.kind} creado por {user}")
        ticket_id = str(channel.id)
        db["tickets"][ticket_id] = {"id": ticket_id, "kind": self.kind, "user_id": user.id, "user_tag": str(user), "status": "open", "created_at": time.time(), "claimed_by": None, "subject": str(self.asunto.value)}
        db["stats"]["created"] = int(db["stats"].get("created", 0)) + 1
        _amx242_ticket_save(db)
        e = _amx242_embed("🎫 Ticket Royal abierto", f"{AMX242_LINE}\n{user.mention}, tu ticket ya está vivo. Un miembro del staff lo revisará.\n{AMX242_LINE}", AMX242_PURPLE, user)
        e.add_field(name="Tipo", value=f"`{self.kind}`", inline=True)
        e.add_field(name="Asunto", value=f"`{self.asunto.value}`", inline=True)
        e.add_field(name="Detalles", value=str(self.detalle.value)[:1024], inline=False)
        e.add_field(name="Controles", value="`📌 Reclamar` staff · `➕ Añadir` staff · `📜 Transcript` · `🔒 Cerrar`", inline=False)
        await channel.send(content=f"{user.mention}", embed=e, view=AMX242TicketChannelView(ticket_id))
        await interaction.response.send_message(embed=_amx242_embed("✅ Ticket creado", f"Tu ticket está en {channel.mention}.", AMX242_OK, user), ephemeral=True)


class AMX242AddUserModal(Modal):
    def __init__(self, ticket_id: str):
        super().__init__(title="Añadir usuario al ticket")
        self.ticket_id = ticket_id
        self.user_text = TextInput(label="Usuario", placeholder="Mención o ID del usuario", max_length=80)
        self.add_item(self.user_text)

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.guild or not isinstance(interaction.channel, discord.TextChannel):
            return await interaction.response.send_message("❌ Canal inválido.", ephemeral=True)
        if not _amx242_is_staff(interaction.user):
            return await interaction.response.send_message("⛔ Solo staff puede añadir usuarios.", ephemeral=True)
        raw = str(self.user_text.value)
        m = re.search(r"\d{15,22}", raw)
        if not m:
            return await interaction.response.send_message("❌ No encontré un ID válido.", ephemeral=True)
        member = interaction.guild.get_member(int(m.group(0)))
        if not member:
            try:
                member = await interaction.guild.fetch_member(int(m.group(0)))
            except Exception:
                member = None
        if not member:
            return await interaction.response.send_message("❌ No encontré ese miembro en el servidor.", ephemeral=True)
        await interaction.channel.set_permissions(member, view_channel=True, send_messages=True, attach_files=True, read_message_history=True)
        await interaction.response.send_message(embed=_amx242_embed("➕ Usuario añadido", f"{member.mention} ahora puede ver este ticket.", AMX242_OK, interaction.user))


class AMX242CloseTicketModal(Modal):
    def __init__(self, ticket_id: str):
        super().__init__(title="Cerrar ticket")
        self.ticket_id = ticket_id
        self.motivo = TextInput(label="Motivo de cierre", placeholder="Ej: resuelto, duplicado, sin respuesta...", style=discord.TextStyle.long, max_length=500)
        self.add_item(self.motivo)

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.guild or not isinstance(interaction.channel, discord.TextChannel):
            return await interaction.response.send_message("❌ Canal inválido.", ephemeral=True)
        if not _amx242_is_staff(interaction.user):
            db = _amx242_ticket_db()
            rec = db.get("tickets", {}).get(self.ticket_id) or {}
            if int(rec.get("user_id", 0) or 0) != interaction.user.id:
                return await interaction.response.send_message("⛔ Solo el creador o staff puede cerrar este ticket.", ephemeral=True)
        await interaction.response.send_message(embed=_amx242_embed("🔒 Cerrando ticket", "Generando transcript y cerrando en unos segundos...", AMX242_GOLD, interaction.user))
        db = _amx242_ticket_db()
        rec = db.get("tickets", {}).get(self.ticket_id, {})
        rec["status"] = "closed"
        rec["closed_at"] = time.time()
        rec["closed_by"] = interaction.user.id
        rec["close_reason"] = str(self.motivo.value)
        db["tickets"][self.ticket_id] = rec
        db["stats"]["closed"] = int(db["stats"].get("closed", 0)) + 1
        _amx242_ticket_save(db)
        transcript = await _amx242_make_transcript(interaction.channel)
        logs = await _amx242_get_or_create_logs(interaction.guild)
        log_embed = _amx242_embed("📜 Ticket cerrado", f"Canal: `{interaction.channel.name}`\nCerrado por: {interaction.user.mention}\nMotivo: **{self.motivo.value}**", AMX242_GOLD, interaction.user)
        try:
            await logs.send(embed=log_embed, file=transcript)
        except Exception:
            pass
        try:
            owner_id = int(rec.get("user_id", 0) or 0)
            owner = interaction.guild.get_member(owner_id) or await interaction.guild.fetch_member(owner_id)
            if owner:
                transcript_dm = await _amx242_make_transcript(interaction.channel)
                await owner.send(embed=log_embed, file=transcript_dm)
        except Exception:
            pass
        await asyncio.sleep(5)
        try:
            await interaction.channel.delete(reason=f"Ticket cerrado: {self.motivo.value}")
        except Exception:
            await interaction.followup.send("⚠️ No pude borrar el canal. Revisa permisos del bot.")


class AMX242TicketChannelView(View):
    def __init__(self, ticket_id: str):
        super().__init__(timeout=None)
