def _amx242_parse_bet(datos, uid: str, raw: str):
    cash = int(datos.get(uid, {}).get("cash", 0) or 0)
    if str(raw).lower() in {"all", "todo"}:
        return max(0, cash)
    try:
        return int(str(raw).replace("_", ""))
    except Exception:
        return -1


