@bot.event
async def on_command_error(ctx, error):
    error = getattr(error, "original", error)
    if isinstance(error, commands.CommandOnCooldown):
        return await ctx.send(embed=_amx242_embed("⏳ Cooldown", f"Espera **{error.retry_after:.1f}s** antes de repetir.", AMX242_GOLD, ctx.author))
    if isinstance(error, commands.MissingPermissions):
        return await ctx.send(embed=_amx242_embed("⛔ Sin permisos", "No tienes permisos para usar ese comando.", AMX242_BAD, ctx.author))
    if isinstance(error, commands.MissingRequiredArgument):
        return await ctx.send(embed=_amx242_embed("🧾 Falta un argumento", f"Revisa el uso del comando: `{ctx.prefix}{ctx.command}`", AMX242_CYAN, ctx.author))
    if isinstance(error, commands.CommandNotFound):
        return
    print(f"[AMX242 COMMAND ERROR] {ctx.command}: {error!r}")
    try:
        await ctx.send(embed=_amx242_embed("⚠️ Error controlado", f"```{repr(error)[:1500]}```", AMX242_BAD, ctx.author))
    except Exception:
        pass


