def ensure_pillow_ready():
    """Carga Pillow de forma perezosa y devuelve estado real."""
    global Image, ImageDraw, ImageFont, ImageFilter
    if Image and ImageDraw and ImageFont and ImageFilter:
        try:
            import PIL
            return True, f"Pillow OK {getattr(PIL, '__version__', 'desconocida')}"
        except Exception:
            return True, "Pillow OK"
    try:
        from PIL import Image as _Image, ImageDraw as _ImageDraw, ImageFont as _ImageFont, ImageFilter as _ImageFilter
        Image = _Image
        ImageDraw = _ImageDraw
        ImageFont = _ImageFont
        ImageFilter = _ImageFilter
        import PIL
        return True, f"Pillow OK {getattr(PIL, '__version__', 'desconocida')}"
    except Exception as exc:
        return False, f"Pillow no disponible: {exc!r}"


def font_path_candidates(bold=False, emoji=False):
    paths = []
    if emoji:
        paths.extend([
            "/usr/share/fonts/truetype/noto/NotoColorEmoji.ttf",
            "/usr/share/fonts/google-noto-emoji/NotoColorEmoji.ttf",
            "/usr/share/fonts/truetype/ancient-scripts/Symbola_hint.ttf",
            r"C:\Windows\Fonts\seguiemj.ttf",
        ])
    paths.extend([
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
        r"C:\Windows\Fonts\segoeuib.ttf" if bold else r"C:\Windows\Fonts\segoeui.ttf",
        r"C:\Windows\Fonts\arialbd.ttf" if bold else r"C:\Windows\Fonts\arial.ttf",
    ])
    return paths


def amx_font(size, bold=False, emoji=False):
    ok, _ = ensure_pillow_ready()
    if not ok:
        return None
    for path in font_path_candidates(bold=bold, emoji=emoji):
        try:
            if path and os.path.exists(path):
                return ImageFont.truetype(path, size)
        except Exception:
            continue
    try:
        return ImageFont.load_default()
    except Exception:
        return None


def text_size(draw, text, font):
    try:
        box = draw.textbbox((0, 0), str(text), font=font)
        return box[2] - box[0], box[3] - box[1]
    except Exception:
        return (len(str(text)) * 10, 20)


def draw_text_shadow(draw, pos, text, font, fill, shadow=(0, 0, 0, 170), offset=2):
    x, y = pos
    draw.text((x + offset, y + offset), str(text), font=font, fill=shadow)
    draw.text((x, y), str(text), font=font, fill=fill)


def draw_centered_text(draw, box, text, font, fill, shadow=True):
    x1, y1, x2, y2 = box
    tw, th = text_size(draw, text, font)
    x = x1 + ((x2 - x1) - tw) / 2
    y = y1 + ((y2 - y1) - th) / 2
    if shadow:
        draw_text_shadow(draw, (x, y), text, font, fill)
    else:
        draw.text((x, y), str(text), font=font, fill=fill)


def fit_font(draw, text, max_width, start_size, bold=False, min_size=18):
    size = start_size
    while size >= min_size:
        f = amx_font(size, bold)
        if text_size(draw, text, f)[0] <= max_width:
            return f
        size -= 2
    return amx_font(min_size, bold)


def rounded_mask(size, radius):
    mask = Image.new("L", size, 0)
    ImageDraw.Draw(mask).rounded_rectangle((0, 0, size[0]-1, size[1]-1), radius=radius, fill=255)
    return mask


def linear_gradient(size, colors, diagonal=True):
    w, h = size
    img = Image.new("RGBA", size, (0, 0, 0, 255))
    px = img.load()
    if not colors:
        colors = [(16, 8, 36), (92, 42, 160), (210, 130, 255)]
    if len(colors) == 1:
        colors = [colors[0], colors[0]]
    for y in range(h):
        for x in range(w):
            t = ((x / max(1, w - 1)) * 0.42 + (y / max(1, h - 1)) * 0.58) if diagonal else (y / max(1, h - 1))
            seg = min(len(colors) - 2, int(t * (len(colors) - 1)))
            local = t * (len(colors) - 1) - seg
            c1, c2 = colors[seg], colors[seg + 1]
            px[x, y] = tuple(int(c1[i] * (1 - local) + c2[i] * local) for i in range(3)) + (255,)
    return img


def style_from_item(item_id=None, item=None):
    item = item or {}
    raw = " ".join(str(x or "") for x in [
        item.get("level_style"), item_id, item.get("tipo"), item.get("nombre"), item.get("descripcion"), item.get("categoria")
    ]).lower()
    rules = [
        ("hackergrid", ["hacker", "matrix", "grid"]),
        ("cybercity", ["cybercity", "cyber city", "ciudad", "city"]),
        ("sakura", ["sakura", "cherry", "flor", "rosa night"]),
        ("quantum", ["quantum", "cuant", "core", "nucleo"]),
        ("neon_storm", ["storm", "tormenta", "neon storm", "rayo"]),
        ("supernova", ["supernova", "nova", "solar"]),
        ("aurora", ["aurora"]),
        ("plasma_pink", ["plasma", "pink", "rosa"]),
        ("streamwave", ["stream", "wave", "onda"]),
        ("velvet_void", ["velvet", "void", "vacío", "vacio"]),
        ("void_dragon", ["void dragon", "dragón dorado", "dragon dorado", "dragon void"]),
        ("dragon", ["dragon", "dragón"]),
        ("blue_fire", ["fuego", "fire", "flame"]),
        ("diamond", ["diamond", "diamante", "crystal", "cristal"]),
        ("gold_empire", ["gold", "dorado", "empire", "imperio"]),
        ("emerald", ["emerald", "esmeralda", "green", "verde"]),
        ("ruby", ["ruby", "rubi", "rubí", "red", "rojo"]),
        ("ocean", ["ocean", "mar", "aqua", "water", "oceano", "océano"]),
        ("lunar", ["lunar", "moon", "luna"]),
        ("pixel", ["pixel", "arcade", "retro"]),
        ("circuit", ["circuit", "circuito", "placa", "electro"]),
        ("obsidian", ["obsidian", "obsidiana"]),
        ("galaxy", ["galaxy", "galaxia", "nebula", "nebulosa", "cosmic", "cosmos"]),
        ("neon_purple", ["neon", "morado", "purple", "amatista"]),
    ]
    explicit = str(item.get("level_style", "") or "").lower()
    if explicit:
        for key, words in rules:
            if explicit == key or any(w in explicit for w in words):
                return key
    for key, words in rules:
        if any(w in raw for w in words):
            return key
    return "amethyst"


