def draw_texture(img, style_key, palette, seed=1):
    d = ImageDraw.Draw(img, "RGBA")
    w, h = img.size
    rng = random.Random(seed + sum(ord(c) for c in style_key))
    accent = palette["accent"]
    glow = palette["glow"]
    for _ in range(120):
        x, y = rng.randint(0, w), rng.randint(0, h)
        r = rng.randint(1, 3)
        d.ellipse((x-r, y-r, x+r, y+r), fill=(255, 255, 255, rng.randint(20, 100)))
    if style_key in {"galaxy", "lunar", "supernova"}:
        for _ in range(12):
            x, y = rng.randint(0, w), rng.randint(0, h)
            r = rng.randint(38, 110)
            d.ellipse((x-r, y-r, x+r, y+r), fill=(*glow, rng.randint(16, 34)))
        if style_key == "lunar":
            d.ellipse((1160, 70, 1310, 220), fill=(235, 230, 255, 72), outline=(*accent, 120), width=3)
            d.ellipse((1208, 54, 1350, 210), fill=(10, 8, 35, 115))
        if style_key == "supernova":
            cx, cy = 1180, 170
            for r in range(42, 230, 26):
                d.ellipse((cx-r, cy-r, cx+r, cy+r), outline=(*accent, max(10, 110-r//3)), width=2)
            for a in range(0, 360, 18):
                import math
                x2 = cx + math.cos(math.radians(a)) * 260
                y2 = cy + math.sin(math.radians(a)) * 210
                d.line((cx, cy, x2, y2), fill=(*glow, 55), width=2)
    elif style_key in {"circuit", "hackergrid", "cybercity"}:
        step = 52 if style_key != "hackergrid" else 34
        for x in range(40, w, step):
            d.line((x, 30, x, h-30), fill=(*accent, 34), width=1)
        for y in range(40, h, step):
            d.line((30, y, w-30, y), fill=(*accent, 30), width=1)
        for _ in range(70):
            x = rng.randrange(60, w-60, max(10, step//2)); y = rng.randrange(60, h-60, max(10, step//2))
            d.rectangle((x-3, y-3, x+3, y+3), fill=(*accent, 120))
        if style_key == "cybercity":
            base_y = h - 100
            for x in range(760, w-70, 48):
                bh = rng.randint(50, 150)
                d.rounded_rectangle((x, base_y-bh, x+34, base_y), radius=4, fill=(10, 20, 48, 165), outline=(*accent, 50))
                for wy in range(base_y-bh+12, base_y-10, 22):
                    d.rectangle((x+9, wy, x+14, wy+6), fill=(*accent, 100))
                    d.rectangle((x+21, wy, x+26, wy+6), fill=(*accent, 80))
    elif style_key in {"blue_fire", "ruby", "dragon", "void_dragon"}:
        for i in range(26):
            x = -80 + i * 70
            y = h - rng.randint(72, 170)
            d.pieslice((x, y-110, x+150, y+170), 190, 350, fill=(*glow, 34))
        if "dragon" in style_key:
            for i in range(18):
                x = 730 + i * 42
                y = 80 + (i % 4) * 38
                d.polygon([(x, y), (x+32, y+14), (x+12, y+38)], fill=(*accent, 52), outline=(*glow, 72))
    elif style_key in {"diamond", "gold_empire", "obsidian", "velvet_void"}:
        for _ in range(36):
            x, y = rng.randint(0, w), rng.randint(0, h)
            r = rng.randint(28, 90)
            points = [(x, y-r), (x+r, y), (x, y+r), (x-r, y)]
            d.polygon(points, fill=(*accent, rng.randint(18, 44)), outline=(*glow, rng.randint(36, 90)))
        if style_key == "gold_empire":
            for a in range(-40, 220, 14):
                d.line((w, h, w-900, h-a*4), fill=(*glow, 38), width=3)
    elif style_key in {"pixel"}:
        for x in range(0, w, 36):
            for y in range(0, h, 36):
                if rng.random() < 0.34:
                    d.rectangle((x, y, x+18, y+18), fill=(*accent, rng.randint(28, 72)))
    elif style_key in {"ocean", "streamwave", "aurora"}:
        for i in range(12):
            y = 70 + i * 38
            pts = []
            for x in range(-30, w+60, 24):
                import math
                pts.append((x, y + math.sin((x+i*60)/75) * (20 + i % 3 * 6)))
            d.line(pts, fill=(*accent, 54), width=3)
        if style_key == "streamwave":
            for r in range(50, 260, 38):
                d.arc((980-r, 150-r, 980+r, 150+r), -50, 50, fill=(*accent, 120-r//3), width=4)
    elif style_key in {"emerald", "quantum"}:
        for _ in range(40):
            x1, y1 = rng.randint(40, w-40), rng.randint(40, h-40)
            x2, y2 = x1 + rng.randint(-120, 120), y1 + rng.randint(-90, 90)
            d.line((x1, y1, x2, y2), fill=(*accent, 48), width=2)
            d.ellipse((x1-4, y1-4, x1+4, y1+4), fill=(*accent, 120))
        if style_key == "quantum":
            cx, cy = 1120, 170
            for r in [60, 100, 140]:
                d.ellipse((cx-r*2, cy-r, cx+r*2, cy+r), outline=(*accent, 72), width=3)
    elif style_key in {"sakura", "plasma_pink", "neon_storm"}:
        for _ in range(45):
            x, y = rng.randint(0, w), rng.randint(0, h)
            if style_key == "sakura":
                d.ellipse((x-7, y-4, x+7, y+4), fill=(*accent, 78))
            elif style_key == "neon_storm":
                d.line((x, y, x+rng.randint(-60, 60), y+rng.randint(50, 140)), fill=(*accent, 85), width=3)
            else:
                r = rng.randint(20, 70)
                d.ellipse((x-r, y-r, x+r, y+r), fill=(*glow, 30))
    else:
        for i in range(14):
            x = (i * 151) % w
            y = (i * 83) % h
            r = 70 + (i % 4) * 22
            d.ellipse((x-r, y-r, x+r, y+r), fill=(*glow, 18))
    return img.filter(ImageFilter.GaussianBlur(0.25))


def draw_vector_icon(draw, center, emoji, style_key, palette, size=70):
    cx, cy = center
    accent = palette["accent"]
    glow = palette["glow"]
    r = size // 2
    draw.ellipse((cx-r-8, cy-r-8, cx+r+8, cy+r+8), fill=(*glow, 34))
    draw.ellipse((cx-r, cy-r, cx+r, cy+r), fill=(12, 9, 30, 190), outline=(*accent, 220), width=3)
    e = str(emoji or "")
    key = style_key
    if "💎" in e or key == "diamond":
        pts = [(cx, cy-r+8), (cx+r-8, cy), (cx, cy+r-8), (cx-r+8, cy)]
        draw.polygon(pts, fill=(*accent, 215), outline=(255,255,255,200))
        draw.line((cx-r+8, cy, cx+r-8, cy), fill=(255,255,255,120), width=2)
    elif "🔥" in e or key == "blue_fire":
        draw.pieslice((cx-r+10, cy-r+4, cx+r-8, cy+r+18), 200, 342, fill=(*accent, 220))
        draw.pieslice((cx-r//2, cy-r+12, cx+r//2, cy+r+8), 190, 350, fill=(255,255,255,150))
    elif "🐉" in e or "dragon" in key:
        draw.polygon([(cx-r+10, cy+12), (cx-8, cy-r+8), (cx+8, cy+10), (cx+r-8, cy-r+4), (cx+20, cy+r-10)], fill=(*accent, 210), outline=(255,255,255,110))
        draw.ellipse((cx+14, cy-8, cx+22, cy), fill=(255,255,255,220))
    elif "👾" in e or key == "pixel":
        s = 11
        for ix in range(-2, 3):
            for iy in range(-2, 3):
                if abs(ix) + abs(iy) < 4:
                    draw.rectangle((cx+ix*s, cy+iy*s, cx+ix*s+s-2, cy+iy*s+s-2), fill=(*accent, 210))
    elif "🧬" in e or key in {"circuit", "hackergrid", "quantum"}:
        for i in range(-2, 3):
            x = cx + i * 13
            draw.line((x, cy-r+15, x, cy+r-15), fill=(*accent, 170), width=3)
            draw.ellipse((x-4, cy-4, x+4, cy+4), fill=(255,255,255,180))
    elif "🌌" in e or key == "galaxy":
        for a in range(0, 360, 35):
            import math
            x = cx + math.cos(math.radians(a)) * (r-14)
            y = cy + math.sin(math.radians(a)) * (r-14)
            draw.ellipse((x-3, y-3, x+3, y+3), fill=(255,255,255,220))
        draw.ellipse((cx-14, cy-14, cx+14, cy+14), fill=(*accent, 220))
    elif "🏆" in e or key == "gold_empire":
        draw.rounded_rectangle((cx-24, cy-22, cx+24, cy+12), radius=8, fill=(*accent, 220))
        draw.rectangle((cx-7, cy+10, cx+7, cy+26), fill=(*accent, 220))
        draw.rectangle((cx-25, cy+24, cx+25, cy+32), fill=(*accent, 220))
    elif "🌙" in e or key == "lunar":
        draw.ellipse((cx-24, cy-26, cx+24, cy+26), fill=(*accent, 220))
        draw.ellipse((cx-5, cy-30, cx+35, cy+18), fill=(12,9,30,210))
    elif "🌊" in e or key in {"ocean", "streamwave"}:
        for i in range(3):
            draw.arc((cx-35+i*6, cy-8+i*10, cx+35+i*6, cy+32+i*10), 190, 350, fill=(*accent, 220), width=5)
    else:
        for a in range(0, 360, 60):
            import math
            x1 = cx + math.cos(math.radians(a)) * 12
            y1 = cy + math.sin(math.radians(a)) * 12
            x2 = cx + math.cos(math.radians(a)) * (r-8)
            y2 = cy + math.sin(math.radians(a)) * (r-8)
            draw.line((x1, y1, x2, y2), fill=(*accent, 210), width=4)
        draw.ellipse((cx-13, cy-13, cx+13, cy+13), fill=(255,255,255,215))


def get_equipped_item_clean(info, slot):
    try:
        if "_amx23_get_equipped_item" in globals():
            return _amx23_get_equipped_item(info, slot)
    except Exception:
        pass
    eq = info.get("equipado") if isinstance(info.get("equipado"), dict) else {}
    value = eq.get(slot)
    if not value:
        return None, None
    for item_id, item in TIENDA_ITEMS.items():
        if str(item_id) == str(value) or str(item.get("tipo", item_id)) == str(value):
            return item_id, item
    return str(value), None


def normalize_slot_clean(item_id, item):
    try:
        if "_amx23_slot_for_item" in globals():
            return _amx23_slot_for_item(item_id, item)
    except Exception:
        pass
    slot = str((item or {}).get("slot") or "").lower()
    typ = str((item or {}).get("tipo", item_id) or item_id).lower()
    cat = str((item or {}).get("categoria", "") or "").lower()
    if slot in {"xp_card", "xpcard", "fondo_nivel", "nivel_fondo", "xp_fondo"}:
        return "lvl_fondo"
    if slot in {"xp_marco", "marco_xp", "marco_nivel", "nivel_marco"}:
        return "lvl_marco"
    if slot:
        return slot
    if "xpcard" in typ or "xp_card" in typ or "fondo_lvl" in typ or cat in {"nivel", "xp", "xpcard"}:
        return "lvl_fondo"
    if "marco" in typ and ("lvl" in typ or "xp" in typ or "nivel" in typ):
        return "lvl_marco"
    for token, out in [("titulo", "titulo"), ("mascota", "mascota"), ("placa", "placa"), ("badge", "placa"), ("firma", "firma"), ("aura", "aura")]:
        if token in typ:
            return out
    return None


def find_item_clean(query):
    q = str(query or "").strip().lower()
    if not q:
        return None, None
    if q in TIENDA_ITEMS:
        return q, TIENDA_ITEMS[q]
    for item_id, item in TIENDA_ITEMS.items():
        candidates = {str(item_id).lower(), str(item.get("tipo", "")).lower(), str(item.get("nombre", "")).lower()}
        if q in candidates:
            return item_id, item
    for item_id, item in TIENDA_ITEMS.items():
        haystack = f"{item_id} {item.get('tipo','')} {item.get('nombre','')} {item.get('descripcion','')}".lower()
        if q in haystack:
            return item_id, item
    return None, None


def item_owned_clean(info, item_id, item):
    try:
        if "_amx23_item_owned" in globals():
            return _amx23_item_owned(info, item_id, item)
    except Exception:
        pass
    inv = info.get("items") if isinstance(info.get("items"), dict) else {}
    typ = str((item or {}).get("tipo", item_id))
    return item_id in inv or typ in inv


def xp_needed_clean(level):
    try:
        if "_xp_needed_for_level" in globals():
            return max(100, int(_xp_needed_for_level(level)))
    except Exception:
        pass
    return max(100, 100 + (int(level or 1) - 1) * 50)


async def build_xp_card_file(ctx, miembro, datos, preview_item=None, preview_id=None):
    ok, msg = ensure_pillow_ready()
    if not ok:
        print(f"[XP CARD] {msg}")
        return None
    uid = str(miembro.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    eq = info.get("equipado") if isinstance(info.get("equipado"), dict) else {}
    info["equipado"] = eq
    for old, new in [("xp_card", "lvl_fondo"), ("xpcard", "lvl_fondo"), ("fondo_nivel", "lvl_fondo"), ("xp_fondo", "lvl_fondo"), ("xp_marco", "lvl_marco"), ("marco_xp", "lvl_marco")]:
        if old in eq and new not in eq:
            eq[new] = eq[old]
    lvl = max(1, int(info.get("nivel", 1) or 1))
    xp = max(0, int(info.get("experiencia", 0) or 0))
    needed = xp_needed_clean(lvl)
    pct = max(0.0, min(1.0, xp / max(1, needed)))
    fondo_id, fondo_item = get_equipped_item_clean(info, "lvl_fondo")
    marco_id, marco_item = get_equipped_item_clean(info, "lvl_marco")
    titulo_id, titulo_item = get_equipped_item_clean(info, "titulo")
    mascota_id, mascota_item = get_equipped_item_clean(info, "mascota")
    placa_id, placa_item = get_equipped_item_clean(info, "placa")
    firma_id, firma_item = get_equipped_item_clean(info, "firma")
    if preview_item and normalize_slot_clean(preview_id or "preview", preview_item) == "lvl_fondo":
        fondo_item, fondo_id = preview_item, preview_id or "preview"
    if preview_item and normalize_slot_clean(preview_id or "preview", preview_item) == "lvl_marco":
        marco_item, marco_id = preview_item, preview_id or "preview"
    style_key = style_from_item(fondo_id, fondo_item)
    palette = XP_CARD_STYLES.get(style_key, XP_CARD_STYLES["amethyst"])
    accent, glow = palette["accent"], palette["glow"]
    W, H = XP_CARD_WIDTH, XP_CARD_HEIGHT
    img = linear_gradient((W, H), palette["colors"]).convert("RGBA")
    img = draw_texture(img, style_key, palette, seed=int(miembro.id))
    glow_layer = Image.new("RGBA", (W, H), (0,0,0,0))
    gd = ImageDraw.Draw(glow_layer, "RGBA")
    gd.rounded_rectangle((22, 22, W-22, H-22), radius=42, fill=(*glow, 45), outline=(*accent, 165), width=4)
    img = Image.alpha_composite(img, glow_layer.filter(ImageFilter.GaussianBlur(4)))
    draw = ImageDraw.Draw(img, "RGBA")
    draw.rounded_rectangle((34, 34, W-34, H-34), radius=38, fill=(7, 8, 24, 138), outline=(*accent, 185), width=3)
    draw.rounded_rectangle((56, 56, W-56, H-56), radius=28, outline=(255,255,255,42), width=1)
    if marco_item:
        mk = style_from_item(marco_id, marco_item)
        mp = XP_CARD_STYLES.get(mk, palette)
        draw.rounded_rectangle((18, 18, W-18, H-18), radius=48, outline=(*mp["accent"], 245), width=7)
        draw.rounded_rectangle((28, 28, W-28, H-28), radius=43, outline=(*mp["glow"], 120), width=2)

    # Avatar perfectamente centrado en su módulo.
    av_size = 230
    av_x, av_y = 92, 118
    try:
        raw = await miembro.display_avatar.replace(size=512, static_format="png").read()
        avatar = Image.open(io.BytesIO(raw)).convert("RGBA")
        try:
            resample = Image.Resampling.LANCZOS
        except Exception:
            resample = Image.LANCZOS
        avatar = avatar.resize((av_size, av_size), resample)
    except Exception:
        avatar = Image.new("RGBA", (av_size, av_size), (*accent, 255))
        ad = ImageDraw.Draw(avatar)
        initial = (miembro.display_name[:1] or "?").upper()
        draw_centered_text(ad, (0, 0, av_size, av_size), initial, amx_font(90, True), (20,20,35,255), shadow=False)
    mask = Image.new("L", (av_size, av_size), 0)
    ImageDraw.Draw(mask).ellipse((0,0,av_size-1,av_size-1), fill=255)
    shadow = Image.new("RGBA", (av_size+42, av_size+42), (0,0,0,0))
    sd = ImageDraw.Draw(shadow, "RGBA")
    sd.ellipse((14,14,av_size+28,av_size+28), fill=(0,0,0,150))
    shadow = shadow.filter(ImageFilter.GaussianBlur(10))
    img.alpha_composite(shadow, (av_x-21, av_y-15))
    img.paste(avatar, (av_x, av_y), mask)
    for i, alpha in enumerate([240, 150, 75]):
        draw.ellipse((av_x-10-i*5, av_y-10-i*5, av_x+av_size+10+i*5, av_y+av_size+10+i*5), outline=(*accent, alpha), width=4)

    # Icono de estilo vectorial, sin depender de fuentes emoji.
    card_emoji = (fondo_item or {}).get("emoji", "💜")
    draw_vector_icon(draw, (296, 132), card_emoji, style_key, palette, size=76)

    font_name = fit_font(draw, miembro.display_name, 760, 58, True, 30)
    font_big = amx_font(48, True)
    font_mid = amx_font(26, True)
    font_small = amx_font(21, False)
    font_tiny = amx_font(17, False)
    name = miembro.display_name[:32]
    draw_text_shadow(draw, (390, 92), name, font_name, (255,255,255,255))
    subtitle = (titulo_item or {}).get("nombre") or "XP Card personalizada"
    draw.text((394, 158), subtitle[:52], font=font_small, fill=(*accent, 242))

    # Level capsule.
    draw.rounded_rectangle((1185, 78, 1418, 168), radius=28, fill=(255,255,255,24), outline=(*accent, 105), width=2)
    draw_centered_text(draw, (1185, 82, 1418, 112), "LEVEL", amx_font(17, True), (235,235,255,210), shadow=False)
    draw_centered_text(draw, (1185, 106, 1418, 170), str(lvl), font_big, (255,255,255,255), shadow=True)

    # XP bar aligned.
    bx, by, bw, bh = 390, 220, 980, 46
    draw.text((bx, by-36), f"Experiencia  {xp:,} / {needed:,} XP", font=font_small, fill=(242,240,255,238))
    draw.text((bx+bw-152, by-34), f"{int(pct*100)}%", font=font_mid, fill=(*accent, 255))
    bar_shadow = Image.new("RGBA", (W, H), (0,0,0,0))
    bsd = ImageDraw.Draw(bar_shadow, "RGBA")
    fill_w = int(bw * pct)
    if fill_w > 0:
        bsd.rounded_rectangle((bx, by, bx+fill_w, by+bh), radius=23, fill=(*glow, 180))
    img.alpha_composite(bar_shadow.filter(ImageFilter.GaussianBlur(9)))
    draw.rounded_rectangle((bx, by, bx+bw, by+bh), radius=23, fill=(255,255,255,22), outline=(255,255,255,48), width=1)
    if fill_w > 0:
        draw.rounded_rectangle((bx, by, bx+fill_w, by+bh), radius=23, fill=(*accent, 235))
    draw_centered_text(draw, (bx, by, bx+bw, by+bh), f"Faltan {max(0, needed-xp):,} XP", amx_font(20, True), (255,255,255,235), shadow=True)

    # Stats grid aligned.
    stats = [
        ("Cash", f"{int(info.get('cash', 0) or 0):,}"),
        ("Banco", f"{int(info.get('bank', 0) or 0):,}"),
        ("Rep", f"{int(info.get('reputacion', 0) or 0):,}"),
        ("Rango RL", str(info.get("rango_rl", "Sin rango"))[:18]),
    ]
    sx, sy, sw, sh, gap = 390, 312, 222, 78, 20
    for i, (label, value) in enumerate(stats):
        x1 = sx + i * (sw + gap)
        draw.rounded_rectangle((x1, sy, x1+sw, sy+sh), radius=20, fill=(255,255,255,20), outline=(255,255,255,34), width=1)
        draw.text((x1+16, sy+13), label, font=font_tiny, fill=(235,232,255,205))
        draw.text((x1+16, sy+38), value, font=font_small, fill=(255,255,255,255))

    # Cosmetic chips with vector icons.
    chip_items = [
        ("Card", fondo_item, fondo_id, style_key),
        ("Marco", marco_item, marco_id, style_from_item(marco_id, marco_item) if marco_item else style_key),
        ("Mascota", mascota_item, mascota_id, style_key),
        ("Placa", placa_item, placa_id, style_key),
        ("Firma", firma_item, firma_id, style_key),
    ]
    chip_x, chip_y = 390, 428
    for label, item, iid, sk in chip_items[:4]:
        if not item and label not in {"Card", "Marco"}:
            continue
        title = (item or {}).get("nombre") or ("Default" if label == "Card" else "Ninguno")
        w_box = 250 if label in {"Card", "Marco"} else 220
        draw.rounded_rectangle((chip_x, chip_y, chip_x+w_box, chip_y+52), radius=17, fill=(255,255,255,18), outline=(255,255,255,26), width=1)
        draw_vector_icon(draw, (chip_x+29, chip_y+26), (item or {}).get("emoji", "💜"), sk, palette, size=34)
        draw.text((chip_x+58, chip_y+8), label, font=font_tiny, fill=(235,232,255,185))
        draw.text((chip_x+58, chip_y+28), title[:18], font=font_tiny, fill=(255,255,255,225))
        chip_x += w_box + 14

    card_name = (fondo_item or {}).get("nombre") or "Default Aether"
    draw.text((104, 390), "XP CARD", font=amx_font(22, True), fill=(255,255,255,235))
    draw.text((104, 420), card_name[:24], font=font_small, fill=(*accent, 245))
    draw.text((W-322, H-42), "X AETHER ULTRA XP CARD", font=font_tiny, fill=(255,255,255,155))
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    buf.seek(0)
    return discord.File(buf, filename=f"xau_public_xpcard_{miembro.id}.png")


def xp_fallback_embed(member, info, diagnostic="Imagen no generada"):
    lvl = max(1, int(info.get("nivel", 1) or 1))
    xp = max(0, int(info.get("experiencia", 0) or 0))
    need = xp_needed_clean(lvl)
    embed = discord.Embed(title=f"XP Card · {member.display_name}", color=discord.Color.purple())
    embed.description = f"Nivel **{lvl}** · XP **{xp:,}/{need:,}**\n`{diagnostic[:900]}`"
    embed.set_thumbnail(url=member.display_avatar.url)
    return embed


