class XPCardsGalleryView(discord.ui.View):
    def __init__(self, owner_id, entries, info, page=0):
        super().__init__(timeout=180)
        self.owner_id = int(owner_id)
        self.entries = entries
        self.info = info
        self.page = max(0, int(page or 0))
        self.per_page = 6
        self.max_page = max(0, (len(entries) - 1) // self.per_page)
        self.update_buttons()

    def update_buttons(self):
        for child in self.children:
            if getattr(child, "custom_id", "") == "xp_prev":
                child.disabled = self.page <= 0
            if getattr(child, "custom_id", "") == "xp_next":
                child.disabled = self.page >= self.max_page
            if getattr(child, "custom_id", "") == "xp_page":
                child.label = f"{self.page+1}/{self.max_page+1}"

    def build_embed(self, user):
        embed = discord.Embed(title="Galería XP Cards", color=discord.Color.purple())
        embed.description = "Cards y marcos con estado real. Usa `!previewxp <id>` para ver la textura antes de comprar."
        start = self.page * self.per_page
        shown = self.entries[start:start+self.per_page]
        for item_id, item in shown:
            owned = item_owned_clean(self.info, item_id, item)
            slot = normalize_slot_clean(item_id, item)
            style = style_from_item(item_id, item)
            level = int(item.get("nivel_min", 1) or 1)
            state = "comprado" if owned else f"nivel {level}" if level > max(1, int(self.info.get("nivel", 1) or 1)) else "disponible"
            marker = "✅" if owned else "🔒" if state.startswith("nivel") else "🟣"
            embed.add_field(
                name=f"{marker} {item.get('nombre', item_id)}",
                value=f"ID: `{item_id}` · slot `{slot}` · textura `{style}`\nPrecio: **{int(item.get('precio', 0) or 0):,}** {amatista} · Estado: **{state}**",
                inline=False,
            )
        embed.set_footer(text=f"Página {self.page+1}/{self.max_page+1} · {len(self.entries)} cosméticos XP")
        return embed

    async def interaction_check(self, interaction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel es de otra persona.", ephemeral=True)
            return False
        return True

    @discord.ui.button(emoji="⬅️", style=discord.ButtonStyle.secondary, custom_id="xp_prev")
    async def previous_page(self, interaction, button):
        self.page = max(0, self.page - 1)
        self.update_buttons()
        await interaction.response.edit_message(embed=self.build_embed(interaction.user), view=self)

    @discord.ui.button(label="1/1", style=discord.ButtonStyle.primary, disabled=True, custom_id="xp_page")
    async def page_indicator(self, interaction, button):
        pass

    @discord.ui.button(emoji="➡️", style=discord.ButtonStyle.secondary, custom_id="xp_next")
    async def next_page(self, interaction, button):
        self.page = min(self.max_page, self.page + 1)
        self.update_buttons()
        await interaction.response.edit_message(embed=self.build_embed(interaction.user), view=self)

    @discord.ui.button(emoji="🗑️", style=discord.ButtonStyle.danger, custom_id="xp_close")
    async def close_panel(self, interaction, button):
        await interaction.response.edit_message(view=None)


@bot.command(name="xpcards", aliases=["fondosnivel", "levelcards", "tarjetasnivel", "estilosxp"])
@commands.cooldown(1, 6, commands.BucketType.user)
async def command_xpcards(ctx, filtro: str = "todo", pagina: int = 1):
    datos = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    entries = [(k, v) for k, v in TIENDA_ITEMS.items() if normalize_slot_clean(k, v) in {"lvl_fondo", "lvl_marco"}]
    filtro = str(filtro or "todo").lower()
    if filtro in {"comprado", "comprados", "mios", "owned"}:
        entries = [(k, v) for k, v in entries if item_owned_clean(info, k, v)]
    elif filtro in {"bloqueado", "bloqueados", "locked"}:
        entries = [(k, v) for k, v in entries if not item_owned_clean(info, k, v)]
    entries.sort(key=lambda kv: (normalize_slot_clean(kv[0], kv[1]) or "", int(kv[1].get("nivel_min", 1) or 1), int(kv[1].get("precio", 0) or 0), kv[0]))
    view = XPCardsGalleryView(ctx.author.id, entries, info, max(0, int(pagina or 1)-1))
    await ctx.send(embed=view.build_embed(ctx.author), view=view)


@bot.command(name="equipar", aliases=["equip"])
@commands.cooldown(1, 4, commands.BucketType.user)
async def command_equipar(ctx, *, item_query: str = None):
    if not item_query:
        return await ctx.send(embed=discord.Embed(title="Equipar cosmético", description="Uso: `!equipar <id>`\nEjemplo: `!equipar fondo_lvl_galaxia`", color=discord.Color.purple()))
    item_id, item = find_item_clean(item_query)
    if not item:
        return await ctx.send(embed=discord.Embed(title="No encontrado", description="No encontré ese item. Usa `!xpcards` o `!buscaritem <texto>`.", color=discord.Color.red()))
    slot = normalize_slot_clean(item_id, item)
    if not slot:
        return await ctx.send(embed=discord.Embed(title="No equipable", description=f"**{item.get('nombre', item_id)}** no es cosmético equipable.", color=discord.Color.red()))
    datos = cargar_datos()
    uid = str(ctx.author.id)
    asegurar_usuario(datos, uid)
    info = datos[uid]
    if not item_owned_clean(info, item_id, item):
        return await ctx.send(embed=discord.Embed(title="No comprado", description=f"Compra primero con `!comprar {item_id}`. Puedes probarlo con `!previewxp {item_id}` si es XP Card.", color=discord.Color.orange()))
    eq = info.setdefault("equipado", {})
    eq[slot] = item_id
    # Limpieza de aliases antiguos para que no gane una key vieja.
    for old in ["xp_card", "xpcard", "fondo_nivel", "nivel_fondo", "xp_fondo"]:
        if slot == "lvl_fondo":
            eq.pop(old, None)
    for old in ["xp_marco", "marco_xp", "marco_nivel", "nivel_marco"]:
        if slot == "lvl_marco":
            eq.pop(old, None)
    guardar_datos(datos)
    embed = discord.Embed(title="Cosmético equipado", color=discord.Color.green())
    embed.description = f"**{item.get('nombre', item_id)}**\nSlot: `{slot}`\nID: `{item_id}`"
    if slot in {"lvl_fondo", "lvl_marco"}:
        embed.add_field(name="XP Card", value="Comprueba el resultado con `!lvl` o `!previewxp`.", inline=False)
    await ctx.send(embed=embed)


# Bienvenida y despedida limpias, alineadas y sin depender de emojis de fuente.
def welcome_palette(kind):
    if str(kind).lower().startswith("fare"):
        return {"colors": [(8, 5, 20), (54, 28, 92), (112, 72, 180)], "accent": (196, 150, 255), "glow": (115, 70, 210)}
    return {"colors": [(10, 6, 32), (88, 32, 145), (215, 122, 255)], "accent": (225, 165, 255), "glow": (178, 80, 255)}


async def build_welcome_card_file(member, kind="welcome"):
    ok, msg = ensure_pillow_ready()
    if not ok:
        print(f"[WELCOME CARD] {msg}")
        return None
    kind = "farewell" if str(kind).lower().startswith("fare") else "welcome"
    pal = welcome_palette(kind)
    W, H = WELCOME_CARD_WIDTH, WELCOME_CARD_HEIGHT
    img = linear_gradient((W, H), pal["colors"]).convert("RGBA")
    draw_texture(img, "galaxy" if kind == "welcome" else "velvet_void", pal, seed=int(member.id))
    draw = ImageDraw.Draw(img, "RGBA")
    accent, glow = pal["accent"], pal["glow"]
    draw.rounded_rectangle((28, 28, W-28, H-28), radius=44, fill=(8, 6, 24, 142), outline=(*accent, 210), width=4)
    draw.rounded_rectangle((52, 52, W-52, H-52), radius=32, outline=(255,255,255,38), width=1)
    # Avatar block.
    av_size = 236
    av_x, av_y = 96, 132
    try:
        raw = await member.display_avatar.replace(size=512, static_format="png").read()
        avatar = Image.open(io.BytesIO(raw)).convert("RGBA")
        try:
            resample = Image.Resampling.LANCZOS
        except Exception:
            resample = Image.LANCZOS
        avatar = avatar.resize((av_size, av_size), resample)
    except Exception:
        avatar = Image.new("RGBA", (av_size, av_size), (*accent, 255))
        ad = ImageDraw.Draw(avatar)
        draw_centered_text(ad, (0, 0, av_size, av_size), (member.display_name[:1] or "?").upper(), amx_font(92, True), (20,20,35,255), shadow=False)
    mask = Image.new("L", (av_size, av_size), 0)
    ImageDraw.Draw(mask).ellipse((0,0,av_size-1,av_size-1), fill=255)
    glow_img = Image.new("RGBA", (av_size+60, av_size+60), (0,0,0,0))
    gd = ImageDraw.Draw(glow_img, "RGBA")
    gd.ellipse((18,18,av_size+42,av_size+42), fill=(*glow, 45), outline=(*accent, 230), width=11)
    img.alpha_composite(glow_img.filter(ImageFilter.GaussianBlur(5)), (av_x-30, av_y-24))
    img.paste(avatar, (av_x, av_y), mask)
    draw.ellipse((av_x-10, av_y-10, av_x+av_size+10, av_y+av_size+10), outline=(255,245,255,230), width=5)
    draw_vector_icon(draw, (330, 142), "🌌" if kind == "welcome" else "🌙", "galaxy" if kind == "welcome" else "lunar", pal, size=66)
    # Text block aligned.
    title = "BIENVENIDO" if kind == "welcome" else "HASTA LUEGO"
    subtitle = "Nos alegra tenerte aquí" if kind == "welcome" else "Esperamos verte de nuevo"
    title_font = amx_font(74, True)
    sub_font = amx_font(31, False)
    name_font = fit_font(draw, member.display_name, 850, 48, True, 28)
    x0 = 410
    draw_text_shadow(draw, (x0, 92), title, title_font, (255,255,255,255), shadow=(0,0,0,190), offset=3)
    draw.text((x0+4, 178), subtitle, font=sub_font, fill=(238, 225, 255, 235))
    draw.rounded_rectangle((x0, 236, W-104, 324), radius=24, fill=(255,255,255,22), outline=(*accent, 95), width=2)
    draw_text_shadow(draw, (x0+28, 252), member.display_name[:36], name_font, (*accent, 255))
    server = getattr(member.guild, "name", "Servidor")[:42]
    count = getattr(member.guild, "member_count", 0) or 0
    label = f"{server} · Miembro #{count}"
    draw.rounded_rectangle((x0, 352, W-104, 408), radius=18, fill=(255,255,255,16), outline=(255,255,255,28), width=1)
    draw.text((x0+24, 368), label, font=amx_font(24, True), fill=(255,255,255,230))
    draw.text((W-355, H-46), "X AETHER ULTRA ROYAL CARD", font=amx_font(17, True), fill=(255,255,255,150))
    buf = io.BytesIO()
    filename = "xau_public_welcome.png" if kind == "welcome" else "xau_public_farewell.png"
    img.save(buf, format="PNG")
    buf.seek(0)
    return discord.File(buf, filename=filename)


def get_welcome_channel(guild, key, default_id=None):
    try:
        cfg = _amx_welcome_load_config() if "_amx_welcome_load_config" in globals() else {}
        gid = str(guild.id)
        channel_id = cfg.get(gid, {}).get(key) or default_id
        return guild.get_channel(int(channel_id)) if channel_id else None
    except Exception:
        return None


@bot.event
async def on_member_join(member):
    if member.bot:
        return
    try:
        role = member.guild.get_role(int(ROL_OBLIGATORIO_ID)) if ROL_OBLIGATORIO_ID else None
        if role and member.guild.me and role < member.guild.me.top_role:
            await member.add_roles(role, reason="Rol automático de entrada")
    except Exception as exc:
        print(f"[WELCOME] Rol automático no asignado: {exc!r}")
    channel = get_welcome_channel(member.guild, "bienvenida", CANAL_BIENVENIDAS_ID)
    if not channel:
        return
    try:
        file = await build_welcome_card_file(member, "welcome")
        if file:
            await channel.send(content=member.mention, file=file)
        else:
            embed = discord.Embed(title="Nuevo miembro", description=f"Bienvenido/a {member.mention}.", color=discord.Color.purple())
            await channel.send(content=member.mention, embed=embed)
    except Exception as exc:
        print(f"[WELCOME] Error enviando bienvenida: {exc!r}")


@bot.event
async def on_member_remove(member):
    if member.bot:
        return
    channel = get_welcome_channel(member.guild, "despedida", CANAL_BIENVENIDAS_ID)
    if not channel:
        return
    try:
        file = await build_welcome_card_file(member, "farewell")
        if file:
            await channel.send(file=file)
        else:
            embed = discord.Embed(title="Un miembro se ha ido", description=f"{member.display_name} salió del servidor.", color=discord.Color.dark_purple())
            await channel.send(embed=embed)
    except Exception as exc:
        print(f"[WELCOME] Error enviando despedida: {exc!r}")


