def _xaether_now_iso() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def _xaether_safe_text(value: Any, limit: int = 500) -> str:
    text = str(value or "").replace("\x00", " ").strip()
    text = re.sub(r"\s+", " ", text)
    return text[:limit]


def _xaether_hash(text: str) -> str:
    return hashlib.sha256(str(text or "").encode("utf-8", "ignore")).hexdigest()[:16]


def _xaether_atomic_write_json_sync(path: str, data: dict):
    """X AETHER ULTRA PATCH: escritura atómica para evitar JSON corruptos si el host corta el proceso."""
    try:
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=".xaether_", suffix=".json", dir=os.path.dirname(os.path.abspath(path)) or ".")
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
    except Exception as exc:
        print(f"[X AETHER JSON] Error guardando {path}: {exc!r}")


def _xaether_load_json_sync(path: str, default: dict | None = None) -> dict:
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data if isinstance(data, dict) else (default or {})
    except Exception as exc:
        print(f"[X AETHER JSON] Error cargando {path}: {exc!r}")
    return default or {}


async def xaether_load_json_async(path: str, default: dict | None = None) -> dict:
    """X AETHER ULTRA PATCH: lectura JSON protegida por asyncio.Lock y movida a thread."""
    async with _xaether_file_locks[path]:
        return await asyncio.to_thread(_xaether_load_json_sync, path, default or {})


async def xaether_save_json_async(path: str, data: dict):
    """X AETHER ULTRA PATCH: guardado JSON protegido por asyncio.Lock y escritura atómica."""
    async with _xaether_file_locks[path]:
        await asyncio.to_thread(_xaether_atomic_write_json_sync, path, data)


def cargar_ouroboros() -> dict:
    """X AETHER ULTRA PATCH: carga Ouroboros con migración compatible y nuevos metadatos evolutivos."""
    estado = _xaether_load_json_sync(OUROBOROS_FILE, {})
    if not isinstance(estado, dict):
        estado = {}
    estado.setdefault("version", "3.1.0")
    estado.setdefault("ciclos_evolucion", 0)
    estado.setdefault("ultima_reflexion", None)
    estado.setdefault("rasgos_activos", list(XAETHER_RASGOS_BASE))
    estado.setdefault("rasgos_puntuacion", {r: (3 if r in XAETHER_RASGOS_BASE else 0) for r in XAETHER_RASGOS_POSIBLES})
    estado.setdefault("reflexiones", [])
    estado.setdefault("aprendizajes", [])
    estado.setdefault("aprendizajes_negativos", [])
    estado.setdefault("patrones", {})
    estado.setdefault("provider_metrics", {})
    estado.setdefault("feedback", {"positivo": 0, "negativo": 0, "eventos": []})
    estado.setdefault("mejoras_internas", [])
    estado.setdefault("estadisticas", {})
    est = estado["estadisticas"]
    est.setdefault("mensajes_procesados", 0)
    est.setdefault("usuarios_recordados", 0)
    est.setdefault("warns_emitidos", 0)
    est.setdefault("kicks_emitidos", 0)
    est.setdefault("conversaciones_totales", 0)
    est.setdefault("timeouts_ia", 0)
    est.setdefault("errores_ia", 0)
    est.setdefault("reflexiones_completadas", len(estado.get("reflexiones", [])))
    return estado


def guardar_ouroboros(estado: dict):
    """X AETHER ULTRA PATCH: guardado atómico del estado Ouroboros."""
