def _xaether_append_evolution_log(entry: dict):
    log = _xaether_load_json_sync(XAETHER_EVOLUTION_LOG_FILE, {"eventos": []})
    log.setdefault("eventos", [])
    entry.setdefault("timestamp", _xaether_now_iso())
    log["eventos"].append(entry)
    log["eventos"] = log["eventos"][-200:]
    _xaether_atomic_write_json_sync(XAETHER_EVOLUTION_LOG_FILE, log)


def _xaether_update_traits(estado: dict, signals: dict | None = None):
    """X AETHER ULTRA PATCH: rasgos evolutivos que suben/bajan según señales reales."""
    signals = signals or {}
    scores = estado.setdefault("rasgos_puntuacion", {r: 0 for r in XAETHER_RASGOS_POSIBLES})
    for rasgo in XAETHER_RASGOS_POSIBLES:
        scores.setdefault(rasgo, 0)
    text = str(signals.get("text", "")).lower()
    latency = float(signals.get("latency", 0) or 0)
    feedback = signals.get("feedback")

    if len(text) > 900:
        scores["detallado"] += 1
        scores["exhaustivo"] += 1
        scores["conciso"] -= 1
    elif 0 < len(text) < 240:
        scores["conciso"] += 1
        scores["directo"] += 1
    if any(w in text for w in ["lo siento", "entiendo", "tranquilo", "te ayudo", "sin problema"]):
        scores["empático"] += 1
    if any(w in text for w in ["paso", "estructura", "permiso", "valid", "error", "log"]):
        scores["lógico"] += 1
        scores["analítico"] += 1
    if any(w in text for w in ["idea", "diseño", "estilo", "crea", "visual"]):
        scores["creativo"] += 1
    if latency > 12:
        scores["conciso"] += 1
    if feedback == "positivo":
        scores["tolerante"] += 1
        scores["empático"] += 1
    if feedback == "negativo":
        scores["detallado"] += 1
        scores["analítico"] += 1
        scores["sarcástico"] -= 2

    for rasgo in scores:
        scores[rasgo] = max(-8, min(20, int(scores.get(rasgo, 0))))
    ranked = sorted(XAETHER_RASGOS_POSIBLES, key=lambda r: (scores.get(r, 0), r), reverse=True)
    activos = []
    for base in XAETHER_RASGOS_BASE:
        if base not in activos:
            activos.append(base)
    for rasgo in ranked:
        if scores.get(rasgo, 0) >= 3 and rasgo not in activos:
            activos.append(rasgo)
        if len(activos) >= 7:
            break
    estado["rasgos_activos"] = activos


def ouroboros_tick(evento: str, datos: dict = None):
    """X AETHER ULTRA PATCH: tick con métricas, patrones y señales para evolución dinámica."""
    datos = datos or {}
    estado = cargar_ouroboros()
    est = estado.setdefault("estadisticas", {})
    est["mensajes_procesados"] = int(est.get("mensajes_procesados", 0)) + 1
    if evento == "warn":
        est["warns_emitidos"] = int(est.get("warns_emitidos", 0)) + 1
    elif evento == "kick":
        est["kicks_emitidos"] = int(est.get("kicks_emitidos", 0)) + 1
    elif evento == "conversacion":
        est["conversaciones_totales"] = int(est.get("conversaciones_totales", 0)) + 1
    elif evento == "timeout_ia":
        est["timeouts_ia"] = int(est.get("timeouts_ia", 0)) + 1
    elif evento == "error_ia":
        est["errores_ia"] = int(est.get("errores_ia", 0)) + 1

    tema = _xaether_safe_text(datos.get("tema", ""), 60).lower()
    if tema:
        patrones = estado.setdefault("patrones", {})
        item = patrones.setdefault(tema, {"conteo": 0, "ultimo": None})
        item["conteo"] = int(item.get("conteo", 0)) + 1
        item["ultimo"] = _xaether_now_iso()
    guardar_ouroboros(estado)


def _xaether_record_provider_metric(provider: str, model: str, latency: float, ok: bool, error: str = "", quality: int | None = None):
    estado = cargar_ouroboros()
    metrics = estado.setdefault("provider_metrics", {})
    key = f"{provider}:{model}"
    item = metrics.setdefault(key, {"provider": provider, "model": model, "calls": 0, "ok": 0, "errors": 0, "latencies": [], "quality": []})
    item["calls"] = int(item.get("calls", 0)) + 1
    if ok:
        item["ok"] = int(item.get("ok", 0)) + 1
    else:
        item["errors"] = int(item.get("errors", 0)) + 1
        item["last_error"] = _xaether_safe_text(error, 220)
    item.setdefault("latencies", []).append(round(float(latency or 0), 3))
    item["latencies"] = item["latencies"][-XAETHER_PROVIDER_METRICS_LIMIT:]
    if quality is not None:
        item.setdefault("quality", []).append(int(quality))
        item["quality"] = item["quality"][-XAETHER_PROVIDER_METRICS_LIMIT:]
    item["last"] = _xaether_now_iso()
    _xaether_update_traits(estado, {"latency": latency})
    guardar_ouroboros(estado)


def _xaether_detect_topic(text: str) -> str:
    low = str(text or "").lower()
    topics = {
        "tienda": ["tienda", "comprar", "item", "inventario", "usar", "amatista"],
        "economia": ["cash", "banco", "daily", "trabajar", "robar", "donar", "misiones"],
        "minijuegos": ["blackjack", "poker", "ruleta", "slots", "casino", "apostar", "dado"],
        "tickets": ["ticket", "soporte", "cerrar", "ayuda"],
        "rocket_league": ["rocket", "rl", "rango", "flip reset", "musty", "freestyle"],
        "codigo_bot": ["error", "python", "discord.py", "comando", "traceback", "pylint"],
        "moderacion": ["warn", "kick", "ban", "spam", "insulto", "moderar"],
    }
    for topic, words in topics.items():
        if any(w in low for w in words):
            return topic
    return "general"


def _xaether_offline_answer(user_message: str, username: str = "") -> str:
    topic = _xaether_detect_topic(user_message)
    if topic == "tienda":
        return "⚙️ Estoy en modo offline, pero para la tienda revisa `!tienda`, compra con `!comprar <id>` y usa consumibles con `!usar <item>`. Si falta cash, tira de `!daily` y `!trabajar` antes de apostar."
    if topic == "codigo_bot":
        return "⚙️ Modo offline activo. Para depurar X AETHER ULTRA: mira el traceback exacto, comprueba comandos duplicados, permisos de intents, variables `.env` y que los JSON no estén corruptos."
    if topic == "moderacion":
        return "⚙️ Modo offline activo. En moderación, verifica jerarquía de roles, permisos `kick_members/ban_members/manage_messages` y nunca apliques acciones automáticas sobre Markelson."
    return random.choice(XAETHER_OFFLINE_RESPONSES)


def cargar_memoria_aether() -> dict:
    """X AETHER ULTRA PATCH: memoria compatible con recuerdos clásicos + metadatos de relevancia."""
    memoria = _xaether_load_json_sync(MEMORIA_FILE, {})
    if not isinstance(memoria, dict):
        memoria = {}
    memoria.setdefault("_meta", {})
    memoria["_meta"].setdefault("creado", _xaether_now_iso())
    memoria["_meta"]["version"] = "3.1.0"
    memoria.setdefault("_channels", {})
    return memoria


def guardar_memoria_aether(memoria: dict):
    """X AETHER ULTRA PATCH: guardado atómico compatible."""
    try:
        if isinstance(memoria, dict):
            memoria.setdefault("_meta", {})["version"] = "3.1.0"
        _xaether_atomic_write_json_sync(MEMORIA_FILE, memoria if isinstance(memoria, dict) else {})
    except Exception as exc:
        print(f"[AETHER MEM] Error guardando memoria: {exc!r}")


def _xaether_memory_importance(text: str) -> int:
    low = str(text or "").lower()
    score = 3
    if any(w in low for w in ["prefiere", "quiere", "proyecto", "bot", "aether", "discord", "rocket", "estudia", "canal", "servidor"]):
        score += 3
    if any(w in low for w in ["siempre", "nunca", "importante", "obligatorio", "recuerda", "from now", "a partir"]):
        score += 4
    if any(w in low for w in ["token", "contraseña", "password", "api_key", "secret", "cookie"]):
        score -= 99
    if len(low) > 180:
        score -= 1
    return max(0, min(10, score))


def _xaether_normalize_user_memory(memoria: dict, user_id: int) -> dict:
    uid = str(user_id)
    raw = memoria.setdefault(uid, {})
    if not isinstance(raw, dict):
        raw = memoria[uid] = {"recuerdos": []}
    raw.setdefault("username", "")
    raw.setdefault("recuerdos", [])
    raw.setdefault("recuerdos_meta", [])
    raw.setdefault("resumen_antiguo", "")

    meta_by_hash = {m.get("hash"): m for m in raw.get("recuerdos_meta", []) if isinstance(m, dict) and m.get("hash")}
    clean = []
    seen = set()
    for rec in raw.get("recuerdos", []) or []:
        text = _xaether_safe_text(rec, 260).lstrip("-•· ").strip()
        if not text or _xaether_memory_importance(text) <= 0:
            continue
        key = _xaether_hash(text.lower())
        if key in seen:
            continue
        seen.add(key)
        clean.append(text)
        if key not in meta_by_hash:
            meta_by_hash[key] = {"hash": key, "text": text, "relevance": _xaether_memory_importance(text), "created_at": _xaether_now_iso(), "last_used": None, "uses": 0}
        else:
            meta_by_hash[key]["text"] = text
            meta_by_hash[key].setdefault("relevance", _xaether_memory_importance(text))
            meta_by_hash[key].setdefault("created_at", _xaether_now_iso())
            meta_by_hash[key].setdefault("uses", 0)
    raw["recuerdos"] = clean
    raw["recuerdos_meta"] = list(meta_by_hash.values())
    return raw


def _xaether_compact_memory(raw: dict):
    """X AETHER ULTRA PATCH: mantiene 200 recuerdos, fusionando los antiguos menos relevantes en resumen."""
    recuerdos = list(raw.get("recuerdos", []) or [])
    metas = {m.get("hash"): m for m in raw.get("recuerdos_meta", []) if isinstance(m, dict)}
    if len(recuerdos) <= XAETHER_MEMORY_MAX:
        return
    ranked = sorted(recuerdos, key=lambda r: (metas.get(_xaether_hash(str(r).lower()), {}).get("relevance", _xaether_memory_importance(r)), recuerdos.index(r)), reverse=True)
    keep = ranked[:XAETHER_MEMORY_MAX]
    forgotten = [r for r in recuerdos if r not in keep]
    if forgotten:
        resumen = raw.get("resumen_antiguo", "")
        mini = "; ".join(_xaether_safe_text(x, 90) for x in forgotten[:20])
        raw["resumen_antiguo"] = _xaether_safe_text((resumen + " | " if resumen else "") + f"Recuerdos antiguos compactados: {mini}", 900)
    raw["recuerdos"] = keep
    keep_hashes = {_xaether_hash(str(r).lower()) for r in keep}
    raw["recuerdos_meta"] = [m for m in raw.get("recuerdos_meta", []) if isinstance(m, dict) and m.get("hash") in keep_hashes]


def obtener_memoria_usuario(user_id: int) -> list:
    memoria = cargar_memoria_aether()
    raw = _xaether_normalize_user_memory(memoria, user_id)
    _xaether_compact_memory(raw)
    metas = {m.get("hash"): m for m in raw.get("recuerdos_meta", []) if isinstance(m, dict)}
    recuerdos = list(raw.get("recuerdos", []) or [])
    recuerdos.sort(key=lambda r: (metas.get(_xaether_hash(str(r).lower()), {}).get("relevance", 0), metas.get(_xaether_hash(str(r).lower()), {}).get("created_at", "")), reverse=True)
    return recuerdos[:XAETHER_MEMORY_MAX]


def _xaether_channel_style(channel_id: int | None) -> str:
    if not channel_id:
        return "DM / estilo personal"
    data = _xaether_load_json_sync(XAETHER_CHANNEL_MEMORY_FILE, {"channels": {}})
    info = (data.get("channels", {}) or {}).get(str(channel_id), {})
    return str(info.get("style", "neutral"))


def construir_contexto_memoria(user_id: int) -> str:
    memoria = cargar_memoria_aether()
    raw = _xaether_normalize_user_memory(memoria, user_id)
    recuerdos = obtener_memoria_usuario(user_id)
    if not recuerdos and not raw.get("resumen_antiguo"):
        return "\n━━ MEMORIA AETHER 3.1 ━━━━━━━━━━━━━━━━━━━━━━━\nSin recuerdos persistentes útiles todavía.\n"
    selected = recuerdos[:XAETHER_MEMORY_CONTEXT_LIMIT]
    older_count = max(0, len(recuerdos) - len(selected))
    resumen = raw.get("resumen_antiguo") or ""
    if older_count and not resumen:
        resumen = "Resumen automático: existen recuerdos antiguos menos recientes; prioriza los mostrados salvo que el usuario pida historial."
    lineas = "\n".join(f"  • {r}" for r in selected) or "  • Sin recuerdos recientes seleccionados."
    return f"""
━━ MEMORIA AETHER 3.0 · RELEVANCIA ━━━━━━━━━━━
{lineas}
{('  • ' + resumen) if resumen else ''}
Total recuerdos compatibles: {len(recuerdos)}. Se inyectan {len(selected)} por relevancia para no saturar contexto.
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Usa esta memoria solo si aporta valor. No la enumeres salvo petición directa.
"""


async def _xaether_add_memory(user_id: int, username: str, new_memories: list[str]):
    memoria = await xaether_load_json_async(MEMORIA_FILE, {})
    memoria.setdefault("_meta", {})["version"] = "3.1.0"
    raw = _xaether_normalize_user_memory(memoria, user_id)
    raw["username"] = username
    existing_hashes = {_xaether_hash(str(r).lower()) for r in raw.get("recuerdos", [])}
    for mem in new_memories:
        text = _xaether_safe_text(mem, 180).lstrip("-•· ").strip()
        score = _xaether_memory_importance(text)
        if not text or score <= 0:
            continue
        h = _xaether_hash(text.lower())
        if h in existing_hashes:
            for meta in raw.get("recuerdos_meta", []):
                if isinstance(meta, dict) and meta.get("hash") == h:
                    meta["relevance"] = min(10, int(meta.get("relevance", score)) + 1)
                    meta["last_used"] = _xaether_now_iso()
            continue
        raw["recuerdos"].append(text)
        raw["recuerdos_meta"].append({"hash": h, "text": text, "relevance": score, "created_at": _xaether_now_iso(), "last_used": None, "uses": 0})
        existing_hashes.add(h)
    _xaether_compact_memory(raw)
    await xaether_save_json_async(MEMORIA_FILE, memoria)


async def actualizar_memoria_aether(user_id: int, username: str, historial_reciente: list):
    """X AETHER ULTRA PATCH: memoria a largo plazo con 200 recuerdos, relevancia y filtro de privacidad."""
    if not historial_reciente or len(historial_reciente) < 2:
        return
    mensajes_usuario = [m for m in historial_reciente if isinstance(m, dict) and m.get("role") == "user"]
    if len(mensajes_usuario) < 2:
        return
    try:
        conv_texto = ""
        for m in historial_reciente[-10:]:
            if not isinstance(m, dict):
                continue
            rol = username if m.get("role") == "user" else "AETHER"
            conv_texto += f"{rol}: {_xaether_safe_text(m.get('content'), 650)}\n"

        recuerdos_actuales = obtener_memoria_usuario(user_id)
        recuerdos_str = "\n".join(f"- {r}" for r in recuerdos_actuales[:60]) if recuerdos_actuales else "Ninguno aún."
        prompt_memoria = f"""Eres el módulo de memoria persistente de X AETHER.
Extrae recuerdos útiles, estables y no sensibles del usuario {username}.

CONVERSACIÓN RECIENTE:
{conv_texto}

RECUERDOS ACTUALES:
{recuerdos_str}

REGLAS:
- Responde NADA si no hay nada útil.
- Máximo 4 recuerdos nuevos.
- Una línea por recuerdo, empezando con '-'.
- No guardes contraseñas, tokens, secretos, datos bancarios, datos íntimos ni insultos.
- Prioriza preferencias, proyectos, decisiones técnicas, gustos, estilo y contexto que mejore respuestas futuras.
"""
        resultado = None
        if GROQ_API_KEY and groq_async_client:
            try:
                resultado = await asyncio.wait_for(_llamar_groq_async([{"role": "user", "content": prompt_memoria}], GROQ_MODELOS[_modelo_idx]), timeout=18)
            except Exception as exc:
                print(f"[AETHER MEM 3.0] extractor IA falló: {exc!r}")
        if not resultado:
            # Extractor offline mínimo: recoge frases explícitas de preferencia/recuerdo.
            posibles = []
            for m in mensajes_usuario[-6:]:
                txt = _xaether_safe_text(m.get("content"), 180)
                if any(k in txt.lower() for k in ["recuerda", "prefiero", "quiero que", "mi proyecto", "a partir de ahora"]):
                    posibles.append("- " + txt)
            resultado = "\n".join(posibles) if posibles else "NADA"
        if str(resultado).strip().upper() == "NADA":
            return
        nuevas = []
        for line in str(resultado).splitlines():
            line = line.strip().lstrip("-•· ").strip()
            if line and line.upper() != "NADA":
                nuevas.append(line)
        if nuevas:
            await _xaether_add_memory(user_id, username, nuevas[:4])
            estado = cargar_ouroboros()
            estado["estadisticas"]["usuarios_recordados"] = len([k for k in cargar_memoria_aether().keys() if not str(k).startswith("_")])
            guardar_ouroboros(estado)
    except Exception as exc:
        print(f"[AETHER MEM 3.0] Error actualizando memoria: {exc!r}")


async def _xaether_track_channel_style(message: discord.Message):
    """X AETHER ULTRA PATCH: memoria por canal, estilo de conversación y señales de adjuntos."""
    try:
        if not message.guild or not message.channel:
            _xaether_runtime_context[message.author.id] = {"channel_id": None, "channel_name": "DM", "guild_id": None, "attachments": []}
            return
        content = str(message.content or "")
        low = content.lower()
        channel_name = getattr(message.channel, "name", "canal") or "canal"
        style = "neutral"
        if any(x in channel_name.lower() for x in ["ayuda", "soporte", "ticket"]):
            style = "formal_soporte"
        elif any(x in channel_name.lower() for x in ["general", "chat", "off-topic"]):
            style = "coloquial"
        elif any(x in channel_name.lower() for x in ["casino", "minijuego", "juego"]):
            style = "energico_juegos"
        elif any(x in low for x in ["error", "traceback", "código", "codigo", "python"]):
            style = "tecnico"
        attachments = []
        for a in getattr(message, "attachments", []) or []:
            attachments.append({"filename": a.filename, "content_type": getattr(a, "content_type", None), "url": a.url, "size": getattr(a, "size", 0)})
        _xaether_runtime_context[message.author.id] = {
            "channel_id": message.channel.id,
            "channel_name": channel_name,
            "guild_id": message.guild.id,
            "style": style,
            "is_staff": bool(getattr(message.author.guild_permissions, "manage_messages", False) or getattr(message.author.guild_permissions, "administrator", False)),
            "attachments": attachments,
        }
        data = await xaether_load_json_async(XAETHER_CHANNEL_MEMORY_FILE, {"channels": {}})
        ch = data.setdefault("channels", {}).setdefault(str(message.channel.id), {"name": channel_name, "style_counts": {}, "last_messages": []})
        ch["name"] = channel_name
        ch.setdefault("style_counts", {})[style] = int(ch.setdefault("style_counts", {}).get(style, 0)) + 1
        ch["style"] = max(ch["style_counts"], key=ch["style_counts"].get)
        ch.setdefault("last_messages", []).append({"user": message.author.id, "sample": _xaether_safe_text(content, 160), "at": _xaether_now_iso()})
        ch["last_messages"] = ch["last_messages"][-30:]
        await xaether_save_json_async(XAETHER_CHANNEL_MEMORY_FILE, data)
    except Exception as exc:
        print(f"[X AETHER CHANNEL MEMORY] {exc!r}")


