def _xau_lock_for(path: str):
    """Return one asyncio lock per JSON file path."""
    key = os.path.abspath(str(path))
    if key not in _XAU_JSON_LOCKS:
        _XAU_JSON_LOCKS[key] = asyncio.Lock()
    return _XAU_JSON_LOCKS[key]

async def xau_json_load(path: str, default=None):
    """Async JSON loader with per-file lock and corruption fallback."""
    lock = _xau_lock_for(path)
    async with lock:
        def _read():
            if not os.path.exists(path):
                return default.copy() if isinstance(default, dict) else (default or {})
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
                return data if data is not None else (default.copy() if isinstance(default, dict) else (default or {}))
            except json.JSONDecodeError:
                backup = f"{path}.corrupt.{int(time.time())}.bak"
                try:
                    os.replace(path, backup)
                    print(f"[{BOT_NAME}] JSON corrupto movido a {backup}")
                except Exception:
                    pass
                return default.copy() if isinstance(default, dict) else (default or {})
        return await asyncio.to_thread(_read)

async def xau_json_save(path: str, data):
    """Async atomic JSON writer. It writes a temp file and then replaces the target."""
    lock = _xau_lock_for(path)
    async with lock:
        def _write():
            folder = os.path.dirname(path) or "."
            os.makedirs(folder, exist_ok=True)
            fd, tmp = tempfile.mkstemp(prefix=".xau_", suffix=".json", dir=folder)
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as fh:
                    json.dump(data if data is not None else {}, fh, ensure_ascii=False, indent=2)
                    fh.flush()
                    os.fsync(fh.fileno())
                os.replace(tmp, path)
            finally:
                try:
                    if os.path.exists(tmp):
                        os.remove(tmp)
                except Exception:
                    pass
        await asyncio.to_thread(_write)

def cargar_datos() -> Dict[str, Any]:
    """Synchronous compatibility loader for legacy commands."""
    try:
        if not os.path.exists(DATOS_FILE):
            return {}
        with open(DATOS_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return data if isinstance(data, dict) else {}
    except json.JSONDecodeError:
        backup = f"{DATOS_FILE}.corrupt.{int(time.time())}.bak"
        try:
            os.replace(DATOS_FILE, backup)
            print(f"[{BOT_NAME}] datos.json corrupto movido a {backup}")
        except Exception:
            pass
        return {}
    except Exception as exc:
        print(f"[{BOT_NAME}] Error cargando datos.json: {exc!r}")
        return {}

def guardar_datos(datos: Dict[str, Any]):
    """Synchronous atomic writer kept for old code paths."""
    try:
        folder = os.path.dirname(DATOS_FILE) or "."
        os.makedirs(folder, exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=".datos_", suffix=".json", dir=folder)
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(datos if isinstance(datos, dict) else {}, fh, ensure_ascii=False, indent=2)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, DATOS_FILE)
    except Exception as exc:
        print(f"[{BOT_NAME}] Error guardando datos.json: {exc!r}")
        try:
            if "tmp" in locals() and os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass

async def cargar_datos_async() -> Dict[str, Any]:
    """Async compatibility loader used by ULTRA commands."""
    data = await xau_json_load(DATOS_FILE, {})
    return data if isinstance(data, dict) else {}

async def guardar_datos_async(datos: Dict[str, Any]):
    """Async compatibility writer used by ULTRA commands."""
    await xau_json_save(DATOS_FILE, datos if isinstance(datos, dict) else {})

def xaether_embed(title: str, description: str = "", color=None, user=None) -> discord.Embed:
    """Premium embed helper unified for X AETHER ULTRA."""
    color = color or discord.Color.from_rgb(170, 82, 255)
    embed = discord.Embed(title=title, description=description or "", color=color, timestamp=datetime.datetime.now(datetime.timezone.utc))
    if user is not None:
        try:
            embed.set_thumbnail(url=user.display_avatar.url)
        except Exception:
            pass
    embed.set_footer(text=BOT_FOOTER)
    return embed

def xau_bar(value: int, maximum: int, size: int = 14, full: str = "▰", empty: str = "▱") -> str:
    """Small visual progress bar for embeds."""
    maximum = max(1, int(maximum or 1))
    value = max(0, min(int(value or 0), maximum))
    filled = round((value / maximum) * size)
    return full * filled + empty * (size - filled)

async def xau_safe_send(destination, *, content=None, embed=None, view=None, file=None, delete_after=None):
    """Send helper that converts common Discord errors into safe no-crash behavior."""
    try:
        return await destination.send(content=content, embed=embed, view=view, file=file, delete_after=delete_after)
    except discord.Forbidden:
        return None
    except discord.NotFound:
        return None
    except discord.HTTPException as exc:
        print(f"[{BOT_NAME}] HTTPException enviando mensaje: {exc!r}")
        return None
    except Exception as exc:
        print(f"[{BOT_NAME}] Error enviando mensaje: {exc!r}")
        return None

def xau_parse_bet(raw, cash: int, default: int = 0) -> int:
    """Parse a bet value supporting all, half and numeric values."""
    if raw is None:
        return int(default or 0)
    txt = str(raw).lower().strip()
    if txt in ("all", "todo", "max"):
        return max(0, int(cash))
    if txt in ("half", "mitad"):
        return max(1, int(cash) // 2)
    txt = txt.replace(".", "").replace(",", "")
    return max(0, int(txt)) if txt.isdigit() else 0

def xau_money(n: int) -> str:
    """Format economy numbers."""
    try:
        return f"{int(n):,}".replace(",", ".")
    except Exception:
        return str(n)

