async def xau_update_game_stats(user_id: int, game: str, bet: int, net: int, win: bool):
    """Update real-time casino stats."""
    stats = await xau_load_game_stats()
    uid = str(user_id)
    user = stats.setdefault(uid, {})
    g = user.setdefault(game, {"plays": 0, "wins": 0, "losses": 0, "net": 0, "streak": 0, "best_streak": 0})
    g["plays"] = int(g.get("plays", 0)) + 1
    g["net"] = int(g.get("net", 0)) + int(net)
    if win:
        g["wins"] = int(g.get("wins", 0)) + 1
        g["streak"] = max(1, int(g.get("streak", 0)) + 1)
        g["best_streak"] = max(int(g.get("best_streak", 0)), int(g["streak"]))
    else:
        g["losses"] = int(g.get("losses", 0)) + 1
        g["streak"] = min(-1, int(g.get("streak", 0)) - 1)
    await xau_json_save(XAU_GAME_STATS_FILE, stats)
    return g

