async def check_achievements(user_id, ctx=None, channel=None):
    """Check and unlock achievements for a user. Call after relevant actions."""
    uid = str(user_id)
    logros = await xau_achievement_data()
    entry = logros.setdefault(uid, {"counters": {}, "unlocked": [], "updated_at": None})
    counters = entry.setdefault("counters", {})
    unlocked = set(entry.setdefault("unlocked", []))
    newly = []
    for ach_id, ach in XAU_ACHIEVEMENTS.items():
        if ach_id in unlocked:
            continue
        if int(counters.get(ach["counter"], 0)) >= int(ach["target"]):
            unlocked.add(ach_id)
            entry["unlocked"] = list(unlocked)
            newly.append((ach_id, ach))
            try:
                await xau_change_cash(int(user_id), int(ach.get("reward", 0)))
            except Exception:
                pass
    entry["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    await xau_json_save(LOGROS_FILE, logros)
    dest = channel or getattr(ctx, "channel", None)
    if dest:
        for ach_id, ach in newly:
            embed = xaether_embed(
                f"🏆 LOGRO DESBLOQUEADO · {ach['emoji']} {ach['name']}",
                f"```ansi\n\u001b[35m◆◆◆ X AETHER ULTRA ACHIEVEMENT ◆◆◆\u001b[0m\n```\n{ach['desc']}\n\nRecompensa: **{xau_money(ach.get('reward',0))}** amatistas\n{ xau_bar(1, 1, 18, '◆', '◇') }",
                discord.Color.gold(),
                getattr(ctx, "author", None)
            )
            await xau_safe_send(dest, embed=embed)
    return newly

async def xau_increment_achievement(user_id: int, counter: str, amount: int = 1, ctx=None, channel=None):
    """Increment one achievement counter and then check unlocks."""
    uid = str(user_id)
    logros = await xau_achievement_data()
    entry = logros.setdefault(uid, {"counters": {}, "unlocked": [], "updated_at": None})
    counters = entry.setdefault("counters", {})
    counters[counter] = int(counters.get(counter, 0)) + int(amount)
    entry["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    await xau_json_save(LOGROS_FILE, logros)
    return await check_achievements(user_id, ctx=ctx, channel=channel)

async def xau_animate(message, frames, delay: float = 0.55):
    """Edit a message through a visual sequence of embed frames."""
    for embed in frames:
        try:
            await message.edit(embed=embed)
        except (discord.Forbidden, discord.NotFound):
            return
        except discord.HTTPException:
            await asyncio.sleep(delay)
            continue
        await asyncio.sleep(delay)

class XAUReplayView(discord.ui.View):
    """Reusable replay button for ULTRA minigames."""
    def __init__(self, author_id: int, command_hint: str, timeout: float = 60):
        super().__init__(timeout=timeout)
        self.author_id = author_id
        self.command_hint = command_hint

    @discord.ui.button(label="Revancha", emoji="🔁", style=discord.ButtonStyle.primary)
    async def replay(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Solo quien inició la partida puede usar esta revancha.", ephemeral=True)
            return
        await interaction.response.send_message(f"🔥 Revancha lista: usa `{self.command_hint}`", ephemeral=True)

def xau_stats_text(stats: dict) -> str:
    """Render game statistics for an embed field."""
    return (
        f"Jugadas: **{stats.get('plays',0)}** · Victorias: **{stats.get('wins',0)}** · Derrotas: **{stats.get('losses',0)}**\n"
        f"Neto: **{xau_money(stats.get('net',0))}** · Racha: **{stats.get('streak',0)}** · Mejor racha: **{stats.get('best_streak',0)}**"
    )

async def xau_game_intro(ctx, title: str, desc: str, color=None):
    """Create a starting message for animated games."""
    embed = xaether_embed(title, desc, color or X_AETHER_ACCENT, ctx.author)
    embed.add_field(name="Fase", value="`Preparación` " + xau_bar(1, 3, 12), inline=False)
    return await ctx.send(embed=embed)

async def xau_finish_game(ctx, msg, game: str, bet: int, net: int, win: bool, title: str, result: str, jackpot: bool = False):
    """Apply money, stats, achievements and final visuals."""
    if bet > 0:
        await xau_change_cash(ctx.author.id, net)
    stats = await xau_update_game_stats(ctx.author.id, game, bet, net, win)
    await xau_increment_achievement(ctx.author.id, "casino", 1, ctx=ctx)
    if jackpot:
        await xau_increment_achievement(ctx.author.id, "jackpot", 1, ctx=ctx)
    color = discord.Color.gold() if jackpot else (X_AETHER_OK if win else X_AETHER_WARN)
    boom = "👑 ✨ 💎 🔥 💜 ⚡ 👑" if jackpot else ("✨ 💜 ✨" if win else "🖤 ▱ 🖤")
    embed = xaether_embed(title, f"{boom}\n\n{result}\n\nNeto: **{xau_money(net)}** amatistas", color, ctx.author)
    embed.add_field(name="Fase", value="`Resultado` " + xau_bar(3, 3, 12), inline=False)
    embed.add_field(name="Estadísticas en tiempo real", value=xau_stats_text(stats), inline=False)
    view = XAUReplayView(ctx.author.id, f"!{game} {bet if bet else 'showcase'}")
    try:
        await msg.edit(embed=embed, view=view)
    except Exception:
        await ctx.send(embed=embed, view=view)

async def xau_require_bet(ctx, amount: int):
    """Validate a paid bet and send a friendly embed on failure."""
    if amount <= 0:
        await ctx.send(embed=xaether_embed("💎 Apuesta inválida", "Usa una cantidad mayor que 0 o `showcase` para ver la animación sin apostar.", X_AETHER_WARN, ctx.author))
        return False
    if not await xau_can_pay(ctx.author.id, amount):
        await ctx.send(embed=xaether_embed("💸 Cash insuficiente", "No tienes suficientes amatistas en cash para esa apuesta.", X_AETHER_WARN, ctx.author))
        return False
    return True

async def xau_autoplay(ctx, game_runner, raw_amount: str, rounds: int, *args):
    """Run a controlled autoplay sequence for a minigame."""
    rounds = max(1, min(int(rounds or 3), 5))
    for idx in range(rounds):
        await ctx.send(embed=xaether_embed("🤖 Autoplay ULTRA", f"Ronda automática **{idx+1}/{rounds}**", X_AETHER_ACCENT, ctx.author))
        await game_runner(ctx, raw_amount, *args)
        if idx < rounds - 1:
            await asyncio.sleep(1.2)

async def xau_slots_runner(ctx, cantidad: str = "showcase"):
    data, uid, rec = await xau_get_user_record(ctx.author.id)
    cash = int(rec.get("cash", 0) or 0)
    showcase = str(cantidad).lower() in ("showcase", "demo", "0")
    bet = 0 if showcase else xau_parse_bet(cantidad, cash)
    if not showcase and not await xau_require_bet(ctx, bet):
        return
    msg = await xau_game_intro(ctx, "🎰 Slots ULTRA · Motor Neón", "`Preparando rodillos...`", discord.Color.purple())
    symbols = _XAU_GAME_EMOJIS["slots"]
    r = [random.choice(symbols) for _ in range(3)]
    frames = []
    for i in range(3):
        visible = [r[j] if j <= i else "❔" for j in range(3)]
        e = xaether_embed("🎰 Slots ULTRA · Rodillos girando", f"```ansi\n\u001b[35m🎰 | {' | '.join(visible)} | 🎰\u001b[0m\n```\n{xau_bar(i+1,3,14)}", X_AETHER_ACCENT, ctx.author)
        e.add_field(name="Fase", value="`Desarrollo` " + xau_bar(2,3,12), inline=False)
        frames.append(e)
    await xau_animate(msg, frames, 0.6)
    jackpot = r[0] == r[1] == r[2]
    pair = len(set(r)) == 2
    if jackpot:
        mult = 8 if r[0] in ("👑", "7️⃣", "💎") else 5
    elif pair:
        mult = 2
    else:
        mult = 0
    net = 0 if showcase else (bet * mult - bet)
    win = mult > 0
    result = f"Resultado final:\n```ansi\n\u001b[33m🎰 | {' | '.join(r)} | 🎰\u001b[0m\n```\n" + (f"**JACKPOT x{mult}!**" if jackpot else (f"Ganancia x{mult}." if win else "No tocó premio."))
    await xau_finish_game(ctx, msg, "slots", bet, net, win, "🎰 Slots ULTRA · Resultado", result, jackpot)

