def xau_card_value(card: str) -> int:
    """Blackjack card value."""
    rank = card[:-2]
    if rank in ("K","Q","J"):
        return 10
    if rank == "A":
        return 11
    try:
        return int(rank)
    except Exception:
        return 10

def xau_hand_value(hand):
    """Blackjack hand value with ace adjustment."""
    total = sum(xau_card_value(c) for c in hand)
    aces = sum(1 for c in hand if c.startswith("A"))
    while total > 21 and aces:
        total -= 10
        aces -= 1
    return total

async def xau_blackjack_runner(ctx, cantidad: str = "showcase"):
    data, uid, rec = await xau_get_user_record(ctx.author.id)
    cash = int(rec.get("cash", 0) or 0)
    showcase = str(cantidad).lower() in ("showcase", "demo", "0")
    bet = 0 if showcase else xau_parse_bet(cantidad, cash)
    if not showcase and not await xau_require_bet(ctx, bet):
        return
    deck = [r+s for r in ["A","K","Q","J","10","9","8","7","6","5","4","3","2"] for s in ["♠️","♥️","♦️","♣️"]]
    random.shuffle(deck)
    player = [deck.pop(), deck.pop()]
    dealer = [deck.pop(), deck.pop()]
    msg = await xau_game_intro(ctx, "🃏 Blackjack ULTRA", "Repartiendo cartas con brillo amatista...", X_AETHER_ACCENT)
    frames = [
        xaether_embed("🃏 Blackjack · Reparto 1", f"Tú: `{player[0]}` `?`\nDealer: `{dealer[0]}` `?`", X_AETHER_ACCENT, ctx.author),
        xaether_embed("🃏 Blackjack · Reparto 2", f"Tú: `{player[0]}` `{player[1]}` = **{xau_hand_value(player)}**\nDealer: `{dealer[0]}` `?`", X_AETHER_ACCENT, ctx.author),
    ]
    await xau_animate(msg, frames, 0.75)
    while xau_hand_value(player) < 16:
        player.append(deck.pop())
    while xau_hand_value(dealer) < 17:
        dealer.append(deck.pop())
    pv, dv = xau_hand_value(player), xau_hand_value(dealer)
    win = (pv <= 21 and (dv > 21 or pv > dv))
    tie = pv == dv and pv <= 21
    blackjack = len(player) == 2 and pv == 21
    mult = 2.5 if blackjack else 2
    net = 0 if showcase or tie else (int(bet * (mult - 1)) if win else -bet)
    result = f"Tú: {' '.join(f'`{c}`' for c in player)} = **{pv}**\nDealer: {' '.join(f'`{c}`' for c in dealer)} = **{dv}**\n" + ("Empate." if tie else ("Blackjack premium." if blackjack else ("Victoria." if win else "Pierdes.")))
    await xau_finish_game(ctx, msg, "blackjack", bet, net, win, "🃏 Blackjack ULTRA · Resultado", result, blackjack)

