async def xau_simple_show_game(ctx, game: str, title: str, frames_text, win_chance: float = 0.5, reward: int = 0):
    """Generic animated free minigame helper."""
    msg = await xau_game_intro(ctx, title, "Showcase interactivo sin apuesta.", X_AETHER_ACCENT)
    frames = []
    for i, txt in enumerate(frames_text):
        e = xaether_embed(title, f"{txt}\n{xau_bar(i+1,len(frames_text),14)}", X_AETHER_ACCENT, ctx.author)
        e.add_field(name="Fase", value="`Desarrollo` " + xau_bar(2,3,12), inline=False)
        frames.append(e)
    await xau_animate(msg, frames, 0.55)
    win = random.random() < win_chance
    net = reward if win else 0
    if net:
        await xau_change_cash(ctx.author.id, net)
    stats = await xau_update_game_stats(ctx.author.id, game, 0, net, win)
    if game == "bingo" and win:
        await xau_increment_achievement(ctx.author.id, "bingo", 1, ctx=ctx)
    embed = xaether_embed(f"{title} · Resultado", ("Victoria visual." if win else "Intento fallido, pero quedó cine.") + (f"\nRecompensa: **{xau_money(net)}** amatistas" if net else ""), X_AETHER_OK if win else X_AETHER_WARN, ctx.author)
    embed.add_field(name="Estadísticas", value=xau_stats_text(stats), inline=False)
    await msg.edit(embed=embed, view=XAUReplayView(ctx.author.id, f"!{game}"))

