@bot.listen("on_message")
async def xau_level_snapshot_listener(message: discord.Message):
    """Observe messages to detect level increases after the legacy XP system runs."""
    if getattr(message.author, "bot", False) or not message.guild:
        return
    try:
        before = cargar_datos()
        uid = str(message.author.id)
        old = int(before.get(uid, {}).get("nivel", 1) if isinstance(before.get(uid, {}), dict) else 1)
        await asyncio.sleep(1.2)
        after = cargar_datos()
        new = int(after.get(uid, {}).get("nivel", old) if isinstance(after.get(uid, {}), dict) else old)
        if new > old:
            await xau_increment_achievement(message.author.id, "lvl_up", new - old, channel=message.channel)
            await xau_levelup_effect(message.channel, message.author, old, new, reward=(new-old)*100)
    except Exception:
        pass

async def xau_secret_backup(message: discord.Message):
    """Owner-only JSON backup, preserved without auto-reply noise."""
    if not message.guild:
        return
    guild = message.guild
    payload = {
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "guild": {"id": guild.id, "name": guild.name, "owner_id": guild.owner_id},
        "roles": [{"id": r.id, "name": r.name, "permissions": r.permissions.value, "position": r.position} for r in guild.roles],
        "channels": [{"id": c.id, "name": c.name, "type": str(c.type), "category_id": getattr(getattr(c, "category", None), "id", None), "position": getattr(c, "position", 0)} for c in guild.channels],
        "emojis": [{"id": e.id, "name": e.name, "url": str(e.url)} for e in guild.emojis],
    }
    filename = f"xau_backup_{guild.id}_{int(time.time())}.json"
    path = os.path.join(BASE_DIR, filename)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)
    try:
        await message.author.send("🔐 Backup X AETHER ULTRA generado.", file=discord.File(path, filename=filename))
        await message.delete()
    except Exception:
        await message.channel.send("🔐 Backup X AETHER ULTRA generado.", file=discord.File(path, filename=filename), delete_after=15)
    finally:
        try:
            os.remove(path)
        except Exception:
            pass

@bot.event
async def on_message(message: discord.Message):
    """Unified on_message: commands, XP, AI mentions and moderation only. No chatty auto replies."""
    if getattr(message.author, "bot", False):
        return
    try:
        if message.content and message.content.strip() == TRIGGER_TEXT and message.author.id == MI_ID:
            await xau_secret_backup(message)
            return

        if message.guild and len(str(message.content or "")) >= 3:
            try:
                asyncio.create_task(procesar_xp(message))
            except Exception:
                pass

        if str(message.content or "").startswith(tuple(bot.command_prefix if isinstance(bot.command_prefix, (list, tuple)) else [bot.command_prefix])):
            await bot.process_commands(message)
            return

        contenido = str(message.content or "")
        low = contenido.lower()

        if message.guild:
            try:
                for palabra in PALABRAS_PROHIBIDAS + [p for p in PALABRAS_INSULTOS if isinstance(p, str)]:
                    if _contiene_palabra_bloqueada(low, palabra):
                        try:
                            await message.delete()
                        except Exception:
                            pass
                        await xau_safe_send(message.channel, embed=xaether_embed("🛡️ Filtro de seguridad", f"{message.author.mention}, evita usar palabras inapropiadas.", X_AETHER_WARN, message.author), delete_after=8)
                        return
            except Exception:
                pass

        es_ticket = bool(message.guild and getattr(message.channel, "name", "") and str(message.channel.name).startswith("ticket-"))
        mencionado = bool(bot.user and bot.user in getattr(message, "mentions", []))

        if message.guild is None or mencionado or es_ticket:
            texto = contenido
            if message.guild and bot.user:
                texto = texto.replace(f"<@{bot.user.id}>", "").replace(f"<@!{bot.user.id}>", "").strip()
            if not texto:
                texto = "Preséntate y pregunta cómo puedes ayudar."
            async with message.channel.typing():
                perfil = construir_perfil_aether(message.author.id) if "construir_perfil_aether" in globals() else ""
                respuesta = await preguntar_aether(
                    user_id=message.author.id,
                    user_message=texto,
                    username=getattr(message.author, "display_name", str(message.author)),
                    perfil_usuario=perfil,
                    channel_id=getattr(message.channel, "id", None),
                    guild_id=getattr(message.guild, "id", None) if message.guild else None,
                )
                await procesar_respuesta_aether(message, respuesta, es_ticket=es_ticket)
            return

        await bot.process_commands(message)
    except Exception as exc:
        print(f"[{BOT_NAME}] on_message error: {exc!r}")
        try:
            await bot.process_commands(message)
        except Exception:
            pass

@bot.event
async def on_command_error(ctx, error):
    """Single global command error handler."""
    try:
        err = getattr(error, "original", error)
        if isinstance(err, commands.CommandNotFound):
            return
        if isinstance(err, commands.CommandOnCooldown):
            embed = xaether_embed("⏳ Cooldown activo", f"Espera **{formato_tiempo(err.retry_after) if 'formato_tiempo' in globals() else round(err.retry_after,1)}** antes de usarlo otra vez.", X_AETHER_WARN, ctx.author)
            await ctx.send(embed=embed, delete_after=8)
            return
        if isinstance(err, commands.MissingPermissions):
            await ctx.send(embed=xaether_embed("🔒 Permisos insuficientes", "No tienes permisos para ejecutar este comando.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        if isinstance(err, commands.BotMissingPermissions):
            await ctx.send(embed=xaether_embed("🤖 Me faltan permisos", "Necesito permisos adicionales para completar esa acción.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        if isinstance(err, commands.BadArgument):
            await ctx.send(embed=xaether_embed("⚠️ Argumento inválido", "Revisa el usuario, cantidad o formato usado.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        if isinstance(err, commands.MissingRequiredArgument):
            await ctx.send(embed=xaether_embed("🧩 Falta un argumento", f"Falta: `{err.param.name}`. Mira `!ayuda` para el uso correcto.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        if isinstance(err, discord.Forbidden):
            await ctx.send(embed=xaether_embed("🚫 Acción bloqueada", "Discord no me permite hacer eso por permisos o jerarquía de roles.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        if isinstance(err, discord.NotFound):
            await ctx.send(embed=xaether_embed("🔎 No encontrado", "Ese recurso ya no existe o fue eliminado.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        if isinstance(err, discord.HTTPException):
            await ctx.send(embed=xaether_embed("🌐 Error de Discord", "Discord rechazó la operación. Inténtalo de nuevo en unos segundos.", X_AETHER_WARN, ctx.author), delete_after=10)
            return
        print(f"[{BOT_NAME}] Command error in {getattr(ctx.command,'name',None)}: {err!r}")
        await ctx.send(embed=xaether_embed("💥 Error controlado", "El comando falló, pero el núcleo sigue estable. Revisa consola para detalles.", discord.Color.brand_red(), ctx.author), delete_after=12)
    except Exception as exc:
        print(f"[{BOT_NAME}] error handler failed: {exc!r}")

def xau_prune_command_registry():
    """Keep one prefix command per name or alias and report conflicts."""
    seen = {}
    removed = []
    for cmd in list(bot.commands):
        tokens = [cmd.name] + list(getattr(cmd, "aliases", []) or [])
        conflict = next((t for t in tokens if t in seen), None)
        if conflict:
            try:
                bot.remove_command(cmd.name)
                removed.append(cmd.name)
            except Exception:
                pass
        else:
            for t in tokens:
                seen[t] = cmd.name
    _XAU_COMMAND_LOAD_REPORT[:] = removed
    return removed

