def xau_voice_energy_gate(samples: bytes, sample_width: int = 2, threshold: int = 420):
    """Simple energy-based voice gate for future voice receive integrations."""
    if not samples:
        return False
    try:
        count = max(1, len(samples) // sample_width)
        total = 0
        for i in range(0, len(samples) - 1, sample_width):
            val = int.from_bytes(samples[i:i+sample_width], "little", signed=True)
            total += abs(val)
        return (total / count) >= threshold
    except Exception:
        return False

