def _xau_world_now_iso():
    """Return a compact UTC timestamp for feature-state metadata."""
    try:
        return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")
    except Exception:
        return str(datetime.datetime.utcnow())

async def xau_world_load_state():
    """Load world feature state without changing old bot JSON formats."""
    default = {"enabled": {}, "guilds": {}, "history": [], "version": BOT_WORLD_FEATURE_ENGINE_VERSION}
    try:
        if "xau_json_load" in globals():
            data = await xau_json_load(WORLD_FEATURES_FILE, default)
        else:
            data = await asyncio.to_thread(lambda: json.load(open(WORLD_FEATURES_FILE, "r", encoding="utf-8")) if os.path.exists(WORLD_FEATURES_FILE) else default.copy())
        if not isinstance(data, dict):
            return default
        data.setdefault("enabled", {})
        data.setdefault("guilds", {})
        data.setdefault("history", [])
        data.setdefault("version", BOT_WORLD_FEATURE_ENGINE_VERSION)
        return data
    except Exception:
        return default

async def xau_world_save_state(data):
    """Save world feature state using the global atomic JSON helper when available."""
    data = data if isinstance(data, dict) else {}
    data.setdefault("version", BOT_WORLD_FEATURE_ENGINE_VERSION)
    if "xau_json_save" in globals():
        await xau_json_save(WORLD_FEATURES_FILE, data)
        return
    def _write():
        os.makedirs(os.path.dirname(WORLD_FEATURES_FILE) or ".", exist_ok=True)
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False, dir=os.path.dirname(WORLD_FEATURES_FILE) or ".", suffix=".tmp") as tmp:
            json.dump(data, tmp, ensure_ascii=False, indent=2)
            tmp.flush()
            os.fsync(tmp.fileno())
            tmp_name = tmp.name
        os.replace(tmp_name, WORLD_FEATURES_FILE)
    await asyncio.to_thread(_write)

def xau_world_find_features(query: str = "", *, category: str = "", source: str = "", limit: int = 12):
    """Search feature blueprints by free text, category or source family."""
    query_l = (query or "").strip().lower()
    category_l = (category or "").strip().lower()
    source_l = (source or "").strip().lower()
    results = []
    for feature in WORLD_FEATURE_BLUEPRINTS:
        hay = " ".join(str(feature.get(k, "")) for k in ("id", "source_family", "platform", "category", "tier", "title", "description")).lower()
        if query_l and query_l not in hay:
            continue
        if category_l and category_l != str(feature.get("category", "")).lower():
            continue
        if source_l and source_l not in str(feature.get("source_family", "")).lower():
            continue
        results.append(feature)
        if len(results) >= max(1, limit):
            break
    return results

def xau_world_categories():
    """Return sorted category names for the world feature engine."""
    return sorted({f.get("category", "otros") for f in WORLD_FEATURE_BLUEPRINTS})

def xau_world_sources():
    """Return sorted source family names for the world feature engine."""
    return sorted({f.get("source_family", "Unknown") for f in WORLD_FEATURE_BLUEPRINTS})

def xau_world_summary_text():
    """Build a compact overview of loaded feature families."""
    categories = xau_world_categories()
    sources = xau_world_sources()
    return (
        f"Blueprints cargados: **{len(WORLD_FEATURE_BLUEPRINTS):,}**\n"
        f"Familias de bots: **{len(sources)}**\n"
        f"Categorías: **{len(categories)}**\n"
        f"Motor: `{BOT_WORLD_FEATURE_ENGINE_VERSION}`\n\n"
        f"Categorías: `{', '.join(categories[:18])}`"
    )

def xau_world_feature_to_line(feature):
    """Render one feature as a readable Discord line."""
    return f"`{feature.get('id')}` · **{feature.get('title')}** · {feature.get('source_family')} · `{feature.get('tier')}`"

def xau_world_embed(title, description, ctx=None, color=None):
    """Use the premium embed helper if present, otherwise create a safe fallback."""
    if "xaether_embed" in globals():
        return xaether_embed(title, description, color or globals().get("X_AETHER_ACCENT", discord.Color.purple()), getattr(ctx, "author", None) if ctx else None)
    embed = discord.Embed(title=title, description=description, color=color or discord.Color.purple())
    embed.set_footer(text=f"X AETHER ULTRA · {BOT_WORLD_FEATURE_ENGINE_VERSION}")
    return embed

class XAUWorldFeatureView(discord.ui.View):
    """Small paginated feature browser. It avoids registering thousands of commands."""
    def __init__(self, ctx, features, page=0):
        super().__init__(timeout=90)
        self.ctx = ctx
        self.features = list(features)
        self.page = max(0, page)
        self.per_page = 8

    def page_count(self):
        return max(1, (len(self.features) + self.per_page - 1) // self.per_page)

    def make_embed(self):
        start = self.page * self.per_page
        chunk = self.features[start:start + self.per_page]
        desc = "\n".join(xau_world_feature_to_line(f) for f in chunk) or "No hay resultados."
        desc += f"\n\nPágina **{self.page+1}/{self.page_count()}** · `{len(self.features)}` resultados cargados."
        return xau_world_embed("🌍 X AETHER ULTRA · World Features", desc, self.ctx)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return interaction.user.id == self.ctx.author.id

    @discord.ui.button(label="◀", style=discord.ButtonStyle.secondary)
    async def prev_page(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page = (self.page - 1) % self.page_count()
        await interaction.response.edit_message(embed=self.make_embed(), view=self)

    @discord.ui.button(label="▶", style=discord.ButtonStyle.secondary)
    async def next_page(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page = (self.page + 1) % self.page_count()
        await interaction.response.edit_message(embed=self.make_embed(), view=self)

# Command registration guard: remove old aliases before adding the new world commands.
for _xau_world_cmd in ("worldbots", "worldmodulos", "worldfeature", "worldactivar", "worlddesactivar", "worldestado", "worldpack", "megafunciones"):
    try:
        bot.remove_command(_xau_world_cmd)
    except Exception:
        pass

@bot.command(name="worldbots", aliases=["megabots", "botfamilias"])
@commands.cooldown(1, 8, commands.BucketType.user)
async def worldbots(ctx):
    """Show public bot families used as inspiration for the feature blueprint engine."""
    lines = []
    for key, data in list(WORLD_FEATURE_REFERENCE_FAMILIES.items())[:30]:
        lines.append(f"`{key}` · **{data['name']}** · {data['platform']} · {data['inspiration']}")
    embed = xau_world_embed("🌍 Familias de bots estudiadas", "\n".join(lines), ctx)
    embed.add_field(name="Motor", value=f"{len(WORLD_FEATURE_BLUEPRINTS):,} blueprints listos para X AETHER ULTRA.", inline=False)
    await ctx.send(embed=embed)

@bot.command(name="worldmodulos", aliases=["modulosworld", "categoriasworld"])
@commands.cooldown(1, 8, commands.BucketType.user)
async def worldmodulos(ctx):
    """List all major world feature categories."""
    cats = xau_world_categories()
    desc = "\n".join(f"`{c}` · {sum(1 for f in WORLD_FEATURE_BLUEPRINTS if f.get('category') == c)} módulos" for c in cats)
    await ctx.send(embed=xau_world_embed("🧩 Categorías World Features", desc[:3900], ctx))

@bot.command(name="worldfeature", aliases=["buscarfeature", "feature"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def worldfeature(ctx, *, query: str = ""):
    """Search a feature blueprint by text, source, category or id."""
    results = xau_world_find_features(query, limit=80) if query else WORLD_FEATURE_BLUEPRINTS[:80]
    view = XAUWorldFeatureView(ctx, results)
    await ctx.send(embed=view.make_embed(), view=view)

@bot.command(name="worldestado", aliases=["featureestado"])
@commands.cooldown(1, 8, commands.BucketType.user)
async def worldestado(ctx):
    """Show enabled feature blueprints for the current guild."""
    state = await xau_world_load_state()
    gid = str(ctx.guild.id) if ctx.guild else "dm"
    enabled = state.get("guilds", {}).get(gid, {}).get("enabled", [])
    desc = xau_world_summary_text()
    desc += f"\n\nActivados aquí: **{len(enabled)}**\n"
    if enabled:
        desc += "\n".join(f"`{x}`" for x in enabled[:30])
    await ctx.send(embed=xau_world_embed("📡 Estado World Engine", desc[:3900], ctx))

@bot.command(name="worldactivar", aliases=["activarfeature"])
@commands.has_permissions(manage_guild=True)
@commands.cooldown(1, 4, commands.BucketType.user)
async def worldactivar(ctx, *, target: str):
    """Enable a feature blueprint or a whole category for this guild."""
    state = await xau_world_load_state()
    gid = str(ctx.guild.id) if ctx.guild else "dm"
    guild_state = state.setdefault("guilds", {}).setdefault(gid, {"enabled": [], "updated_at": None})
    enabled = set(guild_state.get("enabled", []))
    target_l = target.strip().lower()
    matches = []
    if target_l in xau_world_categories():
        matches = [f["id"] for f in WORLD_FEATURE_BLUEPRINTS if f.get("category") == target_l]
    else:
        matches = [f["id"] for f in WORLD_FEATURE_BLUEPRINTS if f.get("id", "").lower() == target_l]
        if not matches:
            matches = [f["id"] for f in xau_world_find_features(target, limit=25)]
    for fid in matches:
        enabled.add(fid)
    guild_state["enabled"] = sorted(enabled)
    guild_state["updated_at"] = _xau_world_now_iso()
    state.setdefault("history", []).append({"guild_id": gid, "action": "enable", "target": target, "count": len(matches), "at": _xau_world_now_iso()})
    state["history"] = state["history"][-250:]
    await xau_world_save_state(state)
    await ctx.send(embed=xau_world_embed("✅ World Feature activado", f"Objetivo: `{target}`\nAñadidos: **{len(matches)}**\nTotal activo: **{len(enabled)}**", ctx, discord.Color.green()))

@bot.command(name="worlddesactivar", aliases=["desactivarfeature"])
@commands.has_permissions(manage_guild=True)
@commands.cooldown(1, 4, commands.BucketType.user)
async def worlddesactivar(ctx, *, target: str):
    """Disable a feature blueprint or category for this guild."""
    state = await xau_world_load_state()
    gid = str(ctx.guild.id) if ctx.guild else "dm"
    guild_state = state.setdefault("guilds", {}).setdefault(gid, {"enabled": [], "updated_at": None})
    enabled = set(guild_state.get("enabled", []))
    target_l = target.strip().lower()
    if target_l in xau_world_categories():
        remove_ids = {f["id"] for f in WORLD_FEATURE_BLUEPRINTS if f.get("category") == target_l}
    else:
        remove_ids = {target.strip()}
    before = len(enabled)
    enabled -= remove_ids
    guild_state["enabled"] = sorted(enabled)
    guild_state["updated_at"] = _xau_world_now_iso()
    state.setdefault("history", []).append({"guild_id": gid, "action": "disable", "target": target, "count": before-len(enabled), "at": _xau_world_now_iso()})
    state["history"] = state["history"][-250:]
    await xau_world_save_state(state)
    await ctx.send(embed=xau_world_embed("🧹 World Feature desactivado", f"Objetivo: `{target}`\nQuitados: **{before-len(enabled)}**\nTotal activo: **{len(enabled)}**", ctx, discord.Color.orange()))

@bot.command(name="worldpack", aliases=["packworld", "megapack"])
@commands.has_permissions(manage_guild=True)
@commands.cooldown(1, 20, commands.BucketType.guild)
async def worldpack(ctx, pack: str = "community"):
    """Enable curated feature packs without adding thousands of live Discord commands."""
    packs = {
        "community": ["moderation", "automod", "logging", "levels", "welcome", "suggestions", "tickets"],
        "streamer": ["streaming", "timers", "giveaways", "creator", "analytics", "social"],
        "security": ["security", "verification", "automod", "logging", "modmail"],
        "games": ["games", "rpg", "economy", "shop", "social"],
        "ai": ["ai", "utility", "analytics", "server_templates", "voice"],
        "all_safe": xau_world_categories(),
    }
    selected = packs.get(pack.lower())
    if not selected:
        await ctx.send(embed=xau_world_embed("📦 Pack no encontrado", f"Packs: `{', '.join(packs)}`", ctx, discord.Color.orange()))
        return
    state = await xau_world_load_state()
    gid = str(ctx.guild.id) if ctx.guild else "dm"
    guild_state = state.setdefault("guilds", {}).setdefault(gid, {"enabled": [], "updated_at": None})
    enabled = set(guild_state.get("enabled", []))
    ids = [f["id"] for f in WORLD_FEATURE_BLUEPRINTS if f.get("category") in selected]
    enabled.update(ids)
    guild_state["enabled"] = sorted(enabled)
    guild_state["updated_at"] = _xau_world_now_iso()
    state.setdefault("history", []).append({"guild_id": gid, "action": "pack", "target": pack, "count": len(ids), "at": _xau_world_now_iso()})
