# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║ X AETHER ULTRA HOTFIX 3.1.1 · ACHIEVEMENT JSON COMPATIBILITY               ║
# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║ Fixes legacy logros.json entries saved as lists. Older versions stored      ║
# ║ each user as ["logro_id", ...], while the ULTRA tracker expects a dict with ║
# ║ counters/unlocked. This hotfix accepts both formats and migrates safely.     ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

XAU_ACHIEVEMENT_SCHEMA_VERSION = 2


def xau_unique_strings(values):
    """Return a stable unique list of string IDs."""
    out = []
    seen = set()
    if isinstance(values, dict):
        iterable = values.keys()
    elif isinstance(values, (list, tuple, set)):
        iterable = values
    elif values is None:
        iterable = []
    else:
        iterable = [values]
    for value in iterable:
        token = str(value).strip()
        if token and token not in seen:
            out.append(token)
            seen.add(token)
    return out


def xau_normalize_achievement_entry(entry):
    """Normalize one user achievement record without losing legacy data."""
    default = {
        "schema": XAU_ACHIEVEMENT_SCHEMA_VERSION,
        "counters": {},
        "unlocked": [],
        "updated_at": None,
    }

    # Legacy format: "123": ["nivel_10", "millonario"]
    if isinstance(entry, list):
        default["unlocked"] = xau_unique_strings(entry)
        default["legacy_migrated"] = True
        return default

    if not isinstance(entry, dict):
        default["legacy_invalid"] = repr(entry)[:300]
        return default

    counters = entry.get("counters", {})
    if not isinstance(counters, dict):
        counters = {}
    clean_counters = {}
    for key, value in counters.items():
        try:
            clean_counters[str(key)] = int(value)
        except Exception:
            clean_counters[str(key)] = 0

    unlocked = []
    unlocked.extend(xau_unique_strings(entry.get("unlocked", [])))
    unlocked.extend(xau_unique_strings(entry.get("logros", [])))
    unlocked.extend(xau_unique_strings(entry.get("achievements", [])))
    unlocked.extend(xau_unique_strings(entry.get("legacy_unlocked", [])))
    unlocked = xau_unique_strings(unlocked)

    normalized = dict(entry)
    normalized["schema"] = int(normalized.get("schema", XAU_ACHIEVEMENT_SCHEMA_VERSION) or XAU_ACHIEVEMENT_SCHEMA_VERSION)
    normalized["counters"] = clean_counters
    normalized["unlocked"] = unlocked
    normalized.setdefault("updated_at", None)
    return normalized


def xau_achievement_unlocked_ids(entry):
    """Read unlocked IDs from either legacy list or modern dict format."""
    return xau_normalize_achievement_entry(entry).get("unlocked", [])


async def xau_achievement_data():
    """Load achievements from logros.json and normalize legacy list entries."""
    raw = await xau_json_load(LOGROS_FILE, {})
    if not isinstance(raw, dict):
        raw = {}
    normalized = {}
    for uid, entry in raw.items():
        normalized[str(uid)] = xau_normalize_achievement_entry(entry)
    return normalized


async def xau_save_achievement_data(data):
    """Persist normalized achievement data atomically."""
    if not isinstance(data, dict):
        data = {}
    normalized = {str(uid): xau_normalize_achievement_entry(entry) for uid, entry in data.items()}
    await xau_json_save(LOGROS_FILE, normalized)


async def check_achievements(user_id, ctx=None, channel=None):
    """Check and unlock achievements for a user. Compatible with old logros.json."""
    uid = str(user_id)
    logros = await xau_achievement_data()
    entry = xau_normalize_achievement_entry(logros.get(uid, {}))
    logros[uid] = entry
    counters = entry.setdefault("counters", {})
    unlocked = set(xau_unique_strings(entry.setdefault("unlocked", [])))
    newly = []

    for ach_id, ach in XAU_ACHIEVEMENTS.items():
        if ach_id in unlocked:
            continue
        if int(counters.get(ach["counter"], 0) or 0) >= int(ach["target"]):
            unlocked.add(ach_id)
            newly.append((ach_id, ach))
            try:
                await xau_change_cash(int(user_id), int(ach.get("reward", 0) or 0))
            except Exception as exc:
                print(f"[{BOT_NAME}] achievement reward warning: {exc!r}")

    entry["unlocked"] = sorted(unlocked)
    entry["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    await xau_save_achievement_data(logros)

    dest = channel or getattr(ctx, "channel", None)
    if dest:
        for ach_id, ach in newly:
            embed = xaether_embed(
                f"🏆 LOGRO DESBLOQUEADO · {ach['emoji']} {ach['name']}",
                f"```ansi\n\u001b[35m◆◆◆ X AETHER ULTRA ACHIEVEMENT ◆◆◆\u001b[0m\n```\n"
                f"{ach['desc']}\n\nRecompensa: **{xau_money(ach.get('reward', 0))}** amatistas\n"
                f"{xau_bar(1, 1, 18, '◆', '◇')}",
                discord.Color.gold(),
                getattr(ctx, "author", None),
            )
            await xau_safe_send(dest, embed=embed)
    return newly


async def xau_increment_achievement(user_id: int, counter: str, amount: int = 1, ctx=None, channel=None):
    """Increment one achievement counter safely, even if logros.json used legacy lists."""
    uid = str(user_id)
    logros = await xau_achievement_data()
    entry = xau_normalize_achievement_entry(logros.get(uid, {}))
    counters = entry.setdefault("counters", {})
    counters[str(counter)] = int(counters.get(str(counter), 0) or 0) + int(amount or 1)
    entry["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    logros[uid] = entry
    await xau_save_achievement_data(logros)
    return await check_achievements(user_id, ctx=ctx, channel=channel)


async def otorgar_logro(uid: str, logro_id: str) -> bool:
    """Grant legacy achievements while preserving the new counters/unlocked schema."""
    uid = str(uid)
    logros_data = await xau_achievement_data()
    entry = xau_normalize_achievement_entry(logros_data.get(uid, {}))
    unlocked = set(xau_unique_strings(entry.get("unlocked", [])))
    if logro_id in unlocked:
        return False
    unlocked.add(str(logro_id))
    entry["unlocked"] = sorted(unlocked)
    entry["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    logros_data[uid] = entry
    await xau_save_achievement_data(logros_data)

    try:
        datos = cargar_datos()
        asegurar_usuario(datos, uid)
        recompensa = int(LOGROS_DISPONIBLES.get(logro_id, {}).get("recompensa", 0) or 0)
        if recompensa:
            agregar_a_cash_y_monedas(datos, uid, recompensa)
            guardar_datos(datos)
    except Exception as exc:
        print(f"[{BOT_NAME}] legacy achievement reward warning: {exc!r}")
    return True


