@bot.command(name="logros", aliases=["logro", "achievements", "ach", "trofeos"])
@commands.cooldown(1, 5, commands.BucketType.user)
async def logros_cmd(ctx, miembro: discord.Member = None):
    """Show unlocked achievements from legacy and ULTRA trackers."""
    miembro = miembro or ctx.author
    uid = str(miembro.id)
    logros_data = await xau_achievement_data()
    entry = xau_normalize_achievement_entry(logros_data.get(uid, {}))
    obtenidos = set(xau_unique_strings(entry.get("unlocked", [])))
    counters = entry.get("counters", {}) if isinstance(entry.get("counters", {}), dict) else {}

    legacy_defs = globals().get("LOGROS_DISPONIBLES", {}) if isinstance(globals().get("LOGROS_DISPONIBLES", {}), dict) else {}
    ultra_defs = globals().get("XAU_ACHIEVEMENTS", {}) if isinstance(globals().get("XAU_ACHIEVEMENTS", {}), dict) else {}
    total_disp = len(legacy_defs) + len(ultra_defs)
    total_obt = len([lid for lid in obtenidos if lid in legacy_defs or lid in ultra_defs])
    pct = total_obt / max(total_disp, 1)
    barras = 14
    filled = min(int(pct * barras), barras)
    barra_total = "█" * filled + "░" * (barras - filled)

    color = discord.Color.gold() if pct >= 1 else discord.Color.purple() if pct > 0 else discord.Color.dark_gray()
    embed = xaether_embed(
        f"🏆 Logros ULTRA · {miembro.display_name}",
        f"**Progreso:** `[{barra_total}]` {total_obt}/{total_disp}\n"
        f"**Contadores:** casino `{counters.get('casino',0)}` · tienda `{counters.get('tienda',0)}` · rep `{counters.get('rep',0)}` · crimen `{counters.get('crimen',0)}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        color,
        miembro,
    )

    shown = 0
    for lid, linfo in legacy_defs.items():
        if shown >= 12:
            break
        desbloqueado = lid in obtenidos
        icono = "✅" if desbloqueado else "🔒"
        reward = linfo.get("recompensa", 0)
        embed.add_field(
            name=f"{icono} {linfo.get('nombre', lid)}",
            value=f"*{linfo.get('desc', 'Logro del sistema clásico.')}*\n"
                  f"{'**Desbloqueado**' if desbloqueado else '*Bloqueado*'} · Recompensa: **{reward:,}** {globals().get('amatista','💎')}",
            inline=False,
        )
        shown += 1

    for lid, linfo in ultra_defs.items():
        if shown >= 20:
            break
        desbloqueado = lid in obtenidos
        counter = linfo.get("counter", "?")
        current = int(counters.get(counter, 0) or 0)
        target = int(linfo.get("target", 1) or 1)
        icono = "✅" if desbloqueado else "🔒"
        embed.add_field(
            name=f"{icono} {linfo.get('emoji','🏆')} {linfo.get('name', lid)}",
            value=f"*{linfo.get('desc', 'Logro ULTRA.')}*\n"
                  f"Progreso: `{xau_bar(current, target, 10)}` {min(current,target)}/{target} · Recompensa: **{linfo.get('reward',0):,}** 💎",
            inline=False,
        )
        shown += 1

    try:
        embed.set_thumbnail(url=miembro.display_avatar.url)
    except Exception:
        pass
    embed.set_footer(text=f"X AETHER ULTRA · logros.json compatible legacy/list + counters/dict · {BOT_VERSION}")
    await ctx.send(embed=embed)


