class XAUMinesView(XAUOwnerView):
    def __init__(self, ctx, bet, showcase=False):
        super().__init__(ctx, timeout=120)
        self.bet = bet; self.showcase = showcase; self.stats = {}; self.revealed = set(); self.dead = False
        self.mines = set(random.sample(range(9), 2))
        for idx in range(9):
            self.add_item(XAUMineButton(idx))
        self.add_item(XAUMinesCashout())

    @property
    def mult(self):
        return 1 + len(self.revealed) * 0.55

    def render(self, phase="Busca gemas, evita minas", color=XAU_GAME_COLOR_IDLE):
        cells = []
        for i in range(9):
            if i in self.revealed: cells.append("💎")
            else: cells.append("⬛")
        grid = f"{cells[0]} {cells[1]} {cells[2]}\n{cells[3]} {cells[4]} {cells[5]}\n{cells[6]} {cells[7]} {cells[8]}"
        desc = f"`{phase}`\n\n{grid}\n\nMultiplicador actual: **x{self.mult:.2f}** · Cashout: **{int(self.bet*self.mult):,}**\n{xauig_stats_line(self.stats, self.bet)}"
        return xauig_embed("⛏️ Minas interactivas ULTRA", desc, color, self.ctx.author)

    async def reveal(self, interaction, idx):
        if idx in self.revealed:
            await interaction.response.send_message("Casilla ya revelada.", ephemeral=True); return
        if idx in self.mines:
            self.dead = True; self.disable_all()
            stats, net = await xauig_pay(self.ctx, 0, "minas", self.bet, "mina")
            embed = self.render("💥 Mina encontrada", XAU_GAME_COLOR_LOSS)
            embed.description += f"\n\nNeto **{net:+,}**"
            await self.safe_edit(interaction, embed, XAUReplayView(f"!minas {self.bet}")); return
        self.revealed.add(idx)
        if len(self.revealed) >= 7:
            await self.cashout(interaction)
            return
        await self.safe_edit(interaction, self.render("Gema encontrada. ¿Sigues o cobras?", XAU_GAME_COLOR_INFO))

    async def cashout(self, interaction):
        payout = int(self.bet * self.mult)
        stats, net = await xauig_pay(self.ctx, payout, "minas", self.bet, "cashout")
        self.disable_all()
        embed = self.render("💰 Cashout correcto", XAU_GAME_COLOR_WIN)
        embed.description += f"\n\nPayout **{payout:,}** · Neto **{net:+,}**"
        await self.safe_edit(interaction, embed, XAUReplayView(f"!minas {self.bet}"))


