class XAUCrashView(XAUOwnerView):
    def __init__(self, ctx, bet, showcase=False):
        super().__init__(ctx, timeout=90)
        self.bet = bet; self.showcase = showcase; self.stats = {}; self.mult = 1.0; self.crashed = False; self.running = False; self.cashed = False
        self.crash_at = random.uniform(1.25, 7.5)

    def render(self, phase="Preparado", color=XAU_GAME_COLOR_IDLE):
        desc = f"`{phase}`\n\n🚀 Multiplicador: **x{self.mult:.2f}**\nMotor: `{xauig_bar(self.mult, max(self.crash_at, 2), 18)}`\nCashout ahora: **{int(self.bet*self.mult):,}**\n{xauig_stats_line(self.stats, self.bet)}"
        return xauig_embed("🚀 Crash interactivo ULTRA", desc, color, self.ctx.author)

    @discord.ui.button(label="Iniciar", emoji="🚀", style=discord.ButtonStyle.green)
    async def start(self, interaction, button):
        if self.running:
            await interaction.response.send_message("Ya está volando.", ephemeral=True); return
        self.running = True; button.disabled = True
        await interaction.response.defer()
        while not self.cashed and self.mult < self.crash_at:
            self.mult += random.uniform(0.10, 0.38)
            await interaction.message.edit(embed=self.render("Subiendo... pulsa cashout antes del crash", discord.Color.gold()), view=self)
            await asyncio.sleep(0.55)
        if not self.cashed:
            self.crashed = True; self.disable_all()
            stats, net = await xauig_pay(self.ctx, 0, "crash", self.bet, "crash")
            await interaction.message.edit(embed=self.render(f"💥 CRASH en x{self.crash_at:.2f} · Neto {net:+,}", XAU_GAME_COLOR_LOSS), view=XAUReplayView(f"!crash {self.bet}"))

    @discord.ui.button(label="Cashout", emoji="💰", style=discord.ButtonStyle.blurple)
    async def cashout(self, interaction, button):
        if not self.running:
            await interaction.response.send_message("Primero inicia el cohete.", ephemeral=True); return
        if self.crashed or self.cashed:
            return
        self.cashed = True
        payout = int(self.bet * self.mult)
        stats, net = await xauig_pay(self.ctx, payout, "crash", self.bet, "cashout")
        self.disable_all()
        await self.safe_edit(interaction, self.render(f"Cashout en x{self.mult:.2f} · Neto {net:+,}", XAU_GAME_COLOR_WIN), XAUReplayView(f"!crash {self.bet}"))


class XAUChestView(XAUOwnerView):
    def __init__(self, ctx, bet, showcase=False):
        super().__init__(ctx, timeout=80)
        self.bet=bet; self.showcase=showcase; self.stats={}
        self.prizes=[0, int(bet*0.5), bet, bet*2, bet*5]
        random.shuffle(self.prizes)
        for i in range(5): self.add_item(XAUChestButton(i))
