class XAUTreasureView(XAUOwnerView):
    def __init__(self, ctx, bet, showcase=False):
        super().__init__(ctx, timeout=100)
        self.bet=bet; self.showcase=showcase; self.stats={}; self.step=0; self.mult=1.0; self.path=[]
    def render(self, phase="Elige ruta", color=XAU_GAME_COLOR_IDLE):
        return xauig_embed("🗺️ Tesoro por decisiones ULTRA", f"`{phase}`\n\nRuta: {' → '.join(self.path) if self.path else 'inicio'}\nPaso **{self.step}/4** · Multiplicador **x{self.mult:.2f}** · Tesoro actual **{int(self.bet*self.mult):,}**\n{xauig_stats_line(self.stats,self.bet)}", color, self.ctx.author)
    async def choose(self, interaction, route):
        self.path.append(route); self.step += 1
        risk = {"selva":0.25,"cueva":0.35,"templo":0.45}.get(route,0.3)
        reward = {"selva":0.45,"cueva":0.75,"templo":1.15}.get(route,0.5)
        if random.random() < risk:
            self.disable_all(); stats, net = await xauig_pay(self.ctx,0,"tesoro",self.bet,"trampa")
            await self.safe_edit(interaction,self.render("☠️ Trampa activada",XAU_GAME_COLOR_LOSS),XAUReplayView(f"!tesoro {self.bet}")); return
        self.mult += reward
        if self.step >= 4:
            payout=int(self.bet*self.mult); stats,net=await xauig_pay(self.ctx,payout,"tesoro",self.bet,"tesoro")
            self.disable_all(); await self.safe_edit(interaction,self.render(f"🏆 Tesoro encontrado · Neto {net:+,}",XAU_GAME_COLOR_WIN),XAUReplayView(f"!tesoro {self.bet}")); return
        await self.safe_edit(interaction,self.render("Avanzas. Elige siguiente ruta",XAU_GAME_COLOR_INFO))
    @discord.ui.button(label="Selva segura",emoji="🌿",style=discord.ButtonStyle.green)
    async def jungle(self,i,b): await self.choose(i,"selva")
    @discord.ui.button(label="Cueva media",emoji="🕳️",style=discord.ButtonStyle.blurple)
    async def cave(self,i,b): await self.choose(i,"cueva")
    @discord.ui.button(label="Templo riesgo",emoji="🏛️",style=discord.ButtonStyle.red)
    async def temple(self,i,b): await self.choose(i,"templo")
    @discord.ui.button(label="Cobrar",emoji="💰",style=discord.ButtonStyle.gray,row=1)
    async def cash(self,i,b):
        payout=int(self.bet*self.mult); stats,net=await xauig_pay(self.ctx,payout,"tesoro",self.bet,"cashout")
        self.disable_all(); await self.safe_edit(i,self.render(f"💰 Retirada sabia · Neto {net:+,}",XAU_GAME_COLOR_WIN if net>0 else XAU_GAME_COLOR_INFO),XAUReplayView(f"!tesoro {self.bet}"))


class XAURaceView(XAUOwnerView):
    def __init__(self,ctx,bet,showcase=False):
        super().__init__(ctx,timeout=90); self.bet=bet; self.showcase=showcase; self.stats={}; self.choice=None; self.boost="normal"
    def render(self,phase="Elige coche y estrategia",color=XAU_GAME_COLOR_IDLE):
        return xauig_embed("🏁 Carrera interactiva ULTRA",f"`{phase}`\n\nCoche: **{self.choice or 'sin elegir'}** · Estrategia: **{self.boost}**\n{xauig_stats_line(self.stats,self.bet)}\n\nTurbo arriesga motor. Control reduce velocidad pero evita choques.",color,self.ctx.author)
    async def pick(self,i,car): self.choice=car; await self.safe_edit(i,self.render(f"Coche elegido: {car}",XAU_GAME_COLOR_INFO))
    @discord.ui.button(label="Fénix",emoji="🦅",style=discord.ButtonStyle.red)
    async def car1(self,i,b): await self.pick(i,"Fénix")
    @discord.ui.button(label="Neón",emoji="💜",style=discord.ButtonStyle.blurple)
    async def car2(self,i,b): await self.pick(i,"Neón")
    @discord.ui.button(label="Obsidiana",emoji="🖤",style=discord.ButtonStyle.gray)
    async def car3(self,i,b): await self.pick(i,"Obsidiana")
    @discord.ui.button(label="Turbo",emoji="⚡",style=discord.ButtonStyle.green,row=1)
    async def turbo(self,i,b): self.boost="turbo"; await self.safe_edit(i,self.render("Turbo preparado",discord.Color.gold()))
    @discord.ui.button(label="Control",emoji="🛡️",style=discord.ButtonStyle.blurple,row=1)
    async def control(self,i,b): self.boost="control"; await self.safe_edit(i,self.render("Conducción segura",XAU_GAME_COLOR_INFO))
    @discord.ui.button(label="Correr",emoji="🏁",style=discord.ButtonStyle.green,row=1)
    async def run(self,i,b):
        if not self.choice: await i.response.send_message("Elige coche primero.",ephemeral=True); return
        await i.response.defer(); pos=0
        crash_chance=0.25 if self.boost=="turbo" else 0.08 if self.boost=="control" else 0.14
        speed=22 if self.boost=="turbo" else 12 if self.boost=="control" else 16
        for t in range(5):
            if random.random()<crash_chance:
                self.disable_all(); stats,net=await xauig_pay(self.ctx,0,"carrera",self.bet,"choque")
                await i.message.edit(embed=self.render(f"💥 Choque en curva · Neto {net:+,}",XAU_GAME_COLOR_LOSS),view=XAUReplayView(f"!carrera {self.bet}")); return
            pos += random.randint(speed-5,speed+8)
            await i.message.edit(embed=self.render(f"🏎️ Progreso `{xauig_bar(pos,100,20)}` {min(pos,100)}%",discord.Color.gold()),view=self); await asyncio.sleep(0.45)
        win=pos>=75; payout=self.bet*(3 if self.boost=="turbo" and win else 2 if win else 0); stats,net=await xauig_pay(self.ctx,payout,"carrera",self.bet,"meta")
        self.disable_all(); await i.message.edit(embed=self.render(f"🏁 {'Victoria' if win else 'Derrota'} · Neto {net:+,}",XAU_GAME_COLOR_WIN if win else XAU_GAME_COLOR_LOSS),view=XAUReplayView(f"!carrera {self.bet}"))


class XAUMemoryView(XAUOwnerView):
    def __init__(self,ctx,bet=0,showcase=False):
        super().__init__(ctx,timeout=100); self.bet=bet; self.showcase=showcase; self.seq=[random.choice(XAU_MEMORY_ICONS) for _ in range(4)]; self.input=[]; self.hidden=False; self.stats={}
        for icon in XAU_MEMORY_ICONS[:4]: self.add_item(XAUMemoryButton(icon))
    def render(self,phase="Memoriza la secuencia",color=XAU_GAME_COLOR_IDLE):
        shown=" ".join(["❔"]*len(self.seq)) if self.hidden else " ".join(self.seq)
        return xauig_embed("🧠 Memoria interactiva ULTRA",f"`{phase}`\n\nSecuencia: **{shown}**\nTu input: **{' '.join(self.input) or 'vacío'}**\n{xauig_stats_line(self.stats,self.bet)}",color,self.ctx.author)
    async def start_hide(self,msg):
        await asyncio.sleep(3); self.hidden=True
        try: await msg.edit(embed=self.render("Repite la secuencia",XAU_GAME_COLOR_INFO),view=self)
        except Exception: pass
    async def press(self,i,icon):
        if not self.hidden: await i.response.send_message("Espera a que se oculte la secuencia.",ephemeral=True); return
        self.input.append(icon)
        if self.input != self.seq[:len(self.input)]:
            self.disable_all(); stats,net=await xauig_pay(self.ctx,0,"memoria_juego",self.bet,"fallo memoria")
            await self.safe_edit(i,self.render(f"❌ Fallaste · Neto {net:+,}",XAU_GAME_COLOR_LOSS),XAUReplayView("!memoria_juego")); return
        if len(self.input)==len(self.seq):
            payout=max(0,self.bet*3); stats,net=await xauig_pay(self.ctx,payout,"memoria_juego",self.bet,"memoria perfecta")
            self.disable_all(); await self.safe_edit(i,self.render(f"✅ Perfecto · Neto {net:+,}",XAU_GAME_COLOR_WIN),XAUReplayView("!memoria_juego")); return
        await self.safe_edit(i,self.render("Bien, sigue",discord.Color.gold()))
class XAUMemoryButton(discord.ui.Button):
    def __init__(self,icon): super().__init__(label=icon,style=discord.ButtonStyle.gray); self.icon=icon
    async def callback(self,interaction): await self.view.press(interaction,self.icon)


class XAUGuessModal(Modal, title="Adivina el número"):
    guess = TextInput(label="Número", placeholder="1-100", required=True, max_length=3)
    def __init__(self, view): super().__init__(); self.game_view=view
    async def on_submit(self, interaction): await self.game_view.submit_guess(interaction, str(self.guess))


class XAUGuessView(XAUOwnerView):
    def __init__(self,ctx,bet=0,showcase=False):
        super().__init__(ctx,timeout=120); self.bet=bet; self.showcase=showcase; self.target=random.randint(1,100); self.tries=0; self.stats={}; self.low=1; self.high=100
    def render(self,phase="Adivina usando pistas",color=XAU_GAME_COLOR_IDLE):
        return xauig_embed("🔢 Adivina interactivo ULTRA",f"`{phase}`\n\nRango: **{self.low}-{self.high}** · Intentos: **{self.tries}/7**\n{xauig_stats_line(self.stats,self.bet)}",color,self.ctx.author)
    @discord.ui.button(label="Adivinar",emoji="🎯",style=discord.ButtonStyle.green)
    async def guess_btn(self,i,b): await i.response.send_modal(XAUGuessModal(self))
    async def submit_guess(self,i,value):
        n=xauig_parse_positive_int(value,1,1,100); self.tries+=1
        if n==self.target:
            payout=self.bet*max(2,8-self.tries); stats,net=await xauig_pay(self.ctx,payout,"adivina",self.bet,"acierto")
            self.disable_all(); await self.safe_edit(i,self.render(f"🎯 Acertaste {self.target} · Neto {net:+,}",XAU_GAME_COLOR_WIN),XAUReplayView(f"!adivina {self.bet}")); return
        if n<self.target: self.low=max(self.low,n+1); hint="más alto"
        else: self.high=min(self.high,n-1); hint="más bajo"
        if self.tries>=7:
            stats,net=await xauig_pay(self.ctx,0,"adivina",self.bet,"fallo")
            self.disable_all(); await self.safe_edit(i,self.render(f"❌ Era {self.target} · Neto {net:+,}",XAU_GAME_COLOR_LOSS),XAUReplayView(f"!adivina {self.bet}")); return
        await self.safe_edit(i,self.render(f"Pista: {hint}",XAU_GAME_COLOR_INFO))


class XAUHangmanModal(Modal, title="Ahorcado"):
    letter = TextInput(label="Letra o palabra", required=True, max_length=20)
    def __init__(self, view): super().__init__(); self.game_view=view
    async def on_submit(self, interaction): await self.game_view.submit(interaction, str(self.letter).lower().strip())


class XAUHangmanView(XAUOwnerView):
    def __init__(self,ctx,bet=0,showcase=False):
        super().__init__(ctx,timeout=180); self.bet=bet; self.showcase=showcase; self.words=["aether","rocket","amatista","freestyle","discord","ouroboros","neon"] ; self.word=random.choice(self.words); self.used=set(); self.fails=0; self.stats={}
    def masked(self): return " ".join([c if c in self.used else "_" for c in self.word])
    def render(self,phase="Propón letras",color=XAU_GAME_COLOR_IDLE):
        return xauig_embed("🪢 Ahorcado interactivo ULTRA",f"`{phase}`\n\nPalabra: **{self.masked()}**\nUsadas: `{', '.join(sorted(self.used)) or 'ninguna'}`\nFallos: **{self.fails}/6**\n{xauig_stats_line(self.stats,self.bet)}",color,self.ctx.author)
    @discord.ui.button(label="Letra/Palabra",emoji="🔤",style=discord.ButtonStyle.green)
    async def letter_btn(self,i,b): await i.response.send_modal(XAUHangmanModal(self))
    async def submit(self,i,value):
        if not value: return
        if value==self.word or (len(value)==1 and value in self.word):
            for c in value if len(value)>1 else [value]: self.used.add(c)
            if all(c in self.used for c in self.word) or value==self.word:
                payout=self.bet*3 if self.bet else 0; stats,net=await xauig_pay(self.ctx,payout,"ahorcado",self.bet,"palabra")
                self.disable_all(); await self.safe_edit(i,self.render(f"✅ Resuelto: {self.word} · Neto {net:+,}",XAU_GAME_COLOR_WIN),XAUReplayView(f"!ahorcado {self.bet}")); return
            await self.safe_edit(i,self.render("Correcto",discord.Color.gold())); return
        self.used.add(value[:1]); self.fails+=1
        if self.fails>=6:
            stats,net=await xauig_pay(self.ctx,0,"ahorcado",self.bet,"ahorcado")
            self.disable_all(); await self.safe_edit(i,self.render(f"❌ Era {self.word} · Neto {net:+,}",XAU_GAME_COLOR_LOSS),XAUReplayView(f"!ahorcado {self.bet}")); return
        await self.safe_edit(i,self.render("Fallaste, piensa mejor",XAU_GAME_COLOR_INFO))


def xauig_rps_resolver(choice, bet):
    botc=random.choice(list(XAU_RPS.keys()))
    win=(choice,botc) in {("piedra","tijera"),("papel","piedra"),("tijera","papel")}
    tie=choice==botc
    payout=bet if tie else bet*2 if win else 0
    return f"Tú {XAU_RPS.get(choice)} **{choice}** vs X AETHER {XAU_RPS.get(botc)} **{botc}**", payout, win or tie

def xauig_coin_resolver(choice, bet):
    result=random.choice(["cara","cruz"]); win=choice==result; return f"Moneda: **{result}** · Elegiste **{choice}**", bet*2 if win else 0, win

def xauig_dice_resolver(choice, bet):
    d1=random.randint(1,6); d2=random.randint(1,6); total=d1+d2
    win=(choice=="alto" and total>=8) or (choice=="bajo" and total<=6) or (choice=="siete" and total==7)
    mult=4 if choice=="siete" else 2
    return f"🎲 {d1}+{d2}=**{total}** · Elegiste **{choice}**", bet*mult if win else 0, win

def xauig_shot_resolver(choice, bet):
    zones={"izquierda":0.42,"centro":0.34,"derecha":0.42,"vaselina":0.24}; win=random.random()<zones.get(choice,0.35); mult=4 if choice=="vaselina" else 2
    return f"Tiro a **{choice}** · {'GOLAZO' if win else 'parada del portero'}", bet*mult if win else 0, win

def xauig_russian_resolver(choice, bet):
    if choice=="escudo": chance=0.08; mult=1
    elif choice=="disparar": chance=0.18; mult=3
    else: chance=0.28; mult=2
    alive=random.random()>chance
    return f"Decisión **{choice}** · {'sigues vivo' if alive else 'click final'}", bet*mult if alive else 0, alive


async def xauig_launch(ctx, amount, view_cls, game_key, title):
    bet, showcase, datos = await xauig_parse_bet(ctx, amount)
    if bet is None:
        await ctx.send(embed=xauig_embed("💸 Cash insuficiente", "No tienes amatistas suficientes para esa apuesta.", XAU_GAME_COLOR_LOSS, ctx.author)); return
    ok = await xauig_lock_bet(ctx, bet, datos)
    if not ok:
        await ctx.send(embed=xauig_embed("💸 Cash insuficiente", "Tu saldo cambió antes de bloquear la apuesta.", XAU_GAME_COLOR_LOSS, ctx.author)); return
    view = view_cls(ctx, bet, showcase)
    try:
        view.stats = await xauig_get_stats(ctx, game_key)
    except Exception:
        view.stats = {}
    msg = await ctx.send(embed=view.render("Showcase sin apuesta" if showcase else "Mesa abierta", XAU_GAME_COLOR_INFO), view=view)
    view.message = msg
    if isinstance(view, XAUMemoryView):
        asyncio.create_task(view.start_hide(msg))


