def xau330_guide_for(game_key: str) -> dict:
    return XAU330_GUIDES.get(str(game_key or "").lower(), {
        "title": "🎮 Minijuego",
        "rules": "Lee el panel de la partida y toma decisiones con los botones disponibles.",
        "controls": "Usa los botones de la mesa. Solo el jugador que abrió la partida puede pulsarlos.",
        "tip": "Piensa antes de pulsar: el objetivo es que tu decisión cambie el resultado.",
    })


def xau330_trim(text: str, limit: int = 1010) -> str:
    text = str(text or "")
    return text if len(text) <= limit else text[: limit - 1] + "…"


def xau330_card_lines(card: str) -> list:
    card = str(card or "🂠")
    if card == "🂠" or len(card) < 2:
        return [
            "┌───────┐",
            "│░░░░░░░│",
            "│░ XAU ░│",
            "│░  ◆  ░│",
            "│░░░░░░░│",
            "└───────┘",
        ]
    rank = card[:-1]
    suit = card[-1]
    r1 = rank.ljust(2)[:2]
    r2 = rank.rjust(2)[-2:]
    return [
        "┌───────┐",
        f"│{r1}     │",
        f"│   {suit}   │",
        f"│  {suit}{suit}{suit}  │",
        f"│     {r2}│",
        "└───────┘",
    ]


def xau330_render_cards(cards, hidden_indexes=None, max_cards=7) -> str:
    hidden_indexes = set(hidden_indexes or [])
    cards = list(cards or [])[:max_cards]
    if not cards:
        return "`sin cartas`"
    blocks = []
    for idx, card in enumerate(cards):
        blocks.append(xau330_card_lines("🂠" if idx in hidden_indexes else card))
    rows = ["  ".join(parts) for parts in zip(*blocks)]
    return "```text\n" + "\n".join(rows) + "\n```"


def xau330_slots_panel(reels, held=None) -> str:
    held = held or [False, False, False]
    top = "  ".join(["╔═══════╗"] * 3)
    mid = "  ".join([f"║  {str(symbol).center(3)}  ║" for symbol in reels])
    bot = "  ".join(["╚═══════╝"] * 3)
    lock = "  ".join(["   🔒   " if flag else "   🔓   " for flag in held])
    return f"```text\n{top}\n{mid}\n{bot}\n{lock}\n```"


def xau330_grid_3x3(cells) -> str:
    cells = list(cells or ["⬛"] * 9)
    return "```text\n┌────┬────┬────┐\n" + \
        f"│ {cells[0]} │ {cells[1]} │ {cells[2]} │\n├────┼────┼────┤\n" + \
        f"│ {cells[3]} │ {cells[4]} │ {cells[5]} │\n├────┼────┼────┤\n" + \
        f"│ {cells[6]} │ {cells[7]} │ {cells[8]} │\n└────┴────┴────┘\n```"


def xau330_add_guide(embed: discord.Embed, game_key: str):
    guide = xau330_guide_for(game_key)
    try:
        embed.add_field(name="📜 Reglas rápidas", value=xau330_trim(guide["rules"]), inline=False)
        embed.add_field(name="🎮 Controles", value=xau330_trim(guide["controls"]), inline=False)
        embed.add_field(name="💡 Consejo táctico", value=xau330_trim(guide["tip"]), inline=False)
        embed.set_footer(text=f"X AETHER ULTRA · Casino Realista ES {XAU_CASINO_VISUAL_VERSION}")
    except Exception:
        pass
    return embed


def xau330_make_embed(title, description, color, user, game_key):
    embed = xauig_embed(title, description, color, user)
    return xau330_add_guide(embed, game_key)


def xau330_view_game_key(view) -> str:
    if hasattr(view, "game_key"):
        return str(getattr(view, "game_key"))
    mapping = {
        "XAUSlotsView": "slots",
        "XAUBlackjackView": "blackjack",
        "XAUPokerView": "poker",
        "XAURouletteView": "ruleta",
        "XAUMinesView": "minas",
        "XAUCrashView": "crash",
        "XAUChestView": "cofre",
        "XAUTreasureView": "tesoro",
        "XAURaceView": "carrera",
        "XAUMemoryView": "memoria_juego",
        "XAUGuessView": "adivina",
        "XAUHangmanView": "ahorcado",
    }
    return mapping.get(type(view).__name__, getattr(view, "xau330_game_key", "minijuego"))


class XAU330RulesButton(discord.ui.Button):
    def __init__(self, game_key: str):
        guide = xau330_guide_for(game_key)
        super().__init__(label="Reglas", emoji="📜", style=discord.ButtonStyle.gray, row=4)
        self.game_key = game_key
        self._guide_title = guide.get("title", "Minijuego")

    async def callback(self, interaction: discord.Interaction):
        guide = xau330_guide_for(self.game_key)
        embed = xauig_embed(
            f"📜 Guía · {guide['title']}",
            f"**Reglas**\n{guide['rules']}\n\n**Controles**\n{guide['controls']}\n\n**Consejo táctico**\n{guide['tip']}",
            XAU_GAME_COLOR_INFO,
            interaction.user,
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)


def xau330_install_rules_button(cls, game_key: str):
    old_init = cls.__init__
    if getattr(old_init, "_xau330_wrapped", False):
        return

    def wrapped(self, *args, **kwargs):
        old_init(self, *args, **kwargs)
        real_key = str(getattr(self, "game_key", game_key) or game_key)
        self.xau330_game_key = real_key
        try:
            if not any(isinstance(child, XAU330RulesButton) for child in self.children):
                self.add_item(XAU330RulesButton(real_key))
        except Exception:
            pass

    wrapped._xau330_wrapped = True
    cls.__init__ = wrapped


def xau330_render_slots(self, phase="Preparación", color=XAU_GAME_COLOR_IDLE):
    desc = (
        f"**{phase}**\n\n"
        f"{xau330_slots_panel(self.reels, self.held)}"
        f"🔁 Giros restantes: **{self.spins_left}**\n"
        f"📊 {xauig_stats_line(self.stats, self.bet)}\n\n"
        f"**Lectura de mesa:** {' · '.join(['bloqueado' if h else 'libre' for h in self.held])}\n"
        f"Aquí decides qué rodillos conservar. Es una tragaperras táctica, no un botón sin alma."
    )
    return xau330_make_embed("🎰 Slots tácticos · Mesa Realista", desc, color, self.ctx.author, "slots")


def xau330_render_blackjack(self, reveal=False, phase="Tu decisión", color=XAU_GAME_COLOR_IDLE):
    pv = xauig_blackjack_value(self.player)
    dv = xauig_blackjack_value(self.dealer) if reveal else xauig_blackjack_value([self.dealer[0]])
    hidden = set() if reveal else {1}
    desc = (
        f"**{phase}**\n\n"
        f"### 🧑 Tu mano · valor **{pv}**\n{xau330_render_cards(self.player)}"
        f"### 🏦 Dealer · valor **{dv if reveal else str(dv) + '+'}**\n{xau330_render_cards(self.dealer, hidden_indexes=hidden)}"
        f"Riesgo de pasarte: `{xauig_bar(pv, 21, 18)}`\n"
        f"📊 {xauig_stats_line(self.stats, self.bet)}\n\n"
        f"**Decisión:** pide si necesitas mejorar, plántate si tu mano ya aguanta, dobla si tienes ventaja clara."
    )
    return xau330_make_embed("🃏 Blackjack · Cartas grandes", desc, color, self.ctx.author, "blackjack")


