class XAU340RouletteView(XAUOwnerView):
    def __init__(self, ctx, bet, showcase=False):
        super().__init__(ctx, timeout=120)
        self.bet = bet
        self.showcase = showcase
        self.choice = None
        self.stats = {}
        self.add_item(XAU340RulesButton("ruleta"))

    def render(self, phase="Selecciona apuesta", color=XAU_GAME_COLOR_IDLE, focus=0):
        board = (
            "```ansi\n"
            "🟢  0\n"
            "🔴  1   ⚫  2   🔴  3    │ Columna 1/2/3\n"
            "⚫  4   🔴  5   ⚫  6    │ Docenas: 1-12 · 13-24 · 25-36\n"
            "... mesa europea 0-36 ...\n"
            "```"
        )
        desc = (
            f"`{phase}`\n\n"
            f"**Apuesta seleccionada:** `{self.choice or 'ninguna'}`\n"
            f"**Cilindro:** {xau340_wheel_window(focus)}\n"
            f"{board}\n"
            f"{xauig_stats_line(self.stats, self.bet)}\n\n"
            f"Pagos: pleno 35:1 · docena/columna 2:1 · rojo/negro/par/impar/alto/bajo 1:1."
        )
        return xauig_embed("🎡 Ruleta europea cinematográfica", desc, color, self.ctx.author)

    async def choose(self, interaction, choice):
        self.choice = choice
        await self.safe_edit(interaction, self.render(f"Apuesta elegida: {choice}", XAU_GAME_COLOR_INFO))

    @discord.ui.button(label="Rojo", emoji="🔴", style=discord.ButtonStyle.red, row=0)
    async def red(self, i, b): await self.choose(i, "rojo")
    @discord.ui.button(label="Negro", emoji="⚫", style=discord.ButtonStyle.gray, row=0)
    async def black(self, i, b): await self.choose(i, "negro")
    @discord.ui.button(label="Par", emoji="2️⃣", style=discord.ButtonStyle.blurple, row=0)
    async def even(self, i, b): await self.choose(i, "par")
    @discord.ui.button(label="Impar", emoji="1️⃣", style=discord.ButtonStyle.blurple, row=0)
    async def odd(self, i, b): await self.choose(i, "impar")
    @discord.ui.button(label="1-18", emoji="⬇️", style=discord.ButtonStyle.green, row=1)
    async def low(self, i, b): await self.choose(i, "bajo")
    @discord.ui.button(label="19-36", emoji="⬆️", style=discord.ButtonStyle.green, row=1)
    async def high(self, i, b): await self.choose(i, "alto")
    @discord.ui.button(label="Docena", emoji="📊", style=discord.ButtonStyle.blurple, row=1)
    async def dozen(self, i, b):
        order = ["1-12", "13-24", "25-36"]
        current = order.index(self.choice) if self.choice in order else -1
        await self.choose(i, order[(current + 1) % 3])
    @discord.ui.button(label="Columna", emoji="🧱", style=discord.ButtonStyle.blurple, row=1)
    async def column(self, i, b):
        order = ["columna 1", "columna 2", "columna 3"]
        current = order.index(self.choice) if self.choice in order else -1
        await self.choose(i, order[(current + 1) % 3])
    @discord.ui.button(label="Pleno", emoji="🎯", style=discord.ButtonStyle.red, row=2)
    async def straight(self, i, b): await i.response.send_modal(XAU340RouletteNumberModal(self))
    @discord.ui.button(label="Girar", emoji="🎡", style=discord.ButtonStyle.green, row=2)
    async def spin(self, interaction, button):
        if not self.choice:
            await interaction.response.send_message("Primero elige una apuesta de la mesa.", ephemeral=True)
            return
        await interaction.response.defer()
        start_idx = random.randrange(len(XAU_EUROPEAN_WHEEL))
        final_num = random.choice(XAU_EUROPEAN_WHEEL)
        final_idx = XAU_EUROPEAN_WHEEL.index(final_num)
        laps = 2 * len(XAU_EUROPEAN_WHEEL)
        distance = (final_idx - start_idx) % len(XAU_EUROPEAN_WHEEL)
        path_len = laps + distance
        # Cinematic deceleration: quick start, slow ending, showing real wheel order.
        for step in range(path_len + 1):
            n = XAU_EUROPEAN_WHEEL[(start_idx + step) % len(XAU_EUROPEAN_WHEEL)]
            delay = 0.045 + (step / max(path_len, 1)) ** 2 * 0.16
            phase = f"La bola recorre el cilindro... paso {step+1}/{path_len+1}"
            await interaction.message.edit(embed=self.render(phase, discord.Color.gold(), n), view=self)
            await asyncio.sleep(delay)
        win, mult, label = xau340_roulette_payout(self.choice, final_num)
        payout = self.bet * mult if win else 0
        stats, net = await xauig_pay(self.ctx, payout, "ruleta", self.bet, self.choice)
        self.disable_all()
        color_name = xau340_roulette_color(final_num)
        embed = self.render(f"Resultado: {xau340_roulette_icon(final_num)} {final_num} · {color_name}", XAU_GAME_COLOR_WIN if win else XAU_GAME_COLOR_LOSS, final_num)
        embed.add_field(name="🎯 Apuesta", value=f"{label} · multiplicador x{mult if win else 0}", inline=True)
        embed.add_field(name="💰 Payout", value=f"**{payout:,}** · Neto **{net:+,}**", inline=True)
        embed.add_field(name="📚 Regla aplicada", value="En ruleta europea el 0 es verde. Pleno paga 35:1; apuestas externas pagan 1:1; docenas/columnas pagan 2:1.", inline=False)
        await self.safe_edit(interaction, embed, XAUReplayView(f"!ruleta {self.bet}"))


