import shlex as _xau_replay_shlex

class XAUReplayContext:
    """Small Context-compatible adapter for launching commands from buttons.

    Discord button interactions do not create a normal prefix-command Context.
    This adapter exposes the fields used by the minigames: author, channel,
    guild, bot, send(), reply() and typing(). It lets replay buttons call the
    real command callback directly while preserving the player as interaction.user.
    """
    def __init__(self, interaction: discord.Interaction, command_text: str):
        self.interaction = interaction
        self.bot = bot
        self.author = interaction.user
        self.user = interaction.user
        self.channel = interaction.channel
        self.guild = interaction.guild
        self.me = getattr(interaction.guild, "me", None) if interaction.guild else None
        self.message = getattr(interaction, "message", None)
        self.command_text = command_text
        self.prefix = "!"
        self.invoked_with = ""
        self.command = None

    async def send(self, *args, **kwargs):
        """Send like commands.Context.send(). Returns the created message."""
        kwargs.pop("ephemeral", None)  # channel.send does not support ephemeral
        if self.channel is None:
            return await self.interaction.followup.send(*args, **kwargs)
        return await self.channel.send(*args, **kwargs)

    async def reply(self, *args, **kwargs):
        """Compatibility alias used by some command bodies."""
        return await self.send(*args, **kwargs)

    def typing(self):
        """Expose channel typing context when available."""
        if self.channel is not None and hasattr(self.channel, "typing"):
            return self.channel.typing()
        class _NullTyping:
            async def __aenter__(self): return self
            async def __aexit__(self, exc_type, exc, tb): return False
        return _NullTyping()


def _xau_replay_parse(command_text: str):
    """Parse a stored replay command such as '!blackjack 100' safely."""
    command_text = str(command_text or "").strip()
    if not command_text:
        return None, []
    if command_text.startswith("!"):
        command_text = command_text[1:]
    try:
        parts = _xau_replay_shlex.split(command_text)
    except Exception:
        parts = command_text.split()
    if not parts:
        return None, []
    return parts[0].lower(), parts[1:]


async def _xau_replay_execute_command(interaction: discord.Interaction, command_text: str):
    """Execute a replay command as the interaction user.

    This avoids sending fake bot messages and does not require the player to copy
    instructions. The command callback is called directly with a lightweight
    Context adapter, which is enough for the casino/minigame functions.
    """
    name, args = _xau_replay_parse(command_text)
    if not name:
        await interaction.followup.send("❌ No pude detectar qué partida repetir.", ephemeral=True)
        return
    command = bot.get_command(name)
    if command is None:
        await interaction.followup.send(f"❌ No encontré el comando `{name}` para repetir la partida.", ephemeral=True)
        return
    ctx = XAUReplayContext(interaction, command_text)
    ctx.command = command
    ctx.invoked_with = name
    try:
        # Most minigames use one optional argument: apuesta/showcase.
        # Extra args are preserved for legacy games such as PPT or ruleta variants.
        result = command.callback(ctx, *args)
        if asyncio.iscoroutine(result):
            await result
    except commands.CommandOnCooldown as exc:
        await interaction.followup.send(
            f"⏳ Esa revancha está en cooldown. Espera **{round(exc.retry_after, 1)}s**.",
            ephemeral=True,
        )
    except TypeError as exc:
        await interaction.followup.send(
            f"❌ No pude repetir `{command_text}` porque la firma del comando no coincide: `{str(exc)[:180]}`",
            ephemeral=True,
        )
    except Exception as exc:
        try:
            logging.exception("[X AETHER ULTRA] Replay button failed for %s", command_text)
        except Exception:
            pass
        await interaction.followup.send(
            f"❌ La revancha falló al ejecutarse: `{type(exc).__name__}: {str(exc)[:220]}`",
            ephemeral=True,
        )


class XAUReplayButton(discord.ui.Button):
    """Button that launches the replay immediately."""
    def __init__(self, command_text: str, owner_id: int | None = None, label: str = "Volver a jugar"):
        super().__init__(label=label, emoji="🔁", style=discord.ButtonStyle.blurple)
        self.command_text = str(command_text or "").strip()
        self.owner_id = int(owner_id) if owner_id else None

    async def callback(self, interaction: discord.Interaction):
        if self.owner_id and interaction.user.id != self.owner_id:
            await interaction.response.send_message("🔒 Esta revancha pertenece a otra persona.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        await interaction.followup.send("🔁 Revancha lanzada. Abriendo una nueva partida...", ephemeral=True)
        await _xau_replay_execute_command(interaction, self.command_text)


class XAUReplayView(discord.ui.View):
    """Final replay view compatible with both old and new constructor styles.

    Supported signatures:
      XAUReplayView('!slots 100')
      XAUReplayView(author_id, '!slots 100')
    """
    def __init__(self, *args, timeout: float = 60):
        super().__init__(timeout=timeout)
        owner_id = None
        command_text = ""
        if len(args) == 1:
            command_text = str(args[0])
        elif len(args) >= 2:
            try:
                owner_id = int(args[0])
            except Exception:
                owner_id = None
            command_text = str(args[1])
        self.add_item(XAUReplayButton(command_text, owner_id=owner_id))


