# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║ X AETHER ULTRA 3.4.2 · REAL BET CHANGE MODALS                              ║
# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║ Adds a real “Cambiar apuesta” flow to every replay/minigame result view.    ║
# ║ The player gets a Discord modal asking the new amount and showing their     ║
# ║ current cash in amatistas. Submitting the modal launches the same game      ║
# ║ immediately with the new bet, instead of printing manual instructions.      ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

_XAU_BET_WORDS_ALL = {"all", "todo", "max", "maximo", "máximo", "allin", "all-in", "full"}
_XAU_BET_WORDS_META = _XAU_BET_WORDS_ALL | {"showcase", "demo"}


def _xau_compact_amount(value) -> str:
    """Return a short Spanish-safe amount for modal labels, keeping Discord limits."""
    try:
        value = int(value)
    except Exception:
        return "0"
    if abs(value) >= 1_000_000_000:
        return f"{value / 1_000_000_000:.1f}B".replace(".0", "")
    if abs(value) >= 1_000_000:
        return f"{value / 1_000_000:.1f}M".replace(".0", "")
    if abs(value) >= 1_000:
        return f"{value / 1_000:.1f}K".replace(".0", "")
    return str(value)


def _xau_get_user_cash(user_id: int) -> int:
    """Read current user cash without changing the existing datos.json format."""
    try:
        datos = cargar_datos()
        uid = str(int(user_id))
        asegurar_usuario(datos, uid)
        return int(datos.get(uid, {}).get("cash", 0) or 0)
    except Exception:
        return 0


def _xau_parse_bet_value(raw_value: str, cash_available: int):
    """Parse modal text into an integer bet. Supports Spanish words and k/m suffixes."""
    value = str(raw_value or "").strip().lower()
    if not value:
        raise ValueError("Escribe una cantidad.")
    value = value.replace(" ", "")
    if value in _XAU_BET_WORDS_ALL:
        if cash_available <= 0:
            raise ValueError("No tienes cash disponible para apostar todo.")
        return int(cash_available)
    multiplier = 1
    if value.endswith("k"):
        multiplier = 1_000
        value = value[:-1]
    elif value.endswith("m"):
        multiplier = 1_000_000
        value = value[:-1]
    value = value.replace(".", "").replace(",", "")
    if not value.isdigit():
        raise ValueError("Usa solo números, por ejemplo 100, 1.000, 5k o todo.")
    amount = int(value) * multiplier
    if amount <= 0:
        raise ValueError("La apuesta debe ser mayor que 0.")
    if amount > int(cash_available):
        raise ValueError(f"No tienes suficiente cash. Disponible: {int(cash_available):,} amatistas.")
    return amount


def _xau_is_bet_token(token: str) -> bool:
    """Return True when a token looks like a bet argument."""
    token = str(token or "").strip().lower()
    if not token:
        return False
    if token in _XAU_BET_WORDS_META:
        return True
    clean = token.replace(".", "").replace(",", "")
    if clean.endswith(("k", "m")):
        clean = clean[:-1]
    return clean.isdigit()


def _xau_rewrite_command_with_bet(command_text: str, new_bet: int) -> str:
    """Replace the first wager-like argument in a command, preserving other options."""
    original = str(command_text or "").strip()
    if not original:
        return f"!slots {int(new_bet)}"
    prefixed = original.startswith("!")
    raw = original[1:] if prefixed else original
    try:
        parts = _xau_replay_shlex.split(raw)
    except Exception:
        parts = raw.split()
    if not parts:
        return f"!slots {int(new_bet)}"
    replaced = False
    for index in range(1, len(parts)):
        if _xau_is_bet_token(parts[index]):
            parts[index] = str(int(new_bet))
            replaced = True
            break
    if not replaced:
        parts.insert(1, str(int(new_bet)))
    return "!" + " ".join(parts)


def _xau_replace_args_with_bet(args, new_bet: int):
    """Replace or inject bet inside legacy callback args."""
    items = list(args or [])
    for index, item in enumerate(items):
        if _xau_is_bet_token(str(item)) or isinstance(item, int):
            items[index] = str(int(new_bet))
            return tuple(items)
    return tuple([str(int(new_bet))] + items)


def _xau_guess_current_bet(command_text: str = "", args=None) -> str:
    """Find current bet for a modal default value."""
    if args:
        for item in args:
            if _xau_is_bet_token(str(item)):
                return str(item)
            if isinstance(item, int):
                return str(item)
    try:
        _, parsed_args = _xau_replay_parse(command_text)
        for item in parsed_args:
            if _xau_is_bet_token(str(item)):
                return str(item)
    except Exception:
        pass
    return "100"


class XAUBetChangeModal(discord.ui.Modal):
    """Modal that asks the player for a new bet and runs the provided launcher."""
    def __init__(self, owner_id: int, cash_available: int, current_bet: str, launch_callback):
        title_cash = _xau_compact_amount(cash_available)
        super().__init__(title=f"Cambiar apuesta · cash {title_cash}"[:45])
        self.owner_id = int(owner_id)
        self.cash_available = int(cash_available)
        self.launch_callback = launch_callback
        label = f"Apuesta (cash: {_xau_compact_amount(cash_available)})"[:45]
        self.amount = discord.ui.TextInput(
            label=label,
            placeholder="Ej: 100, 1.000, 5k o todo",
            default=str(current_bet or "100")[:100],
            min_length=1,
            max_length=20,
            required=True,
        )
        self.add_item(self.amount)

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("🔒 Este modal pertenece a otra partida.", ephemeral=True)
            return
        try:
            # Refresh cash at submit time so the modal cannot use stale balance.
            cash_now = _xau_get_user_cash(interaction.user.id)
            new_bet = _xau_parse_bet_value(str(self.amount.value), cash_now)
        except ValueError as exc:
            await interaction.response.send_message(f"❌ {exc}", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        await interaction.followup.send(
            f"💎 Apuesta cambiada a **{int(new_bet):,} amatistas**. Lanzando nueva partida...",
            ephemeral=True,
        )
        await self.launch_callback(interaction, int(new_bet))


class XAUBetChangeButton(discord.ui.Button):
    """Reusable button that opens the bet-change modal."""
    def __init__(self, owner_id: int | None, current_bet: str, launch_callback):
        super().__init__(label="Cambiar apuesta", emoji="💎", style=discord.ButtonStyle.green)
        self.owner_id = int(owner_id) if owner_id else None
        self.current_bet = str(current_bet or "100")
        self.launch_callback = launch_callback

    async def callback(self, interaction: discord.Interaction):
        if self.owner_id and interaction.user.id != self.owner_id:
            await interaction.response.send_message("🔒 Este botón pertenece a otra persona.", ephemeral=True)
            return
        owner_id = self.owner_id or interaction.user.id
        cash_available = _xau_get_user_cash(interaction.user.id)
        modal = XAUBetChangeModal(owner_id, cash_available, self.current_bet, self.launch_callback)
        await interaction.response.send_modal(modal)


class XAUReplayView(discord.ui.View):
    """Replay view with direct replay and direct bet-change modal.

    Supported signatures:
      XAUReplayView('!slots 100')
      XAUReplayView(author_id, '!slots 100')
    """
    def __init__(self, *args, timeout: float = 75):
        super().__init__(timeout=timeout)
        owner_id = None
        command_text = ""
        if len(args) == 1:
            command_text = str(args[0])
        elif len(args) >= 2:
            try:
                owner_id = int(args[0])
            except Exception:
                owner_id = None
            command_text = str(args[1])
        current_bet = _xau_guess_current_bet(command_text)
        self.command_text = command_text
        self.owner_id = owner_id
        self.add_item(XAUReplayButton(command_text, owner_id=owner_id, label="Repetir"))

        async def _launch_with_new_bet(interaction: discord.Interaction, new_bet: int):
            rewritten = _xau_rewrite_command_with_bet(command_text, new_bet)
            await _xau_replay_execute_command(interaction, rewritten)

        self.add_item(XAUBetChangeButton(owner_id, current_bet, _launch_with_new_bet))


