def _xau_live_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")


def _xau_deep_merge(default, current):
    if isinstance(default, dict) and isinstance(current, dict):
        merged = dict(default)
        for key, value in current.items():
            merged[key] = _xau_deep_merge(default.get(key), value) if key in default else value
        return merged
    return current if current is not None else default


def _xau_live_load_json(path: str, default=None):
    default = XAU_DEFAULT_LIVING_CORE if default is None else default
    lock = _XAU_LIVING_LOCK
    if lock:
        lock.acquire()
    try:
        if not os.path.exists(path):
            return json.loads(json.dumps(default, ensure_ascii=False))
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if path == XAU_LIVING_CORE_FILE:
            return _xau_deep_merge(default, data if isinstance(data, dict) else {})
        return data
    except Exception as exc:
        print(f"[X AETHER ULTRA] live core JSON load error {path}: {exc!r}")
        return json.loads(json.dumps(default, ensure_ascii=False))
    finally:
        if lock:
            lock.release()


def _xau_live_save_json(path: str, data):
    lock = _XAU_LIVING_LOCK
    if lock:
        lock.acquire()
    try:
        directory = os.path.dirname(os.path.abspath(path)) or "."
        os.makedirs(directory, exist_ok=True)
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False, dir=directory, suffix=".tmp") as tmp:
            json.dump(data, tmp, ensure_ascii=False, indent=2)
            tmp.flush()
            os.fsync(tmp.fileno())
            temp_name = tmp.name
        os.replace(temp_name, path)
        return True
    except Exception as exc:
        print(f"[X AETHER ULTRA] live core JSON save error {path}: {exc!r}")
        return False
    finally:
        if lock:
            lock.release()


def _xau_living_state():
    return _xau_live_load_json(XAU_LIVING_CORE_FILE, XAU_DEFAULT_LIVING_CORE)


def _xau_living_save(state):
    return _xau_live_save_json(XAU_LIVING_CORE_FILE, state)


def _xau_guild_key(guild):
    return str(getattr(guild, "id", 0) or 0)


def _xau_channel_key(channel):
    return str(getattr(channel, "id", 0) or 0)


def _xau_member_is_staff(member) -> bool:
    perms = getattr(member, "guild_permissions", None)
    return bool(perms and (perms.manage_guild or perms.manage_messages or perms.administrator))


def _xau_get_channel_config(channel, guild=None):
    state = _xau_living_state()
    gid = _xau_guild_key(guild or getattr(channel, "guild", None))
    cid = _xau_channel_key(channel)
    gconf = state.setdefault("guilds", {}).setdefault(gid, {})
    cconf = state.setdefault("channels", {}).setdefault(cid, {})
    enabled = bool(cconf.get("autonomy", gconf.get("autonomy", state.get("settings", {}).get("autonomy_default", False))))
    return state, gconf, cconf, enabled


def _xau_emotion_apply(event: str, intensity: float = 0.05):
    state = _xau_living_state()
    emotion = state.setdefault("emotion", {})
    intensity = max(0.0, min(1.0, float(intensity or 0)))
    if event in {"win", "achievement", "praise", "new_day"}:
        emotion["energy"] = min(1.0, float(emotion.get("energy", 0.5)) + intensity)
        emotion["affinity"] = min(1.0, float(emotion.get("affinity", 0.5)) + intensity / 2)
        emotion["stress"] = max(0.0, float(emotion.get("stress", 0.1)) - intensity / 2)
        emotion["mood"] = "alegre"
    elif event in {"error", "toxic", "spam", "failed_tool"}:
        emotion["stress"] = min(1.0, float(emotion.get("stress", 0.1)) + intensity)
        emotion["energy"] = max(0.1, float(emotion.get("energy", 0.5)) - intensity / 3)
        emotion["mood"] = "alerta" if emotion["stress"] < 0.75 else "tenso"
    elif event in {"question", "image", "audio", "game"}:
        emotion["mood"] = "curioso"
        emotion["confidence"] = min(1.0, float(emotion.get("confidence", 0.7)) + intensity / 4)
    events = emotion.setdefault("last_events", [])
    events.append({"event": event, "at": _xau_live_now(), "intensity": intensity})
    emotion["last_events"] = events[-24:]
    _xau_living_save(state)


def _xau_emotion_prompt() -> str:
    state = _xau_living_state()
    emotion = state.get("emotion", {})
    mood = emotion.get("mood", "curioso")
    energy = float(emotion.get("energy", 0.5))
    stress = float(emotion.get("stress", 0.1))
    confidence = float(emotion.get("confidence", 0.7))
    return f"""
━━ ESTADO AFECTIVO SIMULADO DE AETHER ━━━━━━━━━
AETHER no tiene sentimientos biológicos, pero mantiene un estado emocional persistente para modular tono y presencia:
- ánimo: {mood}
- energía: {energy:.2f}
- estrés operativo: {stress:.2f}
- confianza: {confidence:.2f}
Usa esto de forma sutil: más cálido si energía alta, más breve si estrés alto, más explicativo si confianza alta.
"""


async def perguntar_aether(user_id: int, user_message: str, username: str, perfil_usuario: str = "", **kwargs) -> str:
    """Compatibility wrapper: injects living-core affective and multimodal context without breaking old callers."""
    previous = _XAU_PREVIOUS_PREGUNTAR_AETHER
    channel_id = kwargs.get("channel_id")
    guild_id = kwargs.get("guild_id")
    media_context = kwargs.get("media_context", "")
    living_context = _xau_emotion_prompt()
    if channel_id or guild_id:
        living_context += f"\n━━ CONTEXTO CANAL ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nCanal ID: {channel_id or 'DM'} · Servidor ID: {guild_id or 'DM'}\n"
    if media_context:
        living_context += f"\n━━ CONTEXTO MULTIMODAL ━━━━━━━━━━━━━━━━━━━━━━━\n{media_context[:2500]}\n"
    perfil_plus = (perfil_usuario or "") + "\n" + living_context
    if previous:
        try:
            return await previous(user_id=user_id, user_message=user_message, username=username, perfil_usuario=perfil_plus)
        except TypeError:
            return await previous(user_id, user_message, username, perfil_plus)
    return "AETHER está activo, pero el proveedor de IA todavía no está configurado."

bot.preguntar_aether = perguntar_aether


