def _xau_attachment_kind(att: discord.Attachment) -> str:
    ct = (getattr(att, "content_type", "") or "").lower()
    name = (getattr(att, "filename", "") or "").lower()
    if ct.startswith("image/") or name.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
        return "image"
    if ct.startswith("audio/") or name.endswith((".mp3", ".wav", ".ogg", ".m4a", ".webm", ".flac")):
        return "audio"
    return "other"


async def _xau_read_attachment_b64(att: discord.Attachment, max_bytes: int = 8_000_000):
    if getattr(att, "size", 0) and att.size > max_bytes:
        raise ValueError(f"Archivo demasiado grande ({att.size} bytes). Máximo {max_bytes} bytes.")
    raw = await att.read()
    if len(raw) > max_bytes:
        raise ValueError(f"Archivo demasiado grande ({len(raw)} bytes). Máximo {max_bytes} bytes.")
    mime = getattr(att, "content_type", None) or "application/octet-stream"
    return f"data:{mime};base64," + _xau_base64.b64encode(raw).decode("ascii"), raw


async def _xau_analyze_image_attachment(att: discord.Attachment, prompt: str = "") -> str:
    client = _xau_openai_client()
    if not client:
        return "No tengo `OPENAI_API_KEY` configurada para visión. Puedo ver el nombre/tamaño del adjunto, pero no analizar píxeles todavía."
    image_url, _ = await _xau_read_attachment_b64(att)
    model = os.getenv("XAU_VISION_MODEL", "gpt-4o-mini")
    user_prompt = prompt.strip() or "Analiza esta imagen para un servidor de Discord. Describe contenido, detalles útiles, posible texto visible y si parece apropiada. Responde en español."
    try:
        resp = await asyncio.wait_for(
            client.chat.completions.create(
                model=model,
                messages=[
                    {"role": "system", "content": "Eres AETHER, analista visual de Discord. Responde en español, claro y útil."},
                    {"role": "user", "content": [
                        {"type": "text", "text": user_prompt},
                        {"type": "image_url", "image_url": {"url": image_url}},
                    ]},
                ],
                max_tokens=700,
            ),
            timeout=float(os.getenv("XAU_VISION_TIMEOUT", "45")),
        )
        content = resp.choices[0].message.content if getattr(resp, "choices", None) else "No pude extraer análisis."
        state = _xau_living_state(); state.setdefault("stats", {})["images_analyzed"] = int(state.setdefault("stats", {}).get("images_analyzed", 0)) + 1; _xau_living_save(state)
        _xau_emotion_apply("image", 0.04)
        return content or "No pude describir la imagen."
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return f"No pude analizar la imagen ahora mismo: `{type(exc).__name__}: {str(exc)[:180]}`"


async def _xau_transcribe_audio_attachment(att: discord.Attachment) -> str:
    client = _xau_openai_client()
    if not client:
        return "No tengo `OPENAI_API_KEY` configurada para transcribir audio."
    _, raw = await _xau_read_attachment_b64(att, max_bytes=24_000_000)
    suffix = os.path.splitext(att.filename or "audio.mp3")[1] or ".mp3"
    temp_path = os.path.join(XAU_MEDIA_CACHE_DIR, f"stt_{int(time.time()*1000)}{suffix}")
    with open(temp_path, "wb") as f:
        f.write(raw)
    model = os.getenv("XAU_STT_MODEL", "whisper-1")
    try:
        with open(temp_path, "rb") as audio_file:
            resp = await asyncio.wait_for(
                client.audio.transcriptions.create(model=model, file=audio_file),
                timeout=float(os.getenv("XAU_STT_TIMEOUT", "90")),
            )
        text = getattr(resp, "text", None) or str(resp)
        state = _xau_living_state(); state.setdefault("stats", {})["audios_transcribed"] = int(state.setdefault("stats", {}).get("audios_transcribed", 0)) + 1; _xau_living_save(state)
        _xau_emotion_apply("audio", 0.04)
        return text.strip() or "No detecté voz clara en el audio."
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return f"No pude transcribir el audio: `{type(exc).__name__}: {str(exc)[:180]}`"
    finally:
        with _xau_contextlib.suppress(Exception):
            os.remove(temp_path)


async def _xau_generate_image(prompt: str) -> tuple:
    client = _xau_openai_client()
    if not client:
        return None, "No tengo `OPENAI_API_KEY` configurada para generar imágenes."
    model = os.getenv("XAU_IMAGE_MODEL", "gpt-image-1")
    size = os.getenv("XAU_IMAGE_SIZE", "1024x1024")
    full_prompt = f"Imagen para Discord de X AETHER ULTRA, estilo premium, nítida, segura, sin texto ilegible. Pedido del usuario: {prompt}"
    try:
        resp = await asyncio.wait_for(
            client.images.generate(model=model, prompt=full_prompt, size=size, n=1),
            timeout=float(os.getenv("XAU_IMAGE_TIMEOUT", "120")),
        )
        item = resp.data[0]
        b64 = getattr(item, "b64_json", None)
        url = getattr(item, "url", None)
        if b64:
            raw = _xau_base64.b64decode(b64)
            out = os.path.join(XAU_MEDIA_CACHE_DIR, f"xau_image_{int(time.time()*1000)}.png")
            with open(out, "wb") as f:
                f.write(raw)
            state = _xau_living_state(); state.setdefault("stats", {})["images_generated"] = int(state.setdefault("stats", {}).get("images_generated", 0)) + 1; _xau_living_save(state)
            return out, None
        if url:
            async with aiohttp.ClientSession() as session:
                async with session.get(url, timeout=90) as r:
                    raw = await r.read()
            out = os.path.join(XAU_MEDIA_CACHE_DIR, f"xau_image_{int(time.time()*1000)}.png")
            with open(out, "wb") as f:
                f.write(raw)
            state = _xau_living_state(); state.setdefault("stats", {})["images_generated"] = int(state.setdefault("stats", {}).get("images_generated", 0)) + 1; _xau_living_save(state)
            return out, None
        return None, "El proveedor no devolvió imagen utilizable."
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return None, f"No pude generar la imagen: `{type(exc).__name__}: {str(exc)[:180]}`"


async def _xau_tts_to_file(text: str, voice: str = None) -> tuple:
    voice = voice or _xau_living_state().get("settings", {}).get("tts_voice", "es-ES-AlvaroNeural")
    text = (text or "").strip()
    if not text:
        return None, "Escribe el texto que quieres que convierta a audio."
    if len(text) > 1400:
        text = text[:1400] + "..."
    if "edge_tts" not in globals() or edge_tts is None:
        return None, "No tengo `edge_tts` disponible para generar audio."
    out = os.path.join(XAU_MEDIA_CACHE_DIR, f"xau_voice_{int(time.time()*1000)}.mp3")
    try:
        communicate = edge_tts.Communicate(text, voice)
        await asyncio.wait_for(communicate.save(out), timeout=90)
        state = _xau_living_state(); state.setdefault("stats", {})["audios_sent"] = int(state.setdefault("stats", {}).get("audios_sent", 0)) + 1; _xau_living_save(state)
        return out, None
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return None, f"No pude generar el audio: `{type(exc).__name__}: {str(exc)[:180]}`"


class XAUAutonomyModeView(discord.ui.View):
    def __init__(self, ctx):
        super().__init__(timeout=90)
        self.ctx = ctx

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.ctx.author.id and not _xau_member_is_staff(interaction.user):
            await interaction.response.send_message("🔒 Solo staff o quien abrió este panel puede cambiar la autonomía.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="🟢 Activar aquí", style=discord.ButtonStyle.green)
    async def enable_here(self, interaction: discord.Interaction, button: discord.ui.Button):
        state = _xau_living_state(); cid = _xau_channel_key(interaction.channel)
        state.setdefault("channels", {}).setdefault(cid, {})["autonomy"] = True
        state["channels"][cid]["enabled_by"] = interaction.user.id
        state["channels"][cid]["enabled_at"] = _xau_live_now()
        _xau_living_save(state)
        await interaction.response.edit_message(embed=_xau_live_embed("🟢 Autonomía activada", "AETHER podrá participar en este canal con cooldown, contexto y límites anti-spam.", discord.Color.green(), interaction.user), view=self)

    @discord.ui.button(label="🔴 Desactivar aquí", style=discord.ButtonStyle.red)
    async def disable_here(self, interaction: discord.Interaction, button: discord.ui.Button):
        state = _xau_living_state(); cid = _xau_channel_key(interaction.channel)
        state.setdefault("channels", {}).setdefault(cid, {})["autonomy"] = False
        state["channels"][cid]["disabled_by"] = interaction.user.id
        state["channels"][cid]["disabled_at"] = _xau_live_now()
        _xau_living_save(state)
        await interaction.response.edit_message(embed=_xau_live_embed("🔴 Autonomía desactivada", "AETHER dejará de hablar por sí mismo en este canal.", discord.Color.red(), interaction.user), view=self)

    @discord.ui.button(label="📊 Estado", style=discord.ButtonStyle.blurple)
    async def status(self, interaction: discord.Interaction, button: discord.ui.Button):
        state, _, cconf, enabled = _xau_get_channel_config(interaction.channel, interaction.guild)
        emotion = state.get("emotion", {})
        desc = (
            f"**Canal:** {'activado' if enabled else 'desactivado'}\n"
            f"**Ánimo simulado:** {emotion.get('mood', 'curioso')}\n"
            f"**Energía:** {float(emotion.get('energy', 0.5)):.2f}\n"
            f"**Estrés:** {float(emotion.get('stress', 0.1)):.2f}\n"
            f"**Cooldown:** {state.get('settings', {}).get('autonomy_cooldown_seconds', 90)}s\n"
        )
        await interaction.response.send_message(embed=_xau_live_embed("📊 Estado Living Core", desc, discord.Color.purple(), interaction.user), ephemeral=True)


class XAULivingHelpView(discord.ui.View):
    def __init__(self, owner_id: int = None):
        super().__init__(timeout=120)
        self.owner_id = owner_id
        self.page = 0
        self.pages = [
            ("🧠 Núcleo vivo", "Autonomía con cooldown, memoria de canal, estado emocional simulado y límites diarios por canal."),
            ("🖼️ Imágenes", "`!imagen <prompt>` genera imágenes. `!analizar_imagen` analiza adjuntos visuales con visión si hay API configurada."),
            ("🎧 Audio", "`!transcribir_audio` entiende audios adjuntos. `!audio <texto>` envía voz MP3 usando TTS."),
            ("🎮 Minijuegos", "Los minijuegos pueden disparar comentarios autónomos, logros, emoción y decoración sin bloquear comandos."),
            ("⚙️ Seguridad", "La autonomía es configurable por canal: `!autonomia activar`, `!autonomia desactivar`, `!autonomia estado`."),
        ]

    def _embed(self, user=None):
        title, desc = self.pages[self.page]
        bar = "▰" * (self.page + 1) + "▱" * (len(self.pages) - self.page - 1)
        return _xau_live_embed(f"{title} · {self.page + 1}/{len(self.pages)}", f"{desc}\n\n`{bar}`", discord.Color.purple(), user)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if self.owner_id and interaction.user.id != self.owner_id:
            await interaction.response.send_message("Abre tu propio panel con `!aether_vivo`.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="⬅️", style=discord.ButtonStyle.secondary)
    async def prev(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page = (self.page - 1) % len(self.pages)
        await interaction.response.edit_message(embed=self._embed(interaction.user), view=self)

    @discord.ui.button(label="➡️", style=discord.ButtonStyle.secondary)
    async def next(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page = (self.page + 1) % len(self.pages)
        await interaction.response.edit_message(embed=self._embed(interaction.user), view=self)

    @discord.ui.button(label="🟣 Autonomía", style=discord.ButtonStyle.blurple)
    async def autonomy(self, interaction: discord.Interaction, button: discord.ui.Button):
        fake_ctx = type("Ctx", (), {"author": interaction.user})()
        await interaction.response.send_message(embed=_xau_live_embed("🟣 Panel de autonomía", "Activa o desactiva la participación autónoma en este canal.", discord.Color.purple(), interaction.user), view=XAUAutonomyModeView(fake_ctx), ephemeral=True)


