async def xau_autonomia_cmd(ctx, accion: str = "estado"):
    """Activa/desactiva la autonomía de AETHER en el canal actual."""
    if ctx.guild and not _xau_member_is_staff(ctx.author) and ctx.author.id not in {globals().get("MI_ID"), globals().get("MARKELSON_ID")}:
        await ctx.send(embed=_xau_live_embed("🔒 Permisos", "Solo staff puede activar o desactivar la autonomía del canal.", discord.Color.red(), ctx.author))
        return
    accion = (accion or "estado").lower().strip()
    state, _, cconf, enabled = _xau_get_channel_config(ctx.channel, ctx.guild)
    cid = _xau_channel_key(ctx.channel)
    if accion in {"on", "activar", "enable", "si", "sí"}:
        state.setdefault("channels", {}).setdefault(cid, {})["autonomy"] = True
        state["channels"][cid]["enabled_by"] = ctx.author.id
        state["channels"][cid]["enabled_at"] = _xau_live_now()
