        emotion = state.get("emotion", {})
        desc = (
            f"**Canal actual:** {'🟢 activo' if enabled else '🔴 inactivo'}\n"
            f"**Ánimo simulado:** {emotion.get('mood', 'curioso')}\n"
            f"**Energía:** {float(emotion.get('energy', 0.5)):.2f}\n"
            f"**Estrés:** {float(emotion.get('stress', 0.1)):.2f}\n"
            f"**Uso:** `!autonomia activar` / `!autonomia desactivar`\n"
        )
        await ctx.send(embed=_xau_live_embed("📊 Estado de autonomía", desc, discord.Color.purple(), ctx.author), view=XAUAutonomyModeView(ctx))


