def _xau_autonomy_score(message: discord.Message) -> tuple:
    content = str(getattr(message, "content", "") or "")
    low = content.lower()
    score = 0.0
    reasons = []
    today = datetime.datetime.now().strftime("%Y-%m-%d")
    ch_key = _xau_channel_key(message.channel)
    greeted_key = f"{ch_key}:{today}"
    if any(w in low for w in ["hola", "buenas", "buenos días", "buenos dias", "hey", "ey"]):
        score += 0.32
        reasons.append("saludo")
        if greeted_key not in _XAU_AUTONOMY_RUNTIME["daily_greeted"]:
            score += 0.30
            reasons.append("primer_saludo_dia")
    if "?" in content or any(w in low for w in ["como", "cómo", "ayuda", "que hago", "qué hago", "porque", "por qué"]):
        score += 0.22
        reasons.append("pregunta")
    if any(w in low for w in ["blackjack", "poker", "texas", "ruleta", "slots", "minas", "crash", "apuesta", "casino", "amatistas"]):
        score += 0.20
        reasons.append("juego")
    if any(w in low for w in ["aether", "bot", "ia", "imagen", "audio", "voz"]):
        score += 0.22
        reasons.append("tema_aether")
    if getattr(message, "attachments", None):
        kinds = [_xau_attachment_kind(a) for a in message.attachments]
        if "image" in kinds:
            score += 0.25
            reasons.append("imagen")
        if "audio" in kinds:
            score += 0.25
            reasons.append("audio")
    if len(content) < 3 and not getattr(message, "attachments", None):
        score -= 0.20
    return max(0.0, min(1.0, score)), reasons


def _xau_autonomy_allowed(message: discord.Message, score: float, reasons: list) -> bool:
    if not getattr(message, "guild", None):
        return False
    state, _, cconf, enabled = _xau_get_channel_config(message.channel, message.guild)
    if not enabled:
        return False
    settings = state.get("settings", {})
    cooldown = int(settings.get("autonomy_cooldown_seconds", 90))
    ch_key = _xau_channel_key(message.channel)
    now = time.time()
    last = float(_XAU_AUTONOMY_RUNTIME["last_channel_message"].get(ch_key, 0))
    if now - last < cooldown:
        return False
    day = datetime.datetime.now().strftime("%Y-%m-%d")
    day_key = f"count:{ch_key}:{day}"
    count = int(cconf.get(day_key, 0))
    if count >= int(settings.get("max_auto_messages_per_channel_day", 12)):
        return False
    probability = float(settings.get("autonomy_probability", 0.025))
    threshold = 0.48
    if score >= threshold:
        return True
    return random.random() < probability and score >= 0.25


async def _xau_autonomous_reply(message: discord.Message, reasons: list):
    ch_key = _xau_channel_key(message.channel)
    state, _, cconf, enabled = _xau_get_channel_config(message.channel, message.guild)
    if not enabled:
        return
    today = datetime.datetime.now().strftime("%Y-%m-%d")
    greeted_key = f"{ch_key}:{today}"
    media_context = ""
    text = str(message.content or "")
    if "image" in reasons:
        image = next((a for a in message.attachments if _xau_attachment_kind(a) == "image"), None)
        if image and any(k in text.lower() for k in ["analiza", "mira", "que ves", "qué ves", "opina", "imagen"]):
            media_context = await _xau_analyze_image_attachment(image, text)
    if "audio" in reasons:
        audio = next((a for a in message.attachments if _xau_attachment_kind(a) == "audio"), None)
        if audio and any(k in text.lower() for k in ["escucha", "transcribe", "audio", "que dice", "qué dice"]):
            media_context = "Transcripción del audio: " + await _xau_transcribe_audio_attachment(audio)
    if "primer_saludo_dia" in reasons and greeted_key not in _XAU_AUTONOMY_RUNTIME["daily_greeted"]:
        _XAU_AUTONOMY_RUNTIME["daily_greeted"].add(greeted_key)
        _xau_emotion_apply("new_day", 0.06)
        prompt = "Es un nuevo día en el canal. Saluda de forma breve, natural y útil, como un miembro del servidor. No suenes robótico."
    else:
        _xau_emotion_apply("game" if "juego" in reasons else "question", 0.03)
        prompt = (
            "Participa de forma autónoma y breve en esta conversación de Discord. "
            "No interrumpas, no sermonees, no digas que eres ChatGPT. Responde como AETHER, con naturalidad. "
            f"Motivos detectados: {', '.join(reasons)}. Mensaje del usuario: {text[:1000]}"
        )
    async with message.channel.typing():
        perfil = construir_perfil_aether(message.author.id) if "construir_perfil_aether" in globals() else ""
        respuesta = await perguntar_aether(
            user_id=message.author.id,
            user_message=prompt,
            username=getattr(message.author, "display_name", str(message.author)),
            perfil_usuario=perfil,
            channel_id=getattr(message.channel, "id", None),
            guild_id=getattr(message.guild, "id", None),
            media_context=media_context,
        )
    if len(respuesta) > 1800:
        respuesta = respuesta[:1800] + "..."
    embed = _xau_live_embed("💬 AETHER participa", respuesta, discord.Color.purple(), message.author)
    await message.channel.send(embed=embed)
    _XAU_AUTONOMY_RUNTIME["last_channel_message"][ch_key] = time.time()
    cconf[f"count:{ch_key}:{today}"] = int(cconf.get(f"count:{ch_key}:{today}", 0)) + 1
    state.setdefault("stats", {})["autonomous_messages"] = int(state.setdefault("stats", {}).get("autonomous_messages", 0)) + 1
    _xau_living_save(state)


# ══════════════════════════════════════════════════════════════════════════════
# X AETHER ULTRA 3.6.5.2.2 · PREFIX RESOLVER HOTFIX
# ══════════════════════════════════════════════════════════════════════════════
# Fixes a public/living on_message crash when discord.py command_prefix is a
# callable (for example commands.when_mentioned_or) instead of a plain string.
# The resolver only returns real string prefixes, so str.startswith() never
# receives functions inside the tuple.

async def _xau_resolve_message_prefixes(message: discord.Message) -> tuple:
    """Return safe string prefixes for this message, supporting static and dynamic prefixes."""
    import inspect as _xau_inspect

    raw_prefix = getattr(bot, "command_prefix", "!")
    prefixes = []

    async def _push(value):
        if value is None:
            return
        if callable(value):
            try:
                value = value(bot, message)
                if _xau_inspect.isawaitable(value):
                    value = await value
            except Exception:
                return
        if isinstance(value, str):
            if value:
                prefixes.append(value)
            return
        if isinstance(value, (list, tuple, set)):
            for item in value:
                await _push(item)

    await _push(raw_prefix)

    # Mention prefixes are useful when command_prefix comes from a callable that
    # fails during startup or when a server has a custom prefix configured.
    with _xau_contextlib.suppress(Exception):
        if getattr(bot, "user", None):
            prefixes.append(f"<@{bot.user.id}> ")
            prefixes.append(f"<@!{bot.user.id}> ")

    clean = []
    seen = set()
    for item in prefixes:
        if isinstance(item, str) and item and item not in seen:
            clean.append(item)
            seen.add(item)
    return tuple(clean or ("!",))


@bot.event
async def on_message(message: discord.Message):
    """Living on_message: commands first, then mentions/DM/tickets, then safe autonomous participation."""
    if getattr(message.author, "bot", False):
        return
    try:
        prefixes = await _xau_resolve_message_prefixes(message)
        if str(message.content or "").startswith(prefixes):
            await bot.process_commands(message)
            return

        if message.content and message.content.strip() == globals().get("TRIGGER_TEXT", "") and message.author.id == globals().get("MI_ID"):
            if "xau_secret_backup" in globals():
                await xau_secret_backup(message)
            return

        if message.guild and len(str(message.content or "")) >= 3 and "procesar_xp" in globals():
            with _xau_contextlib.suppress(Exception):
                asyncio.create_task(procesar_xp(message))

        content = str(message.content or "")
        low = content.lower()
        if message.guild:
            with _xau_contextlib.suppress(Exception):
                for palabra in globals().get("PALABRAS_PROHIBIDAS", []) + [p for p in globals().get("PALABRAS_INSULTOS", []) if isinstance(p, str)]:
                    if "_contiene_palabra_bloqueada" in globals() and _contiene_palabra_bloqueada(low, palabra):
                        with _xau_contextlib.suppress(Exception):
                            await message.delete()
                        await message.channel.send(embed=_xau_live_embed("🛡️ Filtro de seguridad", f"{message.author.mention}, evita usar palabras inapropiadas.", discord.Color.orange(), message.author), delete_after=8)
                        _xau_emotion_apply("toxic", 0.08)
                        return

        es_ticket = bool(message.guild and getattr(message.channel, "name", "") and str(message.channel.name).startswith("ticket-"))
        mencionado = bool(bot.user and bot.user in getattr(message, "mentions", []))
        is_dm = message.guild is None

        if is_dm or mencionado or es_ticket:
            texto = content
            if message.guild and bot.user:
                texto = texto.replace(f"<@{bot.user.id}>", "").replace(f"<@!{bot.user.id}>", "").strip()
            media_context = ""
            if getattr(message, "attachments", None):
                image = next((a for a in message.attachments if _xau_attachment_kind(a) == "image"), None)
                audio = next((a for a in message.attachments if _xau_attachment_kind(a) == "audio"), None)
                if image:
                    media_context += "Análisis de imagen adjunta: " + await _xau_analyze_image_attachment(image, texto) + "\n"
                if audio:
                    media_context += "Transcripción de audio adjunto: " + await _xau_transcribe_audio_attachment(audio) + "\n"
            if not texto:
                texto = "Preséntate y pregunta cómo puedes ayudar."
            async with message.channel.typing():
                perfil = construir_perfil_aether(message.author.id) if "construir_perfil_aether" in globals() else ""
                respuesta = await perguntar_aether(
                    user_id=message.author.id,
                    user_message=texto,
                    username=getattr(message.author, "display_name", str(message.author)),
                    perfil_usuario=perfil,
                    channel_id=getattr(message.channel, "id", None),
                    guild_id=getattr(message.guild, "id", None) if message.guild else None,
                    media_context=media_context,
                )
                if "procesar_respuesta_aether" in globals():
                    await procesar_respuesta_aether(message, respuesta, es_ticket=es_ticket)
                else:
                    await message.channel.send(embed=_xau_live_embed("🤖 AETHER", respuesta[:3900], discord.Color.purple(), message.author))
            return

        score, reasons = _xau_autonomy_score(message)
        if _xau_autonomy_allowed(message, score, reasons):
            with _xau_contextlib.suppress(Exception):
                await _xau_autonomous_reply(message, reasons)
            return

        await bot.process_commands(message)
    except Exception as exc:
        print(f"[X AETHER ULTRA] living on_message error: {exc!r}")
        print(_xau_traceback.format_exc())
        with _xau_contextlib.suppress(Exception):
            await bot.process_commands(message)

