_XAU_FREEAI_VERSION = "3.5.1"
_XAU_FW_MODEL = None


def _xau_freeai_enabled() -> bool:
    return str(os.getenv("XAU_FREE_AI", "1")).strip().lower() not in {"0", "false", "no", "off"}


def _xau_pollinations_image_url(prompt: str) -> str:
    from urllib.parse import quote_plus
    raw_size = os.getenv("XAU_IMAGE_SIZE", "1024x1024").lower().replace("*", "x")
    try:
        w, h = raw_size.split("x", 1)
        width = max(256, min(2048, int(w)))
        height = max(256, min(2048, int(h)))
    except Exception:
        width, height = 1024, 1024
    model = os.getenv("XAU_POLLINATIONS_IMAGE_MODEL", "flux")
    seed = random.randint(1, 999999999)
    clean_prompt = (
        "Discord premium artwork, X AETHER ULTRA aesthetic, aether neon, sharp details, safe for work, "
        + str(prompt or "").strip()
    )[:1800]
    return (
        "https://image.pollinations.ai/prompt/"
        + quote_plus(clean_prompt)
        + f"?width={width}&height={height}&model={quote_plus(model)}&seed={seed}&nologo=true&private=true&safe=true"
    )


async def _xau_ollama_generate(prompt: str, *, model: str = None, images: list = None, timeout: float = None) -> str:
    """Calls local Ollama. 100% free in API cost because it runs on your machine/server."""
    base = os.getenv("OLLAMA_BASE_URL", "http://127.0.0.1:11434").rstrip("/")
    model = model or os.getenv("XAU_LOCAL_TEXT_MODEL", "llama3.1:8b")
    payload = {"model": model, "prompt": prompt, "stream": False}
    if images:
        payload["images"] = images
    timeout = timeout or float(os.getenv("XAU_OLLAMA_TIMEOUT", "90"))
    async with aiohttp.ClientSession() as session:
        async with session.post(f"{base}/api/generate", json=payload, timeout=timeout) as resp:
            txt = await resp.text()
            if resp.status >= 400:
                raise RuntimeError(f"Ollama HTTP {resp.status}: {txt[:300]}")
            try:
                data = json.loads(txt)
            except Exception:
                return txt.strip()
            return str(data.get("response") or data.get("message", {}).get("content") or "").strip()


async def _xau_pollinations_text(prompt: str, *, timeout: float = 60) -> str:
    """Optional no-key text fallback. Not guaranteed unlimited; local Ollama remains the recommended 100% free route."""
    from urllib.parse import quote_plus
    url = "https://text.pollinations.ai/" + quote_plus(prompt[:3000])
    async with aiohttp.ClientSession() as session:
        async with session.get(url, timeout=timeout) as resp:
            if resp.status >= 400:
                raise RuntimeError(f"Pollinations text HTTP {resp.status}")
            return (await resp.text()).strip()


async def _xau_free_text(prompt: str, *, system: str = "", timeout: float = None) -> str:
    full = (system.strip() + "\n\n" if system else "") + str(prompt or "").strip()
    # Primero local. Si Ollama no está encendido, intenta Pollinations como red gratuita.
    try:
        return await _xau_ollama_generate(full, model=os.getenv("XAU_LOCAL_TEXT_MODEL", "llama3.1:8b"), timeout=timeout or 75)
    except Exception as ollama_exc:
        if str(os.getenv("XAU_ALLOW_POLLINATIONS_TEXT", "1")).lower() in {"1", "true", "yes", "on"}:
            try:
                return await _xau_pollinations_text(full, timeout=timeout or 60)
            except Exception as poll_exc:
                return f"No pude usar IA gratis ahora. Ollama: {type(ollama_exc).__name__}. Pollinations: {type(poll_exc).__name__}."
        return f"Ollama local no responde: {type(ollama_exc).__name__}: {str(ollama_exc)[:180]}"


async def _xau_analyze_image_attachment(att: discord.Attachment, prompt: str = "") -> str:
    """Free image understanding through local Ollama + LLaVA. No OpenAI key needed."""
    try:
        _, raw = await _xau_read_attachment_b64(att, max_bytes=int(os.getenv("XAU_VISION_MAX_BYTES", "8000000")))
        b64 = _xau_base64.b64encode(raw).decode("ascii")
        model = os.getenv("XAU_LOCAL_VISION_MODEL", "llava:7b")
        user_prompt = prompt.strip() or "Describe esta imagen para un servidor de Discord: contenido, detalles, texto visible y si parece apropiada. Responde en español."
        result = await _xau_ollama_generate(user_prompt, model=model, images=[b64], timeout=float(os.getenv("XAU_VISION_TIMEOUT", "120")))
        if result:
            state = _xau_living_state(); state.setdefault("stats", {})["images_analyzed"] = int(state.setdefault("stats", {}).get("images_analyzed", 0)) + 1; _xau_living_save(state)
            _xau_emotion_apply("image", 0.04)
            return result[:3900]
        return "El modelo local de visión respondió vacío. Prueba `ollama pull llava:7b` y vuelve a intentarlo."
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return (
            "No pude analizar la imagen con IA gratis local. Para activarlo al 100% gratis instala Ollama y ejecuta: "
            "`ollama pull llava:7b`. Error: "
            f"`{type(exc).__name__}: {str(exc)[:180]}`"
        )


async def _xau_transcribe_audio_attachment(att: discord.Attachment) -> str:
    """Free local speech-to-text with faster-whisper. No paid API."""
    global _XAU_FW_MODEL
    try:
        _, raw = await _xau_read_attachment_b64(att, max_bytes=int(os.getenv("XAU_STT_MAX_BYTES", "24000000")))
        suffix = os.path.splitext(att.filename or "audio.mp3")[1] or ".mp3"
        temp_path = os.path.join(XAU_MEDIA_CACHE_DIR, f"stt_free_{int(time.time()*1000)}{suffix}")
        with open(temp_path, "wb") as f:
            f.write(raw)

        def _run_stt(path: str) -> str:
            global _XAU_FW_MODEL
            from faster_whisper import WhisperModel
            if _XAU_FW_MODEL is None:
                model_name = os.getenv("XAU_LOCAL_WHISPER_MODEL", "base")
                device = os.getenv("XAU_LOCAL_WHISPER_DEVICE", "cpu")
                compute_type = os.getenv("XAU_LOCAL_WHISPER_COMPUTE", "int8")
                _XAU_FW_MODEL = WhisperModel(model_name, device=device, compute_type=compute_type)
            segments, info = _XAU_FW_MODEL.transcribe(path, language=os.getenv("XAU_STT_LANGUAGE", "es"), vad_filter=True)
            return " ".join(seg.text.strip() for seg in segments if getattr(seg, "text", "").strip()).strip()

        try:
            text = await asyncio.wait_for(asyncio.to_thread(_run_stt, temp_path), timeout=float(os.getenv("XAU_STT_TIMEOUT", "180")))
        finally:
            with _xau_contextlib.suppress(Exception):
                os.remove(temp_path)
        state = _xau_living_state(); state.setdefault("stats", {})["audios_transcribed"] = int(state.setdefault("stats", {}).get("audios_transcribed", 0)) + 1; _xau_living_save(state)
        _xau_emotion_apply("audio", 0.04)
        return text or "No detecté voz clara en el audio."
    except ModuleNotFoundError:
        return "Para transcribir gratis 100% instala `faster-whisper`: `pip install faster-whisper`. No usa OpenAI ni API de pago."
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return f"No pude transcribir con IA local gratuita: `{type(exc).__name__}: {str(exc)[:180]}`"


async def _xau_generate_image(prompt: str) -> tuple:
    """Free image generation through Pollinations. No OpenAI key needed."""
    provider = os.getenv("XAU_IMAGE_PROVIDER", "pollinations").lower().strip()
    if provider not in {"pollinations", "free", "gratis"}:
        provider = "pollinations"
    url = _xau_pollinations_image_url(prompt)
    out = os.path.join(XAU_MEDIA_CACHE_DIR, f"xau_free_image_{int(time.time()*1000)}.png")
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(url, timeout=float(os.getenv("XAU_IMAGE_TIMEOUT", "120"))) as resp:
                raw = await resp.read()
                ctype = (resp.headers.get("content-type") or "").lower()
                if resp.status >= 400:
                    return None, f"Pollinations devolvió HTTP {resp.status}."
                if not raw or ("image" not in ctype and len(raw) < 10000):
                    return None, "El proveedor gratuito no devolvió una imagen válida. Inténtalo de nuevo con otro prompt."
        with open(out, "wb") as f:
            f.write(raw)
        state = _xau_living_state(); state.setdefault("stats", {})["images_generated"] = int(state.setdefault("stats", {}).get("images_generated", 0)) + 1; _xau_living_save(state)
        _xau_emotion_apply("image", 0.04)
        return out, None
    except Exception as exc:
        _xau_emotion_apply("failed_tool", 0.06)
        return None, f"No pude generar imagen gratis ahora: `{type(exc).__name__}: {str(exc)[:180]}`"


