# ║ X AETHER ULTRA 3.5.2 · FREE/CREDIT API ROUTER                              ║
# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║ Cloud API alternatives to OpenAI. This block uses direct HTTP via aiohttp,   ║
# ║ so AETHER does not need the OpenAI API. Some providers expose OpenAI-style   ║
# ║ compatible endpoints, but the key/provider is NOT OpenAI.                   ║
# ║                                                                            ║
# ║ Recommended order for 0€ / free-tier testing:                               ║
# ║   XAU_API_PROVIDER_ORDER=groq,openrouter_free,gemini,mistral,huggingface,   ║
# ║                          pollinations,ollama,deepseek                      ║
# ║                                                                            ║
# ║ Optional API keys:                                                          ║
# ║   GROQ_API_KEY=...              # Free tier, rate-limited                   ║
# ║   OPENROUTER_API_KEY=...        # Use openrouter/free router                ║
# ║   GEMINI_API_KEY=...            # Google AI Studio free tier                ║
# ║   MISTRAL_API_KEY=...           # Mistral Experiment/free tier              ║
# ║   HF_TOKEN=...                  # Hugging Face Inference Providers          ║
# ║   DEEPSEEK_API_KEY=...          # Not permanent-free; cheap/free credits    ║
# ║                                                                            ║
# ║ No-key fallback: Pollinations text/image. Local fallback: Ollama.           ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

_XAU_FREEAPI_VERSION = "3.5.2"
_XAU_PREVIOUS_PROVIDER_PLAN = globals().get("_xaether_provider_plan")
_XAU_PREVIOUS_CALL_PROVIDER = globals().get("_xaether_call_provider")
_XAU_FREE_API_CURSOR = {}


def _xau_env(name: str, default: str = "") -> str:
    return str(os.getenv(name, default) or "").strip()


def _xau_messages_to_text(messages: list, limit: int = 12000) -> str:
    parts = []
    for m in messages or []:
        if not isinstance(m, dict):
            continue
        role = str(m.get("role") or "user").upper()
        content = str(m.get("content") or "").strip()
        if content:
            parts.append(f"{role}: {content}")
    return _xaether_safe_text("\n".join(parts), limit) if "_xaether_safe_text" in globals() else "\n".join(parts)[:limit]


def _xau_messages_for_chat(messages: list) -> list:
    clean = []
    for m in messages or []:
        if not isinstance(m, dict):
            continue
        role = str(m.get("role") or "user").strip().lower()
        if role not in {"system", "user", "assistant"}:
            role = "user"
        content = str(m.get("content") or "").strip()
        if content:
            clean.append({"role": role, "content": content})
    return clean or [{"role": "user", "content": "Responde en español."}]


async def _xau_http_json(session, method: str, url: str, *, headers=None, json_payload=None, params=None, timeout=45):
    async with session.request(method, url, headers=headers or {}, json=json_payload, params=params, timeout=timeout) as resp:
        text = await resp.text()
        if resp.status >= 400:
            raise RuntimeError(f"HTTP {resp.status}: {text[:350]}")
        try:
            return json.loads(text)
        except Exception:
            return {"_raw": text}


def _xau_extract_openai_style(data: dict) -> str:
    try:
        choice = (data.get("choices") or [{}])[0]
        msg = choice.get("message") or {}
        content = msg.get("content")
        if isinstance(content, list):
            return "".join(str(x.get("text") or x.get("content") or "") if isinstance(x, dict) else str(x) for x in content).strip()
        return str(content or choice.get("text") or "").strip()
    except Exception:
        return ""


async def _xau_call_openai_compatible_http(base_url: str, api_key: str, model: str, messages: list, *, extra_headers=None, timeout=45) -> str:
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    if extra_headers:
        headers.update(extra_headers)
    payload = {
        "model": model,
        "messages": _xau_messages_for_chat(messages),
        "temperature": float(_xau_env("XAU_API_TEMPERATURE", "0.75")),
        "max_tokens": int(_xau_env("XAU_API_MAX_TOKENS", "900")),
    }
    async with aiohttp.ClientSession() as session:
        data = await _xau_http_json(session, "POST", base_url.rstrip("/") + "/chat/completions", headers=headers, json_payload=payload, timeout=timeout)
    result = _xau_extract_openai_style(data)
    if not result:
        raise RuntimeError("respuesta vacía")
    return result


async def _xau_call_groq_api(messages: list, model: str) -> str:
    key = _xau_env("GROQ_API_KEY")
    if not key:
        raise RuntimeError("falta GROQ_API_KEY")
    model = model or _xau_env("XAU_GROQ_FREE_MODEL", "llama-3.1-8b-instant")
    return await _xau_call_openai_compatible_http("https://api.groq.com/openai/v1", key, model, messages, timeout=float(_xau_env("XAU_GROQ_TIMEOUT", "35")))


async def _xau_call_openrouter_free(messages: list, model: str) -> str:
    key = _xau_env("OPENROUTER_API_KEY")
    if not key:
        raise RuntimeError("falta OPENROUTER_API_KEY")
    model = model or _xau_env("XAU_OPENROUTER_FREE_MODEL", "openrouter/free")
    headers = {
        "HTTP-Referer": _xau_env("XAU_OPENROUTER_REFERER", "https://discord.com"),
        "X-Title": _xau_env("XAU_OPENROUTER_TITLE", "X AETHER ULTRA"),
    }
    return await _xau_call_openai_compatible_http("https://openrouter.ai/api/v1", key, model, messages, extra_headers=headers, timeout=float(_xau_env("XAU_OPENROUTER_TIMEOUT", "45")))


async def _xau_call_gemini_api(messages: list, model: str) -> str:
    key = _xau_env("GEMINI_API_KEY") or _xau_env("GOOGLE_API_KEY") or _xau_env("GOOGLE_AI_API_KEY")
    if not key:
        raise RuntimeError("falta GEMINI_API_KEY")
    model = model or _xau_env("XAU_GEMINI_MODEL", "gemini-2.0-flash")
    system_parts = []
    contents = []
    for m in _xau_messages_for_chat(messages):
        role = m["role"]
        text = m["content"]
        if role == "system":
            system_parts.append(text)
        else:
            contents.append({"role": "model" if role == "assistant" else "user", "parts": [{"text": text}]})
    payload = {
        "contents": contents or [{"role": "user", "parts": [{"text": _xau_messages_to_text(messages)}]}],
        "generationConfig": {"temperature": float(_xau_env("XAU_API_TEMPERATURE", "0.75")), "maxOutputTokens": int(_xau_env("XAU_API_MAX_TOKENS", "900"))},
    }
    if system_parts:
        payload["systemInstruction"] = {"parts": [{"text": "\n".join(system_parts)}]}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
    async with aiohttp.ClientSession() as session:
        data = await _xau_http_json(session, "POST", url, params={"key": key}, json_payload=payload, timeout=float(_xau_env("XAU_GEMINI_TIMEOUT", "45")))
    try:
        return "".join(part.get("text", "") for part in data["candidates"][0]["content"].get("parts", [])).strip()
    except Exception:
        raise RuntimeError("Gemini respondió vacío")


async def _xau_call_mistral_api(messages: list, model: str) -> str:
    key = _xau_env("MISTRAL_API_KEY")
    if not key:
        raise RuntimeError("falta MISTRAL_API_KEY")
    model = model or _xau_env("XAU_MISTRAL_MODEL", "mistral-small-latest")
    return await _xau_call_openai_compatible_http("https://api.mistral.ai/v1", key, model, messages, timeout=float(_xau_env("XAU_MISTRAL_TIMEOUT", "45")))


async def _xau_call_huggingface_api(messages: list, model: str) -> str:
    key = _xau_env("HF_TOKEN") or _xau_env("HUGGINGFACEHUB_API_TOKEN") or _xau_env("HUGGINGFACE_API_KEY")
    if not key:
        raise RuntimeError("falta HF_TOKEN")
    model = model or _xau_env("XAU_HF_MODEL", "meta-llama/Llama-3.1-8B-Instruct:novita")
    return await _xau_call_openai_compatible_http("https://router.huggingface.co/v1", key, model, messages, timeout=float(_xau_env("XAU_HF_TIMEOUT", "55")))


async def _xau_call_deepseek_api(messages: list, model: str) -> str:
    key = _xau_env("DEEPSEEK_API_KEY")
    if not key:
        raise RuntimeError("falta DEEPSEEK_API_KEY")
    model = model or _xau_env("XAU_DEEPSEEK_MODEL", "deepseek-chat")
    # DeepSeek is not guaranteed permanent-free. It is kept as optional cheap/free-credit fallback.
    return await _xau_call_openai_compatible_http("https://api.deepseek.com/v1", key, model, messages, timeout=float(_xau_env("XAU_DEEPSEEK_TIMEOUT", "45")))


async def _xau_call_pollinations_api(messages: list, model: str) -> str:
    prompt = _xau_messages_to_text(messages, 3000)
    if "_xau_pollinations_text" in globals():
        return await _xau_pollinations_text(prompt, timeout=float(_xau_env("XAU_POLLINATIONS_TIMEOUT", "60")))
    from urllib.parse import quote_plus
    url = "https://text.pollinations.ai/" + quote_plus(prompt)
    async with aiohttp.ClientSession() as session:
        async with session.get(url, timeout=float(_xau_env("XAU_POLLINATIONS_TIMEOUT", "60"))) as resp:
            if resp.status >= 400:
                raise RuntimeError(f"Pollinations HTTP {resp.status}")
            return (await resp.text()).strip()


async def _xau_call_ollama_local(messages: list, model: str) -> str:
    if "_xau_ollama_generate" not in globals():
        raise RuntimeError("Ollama helper no disponible")
    model = model or _xau_env("XAU_LOCAL_TEXT_MODEL", "llama3.1:8b")
    return await _xau_ollama_generate(_xau_messages_to_text(messages), model=model, timeout=float(_xau_env("XAU_OLLAMA_TIMEOUT", "90")))


def _xau_provider_enabled(provider: str) -> bool:
    provider = provider.lower().strip()
    key_map = {
        "groq": "GROQ_API_KEY",
        "openrouter_free": "OPENROUTER_API_KEY",
        "openrouter": "OPENROUTER_API_KEY",
        "gemini": "GEMINI_API_KEY",
        "mistral": "MISTRAL_API_KEY",
        "huggingface": "HF_TOKEN",
        "hf": "HF_TOKEN",
        "deepseek": "DEEPSEEK_API_KEY",
        "pollinations": "",
        "ollama": "",
    }
    key = key_map.get(provider, "")
    if provider == "gemini":
        return bool(_xau_env("GEMINI_API_KEY") or _xau_env("GOOGLE_API_KEY") or _xau_env("GOOGLE_AI_API_KEY"))
    if provider in {"huggingface", "hf"}:
        return bool(_xau_env("HF_TOKEN") or _xau_env("HUGGINGFACEHUB_API_TOKEN") or _xau_env("HUGGINGFACE_API_KEY"))
    return True if not key else bool(_xau_env(key))


def _xaether_provider_plan() -> list[tuple[str, str]]:
    """Free/API provider plan. Adds Groq/OpenRouter Free/Gemini/Mistral/HF/Pollinations without OpenAI API."""
    order_raw = _xau_env("XAU_API_PROVIDER_ORDER", "groq,openrouter_free,gemini,mistral,huggingface,pollinations,ollama,deepseek")
    order = [p.strip().lower() for p in order_raw.split(",") if p.strip()]
    model_defaults = {
        "groq": _xau_env("XAU_GROQ_FREE_MODEL", "llama-3.1-8b-instant"),
        "openrouter_free": _xau_env("XAU_OPENROUTER_FREE_MODEL", "openrouter/free"),
        "openrouter": _xau_env("XAU_OPENROUTER_FREE_MODEL", "openrouter/free"),
        "gemini": _xau_env("XAU_GEMINI_MODEL", "gemini-2.0-flash"),
        "mistral": _xau_env("XAU_MISTRAL_MODEL", "mistral-small-latest"),
        "huggingface": _xau_env("XAU_HF_MODEL", "meta-llama/Llama-3.1-8B-Instruct:novita"),
        "hf": _xau_env("XAU_HF_MODEL", "meta-llama/Llama-3.1-8B-Instruct:novita"),
        "pollinations": _xau_env("XAU_POLLINATIONS_TEXT_MODEL", "pollinations-free"),
        "ollama": _xau_env("XAU_LOCAL_TEXT_MODEL", "llama3.1:8b"),
        "deepseek": _xau_env("XAU_DEEPSEEK_MODEL", "deepseek-chat"),
    }
    plan = []
    for provider in order:
        if _xau_provider_enabled(provider):
            plan.append((provider, model_defaults.get(provider, "default")))
    # Keep legacy providers as a final safety net, but avoid duplicate entries.
    if callable(_XAU_PREVIOUS_PROVIDER_PLAN):
        try:
            for p, m in _XAU_PREVIOUS_PROVIDER_PLAN():
                key = (p, m)
                if key not in plan:
                    plan.append(key)
        except Exception:
            pass
    return plan


async def _xaether_call_provider(provider: str, model: str, mensajes: list) -> str:
    start = time.perf_counter()
    provider_norm = str(provider or "").lower().strip()
    try:
        if provider_norm == "groq":
            result = await asyncio.wait_for(_xau_call_groq_api(mensajes, model), timeout=float(_xau_env("XAU_GROQ_TIMEOUT", "35")))
        elif provider_norm in {"openrouter", "openrouter_free"}:
            result = await asyncio.wait_for(_xau_call_openrouter_free(mensajes, model), timeout=float(_xau_env("XAU_OPENROUTER_TIMEOUT", "45")))
        elif provider_norm == "gemini":
            result = await asyncio.wait_for(_xau_call_gemini_api(mensajes, model), timeout=float(_xau_env("XAU_GEMINI_TIMEOUT", "45")))
        elif provider_norm == "mistral":
            result = await asyncio.wait_for(_xau_call_mistral_api(mensajes, model), timeout=float(_xau_env("XAU_MISTRAL_TIMEOUT", "45")))
        elif provider_norm in {"huggingface", "hf"}:
            result = await asyncio.wait_for(_xau_call_huggingface_api(mensajes, model), timeout=float(_xau_env("XAU_HF_TIMEOUT", "55")))
        elif provider_norm == "pollinations":
            result = await asyncio.wait_for(_xau_call_pollinations_api(mensajes, model), timeout=float(_xau_env("XAU_POLLINATIONS_TIMEOUT", "60")))
        elif provider_norm == "ollama":
            result = await asyncio.wait_for(_xau_call_ollama_local(mensajes, model), timeout=float(_xau_env("XAU_OLLAMA_TIMEOUT", "90")))
        elif provider_norm == "deepseek":
            result = await asyncio.wait_for(_xau_call_deepseek_api(mensajes, model), timeout=float(_xau_env("XAU_DEEPSEEK_TIMEOUT", "45")))
        elif callable(_XAU_PREVIOUS_CALL_PROVIDER):
            result = await _XAU_PREVIOUS_CALL_PROVIDER(provider, model, mensajes)
        else:
            raise RuntimeError(f"Proveedor desconocido: {provider}")
        latency = time.perf_counter() - start
        if "_xaether_record_provider_metric" in globals():
            _xaether_record_provider_metric(provider_norm, model, latency, True)
        return str(result or "").strip()
    except Exception as exc:
        latency = time.perf_counter() - start
        if "_xaether_record_provider_metric" in globals():
            _xaether_record_provider_metric(provider_norm, model, latency, False, repr(exc))
        if "ouroboros_tick" in globals():
            with _xau_contextlib.suppress(Exception):
                ouroboros_tick("error_ia", {"provider": provider_norm, "model": model, "error": type(exc).__name__})
        raise


async def _xau_free_text(prompt: str, *, system: str = "", timeout: float = None) -> str:
    """Uses the configured free/credit API chain first, with Pollinations/Ollama fallback. No OpenAI API."""
    messages = []
    if system:
        messages.append({"role": "system", "content": system})
    messages.append({"role": "user", "content": str(prompt or "")})
    errors = []
    for provider, model in _xaether_provider_plan():
        try:
            return await asyncio.wait_for(_xaether_call_provider(provider, model, messages), timeout=timeout or float(_xau_env("XAU_FREE_TEXT_TIMEOUT", "70")))
        except Exception as exc:
            errors.append(f"{provider}:{type(exc).__name__}")
            continue
    return "No pude usar ninguna API gratuita/configurada ahora. Revisa `!ia_gratis`. Errores: " + ", ".join(errors[-6:])


