@commands.cooldown(1, 6, commands.BucketType.guild)
async def xau_setcanal(ctx, tipo: str = None, canal: Optional[discord.TextChannel] = None):
    """Set configurable channels per server."""
    if not await xau_public_require_admin(ctx):
        return
    if not tipo:
        keys = ", ".join(f"`{k}`" for k in sorted(set(XAU_CHANNEL_KEYS.keys())))
        await ctx.reply(embed=xau_public_embed("Uso de setcanal", f"`!setcanal <tipo> #canal`\nTipos: {keys}"))
        return
    key = XAU_CHANNEL_KEYS.get(tipo.lower().strip())
