@bot.command(name="setia", aliases=["configia", "ia_config"])
@commands.cooldown(1, 8, commands.BucketType.guild)
async def xau_setia(ctx, clave: str = None, *, valor: str = None):
    """Configure AI and image provider per server."""
    if not await xau_public_require_admin(ctx):
        return
    allowed = {
        "imagen": "image_provider",
        "image": "image_provider",
        "modelo_imagen": "image_model",
        "image_model": "image_model",
        "estilo": "image_style",
        "style": "image_style",
        "orden_imagen": "image_provider_order",
        "orden_texto": "text_provider_order",
        "autonomia": "autonomy_enabled",
        "sin_mencion": "respond_without_mention",
        "solo_canal_ia": "allowed_ai_channels_only",
    }
    if not clave or valor is None:
        await ctx.reply(embed=xau_public_embed(
            "Uso de setia",
            "`!setia imagen pollinations`\n"
            "`!setia orden_imagen pollinations,aihorde,huggingface,cloudflare`\n"
            "`!setia modelo_imagen flux`\n"
            "`!setia estilo realista cinematográfico 4k`\n"
            "`!setia autonomia on`\n"
            "`!setia sin_mencion off`\n\n"
            "Claves: " + ", ".join(f"`{k}`" for k in allowed.keys())
        ))
        return
    field = allowed.get(clave.lower().strip())
    if not field:
        await ctx.reply(embed=xau_public_embed("Clave IA desconocida", "Usa `!setia` sin argumentos para ver las claves."))
        return
    cfg = await xau_get_guild_config(ctx.guild.id)
    ai = cfg.setdefault("ai", {})
    raw = valor.strip()
    if field in {"autonomy_enabled", "respond_without_mention", "allowed_ai_channels_only"}:
        value = raw.lower() in {"on", "true", "1", "si", "sí", "activar", "activado", "yes"}
    else:
        value = raw
    if field == "image_provider" and str(value).lower() not in XAU_FREE_IMAGE_PROVIDERS:
        await ctx.reply(embed=xau_public_embed("Proveedor no soportado", f"Soportados: {', '.join(f'`{x}`' for x in XAU_FREE_IMAGE_PROVIDERS)}"))
        return
    ai[field] = value
    await xau_save_guild_config(ctx.guild.id, cfg)
    await ctx.reply(embed=xau_public_embed("IA configurada", f"`{field}` = `{value}`", guild=ctx.guild), mention_author=False)

