def xau_public_enhance_image_prompt(prompt: str, cfg: dict) -> str:
    """Improve user prompt for better image generation while keeping intent."""
    ai = cfg.get("ai", {}) if isinstance(cfg, dict) else {}
    style = ai.get("image_style") or "realista, detallado, alta calidad"
    clean = re.sub(r"\s+", " ", str(prompt or "")).strip()
    if not clean:
        clean = "X AETHER ULTRA, avatar de inteligencia artificial amatista"
    # Prompt injector with Spanish-friendly directives.
    return (
        f"{clean}. "
        f"Estilo: {style}. "
        "Calidad alta, composición clara, iluminación cuidada, detalles definidos, sin texto deformado, sin marcas de agua."
    )[:1200]

async def xau_download_url_to_discord_file(url: str, filename: str = "xau_imagen.png") -> Optional[discord.File]:
    """Download a generated image and return a Discord file."""
    timeout = aiohttp.ClientTimeout(total=120)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.get(url) as resp:
            if resp.status >= 400:
                raise RuntimeError(f"HTTP {resp.status}: {await resp.text()[:200]}")
            data = await resp.read()
    if not data or len(data) < 1024:
        raise RuntimeError("La API devolvió una imagen vacía o inválida.")
    return discord.File(io.BytesIO(data), filename=filename)

async def xau_image_pollinations(prompt: str, cfg: dict) -> discord.File:
    """Generate image via Pollinations GET API."""
    from urllib.parse import quote_plus
    ai = cfg.get("ai", {})
    model = ai.get("image_model") or os.getenv("XAU_POLLINATIONS_IMAGE_MODEL", "flux")
    width = int(ai.get("image_width") or 1024)
    height = int(ai.get("image_height") or 1024)
    seed = random.randint(1, 999999999)
    enhance = "true" if ai.get("image_enhance", True) else "false"
    key = os.getenv("POLLINATIONS_API_KEY", "").strip()
    key_q = f"&key={quote_plus(key)}" if key else ""
    # gen.pollinations.ai is the current documented host for image URLs.
    url = (
        "https://gen.pollinations.ai/image/"
        f"{quote_plus(prompt)}?model={quote_plus(model)}&width={width}&height={height}"
        f"&seed={seed}&enhance={enhance}&nologo=true{key_q}"
    )
    return await xau_download_url_to_discord_file(url, "xau_pollinations.png")

async def xau_image_ai_horde(prompt: str, cfg: dict) -> discord.File:
    """Generate image via AI Horde. Anonymous works but can be slow."""
    api_key = os.getenv("AI_HORDE_API_KEY", "0000000000").strip() or "0000000000"
    width = int(cfg.get("ai", {}).get("image_width") or 1024)
    height = int(cfg.get("ai", {}).get("image_height") or 1024)
    payload = {
        "prompt": prompt,
        "params": {
            "width": min(max(width, 512), 1024),
            "height": min(max(height, 512), 1024),
            "steps": 25,
            "n": 1,
            "sampler_name": "k_euler_a",
            "cfg_scale": 7.5,
        },
        "nsfw": False,
        "censor_nsfw": True,
        "trusted_workers": False,
        "models": [os.getenv("AI_HORDE_IMAGE_MODEL", "stable_diffusion")],
        "r2": True,
    }
    headers = {"apikey": api_key, "Client-Agent": "X-AETHER-ULTRA:3.6.0:Markelson"}
    timeout = aiohttp.ClientTimeout(total=180)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.post("https://aihorde.net/api/v2/generate/async", json=payload, headers=headers) as resp:
            if resp.status >= 400:
                raise RuntimeError(f"AI Horde submit HTTP {resp.status}: {(await resp.text())[:250]}")
            submit = await resp.json()
        job_id = submit.get("id")
        if not job_id:
            raise RuntimeError("AI Horde no devolvió ID de generación.")
        for _ in range(45):
            await asyncio.sleep(3)
            async with session.get(f"https://aihorde.net/api/v2/generate/status/{job_id}", headers=headers) as resp:
                if resp.status >= 400:
                    continue
                status = await resp.json()
            gens = status.get("generations") or []
            if gens:
                img_url = gens[0].get("img")
                if not img_url:
                    raise RuntimeError("AI Horde terminó sin URL de imagen.")
                return await xau_download_url_to_discord_file(img_url, "xau_aihorde.webp")
        raise TimeoutError("AI Horde tardó demasiado. Prueba otra vez o usa Pollinations.")

async def xau_image_huggingface(prompt: str, cfg: dict) -> discord.File:
    """Generate image via Hugging Face Inference Providers/Inference API."""
    token = os.getenv("HF_TOKEN", "").strip()
    if not token:
        raise RuntimeError("Falta HF_TOKEN.")
    model = os.getenv("HF_IMAGE_MODEL", "black-forest-labs/FLUX.1-schnell")
    url = f"https://api-inference.huggingface.co/models/{model}"
    headers = {"Authorization": f"Bearer {token}", "Accept": "image/png"}
    payload = {"inputs": prompt}
    timeout = aiohttp.ClientTimeout(total=150)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.post(url, json=payload, headers=headers) as resp:
            data = await resp.read()
            ctype = resp.headers.get("content-type", "")
            if resp.status >= 400:
                raise RuntimeError(f"Hugging Face HTTP {resp.status}: {data[:250]!r}")
            if "image" not in ctype:
                # Some providers return JSON with generated image URL/base64.
                try:
                    js = json.loads(data.decode("utf-8", "ignore"))
                    if isinstance(js, dict) and js.get("error"):
                        raise RuntimeError(js.get("error"))
                except Exception:
                    pass
                raise RuntimeError("Hugging Face no devolvió una imagen directa.")
    return discord.File(io.BytesIO(data), filename="xau_huggingface.png")

async def xau_image_cloudflare(prompt: str, cfg: dict) -> discord.File:
    """Generate image via Cloudflare Workers AI."""
    account = os.getenv("CF_ACCOUNT_ID", "").strip()
    token = os.getenv("CF_API_TOKEN", "").strip()
    if not account or not token:
        raise RuntimeError("Faltan CF_ACCOUNT_ID y/o CF_API_TOKEN.")
    model = os.getenv("CF_IMAGE_MODEL", "@cf/black-forest-labs/flux-1-schnell")
    url = f"https://api.cloudflare.com/client/v4/accounts/{account}/ai/run/{model}"
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    payload = {"prompt": prompt}
    timeout = aiohttp.ClientTimeout(total=120)
    async with aiohttp.ClientSession(timeout=timeout) as session:
        async with session.post(url, json=payload, headers=headers) as resp:
            data = await resp.read()
            if resp.status >= 400:
                raise RuntimeError(f"Cloudflare HTTP {resp.status}: {data[:250]!r}")
            # Some CF image models return raw image bytes; others JSON with base64.
            ctype = resp.headers.get("content-type", "")
            if "image" in ctype:
                return discord.File(io.BytesIO(data), filename="xau_cloudflare.png")
            js = json.loads(data.decode("utf-8", "ignore"))
            result = js.get("result", js)
            b64 = result.get("image") or result.get("b64_json") if isinstance(result, dict) else None
            if not b64:
                raise RuntimeError("Cloudflare no devolvió imagen reconocible.")
            import base64
            return discord.File(io.BytesIO(base64.b64decode(b64)), filename="xau_cloudflare.png")

async def xau_generate_image_free_router(prompt: str, cfg: dict) -> tuple[discord.File, str]:
    """Free/free-tier image router with fallback order controlled per guild."""
    ai = cfg.get("ai", {})
    order_raw = ai.get("image_provider_order") or ai.get("image_provider") or "pollinations,aihorde,huggingface,cloudflare"
    order = [x.strip().lower() for x in str(order_raw).split(",") if x.strip()]
    preferred = str(ai.get("image_provider") or "").strip().lower()
    if preferred and preferred in XAU_FREE_IMAGE_PROVIDERS and preferred not in order:
        order.insert(0, preferred)
    errors = []
    for provider in order:
        try:
            if provider == "pollinations":
                return await xau_image_pollinations(prompt, cfg), "Pollinations"
            if provider in {"aihorde", "stablehorde", "ai_horde"}:
                return await xau_image_ai_horde(prompt, cfg), "AI Horde"
            if provider in {"huggingface", "hf"}:
                return await xau_image_huggingface(prompt, cfg), "Hugging Face"
            if provider in {"cloudflare", "cf"}:
                return await xau_image_cloudflare(prompt, cfg), "Cloudflare Workers AI"
        except Exception as exc:
            errors.append(f"{provider}: {exc}")
            continue
    raise RuntimeError("Todos los proveedores de imagen fallaron:\n" + "\n".join(errors[-6:]))

@bot.command(name="imagen", aliases=["img", "generarimagen", "crearimagen", "imagine"])
@commands.cooldown(1, 30, commands.BucketType.user)
async def xau_imagen_free_public(ctx, *, prompt: str = None):
    """Generate image using free/free-tier providers configured per server."""
    if not prompt:
        await ctx.reply(embed=xau_public_embed(
            "Crear imagen",
            "`!imagen <descripción>`\nEjemplo: `!imagen humano futurista con armadura amatista, realista, 4k`"
        ))
        return
    cfg = await xau_get_guild_config(ctx.guild.id if ctx.guild else 0)
    features = cfg.get("features", {})
    if features.get("imagenes", True) is False:
        await ctx.reply(embed=xau_public_embed("Imágenes desactivadas", "Un administrador desactivó el módulo de imágenes en este servidor."))
        return
    max_chars = int(cfg.get("limits", {}).get("max_image_prompt_chars") or 900)
    if len(prompt) > max_chars:
        prompt = prompt[:max_chars]
    public_prompt = xau_public_enhance_image_prompt(prompt, cfg)
    thinking = await ctx.reply(embed=xau_public_embed(
        "Generando imagen",
        "🎨 Estoy creando la imagen con proveedor gratis/free-tier.\n"
        f"Prompt mejorado:\n```{public_prompt[:900]}```",
        guild=ctx.guild,
    ), mention_author=False)
    try:
        image_file, provider_label = await asyncio.wait_for(xau_generate_image_free_router(public_prompt, cfg), timeout=190)
        embed = xau_public_embed(
            "Imagen generada",
            f"Proveedor: **{provider_label}**\nAutor: {ctx.author.mention}\nPrompt original:\n```{prompt[:900]}```",
            guild=ctx.guild,
        )
        await thinking.edit(embed=embed, attachments=[image_file])
    except Exception as exc:
        embed = xau_public_embed(
            "No pude generar la imagen",
            "Probé los proveedores configurados y fallaron o tardaron demasiado.\n\n"
            f"Error técnico:\n```{str(exc)[:1200]}```\n\n"
            "Prueba:\n`!setia imagen pollinations`\n`!setia orden_imagen pollinations,aihorde,huggingface,cloudflare`",
            color=0xE74C3C,
            guild=ctx.guild,
        )
        try:
            await thinking.edit(embed=embed)
        except Exception:
            await ctx.reply(embed=embed)

@bot.listen("on_guild_join")
async def xau_public_on_guild_join(guild: discord.Guild):
    """Initialize config when the bot joins a public server."""
    try:
        cfg = await xau_get_guild_config(guild.id)
        await xau_save_guild_config(guild.id, cfg)
        target = None
        for ch in guild.text_channels:
            if ch.permissions_for(guild.me).send_messages:
                target = ch
                break
        if target:
            embed = xau_public_embed(
                "Gracias por invitar a X AETHER ULTRA",
                "Soy público y configurable por servidor.\n\n"
                "Primeros pasos:\n"
                "`!setup_publico` → panel de configuración\n"
                "`!setcanal bienvenida #canal`\n"
                "`!setrol staff @rol`\n"
                "`!setia imagen pollinations`\n"
                "`!proveedores_imagen` → APIs de imagen gratis/free-tier",
                guild=guild,
            )
            await target.send(embed=embed)
    except Exception as exc:
        print(f"[X AETHER PUBLIC] on_guild_join error: {exc!r}")

