def _xau_help_to_dict(value):
    """Normalize any old help shape into a clean dictionary."""
    if isinstance(value, dict):
        return {str(k): str(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return {str(v): "Comando disponible." for v in value}
    if value is None:
        return {}
    return {str(value): "Función disponible."}


def _xau_help_command_description(command):
    """Build a human readable description from command metadata."""
    desc = getattr(command, "help", None) or getattr(command, "brief", None)
    if not desc and getattr(command, "callback", None) and getattr(command.callback, "__doc__", None):
        desc = command.callback.__doc__.strip().split("\n")[0]
    desc = str(desc or "Comando disponible.").strip()
    aliases = [str(a) for a in list(getattr(command, "aliases", []) or []) if a]
    if aliases:
        desc += "\nAlias: " + ", ".join(f"`!{a}`" for a in aliases[:10])
    return desc


def _xau_help_guess_category(command_name: str) -> str:
    """Guess the best help category for a command name."""
    n = str(command_name or "").lower().strip().lstrip("!/")
    for category, names in XAU_HELP_CATEGORY_KEYWORDS.items():
        if n in names or any(n.startswith(x + "_") for x in names):
            return category
    return "otros"


def xau_sync_help_catalog() -> dict:
    """Rebuild COMMAND_CATEGORIES from manual catalog + live prefix + slash commands."""
    global COMMAND_CATEGORIES
    if not isinstance(COMMAND_CATEGORIES, dict):
        COMMAND_CATEGORIES = {}

    normalized = {}
    for category, value in list(COMMAND_CATEGORIES.items()):
        key = str(category or "otros").lower().strip() or "otros"
        normalized.setdefault(key, {}).update(_xau_help_to_dict(value))

    for category, entries in XAU_HELP_PUBLIC_COMMANDS.items():
        normalized.setdefault(category, {}).update(entries)

    seen_names = set()
    for data in normalized.values():
        for key in data:
            token = str(key).split()[0].lower().lstrip("!/")
            if token:
                seen_names.add(token)

    for command in sorted(bot.commands, key=lambda c: c.name.lower()):
        if getattr(command, "hidden", False):
            continue
        name = str(command.name).lower()
        category = _xau_help_guess_category(name)
        aliases = [str(a).lower() for a in list(getattr(command, "aliases", []) or [])]
        if name not in seen_names:
            normalized.setdefault(category, {})[f"!{command.name}"] = _xau_help_command_description(command)
            seen_names.add(name)
        for alias in aliases:
            seen_names.add(alias)

    try:
        slash_commands = bot.tree.get_commands()
    except Exception:
        slash_commands = []
    for slash in sorted(slash_commands, key=lambda c: c.name.lower()):
        name = str(getattr(slash, "name", "")).lower().strip()
        if not name:
            continue
        key = f"/{name}"
        desc = str(getattr(slash, "description", "Comando slash disponible.") or "Comando slash disponible.")
        normalized.setdefault("slash", {})[key] = desc

    COMMAND_CATEGORIES = dict(sorted(normalized.items(), key=lambda item: item[0]))
    return COMMAND_CATEGORIES


def _xau_help_find_category(raw: str | None) -> str:
    """Resolve a typed category/search to a known help category."""
    xau_sync_help_catalog()
    if not raw:
        return "inicio"
    q = str(raw).lower().strip()
    if q in {"inicio", "home", "menu", "menú"}:
        return "inicio"
    categories = list(COMMAND_CATEGORIES.keys())
    matches = [c for c in categories if c.lower() == q]
    matches += [c for c in categories if c.lower().startswith(q) and c not in matches]
    matches += [c for c in categories if q in c.lower() and c not in matches]
    if matches:
        return matches[0]
    return "inicio"


def _xau_help_pages(entries, per_page: int = 8):
    pages = []
    entries = list(entries)
    for i in range(0, len(entries), per_page):
        pages.append(entries[i:i + per_page])
    return pages or [[]]


def _xau_help_embed(author=None, guild=None, category: str = "inicio", page: int = 0, search: str | None = None):
    """Build the public synchronized help embed."""
    xau_sync_help_catalog()
    color = 0x9B5CFF
    if category == "inicio":
        total_prefix = len([c for c in bot.commands if not getattr(c, "hidden", False)])
        try:
            total_slash = len(bot.tree.get_commands())
        except Exception:
            total_slash = 0
        embed = discord.Embed(
            title="📚 X AETHER ULTRA · Ayuda sincronizada",
            description=(
                f"{XAU_HELP_LINE}\n"
                "Catálogo reconstruido en tiempo real con comandos prefix, aliases, slash commands y módulos públicos.\n"
                f"{XAU_HELP_LINE}"
            ),
            color=color,
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.add_field(name="⚙️ Prefix", value=f"**{total_prefix}** comandos", inline=True)
        embed.add_field(name="⚡ Slash", value=f"**{total_slash}** comandos", inline=True)
        embed.add_field(name="🧩 Categorías", value=f"**{len(COMMAND_CATEGORIES)}**", inline=True)
        for cat, data in COMMAND_CATEGORIES.items():
            sample = " · ".join(list(data.keys())[:4]) or "Sin entradas"
            embed.add_field(name=f"💠 {cat.title()} · {len(data)}", value=sample[:950], inline=True)
        embed.add_field(name="🔎 Buscar", value="`!comandos imagen` · `!comandos setcanal` · `!comandos blackjack`", inline=False)
        embed.add_field(name="🌍 Setup público", value="`!setup_publico` · `!config_aether` · `!setcanal` · `!setrol` · `!setia`", inline=False)
    else:
        entries = list(COMMAND_CATEGORIES.get(category, {}).items())
        pages = _xau_help_pages(entries, 8)
        page = max(0, min(int(page or 0), len(pages) - 1))
        embed = discord.Embed(
            title=f"📜 Ayuda · {category.title()}",
            description=f"Página **{page + 1}/{len(pages)}** · **{len(entries)}** entradas\n{XAU_HELP_LINE}",
            color=color,
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        for name, desc in pages[page]:
            embed.add_field(name=str(name)[:256], value=str(desc)[:1000], inline=False)
    if author:
        try:
            embed.set_thumbnail(url=author.display_avatar.url)
        except Exception:
            pass
        embed.set_footer(text=f"X AETHER ULTRA · Ayuda pública sincronizada v{XAU_HELP_SYNC_VERSION}", icon_url=getattr(getattr(author, "display_avatar", None), "url", None))
    else:
        embed.set_footer(text=f"X AETHER ULTRA · Ayuda pública sincronizada v{XAU_HELP_SYNC_VERSION}")
    return embed


class XAUHelpSyncSelect(discord.ui.Select):
    def __init__(self, parent: "XAUHelpSyncView"):
        self.parent_view = parent
        xau_sync_help_catalog()
        emojis = {
            "publico": "🌍", "aether": "🧠", "ayuda": "📚", "minijuegos": "🎮",
            "economia": "💎", "tienda": "🛒", "moderacion": "🛡️", "tickets": "🎫",
            "streams": "🔴", "miembros": "👑", "slash": "⚡", "utilidades": "🧰", "otros": "📦",
        }
        options = [discord.SelectOption(label="Inicio", value="inicio", emoji="🏠", description="Menú general")]
        for cat in list(COMMAND_CATEGORIES.keys())[:24]:
            options.append(discord.SelectOption(
                label=cat.title()[:100],
                value=cat,
                emoji=emojis.get(cat, "📌"),
                description=f"{len(COMMAND_CATEGORIES.get(cat, {}))} entradas"[:100],
                default=(cat == parent.category),
            ))
        super().__init__(placeholder="📚 Cambiar categoría", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        self.parent_view.category = self.values[0]
        self.parent_view.page = 0
        await self.parent_view.redraw(interaction)


class XAUHelpSyncView(discord.ui.View):
    def __init__(self, author_id: int, guild=None, category: str = "inicio", page: int = 0):
        super().__init__(timeout=240)
        self.author_id = author_id
        self.guild = guild
        self.category = category if category in COMMAND_CATEGORIES else "inicio"
        self.page = max(0, int(page or 0))
        self.add_item(XAUHelpSyncSelect(self))
        self._update_button_state()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Abre tu propio panel con `!ayuda` o `/ayuda`.", ephemeral=True)
            return False
        return True

    def _max_page(self) -> int:
        if self.category == "inicio":
            return 0
        entries = list(COMMAND_CATEGORIES.get(self.category, {}).items())
        return max(0, len(_xau_help_pages(entries, 8)) - 1)

    def _update_button_state(self):
        max_page = self._max_page()
        for child in self.children:
            if isinstance(child, discord.ui.Button):
                if child.custom_id == "xau_help_prev":
                    child.disabled = self.page <= 0
                elif child.custom_id == "xau_help_next":
                    child.disabled = self.page >= max_page

    async def redraw(self, interaction: discord.Interaction):
        xau_sync_help_catalog()
        self.page = max(0, min(self.page, self._max_page()))
        self._update_button_state()
        embed = _xau_help_embed(author=interaction.user, guild=interaction.guild, category=self.category, page=self.page)
        await interaction.response.edit_message(embed=embed, view=self)

    @discord.ui.button(label="Inicio", emoji="🏠", style=discord.ButtonStyle.secondary, custom_id="xau_help_home", row=1)
    async def home(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.category = "inicio"
        self.page = 0
        await self.redraw(interaction)

    @discord.ui.button(label="Anterior", emoji="⬅️", style=discord.ButtonStyle.primary, custom_id="xau_help_prev", row=1)
    async def prev(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page -= 1
        await self.redraw(interaction)

    @discord.ui.button(label="Siguiente", emoji="➡️", style=discord.ButtonStyle.primary, custom_id="xau_help_next", row=1)
    async def next(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page += 1
        await self.redraw(interaction)

    @discord.ui.button(label="Sincronizar", emoji="🔄", style=discord.ButtonStyle.success, custom_id="xau_help_sync", row=1)
    async def sync(self, interaction: discord.Interaction, button: discord.ui.Button):
        xau_sync_help_catalog()
        await self.redraw(interaction)


