@bot.command(name="comandos", aliases=["buscarcomando"])
@commands.cooldown(1, 4, commands.BucketType.user)
async def xau_comandos_public_sync(ctx, *, busqueda: str = None):
    """Busca comandos sincronizados por nombre, alias, categoría o descripción."""
    xau_sync_help_catalog()
    if not busqueda:
        return await xau_ayuda_public_sync(ctx)
    q = busqueda.lower().strip()
    results = []
    for cat, data in COMMAND_CATEGORIES.items():
        for name, desc in data.items():
            hay = f"{cat} {name} {desc}".lower()
            if q in hay:
                results.append((cat, name, desc))
    embed = discord.Embed(
        title=f"🔎 Comandos encontrados · {busqueda}",
        description=f"{len(results)} resultado(s). Usa `!ayuda <categoría>` para ver páginas completas.",
        color=0x9B5CFF,
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    for cat, name, desc in results[:15]:
        embed.add_field(name=f"{name} · {cat}", value=str(desc)[:900], inline=False)
    if len(results) > 15:
        embed.add_field(name="Más resultados", value=f"Hay {len(results) - 15} más. Afina la búsqueda.", inline=False)
    embed.set_footer(text=f"X AETHER ULTRA · Buscador sincronizado v{XAU_HELP_SYNC_VERSION}")
    await ctx.reply(embed=embed, mention_author=False)


