def _xau_public_safe_int(value, default=0):
    try:
        return int(value or default)
    except Exception:
        return int(default or 0)


def _xau_public_file_exists(name: str) -> bool:
    try:
        return os.path.exists(os.path.join(BASE_DIR, name))
    except Exception:
        return False


def _xau_public_migrate_legacy_files() -> list[str]:
    """Copies old private-branded JSON files to public names without deleting old data."""
    moved = []
    for old, new in XAU_LEGACY_FILE_MIGRATIONS.items():
        old_path = os.path.join(BASE_DIR, old)
        new_path = os.path.join(BASE_DIR, new)
        try:
            if os.path.exists(old_path) and not os.path.exists(new_path):
                import shutil as _xau_shutil
                _xau_shutil.copy2(old_path, new_path)
                moved.append(f"{old} → {new}")
        except Exception as exc:
            print(f"[XAU PUBLIC MIGRATION] No se pudo migrar {old}: {exc!r}")
    return moved


async def _xau_public_channel(guild: discord.Guild, key: str):
    """Returns a configured channel from xau_guild_config.json, never from old fixed IDs."""
    if not guild:
        return None
    try:
        cfg = await xau_get_guild_config(guild.id)
        cid = ((cfg.get("channels") or {}).get(key) or None)
        return guild.get_channel(int(cid)) if cid else None
    except Exception:
        return None


async def _xau_public_role(guild: discord.Guild, key: str):
    """Returns a configured role from xau_guild_config.json, never from old fixed IDs."""
    if not guild:
        return None
    try:
        cfg = await xau_get_guild_config(guild.id)
        rid = ((cfg.get("roles") or {}).get(key) or None)
        return guild.get_role(int(rid)) if rid else None
    except Exception:
        return None


async def _xau_public_feature_enabled(guild: discord.Guild, feature: str, default: bool = False) -> bool:
    if not guild:
        return False
    try:
        cfg = await xau_get_guild_config(guild.id)
        return bool((cfg.get("features") or {}).get(feature, default))
    except Exception:
        return bool(default)


