@bot.event
async def on_ready():
    """Public on_ready: no private server automation, no forced panels, no hardcoded channels."""
    print("\n" + "═" * 70)
    print("🌍 X AETHER ULTRA PUBLIC CORE 3.6.2")
    print("✅ Modo multi-servidor: sin configuración privada precargada")
    print("🧭 Configura cada servidor con: !setup_publico / !setcanal / !setrol / !setia")
    print("═" * 70 + "\n")

    _xau_public_migrate_legacy_files()

    try:
        synced = await bot.tree.sync()
        print(f"🌐 Slash commands globales sincronizados: {len(synced)}")
    except Exception as exc:
        print(f"[XAU PUBLIC] Error sincronizando slash commands: {exc!r}")

    try:
        await bot.change_presence(
            activity=discord.Game(name="bot público · usa !setup_publico"),
            status=discord.Status.online,
        )
    except Exception:
        pass

    global _ia_semaphore, _reactroles, ai_user_history, groq_async_client, deepseek_async_client
    _ia_semaphore = asyncio.Semaphore(3)

    try:
        _reactroles = _cargar_reactroles()
        print(f"[REACTROLES] {len(_reactroles)} reactrole(s) cargado(s).")
    except Exception as exc:
        print(f"[REACTROLES] carga fallida: {exc!r}")

    try:
        ai_user_history = cargar_historial_ia()
        print(f"[IA HIST] Historial cargado: {len(ai_user_history)} usuario(s).")
    except Exception as exc:
        print(f"[IA HIST] carga fallida: {exc!r}")

    try:
        if GROQ_API_KEY:
            groq_async_client = AsyncGroq(api_key=GROQ_API_KEY)
        if DEEPSEEK_API_KEY:
            deepseek_async_client = AsyncOpenAI(api_key=DEEPSEEK_API_KEY, base_url="https://api.deepseek.com")
    except Exception as exc:
        print(f"[IA CLIENTS] inicialización parcial: {exc!r}")

    try:
        if not getattr(bot, "http_session", None) or getattr(bot.http_session, "closed", False):
            bot.http_session = aiohttp.ClientSession()
    except Exception as exc:
        print(f"[HTTP] No se pudo crear sesión aiohttp: {exc!r}")

    try:
        datos = cargar_datos()
        for guild in bot.guilds:
            for member in guild.members:
                if not member.bot:
                    asegurar_usuario(datos, str(member.id))
        guardar_datos(datos)
    except Exception as exc:
        print(f"[DATOS] inicialización parcial: {exc!r}")

    # Safe background loops only. No automatic ticket/stream/welcome panel creation.
    try:
        if "interes_bancario" in globals() and not interes_bancario.is_running():
            interes_bancario.start()
    except Exception as exc:
        print(f"[LOOP] interes_bancario no iniciado: {exc!r}")

    try:
        if "check_streams_loop" in globals() and not check_streams_loop.is_running():
            check_streams_loop.start()
            print("🔴 Loop de streams iniciado en modo público: solo publicará si el servidor configuró canal.")
    except Exception as exc:
        print(f"[LOOP] streams no iniciado: {exc!r}")

    try:
        xau_sync_help_catalog()
    except Exception as exc:
        print(f"[HELP] sync inicial fallida: {exc!r}")

    await _xau_public_send_startup_log()
    print(f"✅ Online como {bot.user} en {len(bot.guilds)} servidor(es).")


@bot.event
async def on_member_join(member: discord.Member):
    """Public welcome: only sends if this guild explicitly configured welcome channel/module."""
    if not member.guild or member.bot:
        return
    try:
        if await _xau_public_feature_enabled(member.guild, "welcome", False):
            channel = await _xau_public_channel(member.guild, "welcome_channel_id")
            if channel:
                embed = xau_public_embed(
                    f"🎉 Bienvenido/a {member.name}",
                    f"Hola {member.mention}, bienvenido/a a **{member.guild.name}**.",
                    guild=member.guild,
                )
                embed.set_thumbnail(url=member.display_avatar.url)
                await channel.send(embed=embed)
        role = await _xau_public_role(member.guild, "member_role_id")
        if role and await _xau_public_feature_enabled(member.guild, "auto_role", False):
            await member.add_roles(role, reason="X AETHER ULTRA public configured auto-role")
    except discord.Forbidden:
        print(f"[XAU PUBLIC WELCOME] Sin permisos en {member.guild.name}")
    except Exception as exc:
        print(f"[XAU PUBLIC WELCOME] {member.guild.name}: {exc!r}")


