# ║ X AETHER ULTRA 3.6.3 · EDITABLE PER-GUILD CURRENCY CORE                    ║
# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║ Public bots cannot ship with one fixed economy name/emoji. This layer       ║
# ║ stores a custom currency per Discord server in xau_guild_config.json.        ║
# ║ Admins can change emoji, singular and plural names without editing code.     ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

try:
    import contextvars as _xau_currency_contextvars
except Exception:
    _xau_currency_contextvars = None

XAU_PUBLIC_CURRENCY_VERSION = "3.6.3"
XAU_DEFAULT_CURRENCY = {
    "emoji": "💎",
    "name": "cristal",
    "plural": "cristales",
    "symbol_after_amount": True,
}

# Keeps the current guild id inside the async task executing a command. This is
# safer than relying on one global mutable emoji when many servers use the bot.
if _xau_currency_contextvars is not None:
    XAU_CURRENT_GUILD_ID = _xau_currency_contextvars.ContextVar("xau_current_guild_id", default=0)
else:
    XAU_CURRENT_GUILD_ID = None

XAU_CURRENCY_CACHE = {}
XAU_CURRENCY_CACHE_MTIME = 0.0


def _xau_currency_normalize(value) -> dict:
    """Normalize legacy/missing currency config without breaking JSON files."""
    base = dict(XAU_DEFAULT_CURRENCY)
    if isinstance(value, dict):
        base.update({k: v for k, v in value.items() if v is not None})
    # Accept common old fields if someone manually edited the file.
    if isinstance(value, dict):
        if value.get("currency_emoji"):
            base["emoji"] = value.get("currency_emoji")
        if value.get("currency_name"):
            base["name"] = value.get("currency_name")
        if value.get("currency_plural"):
            base["plural"] = value.get("currency_plural")
    base["emoji"] = str(base.get("emoji") or XAU_DEFAULT_CURRENCY["emoji"]).strip()[:80]
    base["name"] = str(base.get("name") or XAU_DEFAULT_CURRENCY["name"]).strip()[:40]
    base["plural"] = str(base.get("plural") or (base["name"] + "s")).strip()[:45]
    base["symbol_after_amount"] = bool(base.get("symbol_after_amount", True))
    return base


def _xau_currency_read_all_sync() -> dict:
    """Sync read for tiny config lookups used inside formatting helpers."""
    global XAU_CURRENCY_CACHE, XAU_CURRENCY_CACHE_MTIME
    try:
        path = str(globals().get("XAU_GUILD_CONFIG_FILE") or os.path.join(BASE_DIR, "xau_guild_config.json"))
        if not os.path.exists(path):
            XAU_CURRENCY_CACHE = {}
            XAU_CURRENCY_CACHE_MTIME = 0.0
            return {}
        mtime = os.path.getmtime(path)
        if XAU_CURRENCY_CACHE and XAU_CURRENCY_CACHE_MTIME == mtime:
            return XAU_CURRENCY_CACHE
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        if not isinstance(data, dict):
            data = {}
        XAU_CURRENCY_CACHE = data
        XAU_CURRENCY_CACHE_MTIME = mtime
        return data
    except Exception as exc:
        print(f"[XAU CURRENCY] No se pudo leer configuración de moneda: {exc!r}")
        return XAU_CURRENCY_CACHE if isinstance(XAU_CURRENCY_CACHE, dict) else {}


def _xau_current_guild_id(default: int = 0) -> int:
    """Return current command guild id from contextvars."""
    try:
        if XAU_CURRENT_GUILD_ID is not None:
            return int(XAU_CURRENT_GUILD_ID.get() or default or 0)
    except Exception:
        pass
    return int(default or 0)


def xau_currency_for_guild_id(guild_id: int = 0) -> dict:
    """Return currency config for one guild. Safe for sync formatting helpers."""
    gid = str(int(guild_id or 0))
    data = _xau_currency_read_all_sync()
    cfg = data.get(gid, {}) if isinstance(data, dict) else {}
    if not isinstance(cfg, dict):
        cfg = {}
    economy = cfg.get("economy", {})
    theme = cfg.get("theme", {})
    # Backward compatibility: if someone saved currency under theme.
    if not economy and isinstance(theme, dict) and theme.get("currency"):
        economy = {"currency": theme.get("currency")}
    currency = economy.get("currency", economy) if isinstance(economy, dict) else {}
    return _xau_currency_normalize(currency)


def xau_currency_for_ctx(ctx=None) -> dict:
    """Return currency config from ctx/guild/member if available, otherwise task context."""
    gid = 0
    try:
        # Accept commands.Context, discord.Interaction-like objects, Guild, Member, User fallback.
        if isinstance(ctx, discord.Guild):
            gid = int(ctx.id)
        elif getattr(ctx, "guild", None) is not None:
            gid = int(getattr(ctx.guild, "id", 0) or 0)
        elif getattr(getattr(ctx, "message", None), "guild", None) is not None:
            gid = int(getattr(ctx.message.guild, "id", 0) or 0)
    except Exception:
        gid = 0
    if not gid:
        gid = _xau_current_guild_id(0)
    return xau_currency_for_guild_id(gid)


def xau_currency_amount(amount, ctx=None, *, with_name: bool = False, plural_auto: bool = True) -> str:
    """Format a money amount using the server's custom currency."""
    cur = xau_currency_for_ctx(ctx)
    try:
        n = int(amount)
        number = f"{n:,}".replace(",", ".")
    except Exception:
        n = None
        number = str(amount)
    emoji = cur.get("emoji", "💎")
    if with_name:
        word = cur.get("name", "cristal") if n == 1 and plural_auto else cur.get("plural", "cristales")
        return f"{number} {emoji} {word}" if cur.get("symbol_after_amount", True) else f"{emoji} {number} {word}"
    return f"{number} {emoji}" if cur.get("symbol_after_amount", True) else f"{emoji} {number}"


def xau_currency_word(ctx=None, plural: bool = True) -> str:
    cur = xau_currency_for_ctx(ctx)
    return str(cur.get("plural" if plural else "name", "cristales"))


def xau_currency_emoji(ctx=None) -> str:
    return str(xau_currency_for_ctx(ctx).get("emoji", "💎"))

# Patch the most-used money helpers used by the layered minigames/shop UI. Older
# direct strings still work, but every command using these helpers becomes fully
# per-guild without editing thousands of lines.
def _amethyst(n: int, ctx=None) -> str:  # noqa: F811
    return xau_currency_amount(n, ctx)


def _amx_emoji_money(ctx=None) -> str:  # noqa: F811
    return xau_currency_emoji(ctx)

