def xau_public_default_config(guild_id: int = 0) -> dict:  # noqa: F811
    base = _XAU_ORIGINAL_PUBLIC_DEFAULT_CONFIG_CURRENCY(guild_id) if callable(_XAU_ORIGINAL_PUBLIC_DEFAULT_CONFIG_CURRENCY) else {}
    if not isinstance(base, dict):
        base = {}
    base.setdefault("economy", {})
    base["economy"].setdefault("currency", dict(XAU_DEFAULT_CURRENCY))
    base["economy"].setdefault("cash_label", "cash")
    base["economy"].setdefault("bank_label", "banco")
    return base

async def xau_get_currency_config(guild_id: int) -> dict:
    """Async version used by setup commands."""
    cfg = await xau_get_guild_config(int(guild_id or 0))
    economy = cfg.setdefault("economy", {})
    cur = _xau_currency_normalize(economy.get("currency", {}))
    economy["currency"] = cur
    return cur

async def xau_set_currency_config(guild_id: int, emoji: str = None, name: str = None, plural: str = None) -> dict:
    """Save custom per-server currency and refresh local sync cache."""
    cfg = await xau_get_guild_config(int(guild_id or 0))
    economy = cfg.setdefault("economy", {})
    current = _xau_currency_normalize(economy.get("currency", {}))
    if emoji is not None:
        current["emoji"] = str(emoji).strip()[:80]
    if name is not None:
        current["name"] = str(name).strip()[:40]
    if plural is not None:
        current["plural"] = str(plural).strip()[:45]
    economy["currency"] = _xau_currency_normalize(current)
    await xau_save_guild_config(int(guild_id or 0), cfg)
    try:
        # Force reload after atomic write.
        global XAU_CURRENCY_CACHE_MTIME
        XAU_CURRENCY_CACHE_MTIME = 0.0
        _xau_currency_read_all_sync()
    except Exception:
        pass
    return economy["currency"]

