_XAU_ORIGINAL_PUBLIC_DEFAULT_CONFIG_MEMBERSHIP = globals().get("xau_public_default_config")

def xau_public_default_config(guild_id: int = 0) -> dict:
    """Adds editable membership defaults to the existing public guild config."""
    if callable(_XAU_ORIGINAL_PUBLIC_DEFAULT_CONFIG_MEMBERSHIP):
        base = _XAU_ORIGINAL_PUBLIC_DEFAULT_CONFIG_MEMBERSHIP(guild_id)
    else:
        base = {"guild_id": int(guild_id or 0)}
    if not isinstance(base, dict):
        base = {"guild_id": int(guild_id or 0)}
    base.setdefault("channels", {})
    base["channels"].setdefault("membership_channel_id", None)
    base["channels"].setdefault("membership_log_channel_id", None)
    base.setdefault("roles", {})
    base["roles"].setdefault("member_role_id", None)
    base["roles"].setdefault("royal_role_id", None)
    base["roles"].setdefault("vip_role_id", None)
    base["roles"].setdefault("staff_role_id", None)
    base.setdefault("features", {})
    base["features"].setdefault("membresia", True)
    base["features"].setdefault("miembros", True)
    base.setdefault("membership", xau_default_membership_config())
    base["membership"] = xau_deep_merge_public(xau_default_membership_config(), base.get("membership") or {}) if "xau_deep_merge_public" in globals() else base["membership"]
    return base


async def xau_membership_db() -> dict:
    """Load membership request database with backward-safe shape."""
    data = await xau_public_read_json(XAU_PUBLIC_MEMBERSHIP_FILE, default=dict)
    if not isinstance(data, dict):
        data = {}
    data.setdefault("requests", {})
    data.setdefault("user_index", {})
    data.setdefault("version", XAU_PUBLIC_MEMBERSHIP_VERSION)
    return data


async def xau_membership_save(db: dict) -> bool:
    """Save membership database atomically."""
    if not isinstance(db, dict):
        db = {}
    db.setdefault("requests", {})
    db.setdefault("user_index", {})
    db["version"] = XAU_PUBLIC_MEMBERSHIP_VERSION
    return await xau_public_write_json(XAU_PUBLIC_MEMBERSHIP_FILE, db)


async def xau_membership_config(guild: discord.Guild) -> dict:
    """Return normalized membership settings for a guild."""
    cfg = await xau_get_guild_config(guild.id if guild else 0)
    mem = cfg.setdefault("membership", {})
    mem = xau_deep_merge_public(xau_default_membership_config(), mem) if "xau_deep_merge_public" in globals() else mem
    cfg["membership"] = mem
    return mem


async def xau_membership_admin_allowed(obj) -> bool:
    """Check whether a Context/Interaction user can moderate membership."""
    guild = getattr(obj, "guild", None)
    user = getattr(obj, "author", None) or getattr(obj, "user", None)
    if not guild or not user:
        return False
    if getattr(user, "id", 0) == globals().get("MI_ID"):
        return True
    perms = getattr(user, "guild_permissions", None)
    if perms and (perms.administrator or perms.manage_guild or perms.manage_roles):
        return True
    try:
        cfg = await xau_get_guild_config(guild.id)
        staff_id = ((cfg.get("roles") or {}).get("staff_role_id") or None)
        if staff_id and any(getattr(r, "id", 0) == int(staff_id) for r in getattr(user, "roles", [])):
            return True
    except Exception:
        pass
    return False


def xau_membership_progress_bar(value: int, total: int = 5, width: int = 10) -> str:
    """Small decorative bar for embeds."""
    try:
        value = max(0, min(int(value), int(total)))
        filled = int((value / max(total, 1)) * width)
        return "▰" * filled + "▱" * (width - filled)
    except Exception:
        return "▱" * width


def xau_membership_id(guild_id: int, user_id: int, kind: str) -> str:
    raw = f"{guild_id}:{user_id}:{kind}:{time.time()}:{random.randint(1000,999999)}"
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12].upper()


def xau_membership_index_key(guild_id: int, user_id: int) -> str:
    return f"{int(guild_id or 0)}:{int(user_id or 0)}"


def xau_membership_status_emoji(status: str) -> str:
    return {"pending": "🟡", "approved": "🟢", "rejected": "🔴", "cancelled": "⚫"}.get(str(status), "⚪")


def xau_membership_request_embed(req: dict, guild: Optional[discord.Guild] = None, *, title: str = None, color: int = None) -> discord.Embed:
    """Build a premium request embed for staff review and user status."""
    kind = req.get("kind", "join")
    status = req.get("status", "pending")
    title = title or ("💎 Solicitud de membresía" if kind == "join" else "🚪 Solicitud de salida")
    color = color if color is not None else (XAU_MEMBER_GOLD if status == "pending" else XAU_MEMBER_OK if status == "approved" else XAU_MEMBER_BAD)
    embed = xau_public_embed(
        title,
        f"{XAU_MEMBER_LINE}\n"
        f"{xau_membership_status_emoji(status)} Estado: **{status.upper()}**\n"
        f"🆔 ID: `{req.get('id')}`\n"
        f"{XAU_MEMBER_LINE}",
        color=color,
        guild=guild,
    )
    embed.add_field(name="👤 Usuario", value=f"<@{req.get('user_id')}>\n`{req.get('user_id')}`", inline=True)
    embed.add_field(name="📌 Tipo", value="Entrada" if kind == "join" else "Salida", inline=True)
    embed.add_field(name="🕒 Fecha", value=f"<t:{int(req.get('created_at', time.time()))}:R>", inline=True)
    answers = req.get("answers") or {}
    embed.add_field(name="🪪 Apodo", value=str(answers.get("name") or "No indicado")[:1024], inline=True)
    embed.add_field(name="🎯 Objetivo", value=str(answers.get("goal") or "No indicado")[:1024], inline=True)
    embed.add_field(name="⚙️ Experiencia", value=str(answers.get("experience") or "No indicado")[:1024], inline=False)
    embed.add_field(name="🧾 Motivo", value=str(answers.get("reason") or "No indicado")[:1024], inline=False)
    extra = str(answers.get("extra") or "").strip()
    if extra:
        embed.add_field(name="✨ Extra", value=extra[:1024], inline=False)
    if req.get("decision_reason"):
        embed.add_field(name="📣 Decisión", value=str(req.get("decision_reason"))[:1024], inline=False)
    embed.add_field(name="🛡️ Control", value="Aprobar/rechazar desde botones o comandos. El bot valida permisos y jerarquía de roles.", inline=False)
    return embed


async def xau_membership_can_request(guild_id: int, user_id: int, kind: str) -> tuple[bool, str]:
    """Anti-spam gate for membership forms."""
    guild = bot.get_guild(int(guild_id or 0))
    mem = await xau_membership_config(guild) if guild else xau_default_membership_config()
    db = await xau_membership_db()
    now = time.time()
    all_reqs = list((db.get("requests") or {}).values())
    user_reqs = [r for r in all_reqs if int(r.get("guild_id") or 0) == int(guild_id or 0) and int(r.get("user_id") or 0) == int(user_id or 0)]
    for req in user_reqs:
        if req.get("kind") == kind and req.get("status") == "pending":
            return False, f"ya tienes una solicitud de **{('entrada' if kind == 'join' else 'salida')}** pendiente: `{req.get('id')}`."
    cooldown = int(mem.get("cooldown_seconds") or 1800)
    recent_same = [r for r in user_reqs if r.get("kind") == kind]
    if recent_same:
        latest = max(float(r.get("created_at", 0) or 0) for r in recent_same)
        remaining = int(cooldown - (now - latest))
        if remaining > 0:
            return False, f"anti-spam activo. Espera **{remaining // 60}m {remaining % 60}s** antes de volver a solicitar."
    max_24h = int(mem.get("max_requests_24h") or 4)
    day_count = len([r for r in user_reqs if now - float(r.get("created_at", 0) or 0) <= 86400])
    if day_count >= max_24h:
        return False, f"has alcanzado el límite de **{max_24h} solicitudes en 24h**."
    return True, "ok"


async def xau_membership_review_channel(guild: discord.Guild):
    """Find the best channel for membership staff review."""
    if not guild:
        return None
    cfg = await xau_get_guild_config(guild.id)
    mem = cfg.get("membership") or {}
    channels = cfg.get("channels") or {}
    for raw in (mem.get("review_channel_id"), channels.get("membership_log_channel_id"), mem.get("log_channel_id"), channels.get("logs_channel_id"), channels.get("membership_channel_id")):
        try:
            channel = guild.get_channel(int(raw)) if raw else None
            if channel:
                return channel
        except Exception:
            pass
    return None


async def xau_membership_create_request(interaction: discord.Interaction, kind: str, answers: dict) -> tuple[bool, str, dict]:
    """Create and persist a membership request."""
    if not interaction.guild:
        return False, "Este sistema solo funciona dentro de servidores.", {}
    mem = await xau_membership_config(interaction.guild)
    if not bool(mem.get("enabled", True)):
        return False, "La membresía está desactivada en este servidor.", {}
    if kind == "leave" and not bool(mem.get("allow_leave_request", True)):
        return False, "Las solicitudes de salida están desactivadas en este servidor.", {}
    ok, reason = await xau_membership_can_request(interaction.guild.id, interaction.user.id, kind)
    if not ok:
        return False, reason, {}
    req_id = xau_membership_id(interaction.guild.id, interaction.user.id, kind)
    req = {
        "id": req_id,
        "guild_id": int(interaction.guild.id),
        "guild_name": str(interaction.guild.name),
        "user_id": int(interaction.user.id),
        "user_name": str(interaction.user),
        "kind": kind,
        "status": "pending",
        "answers": answers or {},
        "created_at": time.time(),
        "created_iso": datetime.datetime.utcnow().isoformat(),
        "decided_at": None,
        "decided_by": None,
        "decision_reason": None,
    }
    db = await xau_membership_db()
    db.setdefault("requests", {})[req_id] = req
    key = xau_membership_index_key(interaction.guild.id, interaction.user.id)
    db.setdefault("user_index", {}).setdefault(key, []).append(req_id)
    await xau_membership_save(db)

    review_channel = await xau_membership_review_channel(interaction.guild)
    if review_channel:
        try:
            embed = xau_membership_request_embed(req, interaction.guild)
            await review_channel.send(embed=embed, view=XAUUniversalMembershipDecisionView(req_id))
        except Exception as exc:
            print(f"[XAU MEMBERSHIP] No se pudo enviar revisión: {exc!r}")
    return True, "solicitud creada", req


async def xau_membership_apply_roles(guild: discord.Guild, member: discord.Member, kind: str) -> tuple[list[str], list[str]]:
    """Apply or remove configured membership roles safely."""
    ok_actions, failed = [], []
    if not guild or not member:
        return ok_actions, ["No encontré el usuario dentro del servidor."]
    cfg = await xau_get_guild_config(guild.id)
    mem = cfg.get("membership") or {}
    if not bool(mem.get("auto_assign_roles", True)):
        return ["Asignación automática de roles desactivada por configuración."], []
    role_ids = []
    roles_cfg = cfg.get("roles") or {}
    for key in ("member_role_id", "royal_role_id", "vip_role_id"):
        rid = roles_cfg.get(key)
        if rid and rid not in role_ids:
            role_ids.append(rid)
    bot_member = guild.me
    for rid in role_ids:
        try:
            role = guild.get_role(int(rid))
            if not role:
                failed.append(f"Rol `{rid}` no encontrado.")
                continue
            if role.managed or (bot_member and role >= bot_member.top_role):
                failed.append(f"No puedo gestionar `{role.name}` por jerarquía o rol gestionado.")
                continue
            if kind == "join" and role not in member.roles:
                await member.add_roles(role, reason="Membresía aprobada por staff")
                ok_actions.append(f"Rol añadido: `{role.name}`")
            elif kind == "leave" and role in member.roles:
                await member.remove_roles(role, reason="Salida de membresía aprobada por staff")
                ok_actions.append(f"Rol retirado: `{role.name}`")
        except Exception as exc:
            failed.append(f"Error con rol `{rid}`: {exc!r}")
    if not ok_actions and not failed:
        ok_actions.append("No había roles configurados para aplicar.")
    return ok_actions, failed


async def xau_membership_decide(guild: discord.Guild, request_id: str, approve: bool, actor, reason: str = "") -> tuple[bool, discord.Embed]:
    """Approve or reject a membership request."""
    db = await xau_membership_db()
    req = (db.get("requests") or {}).get(str(request_id).upper())
    if not req:
        return False, xau_public_embed("Solicitud no encontrada", f"No existe `{request_id}`.", color=XAU_MEMBER_BAD, guild=guild)
    if int(req.get("guild_id") or 0) != int(getattr(guild, "id", 0) or 0):
        return False, xau_public_embed("Servidor incorrecto", "Esta solicitud pertenece a otro servidor.", color=XAU_MEMBER_BAD, guild=guild)
    if req.get("status") != "pending":
        return False, xau_membership_request_embed(req, guild, title="Solicitud ya resuelta")
    req["status"] = "approved" if approve else "rejected"
    req["decided_at"] = time.time()
    req["decided_iso"] = datetime.datetime.utcnow().isoformat()
    req["decided_by"] = int(getattr(actor, "id", 0) or 0)
    req["decision_reason"] = reason or ("Aprobada por el staff." if approve else "Rechazada por el staff.")
    actions, failures = [], []
    member = None
    try:
        member = guild.get_member(int(req.get("user_id"))) or await guild.fetch_member(int(req.get("user_id")))
    except Exception:
        member = None
    if approve and member:
        actions, failures = await xau_membership_apply_roles(guild, member, req.get("kind", "join"))
    db.setdefault("requests", {})[req["id"]] = req
    await xau_membership_save(db)
    embed = xau_membership_request_embed(req, guild, title=("✅ Membresía aprobada" if approve else "❌ Membresía rechazada"), color=(XAU_MEMBER_OK if approve else XAU_MEMBER_BAD))
    if actions:
        embed.add_field(name="✅ Acciones aplicadas", value="\n".join(actions)[:1024], inline=False)
    if failures:
        embed.add_field(name="⚠️ Avisos", value="\n".join(failures)[:1024], inline=False)
    if member:
        try:
            mem = await xau_membership_config(guild)
            if bool(mem.get("dm_results", True)):
                dm_embed = xau_membership_request_embed(req, guild, title=("✅ Solicitud aprobada" if approve else "❌ Solicitud rechazada"), color=(XAU_MEMBER_OK if approve else XAU_MEMBER_BAD))
                await member.send(embed=dm_embed)
        except Exception:
            pass
    return True, embed


