async def xau_membership_status_embed(guild: discord.Guild, member) -> discord.Embed:
    """Build user membership request history."""
    db = await xau_membership_db()
    key = xau_membership_index_key(guild.id if guild else 0, member.id)
    ids = list((db.get("user_index") or {}).get(key, []))[-8:]
    embed = xau_public_embed("Estado de membresía", f"Usuario: {getattr(member, 'mention', member)}", color=XAU_MEMBER_BLUE, guild=guild)
    if not ids:
        embed.add_field(name="Historial", value="No tienes solicitudes registradas en este servidor.", inline=False)
        return embed
    for rid in reversed(ids):
        req = (db.get("requests") or {}).get(rid)
        if not req:
            continue
        embed.add_field(
            name=f"{xau_membership_status_emoji(req.get('status'))} {req.get('kind')} · {rid}",
            value=f"Estado: **{req.get('status')}**\nCreada: <t:{int(req.get('created_at', time.time()))}:R>",
            inline=False,
        )
    return embed


