@bot.command(name="membresia_pendientes", aliases=["solicitudesmiembro", "miembropendientes"])
@commands.cooldown(1, 8, commands.BucketType.guild)
async def xau_membresia_pendientes_public_cmd(ctx):
    """List pending membership requests for this guild."""
    if not await xau_membership_admin_allowed(ctx):
        return await ctx.reply(embed=xau_public_embed("Permisos insuficientes", "Necesitas permisos de staff para ver solicitudes.", color=XAU_MEMBER_BAD, guild=ctx.guild), mention_author=False)
    db = await xau_membership_db()
    pending = [r for r in (db.get("requests") or {}).values() if int(r.get("guild_id") or 0) == int(ctx.guild.id) and r.get("status") == "pending"]
    pending.sort(key=lambda r: float(r.get("created_at", 0) or 0), reverse=True)
    embed = xau_public_embed("Solicitudes pendientes", f"Pendientes en este servidor: **{len(pending)}**", color=XAU_MEMBER_GOLD, guild=ctx.guild)
    if not pending:
        embed.description = "No hay solicitudes pendientes. El buzón está limpio. ✨"
    for req in pending[:12]:
        embed.add_field(name=f"{req.get('kind')} · {req.get('id')}", value=f"<@{req.get('user_id')}> · <t:{int(req.get('created_at', time.time()))}:R>\n`!membresia_aprobar {req.get('id')}` · `!membresia_rechazar {req.get('id')} motivo`", inline=False)
    await ctx.reply(embed=embed, mention_author=False)


