@bot.command(name="membresia_audit", aliases=["auditoria_membresia", "audit_membresia"])
@commands.cooldown(1, 15, commands.BucketType.guild)
async def xau_membresia_audit_public_cmd(ctx):
    """Audit membership setup and warn about missing channels/roles."""
    if not await xau_public_require_admin(ctx):
        return
    cfg = await xau_get_guild_config(ctx.guild.id)
    channels = cfg.get("channels") or {}
    roles = cfg.get("roles") or {}
    mem = cfg.get("membership") or {}
    checks = []
    checks.append(("Panel", bool(channels.get("membership_channel_id") or mem.get("panel_channel_id")), "`!setcanal membresia #canal`"))
    checks.append(("Revisión/logs", bool(channels.get("membership_log_channel_id") or channels.get("logs_channel_id")), "`!setcanal membresia_logs #canal`"))
    checks.append(("Rol miembro", bool(roles.get("member_role_id")), "`!setrol miembro @rol`"))
    checks.append(("Módulo activo", bool((cfg.get("features") or {}).get("membresia", True)), "`!modulo membresia on`"))
    embed = xau_public_embed("Auditoría de membresía", "Revisión del sistema público configurable.", color=XAU_MEMBER_BLUE, guild=ctx.guild)
    for name, ok, fix in checks:
        embed.add_field(name=("✅ " if ok else "⚠️ ") + name, value=("Configurado" if ok else f"Pendiente: {fix}"), inline=True)
    embed.add_field(name="Comandos", value="`!config_membresia` · `!panelmembresia` · `!membresia_pendientes` · `!setmembresia`", inline=False)
    await ctx.reply(embed=embed, mention_author=False)


