def _xau_help_meta(category: str):
    key = str(category or "otros").lower()
    return XAU_HELP_CATEGORY_META.get(key, ("✨", key.title(), 0x9B5CFF))


def _xau_help_clean_text(value, limit: int = 1000) -> str:
    value = str(value or "Disponible.").strip()
    return value[:limit] if len(value) <= limit else value[: limit - 1] + "…"


def _xau_help_normalize_entries(value) -> dict:
    if isinstance(value, dict):
        return {str(k): str(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return {str(v): "Disponible." for v in value}
    if value is None:
        return {}
    return {str(value): "Disponible."}


def _xau_help_command_desc(command) -> str:
    desc = getattr(command, "help", None) or getattr(command, "brief", None)
    callback = getattr(command, "callback", None)
    if not desc and callback is not None:
        doc = getattr(callback, "__doc__", None)
        if doc:
            desc = doc.strip().split("\n")[0]
    desc = str(desc or "Comando disponible.").strip()
    aliases = [a for a in list(getattr(command, "aliases", []) or []) if a]
    if aliases:
        desc += "\nAlias: " + ", ".join(f"`!{a}`" for a in aliases[:12])
    return desc


def _xau_help_guess_category(name: str) -> str:
    n = str(name or "").lower().strip().lstrip("!/")
    checks = {
        "publico": {"setup_publico", "config_aether", "publico_exportar", "publico_reset", "auditoria_publica", "sin_privado"},
        "configuracion": {"setcanal", "setrol", "setprefix", "setia", "modulo", "setmoneda", "moneda", "resetmoneda", "auditoria_moneda"},
        "miembros": {"membresia", "panelmembresia", "config_membresia", "setmembresia", "membresia_estado", "membresia_pendientes", "membresia_aprobar", "membresia_rechazar", "salirmiembro", "membresia_demo", "membresia_audit"},
        "economia": {"bal", "balance", "daily", "trabajar", "depositar", "retirar", "donar", "robar", "crimen", "hackear", "misiones", "prestamo", "inversion", "nomina", "rep"},
        "tienda": {"tienda", "comprar", "usar", "inventario", "equipar", "desequipar", "vender", "ofertas", "coleccion", "xpcard"},
        "minijuegos": {"slots", "maquina", "blackjack", "bj", "poker", "pk", "texasholdem", "holdem", "ruleta", "dado", "ppt", "apostar", "bingo", "tiro", "memoria_juego", "ahorcado", "ruleta_rusa", "adivina", "minas", "carrera", "cofre", "crash", "tesoro", "showcase", "reglas_juego"},
        "aether": {"ia", "chat", "pregunta", "imagen", "analizar_imagen", "audio", "transcribir_audio", "ia_gratis", "aether_vivo", "sentimientos", "autonomia", "mimemoria", "memoriaaether", "aether_evolucion"},
        "moderacion": {"kick", "ban", "clear", "warn", "aviso", "silenciar", "dessilenciar", "slowmode", "reactrole", "addmoney", "removemoney", "setrango"},
        "tickets": {"panelticket", "cerrarticket", "agregarusuario", "ticketstats", "resettickets"},
        "streams": {"addstream", "mystreams", "delstream", "streams", "teststream"},
        "utilidades": {"diagnostico", "ping", "userinfo", "info", "serverinfo", "recordatorio", "encuesta", "meme", "buscar", "top", "ranking", "lb", "coinflip", "8ball"},
    }
    for category, names in checks.items():
        if n in names or any(n.startswith(x + "_") for x in names):
            return category
    return "otros"


def xau_rebuild_help_catalog() -> dict:
    """Build a clean help catalog from manual categories, forced public modules, live prefix and slash commands."""
    global COMMAND_CATEGORIES
    base = {}
    if isinstance(globals().get("COMMAND_CATEGORIES"), dict):
        for category, entries in COMMAND_CATEGORIES.items():
            key = str(category or "otros").lower().strip() or "otros"
            base.setdefault(key, {}).update(_xau_help_normalize_entries(entries))

    for category, entries in XAU_HELP_FORCED_ENTRIES.items():
        base.setdefault(category, {}).update(entries)

    # Pull additions from older help-sync layers if they exist.
    for extra_name in ("XAU_HELP_PUBLIC_COMMANDS",):
        extra = globals().get(extra_name)
        if isinstance(extra, dict):
            for category, entries in extra.items():
                base.setdefault(str(category).lower(), {}).update(_xau_help_normalize_entries(entries))

    for command in sorted(list(getattr(bot, "commands", []) or []), key=lambda c: str(c.name).lower()):
        if getattr(command, "hidden", False):
            continue
        category = _xau_help_guess_category(command.name)
        key = f"!{command.name}"
        base.setdefault(category, {})[key] = _xau_help_command_desc(command)

    try:
        slash_commands = list(bot.tree.get_commands())
    except Exception:
        slash_commands = []
    for slash in sorted(slash_commands, key=lambda c: str(getattr(c, "name", "")).lower()):
        name = str(getattr(slash, "name", "")).strip()
        if not name:
            continue
        desc = str(getattr(slash, "description", "Comando slash disponible.") or "Comando slash disponible.")
        base.setdefault("slash", {})[f"/{name}"] = desc

    # Remove empty categories and sort entries.
    clean = {}
    preferred = ["inicio", "publico", "configuracion", "miembros", "economia", "tienda", "minijuegos", "aether", "ouroboros", "moderacion", "tickets", "streams", "utilidades", "slash", "otros"]
    for category in preferred + sorted(k for k in base.keys() if k not in preferred):
        entries = base.get(category) or {}
        if category == "inicio":
            continue
        if entries:
            clean[category] = dict(sorted(entries.items(), key=lambda item: str(item[0]).lower()))
    COMMAND_CATEGORIES = clean
    return clean


def xau_resolve_help_category(raw: str | None) -> str:
    if not raw:
        return "inicio"
    q = str(raw).lower().strip()
    for canonical, aliases in XAU_HELP_CATEGORY_ALIASES.items():
        if q == canonical or q in aliases:
            return canonical
    catalog = xau_rebuild_help_catalog()
    if q in catalog:
        return q
    starts = [c for c in catalog if c.startswith(q)]
    if starts:
        return starts[0]
    contains = [c for c in catalog if q in c]
    if contains:
        return contains[0]
    return "inicio"


def xau_help_chunks(entries, page_size: int = XAU_HELP_PAGE_SIZE):
    items = list(entries)
    return [items[i:i + page_size] for i in range(0, len(items), page_size)] or [[]]


async def xau_help_context_status(guild: discord.Guild | None) -> str:
    if not guild:
        return "Modo DM · algunos comandos de servidor no aplican."
    try:
        cfg = await xau_get_guild_config(guild.id)
    except Exception:
        cfg = {}
    channels = cfg.get("channels") or {}
    roles = cfg.get("roles") or {}
    membership = cfg.get("membership") or {}
    currency = xau_currency_for_guild_id(guild.id) if "xau_currency_for_guild_id" in globals() else {"emoji": "💎", "plural": "cristales"}
    ready = []
    missing = []
    if channels.get("logs_channel_id"):
        ready.append("logs")
    else:
        missing.append("logs")
    if channels.get("membership_channel_id"):
        ready.append("membresía")
    else:
        missing.append("membresía")
    if roles.get("member_role_id"):
        ready.append("rol miembro")
    else:
        missing.append("rol miembro")
    if (cfg.get("ai") or {}).get("image_provider") or (cfg.get("ai") or {}).get("imagen"):
        ready.append("imagen IA")
    estado = " · ".join(f"✅ {x}" for x in ready[:5]) or "sin módulos configurados"
    falta = " · ".join(f"⚠️ {x}" for x in missing[:3]) if missing else "configuración base completa"
    return f"Moneda: {currency.get('emoji','💎')} {currency.get('plural','cristales')}\n{estado}\n{falta}\nMembresía: {'activa' if membership.get('enabled', True) else 'desactivada'}"


async def xau_build_help_embed(ctx_or_interaction=None, category: str = "inicio", page: int = 0, search: str | None = None):
    catalog = xau_rebuild_help_catalog()
    guild = getattr(ctx_or_interaction, "guild", None)
    user = getattr(ctx_or_interaction, "author", None) or getattr(ctx_or_interaction, "user", None)
    category = xau_resolve_help_category(category)
    emoji, title, color = _xau_help_meta(category)

    if search:
        q = str(search).lower().strip()
        results = []
        for cat, entries in catalog.items():
            for name, desc in entries.items():
                blob = f"{cat} {name} {desc}".lower()
                if q in blob:
                    results.append((cat, name, desc))
        pages = xau_help_chunks(results, 6)
        page = max(0, min(int(page or 0), len(pages) - 1))
        embed = discord.Embed(
            title=f"🔎 Búsqueda de comandos · {search}",
            description=f"{XAU_HELP_SEPARATOR}\nResultados: **{len(results)}** · Página **{page + 1}/{len(pages)}**\n{XAU_HELP_SEPARATOR}",
            color=0x57F287,
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        for cat, name, desc in pages[page]:
            ce, ct, _ = _xau_help_meta(cat)
            embed.add_field(name=f"{ce} {name} · {ct}", value=_xau_help_clean_text(desc, 900), inline=False)
        if not results:
            embed.add_field(name="Sin resultados", value="Prueba `!ayuda`, `!ayuda publico`, `!comandos imagen` o `!comandos membresia`.", inline=False)
    elif category == "inicio":
        try:
            prefix_count = len([c for c in bot.commands if not getattr(c, "hidden", False)])
        except Exception:
            prefix_count = 0
        try:
            slash_count = len(bot.tree.get_commands())
        except Exception:
            slash_count = 0
        status = await xau_help_context_status(guild)
        embed = discord.Embed(
            title="📚 X AETHER ULTRA · Centro de ayuda público",
            description=(
                f"{XAU_HELP_SEPARATOR}\n"
                "Ayuda sincronizada con comandos reales, aliases, slash commands y módulos configurables por servidor.\n"
                f"{XAU_HELP_SEPARATOR}"
            ),
            color=0x9B5CFF,
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.add_field(name="⚙️ Comandos prefix", value=f"**{prefix_count}** cargados", inline=True)
        embed.add_field(name="⚡ Slash", value=f"**{slash_count}** cargados", inline=True)
        embed.add_field(name="🧩 Categorías", value=f"**{len(catalog)}**", inline=True)
        embed.add_field(name="🌍 Estado del servidor", value=status[:1000], inline=False)
        top_categories = ["publico", "configuracion", "miembros", "economia", "tienda", "minijuegos", "aether", "moderacion", "tickets", "streams", "utilidades"]
        for cat in top_categories:
            if cat not in catalog:
                continue
            ce, ct, _ = _xau_help_meta(cat)
            sample = " · ".join(list(catalog[cat].keys())[:4])
            embed.add_field(name=f"{ce} {ct} · {len(catalog[cat])}", value=_xau_help_clean_text(sample or "Sin comandos", 400), inline=True)
        embed.add_field(name="🚀 Inicio recomendado", value="`!setup_publico` → `!setcanal` → `!setrol` → `!setmoneda` → `!panelmembresia`", inline=False)
        embed.add_field(name="🔎 Búsquedas rápidas", value="`!comandos membresia` · `!comandos imagen` · `!comandos moneda` · `!ayuda minijuegos`", inline=False)
    else:
        entries = list(catalog.get(category, {}).items())
        pages = xau_help_chunks(entries)
        page = max(0, min(int(page or 0), len(pages) - 1))
        embed = discord.Embed(
            title=f"{emoji} Ayuda · {title}",
            description=f"{XAU_HELP_SEPARATOR}\nCategoría **{category}** · **{len(entries)}** entradas · Página **{page + 1}/{len(pages)}**\n{XAU_HELP_SEPARATOR}",
            color=color,
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        for name, desc in pages[page]:
            embed.add_field(name=_xau_help_clean_text(name, 250), value=_xau_help_clean_text(desc, 950), inline=False)
        if not entries:
            embed.add_field(name="Categoría vacía", value="Usa `!ayuda` para volver al inicio o `!comandos <búsqueda>`.", inline=False)

    if user:
        try:
            embed.set_thumbnail(url=user.display_avatar.url)
        except Exception:
            pass
    embed.set_footer(text=f"X AETHER ULTRA · Help Center {XAU_HELP_PREMIUM_VERSION} · Usa !sincronizar_ayuda para refrescar")
    return embed


class XAUHelpSelect(discord.ui.Select):
    def __init__(self, current: str = "inicio"):
        catalog = xau_rebuild_help_catalog()
        options = [discord.SelectOption(label="Inicio", value="inicio", emoji="🏠", description="Resumen global y setup recomendado")]
        for cat in list(catalog.keys())[:24]:
            emoji, title, _ = _xau_help_meta(cat)
            options.append(discord.SelectOption(label=title[:100], value=cat[:100], emoji=emoji, description=f"{len(catalog.get(cat, {}))} comandos"[:100]))
        super().__init__(placeholder=f"Categoría actual: {current}", min_values=1, max_values=1, options=options[:25])

    async def callback(self, interaction: discord.Interaction):
        view: XAUHelpView = self.view  # type: ignore
        view.category = self.values[0]
        view.page = 0
        embed = await xau_build_help_embed(interaction, view.category, view.page)
        await interaction.response.edit_message(embed=embed, view=view.refresh())


class XAUHelpView(discord.ui.View):
    def __init__(self, author_id: int = 0, category: str = "inicio", page: int = 0, timeout: int = 180):
        super().__init__(timeout=timeout)
        self.author_id = int(author_id or 0)
        self.category = category or "inicio"
        self.page = int(page or 0)
        self.refresh()

    def refresh(self):
        self.clear_items()
        self.add_item(XAUHelpSelect(self.category))
        self.add_item(XAUHelpButton("⬅️", "prev", discord.ButtonStyle.secondary))
        self.add_item(XAUHelpButton("🏠 Inicio", "home", discord.ButtonStyle.primary))
        self.add_item(XAUHelpButton("➡️", "next", discord.ButtonStyle.secondary))
        self.add_item(XAUHelpButton("🔄 Sync", "sync", discord.ButtonStyle.success))
        return self

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not self.author_id or interaction.user.id == self.author_id:
            return True
        try:
            await interaction.response.send_message("Este panel de ayuda lo abrió otra persona. Usa `!ayuda` para abrir el tuyo.", ephemeral=True)
        except Exception:
            pass
        return False


class XAUHelpButton(discord.ui.Button):
    def __init__(self, label: str, action: str, style: discord.ButtonStyle):
        super().__init__(label=label, style=style)
        self.action = action

    async def callback(self, interaction: discord.Interaction):
        view: XAUHelpView = self.view  # type: ignore
        catalog = xau_rebuild_help_catalog()
        if self.action == "home":
            view.category = "inicio"
            view.page = 0
        elif self.action == "sync":
            xau_rebuild_help_catalog()
            view.page = 0
        else:
            entries = list(catalog.get(view.category, {}).items())
            max_page = max(0, len(xau_help_chunks(entries)) - 1)
            if self.action == "prev":
                view.page = max(0, view.page - 1)
            elif self.action == "next":
                view.page = min(max_page, view.page + 1)
        embed = await xau_build_help_embed(interaction, view.category, view.page)
        await interaction.response.edit_message(embed=embed, view=view.refresh())


