async def _xau_harden_send(ctx_or_channel, *, embed=None, content=None, delete_after=None, mention_author=False, ephemeral=False):
    """Send safely to ctx, interaction, or channel without crashing on missing permissions."""
    try:
        if isinstance(ctx_or_channel, discord.Interaction):
            if ctx_or_channel.response.is_done():
                return await ctx_or_channel.followup.send(content=content, embed=embed, ephemeral=ephemeral)
            return await ctx_or_channel.response.send_message(content=content, embed=embed, ephemeral=ephemeral)
        if hasattr(ctx_or_channel, "reply"):
            return await ctx_or_channel.reply(content=content, embed=embed, delete_after=delete_after, mention_author=mention_author)
        if hasattr(ctx_or_channel, "send"):
            return await ctx_or_channel.send(content=content, embed=embed, delete_after=delete_after)
    except (discord.Forbidden, discord.NotFound) as exc:
        _xau_harden_log("safe_send_discord", exc)
    except discord.HTTPException as exc:
        _xau_harden_log("safe_send_http", exc)
    except Exception as exc:
        _xau_harden_log("safe_send_unknown", exc)
    return None


async def _xau_harden_prefixes(message: discord.Message) -> tuple[str, ...]:
    """Resolve every supported discord.py prefix type into a tuple of strings."""
    import inspect as _inspect
    result = []

    async def push(value):
        if value is None:
            return
        if callable(value):
            try:
                value = value(bot, message)
                if _inspect.isawaitable(value):
                    value = await value
            except Exception as exc:
                _xau_harden_log("prefix_callable", exc)
                return
        if isinstance(value, str):
            if value:
                result.append(value)
            return
        if isinstance(value, (list, tuple, set)):
            for item in value:
                await push(item)

    await push(getattr(bot, "command_prefix", "!"))
    # Mention prefixes are safe fallbacks for public bots.
    with _xau_contextlib.suppress(Exception):
        if getattr(bot, "user", None):
            result.extend([f"<@{bot.user.id}> ", f"<@!{bot.user.id}> "])
    seen = set()
    clean = []
    for item in result or ["!"]:
        if isinstance(item, str) and item and item not in seen:
            clean.append(item)
            seen.add(item)
    return tuple(clean or ("!",))


def _xau_harden_command_report():
    tokens = {}
    collisions = []
    commands_list = []
    try:
        commands_list = list(bot.commands)
    except Exception:
        commands_list = []
    for cmd in commands_list:
        names = [getattr(cmd, "name", "")] + list(getattr(cmd, "aliases", []) or [])
        for name in names:
            if not isinstance(name, str) or not name:
                continue
            key = name.lower()
            owner = getattr(cmd, "qualified_name", getattr(cmd, "name", "?"))
            if key in tokens and tokens[key] != owner:
                collisions.append((key, tokens[key], owner))
            tokens[key] = owner
    return commands_list, collisions


def _xau_harden_sanitize_command_registry():
    """Remove ghost aliases and report active collisions without deleting the newest command blindly."""
    try:
        commands_list, collisions = _xau_harden_command_report()
        # discord.py's command map can contain aliases; ensure every map value is a Command-like object.
        all_commands = getattr(bot, "all_commands", {})
        if isinstance(all_commands, dict):
            for key, value in list(all_commands.items()):
                if not isinstance(key, str) or value is None or not hasattr(value, "callback"):
                    all_commands.pop(key, None)
        if collisions:
            _xau_harden_log("command_collisions_active", collisions[:10])
        return len(commands_list), len(collisions)
    except Exception as exc:
        _xau_harden_log("sanitize_command_registry", exc)
        return 0, -1


async def _xau_harden_process_commands(message: discord.Message):
    try:
        await bot.process_commands(message)
    except Exception as exc:
        _xau_harden_log("process_commands", exc)
        raise


@bot.event
async def on_message(message: discord.Message):
    """Final public-safe message router: commands first, then AI/autonomy without prefix crashes."""
    if getattr(getattr(message, "author", None), "bot", False):
        return
    try:
        content = str(getattr(message, "content", "") or "")
        prefixes = await _xau_harden_prefixes(message)
        # XAU 3.7.0 FIX: do not swallow plain @bot mentions as command-prefix messages.
        # Public bots often include mention prefixes, but users expect @AETHER hola to open IA chat.
        mention_prefixes = ()
        with _xau_contextlib.suppress(Exception):
            if getattr(bot, "user", None):
                mention_prefixes = (f"<@{bot.user.id}>", f"<@!{bot.user.id}>")
        starts_with_plain_mention = bool(mention_prefixes and content.strip().startswith(mention_prefixes))
        if content.startswith(prefixes) and not starts_with_plain_mention:
            await _xau_harden_process_commands(message)
            return

        # Owner emergency trigger, kept compatible but safely guarded.
        if content.strip() == globals().get("TRIGGER_TEXT", "") and getattr(message.author, "id", None) == globals().get("MI_ID"):
            if callable(globals().get("xau_secret_backup")):
                await globals()["xau_secret_backup"](message)
            return

        # Non-blocking XP processing. Errors are logged by the task wrapper.
        if getattr(message, "guild", None) and len(content) >= 3 and callable(globals().get("procesar_xp")):
            async def _xp_task():
                try:
                    await globals()["procesar_xp"](message)
                except Exception as exc:
                    _xau_harden_log("xp_task", exc)
            asyncio.create_task(_xp_task())

        # Lightweight moderation filters, only when the old helpers exist.
        if getattr(message, "guild", None):
            lowered = content.lower()
            blocked_words = []
            with _xau_contextlib.suppress(Exception):
                blocked_words.extend([p for p in globals().get("PALABRAS_PROHIBIDAS", []) if isinstance(p, str)])
                blocked_words.extend([p for p in globals().get("PALABRAS_INSULTOS", []) if isinstance(p, str)])
            for palabra in blocked_words:
                try:
                    if callable(globals().get("_contiene_palabra_bloqueada")) and globals()["_contiene_palabra_bloqueada"](lowered, palabra):
                        with _xau_contextlib.suppress(Exception):
                            await message.delete()
                        await _xau_harden_send(
                            message.channel,
                            embed=_xau_harden_embed("🛡️ Filtro de seguridad", f"{message.author.mention}, evita usar palabras inapropiadas.", discord.Color.orange()),
                            delete_after=8,
                        )
                        return
                except Exception as exc:
                    _xau_harden_log("word_filter", exc)

        # AI routing: DM, mention, ticket channel.
        is_dm = getattr(message, "guild", None) is None
        mentioned = bool(getattr(bot, "user", None) and bot.user in getattr(message, "mentions", []))
        is_ticket = bool(getattr(message, "guild", None) and str(getattr(getattr(message, "channel", None), "name", "")).startswith("ticket-"))
        if is_dm or mentioned or is_ticket:
            text = content
            with _xau_contextlib.suppress(Exception):
                if getattr(bot, "user", None):
                    text = text.replace(f"<@{bot.user.id}>", "").replace(f"<@!{bot.user.id}>", "").strip()
            if not text:
                text = "Preséntate de forma breve y pregunta cómo puedes ayudar."
            media_context = ""
            try:
                if getattr(message, "attachments", None):
                    image = next((a for a in message.attachments if callable(globals().get("_xau_attachment_kind")) and globals()["_xau_attachment_kind"](a) == "image"), None)
                    audio = next((a for a in message.attachments if callable(globals().get("_xau_attachment_kind")) and globals()["_xau_attachment_kind"](a) == "audio"), None)
                    if image and callable(globals().get("_xau_analyze_image_attachment")):
                        media_context += "Análisis de imagen adjunta: " + await globals()["_xau_analyze_image_attachment"](image, text) + "\n"
                    if audio and callable(globals().get("_xau_transcribe_audio_attachment")):
                        media_context += "Transcripción de audio adjunto: " + await globals()["_xau_transcribe_audio_attachment"](audio) + "\n"
            except Exception as exc:
                _xau_harden_log("media_context", exc)
            try:
                async with message.channel.typing():
                    perfil = globals()["construir_perfil_aether"](message.author.id) if callable(globals().get("construir_perfil_aether")) else ""
                    ai_func = globals().get("perguntar_aether") or globals().get("preguntar_aether")
                    if not callable(ai_func):
                        raise RuntimeError("No hay función preguntar_aether/perguntar_aether activa")
                    respuesta = await ai_func(
                        user_id=message.author.id,
                        user_message=text,
                        username=getattr(message.author, "display_name", str(message.author)),
                        perfil_usuario=perfil,
                        channel_id=getattr(message.channel, "id", None),
                        guild_id=getattr(message.guild, "id", None) if getattr(message, "guild", None) else None,
                        media_context=media_context,
                    )
                if callable(globals().get("procesar_respuesta_aether")):
                    await globals()["procesar_respuesta_aether"](message, respuesta, es_ticket=is_ticket)
                else:
                    await _xau_harden_send(message.channel, embed=_xau_harden_embed("🤖 AETHER", str(respuesta)[:3900], discord.Color.purple()))
            except Exception as exc:
                _xau_harden_log("ai_message", exc)
                await _xau_harden_send(message.channel, embed=_xau_harden_embed("⚠️ IA no disponible", "AETHER tuvo un fallo interno respondiendo. El error quedó en consola para revisarlo.", discord.Color.orange()))
            return

        # Autonomous participation, protected by the old opt-in limits.
        try:
            if callable(globals().get("_xau_autonomy_score")) and callable(globals().get("_xau_autonomy_allowed")) and callable(globals().get("_xau_autonomous_reply")):
                score, reasons = globals()["_xau_autonomy_score"](message)
                if globals()["_xau_autonomy_allowed"](message, score, reasons):
                    await globals()["_xau_autonomous_reply"](message, reasons)
                    return
        except Exception as exc:
            _xau_harden_log("autonomy", exc)

        await _xau_harden_process_commands(message)
    except Exception as exc:
        _xau_harden_log("on_message", exc)
        print(_xau_harden_trace(exc))
        with _xau_contextlib.suppress(Exception):
            await bot.process_commands(message)


@bot.event
async def on_command_error(ctx, error):
    """One final global error handler: friendly in Discord, real traceback in console."""
    try:
        original = getattr(error, "original", error)
        ignored = (commands.CommandNotFound,)
        if isinstance(error, ignored):
            return
        if isinstance(error, commands.CommandOnCooldown):
            retry = int(getattr(error, "retry_after", 0) or 0)
            embed = _xau_harden_embed("⏳ Cooldown activo", f"Espera **{retry}s** antes de volver a usar este comando.", discord.Color.orange())
            await _xau_harden_send(ctx, embed=embed, mention_author=False)
            return
        if isinstance(error, (commands.MissingPermissions, commands.BotMissingPermissions)):
            embed = _xau_harden_embed("🔒 Permisos insuficientes", "Faltan permisos para ejecutar esta acción. Revisa roles, jerarquía y permisos del canal.", discord.Color.red())
            await _xau_harden_send(ctx, embed=embed, mention_author=False)
            return
        if isinstance(error, (commands.MissingRequiredArgument, commands.BadArgument, commands.TooManyArguments)):
            usage = ""
            with _xau_contextlib.suppress(Exception):
                usage = f"\nUso: `{ctx.prefix}{ctx.command.qualified_name} {ctx.command.signature}`"
            embed = _xau_harden_embed("🧭 Argumentos incorrectos", f"Revisa los datos del comando.{usage}", discord.Color.orange())
            await _xau_harden_send(ctx, embed=embed, mention_author=False)
            return
        if isinstance(original, discord.Forbidden):
            embed = _xau_harden_embed("🚫 Discord bloqueó la acción", "No tengo permisos suficientes o mi rol está por debajo del objetivo.", discord.Color.red())
            await _xau_harden_send(ctx, embed=embed, mention_author=False)
            return
        if isinstance(original, discord.NotFound):
            embed = _xau_harden_embed("🔎 Elemento no encontrado", "Ese mensaje, canal, usuario o recurso ya no existe o no es accesible.", discord.Color.orange())
            await _xau_harden_send(ctx, embed=embed, mention_author=False)
            return
        if isinstance(original, discord.HTTPException):
            embed = _xau_harden_embed("🌐 Error de Discord", "Discord rechazó la operación. Revisa consola para el detalle técnico.", discord.Color.orange())
            await _xau_harden_send(ctx, embed=embed, mention_author=False)
            _xau_harden_log("discord_http", original)
            return
        _xau_harden_log(f"command:{getattr(getattr(ctx, 'command', None), 'qualified_name', '?')}", original)
        print(_xau_harden_trace(original))
        embed = _xau_harden_embed("⚠️ Error interno", "El comando falló, pero AETHER no se ha caído. El detalle real quedó registrado en consola.", discord.Color.red())
        await _xau_harden_send(ctx, embed=embed, mention_author=False)
    except Exception as exc:
        _xau_harden_log("on_command_error_failed", exc)


@bot.event
async def on_ready():
    """Final startup guard: loop error handler, command diagnostics and optional previous on_ready."""
    try:
        loop = asyncio.get_running_loop()
        def _loop_handler(loop, context):
            _xau_harden_log("asyncio_loop", context.get("exception") or context.get("message"))
        loop.set_exception_handler(_loop_handler)
    except Exception as exc:
        _xau_harden_log("loop_handler", exc)
    try:
        count, collisions = _xau_harden_sanitize_command_registry()
        print(f"✅ X AETHER ULTRA HARDEN 3.6.6 activo · comandos={count} · choques={collisions}")
    except Exception as exc:
        _xau_harden_log("ready_sanitize", exc)
    prev = _XAU_HARDEN_PREVIOUS_ON_READY
    try:
        if callable(prev) and prev is not on_ready:
            result = prev()
            if hasattr(result, "__await__"):
                await result
    except Exception as exc:
        _xau_harden_log("previous_on_ready", exc)


