@commands.cooldown(1, 15, commands.BucketType.guild)
async def xau_doctor(ctx):
    """Diagnóstico técnico del bot: comandos, prefijos, Pillow, IA, JSON y últimos errores."""
    commands_list, collisions = _xau_harden_command_report()
    try:
        prefixes = await _xau_harden_prefixes(ctx.message)
    except Exception as exc:
        prefixes = (f"error:{exc!r}",)
    try:
        ok_pil, pil_msg = _amx231_pillow_status() if callable(globals().get("_amx231_pillow_status")) else (Image is not None, "Pillow disponible" if Image else "Pillow no disponible")
    except Exception as exc:
        ok_pil, pil_msg = False, repr(exc)
    json_files = [
        globals().get("DATOS_FILE"), globals().get("MEMORIA_FILE"), globals().get("OUROBOROS_FILE"),
        globals().get("XAU_PUBLIC_CONFIG_FILE"), globals().get("XAU_LIVING_CORE_FILE"),
        globals().get("XAU_MEMBERSHIP_REQUESTS_FILE"), globals().get("XAU_ACHIEVEMENTS_FILE"),
    ]
    json_status = []
    for path in [p for p in json_files if isinstance(p, str)]:
        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    json.load(f)
                json_status.append(f"✅ `{os.path.basename(path)}`")
            else:
                json_status.append(f"⚪ `{os.path.basename(path)}` no existe")
        except Exception as exc:
            json_status.append(f"❌ `{os.path.basename(path)}` {exc.__class__.__name__}")
    embed = _xau_harden_embed("🧪 X AETHER ULTRA · Doctor", "Diagnóstico de salud del monolito público.", discord.Color.green() if not collisions else discord.Color.orange())
    embed.add_field(name="🤖 Bot", value=f"`{getattr(bot.user, 'name', 'no conectado')}` · v`{globals().get('BOT_VERSION', '?')}`", inline=True)
    embed.add_field(name="📦 Comandos", value=f"Prefix: **{len(commands_list)}**\nSlash: **{len(bot.tree.get_commands())}**\nChoques: **{len(collisions)}**", inline=True)
    embed.add_field(name="🔠 Prefijos", value=" · ".join(f"`{p}`" for p in prefixes)[:1000], inline=False)
    embed.add_field(name="🖼️ Pillow", value=("✅ " if ok_pil else "❌ ") + str(pil_msg)[:900], inline=False)
    embed.add_field(name="🧬 JSON", value="\n".join(json_status[:12]) or "Sin archivos detectados", inline=False)
    if collisions:
        embed.add_field(name="⚠️ Choques activos", value="\n".join(f"`{a}`: {b} ↔ {c}" for a,b,c in collisions[:8])[:1000], inline=False)
    if _XAU_HARDEN_LAST_ERRORS:
        embed.add_field(name="🧯 Últimos errores", value="\n".join(f"`{e[-170:]}`" for e in _XAU_HARDEN_LAST_ERRORS[-5:])[:1000], inline=False)
    await _xau_harden_send(ctx, embed=embed, mention_author=False)

