XAU_IMAGE_HOTFIX_VERSION = "3.6.8"
_XAU_IMAGE_USER_LOCKS = {}
_XAU_IMAGE_LAST_ERRORS = []
_XAU_IMAGE_LAST_OK = {}


def _xau_image_note_error(message: str):
    """Keep a tiny rolling error buffer for !ia_api."""
    try:
        _XAU_IMAGE_LAST_ERRORS.append(str(message)[:900])
        del _XAU_IMAGE_LAST_ERRORS[:-12]
    except Exception:
        pass


def _xau_image_clean_prompt(prompt: str, max_chars: int = 900) -> str:
    """Normalize a user prompt and keep it provider-friendly."""
    clean = re.sub(r"\s+", " ", str(prompt or "")).strip()
    clean = clean.replace("```", "").replace("@everyone", "everyone").replace("@here", "here")
    if not clean:
        clean = "avatar futurista de X AETHER ULTRA, energía amatista"
    return clean[:max_chars]


def _xau_image_enhance_prompt_v368(prompt: str, cfg: dict) -> str:
    """Better Spanish-to-image prompt expansion for free image APIs."""
    ai = cfg.get("ai", {}) if isinstance(cfg, dict) else {}
    style = str(ai.get("image_style") or os.getenv("XAU_IMAGE_STYLE") or "realista cinematográfico, ultra detallado, alta calidad").strip()
    negative = "sin texto deformado, sin watermark, sin logo, sin manos deformes, sin baja resolución, sin pixelado"
    prompt = _xau_image_clean_prompt(prompt, int((cfg.get("limits", {}) if isinstance(cfg, dict) else {}).get("max_image_prompt_chars") or 900))
    return (
        f"{prompt}. Estilo visual: {style}. "
        "Composición clara, iluminación profesional, enfoque nítido, detalles definidos, colores ricos, profundidad cinematográfica. "
        f"Evitar: {negative}."
    )[:1400]


async def _xau_image_fetch_bytes(url: str, *, headers: dict = None, timeout_total: int = 130) -> tuple[bytes, str]:
    """Download image bytes with validation and readable errors."""
    timeout = aiohttp.ClientTimeout(total=timeout_total)
    headers = headers or {}
    headers.setdefault("User-Agent", "X-AETHER-ULTRA/3.6.8 DiscordBot ImageRouter")
    async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
        async with session.get(url) as resp:
            data = await resp.read()
            ctype = str(resp.headers.get("content-type", ""))
            if resp.status >= 400:
                text = data[:350].decode("utf-8", "ignore")
                raise RuntimeError(f"HTTP {resp.status} · {ctype or 'sin content-type'} · {text}")
            if not data or len(data) < 1024:
                text = data[:350].decode("utf-8", "ignore")
                raise RuntimeError(f"Respuesta vacía/pequeña · {ctype} · {text}")
            if "image" not in ctype.lower():
                # Some free providers return HTML/JSON when rate-limited or protected.
                if not (data.startswith(b"\x89PNG") or data.startswith(b"\xff\xd8") or data.startswith(b"RIFF") or data.startswith(b"GIF") or data.startswith(b"BM")):
                    text = data[:450].decode("utf-8", "ignore")
                    raise RuntimeError(f"No devolvió imagen · {ctype or 'sin content-type'} · {text}")
            return data, ctype


def _xau_image_file_from_bytes(data: bytes, provider: str, ctype: str = "") -> discord.File:
    """Build a fresh discord.File for every send/edit."""
    ext = "png"
    ctype = (ctype or "").lower()
    if "jpeg" in ctype or data.startswith(b"\xff\xd8"):
        ext = "jpg"
    elif "webp" in ctype or data.startswith(b"RIFF"):
        ext = "webp"
    elif "gif" in ctype or data.startswith(b"GIF"):
        ext = "gif"
    safe_provider = re.sub(r"[^a-z0-9_]+", "_", provider.lower())[:24] or "image"
    return discord.File(io.BytesIO(data), filename=f"xau_{safe_provider}.{ext}")


async def _xau_image_pollinations_v368(prompt: str, cfg: dict) -> tuple[discord.File, str]:
    """Pollinations with multiple endpoints and cache-busting seed, because free endpoints can be temperamental."""
    from urllib.parse import quote, quote_plus

    ai = cfg.get("ai", {}) if isinstance(cfg, dict) else {}
    model = str(ai.get("image_model") or os.getenv("XAU_POLLINATIONS_IMAGE_MODEL") or "flux").strip() or "flux"
    width = int(ai.get("image_width") or os.getenv("XAU_IMAGE_WIDTH") or 1024)
    height = int(ai.get("image_height") or os.getenv("XAU_IMAGE_HEIGHT") or 1024)
    width = min(max(width, 512), 1536)
    height = min(max(height, 512), 1536)
    seed = random.randint(1, 2_147_483_000)
    encoded_path = quote(prompt, safe="")
    encoded_plus = quote_plus(prompt)
    key = os.getenv("POLLINATIONS_API_KEY", "").strip()
    key_q = f"&key={quote_plus(key)}" if key else ""

    urls = [
        f"https://gen.pollinations.ai/image/{encoded_path}?model={quote_plus(model)}&width={width}&height={height}&seed={seed}&nologo=true&enhance=true&safe=true{key_q}",
        f"https://image.pollinations.ai/prompt/{encoded_path}?model={quote_plus(model)}&width={width}&height={height}&seed={seed}&nologo=true&enhance=true&safe=true{key_q}",
        f"https://image.pollinations.ai/prompt/{encoded_plus}?width={width}&height={height}&seed={seed}&nologo=true&safe=true{key_q}",
    ]
    errors = []
    for idx, url in enumerate(urls, start=1):
        try:
            data, ctype = await _xau_image_fetch_bytes(url, timeout_total=130)
            return _xau_image_file_from_bytes(data, f"pollinations_{idx}", ctype), f"Pollinations #{idx}"
        except Exception as exc:
            errors.append(f"Pollinations #{idx}: {exc}")
            await asyncio.sleep(1.5)
    raise RuntimeError(" | ".join(errors)[-1400:])


async def _xau_image_aihorde_v368(prompt: str, cfg: dict) -> tuple[discord.File, str]:
    """AI Horde fallback. It is free/community-powered, so it may be slower."""
    api_key = os.getenv("AI_HORDE_API_KEY", "0000000000").strip() or "0000000000"
    ai = cfg.get("ai", {}) if isinstance(cfg, dict) else {}
    width = min(max(int(ai.get("image_width") or 768), 512), 1024)
    height = min(max(int(ai.get("image_height") or 768), 512), 1024)
    model = os.getenv("AI_HORDE_IMAGE_MODEL", "stable_diffusion").strip() or "stable_diffusion"
    payload = {
        "prompt": prompt,
        "params": {"width": width, "height": height, "steps": int(os.getenv("AI_HORDE_STEPS", "22")), "n": 1, "sampler_name": "k_euler_a", "cfg_scale": 7.5},
        "nsfw": False,
        "censor_nsfw": True,
        "trusted_workers": False,
        "models": [model],
        "r2": True,
    }
    headers = {"apikey": api_key, "Client-Agent": "X-AETHER-ULTRA:3.6.8:Markelson"}
    hosts = ["https://aihorde.net", "https://stablehorde.net"]
    last_error = None
    for host in hosts:
        try:
            timeout = aiohttp.ClientTimeout(total=210)
            async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
                async with session.post(f"{host}/api/v2/generate/async", json=payload) as resp:
                    text = await resp.text()
                    if resp.status >= 400:
                        raise RuntimeError(f"submit HTTP {resp.status}: {text[:300]}")
                    submit = json.loads(text)
                job_id = submit.get("id")
                if not job_id:
                    raise RuntimeError(f"sin ID: {submit}")
                for _ in range(55):
                    await asyncio.sleep(3)
                    async with session.get(f"{host}/api/v2/generate/status/{job_id}") as resp:
                        if resp.status >= 400:
                            continue
                        status = await resp.json()
                    gens = status.get("generations") or []
                    if gens:
                        img_url = gens[0].get("img")
                        if not img_url:
                            raise RuntimeError("terminó sin URL de imagen")
                        data, ctype = await _xau_image_fetch_bytes(img_url, timeout_total=120)
                        return _xau_image_file_from_bytes(data, "aihorde", ctype), "AI Horde"
        except Exception as exc:
            last_error = exc
            continue
    raise TimeoutError(f"AI Horde no respondió a tiempo: {last_error}")


async def _xau_image_huggingface_v368(prompt: str, cfg: dict) -> tuple[discord.File, str]:
    """Optional Hugging Face fallback. Requires HF_TOKEN."""
    token = os.getenv("HF_TOKEN", "").strip()
    if not token:
        raise RuntimeError("Falta HF_TOKEN")
    model = os.getenv("HF_IMAGE_MODEL", "black-forest-labs/FLUX.1-schnell").strip()
    url = f"https://api-inference.huggingface.co/models/{model}"
    headers = {"Authorization": f"Bearer {token}", "Accept": "image/png", "Content-Type": "application/json"}
    timeout = aiohttp.ClientTimeout(total=170)
    async with aiohttp.ClientSession(timeout=timeout, headers=headers) as session:
        async with session.post(url, json={"inputs": prompt}) as resp:
            data = await resp.read()
            ctype = resp.headers.get("content-type", "")
            if resp.status >= 400:
                raise RuntimeError(f"HF HTTP {resp.status}: {data[:350]!r}")
            if "image" not in str(ctype).lower() and not (data.startswith(b"\x89PNG") or data.startswith(b"\xff\xd8")):
                raise RuntimeError(f"HF no devolvió imagen: {data[:350]!r}")
            return _xau_image_file_from_bytes(data, "huggingface", ctype), "Hugging Face"


async def _xau_image_router_v368(prompt: str, cfg: dict) -> tuple[discord.File, str, list]:
    """Generate an image with provider fallback and a real error list."""
    ai = cfg.get("ai", {}) if isinstance(cfg, dict) else {}
    order_raw = ai.get("image_provider_order") or ai.get("image_order") or ai.get("orden_imagen") or os.getenv("XAU_IMAGE_PROVIDER_ORDER") or os.getenv("XAU_IMAGE_PROVIDER") or "pollinations,aihorde,huggingface"
    order = []
    for p in str(order_raw).split(","):
        p = p.strip().lower().replace(" ", "")
        if p and p not in order:
            order.append(p)
    if not order:
        order = ["pollinations", "aihorde", "huggingface"]
    errors = []
    for provider in order:
        try:
            if provider in {"pollinations", "pollination", "free", "gratis"}:
                file, label = await _xau_image_pollinations_v368(prompt, cfg)
            elif provider in {"aihorde", "ai_horde", "stablehorde", "horde"}:
                file, label = await _xau_image_aihorde_v368(prompt, cfg)
            elif provider in {"huggingface", "hf"}:
                file, label = await _xau_image_huggingface_v368(prompt, cfg)
            else:
                errors.append(f"{provider}: proveedor desconocido")
                continue
            _XAU_IMAGE_LAST_OK[str(provider)] = int(time.time())
            return file, label, errors
        except Exception as exc:
            msg = f"{provider}: {exc}"
            errors.append(msg[:900])
            _xau_image_note_error(msg)
            continue
    raise RuntimeError("Todos los proveedores fallaron:\n" + "\n".join(errors[-8:]))


