def _xaucine_bar(step: int, total: int = 12, fill: str = "◆", empty: str = "◇") -> str:
    step = max(0, min(int(step), int(total)))
    return "`" + fill * step + empty * (total - step) + "`"


def _xaucine_parse_bet(raw, cash: int) -> int:
    if raw is None:
        return 100
    txt = str(raw).strip().lower().replace(" ", "")
    if txt in {"showcase", "demo", "video", "gif", "0"}:
        return 0
    if txt in {"all", "todo", "max", "full"}:
        return max(0, int(cash))
    mult = 1
    if txt.endswith("k"):
        mult, txt = 1000, txt[:-1]
    elif txt.endswith("m"):
        mult, txt = 1000000, txt[:-1]
    txt = txt.replace(".", "").replace(",", "")
    try:
        return max(0, int(float(txt)) * mult)
    except Exception:
        return 0


