def _xaucine_card_value(card):
    r, _ = card
    if r == "A":
        return 11
    if r in {"J", "Q", "K"}:
        return 10
    return int(r)


def _xaucine_bj_score(cards):
    total = sum(_xaucine_card_value(c) for c in cards)
    aces = sum(1 for c in cards if c[0] == "A")
    while total > 21 and aces:
        total -= 10
        aces -= 1
    return total


def _xaucine_card_big(card, hidden: bool = False) -> str:
    if hidden:
        return "┌───────┐\n│░░░░░░░│\n│░░ ? ░░│\n│░░░░░░░│\n└───────┘"
    rank, suit = card
    left = f"{rank:<2}"
    right = f"{rank:>2}"
    return f"┌───────┐\n│{left}     │\n│   {suit}   │\n│     {right}│\n└───────┘"


def _xaucine_cards_row(cards, hidden_dealer: bool = False) -> str:
    blocks = []
    for idx, card in enumerate(cards):
        blocks.append(_xaucine_card_big(card, hidden=(hidden_dealer and idx == 1)))
    lines = [b.splitlines() for b in blocks]
    return "\n".join("  ".join(card_lines[i] for card_lines in lines) for i in range(5))


def _xaucine_hand_name(cards):
    ranks = [c[0] for c in cards]
    suits = [c[1] for c in cards]
    values_map = {"A": 14, "K": 13, "Q": 12, "J": 11, "10": 10, "9": 9, "8": 8, "7": 7, "6": 6, "5": 5, "4": 4, "3": 3, "2": 2}
    vals = sorted([values_map[r] for r in ranks], reverse=True)
    counts = sorted([ranks.count(r) for r in set(ranks)], reverse=True)
    flush = len(set(suits)) == 1
    unique = sorted(set(vals))
    straight = len(unique) == 5 and (max(unique) - min(unique) == 4 or unique == [2, 3, 4, 5, 14])
    if straight and flush:
        return "Escalera de color", 25
    if counts[0] == 4:
        return "Póker", 15
    if counts == [3, 2]:
        return "Full house", 8
    if flush:
        return "Color", 6
    if straight:
        return "Escalera", 5
    if counts[0] == 3:
        return "Trío", 3
    if counts == [2, 2, 1]:
        return "Doble pareja", 2
    if counts[0] == 2:
        return "Pareja", 1
    return "Carta alta", 0


