def _xaucine_font(size: int, bold: bool = True):
    if ImageFont is None:
        return None
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
    ]
    for path in candidates:
        try:
            if os.path.exists(path):
                return ImageFont.truetype(path, size)
        except Exception:
            pass
    try:
        return ImageFont.load_default()
    except Exception:
        return None


def _xaucine_draw_center(draw, xy, text, font, fill=(255, 255, 255)):
    try:
        bbox = draw.textbbox((0, 0), text, font=font)
        w = bbox[2] - bbox[0]
        h = bbox[3] - bbox[1]
    except Exception:
        w, h = 400, 40
    draw.text((xy[0] - w / 2, xy[1] - h / 2), text, font=font, fill=fill)




def _xaucine_draw_neon_diamond(draw, cx, cy, size):
    s = int(size)
    pts = [(cx, cy-s), (cx+s, cy), (cx, cy+s), (cx-s, cy)]
    draw.polygon(pts, fill=(85, 230, 255), outline=(210, 255, 255))
    draw.line((cx-s//2, cy, cx, cy+s, cx+s//2, cy), fill=(255, 255, 255), width=max(2, s//12))
    draw.line((cx-s//2, cy, cx, cy-s, cx+s//2, cy), fill=(255, 255, 255), width=max(2, s//14))


def _xaucine_draw_crown(draw, cx, cy, size):
    s = int(size)
    base_y = cy + s//3
    pts = [(cx-s, base_y), (cx-s//2, cy-s//2), (cx, base_y-s//3), (cx+s//2, cy-s//2), (cx+s, base_y), (cx-s, base_y)]
    draw.polygon(pts, fill=(255, 205, 60), outline=(255, 245, 180))
    draw.rounded_rectangle((cx-s, base_y, cx+s, base_y+s//3), radius=max(4, s//8), fill=(220, 145, 30), outline=(255, 235, 140), width=max(2, s//14))
    for dx in (-s//2, 0, s//2):
        draw.ellipse((cx+dx-s//8, cy-s//2-s//8, cx+dx+s//8, cy-s//2+s//8), fill=(255, 245, 160))


def _xaucine_draw_cherry(draw, cx, cy, size):
    s = int(size)
    draw.line((cx, cy-s//2, cx+s//3, cy-s), fill=(70, 230, 100), width=max(3, s//12))
    draw.arc((cx-s//8, cy-s, cx+s, cy-s//5), 180, 285, fill=(90, 255, 130), width=max(3, s//12))
    draw.ellipse((cx-s, cy-s//4, cx-s//8, cy+s//2), fill=(225, 25, 65), outline=(255, 120, 140), width=max(2, s//15))
    draw.ellipse((cx-s//6, cy-s//5, cx+s*3//4, cy+s//2), fill=(210, 20, 60), outline=(255, 120, 140), width=max(2, s//15))
    draw.ellipse((cx-s*3//4, cy-s//10, cx-s//2, cy+s//10), fill=(255, 180, 190))


def _xaucine_draw_bell(draw, cx, cy, size):
    s = int(size)
    draw.pieslice((cx-s, cy-s, cx+s, cy+s), 200, 340, fill=(255, 190, 45), outline=(255, 235, 150), width=max(2, s//15))
    draw.rounded_rectangle((cx-s, cy, cx+s, cy+s//3), radius=s//8, fill=(230, 150, 35), outline=(255, 235, 150), width=max(2, s//15))
    draw.ellipse((cx-s//5, cy+s//4, cx+s//5, cy+s*2//3), fill=(255, 225, 100))


def _xaucine_draw_lemon(draw, cx, cy, size):
    s = int(size)
    draw.ellipse((cx-s, cy-s//2, cx+s, cy+s//2), fill=(245, 230, 65), outline=(255, 255, 180), width=max(2, s//15))
    draw.arc((cx-s//2, cy-s//3, cx+s//2, cy+s//3), 200, 340, fill=(255, 255, 200), width=max(2, s//14))


def _xaucine_draw_rocket(draw, cx, cy, size):
    s = int(size)
    body = [(cx, cy-s), (cx+s//2, cy), (cx+s//4, cy+s//2), (cx-s//4, cy+s//2), (cx-s//2, cy)]
    draw.polygon(body, fill=(210, 220, 255), outline=(120, 180, 255))
    draw.ellipse((cx-s//4, cy-s//3, cx+s//4, cy+s//8), fill=(90, 210, 255), outline=(230, 255, 255))
    draw.polygon([(cx-s//4, cy+s//2), (cx, cy+s), (cx+s//4, cy+s//2)], fill=(255, 120, 45))
    draw.polygon([(cx-s//8, cy+s//2), (cx, cy+s*3//4), (cx+s//8, cy+s//2)], fill=(255, 240, 80))


def _xaucine_draw_icon(draw, cx, cy, sym, size, font=None):
    """Draw emoji-like icons using shapes so casino GIFs work without emoji fonts on Linux/Pterodactyl."""
    raw = str(sym or "")
    if raw in {"💎", "diamante", "cristal"}:
        return _xaucine_draw_neon_diamond(draw, cx, cy, size)
    if raw in {"👑", "corona"}:
        return _xaucine_draw_crown(draw, cx, cy, size)
    if raw in {"🍒", "cereza", "cherry"}:
        return _xaucine_draw_cherry(draw, cx, cy, size)
    if raw in {"🔔", "campana", "bell"}:
        return _xaucine_draw_bell(draw, cx, cy, size)
    if raw in {"🍋", "limon", "limón", "lemon"}:
        return _xaucine_draw_lemon(draw, cx, cy, size)
    if raw in {"🚀", "rocket"}:
        return _xaucine_draw_rocket(draw, cx, cy, size)
    if "7" in raw:
        f = _xaucine_font(max(34, int(size*1.25)))
        return _xaucine_draw_center(draw, (cx, cy), "7", f or font, (255, 80, 110))
    if raw in {"🎲", "dado"}:
        s = int(size)
        draw.rounded_rectangle((cx-s, cy-s, cx+s, cy+s), radius=s//5, fill=(245,245,245), outline=(90,90,130), width=max(2, s//12))
        for dx, dy in [(-.4,-.4),(0,0),(.4,.4)]:
            r=max(3, s//10); x=cx+int(dx*s); y=cy+int(dy*s)
            draw.ellipse((x-r,y-r,x+r,y+r), fill=(40,40,50))
        return
    # fallback: draw a readable ASCII label instead of broken tofu boxes
    label = re.sub(r"[^A-Za-z0-9]+", "", raw)[:3] or "★"
    f = _xaucine_font(max(28, int(size*.8)))
    _xaucine_draw_center(draw, (cx, cy), label, f or font, (255, 255, 255))

def _xaucine_make_gif(game: str, result: dict, author_name: str = "Jugador") -> str:
    """Generate a local animated GIF that Discord can preview like a short video."""
    if Image is None or ImageDraw is None:
        raise RuntimeError("Pillow no está disponible para generar el vídeo/GIF local.")
    game = str(game or "casino").lower()
    width, height = 960, 540
    title_font = _xaucine_font(42)
    big_font = _xaucine_font(72)
    mid_font = _xaucine_font(32)
    small_font = _xaucine_font(22, bold=False)
    frames = []
    symbols = result.get("symbols") or ["💎", "👑", "🍒"]
    final_text = str(result.get("final", "Resultado listo"))
    net_text = str(result.get("net_text", ""))
    color_main = result.get("color", (155, 89, 182))
    for i in range(28):
        img = Image.new("RGB", (width, height), (8, 8, 16))
        draw = ImageDraw.Draw(img)
        # Fondo neón con bandas móviles.
        for y in range(0, height, 18):
            shade = int(18 + 30 * ((y + i * 12) % 140) / 140)
            draw.rectangle((0, y, width, y + 12), fill=(shade, 8, 35 + shade // 2))
        draw.rounded_rectangle((36, 32, width - 36, height - 32), radius=34, outline=color_main, width=5, fill=(15, 12, 28))
        _xaucine_draw_center(draw, (width / 2, 70), f"X AETHER ULTRA · {game.upper()}", title_font, (245, 220, 255))
        draw.text((60, 478), f"Jugador: {author_name} · Resultado integrado en el vídeo", font=small_font, fill=(210, 210, 230))
        if game in {"slots", "maquina", "tragaperras"}:
            spin = [random.choice(["🍒", "💎", "👑", "🔔", "7️⃣", "🍋"]) for _ in range(3)] if i < 20 else symbols[:3]
            for idx, sym in enumerate(spin):
                x = 210 + idx * 190
                draw.rounded_rectangle((x, 155, x + 150, 310), radius=24, fill=(35, 24, 55), outline=(255, 215, 90), width=4)
                _xaucine_draw_icon(draw, x + 75, 232, sym, 52, big_font)
            _xaucine_draw_center(draw, (width / 2, 380), final_text if i > 20 else "Rodillos girando...", mid_font, (255, 230, 120))
        elif game in {"ruleta", "roulette"}:
            cx, cy, r = width // 2, 255, 145
            draw.ellipse((cx-r, cy-r, cx+r, cy+r), outline=(255, 220, 80), width=8, fill=(35, 12, 24))
            for n in range(16):
                angle = (n * 22 + i * 17) % 360
                import math
                x = cx + int(math.cos(math.radians(angle)) * 112)
                y = cy + int(math.sin(math.radians(angle)) * 112)
                draw.ellipse((x-15, y-15, x+15, y+15), fill=(220, 40, 55) if n % 2 else (20, 20, 25))
            ball_angle = (i * 29 + 45) % 360
            import math
            bx = cx + int(math.cos(math.radians(ball_angle)) * (98 - min(i, 18)))
            by = cy + int(math.sin(math.radians(ball_angle)) * (98 - min(i, 18)))
            draw.ellipse((bx-13, by-13, bx+13, by+13), fill=(245, 245, 245))
            _xaucine_draw_center(draw, (width / 2, 430), final_text if i > 20 else "La bola está girando...", mid_font, (255, 230, 120))
        elif game in {"blackjack", "bj", "poker", "texasholdem"}:
            cards = result.get("cards") or ["A♠", "K♥", "7♦", "9♣", "Q♠"]
            for idx, card in enumerate(cards[:5]):
                x = 115 + idx * 150
                y = 170 + (8 if i % 2 else 0)
                draw.rounded_rectangle((x, y, x + 105, y + 150), radius=12, fill=(250, 250, 245), outline=(120, 60, 160), width=4)
                _xaucine_draw_center(draw, (x + 52, y + 75), str(card), mid_font, (20, 20, 30))
            _xaucine_draw_center(draw, (width / 2, 395), final_text, mid_font, (255, 230, 120))
        elif game == "crash":
            mult = result.get("mult", 1.0) if i > 20 else (1.0 + i * 0.08)
            x = 90 + i * 26
            y = 420 - i * 10
            draw.line((80, 430, min(x, 830), max(y, 120)), fill=(80, 220, 255), width=7)
            _xaucine_draw_icon(draw, min(x, 835), max(y, 115), "🚀", 44, big_font)
            _xaucine_draw_center(draw, (width / 2, 120), f"x{float(mult):.2f}", big_font, (255, 230, 120))
            _xaucine_draw_center(draw, (width / 2, 455), final_text if i > 20 else "Subiendo...", mid_font, (255, 230, 120))
        else:
            _xaucine_draw_icon(draw, width//2 - 120, 245, "🎲", 42, big_font)
            _xaucine_draw_icon(draw, width//2 - 30, 245, "💎", 42, big_font)
            _xaucine_draw_icon(draw, width//2 + 60, 245, "👑", 42, big_font)
            _xaucine_draw_center(draw, (width / 2, 330), "CASINO", mid_font, (255, 255, 255))
            _xaucine_draw_center(draw, (width / 2, 370), final_text, mid_font, (255, 230, 120))
        if net_text:
            _xaucine_draw_center(draw, (width / 2, 455), net_text, mid_font, (200, 255, 210) if "+" in net_text else (255, 180, 180))
        frames.append(img)
    path = os.path.join(XAU_CINEMA_TMP_DIR, f"casino_{game}_{int(time.time()*1000)}_{random.randint(1000,9999)}.gif")
    frames[0].save(path, save_all=True, append_images=frames[1:], duration=85, loop=0, optimize=False)
    return path


class XAUCineResultView(discord.ui.View):
    """Final casino view with local video generation."""
    def __init__(self, author_id: int, game: str, bet: int, payload: dict, timeout: float = 90):
        super().__init__(timeout=timeout)
        self.author_id = int(author_id)
        self.game = str(game)
        self.bet = int(bet or 0)
        self.payload = payload if isinstance(payload, dict) else {}

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Solo quien inició la partida puede usar estos botones.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Generar vídeo", emoji="🎬", style=discord.ButtonStyle.success)
    async def video_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer(ephemeral=True, thinking=True)
        try:
            path = await asyncio.to_thread(_xaucine_make_gif, self.game, self.payload, interaction.user.display_name)
            await interaction.followup.send(
                content="🎬 Resultado renderizado por X AETHER ULTRA. Es GIF local, sin API de pago.",
                file=discord.File(path, filename=f"xau_{self.game}_resultado.gif"),
                ephemeral=True,
            )
        except Exception as exc:
            await interaction.followup.send(f"No pude generar el vídeo local: `{str(exc)[:500]}`", ephemeral=True)

    @discord.ui.button(label="Reglas", emoji="📜", style=discord.ButtonStyle.secondary)
    async def rules_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_message(_xaucine_rules(self.game), ephemeral=True)


class XAUCineBlackjackView(discord.ui.View):
    def __init__(self, ctx, bet: int, deck, player, dealer, msg=None):
        super().__init__(timeout=90)
        self.ctx = ctx
        self.author_id = ctx.author.id
        self.bet = int(bet or 0)
        self.deck = deck
        self.player = player
        self.dealer = dealer
        self.finished = False

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("Esta mesa es de otro jugador.", ephemeral=True)
            return False
        return True

    def _embed(self, reveal=False, note="Elige tu jugada."):
        ps = _xaucine_bj_score(self.player)
        ds = _xaucine_bj_score(self.dealer) if reveal else _xaucine_bj_score([self.dealer[0]])
        desc = (
            f"Apuesta: **{_xaucine_money(self.ctx, self.bet, True) if self.bet else 'Showcase'}**\n"
            f"Tu mano: **{ps}** · Dealer: **{ds}{'' if reveal else '+'}**\n\n"
            f"**Tus cartas**\n```text\n{_xaucine_cards_row(self.player)}\n```\n"
            f"**Dealer**\n```text\n{_xaucine_cards_row(self.dealer, hidden_dealer=not reveal)}\n```\n"
            f"{note}\n\n📜 { _xaucine_rules('blackjack') }"
        )
        return _xaucine_embed(self.ctx, "🃏 Blackjack cinematográfico", desc, _XAUCINE_PURPLE)

    async def _finish(self, interaction: discord.Interaction, reason="Plantado"):
        if self.finished:
            return
        self.finished = True
        while _xaucine_bj_score(self.dealer) < 17:
            self.dealer.append(self.deck.pop())
        ps = _xaucine_bj_score(self.player)
        ds = _xaucine_bj_score(self.dealer)
        if ps > 21:
            win, net, title = False, -self.bet, "Te pasaste de 21"
        elif ds > 21 or ps > ds:
            win, net, title = True, self.bet, "Victoria"
        elif ps == ds:
            win, net, title = False, 0, "Empate"
        else:
            win, net, title = False, -self.bet, "Derrota"
        stats = await _xaucine_apply_result(self.ctx, "blackjack", self.bet, net, win)
        for child in self.children:
            if hasattr(child, "disabled"):
                child.disabled = True
        payload = {"cards": [f"{r}{s}" for r, s in self.player + self.dealer], "final": f"{title}: jugador {ps} vs dealer {ds}", "net_text": f"Neto {net:+}", "color": (46, 204, 113) if win else (231, 76, 60)}
        view = XAUCineResultView(self.author_id, "blackjack", self.bet, payload)
        embed = self._embed(True, f"**{title}** · Neto: **{_xaucine_money(self.ctx, net, True)}**\n{_xaucine_stats_field(stats)}")
        await interaction.response.edit_message(embed=embed, view=view)

    @discord.ui.button(label="Pedir", emoji="➕", style=discord.ButtonStyle.primary)
    async def hit_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.player.append(self.deck.pop())
        if _xaucine_bj_score(self.player) > 21:
            await self._finish(interaction, "Te pasaste")
        else:
            await interaction.response.edit_message(embed=self._embed(False, "Carta recibida. Puedes pedir otra o plantarte."), view=self)

    @discord.ui.button(label="Plantarse", emoji="🛑", style=discord.ButtonStyle.secondary)
    async def stand_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._finish(interaction, "Plantado")

    @discord.ui.button(label="Doblar", emoji="💎", style=discord.ButtonStyle.success)
    async def double_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.bet <= 0:
            await interaction.response.send_message("En showcase no se puede doblar apuesta.", ephemeral=True)
            return
        cash = await _xaucine_get_cash(self.ctx)
        if cash < self.bet * 2:
            await interaction.response.send_message("No tienes cash suficiente para doblar.", ephemeral=True)
            return
        self.bet *= 2
        self.player.append(self.deck.pop())
        await self._finish(interaction, "Doblado")

    @discord.ui.button(label="Reglas", emoji="📜", style=discord.ButtonStyle.secondary)
    async def rules_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_message(_xaucine_rules("blackjack"), ephemeral=True)


async def _xaucine_slots(ctx, cantidad="showcase"):
    cash = await _xaucine_get_cash(ctx)
    bet = _xaucine_parse_bet(cantidad, cash)
    if not await _xaucine_paycheck(ctx, bet):
        return
    msg = await ctx.reply(embed=_xaucine_embed(ctx, "🎰 Slots cinematográfico", "Preparando rodillos neón..."), mention_author=False)
    symbols_pool = ["🍒", "🍋", "🔔", "💎", "👑", "7️⃣"]
    final = [random.choice(symbols_pool) for _ in range(3)]
    jackpot = random.random() < 0.08
    if jackpot:
        final = ["👑", "👑", "👑"]
    frames = []
    for i in range(8):
        spin = [random.choice(symbols_pool) for _ in range(3)] if i < 7 else final
        frames.append(f"```text\n╔════════════════════╗\n║  🎰  {spin[0]} │ {spin[1]} │ {spin[2]}  🎰  ║\n╚════════════════════╝\n```\nRodillos: **{i+1}/8**\n{_xaucine_bar(i+1, 8)}")
    await _xaucine_edit_sequence(msg, ctx, "🎰 Slots cinematográfico", frames, _XAUCINE_GOLD, 0.35)
    if len(set(final)) == 1:
        mult = 12 if final[0] == "👑" else 6
    elif len(set(final)) == 2:
        mult = 2
    else:
        mult = 0
    net = 0 if bet == 0 else bet * mult - bet
    win = net >= 0 and mult > 0
    stats = await _xaucine_apply_result(ctx, "slots", bet, net, win)
    payload = {"symbols": final, "final": f"Resultado: {' │ '.join(final)}", "net_text": f"Neto {net:+}", "color": (241, 196, 15) if jackpot else ((46, 204, 113) if win else (231, 76, 60))}
    embed = _xaucine_embed(ctx, "🎰 Resultado Slots", f"```text\n╔════════════════════╗\n║  🎰  {final[0]} │ {final[1]} │ {final[2]}  🎰  ║\n╚════════════════════╝\n```\nMultiplicador: **x{mult}**\nNeto: **{_xaucine_money(ctx, net, True)}**", _XAUCINE_GOLD if jackpot else (_XAUCINE_GREEN if win else _XAUCINE_RED))
    embed.add_field(name="📊 Estadísticas", value=_xaucine_stats_field(stats), inline=False)
    embed.add_field(name="📜 Reglas", value=_xaucine_rules("slots"), inline=False)
    await msg.edit(embed=embed, view=XAUCineResultView(ctx.author.id, "slots", bet, payload))


async def _xaucine_ruleta(ctx, cantidad="showcase", eleccion="rojo"):
    cash = await _xaucine_get_cash(ctx)
    bet = _xaucine_parse_bet(cantidad, cash)
    if not await _xaucine_paycheck(ctx, bet):
        return
    eleccion = str(eleccion or "rojo").lower().strip()
    msg = await ctx.reply(embed=_xaucine_embed(ctx, "🎡 Ruleta europea cinematográfica", "La bola entra en el cilindro..."), mention_author=False)
    result = random.choice(_XAUCINE_ROULETTE_ORDER)
    pos = _XAUCINE_ROULETTE_ORDER.index(result)
    frames = []
    for i in range(14):
        n = _XAUCINE_ROULETTE_ORDER[(pos + 14 - i) % len(_XAUCINE_ROULETTE_ORDER)] if i < 13 else result
        color = "🟢" if n == 0 else ("🔴" if n in _XAUCINE_ROULETTE_RED else "⚫")
        frames.append(f"```text\n      {color} {n:02d}\n   ◜─────────◝\n  │  ◉   ◌   │\n   ◟─────────◞\n```\nApuesta: **{eleccion}**\nLa bola desacelera...\n{_xaucine_bar(i+1, 14)}")
    await _xaucine_edit_sequence(msg, ctx, "🎡 Ruleta europea cinematográfica", frames, _XAUCINE_PURPLE, 0.28)
    is_red = result in _XAUCINE_ROULETTE_RED
    result_color = "rojo" if is_red else ("verde" if result == 0 else "negro")
    win = False
    payout = 0
    if eleccion.isdigit() and int(eleccion) == result:
        win, payout = True, 36
    elif eleccion in {"rojo", "red"} and result_color == "rojo":
        win, payout = True, 2
    elif eleccion in {"negro", "black"} and result_color == "negro":
        win, payout = True, 2
    elif eleccion == "par" and result != 0 and result % 2 == 0:
        win, payout = True, 2
    elif eleccion == "impar" and result % 2 == 1:
        win, payout = True, 2
    elif eleccion in {"alto", "high"} and 19 <= result <= 36:
        win, payout = True, 2
    elif eleccion in {"bajo", "low"} and 1 <= result <= 18:
        win, payout = True, 2
    elif eleccion in {"docena1", "1docena"} and 1 <= result <= 12:
        win, payout = True, 3
    elif eleccion in {"docena2", "2docena"} and 13 <= result <= 24:
        win, payout = True, 3
    elif eleccion in {"docena3", "3docena"} and 25 <= result <= 36:
        win, payout = True, 3
    net = 0 if bet == 0 else (bet * payout - bet if win else -bet)
    stats = await _xaucine_apply_result(ctx, "ruleta", bet, net, win)
    payload = {"final": f"Cayó {result} {result_color}. Apuesta: {eleccion}", "net_text": f"Neto {net:+}", "color": (46, 204, 113) if win else (231, 76, 60)}
    embed = _xaucine_embed(ctx, "🎡 Resultado Ruleta", f"La bola cayó en **{result} {result_color}**.\nTu apuesta: **{eleccion}**\nPago: **x{payout}**\nNeto: **{_xaucine_money(ctx, net, True)}**", _XAUCINE_GREEN if win else _XAUCINE_RED)
    embed.add_field(name="📊 Estadísticas", value=_xaucine_stats_field(stats), inline=False)
    embed.add_field(name="📜 Reglas", value=_xaucine_rules("ruleta"), inline=False)
    await msg.edit(embed=embed, view=XAUCineResultView(ctx.author.id, "ruleta", bet, payload))


