async def _xaucine_poker(ctx, cantidad="showcase"):
    cash = await _xaucine_get_cash(ctx)
    bet = _xaucine_parse_bet(cantidad, cash)
    if not await _xaucine_paycheck(ctx, bet):
        return
    deck = _xaucine_deck()
    hand = [deck.pop() for _ in range(5)]
    before_name, before_mult = _xaucine_hand_name(hand)
    msg = await ctx.reply(embed=_xaucine_embed(ctx, "♠️ Poker cinematográfico", f"Repartiendo 5 cartas...\n```text\n{_xaucine_cards_row(hand)}\n```"), mention_author=False)
    await asyncio.sleep(0.8)
    # Estrategia automática ligera: si no hay pareja, cambia hasta 3 cartas bajas.
    counts = {r: [c[0] for c in hand].count(r) for r in set(c[0] for c in hand)}
    keep_ranks = {r for r, c in counts.items() if c >= 2}
    change_idx = [i for i, c in enumerate(hand) if c[0] not in keep_ranks][:3]
    for idx in change_idx:
        hand[idx] = deck.pop()
    after_name, mult = _xaucine_hand_name(hand)
    net = 0 if bet == 0 else (bet * mult - bet if mult > 0 else -bet)
    win = mult >= 1
    stats = await _xaucine_apply_result(ctx, "poker", bet, net, win)
    payload = {"cards": [f"{r}{s}" for r, s in hand], "final": f"{after_name} · x{mult}", "net_text": f"Neto {net:+}", "color": (46, 204, 113) if win else (231, 76, 60)}
    embed = _xaucine_embed(ctx, "♠️ Resultado Poker", f"Mano inicial: **{before_name}**\nCambio automático táctico: **{len(change_idx)} cartas**\n\n```text\n{_xaucine_cards_row(hand)}\n```\nMano final: **{after_name}** · Pago **x{mult}**\nNeto: **{_xaucine_money(ctx, net, True)}**", _XAUCINE_GREEN if win else _XAUCINE_RED)
    embed.add_field(name="📊 Estadísticas", value=_xaucine_stats_field(stats), inline=False)
    embed.add_field(name="📜 Reglas", value=_xaucine_rules("poker"), inline=False)
    await msg.edit(embed=embed, view=XAUCineResultView(ctx.author.id, "poker", bet, payload))


async def _xaucine_crash(ctx, cantidad="showcase"):
    cash = await _xaucine_get_cash(ctx)
    bet = _xaucine_parse_bet(cantidad, cash)
    if not await _xaucine_paycheck(ctx, bet):
        return
    msg = await ctx.reply(embed=_xaucine_embed(ctx, "🚀 Crash cinematográfico", "El cohete está cargando motores..."), mention_author=False)
    crash_at = round(random.uniform(1.25, 5.0), 2)
    cashout = round(random.uniform(1.15, crash_at + 0.65), 2)
    frames = []
    for i in range(10):
        mult = round(1.0 + i * 0.23, 2)
        frames.append(f"```text\n        🚀\n       /|\\\n      /_|_\\\n━━━━━━━━━━━━━━━━\n```\nMultiplicador: **x{mult:.2f}**\n{_xaucine_bar(i+1, 10)}")
    await _xaucine_edit_sequence(msg, ctx, "🚀 Crash cinematográfico", frames, _XAUCINE_BLUE, 0.32)
    win = cashout < crash_at
    net = 0 if bet == 0 else (int(bet * cashout) - bet if win else -bet)
    stats = await _xaucine_apply_result(ctx, "crash", bet, net, win)
    payload = {"final": f"Cashout x{cashout:.2f} · Crash x{crash_at:.2f}", "net_text": f"Neto {net:+}", "mult": cashout, "color": (46, 204, 113) if win else (231, 76, 60)}
    embed = _xaucine_embed(ctx, "🚀 Resultado Crash", f"Crash en **x{crash_at:.2f}**\nTu retirada: **x{cashout:.2f}**\nNeto: **{_xaucine_money(ctx, net, True)}**", _XAUCINE_GREEN if win else _XAUCINE_RED)
    embed.add_field(name="📊 Estadísticas", value=_xaucine_stats_field(stats), inline=False)
    embed.add_field(name="📜 Reglas", value=_xaucine_rules("crash"), inline=False)
    await msg.edit(embed=embed, view=XAUCineResultView(ctx.author.id, "crash", bet, payload))


async def _xaucine_dado(ctx, cantidad="showcase", eleccion="alto"):
    cash = await _xaucine_get_cash(ctx)
    bet = _xaucine_parse_bet(cantidad, cash)
    if not await _xaucine_paycheck(ctx, bet):
        return
    eleccion = str(eleccion or "alto").lower()
    msg = await ctx.reply(embed=_xaucine_embed(ctx, "🎲 Dados cinematográficos", "Los dados empiezan a rodar..."), mention_author=False)
    faces = ["⚀", "⚁", "⚂", "⚃", "⚄", "⚅"]
    frames = []
    for i in range(7):
        a, b = random.choice(faces), random.choice(faces)
        frames.append(f"```text\n╔══════════╗\n║   {a}  {b}   ║\n╚══════════╝\n```\nPredicción: **{eleccion}**\n{_xaucine_bar(i+1, 7)}")
    await _xaucine_edit_sequence(msg, ctx, "🎲 Dados cinematográficos", frames, _XAUCINE_PURPLE, 0.35)
    d1, d2 = random.randint(1, 6), random.randint(1, 6)
    total = d1 + d2
    win = (eleccion == "alto" and total >= 8) or (eleccion == "bajo" and total <= 6) or (eleccion in {"siete", "7"} and total == 7)
    payout = 5 if eleccion in {"siete", "7"} and win else (2 if win else 0)
    net = 0 if bet == 0 else (bet * payout - bet if win else -bet)
    stats = await _xaucine_apply_result(ctx, "dado", bet, net, win)
    payload = {"final": f"Dados {d1}+{d2}={total} · {eleccion}", "net_text": f"Neto {net:+}", "color": (46, 204, 113) if win else (231, 76, 60)}
    embed = _xaucine_embed(ctx, "🎲 Resultado Dados", f"Resultado: **{d1} + {d2} = {total}**\nPredicción: **{eleccion}**\nPago: **x{payout}**\nNeto: **{_xaucine_money(ctx, net, True)}**", _XAUCINE_GREEN if win else _XAUCINE_RED)
    embed.add_field(name="📊 Estadísticas", value=_xaucine_stats_field(stats), inline=False)
    await msg.edit(embed=embed, view=XAUCineResultView(ctx.author.id, "dado", bet, payload))


async def _xaucine_apostar(ctx, cantidad="showcase", eleccion="cara"):
    cash = await _xaucine_get_cash(ctx)
    bet = _xaucine_parse_bet(cantidad, cash)
    if not await _xaucine_paycheck(ctx, bet):
        return
    eleccion = str(eleccion or "cara").lower()
    msg = await ctx.reply(embed=_xaucine_embed(ctx, "🪙 Cara o cruz cinematográfico", "La moneda gira en el aire..."), mention_author=False)
    frames = []
    for i in range(8):
        frames.append(f"```text\n        {'🟡' if i % 2 else '⚪'}\n     ╱─────╲\n    │ {'CARA' if i % 2 else 'CRUZ'} │\n     ╲─────╱\n```\nElegiste: **{eleccion}**\n{_xaucine_bar(i+1, 8)}")
    await _xaucine_edit_sequence(msg, ctx, "🪙 Cara o cruz cinematográfico", frames, _XAUCINE_GOLD, 0.28)
    result = random.choice(["cara", "cruz"])
    win = result == eleccion
    net = 0 if bet == 0 else (bet if win else -bet)
    stats = await _xaucine_apply_result(ctx, "apostar", bet, net, win)
    payload = {"final": f"Salió {result}. Elegiste {eleccion}", "net_text": f"Neto {net:+}", "color": (46, 204, 113) if win else (231, 76, 60)}
    embed = _xaucine_embed(ctx, "🪙 Resultado Cara o cruz", f"Salió **{result}**.\nElegiste: **{eleccion}**\nNeto: **{_xaucine_money(ctx, net, True)}**", _XAUCINE_GREEN if win else _XAUCINE_RED)
    embed.add_field(name="📊 Estadísticas", value=_xaucine_stats_field(stats), inline=False)
    await msg.edit(embed=embed, view=XAUCineResultView(ctx.author.id, "apostar", bet, payload))


