# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║ Final public-bot layer: legacy commands can still contain visible Spanish   ║
# ║ text like "amatista/amatistas". This patch sanitizes outgoing Discord       ║
# ║ payloads at the last moment using the per-guild currency configuration.     ║
# ║ It does NOT rename internal item IDs or JSON keys, so old data stays safe.  ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

try:
    import re as _xau371_re
    import copy as _xau371_copy
except Exception:
    _xau371_re = re
    _xau371_copy = None

_XAU371_OLD_CONTEXT_SEND = getattr(commands.Context, "send", None)
_XAU371_OLD_CONTEXT_REPLY = getattr(commands.Context, "reply", None)
_XAU371_OLD_MESSAGEABLE_SEND = getattr(discord.abc.Messageable, "send", None)
_XAU371_OLD_INTERACTION_SEND_MESSAGE = getattr(discord.InteractionResponse, "send_message", None)
_XAU371_OLD_INTERACTION_EDIT = getattr(discord.Interaction, "edit_original_response", None)
_XAU371_OLD_WEBHOOK_SEND = getattr(discord.Webhook, "send", None)


def _xau371_get_guild_id(obj=None) -> int:
    """Best-effort guild id resolver for ctx/channel/interaction/webhook send payloads."""
    try:
        if obj is None:
            return 0
        guild = getattr(obj, "guild", None)
        if guild is not None and getattr(guild, "id", None):
            return int(guild.id)
        channel = getattr(obj, "channel", None)
        guild = getattr(channel, "guild", None)
        if guild is not None and getattr(guild, "id", None):
            return int(guild.id)
        message = getattr(obj, "message", None)
        guild = getattr(message, "guild", None)
        if guild is not None and getattr(guild, "id", None):
            return int(guild.id)
    except Exception:
        return 0
    return 0


def _xau371_currency_for(obj=None) -> dict:
    """Return the editable per-guild currency, with several compatibility fallbacks."""
    gid = _xau371_get_guild_id(obj)
    try:
        if callable(globals().get("xau_currency_for_guild_id")):
            cur = globals()["xau_currency_for_guild_id"](gid)
            if isinstance(cur, dict):
                return {
                    "emoji": str(cur.get("emoji") or "💎"),
                    "name": str(cur.get("name") or cur.get("singular") or "moneda"),
                    "plural": str(cur.get("plural") or "monedas"),
                }
    except Exception:
        pass
    try:
        path = os.path.join(BASE_DIR, "xau_guild_config.json")
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f) or {}
            node = None
            for key in (str(gid), gid):
                if isinstance(data, dict) and key in data:
                    node = data[key]
                    break
            if node is None and isinstance(data.get("guilds"), dict):
                node = data["guilds"].get(str(gid)) or data["guilds"].get(gid)
            if isinstance(node, dict):
                economy = node.get("economy", {}) if isinstance(node.get("economy", {}), dict) else {}
                cur = economy.get("currency") or node.get("currency") or node.get("moneda") or {}
                if isinstance(cur, dict):
                    return {
                        "emoji": str(cur.get("emoji") or cur.get("symbol") or "💎"),
                        "name": str(cur.get("name") or cur.get("singular") or cur.get("nombre") or "moneda"),
                        "plural": str(cur.get("plural") or cur.get("plural_name") or cur.get("nombre_plural") or "monedas"),
                    }
    except Exception:
        pass
    return {"emoji": "💎", "name": "moneda", "plural": "monedas"}


def _xau371_cap_first(value: str) -> str:
    try:
        return value[:1].upper() + value[1:]
    except Exception:
        return value


def _xau371_replace_currency_words(text_value: str, cur: dict) -> str:
    """Replace old visible currency words without touching internal code/data."""
    if not isinstance(text_value, str) or not text_value:
        return text_value
    emoji = str(cur.get("emoji") or "💎")
    singular = str(cur.get("name") or "moneda")
    plural = str(cur.get("plural") or "monedas")
    cap_singular = _xau371_cap_first(singular)
    cap_plural = _xau371_cap_first(plural)

    text_value = _xau371_re.sub(r"<a?:amatista:\d+>", emoji, text_value, flags=_xau371_re.IGNORECASE)

    # Amounts should normally use plural: "500 amatista" -> "500 monedas".
    text_value = _xau371_re.sub(r"(?i)(\d[\d\.,_\s]*\s*)(amatistas?|amethyst)", lambda m: m.group(1) + plural, text_value)

    # Standalone words keep singular/plural shape.
    replacements = (
        (r"\bAMATISTAS\b", plural.upper()),
        (r"\bAMATISTA\b", singular.upper()),
        (r"\bAmatistas\b", cap_plural),
        (r"\bAmatista\b", cap_singular),
        (r"\bamatistas\b", plural),
        (r"\bamatista\b", singular),
        (r"\bAmethyst\b", cap_singular),
        (r"\bamethyst\b", singular),
    )
    for pat, rep in replacements:
        text_value = _xau371_re.sub(pat, rep, text_value)
    return text_value


def _xau371_sanitize_any(obj, cur: dict):
    """Sanitize strings inside lists/dicts/embed dictionaries."""
    try:
        if isinstance(obj, str):
            return _xau371_replace_currency_words(obj, cur)
        if isinstance(obj, list):
            return [_xau371_sanitize_any(x, cur) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_xau371_sanitize_any(x, cur) for x in obj)
        if isinstance(obj, dict):
            return {k: _xau371_sanitize_any(v, cur) for k, v in obj.items()}
    except Exception:
        return obj
    return obj


def _xau371_sanitize_embed(embed, cur: dict):
    """Return a sanitized copy of a discord.Embed."""
    try:
        if embed is None:
            return None
        data = embed.to_dict()
        data = _xau371_sanitize_any(data, cur)
        return discord.Embed.from_dict(data)
    except Exception:
        # If copying fails, try in-place minimal cleanup.
        try:
            if getattr(embed, "title", None):
                embed.title = _xau371_replace_currency_words(embed.title, cur)
            if getattr(embed, "description", None):
                embed.description = _xau371_replace_currency_words(embed.description, cur)
        except Exception:
            pass
        return embed


def _xau371_sanitize_send_args(owner, args, kwargs):
    """Sanitize content/embed/embeds in Discord send-style calls."""
    cur = _xau371_currency_for(owner)
    args = list(args)
    if args and isinstance(args[0], str):
        args[0] = _xau371_replace_currency_words(args[0], cur)
    if "content" in kwargs and isinstance(kwargs.get("content"), str):
        kwargs["content"] = _xau371_replace_currency_words(kwargs["content"], cur)
    if kwargs.get("embed") is not None:
        kwargs["embed"] = _xau371_sanitize_embed(kwargs.get("embed"), cur)
    if kwargs.get("embeds") is not None:
        kwargs["embeds"] = [_xau371_sanitize_embed(e, cur) for e in list(kwargs.get("embeds") or [])]
    return tuple(args), kwargs


async def _xau371_context_send(self, *args, **kwargs):
    args, kwargs = _xau371_sanitize_send_args(self, args, kwargs)
    return await _XAU371_OLD_CONTEXT_SEND(self, *args, **kwargs)


async def _xau371_context_reply(self, *args, **kwargs):
    args, kwargs = _xau371_sanitize_send_args(self, args, kwargs)
    return await _XAU371_OLD_CONTEXT_REPLY(self, *args, **kwargs)


async def _xau371_messageable_send(self, *args, **kwargs):
    args, kwargs = _xau371_sanitize_send_args(self, args, kwargs)
    return await _XAU371_OLD_MESSAGEABLE_SEND(self, *args, **kwargs)


async def _xau371_interaction_send_message(self, *args, **kwargs):
    interaction = getattr(self, "_parent", None) or getattr(self, "_interaction", None)
    args, kwargs = _xau371_sanitize_send_args(interaction, args, kwargs)
    return await _XAU371_OLD_INTERACTION_SEND_MESSAGE(self, *args, **kwargs)


async def _xau371_interaction_edit_original_response(self, *args, **kwargs):
    args, kwargs = _xau371_sanitize_send_args(self, args, kwargs)
    return await _XAU371_OLD_INTERACTION_EDIT(self, *args, **kwargs)


async def _xau371_webhook_send(self, *args, **kwargs):
    args, kwargs = _xau371_sanitize_send_args(self, args, kwargs)
    return await _XAU371_OLD_WEBHOOK_SEND(self, *args, **kwargs)


