def _xau372_guild_from_obj(obj):
    try:
        guild = getattr(obj, "guild", None)
        if guild is not None:
            return guild
        channel = getattr(obj, "channel", None)
        guild = getattr(channel, "guild", None)
        if guild is not None:
            return guild
        message = getattr(obj, "message", None)
        guild = getattr(message, "guild", None)
        if guild is not None:
            return guild
        interaction = getattr(obj, "interaction", None) or getattr(obj, "_parent", None) or getattr(obj, "_interaction", None)
        guild = getattr(interaction, "guild", None)
        if guild is not None:
            return guild
    except Exception:
        return None
    return None


async def xau372_get_prefix(obj=None) -> str:
    """Return the effective prefix for the current guild, safely."""
    try:
        guild = _xau372_guild_from_obj(obj)
        if guild is not None and callable(globals().get("xau_get_guild_config")):
            cfg = await globals()["xau_get_guild_config"](int(guild.id))
            prefix = str(cfg.get("prefix") or XAU372_PREFIX_DEFAULT).strip()
            return prefix[:8] if prefix else XAU372_PREFIX_DEFAULT
    except Exception:
        pass
    return XAU372_PREFIX_DEFAULT


async def xau372_set_prefix_for_guild(guild_id: int, prefix: str) -> bool:
    """Persist the guild prefix in the existing public config file."""
    if not callable(globals().get("xau_get_guild_config")) or not callable(globals().get("xau_save_guild_config")):
        return False
    cfg = await globals()["xau_get_guild_config"](int(guild_id or 0))
    cfg["prefix"] = str(prefix)
    return bool(await globals()["xau_save_guild_config"](int(guild_id or 0), cfg))


def _xau372_command_names() -> set[str]:
    names = set()
    try:
        for command in list(getattr(bot, "commands", []) or []):
            if getattr(command, "hidden", False):
                continue
            name = str(getattr(command, "name", "") or "").strip()
            if name:
                names.add(name)
            for alias in list(getattr(command, "aliases", []) or []):
                alias = str(alias or "").strip()
                if alias:
                    names.add(alias)
    except Exception:
        pass
    return names


def _xau372_replace_prefix_words(text_value: str, prefix: str) -> str:
    """Rewrite hardcoded legacy !command examples to the guild prefix."""
    if not isinstance(text_value, str) or not text_value or not prefix or prefix == "!":
        return text_value
    try:
        names = _xau372_command_names()
        if not names:
            return text_value
        pattern = r"(?<![\w/])!({})(?=\b|[\s`.,:;!?)\]\}}<>]|$)".format("|".join(_xau372_re.escape(n) for n in sorted(names, key=len, reverse=True)))
        return _xau372_re.sub(pattern, lambda m: f"{prefix}{m.group(1)}", text_value)
    except Exception:
        return text_value


def _xau372_sanitize_any(obj, prefix: str):
    try:
        if isinstance(obj, str):
            return _xau372_replace_prefix_words(obj, prefix)
        if isinstance(obj, list):
            return [_xau372_sanitize_any(v, prefix) for v in obj]
        if isinstance(obj, tuple):
            return tuple(_xau372_sanitize_any(v, prefix) for v in obj)
        if isinstance(obj, dict):
            return {k: _xau372_sanitize_any(v, prefix) for k, v in obj.items()}
    except Exception:
        return obj
    return obj


def _xau372_sanitize_embed(embed, prefix: str):
    try:
        if embed is None:
            return None
        data = embed.to_dict()
        data = _xau372_sanitize_any(data, prefix)
        return discord.Embed.from_dict(data)
    except Exception:
        return embed


async def _xau372_sanitize_send_args(owner, args, kwargs):
    prefix = await xau372_get_prefix(owner)
    args = list(args)
    if args and isinstance(args[0], str):
        args[0] = _xau372_replace_prefix_words(args[0], prefix)
    if "content" in kwargs and isinstance(kwargs.get("content"), str):
        kwargs["content"] = _xau372_replace_prefix_words(kwargs["content"], prefix)
    if kwargs.get("embed") is not None:
        kwargs["embed"] = _xau372_sanitize_embed(kwargs.get("embed"), prefix)
    if kwargs.get("embeds") is not None:
        kwargs["embeds"] = [_xau372_sanitize_embed(e, prefix) for e in list(kwargs.get("embeds") or [])]
    return tuple(args), kwargs


