def _xau372_category_for(command) -> str:
    name = str(getattr(command, "name", "") or "").lower()
    aliases = {str(a).lower() for a in list(getattr(command, "aliases", []) or [])}
    tokens = {name} | aliases
    for category in XAU372_CATEGORY_ORDER:
        if category == "inicio":
            continue
        if tokens & XAU372_COMMAND_GROUPS.get(category, set()):
            return category
    return "otros"


def _xau372_short_desc(command) -> str:
    text = str(getattr(command, "brief", None) or getattr(command, "help", None) or getattr(command, "description", None) or "").strip()
    if not text:
        try:
            text = str(command.callback.__doc__ or "").strip()
        except Exception:
            text = ""
    text = " ".join(text.split())
    return text[:180] if text else "Sin descripción todavía."


def _xau372_collect_catalog():
    catalog = {cat: [] for cat in XAU372_CATEGORY_ORDER if cat != "inicio"}
    try:
        for command in sorted(list(bot.commands), key=lambda c: str(getattr(c, "name", "")).lower()):
            if getattr(command, "hidden", False):
                continue
            category = _xau372_category_for(command)
            aliases = [str(a) for a in list(getattr(command, "aliases", []) or [])[:5]]
            signature = str(getattr(command, "signature", "") or "").strip()
            catalog.setdefault(category, []).append({
                "name": str(getattr(command, "name", "?")),
                "aliases": aliases,
                "signature": signature,
                "desc": _xau372_short_desc(command),
            })
    except Exception as exc:
        print(f"[XAU HELP 3.7.2] collect failed: {exc!r}")
    return catalog


def _xau372_chunk(items, size=8):
    return [items[i:i + size] for i in range(0, len(items), size)] or [[]]


async def xau372_build_help_embed(obj, category="inicio", page=0, search=None):
    prefix = await xau372_get_prefix(obj)
    catalog = _xau372_collect_catalog()
    category = str(category or "inicio").lower().strip()
    if category in {"config", "setup", "ajustes"}:
        category = "configuracion"
    if category in {"member", "members", "membresia"}:
        category = "miembros"
    if category in {"money", "currency"}:
        category = "moneda"
    if category in {"ai", "aether"}:
        category = "ia"
    if category not in ["inicio"] + list(catalog.keys()):
        search = category if search is None else search
        category = "inicio"

    total_commands = sum(len(v) for v in catalog.values())
    guild = _xau372_guild_from_obj(obj)
    guild_name = getattr(guild, "name", "DM / Global") if guild else "DM / Global"

    embed = discord.Embed(
        title=f"{XAU372_CATEGORY_TITLES.get(category, '✨ Ayuda')} · X AETHER ULTRA",
        color=0x9B59B6,
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.set_footer(text=f"X AETHER ULTRA · Help Center {XAU372_HELP_VERSION} · Prefijo actual: {prefix}")

    try:
        user = getattr(obj, "author", None) or getattr(obj, "user", None)
        if user and getattr(user, "display_avatar", None):
            embed.set_thumbnail(url=user.display_avatar.url)
    except Exception:
        pass

    if search:
        q = str(search).lower().strip()
        results = []
        for cat, rows in catalog.items():
            for row in rows:
                hay = " ".join([row["name"], " ".join(row["aliases"]), row["desc"], cat]).lower()
                if q in hay:
                    results.append((cat, row))
        pages = _xau372_chunk(results, 8)
        page = max(0, min(int(page or 0), len(pages) - 1))
        embed.description = (
            f"╔════════════════════════════╗\n"
            f"║ 🔎 **Búsqueda:** `{search}`\n"
            f"║ 🧭 **Prefijo:** `{prefix}`\n"
            f"║ 🏠 **Servidor:** `{guild_name}`\n"
            f"╚════════════════════════════╝\n"
            f"Resultados: **{len(results)}** · Página **{page + 1}/{len(pages)}**"
        )
        for cat, row in pages[page]:
            aliases = f"\nAlias: " + ", ".join(f"`{prefix}{a}`" for a in row["aliases"]) if row["aliases"] else ""
            sig = f" {row['signature']}" if row["signature"] else ""
            embed.add_field(name=f"{prefix}{row['name']}{sig}", value=f"{row['desc']}{aliases}\nCategoría: **{cat}**", inline=False)
        if not results:
            embed.add_field(name="Sin resultados", value=f"Prueba `{prefix}ayuda`, `{prefix}ayuda minijuegos` o `{prefix}comandos moneda`.", inline=False)
        return embed

    if category == "inicio":
        embed.description = (
            "```text\n"
            "╔══════════════════════════════════════╗\n"
            "║        X AETHER ULTRA HELP CORE      ║\n"
            "║        Público · Multi-servidor      ║\n"
            "╚══════════════════════════════════════╝\n"
            "```\n"
            f"🧭 **Prefijo actual:** `{prefix}`\n"
            f"🏠 **Servidor:** `{guild_name}`\n"
            f"📦 **Comandos cargados:** `{total_commands}`\n\n"
            f"Usa `{prefix}ayuda <categoría>` o `{prefix}comandos <búsqueda>`.\n"
            f"Ejemplo: `{prefix}ayuda minijuegos`, `{prefix}ayuda configuracion`, `{prefix}comandos blackjack`."
        )
        for cat in XAU372_CATEGORY_ORDER:
            if cat == "inicio":
                continue
            count = len(catalog.get(cat, []))
            if count:
                embed.add_field(name=XAU372_CATEGORY_TITLES.get(cat, cat.title()), value=f"`{prefix}ayuda {cat}` · {count} comandos", inline=True)
        embed.add_field(
            name="🃏 Blackjack modo Texas Hold'em",
            value=f"Por defecto `{prefix}blackjack <apuesta>` abre Texas Hold'em estilo casino. Usa `{prefix}blackjack clasico <apuesta>` para el blackjack normal.",
            inline=False,
        )
        embed.add_field(name="⚙️ Cambiar prefijo", value=f"`{prefix}setprefix ?` · la ayuda se actualiza sola con el nuevo prefijo.", inline=False)
        return embed

    rows = catalog.get(category, [])
    pages = _xau372_chunk(rows, 8)
    page = max(0, min(int(page or 0), len(pages) - 1))
    embed.description = (
        f"╔════════════════════════════╗\n"
        f"║ 🧭 **Prefijo:** `{prefix}`\n"
        f"║ 📚 **Categoría:** `{category}`\n"
        f"║ 📄 **Página:** `{page + 1}/{len(pages)}`\n"
        f"╚════════════════════════════╝"
    )
    if not rows:
        embed.add_field(name="Categoría vacía", value=f"Usa `{prefix}ayuda` para ver todas las categorías.", inline=False)
        return embed
    for row in pages[page]:
        aliases = f"\nAlias: " + ", ".join(f"`{prefix}{a}`" for a in row["aliases"]) if row["aliases"] else ""
        sig = f" {row['signature']}" if row["signature"] else ""
        embed.add_field(name=f"{prefix}{row['name']}{sig}", value=f"{row['desc']}{aliases}", inline=False)
    return embed


class XAU372HelpCategorySelect(discord.ui.Select):
    def __init__(self, owner_id: int, current: str):
        options = []
        for cat in XAU372_CATEGORY_ORDER[:25]:
            options.append(discord.SelectOption(label=XAU372_CATEGORY_TITLES.get(cat, cat).replace("· X AETHER ULTRA", "")[:80], value=cat, default=(cat == current)))
        super().__init__(placeholder="Elige una categoría", min_values=1, max_values=1, options=options)
        self.owner_id = owner_id

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de ayuda no es tuyo.", ephemeral=True)
            return
        category = self.values[0]
        embed = await xau372_build_help_embed(interaction, category, 0)
        await interaction.response.edit_message(embed=embed, view=XAU372HelpView(self.owner_id, category, 0))


class XAU372HelpButton(discord.ui.Button):
    def __init__(self, label, action, style=discord.ButtonStyle.secondary):
        super().__init__(label=label, style=style)
        self.action = action

    async def callback(self, interaction: discord.Interaction):
        view: XAU372HelpView = self.view
        if interaction.user.id != view.owner_id:
            await interaction.response.send_message("Este panel de ayuda no es tuyo.", ephemeral=True)
            return
        if self.action == "home":
            view.category = "inicio"; view.page = 0
        elif self.action == "prev":
            view.page = max(0, view.page - 1)
        elif self.action == "next":
            view.page = view.page + 1
        embed = await xau372_build_help_embed(interaction, view.category, view.page)
        await interaction.response.edit_message(embed=embed, view=XAU372HelpView(view.owner_id, view.category, view.page))


class XAU372HelpView(discord.ui.View):
    def __init__(self, owner_id: int, category="inicio", page=0):
        super().__init__(timeout=120)
        self.owner_id = owner_id
        self.category = category or "inicio"
        self.page = int(page or 0)
        self.add_item(XAU372HelpCategorySelect(owner_id, self.category))
        self.add_item(XAU372HelpButton("◀", "prev"))
        self.add_item(XAU372HelpButton("🏠", "home", discord.ButtonStyle.blurple))
        self.add_item(XAU372HelpButton("▶", "next"))


