@bot.command(name="setprefix", aliases=["prefix", "prefijo"])
@commands.has_permissions(manage_guild=True)
@commands.cooldown(1, 8, commands.BucketType.guild)
async def xau372_setprefix(ctx, nuevo: str = None):
    if not ctx.guild:
        await ctx.reply("Este comando solo funciona dentro de servidores.", mention_author=False)
        return
    old = await xau372_get_prefix(ctx)
    if not nuevo:
        await ctx.reply(embed=discord.Embed(title="⚙️ Cambiar prefijo", description=f"Prefijo actual: `{old}`\nUso: `{old}setprefix <nuevo_prefijo>`\nEjemplo: `{old}setprefix ?`", color=0x9B59B6), mention_author=False)
        return
    nuevo = str(nuevo).strip()
    if len(nuevo) < 1 or len(nuevo) > 5 or any(ch.isspace() for ch in nuevo) or nuevo.startswith("<@"):
        await ctx.reply(embed=discord.Embed(title="⚠️ Prefijo inválido", description="Usa de 1 a 5 caracteres, sin espacios ni menciones.", color=0xE74C3C), mention_author=False)
        return
    ok = await xau372_set_prefix_for_guild(ctx.guild.id, nuevo)
    if not ok:
        await ctx.reply(embed=discord.Embed(title="⚠️ No pude guardar el prefijo", description="No encontré el sistema de configuración pública. Revisa `xau_guild_config.json`.", color=0xE74C3C), mention_author=False)
        return
    embed = discord.Embed(
        title="✅ Prefijo actualizado",
        description=f"Antes: `{old}`\nAhora: `{nuevo}`\n\nLa ayuda ya usará el prefijo nuevo automáticamente.\nPrueba: `{nuevo}ayuda`",
        color=0x57F287,
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    await ctx.reply(embed=embed, mention_author=False)


