# ──────────────────────────────────────────────────────────────────────────────
# Blackjack Hold'em mode: !blackjack now can run Texas Hold'em using the same
# premium card-table style. Classic blackjack remains available with "clasico".
# ──────────────────────────────────────────────────────────────────────────────

async def xau372_get_blackjack_mode(ctx) -> str:
    try:
        if ctx.guild and callable(globals().get("xau_get_guild_config")):
            cfg = await globals()["xau_get_guild_config"](ctx.guild.id)
            casino = cfg.get("casino", {}) if isinstance(cfg.get("casino", {}), dict) else {}
            mode = str(casino.get("blackjack_mode") or "texas_holdem").lower()
            if mode in {"classic", "clasico", "blackjack"}:
                return "classic"
    except Exception:
        pass
    return "texas_holdem"


async def xau372_save_blackjack_mode(ctx, mode: str) -> bool:
    if not ctx.guild or not callable(globals().get("xau_get_guild_config")) or not callable(globals().get("xau_save_guild_config")):
        return False
    cfg = await globals()["xau_get_guild_config"](ctx.guild.id)
    casino = cfg.setdefault("casino", {})
    if not isinstance(casino, dict):
        cfg["casino"] = casino = {}
    casino["blackjack_mode"] = "classic" if mode == "classic" else "texas_holdem"
    return bool(await globals()["xau_save_guild_config"](ctx.guild.id, cfg))


def xau372_parse_blackjack_args(tokens):
    mode = None
    bet = "showcase"
    for raw in list(tokens or []):
        token = str(raw or "").strip()
        low = token.lower()
        if not token:
            continue
        if low in {"texas", "holdem", "texasholdem", "th", "poker"}:
            mode = "texas_holdem"
            continue
        if low in {"clasico", "clásico", "classic", "bj", "blackjack", "21", "veintiuno"}:
            mode = "classic"
            continue
        bet = token
    return bet, mode


async def xau372_launch_texas_holdem_from_blackjack(ctx, bet="showcase"):
    """Launch existing Texas Hold'em table with blackjack command semantics."""
    if "xauig_launch" in globals() and "XAU340TexasHoldemView" in globals():
        await globals()["xauig_launch"](ctx, bet, globals()["XAU340TexasHoldemView"], "texasholdem", "Blackjack Hold'em")
        return
    if "texas_holdem_340" in globals() and callable(globals()["texas_holdem_340"]):
        await globals()["texas_holdem_340"](ctx, bet)
        return
    await ctx.reply(embed=discord.Embed(title="⚠️ Texas Hold'em no disponible", description="No encontré la mesa Texas Hold'em cargada en este archivo.", color=0xE74C3C), mention_author=False)


for _xau372_game_cmd in ("blackjack", "bj", "veintiuno", "texasholdem", "holdem", "th", "texas", "setcasino", "casino_config"):
    with _xau372_contextlib.suppress(Exception):
        bot.remove_command(_xau372_game_cmd)


