# X AETHER ULTRA 3.7.3 · CARD VISUALS INSIDE MINIGAMES
# Adds small in-game card images for Blackjack, Poker and Texas Hold'em.
# Keeps the same interactive style, but the table now includes rendered cards.
# ═══════════════════════════════════════════════════════════════════════════
try:
    import io as _xau373_io
    from PIL import Image as _XAU373_Image, ImageDraw as _XAU373_ImageDraw, ImageFont as _XAU373_ImageFont
    XAU373_PIL_OK = True
except Exception as _xau373_pil_exc:
    _XAU373_Image = _XAU373_ImageDraw = _XAU373_ImageFont = None
    XAU373_PIL_OK = False
    print(f"[X AETHER ULTRA] card visuals disabled: {_xau373_pil_exc!r}")

XAU373_CARD_VERSION = "3.7.3"
XAU373_SUIT_COLORS = {"♥": (210, 40, 55), "♦": (210, 40, 55), "♠": (28, 28, 35), "♣": (28, 28, 35)}
XAU373_TABLE_BG = (31, 18, 44)
XAU373_TABLE_ACCENT = (126, 87, 194)
XAU373_PANEL = (52, 34, 74)
XAU373_GOLD = (245, 203, 88)


def xau373_font(size=24, bold=False):
    if not XAU373_PIL_OK:
        return None
    candidates = []
    if bold:
        candidates += [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf",
        ]
    candidates += [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
    ]
    for path in candidates:
        try:
            return _XAU373_ImageFont.truetype(path, size=size)
        except Exception:
            continue
    try:
        return _XAU373_ImageFont.load_default()
    except Exception:
        return None


def xau373_round_rect(draw, box, radius=18, fill=(255,255,255), outline=None, width=2):
    try:
        draw.rounded_rectangle(box, radius=radius, fill=fill, outline=outline, width=width)
    except Exception:
        draw.rectangle(box, fill=fill, outline=outline, width=width)


def xau373_card_parts(card):
    if not isinstance(card, str) or card in {"🂠", "?", ""}:
        return ("", "", True)
    try:
        return (card[:-1], card[-1], False)
    except Exception:
        return ("", "", True)


def xau373_draw_card(draw, x, y, card, w=96, h=136, held=False):
    rank, suit, hidden = xau373_card_parts(card)
    if hidden:
        xau373_round_rect(draw, (x, y, x+w, y+h), radius=16, fill=(67, 44, 103), outline=(180, 150, 255), width=3)
        for gy in range(y+10, y+h-10, 16):
            draw.line((x+10, gy, x+w-10, gy), fill=(112, 82, 160), width=2)
        f = xau373_font(28, True)
        draw.text((x + w/2, y + h/2), "X", fill=(240, 230, 255), font=f, anchor="mm")
        return
    fill = (255,255,255)
    outline = XAU373_GOLD if held else (185, 185, 205)
    xau373_round_rect(draw, (x, y, x+w, y+h), radius=16, fill=fill, outline=outline, width=4 if held else 2)
    color = XAU373_SUIT_COLORS.get(suit, (30,30,30))
    fr = xau373_font(26, True)
    fs = xau373_font(28, True)
    fm = xau373_font(38, True)
    draw.text((x+14, y+12), rank, fill=color, font=fr)
    draw.text((x+w-14, y+h-12), rank, fill=color, font=fr, anchor="rs")
    draw.text((x+16, y+38), suit, fill=color, font=fs)
    draw.text((x+w/2, y+h/2), suit, fill=color, font=fm, anchor="mm")
    draw.text((x+w-16, y+h-32), suit, fill=color, font=fs, anchor="rs")
    if held:
        badge_w, badge_h = 34, 18
        bx1, by1 = x+w-badge_w-8, y+8
        xau373_round_rect(draw, (bx1, by1, bx1+badge_w, by1+badge_h), radius=8, fill=(39, 126, 74), outline=(220,255,230), width=1)
        fb = xau373_font(12, True)
        draw.text((bx1 + badge_w/2, by1 + badge_h/2), "HOLD", fill=(245,255,245), font=fb, anchor="mm")


def xau373_draw_title(draw, text, W):
    f1 = xau373_font(26, True)
    f2 = xau373_font(15, False)
    draw.text((W//2, 28), text, fill=(245, 240, 255), font=f1, anchor="mm")
    draw.text((W//2, 54), "X AETHER ULTRA · Casino interactivo", fill=(220, 210, 245), font=f2, anchor="mm")


def xau373_section(draw, title, y, W):
    f = xau373_font(18, True)
    xau373_round_rect(draw, (26, y, W-26, y+28), radius=10, fill=XAU373_PANEL, outline=(120, 92, 176), width=1)
    draw.text((42, y+14), title, fill=(243,236,255), font=f, anchor="lm")


def xau373_cards_png(cards_rows, title="Mesa", labels=None, held_rows=None):
    if not XAU373_PIL_OK:
        return None
    rows = [list(r or []) for r in cards_rows]
    labels = list(labels or ["Mesa"] * len(rows))
    held_rows = held_rows or [[] for _ in rows]
    card_w, card_h, gap = 96, 136, 14
    max_len = max([len(r) for r in rows] + [1])
    W = max(760, 60 + max_len * (card_w + gap) + 40)
    row_gap = 196
    H = 96 + len(rows) * row_gap + 24
    img = _XAU373_Image.new("RGB", (W, H), XAU373_TABLE_BG)
    draw = _XAU373_ImageDraw.Draw(img)
    xau373_round_rect(draw, (10, 10, W-10, H-10), radius=28, fill=(35, 22, 50), outline=(118, 79, 180), width=3)
    xau373_draw_title(draw, title, W)
    for idx, row in enumerate(rows):
        y0 = 86 + idx * row_gap
        xau373_section(draw, labels[idx], y0, W)
        row_y = y0 + 42
        total_w = max(1, len(row)) * (card_w + gap) - gap
        start_x = max(28, (W - total_w)//2)
        held = held_rows[idx] if idx < len(held_rows) else []
        for j, card in enumerate(row):
            is_held = j < len(held) and bool(held[j])
            xau373_draw_card(draw, start_x + j*(card_w+gap), row_y, card, card_w, card_h, held=is_held)
    bio = _xau373_io.BytesIO()
    img.save(bio, format="PNG")
    bio.seek(0)
    return bio


def xau373_attach_visual(embed, bio, filename="xau_cards.png"):
    if not bio:
        return None
    try:
        embed.set_image(url=f"attachment://{filename}")
    except Exception:
        pass
    return discord.File(bio, filename=filename)


def xau373_file_for_view(view):
    if not XAU373_PIL_OK:
        return None
    state = getattr(view, "_xau373_state", {}) or {}
    reveal = bool(state.get("reveal", False))
    try:
        if isinstance(view, XAU340BlackjackView):
            dealer = list(getattr(view, "dealer", []) or [])
            if not reveal and len(dealer) >= 2:
                dealer = [dealer[0], "🂠"] + dealer[2:]
            bio = xau373_cards_png([dealer, list(getattr(view, "player", []) or [])], title="Blackjack", labels=["Dealer", "Tu mano"])
            return xau373_attach_visual(state.get("embed"), bio, "xau_blackjack.png")
        if isinstance(view, XAUPokerView):
            hand = list(getattr(view, "hand", []) or [])
            held = list(getattr(view, "hold", []) or [])
            bio = xau373_cards_png([hand], title="Poker 5 Card Draw", labels=["Tu mano"], held_rows=[held])
            return xau373_attach_visual(state.get("embed"), bio, "xau_poker.png")
        if isinstance(view, XAU340TexasHoldemView):
            board = list(getattr(view, "board", []) or [])
            while len(board) < 5:
                board.append("🂠")
            rival = list(getattr(view, "bot_hand", []) or [])
            if not reveal and len(rival) >= 2:
                rival = [rival[0], "🂠"] + rival[2:]
            bio = xau373_cards_png([rival, board, list(getattr(view, "player", []) or [])], title="Texas Hold'em", labels=["Rival X AETHER", "Mesa comunitaria", "Tus cartas"])
            return xau373_attach_visual(state.get("embed"), bio, "xau_texas.png")
    except Exception as exc:
        print(f"[X AETHER ULTRA] card visual generation error: {exc!r}")
    return None


def xau373_wrap_render(cls, method_name="render"):
    try:
        old = getattr(cls, method_name)
    except Exception:
        return
    if getattr(old, "_xau373_wrapped", False):
        return
    def wrapped(self, *args, **kwargs):
        embed = old(self, *args, **kwargs)
        reveal = False
        if args:
            first = args[0]
            if isinstance(first, bool):
                reveal = first
        if "reveal" in kwargs:
            reveal = bool(kwargs.get("reveal"))
        self._xau373_state = {"reveal": reveal, "embed": embed}
        xau373_file_for_view(self)
        return embed
    wrapped._xau373_wrapped = True
    setattr(cls, method_name, wrapped)


for _xau373_cls in (XAU340BlackjackView, XAUPokerView, XAU340TexasHoldemView):
    xau373_wrap_render(_xau373_cls)


async def xau373_safe_edit(self, interaction: discord.Interaction, embed: discord.Embed, view=None):
    view = self if view is None else view
    try:
        self._xau373_state = getattr(self, "_xau373_state", {}) or {}
        self._xau373_state["embed"] = embed
    except Exception:
        pass
    file = xau373_file_for_view(self)
    kwargs = {"embed": embed, "view": view}
    if file:
        kwargs["attachments"] = [file]
    try:
        if interaction.response.is_done():
            await interaction.message.edit(**kwargs)
        else:
            try:
                await interaction.response.edit_message(**kwargs)
            except Exception:
                await interaction.response.defer()
                await interaction.message.edit(**kwargs)
    except Exception:
        try:
            if not interaction.response.is_done():
                await interaction.response.send_message(embed=embed, ephemeral=True)
            else:
                await interaction.followup.send(embed=embed, ephemeral=True)
        except Exception:
            pass

XAUOwnerView.safe_edit = xau373_safe_edit


async def xau373_launch(ctx, amount, view_cls, game_key, title):
    bet, showcase, datos = await xauig_parse_bet(ctx, amount)
    if bet is None:
        await ctx.send(embed=xauig_embed("💸 Cash insuficiente", "No tienes saldo suficiente para esa apuesta.", XAU_GAME_COLOR_LOSS, ctx.author)); return
    ok = await xauig_lock_bet(ctx, bet, datos)
    if not ok:
        await ctx.send(embed=xauig_embed("💸 Cash insuficiente", "Tu saldo cambió antes de bloquear la apuesta.", XAU_GAME_COLOR_LOSS, ctx.author)); return
    view = view_cls(ctx, bet, showcase)
    try:
        view.stats = await xauig_get_stats(ctx, game_key)
    except Exception:
        view.stats = {}
    embed = view.render("Showcase sin apuesta" if showcase else "Mesa abierta", XAU_GAME_COLOR_INFO)
    file = xau373_file_for_view(view)
    send_kwargs = {"embed": embed, "view": view}
    if file:
        send_kwargs["file"] = file
    msg = await ctx.send(**send_kwargs)
    view.message = msg
    if isinstance(view, XAUMemoryView):
        asyncio.create_task(view.start_hide(msg))

xauig_launch = xau373_launch

