import contextlib as _xautv_contextlib

XAUTV_VERSION = "4.1.0"
XAUTV_FILE = os.path.join(BASE_DIR, "xau_tempvoice.json")
XAUTV_COLOR = 0x9B5CFF
XAUTV_OK = 0x57F287
XAUTV_WARN = 0xFEE75C
XAUTV_BAD = 0xED4245
XAUTV_LOCK = asyncio.Lock()


def _xautv_now() -> str:
    try:
        return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")
    except Exception:
        return str(datetime.datetime.utcnow())


def _xautv_default_state() -> dict:
    return {"version": XAUTV_VERSION, "guilds": {}, "active": {}, "history": []}


def _xautv_default_guild() -> dict:
    return {
        "enabled": True,
        "delete_delay": 2,
        "panel_mode": "voice",  # voice / off
        "default_name": "🔊 Sala de {user}",
        "default_limit": 0,
        "default_bitrate": 64000,
        "creators": {},
    }


def _xautv_clean_state(data: Any) -> dict:
    if not isinstance(data, dict):
        data = _xautv_default_state()
    data.setdefault("version", XAUTV_VERSION)
    data.setdefault("guilds", {})
    data.setdefault("active", {})
    data.setdefault("history", [])
    if not isinstance(data["guilds"], dict):
        data["guilds"] = {}
    if not isinstance(data["active"], dict):
        data["active"] = {}
    return data


async def xautv_load() -> dict:
    async with XAUTV_LOCK:
        def _read():
            if not os.path.exists(XAUTV_FILE):
                return _xautv_default_state()
            with open(XAUTV_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        try:
            return _xautv_clean_state(await asyncio.to_thread(_read))
        except Exception as exc:
            print(f"[XAUTV] load error: {exc!r}")
            return _xautv_default_state()


async def xautv_save(data: dict) -> None:
    data = _xautv_clean_state(data)
    async with XAUTV_LOCK:
        def _write():
            folder = os.path.dirname(XAUTV_FILE) or "."
            os.makedirs(folder, exist_ok=True)
            with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False, dir=folder, suffix=".tmp") as tmp:
                json.dump(data, tmp, ensure_ascii=False, indent=2)
                tmp.flush()
                os.fsync(tmp.fileno())
                tmp_name = tmp.name
            os.replace(tmp_name, XAUTV_FILE)
        try:
            await asyncio.to_thread(_write)
        except Exception as exc:
            print(f"[XAUTV] save error: {exc!r}")


async def xautv_get_guild_cfg(guild_id: int) -> dict:
    data = await xautv_load()
    gid = str(guild_id)
    guild_cfg = data["guilds"].setdefault(gid, _xautv_default_guild())
    base = _xautv_default_guild()
    for k, v in base.items():
        guild_cfg.setdefault(k, v if not isinstance(v, dict) else {})
    return guild_cfg


def _xautv_int(value: Any, default: int = 0, low: int | None = None, high: int | None = None) -> int:
    try:
        n = int(value)
    except Exception:
        n = int(default)
    if low is not None:
        n = max(low, n)
    if high is not None:
        n = min(high, n)
    return n


def _xautv_sanitize_name(name: str, fallback: str = "Sala") -> str:
    name = str(name or fallback)
    name = re.sub(r"[\r\n\t]+", " ", name)
    name = re.sub(r"[`*_~|<>@#]+", "", name)
    name = re.sub(r"\s{2,}", " ", name).strip()
    return (name or fallback)[:90]


def _xautv_format_name(template: str, member: discord.Member, counter: int = 1) -> str:
    display = getattr(member, "display_name", None) or getattr(member, "name", "usuario")
    values = {
        "user": display,
        "username": getattr(member, "name", display),
        "display": display,
        "id": str(getattr(member, "id", "")),
        "counter": str(counter),
        "guild": getattr(getattr(member, "guild", None), "name", "server"),
    }
    try:
        name = str(template or "🔊 Sala de {user}").format(**values)
    except Exception:
        name = f"🔊 Sala de {display}"
    return _xautv_sanitize_name(name, f"Sala de {display}")


def _xautv_embed(title: str, desc: str = "", color: int = XAUTV_COLOR, guild: discord.Guild | None = None) -> discord.Embed:
    embed = discord.Embed(title=title, description=desc, color=color, timestamp=datetime.datetime.now(datetime.timezone.utc))
    embed.set_footer(text=f"X AETHER TempVoice {XAUTV_VERSION} · canales temporales gratis")
    if guild and getattr(guild, "icon", None):
        with _xautv_contextlib.suppress(Exception):
            embed.set_thumbnail(url=guild.icon.url)
    return embed


async def _xautv_reply(interaction: discord.Interaction, *, embed: discord.Embed | None = None, content: str | None = None, view: discord.ui.View | None = None, ephemeral: bool = True):
    try:
        if interaction.response.is_done():
            return await interaction.followup.send(content=content, embed=embed, view=view, ephemeral=ephemeral)
        return await interaction.response.send_message(content=content, embed=embed, view=view, ephemeral=ephemeral)
    except Exception as exc:
        print(f"[XAUTV] reply error: {exc!r}")


def _xautv_is_admin(member: discord.Member | None) -> bool:
    if not member:
        return False
    perms = getattr(member, "guild_permissions", None)
    return bool(perms and (perms.administrator or perms.manage_guild or perms.manage_channels))


async def _xautv_require_admin(interaction: discord.Interaction) -> bool:
    if _xautv_is_admin(interaction.user):
        return True
    await _xautv_reply(interaction, embed=_xautv_embed("⛔ Permiso insuficiente", "Necesitas `Gestionar servidor` o `Gestionar canales`.", XAUTV_BAD, interaction.guild), ephemeral=True)
    return False


def _xautv_member_voice(member: discord.Member | discord.User | None) -> discord.VoiceChannel | None:
    try:
        channel = member.voice.channel
        if isinstance(channel, discord.VoiceChannel):
            return channel
    except Exception:
        return None
    return None


async def _xautv_active_for_voice(voice_id: int) -> dict | None:
    data = await xautv_load()
    item = data.get("active", {}).get(str(voice_id))
    return item if isinstance(item, dict) else None


async def _xautv_active_for_member(member: discord.Member) -> tuple[discord.VoiceChannel | None, dict | None]:
    vc = _xautv_member_voice(member)
    if not vc:
        return None, None
    return vc, await _xautv_active_for_voice(vc.id)


async def _xautv_owner_check(interaction: discord.Interaction) -> tuple[discord.VoiceChannel | None, dict | None, bool]:
    if not interaction.guild or not isinstance(interaction.user, discord.Member):
        await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Solo en servidor", "Este comando solo funciona dentro de un servidor.", XAUTV_WARN), ephemeral=True)
        return None, None, False
    vc, active = await _xautv_active_for_member(interaction.user)
    if not vc or not active:
        await _xautv_reply(interaction, embed=_xautv_embed("🎙️ No estás en una sala temporal", "Entra primero a una sala creada por AETHER TempVoice.", XAUTV_WARN, interaction.guild), ephemeral=True)
        return None, None, False
    owner_id = _xautv_int(active.get("owner_id"), 0)
    if owner_id != interaction.user.id and not _xautv_is_admin(interaction.user):
        await _xautv_reply(interaction, embed=_xautv_embed("👑 Solo el dueño", "Solo el dueño de la sala o un administrador puede usar este control.", XAUTV_BAD, interaction.guild), ephemeral=True)
        return vc, active, False
    return vc, active, True


async def _xautv_update_active(voice_id: int, **changes) -> dict | None:
    data = await xautv_load()
    item = data.get("active", {}).get(str(voice_id))
    if not isinstance(item, dict):
        return None
    item.update(changes)
    item["updated_at"] = _xautv_now()
    data["active"][str(voice_id)] = item
    await xautv_save(data)
    return item


async def _xautv_remove_active(voice_id: int) -> None:
    data = await xautv_load()
    data.get("active", {}).pop(str(voice_id), None)
    await xautv_save(data)


def _xautv_base_voice_overwrites(guild: discord.Guild, owner: discord.Member, *, locked: bool = False, hidden: bool = False) -> dict:
    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=not hidden, connect=not locked),
        owner: discord.PermissionOverwrite(view_channel=True, connect=True, speak=True, stream=True, use_voice_activation=True, send_messages=True, read_message_history=True, embed_links=True),
        guild.me: discord.PermissionOverwrite(view_channel=True, connect=True, speak=True, move_members=True, manage_channels=True, manage_permissions=True, send_messages=True, read_message_history=True, embed_links=True),
    }
    return overwrites


async def _xautv_send_panel_to_voice_chat(voice: discord.VoiceChannel, owner: discord.Member, active: dict) -> discord.Message | None:
    """Envía el panel en el chat integrado del propio canal de voz."""
    try:
        embed = _xautv_panel_embed(voice, owner, active)
        msg = await voice.send(embed=embed, view=XAUTVControlPanel(voice.id))
        return msg
    except Exception as exc:
        print(f"[XAUTV] send voice-chat panel error: {exc!r}")
        return None


def _xautv_panel_embed(voice: discord.VoiceChannel, owner: discord.Member | None, active: dict) -> discord.Embed:
    owner_txt = owner.mention if owner else f"`{active.get('owner_id', 'desconocido')}`"
    locked = "🔒 Bloqueada" if active.get("locked") else "🔓 Abierta"
    hidden = "👻 Oculta" if active.get("hidden") else "👁️ Visible"
    limit = getattr(voice, "user_limit", 0) or 0
    bitrate = int((getattr(voice, "bitrate", 0) or 0) / 1000)
    embed = _xautv_embed("🎛️ Panel de sala temporal", f"Controla tu canal como un mini-dashboard dentro del servidor.", XAUTV_COLOR, voice.guild)
    embed.add_field(name="🎙️ Sala", value=f"{voice.mention}\n`{voice.name}`", inline=True)
    embed.add_field(name="👑 Dueño", value=owner_txt, inline=True)
    embed.add_field(name="👥 Límite", value="Sin límite" if limit == 0 else str(limit), inline=True)
    embed.add_field(name="Estado", value=f"{locked}\n{hidden}\n🔊 {bitrate} kbps", inline=True)
    embed.add_field(name="Comandos rápidos", value="`/voice name` · `/voice limit` · `/voice invite` · `/voice block` · `/voice transfer`", inline=False)
    embed.add_field(name="Auto limpieza", value="Cuando la sala queda vacía se elimina la voz; el panel desaparece con su chat integrado.", inline=False)
    return embed


async def _xautv_refresh_panel(voice: discord.VoiceChannel, active: dict | None = None) -> None:
    try:
        active = active or await _xautv_active_for_voice(voice.id)
        if not active:
            return
        msg_id = _xautv_int(active.get("panel_message_id"), 0)
        if not msg_id:
            return
        owner = voice.guild.get_member(_xautv_int(active.get("owner_id"), 0))
        msg = await voice.fetch_message(msg_id)
        await msg.edit(embed=_xautv_panel_embed(voice, owner, active), view=XAUTVControlPanel(voice.id))
    except Exception as exc:
        print(f"[XAUTV] refresh voice-chat panel error: {exc!r}")


async def _xautv_delete_room(voice: discord.VoiceChannel, reason: str = "X AETHER TempVoice cleanup") -> None:
    # El panel vive dentro del chat del propio canal de voz, así que al borrar la voz
    # desaparece el panel con ella. No se crean ni se borran canales de texto extra.
    await _xautv_remove_active(voice.id)
    with _xautv_contextlib.suppress(Exception):
        await voice.delete(reason=reason)


async def _xautv_create_room(member: discord.Member, creator: discord.VoiceChannel, cfg: dict) -> None:
    guild = member.guild
    if not guild or not guild.me:
        return
    perms = guild.me.guild_permissions
    if not (perms.manage_channels and perms.move_members):
        print(f"[XAUTV] Missing permissions in {guild.name}: manage_channels/move_members")
        return
    category = guild.get_channel(_xautv_int(cfg.get("category_id"), 0)) or creator.category
    if category is not None and not isinstance(category, discord.CategoryChannel):
        category = creator.category
    data = await xautv_load()
    active_count = sum(1 for a in data.get("active", {}).values() if isinstance(a, dict) and _xautv_int(a.get("guild_id"), 0) == guild.id)
    limit = _xautv_int(cfg.get("limit", 0), 0, 0, 99)
    bitrate = _xautv_int(cfg.get("bitrate", 64000), 64000, 8000, max(8000, guild.bitrate_limit))
    locked = bool(cfg.get("locked_by_default", False))
    hidden = bool(cfg.get("hidden_by_default", False))
    name = _xautv_format_name(cfg.get("name", "🔊 Sala de {user}"), member, active_count + 1)
    overwrites = _xautv_base_voice_overwrites(guild, member, locked=locked, hidden=hidden)
    try:
        voice = await guild.create_voice_channel(
            name=name,
            category=category,
            user_limit=limit,
            bitrate=bitrate,
            overwrites=overwrites,
            reason=f"X AETHER TempVoice creado por {member} desde {creator.name}",
        )
        await member.move_to(voice, reason="X AETHER TempVoice join-to-create")
    except Exception as exc:
        print(f"[XAUTV] create room error: {exc!r}")
        with _xautv_contextlib.suppress(Exception):
            if 'voice' in locals():
                await voice.delete(reason="X AETHER TempVoice rollback por error")
        return

    active = {
        "guild_id": guild.id,
        "voice_id": voice.id,
        "creator_id": creator.id,
        "owner_id": member.id,
        "panel_channel_id": voice.id,
        "panel_location": "voice_chat",
        "panel_message_id": 0,
        "name": name,
        "limit": limit,
        "bitrate": bitrate,
        "locked": locked,
        "hidden": hidden,
        "trusted": [],
        "blocked": [],
        "created_at": _xautv_now(),
        "updated_at": _xautv_now(),
    }

    data = await xautv_load()
    data.setdefault("active", {})[str(voice.id)] = active
    data.setdefault("history", []).append({"event": "create", "guild_id": guild.id, "voice_id": voice.id, "owner_id": member.id, "creator_id": creator.id, "at": _xautv_now()})
    data["history"] = data.get("history", [])[-250:]
    await xautv_save(data)

    guild_cfg = data.get("guilds", {}).get(str(guild.id), {}) if isinstance(data, dict) else {}
    panel_mode = str(guild_cfg.get("panel_mode", "voice")).lower()
    if panel_mode != "off" and bool(cfg.get("panel", True)):
        msg = await _xautv_send_panel_to_voice_chat(voice, member, active)
        if msg:
            active["panel_channel_id"] = voice.id
            active["panel_location"] = "voice_chat"
            active["panel_message_id"] = msg.id
            await _xautv_update_active(
                voice.id,
                panel_channel_id=voice.id,
                panel_location="voice_chat",
                panel_message_id=active["panel_message_id"],
            )


async def _xautv_set_lock(voice: discord.VoiceChannel, active: dict, locked: bool) -> dict | None:
    try:
        await voice.set_permissions(voice.guild.default_role, connect=not locked, reason="X AETHER TempVoice lock/unlock")
        active = await _xautv_update_active(voice.id, locked=locked)
        await _xautv_refresh_panel(voice, active)
        return active
    except Exception as exc:
        print(f"[XAUTV] lock error: {exc!r}")
        return None


async def _xautv_set_hidden(voice: discord.VoiceChannel, active: dict, hidden: bool) -> dict | None:
    try:
        await voice.set_permissions(voice.guild.default_role, view_channel=not hidden, reason="X AETHER TempVoice hide/show")
        active = await _xautv_update_active(voice.id, hidden=hidden)
        await _xautv_refresh_panel(voice, active)
        return active
    except Exception as exc:
        print(f"[XAUTV] hide error: {exc!r}")
        return None


def _xautv_parse_user_id(raw: str) -> int:
    raw = str(raw or "")
    m = re.search(r"(\d{15,25})", raw)
    return int(m.group(1)) if m else 0


async def _xautv_find_member(guild: discord.Guild, raw: str) -> discord.Member | None:
    user_id = _xautv_parse_user_id(raw)
    if user_id:
        member = guild.get_member(user_id)
        if member:
            return member
        with _xautv_contextlib.suppress(Exception):
            return await guild.fetch_member(user_id)
    raw_low = str(raw or "").lower().strip()
    for m in guild.members:
        if raw_low and (raw_low == m.name.lower() or raw_low == m.display_name.lower()):
            return m
    return None


class XAUTVNameModal(discord.ui.Modal, title="Cambiar nombre de sala"):
    new_name = discord.ui.TextInput(label="Nuevo nombre", placeholder="Ej: ⚔️ 2s Ranked", max_length=90, required=True)

    def __init__(self, voice_id: int):
        super().__init__(timeout=180)
        self.voice_id = voice_id

    async def on_submit(self, interaction: discord.Interaction):
        voice = interaction.guild.get_channel(self.voice_id) if interaction.guild else None
        active = await _xautv_active_for_voice(self.voice_id)
        if not isinstance(voice, discord.VoiceChannel) or not active:
            return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Sala no encontrada", "La sala temporal ya no existe.", XAUTV_WARN), ephemeral=True)
        owner_id = _xautv_int(active.get("owner_id"), 0)
        if interaction.user.id != owner_id and not _xautv_is_admin(interaction.user):
            return await _xautv_reply(interaction, embed=_xautv_embed("⛔ Solo dueño", "No eres dueño de esta sala.", XAUTV_BAD), ephemeral=True)
        name = _xautv_sanitize_name(str(self.new_name.value), voice.name)
        await voice.edit(name=name, reason="X AETHER TempVoice rename panel")
        active = await _xautv_update_active(voice.id, name=name)
        await _xautv_refresh_panel(voice, active)
        await _xautv_reply(interaction, embed=_xautv_embed("✅ Nombre cambiado", f"Nuevo nombre: `{name}`", XAUTV_OK, interaction.guild), ephemeral=True)


class XAUTVLimitModal(discord.ui.Modal, title="Cambiar límite de usuarios"):
    limit = discord.ui.TextInput(label="Límite 0-99", placeholder="0 = sin límite, 2 = duos, 3 = trios", max_length=2, required=True)

    def __init__(self, voice_id: int):
        super().__init__(timeout=180)
        self.voice_id = voice_id

    async def on_submit(self, interaction: discord.Interaction):
        voice = interaction.guild.get_channel(self.voice_id) if interaction.guild else None
        active = await _xautv_active_for_voice(self.voice_id)
        if not isinstance(voice, discord.VoiceChannel) or not active:
            return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Sala no encontrada", "La sala temporal ya no existe.", XAUTV_WARN), ephemeral=True)
        owner_id = _xautv_int(active.get("owner_id"), 0)
        if interaction.user.id != owner_id and not _xautv_is_admin(interaction.user):
            return await _xautv_reply(interaction, embed=_xautv_embed("⛔ Solo dueño", "No eres dueño de esta sala.", XAUTV_BAD), ephemeral=True)
        n = _xautv_int(self.limit.value, 0, 0, 99)
        await voice.edit(user_limit=n, reason="X AETHER TempVoice limit panel")
        active = await _xautv_update_active(voice.id, limit=n)
        await _xautv_refresh_panel(voice, active)
        await _xautv_reply(interaction, embed=_xautv_embed("✅ Límite cambiado", "Nuevo límite: **sin límite**" if n == 0 else f"Nuevo límite: **{n}**", XAUTV_OK, interaction.guild), ephemeral=True)


class XAUTVUserModal(discord.ui.Modal):
    user_value = discord.ui.TextInput(label="Usuario", placeholder="Mención, ID o nombre exacto", max_length=120, required=True)

    def __init__(self, voice_id: int, action: str):
        titles = {"invite": "Permitir usuario", "block": "Bloquear usuario", "unblock": "Desbloquear usuario", "transfer": "Transferir dueño", "kick": "Expulsar usuario"}
        super().__init__(title=titles.get(action, "Usuario"), timeout=180)
        self.voice_id = voice_id
        self.action = action

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        voice = guild.get_channel(self.voice_id) if guild else None
        active = await _xautv_active_for_voice(self.voice_id)
        if not guild or not isinstance(voice, discord.VoiceChannel) or not active:
            return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Sala no encontrada", "La sala temporal ya no existe.", XAUTV_WARN), ephemeral=True)
        owner_id = _xautv_int(active.get("owner_id"), 0)
        if interaction.user.id != owner_id and not _xautv_is_admin(interaction.user):
            return await _xautv_reply(interaction, embed=_xautv_embed("⛔ Solo dueño", "No eres dueño de esta sala.", XAUTV_BAD), ephemeral=True)
        member = await _xautv_find_member(guild, str(self.user_value.value))
        if not member:
            return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Usuario no encontrado", "Usa mención o ID para evitar confusiones.", XAUTV_WARN, guild), ephemeral=True)
        trusted = set(map(int, active.get("trusted", []) or []))
        blocked = set(map(int, active.get("blocked", []) or []))
        try:
            if self.action == "invite":
                trusted.add(member.id); blocked.discard(member.id)
                await voice.set_permissions(member, view_channel=True, connect=True, speak=True, stream=True, reason="X AETHER TempVoice invite")
                await _xautv_update_active(voice.id, trusted=sorted(trusted), blocked=sorted(blocked))
                msg = f"{member.mention} ahora puede entrar a {voice.mention}."
            elif self.action == "block":
                blocked.add(member.id); trusted.discard(member.id)
                await voice.set_permissions(member, view_channel=False, connect=False, reason="X AETHER TempVoice block")
                if member.voice and member.voice.channel and member.voice.channel.id == voice.id:
                    await member.move_to(None, reason="X AETHER TempVoice blocked")
                await _xautv_update_active(voice.id, trusted=sorted(trusted), blocked=sorted(blocked))
                msg = f"{member.mention} bloqueado en esta sala."
            elif self.action == "unblock":
                blocked.discard(member.id)
                await voice.set_permissions(member, overwrite=None, reason="X AETHER TempVoice unblock")
                await _xautv_update_active(voice.id, blocked=sorted(blocked))
                msg = f"{member.mention} desbloqueado."
            elif self.action == "kick":
                if member.voice and member.voice.channel and member.voice.channel.id == voice.id:
                    await member.move_to(None, reason="X AETHER TempVoice kick")
                    msg = f"{member.mention} expulsado de la sala."
                else:
                    msg = f"{member.mention} no está dentro de esta sala."
            elif self.action == "transfer":
                await voice.set_permissions(member, view_channel=True, connect=True, speak=True, stream=True, reason="X AETHER TempVoice transfer owner")
                # El panel está dentro del chat de voz, no hay canal de texto separado que tocar.
                active = await _xautv_update_active(voice.id, owner_id=member.id)
                await _xautv_refresh_panel(voice, active)
                msg = f"La sala ahora pertenece a {member.mention}."
            else:
                msg = "Acción desconocida."
            await _xautv_refresh_panel(voice)
            await _xautv_reply(interaction, embed=_xautv_embed("✅ Acción completada", msg, XAUTV_OK, guild), ephemeral=True)
        except Exception as exc:
            await _xautv_reply(interaction, embed=_xautv_embed("❌ Error", f"Discord rechazó la acción: `{exc}`", XAUTV_BAD, guild), ephemeral=True)


class XAUTVControlPanel(discord.ui.View):
    def __init__(self, voice_id: int):
        super().__init__(timeout=900)
        self.voice_id = int(voice_id)

    async def _voice_active_owner(self, interaction: discord.Interaction):
        guild = interaction.guild
        voice = guild.get_channel(self.voice_id) if guild else None
        active = await _xautv_active_for_voice(self.voice_id)
        if not guild or not isinstance(voice, discord.VoiceChannel) or not active:
            await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Sala no encontrada", "Esta sala temporal ya no existe.", XAUTV_WARN), ephemeral=True)
            return None, None, False
        owner_id = _xautv_int(active.get("owner_id"), 0)
        if interaction.user.id != owner_id and not _xautv_is_admin(interaction.user):
            await _xautv_reply(interaction, embed=_xautv_embed("⛔ Solo dueño", "Este panel solo lo puede usar el dueño de la sala o un admin.", XAUTV_BAD, guild), ephemeral=True)
            return voice, active, False
        return voice, active, True

    @discord.ui.button(label="Nombre", emoji="📝", style=discord.ButtonStyle.primary)
    async def btn_name(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(XAUTVNameModal(self.voice_id))

    @discord.ui.button(label="Límite", emoji="👥", style=discord.ButtonStyle.primary)
    async def btn_limit(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(XAUTVLimitModal(self.voice_id))

    @discord.ui.button(label="Lock", emoji="🔒", style=discord.ButtonStyle.secondary)
    async def btn_lock(self, interaction: discord.Interaction, button: discord.ui.Button):
        voice, active, ok = await self._voice_active_owner(interaction)
        if not ok: return
        new_locked = not bool(active.get("locked"))
        active = await _xautv_set_lock(voice, active, new_locked)
        await _xautv_reply(interaction, embed=_xautv_embed("✅ Privacidad actualizada", "Sala bloqueada." if new_locked else "Sala desbloqueada.", XAUTV_OK, interaction.guild), ephemeral=True)

    @discord.ui.button(label="Ocultar", emoji="👻", style=discord.ButtonStyle.secondary)
    async def btn_hide(self, interaction: discord.Interaction, button: discord.ui.Button):
        voice, active, ok = await self._voice_active_owner(interaction)
        if not ok: return
        new_hidden = not bool(active.get("hidden"))
        active = await _xautv_set_hidden(voice, active, new_hidden)
        await _xautv_reply(interaction, embed=_xautv_embed("✅ Visibilidad actualizada", "Sala oculta." if new_hidden else "Sala visible.", XAUTV_OK, interaction.guild), ephemeral=True)

    @discord.ui.button(label="Permitir", emoji="✅", style=discord.ButtonStyle.success)
    async def btn_invite(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(XAUTVUserModal(self.voice_id, "invite"))

    @discord.ui.button(label="Bloquear", emoji="⛔", style=discord.ButtonStyle.danger)
    async def btn_block(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(XAUTVUserModal(self.voice_id, "block"))

    @discord.ui.button(label="Transferir", emoji="👑", style=discord.ButtonStyle.secondary)
    async def btn_transfer(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(XAUTVUserModal(self.voice_id, "transfer"))

    @discord.ui.button(label="Borrar", emoji="🗑️", style=discord.ButtonStyle.danger)
    async def btn_delete(self, interaction: discord.Interaction, button: discord.ui.Button):
        voice, active, ok = await self._voice_active_owner(interaction)
        if not ok: return
        await _xautv_reply(interaction, embed=_xautv_embed("🗑️ Sala eliminada", "Borrando la sala; el panel integrado desaparecerá con ella.", XAUTV_OK, interaction.guild), ephemeral=True)
        await _xautv_delete_room(voice, reason=f"X AETHER TempVoice eliminado por {interaction.user}")


