@xautv_admin_group.command(name="set", description="Cambia una opción de un canal creador")
@app_commands.describe(channel="Canal creador", option="limit/name/bitrate/panel/locked/hidden/category/enabled", value="Valor nuevo")
async def xautv_set_creator(interaction: discord.Interaction, channel: discord.VoiceChannel, option: str, value: str):
    if not await _xautv_require_admin(interaction):
        return
    opt = str(option or "").lower().strip()
    data = await xautv_load()
    guild_cfg = data["guilds"].setdefault(str(interaction.guild.id), _xautv_default_guild())
    creators = guild_cfg.setdefault("creators", {})
    cfg = creators.get(str(channel.id))
    if not isinstance(cfg, dict):
        return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ No configurado", "Ese canal no es creador. Usa `/tempvoice add_creator`.", XAUTV_WARN, interaction.guild), ephemeral=True)
    if opt in {"limit", "límite", "limite"}:
        cfg["limit"] = _xautv_int(value, 0, 0, 99)
    elif opt == "name":
        cfg["name"] = _xautv_sanitize_name(value, cfg.get("name", "🔊 Sala de {user}"))
    elif opt == "bitrate":
        cfg["bitrate"] = _xautv_int(value, 64000, 8000, max(8000, interaction.guild.bitrate_limit))
    elif opt == "panel":
        cfg["panel"] = str(value).lower() in {"1", "true", "yes", "si", "sí", "on", "enable"}
    elif opt == "locked":
        cfg["locked_by_default"] = str(value).lower() in {"1", "true", "yes", "si", "sí", "on", "enable"}
    elif opt == "hidden":
        cfg["hidden_by_default"] = str(value).lower() in {"1", "true", "yes", "si", "sí", "on", "enable"}
    elif opt == "enabled":
        cfg["enabled"] = str(value).lower() in {"1", "true", "yes", "si", "sí", "on", "enable"}
    elif opt == "category":
        cid = _xautv_parse_user_id(value)
        cat = interaction.guild.get_channel(cid) if cid else None
        if not isinstance(cat, discord.CategoryChannel):
            return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Categoría inválida", "Pasa la ID de la categoría.", XAUTV_WARN, interaction.guild), ephemeral=True)
        cfg["category_id"] = cat.id
    else:
        return await _xautv_reply(interaction, embed=_xautv_embed("⚠️ Opción inválida", "Opciones: `limit`, `name`, `bitrate`, `panel`, `locked`, `hidden`, `category`, `enabled`.", XAUTV_WARN, interaction.guild), ephemeral=True)
    creators[str(channel.id)] = cfg
    await xautv_save(data)
    await _xautv_reply(interaction, embed=_xautv_embed("✅ Configuración actualizada", f"`{opt}` actualizado en {channel.mention}.", XAUTV_OK, interaction.guild), ephemeral=True)


@xautv_admin_group.command(name="list", description="Lista creadores y salas activas")
async def xautv_list(interaction: discord.Interaction):
    if not await _xautv_require_admin(interaction):
        return
    data = await xautv_load()
    guild_cfg = data.get("guilds", {}).get(str(interaction.guild.id), _xautv_default_guild())
    creators = guild_cfg.get("creators", {}) or {}
    lines = []
    for cid, cfg in creators.items():
        ch = interaction.guild.get_channel(_xautv_int(cid, 0))
        limit = _xautv_int(cfg.get("limit", 0), 0, 0, 99)
        lines.append(f"{'✅' if cfg.get('enabled', True) else '⛔'} {ch.mention if ch else '`'+cid+'`'} → límite `{limit}` · `{cfg.get('name','')}`")
    active_lines = []
    for vid, active in (data.get("active", {}) or {}).items():
        if _xautv_int(active.get("guild_id"), 0) != interaction.guild.id:
            continue
        vc = interaction.guild.get_channel(_xautv_int(vid, 0))
        owner = interaction.guild.get_member(_xautv_int(active.get("owner_id"), 0))
        active_lines.append(f"🎙️ {vc.mention if vc else '`'+vid+'`'} · dueño: {owner.mention if owner else active.get('owner_id')}")
    embed = _xautv_embed("🎛️ TempVoice estado", "Sistema propio de voz temporal.", XAUTV_COLOR, interaction.guild)
    embed.add_field(name="Canales creadores", value="\n".join(lines)[:1000] if lines else "No hay creadores configurados.", inline=False)
    embed.add_field(name="Salas activas", value="\n".join(active_lines)[:1000] if active_lines else "No hay salas activas.", inline=False)
    await _xautv_reply(interaction, embed=embed, ephemeral=True)


@xautv_admin_group.command(name="cleanup", description="Limpia salas temporales huérfanas o vacías")
async def xautv_cleanup(interaction: discord.Interaction):
    if not await _xautv_require_admin(interaction):
        return
    await interaction.response.defer(ephemeral=True, thinking=True)
    data = await xautv_load()
    removed = 0
    for vid, active in list((data.get("active", {}) or {}).items()):
        if _xautv_int(active.get("guild_id"), 0) != interaction.guild.id:
            continue
        vc = interaction.guild.get_channel(_xautv_int(vid, 0))
        if not isinstance(vc, discord.VoiceChannel) or len(vc.members) == 0:
            if isinstance(vc, discord.VoiceChannel):
                await _xautv_delete_room(vc, reason="X AETHER TempVoice admin cleanup")
            else:
                data.get("active", {}).pop(vid, None)
                await xautv_save(data)
            removed += 1
    await interaction.followup.send(embed=_xautv_embed("🧹 Limpieza completada", f"Salas limpiadas: **{removed}**", XAUTV_OK, interaction.guild), ephemeral=True)


@xautv_admin_group.command(name="sync", description="Fuerza sincronización de slash commands")
async def xautv_sync(interaction: discord.Interaction):
    if not await _xautv_require_admin(interaction):
        return
    await interaction.response.defer(ephemeral=True, thinking=True)
    try:
        synced = await bot.tree.sync()
        await interaction.followup.send(embed=_xautv_embed("✅ Slash sincronizados", f"Comandos sincronizados: **{len(synced)}**. Si Discord tarda, espera unos minutos.", XAUTV_OK, interaction.guild), ephemeral=True)
    except Exception as exc:
        await interaction.followup.send(embed=_xautv_embed("❌ Sync falló", f"Error: `{exc}`", XAUTV_BAD, interaction.guild), ephemeral=True)


