@bot.listen("on_voice_state_update")
async def xautv_on_voice_state_update(member: discord.Member, before: discord.VoiceState, after: discord.VoiceState):
    if getattr(member, "bot", False) or not member.guild:
        return
    try:
        data = await xautv_load()
        guild_cfg = data.get("guilds", {}).get(str(member.guild.id), {})
        if not guild_cfg or not guild_cfg.get("enabled", True):
            return
        creators = guild_cfg.get("creators", {}) or {}
        if after and after.channel and isinstance(after.channel, discord.VoiceChannel):
            cfg = creators.get(str(after.channel.id))
            if isinstance(cfg, dict) and cfg.get("enabled", True):
                # Evita duplicar si el usuario ya tiene una sala temporal activa en este server.
                for vid, active in list((data.get("active", {}) or {}).items()):
                    if _xautv_int(active.get("guild_id"), 0) == member.guild.id and _xautv_int(active.get("owner_id"), 0) == member.id:
                        old_vc = member.guild.get_channel(_xautv_int(vid, 0))
                        if isinstance(old_vc, discord.VoiceChannel):
                            with _xautv_contextlib.suppress(Exception):
                                await member.move_to(old_vc, reason="X AETHER TempVoice existing room")
                            return
                await _xautv_create_room(member, after.channel, cfg)
                return
        if before and before.channel and isinstance(before.channel, discord.VoiceChannel):
            active = data.get("active", {}).get(str(before.channel.id))
            if isinstance(active, dict):
                delay = _xautv_int(guild_cfg.get("delete_delay", 2), 2, 0, 60)
                await asyncio.sleep(delay)
                channel = member.guild.get_channel(before.channel.id)
                if isinstance(channel, discord.VoiceChannel) and len(channel.members) == 0:
                    await _xautv_delete_room(channel, reason="X AETHER TempVoice empty room cleanup")
    except Exception as exc:
        print(f"[XAUTV] voice_state error: {exc!r}")


